INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('敦煌莫高窟纯攻略·周末版','guide','酒泉 · 敦煌莫高窟','red','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',2990,1600,7,'莫高窟 / 鸣沙山月牙泉 / 沙洲夜市 —— 纯攻略助你玩透敦煌莫高窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「敦煌莫高窟」三日深度游——人文。敦煌夜光杯工艺品别致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 酒泉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往酒泉，抵达后办理入住、熟悉周边环境。","addr":"酒泉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫高窟","description":"下午首站莫高窟，调整状态进入旅行节奏，千年壁画宝库，A类票提前约。","addr":"敦煌市鸣沙山东麓","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游酒泉一带氛围拉满，晚餐驴肉黄面人均28元。","addr":"滨河世纪家园","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"鸣沙山月牙泉","description":"全天主景点鸣沙山月牙泉，沙漠绿洲，骆驼队与滑沙。","addr":"敦煌市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐胡羊焖饼（人均58元），早点休息。","addr":"沙洲路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙洲夜市","description":"收官沙洲夜市，驴肉黄面与夜市淘货。","addr":"敦煌市区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏皮水后集合返程，三日旅程圆满。","addr":"沙洲夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫高窟","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"莫高窟是敦煌莫高窟最有代表性的看点，千年壁画宝库，A类票提前约。攻略把它排进主线，时间留得最足。","notice":"千年壁画宝库，A类票提前约。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"敦煌市鸣沙山东麓"},{"spotId":"S2","name":"鸣沙山月牙泉","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"鸣沙山月牙泉是敦煌莫高窟最有代表性的看点，沙漠绿洲，骆驼队与滑沙。攻略把它排进主线，时间留得最足。","notice":"沙漠绿洲，骆驼队与滑沙。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"敦煌市"},{"spotId":"S3","name":"沙洲夜市","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"沙洲夜市是敦煌莫高窟最有代表性的看点，驴肉黄面与夜市淘货。攻略把它排进主线，时间留得最足。","notice":"驴肉黄面与夜市淘货。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"敦煌市区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉黄面（人均28元）","description":"酒泉 · 敦煌莫高窟的招牌是驴肉黄面，顺张驴肉黄面馆本地人都认这家，点单照攻略不踩雷。","addr":"滨河世纪家园"},{"title":"胡羊焖饼（人均58元）","description":"酒泉 · 敦煌莫高窟的招牌是胡羊焖饼，靖远尕六美味羊羔肉本地人都认这家，点单照攻略不踩雷。","addr":"沙洲路"},{"title":"杏皮水（人均8元）","description":"酒泉 · 敦煌莫高窟的招牌是杏皮水，夜市摊位本地人都认这家，点单照攻略不踩雷。","addr":"沙洲夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","轻便雨衣或折叠伞","保温水杯与少量现金","墨镜与拍照道具","防晒霜与遮阳帽","身份证件与手机充电宝","少量零食补给","换洗衣物与外套（早晚温差）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 酒泉 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('布达拉宫纯攻略·亲子篇','guide','拉萨 · 布达拉宫','plateau','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,2,'布达拉宫 / 大昭寺 / 色拉寺 —— 纯攻略助你玩透布达拉宫精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「布达拉宫」两日慢旅行——高原。拉萨转经筒小件最好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 拉萨"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴拉萨","description":"集合出发，大巴直达布达拉宫，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"布达拉宫","description":"抵达后首游布达拉宫，海拔3700宫殿，提前一天预约。","addr":"拉萨市城关区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏面（人均12元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大昭寺","description":"早起人少，大昭寺精华时段，八廓街转经道，藏地心脏。","addr":"老城区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤牦牛肉，人均68元，补充体力。","addr":"八角东南角","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"色拉寺","description":"午后游览色拉寺，辩经下午3点开始，场面壮观。","addr":"城北","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"布达拉宫","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"布达拉宫是布达拉宫最有代表性的看点，海拔3700宫殿，提前一天预约。攻略把它排进主线，时间留得最足。","notice":"海拔3700宫殿，提前一天预约。这个点位上午光线最好。","durationMinutes":240,"addr":"拉萨市城关区"},{"spotId":"S2","name":"大昭寺","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"大昭寺是布达拉宫最有代表性的看点，八廓街转经道，藏地心脏。攻略把它排进主线，时间留得最足。","notice":"八廓街转经道，藏地心脏。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"老城区"},{"spotId":"S3","name":"色拉寺","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"色拉寺是布达拉宫最有代表性的看点，辩经下午3点开始，场面壮观。攻略把它排进主线，时间留得最足。","notice":"辩经下午3点开始，场面壮观。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"城北"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏面（人均12元）","description":"拉萨 · 布达拉宫的招牌是藏面，光明港琼甜茶馆本地人都认这家，点单照攻略不踩雷。","addr":"八廓街"},{"title":"烤牦牛肉（人均68元）","description":"拉萨 · 布达拉宫的招牌是烤牦牛肉，玛吉阿米本地人都认这家，点单照攻略不踩雷。","addr":"八角东南角"},{"title":"青稞酒（人均30元）","description":"拉萨 · 布达拉宫的招牌是青稞酒，藏家宴本地人都认这家，点单照攻略不踩雷。","addr":"藏医院路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","墨镜与拍照道具","轻便雨衣或折叠伞","防晒霜与遮阳帽","保温水杯与少量现金","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 拉萨，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五大道瓷房子纯攻略·摄影机位','guide','和平 · 五大道瓷房子','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1500,800,5,'五大道 / 瓷房子 / 古文化街 —— 纯攻略助你玩透五大道瓷房子精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「五大道瓷房子」三日深度游——文艺。天津泥人张彩塑传神。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"天津 · 和平"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往和平，抵达后办理入住、熟悉周边环境。","addr":"和平市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"五大道","description":"下午首站五大道，调整状态进入旅行节奏，万国建筑博览会，马车游。","addr":"天津市和平区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游和平一带氛围拉满，晚餐煎饼果子人均10元。","addr":"和平区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"瓷房子","description":"全天主景点瓷房子，7亿瓷片房子，白天看外观。","addr":"和平区赤峰道","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐狗不理包子（人均45元），早点休息。","addr":"山东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古文化街","description":"收官古文化街，泥人张杨柳青年画。","addr":"南开区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐耳朵眼炸糕后集合返程，三日旅程圆满。","addr":"古文化街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"五大道","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"五大道是五大道瓷房子最有代表性的看点，万国建筑博览会，马车游。攻略把它排进主线，时间留得最足。","notice":"万国建筑博览会，马车游。这个点位上午光线最好。","durationMinutes":150,"addr":"天津市和平区"},{"spotId":"S2","name":"瓷房子","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"瓷房子是五大道瓷房子最有代表性的看点，7亿瓷片房子，白天看外观。攻略把它排进主线，时间留得最足。","notice":"7亿瓷片房子，白天看外观。提前10分钟到，避开旅行团大部队。","durationMinutes":30,"addr":"和平区赤峰道"},{"spotId":"S3","name":"古文化街","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"古文化街是五大道瓷房子最有代表性的看点，泥人张杨柳青年画。攻略把它排进主线，时间留得最足。","notice":"泥人张杨柳青年画。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"南开区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"煎饼果子（人均10元）","description":"和平 · 五大道瓷房子的招牌是煎饼果子，南楼煎饼本地人都认这家，点单照攻略不踩雷。","addr":"和平区"},{"title":"狗不理包子（人均45元）","description":"和平 · 五大道瓷房子的招牌是狗不理包子，狗不理总店本地人都认这家，点单照攻略不踩雷。","addr":"山东路"},{"title":"耳朵眼炸糕（人均8元）","description":"和平 · 五大道瓷房子的招牌是耳朵眼炸糕，耳朵眼总店本地人都认这家，点单照攻略不踩雷。","addr":"古文化街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","墨镜与拍照道具","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙虎山纯攻略·美食清单','guide','鹰潭 · 龙虎山','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',1200,600,2,'仙水岩 / 泸溪河竹筏 / 上清古镇 —— 纯攻略助你玩透龙虎山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙虎山」两日慢旅行——水景。龙虎山道教养生茶值得带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 鹰潭"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴鹰潭","description":"集合出发，大巴直达龙虎山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"仙水岩","description":"抵达后首游仙水岩，悬棺表演一天四场，提前占前排。","addr":"龙虎山仙水岩景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐天师板栗烧鸡（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"泸溪河竹筏","description":"早起人少，泸溪河竹筏精华时段，顺流漂90分钟，防晒必做。","addr":"龙虎山竹筏码头","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐泸溪河鱼，人均58元，补充体力。","addr":"竹筏码头旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"上清古镇","description":"午后游览上清古镇，天师府在此，古街人少。","addr":"龙虎山上清镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"仙水岩","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"仙水岩是龙虎山最有代表性的看点，悬棺表演一天四场，提前占前排。攻略把它排进主线，时间留得最足。","notice":"悬棺表演一天四场，提前占前排。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"龙虎山仙水岩景区"},{"spotId":"S2","name":"泸溪河竹筏","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"泸溪河竹筏是龙虎山最有代表性的看点，顺流漂90分钟，防晒必做。攻略把它排进主线，时间留得最足。","notice":"顺流漂90分钟，防晒必做。这个点位上午光线最好。","durationMinutes":90,"addr":"龙虎山竹筏码头"},{"spotId":"S3","name":"上清古镇","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"上清古镇是龙虎山最有代表性的看点，天师府在此，古街人少。攻略把它排进主线，时间留得最足。","notice":"天师府在此，古街人少。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙虎山上清镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"天师板栗烧鸡（人均68元）","description":"鹰潭 · 龙虎山的招牌是天师板栗烧鸡，上清古镇饭店本地人都认这家，点单照攻略不踩雷。","addr":"上清古镇长街"},{"title":"泸溪河鱼（人均58元）","description":"鹰潭 · 龙虎山的招牌是泸溪河鱼，仙水岩渔家本地人都认这家，点单照攻略不踩雷。","addr":"竹筏码头旁"},{"title":"上清豆腐（人均20元）","description":"鹰潭 · 龙虎山的招牌是上清豆腐，古镇豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"上清古街中段"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","相机或运动相机","保温水杯与少量现金","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 鹰潭 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('张家界国家森林公园纯攻略·自由行手册','guide','张家界 · 张家界国家森林公园','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',990,500,2,'袁家界 / 天子山 / 金鞭溪 —— 纯攻略助你玩透张家界国家森林公园精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「张家界国家森林公园」三日深度游——山岳。张家界莓茶降火神器。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 张家界"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往张家界，抵达后办理入住、熟悉周边环境。","addr":"张家界市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"袁家界","description":"下午首站袁家界，调整状态进入旅行节奏，阿凡达悬浮山原型，百龙天梯上山。","addr":"武陵源区森林公园","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游张家界一带氛围拉满，晚餐三下锅人均58元。","addr":"武陵源汽车站旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天子山","description":"全天主景点天子山，御笔峰日落绝佳，贺龙公园顺路。","addr":"武陵源天子山景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土家腊肉（人均48元），早点休息。","addr":"溪布街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"金鞭溪","description":"收官金鞭溪，全程7.5公里平路，溪边猕猴抢食注意。","addr":"森林公园大氧吧广场","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐岩耳炖土鸡后集合返程，三日旅程圆满。","addr":"森林公园门票站","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"袁家界","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"袁家界是张家界国家森林公园最有代表性的看点，阿凡达悬浮山原型，百龙天梯上山。攻略把它排进主线，时间留得最足。","notice":"阿凡达悬浮山原型，百龙天梯上山。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"武陵源区森林公园"},{"spotId":"S2","name":"天子山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"天子山是张家界国家森林公园最有代表性的看点，御笔峰日落绝佳，贺龙公园顺路。攻略把它排进主线，时间留得最足。","notice":"御笔峰日落绝佳，贺龙公园顺路。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"武陵源天子山景区"},{"spotId":"S3","name":"金鞭溪","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"金鞭溪是张家界国家森林公园最有代表性的看点，全程7.5公里平路，溪边猕猴抢食注意。攻略把它排进主线，时间留得最足。","notice":"全程7.5公里平路，溪边猕猴抢食注意。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"森林公园大氧吧广场"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"三下锅（人均58元）","description":"张家界 · 张家界国家森林公园的招牌是三下锅，胡师傅三下锅本地人都认这家，点单照攻略不踩雷。","addr":"武陵源汽车站旁"},{"title":"土家腊肉（人均48元）","description":"张家界 · 张家界国家森林公园的招牌是土家腊肉，湘西腊肉馆本地人都认这家，点单照攻略不踩雷。","addr":"溪布街"},{"title":"岩耳炖土鸡（人均88元）","description":"张家界 · 张家界国家森林公园的招牌是岩耳炖土鸡，山里人家本地人都认这家，点单照攻略不踩雷。","addr":"森林公园门票站"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","墨镜与拍照道具","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","身份证件与手机充电宝","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 张家界 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('紫鹊界梯田纯攻略·省钱玩法','guide','娄底 · 紫鹊界梯田','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',1500,800,1,'紫鹊界梯田 / 正龙古村 / 梅山龙宫 —— 纯攻略助你玩透紫鹊界梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「紫鹊界梯田」两日慢旅行——古村落。新化黄精茶养生。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 娄底"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴娄底","description":"集合出发，大巴直达紫鹊界梯田，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"紫鹊界梯田","description":"抵达后首游紫鹊界梯田，两千年秦人梯田，月牙山八仙过海。","addr":"娄底市新化县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐新化三合汤（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"正龙古村","description":"早起人少，正龙古村精华时段，干栏式板屋村落。","addr":"紫鹊界脚下","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐杯子糕，人均10元，补充体力。","addr":"紫鹊界","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"梅山龙宫","description":"午后游览梅山龙宫，地下溶洞暗河乘船。","addr":"新化县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"紫鹊界梯田","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"紫鹊界梯田是紫鹊界梯田最有代表性的看点，两千年秦人梯田，月牙山八仙过海。攻略把它排进主线，时间留得最足。","notice":"两千年秦人梯田，月牙山八仙过海。这个点位上午光线最好。","durationMinutes":180,"addr":"娄底市新化县"},{"spotId":"S2","name":"正龙古村","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"正龙古村是紫鹊界梯田最有代表性的看点，干栏式板屋村落。攻略把它排进主线，时间留得最足。","notice":"干栏式板屋村落。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"紫鹊界脚下"},{"spotId":"S3","name":"梅山龙宫","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"梅山龙宫是紫鹊界梯田最有代表性的看点，地下溶洞暗河乘船。攻略把它排进主线，时间留得最足。","notice":"地下溶洞暗河乘船。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"新化县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新化三合汤（人均38元）","description":"娄底 · 紫鹊界梯田的招牌是新化三合汤，老字号三合汤本地人都认这家，点单照攻略不踩雷。","addr":"新化县城"},{"title":"杯子糕（人均10元）","description":"娄底 · 紫鹊界梯田的招牌是杯子糕，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"紫鹊界"},{"title":"柴火腊肉（人均45元）","description":"娄底 · 紫鹊界梯田的招牌是柴火腊肉，农家直购本地人都认这家，点单照攻略不踩雷。","addr":"正龙古村"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大熊猫基地都江堰纯攻略·避坑版','guide','成都 · 大熊猫基地都江堰','food','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',1990,1000,3,'大熊猫繁育研究基地 / 都江堰 / 南桥夜啤酒 —— 纯攻略助你玩透大熊猫基地都江堰精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大熊猫基地都江堰」三日深度游——美食。郫县豆瓣是川菜之魂。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 成都"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往成都，抵达后办理入住、熟悉周边环境。","addr":"成都市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大熊猫繁育研究基地","description":"下午首站大熊猫繁育研究基地，调整状态进入旅行节奏，早8点开园直奔月亮产房，熊猫最活跃。","addr":"成华区外北熊猫大道","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游成都一带氛围拉满，晚餐火锅人均110元。","addr":"建设路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"都江堰","description":"全天主景点都江堰，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。","addr":"都江堰市公园路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐串串香（人均65元），早点休息。","addr":"玉林路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"南桥夜啤酒","description":"收官南桥夜啤酒，岷江水上的夜风与美食。","addr":"都江堰市南桥","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐钟水饺后集合返程，三日旅程圆满。","addr":"人民公园旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大熊猫繁育研究基地","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"大熊猫繁育研究基地是大熊猫基地都江堰最有代表性的看点，早8点开园直奔月亮产房，熊猫最活跃。攻略把它排进主线，时间留得最足。","notice":"早8点开园直奔月亮产房，熊猫最活跃。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"成华区外北熊猫大道"},{"spotId":"S2","name":"都江堰","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"都江堰是大熊猫基地都江堰最有代表性的看点，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。攻略把它排进主线，时间留得最足。","notice":"鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"都江堰市公园路"},{"spotId":"S3","name":"南桥夜啤酒","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"南桥夜啤酒是大熊猫基地都江堰最有代表性的看点，岷江水上的夜风与美食。攻略把它排进主线，时间留得最足。","notice":"岷江水上的夜风与美食。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"都江堰市南桥"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"火锅（人均110元）","description":"成都 · 大熊猫基地都江堰的招牌是火锅，蜀大侠本地人都认这家，点单照攻略不踩雷。","addr":"建设路"},{"title":"串串香（人均65元）","description":"成都 · 大熊猫基地都江堰的招牌是串串香，马路边边本地人都认这家，点单照攻略不踩雷。","addr":"玉林路"},{"title":"钟水饺（人均15元）","description":"成都 · 大熊猫基地都江堰的招牌是钟水饺，老字号小吃本地人都认这家，点单照攻略不踩雷。","addr":"人民公园旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄果树瀑布纯攻略·深度指南','guide','安顺 · 黄果树瀑布','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,2,'黄果树大瀑布 / 天星桥 / 陡坡塘 —— 纯攻略助你玩透黄果树瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「黄果树瀑布」两日慢旅行——水景。安顺三刀是传统名点。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 安顺"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴安顺","description":"集合出发，大巴直达黄果树瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄果树大瀑布","description":"抵达后首游黄果树大瀑布，亚洲最大瀑布，水帘洞穿瀑而过。","addr":"安顺市镇宁县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐夺夺粉（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天星桥","description":"早起人少，天星桥精华时段，石景水上盆景，数生步趣味。","addr":"黄果树景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐裹卷，人均12元，补充体力。","addr":"黄果树镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"陡坡塘","description":"午后游览陡坡塘，西游记片尾取景地。","addr":"黄果树景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄果树大瀑布","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"黄果树大瀑布是黄果树瀑布最有代表性的看点，亚洲最大瀑布，水帘洞穿瀑而过。攻略把它排进主线，时间留得最足。","notice":"亚洲最大瀑布，水帘洞穿瀑而过。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"安顺市镇宁县"},{"spotId":"S2","name":"天星桥","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"天星桥是黄果树瀑布最有代表性的看点，石景水上盆景，数生步趣味。攻略把它排进主线，时间留得最足。","notice":"石景水上盆景，数生步趣味。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"黄果树景区"},{"spotId":"S3","name":"陡坡塘","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"陡坡塘是黄果树瀑布最有代表性的看点，西游记片尾取景地。攻略把它排进主线，时间留得最足。","notice":"西游记片尾取景地。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"黄果树景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"夺夺粉（人均35元）","description":"安顺 · 黄果树瀑布的招牌是夺夺粉，安顺小吃街本地人都认这家，点单照攻略不踩雷。","addr":"安顺市区"},{"title":"裹卷（人均12元）","description":"安顺 · 黄果树瀑布的招牌是裹卷，苗岭小吃本地人都认这家，点单照攻略不踩雷。","addr":"黄果树镇"},{"title":"布依农家餐（人均48元）","description":"安顺 · 黄果树瀑布的招牌是布依农家餐，石头寨本地人都认这家，点单照攻略不踩雷。","addr":"石头寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","常用药品（肠胃药/创可贴）","保温水杯与少量现金","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","相机或运动相机","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 安顺，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙脊梯田纯攻略·周末版','guide','桂林 · 龙脊梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',2500,1300,1,'平安寨七星伴月 / 金坑大寨 / 黄洛红瑶寨 —— 纯攻略助你玩透龙脊梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙脊梯田」三日深度游——古村落。龙脊辣椒酱拌饭一绝。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往桂林，抵达后办理入住、熟悉周边环境。","addr":"桂林市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"平安寨七星伴月","description":"下午首站平安寨七星伴月，调整状态进入旅行节奏，经典梯田观景台，徒步30分钟。","addr":"龙胜县龙脊镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游桂林一带氛围拉满，晚餐竹筒饭人均25元。","addr":"平安寨","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"金坑大寨","description":"全天主景点金坑大寨，缆车直达3号观景点，日落最佳。","addr":"龙脊梯田金坑","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土鸡煲（人均68元），早点休息。","addr":"金坑梯田","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"黄洛红瑶寨","description":"收官黄洛红瑶寨，天下第一长发村表演。","addr":"龙脊山下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐龙脊茶后集合返程，三日旅程圆满。","addr":"黄洛瑶寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"平安寨七星伴月","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"平安寨七星伴月是龙脊梯田最有代表性的看点，经典梯田观景台，徒步30分钟。攻略把它排进主线，时间留得最足。","notice":"经典梯田观景台，徒步30分钟。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"龙胜县龙脊镇"},{"spotId":"S2","name":"金坑大寨","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"金坑大寨是龙脊梯田最有代表性的看点，缆车直达3号观景点，日落最佳。攻略把它排进主线，时间留得最足。","notice":"缆车直达3号观景点，日落最佳。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"龙脊梯田金坑"},{"spotId":"S3","name":"黄洛红瑶寨","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"黄洛红瑶寨是龙脊梯田最有代表性的看点，天下第一长发村表演。攻略把它排进主线，时间留得最足。","notice":"天下第一长发村表演。这个点位上午光线最好。","durationMinutes":60,"addr":"龙脊山下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"竹筒饭（人均25元）","description":"桂林 · 龙脊梯田的招牌是竹筒饭，梯田农家本地人都认这家，点单照攻略不踩雷。","addr":"平安寨"},{"title":"土鸡煲（人均68元）","description":"桂林 · 龙脊梯田的招牌是土鸡煲，大寨农家本地人都认这家，点单照攻略不踩雷。","addr":"金坑梯田"},{"title":"龙脊茶（人均20元）","description":"桂林 · 龙脊梯田的招牌是龙脊茶，茶农家本地人都认这家，点单照攻略不踩雷。","addr":"黄洛瑶寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","轻便雨衣或折叠伞","墨镜与拍照道具","保温水杯与少量现金","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","身份证件与手机充电宝","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["当地有什么必吃？","到了 桂林，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 桂林 的交通方便吗？","推荐先到 桂林，再打车或景区直通车前往核心景区；自驾导航直接搜龙脊梯田即可。"],["几月份去 桂林 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('霞浦滩涂纯攻略·亲子篇','guide','宁德 · 霞浦滩涂','photography','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',2500,1300,12,'北岐滩涂 / 杨家溪 / 东壁日落 —— 纯攻略助你玩透霞浦滩涂精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「霞浦滩涂」两日慢旅行——摄影胜地。霞浦紫菜海带全国第一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 宁德"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宁德","description":"集合出发，大巴直达霞浦滩涂，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"北岐滩涂","description":"抵达后首游北岐滩涂，日出紫菜架光影，摄影圣地。","addr":"霞浦县松港街道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐霞浦剑蛏（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"杨家溪","description":"早起人少，杨家溪精华时段，千年枫榕树群，牛群穿雾。","addr":"霞浦县牙城镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐海带排骨汤，人均38元，补充体力。","addr":"北岐村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"东壁日落","description":"午后游览东壁日落，落日渔船归航机位。","addr":"霞浦县三沙镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"北岐滩涂","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"北岐滩涂是霞浦滩涂最有代表性的看点，日出紫菜架光影，摄影圣地。攻略把它排进主线，时间留得最足。","notice":"日出紫菜架光影，摄影圣地。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"霞浦县松港街道"},{"spotId":"S2","name":"杨家溪","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"杨家溪是霞浦滩涂最有代表性的看点，千年枫榕树群，牛群穿雾。攻略把它排进主线，时间留得最足。","notice":"千年枫榕树群，牛群穿雾。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"霞浦县牙城镇"},{"spotId":"S3","name":"东壁日落","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"东壁日落是霞浦滩涂最有代表性的看点，落日渔船归航机位。攻略把它排进主线，时间留得最足。","notice":"落日渔船归航机位。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"霞浦县三沙镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"霞浦剑蛏（人均68元）","description":"宁德 · 霞浦滩涂的招牌是霞浦剑蛏，海鲜大排档本地人都认这家，点单照攻略不踩雷。","addr":"三沙镇"},{"title":"海带排骨汤（人均38元）","description":"宁德 · 霞浦滩涂的招牌是海带排骨汤，渔家菜本地人都认这家，点单照攻略不踩雷。","addr":"北岐村"},{"title":"糊汤（人均10元）","description":"宁德 · 霞浦滩涂的招牌是糊汤，街头早点本地人都认这家，点单照攻略不踩雷。","addr":"霞浦县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机","少量零食补给","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 宁德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('拙政园林纯攻略·摄影机位','guide','苏州 · 拙政园林','art','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,5,'拙政园 / 平江路 / 虎丘 —— 纯攻略助你玩透拙政园林精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「拙政园林」三日深度游——文艺。苏绣团扇工艺最精。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 苏州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往苏州，抵达后办理入住、熟悉周边环境。","addr":"苏州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"拙政园","description":"下午首站拙政园，调整状态进入旅行节奏，江南园林之母，人再多也值得。","addr":"苏州市姑苏区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游苏州一带氛围拉满，晚餐松鼠桂鱼人均128元。","addr":"太监弄","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"平江路","description":"全天主景点平江路，小桥流水人家，评弹声里喝茶。","addr":"姑苏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蟹粉小笼（人均25元），早点休息。","addr":"临顿路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"虎丘","description":"收官虎丘，吴中第一名胜，斜塔传奇。","addr":"姑苏区山塘街","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桂花糕后集合返程，三日旅程圆满。","addr":"山塘街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"拙政园","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"拙政园是拙政园林最有代表性的看点，江南园林之母，人再多也值得。攻略把它排进主线，时间留得最足。","notice":"江南园林之母，人再多也值得。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"苏州市姑苏区"},{"spotId":"S2","name":"平江路","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"平江路是拙政园林最有代表性的看点，小桥流水人家，评弹声里喝茶。攻略把它排进主线，时间留得最足。","notice":"小桥流水人家，评弹声里喝茶。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"姑苏区"},{"spotId":"S3","name":"虎丘","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"虎丘是拙政园林最有代表性的看点，吴中第一名胜，斜塔传奇。攻略把它排进主线，时间留得最足。","notice":"吴中第一名胜，斜塔传奇。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"姑苏区山塘街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松鼠桂鱼（人均128元）","description":"苏州 · 拙政园林的招牌是松鼠桂鱼，得月楼本地人都认这家，点单照攻略不踩雷。","addr":"太监弄"},{"title":"蟹粉小笼（人均25元）","description":"苏州 · 拙政园林的招牌是蟹粉小笼，哑巴生煎本地人都认这家，点单照攻略不踩雷。","addr":"临顿路"},{"title":"桂花糕（人均15元）","description":"苏州 · 拙政园林的招牌是桂花糕，采芝斋本地人都认这家，点单照攻略不踩雷。","addr":"山塘街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","相机或运动相机","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('恩施大峡谷纯攻略·美食清单','guide','恩施 · 恩施大峡谷','adventure','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',990,500,9,'七星寨 / 云龙地缝 / 梭布垭石林 —— 纯攻略助你玩透恩施大峡谷精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「恩施大峡谷」两日慢旅行——探险地。恩施玉露茶古法蒸青。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 恩施"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴恩施","description":"集合出发，大巴直达恩施大峡谷，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七星寨","description":"抵达后首游七星寨，一炷香奇观，云龙地缝联游。","addr":"恩施市沐抚街道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐土家腊蹄子（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"云龙地缝","description":"早起人少，云龙地缝精华时段，U型地缝瀑布成群。","addr":"大峡谷景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐合渣，人均28元，补充体力。","addr":"沐抚镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"梭布垭石林","description":"午后游览梭布垭石林，戴冠石林迷宫。","addr":"恩施市太阳河乡","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七星寨","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"七星寨是恩施大峡谷最有代表性的看点，一炷香奇观，云龙地缝联游。攻略把它排进主线，时间留得最足。","notice":"一炷香奇观，云龙地缝联游。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"恩施市沐抚街道"},{"spotId":"S2","name":"云龙地缝","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"云龙地缝是恩施大峡谷最有代表性的看点，U型地缝瀑布成群。攻略把它排进主线，时间留得最足。","notice":"U型地缝瀑布成群。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"大峡谷景区"},{"spotId":"S3","name":"梭布垭石林","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"梭布垭石林是恩施大峡谷最有代表性的看点，戴冠石林迷宫。攻略把它排进主线，时间留得最足。","notice":"戴冠石林迷宫。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"恩施市太阳河乡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土家腊蹄子（人均58元）","description":"恩施 · 恩施大峡谷的招牌是土家腊蹄子，张关合渣本地人都认这家，点单照攻略不踩雷。","addr":"恩施市区"},{"title":"合渣（人均28元）","description":"恩施 · 恩施大峡谷的招牌是合渣，土家合渣馆本地人都认这家，点单照攻略不踩雷。","addr":"沐抚镇"},{"title":"土豆饭（人均22元）","description":"恩施 · 恩施大峡谷的招牌是土豆饭，农家本地人都认这家，点单照攻略不踩雷。","addr":"大峡谷游客中心"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","少量零食补给","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 恩施 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('老君山纯攻略·自由行手册','guide','栾川 · 老君山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1200,600,2,'金顶道观群 / 十里画屏 / 追梦谷 —— 纯攻略助你玩透老君山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「老君山」三日深度游——山岳。老君山高山茶清冽。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 栾川"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往栾川，抵达后办理入住、熟悉周边环境。","addr":"栾川市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶道观群","description":"下午首站金顶道观群，调整状态进入旅行节奏，云海雪景封神，远赴人间惊鸿宴。","addr":"洛阳市栾川县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游栾川一带氛围拉满，晚餐栾川豆腐人均28元。","addr":"栾川县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"十里画屏","description":"全天主景点十里画屏，滑道下山，省膝盖。","addr":"老君山石林","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蝌蚪面（人均18元），早点休息。","addr":"鸡冠洞乡","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"追梦谷","description":"收官追梦谷，溪瀑竹林轻松线。","addr":"老君山脚下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐玉米糁汤后集合返程，三日旅程圆满。","addr":"景区民宿","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶道观群","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"金顶道观群是老君山最有代表性的看点，云海雪景封神，远赴人间惊鸿宴。攻略把它排进主线，时间留得最足。","notice":"云海雪景封神，远赴人间惊鸿宴。这个点位上午光线最好。","durationMinutes":300,"addr":"洛阳市栾川县"},{"spotId":"S2","name":"十里画屏","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"十里画屏是老君山最有代表性的看点，滑道下山，省膝盖。攻略把它排进主线，时间留得最足。","notice":"滑道下山，省膝盖。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"老君山石林"},{"spotId":"S3","name":"追梦谷","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"追梦谷是老君山最有代表性的看点，溪瀑竹林轻松线。攻略把它排进主线，时间留得最足。","notice":"溪瀑竹林轻松线。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"老君山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"栾川豆腐（人均28元）","description":"栾川 · 老君山的招牌是栾川豆腐，山城豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"栾川县城"},{"title":"蝌蚪面（人均18元）","description":"栾川 · 老君山的招牌是蝌蚪面，老君山农家本地人都认这家，点单照攻略不踩雷。","addr":"鸡冠洞乡"},{"title":"玉米糁汤（人均10元）","description":"栾川 · 老君山的招牌是玉米糁汤，农家早餐本地人都认这家，点单照攻略不踩雷。","addr":"景区民宿"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 栾川，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 栾川 的交通方便吗？","推荐先到 栾川，再打车或景区直通车前往核心景区；自驾导航直接搜老君山即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('泰山纯攻略·省钱玩法','guide','泰安 · 泰山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',2500,1300,2,'玉皇顶 / 十八盘 / 岱庙 —— 纯攻略助你玩透泰山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「泰山」两日慢旅行——山岳。泰山墨玉平安扣吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 泰安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴泰安","description":"集合出发，大巴直达泰山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"玉皇顶","description":"抵达后首游玉皇顶，五岳之首看日出，夜爬经典。","addr":"泰安市泰山区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐泰安煎饼（人均12元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"十八盘","description":"早起人少，十八盘精华时段，1600级台阶，紧十八慢十八。","addr":"泰山中天门","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐豆腐宴，人均38元，补充体力。","addr":"岱庙旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"岱庙","description":"午后游览岱庙，历代帝王封禅起点。","addr":"泰山区东岳大街","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"玉皇顶","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"玉皇顶是泰山最有代表性的看点，五岳之首看日出，夜爬经典。攻略把它排进主线，时间留得最足。","notice":"五岳之首看日出，夜爬经典。提前10分钟到，避开旅行团大部队。","durationMinutes":360,"addr":"泰安市泰山区"},{"spotId":"S2","name":"十八盘","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"十八盘是泰山最有代表性的看点，1600级台阶，紧十八慢十八。攻略把它排进主线，时间留得最足。","notice":"1600级台阶，紧十八慢十八。这个点位上午光线最好。","durationMinutes":180,"addr":"泰山中天门"},{"spotId":"S3","name":"岱庙","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"岱庙是泰山最有代表性的看点，历代帝王封禅起点。攻略把它排进主线，时间留得最足。","notice":"历代帝王封禅起点。这个点位上午光线最好。","durationMinutes":90,"addr":"泰山区东岳大街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"泰安煎饼（人均12元）","description":"泰安 · 泰山的招牌是泰安煎饼，煎饼卷大葱本地人都认这家，点单照攻略不踩雷。","addr":"红门路"},{"title":"豆腐宴（人均38元）","description":"泰安 · 泰山的招牌是豆腐宴，岱庙豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"岱庙旁"},{"title":"赤鳞鱼（人均68元）","description":"泰安 · 泰山的招牌是赤鳞鱼，山溪鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"中天门"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","身份证件与手机充电宝","轻便雨衣或折叠伞","少量零食补给","保温水杯与少量现金","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 泰安，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('潮州古城纯攻略·避坑版','guide','潮州 · 潮州古城','food','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1200,600,3,'广济桥 / 牌坊街 / 韩文公祠 —— 纯攻略助你玩透潮州古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「潮州古城」三日深度游——美食。潮州手拉朱泥壶雅致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 潮州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往潮州，抵达后办理入住、熟悉周边环境。","addr":"潮州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"广济桥","description":"下午首站广济桥，调整状态进入旅行节奏，十八梭船廿四洲，灯光秀。","addr":"潮州市湘桥区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游潮州一带氛围拉满，晚餐牛肉火锅人均88元。","addr":"官塘镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"牌坊街","description":"全天主景点牌坊街，23座古牌坊，手拉壶体验。","addr":"湘桥区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蚝烙（人均25元），早点休息。","addr":"西马路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"韩文公祠","description":"收官韩文公祠，纪念韩愈，笔架山对望。","addr":"韩江东岸","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐鸭母捻后集合返程，三日旅程圆满。","addr":"牌坊街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"广济桥","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"广济桥是潮州古城最有代表性的看点，十八梭船廿四洲，灯光秀。攻略把它排进主线，时间留得最足。","notice":"十八梭船廿四洲，灯光秀。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"潮州市湘桥区"},{"spotId":"S2","name":"牌坊街","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"牌坊街是潮州古城最有代表性的看点，23座古牌坊，手拉壶体验。攻略把它排进主线，时间留得最足。","notice":"23座古牌坊，手拉壶体验。这个点位上午光线最好。","durationMinutes":120,"addr":"湘桥区"},{"spotId":"S3","name":"韩文公祠","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"韩文公祠是潮州古城最有代表性的看点，纪念韩愈，笔架山对望。攻略把它排进主线，时间留得最足。","notice":"纪念韩愈，笔架山对望。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"韩江东岸"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牛肉火锅（人均88元）","description":"潮州 · 潮州古城的招牌是牛肉火锅，官塘兄弟本地人都认这家，点单照攻略不踩雷。","addr":"官塘镇"},{"title":"蚝烙（人均25元）","description":"潮州 · 潮州古城的招牌是蚝烙，老柯蚝烙本地人都认这家，点单照攻略不踩雷。","addr":"西马路"},{"title":"鸭母捻（人均12元）","description":"潮州 · 潮州古城的招牌是鸭母捻，胡荣泉本地人都认这家，点单照攻略不踩雷。","addr":"牌坊街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机","轻便雨衣或折叠伞","防晒霜与遮阳帽","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 潮州 的交通方便吗？","推荐先到 潮州，再打车或景区直通车前往核心景区；自驾导航直接搜潮州古城即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 潮州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七彩丹霞纯攻略·深度指南','guide','张掖 · 七彩丹霞','photography','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,12,'七彩丹霞 / 平山湖大峡谷 / 马蹄寺 —— 纯攻略助你玩透七彩丹霞精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「七彩丹霞」两日慢旅行——摄影胜地。张掖圆梨啤特有风味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 张掖"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴张掖","description":"集合出发，大巴直达七彩丹霞，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七彩丹霞","description":"抵达后首游七彩丹霞，上帝的调色盘，4号观景台日落。","addr":"张掖市临泽县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐搓鱼面（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"平山湖大峡谷","description":"早起人少，平山湖大峡谷精华时段，张掖版科罗拉多，越野车深入。","addr":"甘州区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐炒炮，人均18元，补充体力。","addr":"大佛寺旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"马蹄寺","description":"午后游览马蹄寺，石窟与裕固族风情。","addr":"肃南县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七彩丹霞","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"七彩丹霞是七彩丹霞最有代表性的看点，上帝的调色盘，4号观景台日落。攻略把它排进主线，时间留得最足。","notice":"上帝的调色盘，4号观景台日落。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"张掖市临泽县"},{"spotId":"S2","name":"平山湖大峡谷","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"平山湖大峡谷是七彩丹霞最有代表性的看点，张掖版科罗拉多，越野车深入。攻略把它排进主线，时间留得最足。","notice":"张掖版科罗拉多，越野车深入。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"甘州区"},{"spotId":"S3","name":"马蹄寺","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"马蹄寺是七彩丹霞最有代表性的看点，石窟与裕固族风情。攻略把它排进主线，时间留得最足。","notice":"石窟与裕固族风情。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"肃南县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"搓鱼面（人均15元）","description":"张掖 · 七彩丹霞的招牌是搓鱼面，张掖搓鱼子本地人都认这家，点单照攻略不踩雷。","addr":"甘州区"},{"title":"炒炮（人均18元）","description":"张掖 · 七彩丹霞的招牌是炒炮，孙记炒炮本地人都认这家，点单照攻略不踩雷。","addr":"大佛寺旁"},{"title":"牛肉小饭（人均12元）","description":"张掖 · 七彩丹霞的招牌是牛肉小饭，早市小饭馆本地人都认这家，点单照攻略不踩雷。","addr":"南关市场"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）","墨镜与拍照道具","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","少量零食补给"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["到达 张掖 的交通方便吗？","推荐先到 张掖，再打车或景区直通车前往核心景区；自驾导航直接搜七彩丹霞即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 张掖 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雅鲁藏布大峡谷纯攻略·周末版','guide','林芝 · 雅鲁藏布大峡谷','plateau','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',2500,1300,2,'南迦巴瓦观景台 / 雅鲁藏布大峡谷 / 鲁朗林海 —— 纯攻略助你玩透雅鲁藏布大峡谷精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「雅鲁藏布大峡谷」三日深度游——高原。林芝松茸6-8月最鲜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 林芝"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往林芝，抵达后办理入住、熟悉周边环境。","addr":"林芝市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"南迦巴瓦观景台","description":"下午首站南迦巴瓦观景台，调整状态进入旅行节奏，羞女峰十人九不遇，直白村最近。","addr":"米林县派镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游林芝一带氛围拉满，晚餐鲁朗石锅鸡人均128元。","addr":"鲁朗镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"雅鲁藏布大峡谷","description":"全天主景点雅鲁藏布大峡谷，世界最深深峡，换乘游览。","addr":"林芝市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐藏香猪（人均58元），早点休息。","addr":"派镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"鲁朗林海","description":"收官鲁朗林海，东方瑞士，石锅鸡之乡。","addr":"鲁朗镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐松茸炖藏鸡后集合返程，三日旅程圆满。","addr":"林芝市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"南迦巴瓦观景台","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"南迦巴瓦观景台是雅鲁藏布大峡谷最有代表性的看点，羞女峰十人九不遇，直白村最近。攻略把它排进主线，时间留得最足。","notice":"羞女峰十人九不遇，直白村最近。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"米林县派镇"},{"spotId":"S2","name":"雅鲁藏布大峡谷","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"雅鲁藏布大峡谷是雅鲁藏布大峡谷最有代表性的看点，世界最深深峡，换乘游览。攻略把它排进主线，时间留得最足。","notice":"世界最深深峡，换乘游览。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"林芝市"},{"spotId":"S3","name":"鲁朗林海","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"鲁朗林海是雅鲁藏布大峡谷最有代表性的看点，东方瑞士，石锅鸡之乡。攻略把它排进主线，时间留得最足。","notice":"东方瑞士，石锅鸡之乡。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"鲁朗镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"鲁朗石锅鸡（人均128元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是鲁朗石锅鸡，石锅鸡总店本地人都认这家，点单照攻略不踩雷。","addr":"鲁朗镇"},{"title":"藏香猪（人均58元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是藏香猪，工布藏餐本地人都认这家，点单照攻略不踩雷。","addr":"派镇"},{"title":"松茸炖藏鸡（人均98元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是松茸炖藏鸡，林芝菌菇宴本地人都认这家，点单照攻略不踩雷。","addr":"林芝市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","相机或运动相机","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙坡头纯攻略·亲子篇','guide','中卫 · 沙坡头','adventure','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,9,'沙坡头 / 通湖草原 / 66号公路 —— 纯攻略助你玩透沙坡头精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「沙坡头」两日慢旅行——探险地。中卫硒砂瓜甜到心里。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"宁夏 · 中卫"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴中卫","description":"集合出发，大巴直达沙坡头，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"沙坡头","description":"抵达后首游沙坡头，黄河飞索与羊皮筏子，沙漠骑骆驼。","addr":"中卫市沙坡头区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐硒砂瓜（人均10元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"通湖草原","description":"早起人少，通湖草原精华时段，沙漠营地篝火晚会。","addr":"阿拉善左旗","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐黄河大鲤鱼，人均58元，补充体力。","addr":"景区旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"66号公路","description":"午后游览66号公路，网红沙漠公路打卡。","addr":"中卫市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"沙坡头","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"沙坡头是沙坡头最有代表性的看点，黄河飞索与羊皮筏子，沙漠骑骆驼。攻略把它排进主线，时间留得最足。","notice":"黄河飞索与羊皮筏子，沙漠骑骆驼。这个点位上午光线最好。","durationMinutes":240,"addr":"中卫市沙坡头区"},{"spotId":"S2","name":"通湖草原","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"通湖草原是沙坡头最有代表性的看点，沙漠营地篝火晚会。攻略把它排进主线，时间留得最足。","notice":"沙漠营地篝火晚会。这个点位上午光线最好。","durationMinutes":150,"addr":"阿拉善左旗"},{"spotId":"S3","name":"66号公路","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"66号公路是沙坡头最有代表性的看点，网红沙漠公路打卡。攻略把它排进主线，时间留得最足。","notice":"网红沙漠公路打卡。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"中卫市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"硒砂瓜（人均10元）","description":"中卫 · 沙坡头的招牌是硒砂瓜，路边瓜摊本地人都认这家，点单照攻略不踩雷。","addr":"沙坡头"},{"title":"黄河大鲤鱼（人均58元）","description":"中卫 · 沙坡头的招牌是黄河大鲤鱼，沙坡头渔村本地人都认这家，点单照攻略不踩雷。","addr":"景区旁"},{"title":"手抓滩羊（人均68元）","description":"中卫 · 沙坡头的招牌是手抓滩羊，夏华火锅本地人都认这家，点单照攻略不踩雷。","addr":"中卫市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","保温水杯与少量现金","轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 中卫 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滕王阁纯攻略·摄影机位','guide','南昌 · 滕王阁','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1990,1000,5,'滕王阁 / 万寿宫历史文化街区 / 秋水广场 —— 纯攻略助你玩透滕王阁精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「滕王阁」三日深度游——文艺。南昌瓷板画是独特纪念品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 南昌"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往南昌，抵达后办理入住、熟悉周边环境。","addr":"南昌市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"滕王阁","description":"下午首站滕王阁，调整状态进入旅行节奏，落霞与孤鹜齐名的主阁，登顶看赣江。","addr":"南昌市东湖区仿古街58号","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游南昌一带氛围拉满，晚餐瓦罐汤人均18元。","addr":"万寿宫街区巷口","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"万寿宫历史文化街区","description":"全天主景点万寿宫历史文化街区，夜市烟火气，白天逛老建筑。","addr":"西湖区中山路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐拌粉（人均12元），早点休息。","addr":"中山路支巷","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"秋水广场","description":"收官秋水广场，亚洲最大音乐喷泉群，晚上两场。","addr":"红谷滩区赣江中大道","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐白糖糕后集合返程，三日旅程圆满。","addr":"万寿宫内街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"滕王阁","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"滕王阁是滕王阁最有代表性的看点，落霞与孤鹜齐名的主阁，登顶看赣江。攻略把它排进主线，时间留得最足。","notice":"落霞与孤鹜齐名的主阁，登顶看赣江。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"南昌市东湖区仿古街58号"},{"spotId":"S2","name":"万寿宫历史文化街区","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"万寿宫历史文化街区是滕王阁最有代表性的看点，夜市烟火气，白天逛老建筑。攻略把它排进主线，时间留得最足。","notice":"夜市烟火气，白天逛老建筑。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"西湖区中山路"},{"spotId":"S3","name":"秋水广场","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"秋水广场是滕王阁最有代表性的看点，亚洲最大音乐喷泉群，晚上两场。攻略把它排进主线，时间留得最足。","notice":"亚洲最大音乐喷泉群，晚上两场。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"红谷滩区赣江中大道"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"瓦罐汤（人均18元）","description":"南昌 · 滕王阁的招牌是瓦罐汤，民间瓦罐汤店本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫街区巷口"},{"title":"拌粉（人均12元）","description":"南昌 · 滕王阁的招牌是拌粉，南昌拌粉总店本地人都认这家，点单照攻略不踩雷。","addr":"中山路支巷"},{"title":"白糖糕（人均8元）","description":"南昌 · 滕王阁的招牌是白糖糕，老字号糕点铺本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","墨镜与拍照道具","身份证件与手机充电宝","保温水杯与少量现金","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["几月份去 南昌 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 南昌，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 南昌 的交通方便吗？","推荐先到 南昌，再打车或景区直通车前往核心景区；自驾导航直接搜滕王阁即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('凤凰古城纯攻略·美食清单','guide','湘西 · 凤凰古城','ancient_town','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',2500,1300,1,'沱江跳岩 / 沈从文故居 / 南华山 —— 纯攻略助你玩透凤凰古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「凤凰古城」两日慢旅行——古镇。凤凰银饰认准足银999。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 湘西"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴湘西","description":"集合出发，大巴直达凤凰古城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"沱江跳岩","description":"抵达后首游沱江跳岩，清晨雾气中的吊脚楼最出片。","addr":"凤凰古城沱江北门","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐血粑鸭（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"沈从文故居","description":"早起人少，沈从文故居精华时段，文学爱好者必打卡，讲解值得请。","addr":"凤凰古城中营街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐苗家酸汤鱼，人均68元，补充体力。","addr":"沱江边吊脚楼","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南华山","description":"午后游览南华山，登高俯瞰全城夜景。","addr":"凤凰城南","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"沱江跳岩","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"沱江跳岩是凤凰古城最有代表性的看点，清晨雾气中的吊脚楼最出片。攻略把它排进主线，时间留得最足。","notice":"清晨雾气中的吊脚楼最出片。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"凤凰古城沱江北门"},{"spotId":"S2","name":"沈从文故居","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"沈从文故居是凤凰古城最有代表性的看点，文学爱好者必打卡，讲解值得请。攻略把它排进主线，时间留得最足。","notice":"文学爱好者必打卡，讲解值得请。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"凤凰古城中营街"},{"spotId":"S3","name":"南华山","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"南华山是凤凰古城最有代表性的看点，登高俯瞰全城夜景。攻略把它排进主线，时间留得最足。","notice":"登高俯瞰全城夜景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"凤凰城南"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"血粑鸭（人均58元）","description":"湘西 · 凤凰古城的招牌是血粑鸭，凤凰老字号本地人都认这家，点单照攻略不踩雷。","addr":"虹桥东路"},{"title":"苗家酸汤鱼（人均68元）","description":"湘西 · 凤凰古城的招牌是苗家酸汤鱼，古城酸汤鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"沱江边吊脚楼"},{"title":"凤凰姜糖（人均15元）","description":"湘西 · 凤凰古城的招牌是凤凰姜糖，老街姜糖铺本地人都认这家，点单照攻略不踩雷。","addr":"东正街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","保温水杯与少量现金","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大理古城洱海纯攻略·自由行手册','guide','大理 · 大理古城洱海','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1990,1000,2,'洱海生态廊道 / 大理古城 / 崇圣寺三塔 —— 纯攻略助你玩透大理古城洱海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大理古城洱海」三日深度游——水景。喜洲粑粑现烤的最香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 大理"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大理，抵达后办理入住、熟悉周边环境。","addr":"大理市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"洱海生态廊道","description":"下午首站洱海生态廊道，调整状态进入旅行节奏，租电动车骑行，S湾拍倒影。","addr":"大理市环海西路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大理一带氛围拉满，晚餐白族三道茶人均48元。","addr":"喜洲古镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大理古城","description":"全天主景点大理古城，洋人街与五华楼，夜晚酒吧街热闹。","addr":"大理市一塔路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐砂锅鱼（人均78元），早点休息。","addr":"才村码头","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"崇圣寺三塔","description":"收官崇圣寺三塔，大理地标，倒影公园拍三塔。","addr":"大理市三塔路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐乳扇后集合返程，三日旅程圆满。","addr":"古城人民路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"洱海生态廊道","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"洱海生态廊道是大理古城洱海最有代表性的看点，租电动车骑行，S湾拍倒影。攻略把它排进主线，时间留得最足。","notice":"租电动车骑行，S湾拍倒影。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"大理市环海西路"},{"spotId":"S2","name":"大理古城","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"大理古城是大理古城洱海最有代表性的看点，洋人街与五华楼，夜晚酒吧街热闹。攻略把它排进主线，时间留得最足。","notice":"洋人街与五华楼，夜晚酒吧街热闹。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"大理市一塔路"},{"spotId":"S3","name":"崇圣寺三塔","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"崇圣寺三塔是大理古城洱海最有代表性的看点，大理地标，倒影公园拍三塔。攻略把它排进主线，时间留得最足。","notice":"大理地标，倒影公园拍三塔。这个点位上午光线最好。","durationMinutes":120,"addr":"大理市三塔路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"白族三道茶（人均48元）","description":"大理 · 大理古城洱海的招牌是白族三道茶，严家大院本地人都认这家，点单照攻略不踩雷。","addr":"喜洲古镇"},{"title":"砂锅鱼（人均78元）","description":"大理 · 大理古城洱海的招牌是砂锅鱼，大理砂锅鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"才村码头"},{"title":"乳扇（人均12元）","description":"大理 · 大理古城洱海的招牌是乳扇，杨记乳扇本地人都认这家，点单照攻略不踩雷。","addr":"古城人民路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","相机或运动相机","身份证件与手机充电宝","少量零食补给","轻便雨衣或折叠伞","保温水杯与少量现金","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["几月份去 大理 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 大理 的交通方便吗？","推荐先到 大理，再打车或景区直通车前往核心景区；自驾导航直接搜大理古城洱海即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九寨沟纯攻略·省钱玩法','guide','阿坝 · 九寨沟','water','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,2,'五花海 / 诺日朗瀑布 / 长海 —— 纯攻略助你玩透九寨沟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九寨沟」两日慢旅行——水景。九寨沟牦牛酸奶值得尝。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达九寨沟，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"五花海","description":"抵达后首游五花海，九寨精华，孔雀河道顺光最美。","addr":"九寨沟县漳扎镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐牦牛肉汤锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"诺日朗瀑布","description":"早起人少，诺日朗瀑布精华时段，中国最宽钙华瀑布。","addr":"九寨沟中心站","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐青稞酒，人均30元，补充体力。","addr":"藏寨","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"长海","description":"午后游览长海，最大海子，雪山倒影。","addr":"九寨沟则查洼沟","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"五花海","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"五花海是九寨沟最有代表性的看点，九寨精华，孔雀河道顺光最美。攻略把它排进主线，时间留得最足。","notice":"九寨精华，孔雀河道顺光最美。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"九寨沟县漳扎镇"},{"spotId":"S2","name":"诺日朗瀑布","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"诺日朗瀑布是九寨沟最有代表性的看点，中国最宽钙华瀑布。攻略把它排进主线，时间留得最足。","notice":"中国最宽钙华瀑布。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"九寨沟中心站"},{"spotId":"S3","name":"长海","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"长海是九寨沟最有代表性的看点，最大海子，雪山倒影。攻略把它排进主线，时间留得最足。","notice":"最大海子，雪山倒影。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"九寨沟则查洼沟"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉汤锅（人均78元）","description":"阿坝 · 九寨沟的招牌是牦牛肉汤锅，沟口藏家本地人都认这家，点单照攻略不踩雷。","addr":"漳扎镇"},{"title":"青稞酒（人均30元）","description":"阿坝 · 九寨沟的招牌是青稞酒，藏家体验本地人都认这家，点单照攻略不踩雷。","addr":"藏寨"},{"title":"糌粑（人均20元）","description":"阿坝 · 九寨沟的招牌是糌粑，藏族人家本地人都认这家，点单照攻略不踩雷。","addr":"树正寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","墨镜与拍照道具","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 阿坝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 阿坝 的交通方便吗？","推荐先到 阿坝，再打车或景区直通车前往核心景区；自驾导航直接搜九寨沟即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('荔波小七孔纯攻略·避坑版','guide','黔南 · 荔波小七孔','water','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',990,500,2,'小七孔古桥 / 卧龙潭 / 大七孔 —— 纯攻略助你玩透荔波小七孔精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「荔波小七孔」三日深度游——水景。荔波青梅制品酸甜开胃。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黔南，抵达后办理入住、熟悉周边环境。","addr":"黔南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"小七孔古桥","description":"下午首站小七孔古桥，调整状态进入旅行节奏，68级跌水瀑布起点，绿宝石湖水。","addr":"荔波县小七孔镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黔南一带氛围拉满，晚餐酸汤鱼人均68元。","addr":"荔波县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"卧龙潭","description":"全天主景点卧龙潭，蓝到不真实的深潭，漂流出片。","addr":"小七孔景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐杨梅汤（人均10元），早点休息。","addr":"小七孔镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"大七孔","description":"收官大七孔，天生桥鬼斧神工。","addr":"荔波县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糯米排骨后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"小七孔古桥","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"小七孔古桥是荔波小七孔最有代表性的看点，68级跌水瀑布起点，绿宝石湖水。攻略把它排进主线，时间留得最足。","notice":"68级跌水瀑布起点，绿宝石湖水。这个点位上午光线最好。","durationMinutes":180,"addr":"荔波县小七孔镇"},{"spotId":"S2","name":"卧龙潭","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"卧龙潭是荔波小七孔最有代表性的看点，蓝到不真实的深潭，漂流出片。攻略把它排进主线，时间留得最足。","notice":"蓝到不真实的深潭，漂流出片。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"小七孔景区"},{"spotId":"S3","name":"大七孔","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"大七孔是荔波小七孔最有代表性的看点，天生桥鬼斧神工。攻略把它排进主线，时间留得最足。","notice":"天生桥鬼斧神工。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"荔波县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均68元）","description":"黔南 · 荔波小七孔的招牌是酸汤鱼，凯里酸汤鱼本地人都认这家，点单照攻略不踩雷。","addr":"荔波县城"},{"title":"杨梅汤（人均10元）","description":"黔南 · 荔波小七孔的招牌是杨梅汤，街边饮品本地人都认这家，点单照攻略不踩雷。","addr":"小七孔镇"},{"title":"糯米排骨（人均42元）","description":"黔南 · 荔波小七孔的招牌是糯米排骨，布依农家本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","相机或运动相机","轻便雨衣或折叠伞","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('涠洲岛纯攻略·深度指南','guide','北海 · 涠洲岛','sea','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1500,800,6,'鳄鱼山火山公园 / 五彩滩 / 滴水丹屏 —— 纯攻略助你玩透涠洲岛精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「涠洲岛」两日慢旅行——海滨。涠洲岛香蕉又软又甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 北海"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴北海","description":"集合出发，大巴直达涠洲岛，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"鳄鱼山火山公园","description":"抵达后首游鳄鱼山火山公园，火山地质地貌，灯塔海景。","addr":"涠洲岛南湾","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐海鲜大餐（人均98元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"五彩滩","description":"早起人少，五彩滩精华时段，退潮时火山岩纹理最美。","addr":"涠洲岛东岸","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香蕉猪，人均58元，补充体力。","addr":"滴水村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"滴水丹屏","description":"午后游览滴水丹屏，日落圣地，海水退潮捡贝壳。","addr":"涠洲岛西侧","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"鳄鱼山火山公园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"鳄鱼山火山公园是涠洲岛最有代表性的看点，火山地质地貌，灯塔海景。攻略把它排进主线，时间留得最足。","notice":"火山地质地貌，灯塔海景。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"涠洲岛南湾"},{"spotId":"S2","name":"五彩滩","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"五彩滩是涠洲岛最有代表性的看点，退潮时火山岩纹理最美。攻略把它排进主线，时间留得最足。","notice":"退潮时火山岩纹理最美。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"涠洲岛东岸"},{"spotId":"S3","name":"滴水丹屏","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"滴水丹屏是涠洲岛最有代表性的看点，日落圣地，海水退潮捡贝壳。攻略把它排进主线，时间留得最足。","notice":"日落圣地，海水退潮捡贝壳。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"涠洲岛西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜大餐（人均98元）","description":"北海 · 涠洲岛的招牌是海鲜大餐，南湾海鲜市场加工本地人都认这家，点单照攻略不踩雷。","addr":"南湾街"},{"title":"香蕉猪（人均58元）","description":"北海 · 涠洲岛的招牌是香蕉猪，岛民农家本地人都认这家，点单照攻略不踩雷。","addr":"滴水村"},{"title":"椰子冻（人均15元）","description":"北海 · 涠洲岛的招牌是椰子冻，夜市摊本地人都认这家，点单照攻略不踩雷。","addr":"南湾夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","相机或运动相机","保温水杯与少量现金","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["几月份去 北海 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 北海 的交通方便吗？","推荐先到 北海，再打车或景区直通车前往核心景区；自驾导航直接搜涠洲岛即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('西湖灵隐纯攻略·周末版','guide','杭州 · 西湖灵隐','water','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',990,500,2,'西湖断桥苏堤 / 灵隐寺飞来峰 / 龙井村 —— 纯攻略助你玩透西湖灵隐精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「西湖灵隐」三日深度游——水景。明前龙井茶农直购最划算。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 杭州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往杭州，抵达后办理入住、熟悉周边环境。","addr":"杭州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"西湖断桥苏堤","description":"下午首站西湖断桥苏堤，调整状态进入旅行节奏，清晨环湖骑行，断桥残雪碑打卡。","addr":"杭州市西湖区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游杭州一带氛围拉满，晚餐西湖醋鱼人均98元。","addr":"孤山路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"灵隐寺飞来峰","description":"全天主景点灵隐寺飞来峰，石窟造像与古刹，香火鼎盛。","addr":"西湖区灵隐路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐龙井虾仁（人均58元），早点休息。","addr":"西湖天地","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"龙井村","description":"收官龙井村，茶山徒步至九溪十八涧。","addr":"西湖区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐片儿川后集合返程，三日旅程圆满。","addr":"中山中路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"西湖断桥苏堤","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"西湖断桥苏堤是西湖灵隐最有代表性的看点，清晨环湖骑行，断桥残雪碑打卡。攻略把它排进主线，时间留得最足。","notice":"清晨环湖骑行，断桥残雪碑打卡。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"杭州市西湖区"},{"spotId":"S2","name":"灵隐寺飞来峰","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"灵隐寺飞来峰是西湖灵隐最有代表性的看点，石窟造像与古刹，香火鼎盛。攻略把它排进主线，时间留得最足。","notice":"石窟造像与古刹，香火鼎盛。这个点位上午光线最好。","durationMinutes":150,"addr":"西湖区灵隐路"},{"spotId":"S3","name":"龙井村","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"龙井村是西湖灵隐最有代表性的看点，茶山徒步至九溪十八涧。攻略把它排进主线，时间留得最足。","notice":"茶山徒步至九溪十八涧。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"西湖区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"西湖醋鱼（人均98元）","description":"杭州 · 西湖灵隐的招牌是西湖醋鱼，楼外楼本地人都认这家，点单照攻略不踩雷。","addr":"孤山路"},{"title":"龙井虾仁（人均58元）","description":"杭州 · 西湖灵隐的招牌是龙井虾仁，绿茶餐厅本地人都认这家，点单照攻略不踩雷。","addr":"西湖天地"},{"title":"片儿川（人均25元）","description":"杭州 · 西湖灵隐的招牌是片儿川，菊英面馆本地人都认这家，点单照攻略不踩雷。","addr":"中山中路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","保温水杯与少量现金","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["几月份去 杭州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('夫子庙中山陵纯攻略·亲子篇','guide','南京 · 夫子庙中山陵','red','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',1990,1000,7,'中山陵 / 夫子庙秦淮河 / 明孝陵石象路 —— 纯攻略助你玩透夫子庙中山陵精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「夫子庙中山陵」两日慢旅行——人文。南京雨花石送小朋友最爱。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 南京"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南京","description":"集合出发，大巴直达夫子庙中山陵，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中山陵","description":"抵达后首游中山陵，392级台阶，民国气势。","addr":"南京市玄武区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐盐水鸭（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"夫子庙秦淮河","description":"早起人少，夫子庙秦淮河精华时段，夜泊秦淮，画舫灯影。","addr":"秦淮区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐鸭血粉丝汤，人均18元，补充体力。","addr":"老门东","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"明孝陵石象路","description":"午后游览明孝陵石象路，秋日梧桐大道封神。","addr":"玄武区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中山陵","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"中山陵是夫子庙中山陵最有代表性的看点，392级台阶，民国气势。攻略把它排进主线，时间留得最足。","notice":"392级台阶，民国气势。这个点位上午光线最好。","durationMinutes":150,"addr":"南京市玄武区"},{"spotId":"S2","name":"夫子庙秦淮河","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"夫子庙秦淮河是夫子庙中山陵最有代表性的看点，夜泊秦淮，画舫灯影。攻略把它排进主线，时间留得最足。","notice":"夜泊秦淮，画舫灯影。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"秦淮区"},{"spotId":"S3","name":"明孝陵石象路","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"明孝陵石象路是夫子庙中山陵最有代表性的看点，秋日梧桐大道封神。攻略把它排进主线，时间留得最足。","notice":"秋日梧桐大道封神。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"玄武区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"盐水鸭（人均45元）","description":"南京 · 夫子庙中山陵的招牌是盐水鸭，桂花鸭专卖店本地人都认这家，点单照攻略不踩雷。","addr":"夫子庙"},{"title":"鸭血粉丝汤（人均18元）","description":"南京 · 夫子庙中山陵的招牌是鸭血粉丝汤，回味本地人都认这家，点单照攻略不踩雷。","addr":"老门东"},{"title":"汤包（人均22元）","description":"南京 · 夫子庙中山陵的招牌是汤包，鸡鸣汤包本地人都认这家，点单照攻略不踩雷。","addr":"科巷"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","少量零食补给","身份证件与手机充电宝","保温水杯与少量现金","防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武当山纯攻略·摄影机位','guide','十堰 · 武当山','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,2,'金顶 / 南岩宫 / 紫霄宫 —— 纯攻略助你玩透武当山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武当山」三日深度游——山岳。武当道茶甘醇。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 十堰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往十堰，抵达后办理入住、熟悉周边环境。","addr":"十堰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，武当之巅金殿，转运台。","addr":"十堰市丹江口","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游十堰一带氛围拉满，晚餐道家素斋人均48元。","addr":"武当山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"南岩宫","description":"全天主景点南岩宫，龙头香悬崖奇观。","addr":"武当山南岩","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐武当冻豆腐（人均38元），早点休息。","addr":"南岩","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"紫霄宫","description":"收官紫霄宫，皇家道观规制。","addr":"武当山展旗峰","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐太极养生汤后集合返程，三日旅程圆满。","addr":"紫霄宫旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武当山最有代表性的看点，武当之巅金殿，转运台。攻略把它排进主线，时间留得最足。","notice":"武当之巅金殿，转运台。这个点位上午光线最好。","durationMinutes":240,"addr":"十堰市丹江口"},{"spotId":"S2","name"