INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('兵马俑城墙纯攻略·美食清单','guide','西安 · 兵马俑城墙','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1990,1000,7,'秦始皇兵马俑 / 西安城墙 / 大唐不夜城 —— 纯攻略助你玩透兵马俑城墙精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「兵马俑城墙」两日慢旅行——人文。兵马俑文创手办很火。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 西安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴西安","description":"集合出发，大巴直达兵马俑城墙，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"秦始皇兵马俑","description":"抵达后首游秦始皇兵马俑，一号坑震撼，讲解必请。","addr":"西安市临潼区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐肉夹馍（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"西安城墙","description":"早起人少，西安城墙精华时段，骑行环城14公里，日落最美。","addr":"碑林区南门","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐biangbiang面，人均22元，补充体力。","addr":"南院门","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大唐不夜城","description":"午后游览大唐不夜城，不倒翁小姐姐与灯光夜市。","addr":"雁塔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"秦始皇兵马俑","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"秦始皇兵马俑是兵马俑城墙最有代表性的看点，一号坑震撼，讲解必请。攻略把它排进主线，时间留得最足。","notice":"一号坑震撼，讲解必请。这个点位上午光线最好。","durationMinutes":240,"addr":"西安市临潼区"},{"spotId":"S2","name":"西安城墙","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"西安城墙是兵马俑城墙最有代表性的看点，骑行环城14公里，日落最美。攻略把它排进主线，时间留得最足。","notice":"骑行环城14公里，日落最美。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"碑林区南门"},{"spotId":"S3","name":"大唐不夜城","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"大唐不夜城是兵马俑城墙最有代表性的看点，不倒翁小姐姐与灯光夜市。攻略把它排进主线，时间留得最足。","notice":"不倒翁小姐姐与灯光夜市。这个点位上午光线最好。","durationMinutes":150,"addr":"雁塔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肉夹馍（人均15元）","description":"西安 · 兵马俑城墙的招牌是肉夹馍，子午路张记本地人都认这家，点单照攻略不踩雷。","addr":"临潼区"},{"title":"biangbiang面（人均22元）","description":"西安 · 兵马俑城墙的招牌是biangbiang面，老碗会本地人都认这家，点单照攻略不踩雷。","addr":"南院门"},{"title":"羊肉泡馍（人均45元）","description":"西安 · 兵马俑城墙的招牌是羊肉泡馍，老孙家本地人都认这家，点单照攻略不踩雷。","addr":"东关正街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机","墨镜与拍照道具","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 西安 的交通方便吗？","推荐先到 西安，再打车或景区直通车前往核心景区；自驾导航直接搜兵马俑城墙即可。"],["当地有什么必吃？","到了 西安，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('栈桥崂山纯攻略·自由行手册','guide','青岛 · 栈桥崂山','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1990,1000,6,'栈桥 / 崂山仰口 / 八大关 —— 纯攻略助你玩透栈桥崂山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「栈桥崂山」三日深度游——海滨。青岛啤酒原浆当天最新鲜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 青岛"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往青岛，抵达后办理入住、熟悉周边环境。","addr":"青岛市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"栈桥","description":"下午首站栈桥，调整状态进入旅行节奏，回澜阁海鸥季，夜色灯光。","addr":"青岛市市南区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游青岛一带氛围拉满，晚餐海鲜水饺人均58元。","addr":"闽江路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"崂山仰口","description":"全天主景点崂山仰口，海上第一名山，觅天洞。","addr":"崂山区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐野馄饨（人均15元），早点休息。","addr":"登州路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"八大关","description":"收官八大关，万国建筑与梧桐，秋天最美。","addr":"市南区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐崂山菇炖鸡后集合返程，三日旅程圆满。","addr":"仰口湾","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"栈桥","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"栈桥是栈桥崂山最有代表性的看点，回澜阁海鸥季，夜色灯光。攻略把它排进主线，时间留得最足。","notice":"回澜阁海鸥季，夜色灯光。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"青岛市市南区"},{"spotId":"S2","name":"崂山仰口","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"崂山仰口是栈桥崂山最有代表性的看点，海上第一名山，觅天洞。攻略把它排进主线，时间留得最足。","notice":"海上第一名山，觅天洞。这个点位上午光线最好。","durationMinutes":180,"addr":"崂山区"},{"spotId":"S3","name":"八大关","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"八大关是栈桥崂山最有代表性的看点，万国建筑与梧桐，秋天最美。攻略把它排进主线，时间留得最足。","notice":"万国建筑与梧桐，秋天最美。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"市南区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜水饺（人均58元）","description":"青岛 · 栈桥崂山的招牌是海鲜水饺，船歌鱼水饺本地人都认这家，点单照攻略不踩雷。","addr":"闽江路"},{"title":"野馄饨（人均15元）","description":"青岛 · 栈桥崂山的招牌是野馄饨，夜市馄饨摊本地人都认这家，点单照攻略不踩雷。","addr":"登州路"},{"title":"崂山菇炖鸡（人均68元）","description":"青岛 · 栈桥崂山的招牌是崂山菇炖鸡，山海农家本地人都认这家，点单照攻略不踩雷。","addr":"仰口湾"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","相机或运动相机","保温水杯与少量现金","轻便雨衣或折叠伞","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 青岛 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七星岩纯攻略·省钱玩法','guide','肇庆 · 七星岩','water','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1990,1000,2,'七星岩 / 鼎湖山 / 紫云谷 —— 纯攻略助你玩透七星岩精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「七星岩」两日慢旅行——水景。端砚四大名砚之首。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 肇庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴肇庆","description":"集合出发，大巴直达七星岩，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七星岩","description":"抵达后首游七星岩，岭南第一奇观，湖山相映。","addr":"肇庆市端州区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐裹蒸粽（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"鼎湖山","description":"早起人少，鼎湖山精华时段，北回归线上的绿宝石，庆云寺。","addr":"鼎湖区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐文庆鲤，人均68元，补充体力。","addr":"鼎湖区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"紫云谷","description":"午后游览紫云谷，端砚石产地，溪水清凉。","addr":"羚羊峡","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七星岩","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"七星岩是七星岩最有代表性的看点，岭南第一奇观，湖山相映。攻略把它排进主线，时间留得最足。","notice":"岭南第一奇观，湖山相映。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"肇庆市端州区"},{"spotId":"S2","name":"鼎湖山","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"鼎湖山是七星岩最有代表性的看点，北回归线上的绿宝石，庆云寺。攻略把它排进主线，时间留得最足。","notice":"北回归线上的绿宝石，庆云寺。这个点位上午光线最好。","durationMinutes":180,"addr":"鼎湖区"},{"spotId":"S3","name":"紫云谷","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"紫云谷是七星岩最有代表性的看点，端砚石产地，溪水清凉。攻略把它排进主线，时间留得最足。","notice":"端砚石产地，溪水清凉。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"羚羊峡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"裹蒸粽（人均15元）","description":"肇庆 · 七星岩的招牌是裹蒸粽，皇中皇本地人都认这家，点单照攻略不踩雷。","addr":"端州区"},{"title":"文庆鲤（人均68元）","description":"肇庆 · 七星岩的招牌是文庆鲤，文庆鲤餐馆本地人都认这家，点单照攻略不踩雷。","addr":"鼎湖区"},{"title":"茶油鸡（人均48元）","description":"肇庆 · 七星岩的招牌是茶油鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"七星岩东门"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","相机或运动相机","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道"],"faqs":[["几月份去 肇庆 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('青海湖茶卡纯攻略·避坑版','guide','海南州 · 青海湖茶卡','plateau','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,2,'二郎剑景区 / 茶卡盐湖 / 日月山 —— 纯攻略助你玩透青海湖茶卡精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「青海湖茶卡」三日深度游——高原。青海湖黄蘑菇炖汤鲜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"青海 · 海南州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往海南州，抵达后办理入住、熟悉周边环境。","addr":"海南州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"二郎剑景区","description":"下午首站二郎剑景区，调整状态进入旅行节奏，油菜花与蓝湖，骑行湖岸。","addr":"共和县青海湖南岸","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游海南州一带氛围拉满，晚餐老酸奶人均10元。","addr":"环湖公路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"茶卡盐湖","description":"全天主景点茶卡盐湖，天空之镜，赤脚下盐滩。","addr":"乌兰县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊肉汤（人均35元），早点休息。","addr":"黑马河乡","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"日月山","description":"收官日月山，文成公主进藏口，倒淌河。","addr":"湟源县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糌粑后集合返程，三日旅程圆满。","addr":"茶卡镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"二郎剑景区","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"二郎剑景区是青海湖茶卡最有代表性的看点，油菜花与蓝湖，骑行湖岸。攻略把它排进主线，时间留得最足。","notice":"油菜花与蓝湖，骑行湖岸。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"共和县青海湖南岸"},{"spotId":"S2","name":"茶卡盐湖","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"茶卡盐湖是青海湖茶卡最有代表性的看点，天空之镜，赤脚下盐滩。攻略把它排进主线，时间留得最足。","notice":"天空之镜，赤脚下盐滩。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"乌兰县"},{"spotId":"S3","name":"日月山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"日月山是青海湖茶卡最有代表性的看点，文成公主进藏口，倒淌河。攻略把它排进主线，时间留得最足。","notice":"文成公主进藏口，倒淌河。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"湟源县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"老酸奶（人均10元）","description":"海南州 · 青海湖茶卡的招牌是老酸奶，青海老酸奶本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"},{"title":"羊肉汤（人均35元）","description":"海南州 · 青海湖茶卡的招牌是羊肉汤，藏家羊汤本地人都认这家，点单照攻略不踩雷。","addr":"黑马河乡"},{"title":"糌粑（人均20元）","description":"海南州 · 青海湖茶卡的招牌是糌粑，牧民家访本地人都认这家，点单照攻略不踩雷。","addr":"茶卡镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","少量零食补给","墨镜与拍照道具","相机或运动相机","保温水杯与少量现金","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["几月份去 海南州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('呼伦贝尔草原纯攻略·深度指南','guide','呼伦贝尔 · 呼伦贝尔草原','village','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1500,800,1,'莫日格勒河 / 额尔古纳湿地 / 恩和俄罗斯族乡 —— 纯攻略助你玩透呼伦贝尔草原精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「呼伦贝尔草原」两日慢旅行——古村落。呼伦贝尔风干牛肉原味香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"内蒙古 · 呼伦贝尔"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴呼伦贝尔","description":"集合出发，大巴直达呼伦贝尔草原，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"莫日格勒河","description":"抵达后首游莫日格勒河，天下第一曲水，断崖机位。","addr":"陈巴尔虎旗","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐烤羊腿（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"额尔古纳湿地","description":"早起人少，额尔古纳湿地精华时段，亚洲第一湿地，日落金色。","addr":"额尔古纳市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐蒙古锅茶，人均35元，补充体力。","addr":"陈巴尔虎旗","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"恩和俄罗斯族乡","description":"午后游览恩和俄罗斯族乡，木刻楞小屋与列巴。","addr":"额尔古纳市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"莫日格勒河","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"莫日格勒河是呼伦贝尔草原最有代表性的看点，天下第一曲水，断崖机位。攻略把它排进主线，时间留得最足。","notice":"天下第一曲水，断崖机位。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"陈巴尔虎旗"},{"spotId":"S2","name":"额尔古纳湿地","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"额尔古纳湿地是呼伦贝尔草原最有代表性的看点，亚洲第一湿地，日落金色。攻略把它排进主线，时间留得最足。","notice":"亚洲第一湿地，日落金色。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"额尔古纳市"},{"spotId":"S3","name":"恩和俄罗斯族乡","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"恩和俄罗斯族乡是呼伦贝尔草原最有代表性的看点，木刻楞小屋与列巴。攻略把它排进主线，时间留得最足。","notice":"木刻楞小屋与列巴。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"额尔古纳市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤羊腿（人均128元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是烤羊腿，草原牧民人家本地人都认这家，点单照攻略不踩雷。","addr":"黑山头镇"},{"title":"蒙古锅茶（人均35元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是蒙古锅茶，牧户家访本地人都认这家，点单照攻略不踩雷。","addr":"陈巴尔虎旗"},{"title":"俄罗斯列巴（人均15元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是俄罗斯列巴，恩和列巴坊本地人都认这家，点单照攻略不踩雷。","addr":"恩和乡"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","少量零食补给","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["当地有什么必吃？","到了 呼伦贝尔，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('婺源篁岭纯攻略·周末版','guide','上饶 · 婺源篁岭','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',1200,600,1,'晒秋人家 / 垒心桥 / 梯田花海 —— 纯攻略助你玩透婺源篁岭精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「婺源篁岭」三日深度游——古村落。婺源荷包红鲤鱼可真空打包带回家。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往上饶，抵达后办理入住、熟悉周边环境。","addr":"上饶市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"晒秋人家","description":"下午首站晒秋人家，调整状态进入旅行节奏，晒秋最佳拍摄位在天街中层，上午顺光。","addr":"婺源县江湾镇篁岭村","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游上饶一带氛围拉满，晚餐蒸汽糕人均28元。","addr":"篁岭天街中段","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"垒心桥","description":"全天主景点垒心桥，桥面风大，手机拿稳。","addr":"篁岭景区索道上站","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐清明果（人均15元），早点休息。","addr":"篁岭古村巷内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"梯田花海","description":"收官梯田花海，春季油菜花、秋季稻浪，两季都出片。","addr":"篁岭村北坡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐荷包红鲤鱼后集合返程，三日旅程圆满。","addr":"篁岭村口第一家","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"晒秋人家","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"晒秋人家是婺源篁岭最有代表性的看点，晒秋最佳拍摄位在天街中层，上午顺光。攻略把它排进主线，时间留得最足。","notice":"晒秋最佳拍摄位在天街中层，上午顺光。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"婺源县江湾镇篁岭村"},{"spotId":"S2","name":"垒心桥","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"垒心桥是婺源篁岭最有代表性的看点，桥面风大，手机拿稳。攻略把它排进主线，时间留得最足。","notice":"桥面风大，手机拿稳。这个点位上午光线最好。","durationMinutes":60,"addr":"篁岭景区索道上站"},{"spotId":"S3","name":"梯田花海","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"梯田花海是婺源篁岭最有代表性的看点，春季油菜花、秋季稻浪，两季都出片。攻略把它排进主线，时间留得最足。","notice":"春季油菜花、秋季稻浪，两季都出片。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"篁岭村北坡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蒸汽糕（人均28元）","description":"上饶 · 婺源篁岭的招牌是蒸汽糕，天街食府本地人都认这家，点单照攻略不踩雷。","addr":"篁岭天街中段"},{"title":"清明果（人均15元）","description":"上饶 · 婺源篁岭的招牌是清明果，晒秋人家小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"篁岭古村巷内"},{"title":"荷包红鲤鱼（人均68元）","description":"上饶 · 婺源篁岭的招牌是荷包红鲤鱼，篁岭酒楼本地人都认这家，点单照攻略不踩雷。","addr":"篁岭村口第一家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","相机或运动相机","舒适徒步鞋（防滑鞋底）","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 上饶，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 上饶 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('陶溪川纯攻略·亲子篇','guide','景德镇 · 陶溪川','art','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,5,'陶溪川文创街区 / 古窑民俗博览区 / 雕塑瓷厂乐天市集 —— 纯攻略助你玩透陶溪川精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「陶溪川」两日慢旅行——文艺。景德镇薄胎瓷碗轻巧又体面。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 景德镇"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴景德镇","description":"集合出发，大巴直达陶溪川，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"陶溪川文创街区","description":"抵达后首游陶溪川文创街区，夜市周五六日开，手作摊最好逛。","addr":"珠山区新厂西路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐饺子粑（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"古窑民俗博览区","description":"早起人少，古窑民俗博览区精华时段，看柴窑镇窑复烧，拉坯体验要排队。","addr":"昌江区枫树山蟠龙岗","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐冷粉，人均12元，补充体力。","addr":"人民广场附近","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"雕塑瓷厂乐天市集","description":"午后游览雕塑瓷厂乐天市集，周六上午开市，淘手作好物。","addr":"新厂东路139号","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"陶溪川文创街区","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"陶溪川文创街区是陶溪川最有代表性的看点，夜市周五六日开，手作摊最好逛。攻略把它排进主线，时间留得最足。","notice":"夜市周五六日开，手作摊最好逛。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"珠山区新厂西路"},{"spotId":"S2","name":"古窑民俗博览区","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"古窑民俗博览区是陶溪川最有代表性的看点，看柴窑镇窑复烧，拉坯体验要排队。攻略把它排进主线，时间留得最足。","notice":"看柴窑镇窑复烧，拉坯体验要排队。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"昌江区枫树山蟠龙岗"},{"spotId":"S3","name":"雕塑瓷厂乐天市集","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"雕塑瓷厂乐天市集是陶溪川最有代表性的看点，周六上午开市，淘手作好物。攻略把它排进主线，时间留得最足。","notice":"周六上午开市，淘手作好物。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"新厂东路139号"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"饺子粑（人均15元）","description":"景德镇 · 陶溪川的招牌是饺子粑，老字号小吃店本地人都认这家，点单照攻略不踩雷。","addr":"中山北路"},{"title":"冷粉（人均12元）","description":"景德镇 · 陶溪川的招牌是冷粉，景德镇冷粉店本地人都认这家，点单照攻略不踩雷。","addr":"人民广场附近"},{"title":"碱水粑炒鸡蛋（人均28元）","description":"景德镇 · 陶溪川的招牌是碱水粑炒鸡蛋，瓷都家常菜本地人都认这家，点单照攻略不踩雷。","addr":"陶溪川周边小馆"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","相机或运动相机","换洗衣物与外套（早晚温差）","保温水杯与少量现金","墨镜与拍照道具","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳麓山橘子洲纯攻略·摄影机位','guide','长沙 · 岳麓山橘子洲','mountain','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1990,1000,2,'岳麓山 / 橘子洲头 / 太平老街 —— 纯攻略助你玩透岳麓山橘子洲精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「岳麓山橘子洲」三日深度游——山岳。长沙湘绣摆件精致好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 长沙"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往长沙，抵达后办理入住、熟悉周边环境。","addr":"长沙市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"岳麓山","description":"下午首站岳麓山，调整状态进入旅行节奏，爱晚亭秋色最美，索道下山省力。","addr":"长沙市岳麓区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游长沙一带氛围拉满，晚餐茶颜悦色人均18元。","addr":"太平老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"橘子洲头","description":"全天主景点橘子洲头，青年毛泽东雕像打卡，小火车代步。","addr":"长沙市橘子洲景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐文和友臭豆腐（人均15元），早点休息。","addr":"海信广场","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"太平老街","description":"收官太平老街，臭豆腐与糖油粑粑的主场。","addr":"长沙市天心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糖油粑粑后集合返程，三日旅程圆满。","addr":"坡子街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"岳麓山","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"岳麓山是岳麓山橘子洲最有代表性的看点，爱晚亭秋色最美，索道下山省力。攻略把它排进主线，时间留得最足。","notice":"爱晚亭秋色最美，索道下山省力。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"长沙市岳麓区"},{"spotId":"S2","name":"橘子洲头","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"橘子洲头是岳麓山橘子洲最有代表性的看点，青年毛泽东雕像打卡，小火车代步。攻略把它排进主线，时间留得最足。","notice":"青年毛泽东雕像打卡，小火车代步。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"长沙市橘子洲景区"},{"spotId":"S3","name":"太平老街","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"太平老街是岳麓山橘子洲最有代表性的看点，臭豆腐与糖油粑粑的主场。攻略把它排进主线，时间留得最足。","notice":"臭豆腐与糖油粑粑的主场。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"长沙市天心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"茶颜悦色（人均18元）","description":"长沙 · 岳麓山橘子洲的招牌是茶颜悦色，太平街店本地人都认这家，点单照攻略不踩雷。","addr":"太平老街"},{"title":"文和友臭豆腐（人均15元）","description":"长沙 · 岳麓山橘子洲的招牌是文和友臭豆腐，文和友本地人都认这家，点单照攻略不踩雷。","addr":"海信广场"},{"title":"糖油粑粑（人均8元）","description":"长沙 · 岳麓山橘子洲的招牌是糖油粑粑，李公庙糖油粑粑本地人都认这家，点单照攻略不踩雷。","addr":"坡子街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","相机或运动相机","保温水杯与少量现金","少量零食补给","防晒霜与遮阳帽"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 长沙 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丽江古城玉龙雪山纯攻略·美食清单','guide','丽江 · 丽江古城玉龙雪山','mountain','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,2,'玉龙雪山 / 蓝月谷 / 丽江古城 —— 纯攻略助你玩透丽江古城玉龙雪山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「丽江古城玉龙雪山」两日慢旅行——山岳。雪山玫瑰饼是最热手信。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 丽江"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴丽江","description":"集合出发，大巴直达丽江古城玉龙雪山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"玉龙雪山","description":"抵达后首游玉龙雪山，大索道直达4506米，租羽绒服买氧气瓶。","addr":"丽江市玉龙县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐腊排骨火锅（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"蓝月谷","description":"早起人少，蓝月谷精华时段，牛奶蓝湖水，电瓶车游三湖。","addr":"玉龙雪山脚下","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐鸡豆凉粉，人均10元，补充体力。","addr":"四方街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"丽江古城","description":"午后游览丽江古城，四方街打跳，狮子山看全景。","addr":"古城区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"玉龙雪山","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"玉龙雪山是丽江古城玉龙雪山最有代表性的看点，大索道直达4506米，租羽绒服买氧气瓶。攻略把它排进主线，时间留得最足。","notice":"大索道直达4506米，租羽绒服买氧气瓶。提前10分钟到，避开旅行团大部队。","durationMinutes":300,"addr":"丽江市玉龙县"},{"spotId":"S2","name":"蓝月谷","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"蓝月谷是丽江古城玉龙雪山最有代表性的看点，牛奶蓝湖水，电瓶车游三湖。攻略把它排进主线，时间留得最足。","notice":"牛奶蓝湖水，电瓶车游三湖。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"玉龙雪山脚下"},{"spotId":"S3","name":"丽江古城","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"丽江古城是丽江古城玉龙雪山最有代表性的看点，四方街打跳，狮子山看全景。攻略把它排进主线，时间留得最足。","notice":"四方街打跳，狮子山看全景。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"古城区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"腊排骨火锅（人均68元）","description":"丽江 · 丽江古城玉龙雪山的招牌是腊排骨火锅，象山市场本地人都认这家，点单照攻略不踩雷。","addr":"古城区象山街"},{"title":"鸡豆凉粉（人均10元）","description":"丽江 · 丽江古城玉龙雪山的招牌是鸡豆凉粉，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"四方街"},{"title":"丽江粑粑（人均12元）","description":"丽江 · 丽江古城玉龙雪山的招牌是丽江粑粑，忠义市场本地人都认这家，点单照攻略不踩雷。","addr":"忠义市场内"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('稻城亚丁纯攻略·自由行手册','guide','甘孜 · 稻城亚丁','plateau','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',990,500,2,'牛奶海 / 五色海 / 冲古寺草坪 —— 纯攻略助你玩透稻城亚丁精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「稻城亚丁」三日深度游——高原。高原反应别逞强慢慢走。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 甘孜"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往甘孜，抵达后办理入住、熟悉周边环境。","addr":"甘孜市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"牛奶海","description":"下午首站牛奶海，调整状态进入旅行节奏，海拔4600，马帮或徒步，量力而行。","addr":"稻城县香格里拉镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游甘孜一带氛围拉满，晚餐松茸炖鸡人均128元。","addr":"亚丁村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"五色海","description":"全天主景点五色海，最后一百步最陡，景色值得。","addr":"牛奶海上方","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酥油茶（人均15元），早点休息。","addr":"香格里拉镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"冲古寺草坪","description":"收官冲古寺草坪，仙乃日倒影机位。","addr":"亚丁村","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐高原土豆后集合返程，三日旅程圆满。","addr":"洛绒牛场补给点","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"牛奶海","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"牛奶海是稻城亚丁最有代表性的看点，海拔4600，马帮或徒步，量力而行。攻略把它排进主线，时间留得最足。","notice":"海拔4600，马帮或徒步，量力而行。这个点位上午光线最好。","durationMinutes":360,"addr":"稻城县香格里拉镇"},{"spotId":"S2","name":"五色海","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"五色海是稻城亚丁最有代表性的看点，最后一百步最陡，景色值得。攻略把它排进主线，时间留得最足。","notice":"最后一百步最陡，景色值得。这个点位上午光线最好。","durationMinutes":60,"addr":"牛奶海上方"},{"spotId":"S3","name":"冲古寺草坪","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"冲古寺草坪是稻城亚丁最有代表性的看点，仙乃日倒影机位。攻略把它排进主线，时间留得最足。","notice":"仙乃日倒影机位。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"亚丁村"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松茸炖鸡（人均128元）","description":"甘孜 · 稻城亚丁的招牌是松茸炖鸡，亚丁村民宿本地人都认这家，点单照攻略不踩雷。","addr":"亚丁村"},{"title":"酥油茶（人均15元）","description":"甘孜 · 稻城亚丁的招牌是酥油茶，藏家小屋本地人都认这家，点单照攻略不踩雷。","addr":"香格里拉镇"},{"title":"高原土豆（人均10元）","description":"甘孜 · 稻城亚丁的招牌是高原土豆，小卖部熟食本地人都认这家，点单照攻略不踩雷。","addr":"洛绒牛场补给点"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 甘孜 的交通方便吗？","推荐先到 甘孜，再打车或景区直通车前往核心景区；自驾导航直接搜稻城亚丁即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 甘孜 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('西江千户苗寨纯攻略·省钱玩法','guide','黔东南 · 西江千户苗寨','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',1990,1000,1,'西江观景台 / 一号风雨桥 / 嘎歌古巷 —— 纯攻略助你玩透西江千户苗寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「西江千户苗寨」两日慢旅行——古村落。苗银手镯按克计价别按件。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔东南","description":"集合出发，大巴直达西江千户苗寨，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"西江观景台","description":"抵达后首游西江观景台，万家灯火夜景，天黑后1小时最佳。","addr":"雷山县西江镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐苗家酸汤鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"一号风雨桥","description":"早起人少，一号风雨桥精华时段，苗家歌舞表演互动。","addr":"西江苗寨","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐糯米饭，人均10元，补充体力。","addr":"风雨桥头","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"嘎歌古巷","description":"午后游览嘎歌古巷，非遗银饰刺绣工坊。","addr":"西江苗寨","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"西江观景台","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"西江观景台是西江千户苗寨最有代表性的看点，万家灯火夜景，天黑后1小时最佳。攻略把它排进主线，时间留得最足。","notice":"万家灯火夜景，天黑后1小时最佳。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"雷山县西江镇"},{"spotId":"S2","name":"一号风雨桥","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"一号风雨桥是西江千户苗寨最有代表性的看点，苗家歌舞表演互动。攻略把它排进主线，时间留得最足。","notice":"苗家歌舞表演互动。这个点位上午光线最好。","durationMinutes":60,"addr":"西江苗寨"},{"spotId":"S3","name":"嘎歌古巷","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"嘎歌古巷是西江千户苗寨最有代表性的看点，非遗银饰刺绣工坊。攻略把它排进主线，时间留得最足。","notice":"非遗银饰刺绣工坊。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"西江苗寨"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"苗家酸汤鱼（人均68元）","description":"黔东南 · 西江千户苗寨的招牌是苗家酸汤鱼，阿浓苗家本地人都认这家，点单照攻略不踩雷。","addr":"西江主街"},{"title":"糯米饭（人均10元）","description":"黔东南 · 西江千户苗寨的招牌是糯米饭，苗家早餐摊本地人都认这家，点单照攻略不踩雷。","addr":"风雨桥头"},{"title":"米豆腐（人均12元）","description":"黔东南 · 西江千户苗寨的招牌是米豆腐，古巷小吃本地人都认这家，点单照攻略不踩雷。","addr":"嘎歌古巷"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽","相机或运动相机","换洗衣物与外套（早晚温差）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 黔东南 的交通方便吗？","推荐先到 黔东南，再打车或景区直通车前往核心景区；自驾导航直接搜西江千户苗寨即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('德天跨国瀑布纯攻略·避坑版','guide','崇左 · 德天跨国瀑布','water','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2500,1300,2,'德天瀑布 / 明仕田园 / 53号界碑 —— 纯攻略助你玩透德天跨国瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「德天跨国瀑布」三日深度游——水景。崇左酸嘢开胃解腻。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 崇左"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往崇左，抵达后办理入住、熟悉周边环境。","addr":"崇左市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"德天瀑布","description":"下午首站德天瀑布，调整状态进入旅行节奏，亚洲第一跨国瀑布，竹筏近观。","addr":"大新县硕龙镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游崇左一带氛围拉满，晚餐越式卷粉人均12元。","addr":"硕龙镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"明仕田园","description":"全天主景点明仕田园，小桂林田园风光，骑行环线。","addr":"大新县明仕村","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐烤香猪（人均58元），早点休息。","addr":"德天游客中心","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"53号界碑","description":"收官53号界碑，中越边境打卡。","addr":"德天景区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸嘢后集合返程，三日旅程圆满。","addr":"明仕田园","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"德天瀑布","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"德天瀑布是德天跨国瀑布最有代表性的看点，亚洲第一跨国瀑布，竹筏近观。攻略把它排进主线，时间留得最足。","notice":"亚洲第一跨国瀑布，竹筏近观。这个点位上午光线最好。","durationMinutes":180,"addr":"大新县硕龙镇"},{"spotId":"S2","name":"明仕田园","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"明仕田园是德天跨国瀑布最有代表性的看点，小桂林田园风光，骑行环线。攻略把它排进主线，时间留得最足。","notice":"小桂林田园风光，骑行环线。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"大新县明仕村"},{"spotId":"S3","name":"53号界碑","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"53号界碑是德天跨国瀑布最有代表性的看点，中越边境打卡。攻略把它排进主线，时间留得最足。","notice":"中越边境打卡。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"德天景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"越式卷粉（人均12元）","description":"崇左 · 德天跨国瀑布的招牌是越式卷粉，边关小吃本地人都认这家，点单照攻略不踩雷。","addr":"硕龙镇"},{"title":"烤香猪（人均58元）","description":"崇左 · 德天跨国瀑布的招牌是烤香猪，壮乡风味本地人都认这家，点单照攻略不踩雷。","addr":"德天游客中心"},{"title":"酸嘢（人均10元）","description":"崇左 · 德天跨国瀑布的招牌是酸嘢，水果酸摊本地人都认这家，点单照攻略不踩雷。","addr":"明仕田园"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","相机或运动相机","保温水杯与少量现金","换洗衣物与外套（早晚温差）","少量零食补给","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌镇西栅纯攻略·深度指南','guide','嘉兴 · 乌镇西栅','ancient_town','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',990,500,1,'乌镇西栅 / 木心美术馆 / 南浔古镇 —— 纯攻略助你玩透乌镇西栅精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「乌镇西栅」两日慢旅行——古镇。乌镇蓝印花布制品雅致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 嘉兴"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴嘉兴","description":"集合出发，大巴直达乌镇西栅，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乌镇西栅","description":"抵达后首游乌镇西栅，夜景封神，染坊与书院。","addr":"桐乡市乌镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红烧羊肉（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"木心美术馆","description":"早起人少，木心美术馆精华时段，建筑与展览双重享受。","addr":"西栅景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐定胜糕，人均10元，补充体力。","addr":"乌镇南栅","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南浔古镇","description":"午后游览南浔古镇，人少水乡，百间楼原生。","addr":"湖州南浔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乌镇西栅","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"乌镇西栅是乌镇西栅最有代表性的看点，夜景封神，染坊与书院。攻略把它排进主线，时间留得最足。","notice":"夜景封神，染坊与书院。这个点位上午光线最好。","durationMinutes":240,"addr":"桐乡市乌镇"},{"spotId":"S2","name":"木心美术馆","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"木心美术馆是乌镇西栅最有代表性的看点，建筑与展览双重享受。攻略把它排进主线，时间留得最足。","notice":"建筑与展览双重享受。这个点位上午光线最好。","durationMinutes":90,"addr":"西栅景区"},{"spotId":"S3","name":"南浔古镇","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"南浔古镇是乌镇西栅最有代表性的看点，人少水乡，百间楼原生。攻略把它排进主线，时间留得最足。","notice":"人少水乡，百间楼原生。这个点位上午光线最好。","durationMinutes":150,"addr":"湖州南浔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红烧羊肉（人均45元）","description":"嘉兴 · 乌镇西栅的招牌是红烧羊肉，书生羊肉面本地人都认这家，点单照攻略不踩雷。","addr":"西栅大街"},{"title":"定胜糕（人均10元）","description":"嘉兴 · 乌镇西栅的招牌是定胜糕，小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"乌镇南栅"},{"title":"白水鱼（人均58元）","description":"嘉兴 · 乌镇西栅的招牌是白水鱼，水乡渔家本地人都认这家，点单照攻略不踩雷。","addr":"南浔百间楼"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","防晒霜与遮阳帽","少量零食补给","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 嘉兴，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('瘦西湖纯攻略·周末版','guide','扬州 · 瘦西湖','water','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1990,1000,2,'瘦西湖 / 个园 / 东关街 —— 纯攻略助你玩透瘦西湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「瘦西湖」三日深度游——水景。扬州漆器螺钿最精美。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 扬州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往扬州，抵达后办理入住、熟悉周边环境。","addr":"扬州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"瘦西湖","description":"下午首站瘦西湖，调整状态进入旅行节奏，两堤花柳全依水，五亭桥白塔。","addr":"扬州市邗江区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游扬州一带氛围拉满，晚餐蟹粉狮子头人均68元。","addr":"念四路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"个园","description":"全天主景点个园，四季假山一园看尽。","addr":"东关街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐扬州炒饭（人均28元），早点休息。","addr":"东关街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"东关街","description":"收官东关街，千年古街，夜色灯笼。","addr":"广陵区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐烫干丝后集合返程，三日旅程圆满。","addr":"得胜桥","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"瘦西湖","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"瘦西湖是瘦西湖最有代表性的看点，两堤花柳全依水，五亭桥白塔。攻略把它排进主线，时间留得最足。","notice":"两堤花柳全依水，五亭桥白塔。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"扬州市邗江区"},{"spotId":"S2","name":"个园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"个园是瘦西湖最有代表性的看点，四季假山一园看尽。攻略把它排进主线，时间留得最足。","notice":"四季假山一园看尽。这个点位上午光线最好。","durationMinutes":90,"addr":"东关街"},{"spotId":"S3","name":"东关街","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"东关街是瘦西湖最有代表性的看点，千年古街，夜色灯笼。攻略把它排进主线，时间留得最足。","notice":"千年古街，夜色灯笼。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"广陵区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蟹粉狮子头（人均68元）","description":"扬州 · 瘦西湖的招牌是蟹粉狮子头，食为天本地人都认这家，点单照攻略不踩雷。","addr":"念四路"},{"title":"扬州炒饭（人均28元）","description":"扬州 · 瘦西湖的招牌是扬州炒饭，老字号本地人都认这家，点单照攻略不踩雷。","addr":"东关街"},{"title":"烫干丝（人均22元）","description":"扬州 · 瘦西湖的招牌是烫干丝，富春茶社本地人都认这家，点单照攻略不踩雷。","addr":"得胜桥"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","相机或运动相机","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 扬州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 扬州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三峡人家纯攻略·亲子篇','guide','宜昌 · 三峡人家','water','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',2990,1600,2,'三峡人家 / 三峡大坝 / 清江画廊 —— 纯攻略助你玩透三峡人家精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「三峡人家」两日慢旅行——水景。宜昌柑橘橙都好吃。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 宜昌"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宜昌","description":"集合出发，大巴直达三峡人家，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"三峡人家","description":"抵达后首游三峡人家，灯影石与龙进溪，土家婚俗表演。","addr":"宜昌市夷陵区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐峡口肥鱼（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三峡大坝","description":"早起人少，三峡大坝精华时段，国之重器，坛子岭俯瞰。","addr":"夷陵区三斗坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐懒豆腐，人均28元，补充体力。","addr":"三峡人家景区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"清江画廊","description":"午后游览清江画廊，乘船入画，巴人发源地。","addr":"长阳县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"三峡人家","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"三峡人家是三峡人家最有代表性的看点，灯影石与龙进溪，土家婚俗表演。攻略把它排进主线，时间留得最足。","notice":"灯影石与龙进溪，土家婚俗表演。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"宜昌市夷陵区"},{"spotId":"S2","name":"三峡大坝","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"三峡大坝是三峡人家最有代表性的看点，国之重器，坛子岭俯瞰。攻略把它排进主线，时间留得最足。","notice":"国之重器，坛子岭俯瞰。这个点位上午光线最好。","durationMinutes":180,"addr":"夷陵区三斗坪镇"},{"spotId":"S3","name":"清江画廊","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"清江画廊是三峡人家最有代表性的看点，乘船入画，巴人发源地。攻略把它排进主线，时间留得最足。","notice":"乘船入画，巴人发源地。这个点位上午光线最好。","durationMinutes":180,"addr":"长阳县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"峡口肥鱼（人均88元）","description":"宜昌 · 三峡人家的招牌是峡口肥鱼，江边鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"三斗坪"},{"title":"懒豆腐（人均28元）","description":"宜昌 · 三峡人家的招牌是懒豆腐，土家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"三峡人家景区"},{"title":"清江银鱼（人均45元）","description":"宜昌 · 三峡人家的招牌是清江银鱼，水产馆本地人都认这家，点单照攻略不踩雷。","addr":"长阳县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","墨镜与拍照道具","少量零食补给","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","相机或运动相机","防晒霜与遮阳帽","保温水杯与少量现金"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 宜昌 的交通方便吗？","推荐先到 宜昌，再打车或景区直通车前往核心景区；自驾导航直接搜三峡人家即可。"],["几月份去 宜昌 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('华山纯攻略·摄影机位','guide','渭南 · 华山','adventure','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1990,1000,9,'东峰朝阳峰 / 西峰莲花峰 / 苍龙岭 —— 纯攻略助你玩透华山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「华山」三日深度游——探险地。华山论剑碑打卡要排队。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 渭南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往渭南，抵达后办理入住、熟悉周边环境。","addr":"渭南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"东峰朝阳峰","description":"下午首站东峰朝阳峰，调整状态进入旅行节奏，长空栈道与鹞子翻身，排队2小时。","addr":"华阴市华山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游渭南一带氛围拉满，晚餐大刀面人均18元。","addr":"华阴市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西峰莲花峰","description":"全天主景点西峰莲花峰，索道直达，斧劈石传说。","addr":"华山最美峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐踅面（人均15元），早点休息。","addr":"华山脚下","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"苍龙岭","description":"收官苍龙岭，岭脊如龙，两侧深渊。","addr":"华山中段","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐秦镇米皮后集合返程，三日旅程圆满。","addr":"玉泉院旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"东峰朝阳峰","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"东峰朝阳峰是华山最有代表性的看点，长空栈道与鹞子翻身，排队2小时。攻略把它排进主线，时间留得最足。","notice":"长空栈道与鹞子翻身，排队2小时。提前10分钟到，避开旅行团大部队。","durationMinutes":300,"addr":"华阴市华山风景区"},{"spotId":"S2","name":"西峰莲花峰","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"西峰莲花峰是华山最有代表性的看点，索道直达，斧劈石传说。攻略把它排进主线，时间留得最足。","notice":"索道直达，斧劈石传说。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"华山最美峰"},{"spotId":"S3","name":"苍龙岭","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"苍龙岭是华山最有代表性的看点，岭脊如龙，两侧深渊。攻略把它排进主线，时间留得最足。","notice":"岭脊如龙，两侧深渊。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"华山中段"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"大刀面（人均18元）","description":"渭南 · 华山的招牌是大刀面，华阴老字号本地人都认这家，点单照攻略不踩雷。","addr":"华阴市区"},{"title":"踅面（人均15元）","description":"渭南 · 华山的招牌是踅面，合阳踅面本地人都认这家，点单照攻略不踩雷。","addr":"华山脚下"},{"title":"秦镇米皮（人均12元）","description":"渭南 · 华山的招牌是秦镇米皮，老秦镇本地人都认这家，点单照攻略不踩雷。","addr":"玉泉院旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","少量零食补给","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","防晒霜与遮阳帽","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 渭南 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('曲阜三孔纯攻略·美食清单','guide','济宁 · 曲阜三孔','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1200,600,7,'孔庙 / 孔府 / 孔林 —— 纯攻略助你玩透曲阜三孔精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「曲阜三孔」两日慢旅行——人文。曲阜楷木雕如意吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 济宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴济宁","description":"集合出发，大巴直达曲阜三孔，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"孔庙","description":"抵达后首游孔庙，祭孔大典地，古柏森森。","addr":"济宁市曲阜市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐孔府菜（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"孔府","description":"早起人少，孔府精华时段，天下第一家，后花园。","addr":"曲阜","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山东煎饼，人均10元，补充体力。","addr":"鼓楼街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"孔林","description":"午后游览孔林，至圣林，孔子墓。","addr":"曲阜","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"孔庙","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"孔庙是曲阜三孔最有代表性的看点，祭孔大典地，古柏森森。攻略把它排进主线，时间留得最足。","notice":"祭孔大典地，古柏森森。这个点位上午光线最好。","durationMinutes":150,"addr":"济宁市曲阜市"},{"spotId":"S2","name":"孔府","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"孔府是曲阜三孔最有代表性的看点，天下第一家，后花园。攻略把它排进主线，时间留得最足。","notice":"天下第一家，后花园。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"曲阜"},{"spotId":"S3","name":"孔林","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"孔林是曲阜三孔最有代表性的看点，至圣林，孔子墓。攻略把它排进主线，时间留得最足。","notice":"至圣林，孔子墓。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"曲阜"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"孔府菜（人均88元）","description":"济宁 · 曲阜三孔的招牌是孔府菜，阙里宾舍本地人都认这家，点单照攻略不踩雷。","addr":"曲阜孔庙旁"},{"title":"山东煎饼（人均10元）","description":"济宁 · 曲阜三孔的招牌是山东煎饼，煎饼卷本地人都认这家，点单照攻略不踩雷。","addr":"鼓楼街"},{"title":"羊肉泡粥（人均28元）","description":"济宁 · 曲阜三孔的招牌是羊肉泡粥，羊肉泡粥馆本地人都认这家，点单照攻略不踩雷。","addr":"曲阜市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","身份证件与手机充电宝","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金","相机或运动相机","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意"],"faqs":[["几月份去 济宁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 济宁 的交通方便吗？","推荐先到 济宁，再打车或景区直通车前往核心景区；自驾导航直接搜曲阜三孔即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('亚龙湾蜈支洲纯攻略·自由行手册','guide','三亚 · 亚龙湾蜈支洲','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1990,1000,6,'蜈支洲岛 / 亚龙湾热带天堂森林公园 / 后海村 —— 纯攻略助你玩透亚龙湾蜈支洲精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「亚龙湾蜈支洲」三日深度游——海滨。三亚贵妃芒香甜多汁。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 三亚"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往三亚，抵达后办理入住、熟悉周边环境。","addr":"三亚市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜈支洲岛","description":"下午首站蜈支洲岛，调整状态进入旅行节奏，中国马尔代夫，潜水胜地。","addr":"三亚市海棠区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游三亚一带氛围拉满，晚餐椰子鸡人均78元。","addr":"后海村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"亚龙湾热带天堂森林公园","description":"全天主景点亚龙湾热带天堂森林公园，过江龙索道，电影取景地。","addr":"亚龙湾","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐清补凉（人均15元），早点休息。","addr":"第一市场","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"后海村","description":"收官后海村，冲浪初学者天堂，夜市。","addr":"海棠湾","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐海鲜加工后集合返程，三日旅程圆满。","addr":"新民街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜈支洲岛","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"蜈支洲岛是亚龙湾蜈支洲最有代表性的看点，中国马尔代夫，潜水胜地。攻略把它排进主线，时间留得最足。","notice":"中国马尔代夫，潜水胜地。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"三亚市海棠区"},{"spotId":"S2","name":"亚龙湾热带天堂森林公园","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"亚龙湾热带天堂森林公园是亚龙湾蜈支洲最有代表性的看点，过江龙索道，电影取景地。攻略把它排进主线，时间留得最足。","notice":"过江龙索道，电影取景地。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"亚龙湾"},{"spotId":"S3","name":"后海村","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"后海村是亚龙湾蜈支洲最有代表性的看点，冲浪初学者天堂，夜市。攻略把它排进主线，时间留得最足。","notice":"冲浪初学者天堂，夜市。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"海棠湾"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"椰子鸡（人均78元）","description":"三亚 · 亚龙湾蜈支洲的招牌是椰子鸡，萌哒哒椰子鸡本地人都认这家，点单照攻略不踩雷。","addr":"后海村"},{"title":"清补凉（人均15元）","description":"三亚 · 亚龙湾蜈支洲的招牌是清补凉，一馨清补凉本地人都认这家，点单照攻略不踩雷。","addr":"第一市场"},{"title":"海鲜加工（人均98元）","description":"三亚 · 亚龙湾蜈支洲的招牌是海鲜加工，第一市场本地人都认这家，点单照攻略不踩雷。","addr":"新民街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","相机或运动相机","墨镜与拍照道具","保温水杯与少量现金","身份证件与手机充电宝","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('塔尔寺纯攻略·省钱玩法','guide','西宁 · 塔尔寺','red','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1500,800,7,'塔尔寺 / 东关清真大寺 / 青海省博物馆 —— 纯攻略助你玩透塔尔寺精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「塔尔寺」两日慢旅行——人文。西宁牦牛绒围巾暖和。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"青海 · 西宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴西宁","description":"集合出发，大巴直达塔尔寺，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"塔尔寺","description":"抵达后首游塔尔寺，酥油花壁画堆绣三绝。","addr":"湟中区鲁沙尔镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐手抓羊肉（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"东关清真大寺","description":"早起人少，东关清真大寺精华时段，西北四大清真寺之一。","addr":"西宁市城东区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酿皮，人均12元，补充体力。","addr":"莫家街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"青海省博物馆","description":"午后游览青海省博物馆，了解高原文明。","addr":"城西区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"塔尔寺","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"塔尔寺是塔尔寺最有代表性的看点，酥油花壁画堆绣三绝。攻略把它排进主线，时间留得最足。","notice":"酥油花壁画堆绣三绝。这个点位上午光线最好。","durationMinutes":180,"addr":"湟中区鲁沙尔镇"},{"spotId":"S2","name":"东关清真大寺","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"东关清真大寺是塔尔寺最有代表性的看点，西北四大清真寺之一。攻略把它排进主线，时间留得最足。","notice":"西北四大清真寺之一。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"西宁市城东区"},{"spotId":"S3","name":"青海省博物馆","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"青海省博物馆是塔尔寺最有代表性的看点，了解高原文明。攻略把它排进主线，时间留得最足。","notice":"了解高原文明。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"城西区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"手抓羊肉（人均58元）","description":"西宁 · 塔尔寺的招牌是手抓羊肉，益鑫手抓本地人都认这家，点单照攻略不踩雷。","addr":"礼让街"},{"title":"酿皮（人均12元）","description":"西宁 · 塔尔寺的招牌是酿皮，马忠食府本地人都认这家，点单照攻略不踩雷。","addr":"莫家街"},{"title":"甜醅（人均8元）","description":"西宁 · 塔尔寺的招牌是甜醅，小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"水井巷"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机","防晒霜与遮阳帽","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滨海路金石滩纯攻略·避坑版','guide','大连 · 滨海路金石滩','sea','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',990,500,6,'滨海路木栈道 / 金石滩国家地质公园 / 星海广场 —— 纯攻略助你玩透滨海路金石滩精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「滨海路金石滩」三日深度游——海滨。大连海参干货首选。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"辽宁 · 大连"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大连，抵达后办理入住、熟悉周边环境。","addr":"大连市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"滨海路木栈道","description":"下午首站滨海路木栈道，调整状态进入旅行节奏，山海相依城市步道，北大桥日落。","addr":"大连市中山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大连一带氛围拉满，晚餐海鲜焖子人均48元。","addr":"滨海路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"金石滩国家地质公园","description":"全天主景点金石滩国家地质公园，恐龙探海奇石，龟裂石。","addr":"金州区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海胆蒸蛋（人均68元），早点休息。","addr":"老虎滩","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"星海广场","description":"收官星海广场，亚洲最大城市广场，夜景。","addr":"沙河口区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐铁板鱿鱼后集合返程，三日旅程圆满。","addr":"西安路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"滨海路木栈道","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"滨海路木栈道是滨海路金石滩最有代表性的看点，山海相依城市步道，北大桥日落。攻略把它排进主线，时间留得最足。","notice":"山海相依城市步道，北大桥日落。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大连市中山区"},{"spotId":"S2","name":"金石滩国家地质公园","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"金石滩国家地质公园是滨海路金石滩最有代表性的看点，恐龙探海奇石，龟裂石。攻略把它排进主线，时间留得最足。","notice":"恐龙探海奇石，龟裂石。这个点位上午光线最好。","durationMinutes":150,"addr":"金州区"},{"spotId":"S3","name":"星海广场","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"星海广场是滨海路金石滩最有代表性的看点，亚洲最大城市广场，夜景。攻略把它排进主线，时间留得最足。","notice":"亚洲最大城市广场，夜景。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"沙河口区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜焖子（人均48元）","description":"大连 · 滨海路金石滩的招牌是海鲜焖子，品海楼本地人都认这家，点单照攻略不踩雷。","addr":"滨海路"},{"title":"海胆蒸蛋（人均68元）","description":"大连 · 滨海路金石滩的招牌是海胆蒸蛋，日丰园本地人都认这家，点单照攻略不踩雷。","addr":"老虎滩"},{"title":"铁板鱿鱼（人均25元）","description":"大连 · 滨海路金石滩的招牌是铁板鱿鱼，中央大道夜市本地人都认这家，点单照攻略不踩雷。","addr":"西安路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","保温水杯与少量现金","相机或运动相机","墨镜与拍照道具","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["几月份去 大连 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 大连 的交通方便吗？","推荐先到 大连，再打车或景区直通车前往核心景区；自驾导航直接搜滨海路金石滩即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三清山纯攻略·深度指南','guide','上饶 · 三清山','mountain','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,2,'南清园 / 阳光海岸 / 万寿园 —— 纯攻略助你玩透三清山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「三清山」两日慢旅行——山岳。三清山猴头菇干货是手信首选。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴上饶","description":"集合出发，大巴直达三清山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"南清园","description":"抵达后首游南清园，巨蟒出山、东方女神都在这条环线，台阶多备水。","addr":"三清山风景区南门","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐石鸡汤锅（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"阳光海岸","description":"早起人少，阳光海岸精华时段，栈道悬空，恐高走东线缓冲段。","addr":"三清山高空栈道","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐野艾果，人均10元，补充体力。","addr":"南山索道下站旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"万寿园","description":"午后游览万寿园，坡缓树多，适合收尾慢慢走。","addr":"三清山南部入口","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"南清园","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"南清园是三清山最有代表性的看点，巨蟒出山、东方女神都在这条环线，台阶多备水。攻略把它排进主线，时间留得最足。","notice":"巨蟒出山、东方女神都在这条环线，台阶多备水。这个点位上午光线最好。","durationMinutes":240,"addr":"三清山风景区南门"},{"spotId":"S2","name":"阳光海岸","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"阳光海岸是三清山最有代表性的看点，栈道悬空，恐高走东线缓冲段。攻略把它排进主线，时间留得最足。","notice":"栈道悬空，恐高走东线缓冲段。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"三清山高空栈道"},{"spotId":"S3","name":"万寿园","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"万寿园是三清山最有代表性的看点，坡缓树多，适合收尾慢慢走。攻略把它排进主线，时间留得最足。","notice":"坡缓树多，适合收尾慢慢走。这个点位上午光线最好。","durationMinutes":90,"addr":"三清山南部入口"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"石鸡汤锅（人均58元）","description":"上饶 · 三清山的招牌是石鸡汤锅，山脚农家菜本地人都认这家，点单照攻略不踩雷。","addr":"三清山外双溪服务区"},{"title":"野艾果（人均10元）","description":"上饶 · 三清山的招牌是野艾果，路边农家本地人都认这家，点单照攻略不踩雷。","addr":"南山索道下站旁"},{"title":"三清山烧饼（人均8元）","description":"上饶 · 三清山的招牌是三清山烧饼，南清园补给点本地人都认这家，点单照攻略不踩雷。","addr":"登山途中补给站"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","少量零食补给","身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 上饶，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 上饶 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('明月山纯攻略·周末版','guide','宜春 · 明月山','mountain','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',2500,1300,2,'青云栈道 / 云谷飞瀑 / 温汤镇古井泉街 —— 纯攻略助你玩透明月山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「明月山」三日深度游——山岳。温汤富硒温泉蛋一元一个。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 宜春"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜春，抵达后办理入住、熟悉周边环境。","addr":"宜春市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"青云栈道","description":"下午首站青云栈道，调整状态进入旅行节奏，悬空栈道绕山腰，云雾天如仙境。","addr":"明月山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜春一带氛围拉满，晚餐温泉豆腐人均48元。","addr":"温汤镇古井旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"云谷飞瀑","description":"全天主景点云谷飞瀑，宜春八景之一，负氧离子爆表。","addr":"明月山核心景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐慈化鸡爪（人均22元），早点休息。","addr":"温汤镇主街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"温汤镇古井泉街","description":"收官温汤镇古井泉街，富硒温泉足浴28元一位，晚上泡最解乏。","addr":"袁州区温汤镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐扎粉后集合返程，三日旅程圆满。","addr":"古井泉街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"青云栈道","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"青云栈道是明月山最有代表性的看点，悬空栈道绕山腰，云雾天如仙境。攻略把它排进主线，时间留得最足。","notice":"悬空栈道绕山腰，云雾天如仙境。这个点位上午光线最好。","durationMinutes":180,"addr":"明月山风景区"},{"spotId":"S2","name":"云谷飞瀑","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"云谷飞瀑是明月山最有代表性的看点，宜春八景之一，负氧离子爆表。攻略把它排进主线，时间留得最足。","notice":"宜春八景之一，负氧离子爆表。这个点位上午光线最好。","durationMinutes":90,"addr":"明月山核心景区"},{"spotId":"S3","name":"温汤镇古井泉街","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"温汤镇古井泉街是明月山最有代表性的看点，富硒温泉足浴28元一位，晚上泡最解乏。攻略把它排进主线，时间留得最足。","notice":"富硒温泉足浴28元一位，晚上泡最解乏。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"袁州区温汤镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"温泉豆腐（人均48元）","description":"宜春 · 明月山的招牌是温泉豆腐，温汤镇豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇古井旁"},{"title":"慈化鸡爪（人均22元）","description":"宜春 · 明月山的招牌是慈化鸡爪，宜春小吃店本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇主街"},{"title":"扎粉（人均15元）","description":"宜春 · 明月山的招牌是扎粉，宜春扎粉店本地人都认这家，点单照攻略不踩雷。","addr":"古井泉街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 宜春 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南岳衡山纯攻略·亲子篇','guide','衡阳 · 南岳衡山','mountain','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,2,'祝融峰 / 南岳大庙 / 藏经殿 —— 纯攻略助你玩透南岳衡山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「南岳衡山」两日慢旅行——山岳。南岳香文化用品别乱买。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 衡阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴衡阳","description":"集合出发，大巴直达南岳衡山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"祝融峰","description":"抵达后首游祝融峰，五岳最高峰观日出，山顶租赁军大衣。","addr":"南岳区衡山风景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐南岳素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"南岳大庙","description":"早起人少，南岳大庙精华时段，江南第一庙，香火极旺。","addr":"南岳区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐观音笋，人均38元，补充体力。","addr":"半山亭","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"藏经殿","description":"午后游览藏经殿，幽谷深林中的古刹。","addr":"衡山半山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"祝融峰","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"祝融峰是南岳衡山最有代表性的看点，五岳最高峰观日出，山顶租赁军大衣。攻略把它排进主线，时间留得最足。","notice":"五岳最高峰观日出，山顶租赁军大衣。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"南岳区衡山风景区"},{"spotId":"S2","name":"南岳大庙","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"南岳大庙是南岳衡山最有代表性的看点，江南第一庙，香火极旺。攻略把它排进主线，时间留得最足。","notice":"江南第一庙，香火极旺。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"南岳区"},{"spotId":"S3","name":"藏经殿","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"藏经殿是南岳衡山最有代表性的看点，幽谷深林中的古刹。攻略把它排进主线，时间留得最足。","notice":"幽谷深林中的古刹。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"衡山半山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"南岳素斋（人均48元）","description":"衡阳 · 南岳衡山的招牌是南岳素斋，大庙素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"南岳大庙旁"},{"title":"观音笋（人均38元）","description":"衡阳 · 南岳衡山的招牌是观音笋，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"半山亭"},{"title":"衡山云雾茶（人均30元）","description":"衡阳 · 南岳衡山的招牌是衡山云雾茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"南岳镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","少量零食补给","相机或运动相机","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 衡阳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('香格里拉纯攻略·摄影机位','guide','迪庆 · 香格里拉','plateau','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1500,800,2,'普达措国家公园 / 松赞林寺 / 独克宗古城 —— 纯攻略助你玩透香格里拉精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「香格里拉」三日深度游——高原。牦牛肉干认准风干原味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 迪庆"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往迪庆，抵达后办理入住、熟悉周边环境。","addr":"迪庆市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"普达措国家公园","description":"下午首站普达措国家公园，调整状态进入旅行节奏，属都湖栈道环湖，高原慢慢走。","addr":"香格里拉市建塘镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游迪庆一带氛围拉满，晚餐牦牛肉火锅人均88元。","addr":"独克宗古城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"松赞林寺","description":"全天主景点松赞林寺，小布达拉宫，顺时针转寺。","addr":"香格里拉市佛屏山前","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酥油茶（人均20元），早点休息。","addr":"古城内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"独克宗古城","description":"收官独克宗古城，转世界最大转经筒，夜景美。","addr":"香格里拉市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐青稞饼后集合返程，三日旅程圆满。","addr":"池慈卡街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"普达措国家公园","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"普达措国家公园是香格里拉最有代表性的看点，属都湖栈道环湖，高原慢慢走。攻略把它排进主线，时间留得最足。","notice":"属都湖栈道环湖，高原慢慢走。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"香格里拉市建塘镇"},{"spotId":"S2","name":"松赞林寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"松赞林寺是香格里拉最有代表性的看点，小布达拉宫，顺时针转寺。攻略把它排进主线，时间留得最足。","notice":"小布达拉宫，顺时针转寺。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"香格里拉市佛屏山前"},{"spotId":"S3","name":"独克宗古城","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"独克宗古城是香格里拉最有代表性的看点，转世界最大转经筒，夜景美。攻略把它排进主线，时间留得最足。","notice":"转世界最大转经筒，夜景美。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"香格里拉市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉火锅（人均88元）","description":"迪庆 · 香格里拉的招牌是牦牛肉火锅，市井牦牛火锅本地人都认这家，点单照攻略不踩雷。","addr":"独克宗古城"},{"title":"酥油茶（人均20元）","description":"迪庆 · 香格里拉的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"青稞饼（人均12元）","description":"迪庆 · 香格里拉的招牌是青稞饼，藏式饼铺本地人都认这家，点单照攻略不踩雷。","addr":"池慈卡街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('峨眉山乐山大佛纯攻略·美食清单','guide','乐山 · 峨眉山乐山大佛','mountain','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,2,'乐山大佛 / 峨眉山金顶 / 清音阁 —— 纯攻略助你玩透峨眉山乐山大佛精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「峨眉山乐山大佛」两日慢旅行——山岳。峨眉雪芽茶清甜回甘。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 乐山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴乐山","description":"集合出发，大巴直达峨眉山乐山大佛，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乐山大佛","description":"抵达后首游乐山大佛，九曲栈道近距离看大佛脚背。","addr":"乐山市凌云路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐钵钵鸡（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"峨眉山金顶","description":"早起人少，峨眉山金顶精华时段，十方普贤金像，云海日出。","addr":"峨眉山市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐甜皮鸭，人均28元，补充体力。","addr":"乐山张公桥","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"清音阁","description":"午后游览清音阁，双桥清音，平路好走。","addr":"峨眉山低山区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乐山大佛","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"乐山大佛是峨眉山乐山大佛最有代表性的看点，九曲栈道近距离看大佛脚背。攻略把它排进主线，时间留得最足。","notice":"九曲栈道近距离看大佛脚背。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"乐山市凌云路"},{"spotId":"S2","name":"峨眉山金顶","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"峨眉山金顶是峨眉山乐山大佛最有代表性的看点，十方普贤金像，云海日出。攻略把它排进主线，时间留得最足。","notice":"十方普贤金像，云海日出。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"峨眉山市"},{"spotId":"S3","name":"清音阁","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"清音阁是峨眉山乐山大佛最有代表性的看点，双桥清音，平路好走。攻略把它排进主线，时间留得最足。","notice":"双桥清音，平路好走。这个点位上午光线最好。","durationMinutes":120,"addr":"峨眉山低山区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"钵钵鸡（人均35元）","description":"乐山 · 峨眉山乐山大佛的招牌是钵钵鸡，叶婆婆本地人都认这家，点单照攻略不踩雷。","addr":"乐山港"},{"title":"甜皮鸭（人均28元）","description":"乐山 · 峨眉山乐山大佛的招牌是甜皮鸭，赵鸭子本地人都认这家，点单照攻略不踩雷。","addr":"乐山张公桥"},{"title":"豆腐脑（人均12元）","description":"乐山 · 峨眉山乐山大佛的招牌是豆腐脑，峨眉豆腐脑本地人都认这家，点单照攻略不踩雷。","addr":"峨眉市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","少量零食补给","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 乐山，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('梵净山纯攻略·自由行手册','guide','铜仁 · 梵净山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',2990,1600,2,'红云金顶 / 蘑菇石 / 承恩寺 —— 纯攻略助你玩透梵净山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「梵净山」三日深度游——山岳。梵净山藤茶甘甜养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 铜仁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往铜仁，抵达后办理入住、熟悉周边环境。","addr":"铜仁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"红云金顶","description":"下午首站红云金顶，调整状态进入旅行节奏，海拔2493双峰寺庙，爬铁索上天桥。","addr":"铜仁市江口县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游铜仁一带氛围拉满，晚餐江口豆腐干人均28元。","addr":"梵净山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"蘑菇石","description":"全天主景点蘑菇石，10亿年奇石，排队打卡。","addr":"梵净山标志性景观","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐米虾（人均48元），早点休息。","addr":"太平镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"承恩寺","description":"收官承恩寺，明代古刹，云海时分最妙。","addr":"金顶下方","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐天麻炖鸡后集合返程，三日旅程圆满。","addr":"江口县城","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"红云金顶","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"红云金顶是梵净山最有代表性的看点，海拔2493双峰寺庙，爬铁索上天桥。攻略把它排进主线，时间留得最足。","notice":"海拔2493双峰寺庙，爬铁索上天桥。这个点位上午光线最好。","durationMinutes":240,"addr":"铜仁市江口县"},{"spotId":"S2","name":"蘑菇石","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"蘑菇石是梵净山最有代表性的看点，10亿年奇石，排队打卡。攻略把它排进主线，时间留得最足。","notice":"10亿年奇石，排队打卡。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"梵净山标志性景观"},{"spotId":"S3","name":"承恩寺","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"承恩寺是梵净山最有代表性的看点，明代古刹，云海时分最妙。攻略把它排进主线，时间留得最足。","notice":"明代古刹，云海时分最妙。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"金顶下方"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"江口豆腐干（人均28元）","description":"铜仁 · 梵净山的招牌是江口豆腐干，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"梵净山镇"},{"title":"米虾（人均48元）","description":"铜仁 · 梵净山的招牌是米虾，河鲜馆本地人都认这家，点单照攻略不踩雷。","addr":"太平镇"},{"title":"天麻炖鸡（人均88元）","description":"铜仁 · 梵净山的招牌是天麻炖鸡，药膳馆本地人都认这家，点单照攻略不踩雷。","addr":"江口县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","相机或运动相机","换洗衣物与外套（早晚温差）","墨镜与拍照道具","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 铜仁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('程阳八寨纯攻略·省钱玩法','guide','柳州 · 程阳八寨','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,1,'程阳八寨 / 三江侗天宫 / 窑埠古镇 —— 纯攻略助你玩透程阳八寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「程阳八寨」两日慢旅行——古村落。柳州螺蛳粉袋装正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 柳州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴柳州","description":"集合出发，大巴直达程阳八寨，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"程阳八寨","description":"抵达后首游程阳八寨，风雨桥鼓楼，侗族百家宴。","addr":"柳州市三江县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐螺蛳粉（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三江侗天宫","description":"早起人少，三江侗天宫精华时段，侗族文化大观。","addr":"三江县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐百家宴，人均58元，补充体力。","addr":"程阳八寨","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"窑埠古镇","description":"午后游览窑埠古镇，百里柳江夜景起点。","addr":"柳州市区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"程阳八寨","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"程阳八寨是程阳八寨最有代表性的看点，风雨桥鼓楼，侗族百家宴。攻略把它排进主线，时间留得最足。","notice":"风雨桥鼓楼，侗族百家宴。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"柳州市三江县"},{"spotId":"S2","name":"三江侗天宫","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"三江侗天宫是程阳八寨最有代表性的看点，侗族文化大观。攻略把它排进主线，时间留得最足。","notice":"侗族文化大观。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"三江县"},{"spotId":"S3","name":"窑埠古镇","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"窑埠古镇是程阳八寨最有代表性的看点，百里柳江夜景起点。攻略把它排进主线，时间留得最足。","notice":"百里柳江夜景起点。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"柳州市区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"螺蛳粉（人均15元）","description":"柳州 · 程阳八寨的招牌是螺蛳粉，爱民螺蛳粉本地人都认这家，点单照攻略不踩雷。","addr":"柳州市区"},{"title":"百家宴（人均58元）","description":"柳州 · 程阳八寨的招牌是百家宴，程阳八寨本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"},{"title":"打油茶（人均20元）","description":"柳州 · 程阳八寨的招牌是打油茶，寨中茶楼本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","少量零食补给","相机或运动相机"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 柳州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 柳州 的交通方便吗？","推荐先到 柳州，再打车或景区直通车前往核心景区；自驾导航直接搜程阳八寨即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('普陀山纯攻略·避坑版','guide','舟山 · 普陀山','sea','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2500,1300,6,'普济寺 / 南海观音 / 百步沙 —— 纯攻略助你玩透普陀山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普陀山」三日深度游——海滨。普陀佛茶清香回甘。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 舟山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往舟山，抵达后办理入住、熟悉周边环境。","addr":"舟山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"普济寺","description":"下午首站普济寺，调整状态进入旅行节奏，普陀山主刹，香花券5元。","addr":"舟山市普陀区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游舟山一带氛围拉满，晚餐海鲜面人均38元。","addr":"沈家门渔港","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"南海观音","description":"全天主景点南海观音，33米观音立像，海天佛国。","addr":"普陀山南端","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐普陀佛茶（人均30元），早点休息。","addr":"普济寺旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"百步沙","description":"收官百步沙，看日出踩沙滩。","addr":"普陀山","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐素斋后集合返程，三日旅程圆满。","addr":"普济寺边","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"普济寺","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"普济寺是普陀山最有代表性的看点，普陀山主刹，香花券5元。攻略把它排进主线，时间留得最足。","notice":"普陀山主刹，香花券5元。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"舟山市普陀区"},{"spotId":"S2","name":"南海观音","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"南海观音是普陀山最有代表性的看点，33米观音立像，海天佛国。攻略把它排进主线，时间留得最足。","notice":"33米观音立像，海天佛国。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"普陀山南端"},{"spotId":"S3","name":"百步沙","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"百步沙是普陀山最有代表性的看点，看日出踩沙滩。攻略把它排进主线，时间留得最足。","notice":"看日出踩沙滩。这个点位上午光线最好。","durationMinutes":60,"addr":"普陀山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜面（人均38元）","description":"舟山 · 普陀山的招牌是海鲜面，沈家门夜排档本地人都认这家，点单照攻略不踩雷。","addr":"沈家门渔港"},{"title":"普陀佛茶（人均30元）","description":"舟山 · 普陀山的招牌是普陀佛茶，茶室体验本地人都认这家，点单照攻略不踩雷。","addr":"普济寺旁"},{"title":"素斋（人均28元）","description":"舟山 · 普陀山的招牌是素斋，三圣堂素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"普济寺边"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","轻便雨衣或折叠伞","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('太湖鼋头渚纯攻略·深度指南','guide','无锡 · 太湖鼋头渚','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,2,'鼋头渚 / 灵山大佛 / 南长街 —— 纯攻略助你玩透太湖鼋头渚精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「太湖鼋头渚」两日慢旅行——水景。惠山泥人阿福最喜庆。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 无锡"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴无锡","description":"集合出发，大巴直达太湖鼋头渚，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"鼋头渚","description":"抵达后首游鼋头渚，太湖第一名胜，樱花季封神。","addr":"无锡市滨湖区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐无锡小笼（人均22元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"灵山大佛","description":"早起人少，灵山大佛精华时段，88米大佛，梵宫震撼。","addr":"滨湖区马山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酱排骨，人均48元，补充体力。","addr":"中山路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南长街","description":"午后游览南长街，古运河夜色，清名桥倒影。","addr":"梁溪区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"鼋头渚","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"鼋头渚是太湖鼋头渚最有代表性的看点，太湖第一名胜，樱花季封神。攻略把它排进主线，时间留得最足。","notice":"太湖第一名胜，樱花季封神。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"无锡市滨湖区"},{"spotId":"S2","name":"灵山大佛","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"灵山大佛是太湖鼋头渚最有代表性的看点，88米大佛，梵宫震撼。攻略把它排进主线，时间留得最足。","notice":"88米大佛，梵宫震撼。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"滨湖区马山"},{"spotId":"S3","name":"南长街","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"南长街是太湖鼋头渚最有代表性的看点，古运河夜色，清名桥倒影。攻略把它排进主线，时间留得最足。","notice":"古运河夜色，清名桥倒影。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"梁溪区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"无锡小笼（人均22元）","description":"无锡 · 太湖鼋头渚的招牌是无锡小笼，熙盛源本地人都认这家，点单照攻略不踩雷。","addr":"南禅寺"},{"title":"酱排骨（人均48元）","description":"无锡 · 太湖鼋头渚的招牌是酱排骨，三凤桥本地人都认这家，点单照攻略不踩雷。","addr":"中山路"},{"title":"太湖三白（人均98元）","description":"无锡 · 太湖鼋头渚的招牌是太湖三白，渔人码头本地人都认这家，点单照攻略不踩雷。","addr":"鼋头渚旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","墨镜与拍照道具","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","保温水杯与少量现金","少量零食补给","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["到达 无锡 的交通方便吗？","推荐先到 无锡，再打车或景区直通车前往核心景区；自驾导航直接搜太湖鼋头渚即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 无锡 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九宫山隐水洞纯攻略·周末版','guide','咸宁 · 九宫山隐水洞','mountain','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',990,500,2,'九宫山 / 隐水洞 / 刘家桥古民居 —— 纯攻略助你玩透九宫山隐水洞精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九宫山隐水洞」三日深度游——山岳。咸宁桂花蜜香甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 咸宁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往咸宁，抵达后办理入住、熟悉周边环境。","addr":"咸宁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"九宫山","description":"下午首站九宫山，调整状态进入旅行节奏，云中湖避暑胜地，闯王陵。","addr":"咸宁市通山县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游咸宁一带氛围拉满，晚餐贺胜桥鸡汤人均58元。","addr":"咸安区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"隐水洞","description":"全天主景点隐水洞，水路旱路双游线溶洞。","addr":"通山县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐桂花糕（人均15元），早点休息。","addr":"温泉城区","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"刘家桥古民居","description":"收官刘家桥古民居，明清廊桥古民居。","addr":"咸安区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐通山合菜面后集合返程，三日旅程圆满。","addr":"通山县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"九宫山","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"九宫山是九宫山隐水洞最有代表性的看点，云中湖避暑胜地，闯王陵。攻略把它排进主线，时间留得最足。","notice":"云中湖避暑胜地，闯王陵。这个点位上午光线最好。","durationMinutes":180,"addr":"咸宁市通山县"},{"spotId":"S2","name":"隐水洞","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"隐水洞是九宫山隐水洞最有代表性的看点，水路旱路双游线溶洞。攻略把它排进主线，时间留得最足。","notice":"水路旱路双游线溶洞。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"通山县"},{"spotId":"S3","name":"刘家桥古民居","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"刘家桥古民居是九宫山隐水洞最有代表性的看点，明清廊桥古民居。攻略把它排进主线，时间留得最足。","notice":"明清廊桥古民居。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"咸安区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"贺胜桥鸡汤（人均58元）","description":"咸宁 · 九宫山隐水洞的招牌是贺胜桥鸡汤，贺胜桥土鸡馆本地人都认这家，点单照攻略不踩雷。","addr":"咸安区"},{"title":"桂花糕（人均15元）","description":"咸宁 · 九宫山隐水洞的招牌是桂花糕，桂花之乡本地人都认这家，点单照攻略不踩雷。","addr":"温泉城区"},{"title":"通山合菜面（人均28元）","description":"咸宁 · 九宫山隐水洞的招牌是通山合菜面，通山农家本地人都认这家，点单照攻略不踩雷。","addr":"通山县"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","轻便雨衣或折叠伞","相机或运动相机","身份证件与手机充电宝","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 咸宁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 咸宁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('壶口瀑布纯攻略·亲子篇','guide','延安 · 壶口瀑布','red','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',2500,1300,7,'壶口瀑布 / 宝塔山 / 枣园革命旧址 —— 纯攻略助你玩透壶口瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「壶口瀑布」两日慢旅行——人文。延安小米熬粥最养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 延安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延安","description":"集合出发，大巴直达壶口瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"壶口瀑布","description":"抵达后首游壶口瀑布，黄河之水天上来，旱地行船遗址。","addr":"延安市宜川县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐油馍馍（人均10元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"宝塔山","description":"早起人少，宝塔山精华时段，延安地标灯光秀。","addr":"延安市宝塔区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐羊杂碎，人均25元，补充体力。","addr":"宝塔区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"枣园革命旧址","description":"午后游览枣园革命旧址，窑洞与历史课堂。","addr":"宝塔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"壶口瀑布","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"壶口瀑布是壶口瀑布最有代表性的看点，黄河之水天上来，旱地行船遗址。攻略把它排进主线，时间留得最足。","notice":"黄河之水天上来，旱地行船遗址。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"延安市宜川县"},{"spotId":"S2","name":"宝塔山","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"宝塔山是壶口瀑布最有代表性的看点，延安地标灯光秀。攻略把它排进主线，时间留得最足。","notice":"延安地标灯光秀。这个点位上午光线最好。","durationMinutes":90,"addr":"延安市宝塔区"},{"spotId":"S3","name":"枣园革命旧址","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"枣园革命旧址是壶口瀑布最有代表性的看点，窑洞与历史课堂。攻略把它排进主线，时间留得最足。","notice":"窑洞与历史课堂。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"宝塔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"油馍馍（人均10元）","description":"延安 · 壶口瀑布的招牌是油馍馍，延安小吃本地人都认这家，点单照攻略不踩雷。","addr":"枣园路口"},{"title":"羊杂碎（人均25元）","description":"延安 · 壶口瀑布的招牌是羊杂碎，陕北羊汤馆本地人都认这家，点单照攻略不踩雷。","addr":"宝塔区"},{"title":"洋芋擦擦（人均18元）","description":"延安 · 壶口瀑布的招牌是洋芋擦擦，陕北农家本地人都认这家，点单照攻略不踩雷。","addr":"宜川县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","保温水杯与少量现金","墨镜与拍照道具","相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["当地有什么必吃？","到了 延安，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 延安 的交通方便吗？","推荐先到 延安，再打车或景区直通车前往核心景区；自驾导航直接搜壶口瀑布即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('避暑山庄纯攻略·摄影机位','guide','承德 · 避暑山庄','village','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1990,1000,1,'避暑山庄 / 普宁寺 / 磬锤峰 —— 纯攻略助你玩透避暑山庄精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「避暑山庄」三日深度游——古村落。承德木雕核桃吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 承德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往承德，抵达后办理入住、熟悉周边环境。","addr":"承德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"避暑山庄","description":"下午首站避暑山庄，调整状态进入旅行节奏，皇家园林之最，山区乘车看小布达拉。","addr":"承德市双桥区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游承德一带氛围拉满，晚餐御土荷叶鸡人均38元。","addr":"承德市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"普宁寺","description":"全天主景点普宁寺，大佛寺千手千眼观音。","addr":"承德市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐荞面饸饹（人均18元），早点休息。","addr":"山庄东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"磬锤峰","description":"收官磬锤峰，棒槌山奇观，索道往返。","addr":"承德市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏仁茶后集合返程，三日旅程圆满。","addr":"二仙居","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"避暑山庄","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"避暑山庄是避暑山庄最有代表性的看点，皇家园林之最，山区乘车看小布达拉。攻略把它排进主线，时间留得最足。","notice":"皇家园林之最，山区乘车看小布达拉。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"承德市双桥区"},{"spotId":"S2","name":"普宁寺","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"普宁寺是避暑山庄最有代表性的看点，大佛寺千手千眼观音。攻略把它排进主线，时间留得最足。","notice":"大佛寺千手千眼观音。这个点位上午光线最好。","durationMinutes":90,"addr":"承德市"},{"spotId":"S3","name":"磬锤峰","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"磬锤峰是避暑山庄最有代表性的看点，棒槌山奇观，索道往返。攻略把它排进主线，时间留得最足。","notice":"棒槌山奇观，索道往返。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"承德市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"御土荷叶鸡（人均38元）","description":"承德 · 避暑山庄的招牌是御土荷叶鸡，老三羊汤本地人都认这家，点单照攻略不踩雷。","addr":"承德市区"},{"title":"荞面饸饹（人均18元）","description":"承德 · 避暑山庄的招牌是荞面饸饹，莜面馆本地人都认这家，点单照攻略不踩雷。","addr":"山庄东路"},{"title":"杏仁茶（人均10元）","description":"承德 · 避暑山庄的招牌是杏仁茶，小吃街本地人都认这家，点单照攻略不踩雷。","addr":"二仙居"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","换洗衣物与外套（早晚温差）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","相机或运动相机","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图"],"faqs":[["到达 承德 的交通方便吗？","推荐先到 承德，再打车或景区直通车前往核心景区；自驾导航直接搜避暑山庄即可。"],["几月份去 承德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('日月湾冲浪纯攻略·美食清单','guide','万宁 · 日月湾冲浪','sea','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',990,500,6,'日月湾 / 石梅湾 / 兴隆热带植物园 —— 纯攻略助你玩透日月湾冲浪精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「日月湾冲浪」两日慢旅行——海滨。兴隆炭烧咖啡回香浓。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 万宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴万宁","description":"集合出发，大巴直达日月湾冲浪，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"日月湾","description":"抵达后首游日月湾，国家冲浪队训练地，新手教程2小时。","addr":"万宁市礼纪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐和乐蟹（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"石梅湾","description":"早起人少，石梅湾精华时段，加井岛浮潜，凤凰九里书屋。","addr":"万宁市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐东山羊，人均88元，补充体力。","addr":"万城镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"兴隆热带植物园","description":"午后游览兴隆热带植物园，咖啡可可巧克力之旅。","addr":"兴隆镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"日月湾","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"日月湾是日月湾冲浪最有代表性的看点，国家冲浪队训练地，新手教程2小时。攻略把它排进主线，时间留得最足。","notice":"国家冲浪队训练地，新手教程2小时。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"万宁市礼纪镇"},{"spotId":"S2","name":"石梅湾","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"石梅湾是日月湾冲浪最有代表性的看点，加井岛浮潜，凤凰九里书屋。攻略把它排进主线，时间留得最足。","notice":"加井岛浮潜，凤凰九里书屋。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"万宁市"},{"spotId":"S3","name":"兴隆热带植物园","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"兴隆热带植物园是日月湾冲浪最有代表性的看点，咖啡可可巧克力之旅。攻略把它排进主线，时间留得最足。","notice":"咖啡可可巧克力之旅。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"兴隆镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"和乐蟹（人均88元）","description":"万宁 · 日月湾冲浪的招牌是和乐蟹，渔家海鲜本地人都认这家，点单照攻略不踩雷。","addr":"东澳镇"},{"title":"东山羊（人均88元）","description":"万宁 · 日月湾冲浪的招牌是东山羊，东山羊庄本地人都认这家，点单照攻略不踩雷。","addr":"万城镇"},{"title":"兴隆咖啡（人均25元）","description":"万宁 · 日月湾冲浪的招牌是兴隆咖啡，咖啡庄园本地人都认这家，点单照攻略不踩雷。","addr":"兴隆镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","少量零食补给","防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 万宁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 万宁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('喀纳斯纯攻略·自由行手册','guide','阿勒泰 · 喀纳斯','water','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',990,500,2,'喀纳斯湖 / 禾木村 / 白哈巴 —— 纯攻略助你玩透喀纳斯精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「喀纳斯」三日深度游——水景。喀纳斯冷水鱼干风味独特。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 阿勒泰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往阿勒泰，抵达后办理入住、熟悉周边环境。","addr":"阿勒泰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"喀纳斯湖","description":"下午首站喀纳斯湖，调整状态进入旅行节奏，三湾晨雾与湖怪传说，观鱼台俯瞰。","addr":"布尔津县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游阿勒泰一带氛围拉满，晚餐烤全羊人均128元。","addr":"禾木村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"禾木村","description":"全天主景点禾木村，图瓦人村落，白桦林晨雾。","addr":"喀纳斯景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐手抓饭（人均35元），早点休息。","addr":"贾登峪","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"白哈巴","description":"收官白哈巴，中哈边境原始村落。","addr":"哈巴河县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐奶茶后集合返程，三日旅程圆满。","addr":"白哈巴","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"喀纳斯湖","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"喀纳斯湖是喀纳斯最有代表性的看点，三湾晨雾与湖怪传说，观鱼台俯瞰。攻略把它排进主线，时间留得最足。","notice":"三湾晨雾与湖怪传说，观鱼台俯瞰。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"布尔津县"},{"spotId":"S2","name":"禾木村","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"禾木村是喀纳斯最有代表性的看点，图瓦人村落，白桦林晨雾。攻略把它排进主线，时间留得最足。","notice":"图瓦人村落，白桦林晨雾。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"喀纳斯景区"},{"spotId":"S3","name":"白哈巴","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"白哈巴是喀纳斯最有代表性的看点，中哈边境原始村落。攻略把它排进主线，时间留得最足。","notice":"中哈边境原始村落。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"哈巴河县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤全羊（人均128元）","description":"阿勒泰 · 喀纳斯的招牌是烤全羊，图瓦人家本地人都认这家，点单照攻略不踩雷。","addr":"禾木村"},{"title":"手抓饭（人均35元）","description":"阿勒泰 · 喀纳斯的招牌是手抓饭，别克餐厅本地人都认这家，点单照攻略不踩雷。","addr":"贾登峪"},{"title":"奶茶（人均20元）","description":"阿勒泰 · 喀纳斯的招牌是奶茶，哈萨克毡房本地人都认这家，点单照攻略不踩雷。","addr":"白哈巴"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","墨镜与拍照道具","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["当地有什么必吃？","到了 阿勒泰，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('中央大街冰雪纯攻略·省钱玩法','guide','哈尔滨 · 中央大街冰雪','art','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,5,'中央大街 / 圣索菲亚大教堂 / 松花江防洪纪念塔 —— 纯攻略助你玩透中央大街冰雪精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「中央大街冰雪」两日慢旅行——文艺。哈尔滨红肠真空好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"黑龙江 · 哈尔滨"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴哈尔滨","description":"集合出发，大巴直达中央大街冰雪，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中央大街","description":"抵达后首游中央大街，百年面包石街道，马迭尔冰棍。","addr":"哈尔滨市道里区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐锅包肉（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"圣索菲亚大教堂","description":"早起人少，圣索菲亚大教堂精华时段，拜占庭绿顶，鸽子广场。","addr":"透笼街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐哈尔滨红肠，人均25元，补充体力。","addr":"中央大街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"松花江防洪纪念塔","description":"午后游览松花江防洪纪念塔，冬季冰上活动集合地。","addr":"道里区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中央大街","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"中央大街是中央大街冰雪最有代表性的看点，百年面包石街道，马迭尔冰棍。攻略把它排进主线，时间留得最足。","notice":"百年面包石街道，马迭尔冰棍。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"哈尔滨市道里区"},{"spotId":"S2","name":"圣索菲亚大教堂","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"圣索菲亚大教堂是中央大街冰雪最有代表性的看点，拜占庭绿顶，鸽子广场。攻略把它排进主线，时间留得最足。","notice":"拜占庭绿顶，鸽子广场。这个点位上午光线最好。","durationMinutes":60,"addr":"透笼街"},{"spotId":"S3","name":"松花江防洪纪念塔","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"松花江防洪纪念塔是中央大街冰雪最有代表性的看点，冬季冰上活动集合地。攻略把它排进主线，时间留得最足。","notice":"冬季冰上活动集合地。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"道里区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"锅包肉（人均48元）","description":"哈尔滨 · 中央大街冰雪的招牌是锅包肉，老厨家本地人都认这家，点单照攻略不踩雷。","addr":"友谊路"},{"title":"哈尔滨红肠（人均25元）","description":"哈尔滨 · 中央大街冰雪的招牌是哈尔滨红肠，秋林里道斯本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"},{"title":"格瓦斯（人均12元）","description":"哈尔滨 · 中央大街冰雪的招牌是格瓦斯，马迭尔冷饮厅本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","相机或运动相机","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","身份证件与手机充电宝","墨镜与拍照道具","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 哈尔滨 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武功山纯攻略·避坑版','guide','萍乡 · 武功山','mountain','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,2,'金顶 / 发云界 / 玻璃栈道 —— 纯攻略助你玩透武功山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武功山」三日深度游——山岳。武功山泉水豆腐宴别错过。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往萍乡，抵达后办理入住、熟悉周边环境。","addr":"萍乡市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，日出云海核心位，山顶比山下冷10度。","addr":"武功山风景区金顶","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游萍乡一带氛围拉满，晚餐萍乡小炒肉人均42元。","addr":"武功山游客中心旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"发云界","description":"全天主景点发云界，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐艾米古（人均10元），早点休息。","addr":"金顶驿站","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"玻璃栈道","description":"收官玻璃栈道，栈道限流，旺季排30分钟。","addr":"武功山吊马桩","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐紫红米粉后集合返程，三日旅程圆满。","addr":"武功山镇主街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。这个点位上午光线最好。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","身份证件与手机充电宝","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","少量零食补给","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 萍乡，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 萍乡 的交通方便吗？","推荐先到 萍乡，再打车或景区直通车前往核心景区；自驾导航直接搜武功山即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('仙女湖纯攻略·深度指南','guide','新余 · 仙女湖','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',2500,1300,2,'仙女湖主体湖区 / 圣集寺 / 龙王阁 —— 纯攻略助你玩透仙女湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「仙女湖」两日慢旅行——水景。新余蜜桔十月后最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 新余"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴新余","description":"集合出发，大巴直达仙女湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"仙女湖主体湖区","description":"抵达后首游仙女湖主体湖区，坐船跳岛游，爱情岛最热门。","addr":"新余市渝水区仙女湖大道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐仙女湖鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"圣集寺","description":"早起人少，圣集寺精华时段，湖畔禅意，人少清净。","addr":"仙女湖钤阳湖畔","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐新余蜜桔鸡，人均58元，补充体力。","addr":"景区出口农家乐","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙王阁","description":"午后游览龙王阁，登阁看千岛湖景。","addr":"仙女湖最高点","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"仙女湖主体湖区","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"仙女湖主体湖区是仙女湖最有代表性的看点，坐船跳岛游，爱情岛最热门。攻略把它排进主线，时间留得最足。","notice":"坐船跳岛游，爱情岛最热门。这个点位上午光线最好。","durationMinutes":180,"addr":"新余市渝水区仙女湖大道"},{"spotId":"S2","name":"圣集寺","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"圣集寺是仙女湖最有代表性的看点，湖畔禅意，人少清净。攻略把它排进主线，时间留得最足。","notice":"湖畔禅意，人少清净。这个点位上午光线最好。","durationMinutes":60,"addr":"仙女湖钤阳湖畔"},{"spotId":"S3","name":"龙王阁","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"龙王阁是仙女湖最有代表性的看点，登阁看千岛湖景。攻略把它排进主线，时间留得最足。","notice":"登阁看千岛湖景。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"仙女湖最高点"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"仙女湖鱼头（人均78元）","description":"新余 · 仙女湖的招牌是仙女湖鱼头，湖畔渔村本地人都认这家，点单照攻略不踩雷。","addr":"仙女湖码头渔家街"},{"title":"新余蜜桔鸡（人均58元）","description":"新余 · 仙女湖的招牌是新余蜜桔鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口农家乐"},{"title":"水北豆腐（人均25元）","description":"新余 · 仙女湖的招牌是水北豆腐，老豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"新余城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","相机或运动相机","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","身份证件与手机充电宝","少量零食补给","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 新余 的交通方便吗？","推荐先到 新余，再打车或景区直通车前往核心景区；自驾导航直接搜仙女湖即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('崀山纯攻略·周末版','guide','邵阳 · 崀山','adventure','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',1990,1000,9,'辣椒峰 / 天一巷 / 扶夷江竹筏 —— 纯攻略助你玩透崀山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「崀山」三日深度游——探险地。新宁脐橙秋冬正当季。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 邵阳"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往邵阳，抵达后办理入住、熟悉周边环境。","addr":"邵阳市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"辣椒峰","description":"下午首站辣椒峰，调整状态进入旅行节奏，丹霞地貌标志峰，远观近爬两相宜。","addr":"新宁县崀山景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游邵阳一带氛围拉满，晚餐崀山腊肉人均52元。","addr":"崀山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天一巷","description":"全天主景点天一巷，一线天最窄处仅33厘米。","addr":"崀山丹霞巷谷","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐血酱鸭（人均58元），早点休息。","addr":"新宁县城","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"扶夷江竹筏","description":"收官扶夷江竹筏，竹筏漂流看丹霞倒影。","addr":"崀山水上游线","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐脐橙后集合返程，三日旅程圆满。","addr":"崀山脚下果园","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"辣椒峰","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"辣椒峰是崀山最有代表性的看点，丹霞地貌标志峰，远观近爬两相宜。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌标志峰，远观近爬两相宜。这个点位上午光线最好。","durationMinutes":150,"addr":"新宁县崀山景区"},{"spotId":"S2","name":"天一巷","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"天一巷是崀山最有代表性的看点，一线天最窄处仅33厘米。攻略把它排进主线，时间留得最足。","notice":"一线天最窄处仅33厘米。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"崀山丹霞巷谷"},{"spotId":"S3","name":"扶夷江竹筏","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"扶夷江竹筏是崀山最有代表性的看点，竹筏漂流看丹霞倒影。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流看丹霞倒影。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"崀山水上游线"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"崀山腊肉（人均52元）","description":"邵阳 · 崀山的招牌是崀山腊肉，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"崀山镇"},{"title":"血酱鸭（人均58元）","description":"邵阳 · 崀山的招牌是血酱鸭，邵阳风味馆本地人都认这家，点单照攻略不踩雷。","addr":"新宁县城"},{"title":"脐橙（人均10元）","description":"邵阳 · 崀山的招牌是脐橙，果园直购本地人都认这家，点单照攻略不踩雷。","addr":"崀山脚下果园"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机","换洗衣物与外套（早晚温差）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('告庄西双景纯攻略·亲子篇','guide','西双版纳 · 告庄西双景','sea','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,6,'告庄星光夜市 / 曼听公园 / 中科院热带植物园 —— 纯攻略助你玩透告庄西双景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「告庄西双景」两日慢旅行——海滨。版纳小粒咖啡香浓不酸。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 西双版纳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴西双版纳","description":"集合出发，大巴直达告庄西双景，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"告庄星光夜市","description":"抵达后首游告庄星光夜市，大金塔下的东南亚最大夜市。","addr":"景洪市告庄西双景","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐菠萝饭（人均25元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"曼听公园","description":"早起人少，曼听公园精华时段，总佛寺相邻，晚场篝火晚会。","addr":"景洪市曼听路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香茅草烤鱼，人均48元，补充体力。","addr":"告庄内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"中科院热带植物园","description":"午后游览中科院热带植物园，王莲上坐一坐，热气球拍照。","addr":"勐腊县勐仑镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"告庄星光夜市","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"告庄星光夜市是告庄西双景最有代表性的看点，大金塔下的东南亚最大夜市。攻略把它排进主线，时间留得最足。","notice":"大金塔下的东南亚最大夜市。这个点位上午光线最好。","durationMinutes":180,"addr":"景洪市告庄西双景"},{"spotId":"S2","name":"曼听公园","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"曼听公园是告庄西双景最有代表性的看点，总佛寺相邻，晚场篝火晚会。攻略把它排进主线，时间留得最足。","notice":"总佛寺相邻，晚场篝火晚会。这个点位上午光线最好。","durationMinutes":150,"addr":"景洪市曼听路"},{"spotId":"S3","name":"中科院热带植物园","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"中科院热带植物园是告庄西双景最有代表性的看点，王莲上坐一坐，热气球拍照。攻略把它排进主线，时间留得最足。","notice":"王莲上坐一坐，热气球拍照。这个点位上午光线最好。","durationMinutes":240,"addr":"勐腊县勐仑镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"菠萝饭（人均25元）","description":"西双版纳 · 告庄西双景的招牌是菠萝饭，夜市傣味摊本地人都认这家，点单照攻略不踩雷。","addr":"星光夜市"},{"title":"香茅草烤鱼（人均48元）","description":"西双版纳 · 告庄西双景的招牌是香茅草烤鱼，曼飞龙烤鸡本地人都认这家，点单照攻略不踩雷。","addr":"告庄内"},{"title":"泡鲁达（人均15元）","description":"西双版纳 · 告庄西双景的招牌是泡鲁达，傣家甜品店本地人都认这家，点单照攻略不踩雷。","addr":"大金塔旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","保温水杯与少量现金","少量零食补给","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","相机或运动相机","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 西双版纳 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 西双版纳 的交通方便吗？","推荐先到 西双版纳，再打车或景区直通车前往核心景区；自驾导航直接搜告庄西双景即可。"],["当地有什么必吃？","到了 西双版纳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阆中古城纯攻略·摄影机位','guide','南充 · 阆中古城','ancient_town','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',990,500,1,'阆中古城 / 华光楼 / 锦屏山 —— 纯攻略助你玩透阆中古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阆中古城」三日深度游——古镇。保宁醋是四大名醋之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 南充"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往南充，抵达后办理入住、熟悉周边环境。","addr":"南充市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"阆中古城","description":"下午首站阆中古城，调整状态进入旅行节奏，四大古城之一，张飞庙贡院联票。","addr":"南充市阆中市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游南充一带氛围拉满，晚餐张飞牛肉人均45元。","addr":"古城北街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"华光楼","description":"全天主景点华光楼，登楼看嘉陵江三面环抱。","addr":"古城上华街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐保宁醋（人均20元），早点休息。","addr":"古城内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"锦屏山","description":"收官锦屏山，观古城全景最佳位。","addr":"古城对岸","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐油香后集合返程，三日旅程圆满。","addr":"下沙河街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"阆中古城","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"阆中古城是阆中古城最有代表性的看点，四大古城之一，张飞庙贡院联票。攻略把它排进主线，时间留得最足。","notice":"四大古城之一，张飞庙贡院联票。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"南充市阆中市"},{"spotId":"S2","name":"华光楼","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"华光楼是阆中古城最有代表性的看点，登楼看嘉陵江三面环抱。攻略把它排进主线，时间留得最足。","notice":"登楼看嘉陵江三面环抱。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"古城上华街"},{"spotId":"S3","name":"锦屏山","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"锦屏山是阆中古城最有代表性的看点，观古城全景最佳位。攻略把它排进主线，时间留得最足。","notice":"观古城全景最佳位。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"古城对岸"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"张飞牛肉（人均45元）","description":"南充 · 阆中古城的招牌是张飞牛肉，张飞牛肉旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"古城北街"},{"title":"保宁醋（人均20元）","description":"南充 · 阆中古城的招牌是保宁醋，醋文化博览馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"油香（人均8元）","description":"南充 · 阆中古城的招牌是油香，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"下沙河街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","墨镜与拍照道具","保温水杯与少量现金","换洗衣物与外套（早晚温差）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 南充 的交通方便吗？","推荐先到 南充，再打车或景区直通车前往核心景区；自驾导航直接搜阆中古城即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('镇远古镇纯攻略·美食清单','guide','黔东南 · 镇远古镇','ancient_town','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',2500,1300,1,'青龙洞 / 舞阳河 / 石屏山 —— 纯攻略助你玩透镇远古镇精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「镇远古镇」两日慢旅行——古镇。镇远蓝染布艺越洗越好看。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔东南","description":"集合出发，大巴直达镇远古镇，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青龙洞","description":"抵达后首游青龙洞，贴崖古建筑群，对望古城。","addr":"镇远县中和山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐酸汤鱼（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"舞阳河","description":"早起人少，舞阳河精华时段，乘船看孔雀开屏峰。","addr":"镇远县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐陈年道菜，人均30元，补充体力。","addr":"古镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"石屏山","description":"午后游览石屏山，俯瞰太极古城全景。","addr":"古城北侧","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青龙洞","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"青龙洞是镇远古镇最有代表性的看点，贴崖古建筑群，对望古城。攻略把它排进主线，时间留得最足。","notice":"贴崖古建筑群，对望古城。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"镇远县中和山"},{"spotId":"S2","name":"舞阳河","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"舞阳河是镇远古镇最有代表性的看点，乘船看孔雀开屏峰。攻略把它排进主线，时间留得最足。","notice":"乘船看孔雀开屏峰。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"镇远县"},{"spotId":"S3","name":"石屏山","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"石屏山是镇远古镇最有代表性的看点，俯瞰太极古城全景。攻略把它排进主线，时间留得最足。","notice":"俯瞰太极古城全景。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"古城北侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均58元）","description":"黔东南 · 镇远古镇的招牌是酸汤鱼，古城酸汤馆本地人都认这家，点单照攻略不踩雷。","addr":"兴隆街"},{"title":"陈年道菜（人均30元）","description":"黔东南 · 镇远古镇的招牌是陈年道菜，老字号本地人都认这家，点单照攻略不踩雷。","addr":"古镇主街"},{"title":"苗家腊肉（人均48元）","description":"黔东南 · 镇远古镇的招牌是苗家腊肉，河畔农家本地人都认这家，点单照攻略不踩雷。","addr":"舞阳河畔"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金","相机或运动相机","常用药品（肠胃药/创可贴）","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 黔东南，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 黔东南 的交通方便吗？","推荐先到 黔东南，再打车或景区直通车前往核心景区；自驾导航直接搜镇远古镇即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('鼓浪屿纯攻略·自由行手册','guide','厦门 · 鼓浪屿','sea','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',2500,1300,6,'日光岩 / 菽庄花园 / 沙坡尾 —— 纯攻略助你玩透鼓浪屿精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「鼓浪屿」三日深度游——海滨。厦门馅饼老字号最正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 厦门"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往厦门，抵达后办理入住、熟悉周边环境。","addr":"厦门市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"日光岩","description":"下午首站日光岩，调整状态进入旅行节奏，全岛最高点看红瓦绿树海景。","addr":"鼓浪屿龙头山路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游厦门一带氛围拉满，晚餐沙茶面人均28元。","addr":"民族路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"菽庄花园","description":"全天主景点菽庄花园，四十四桥跨海，钢琴博物馆。","addr":"鼓浪屿港仔后路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海蛎煎（人均25元），早点休息。","addr":"八市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙坡尾","description":"收官沙坡尾，避风坞文艺街区，猫街涂鸦。","addr":"厦门市思明区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐土笋冻后集合返程，三日旅程圆满。","addr":"斗西路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"日光岩","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"日光岩是鼓浪屿最有代表性的看点，全岛最高点看红瓦绿树海景。攻略把它排进主线，时间留得最足。","notice":"全岛最高点看红瓦绿树海景。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"鼓浪屿龙头山路"},{"spotId":"S2","name":"菽庄花园","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"菽庄花园是鼓浪屿最有代表性的看点，四十四桥跨海，钢琴博物馆。攻略把它排进主线，时间留得最足。","notice":"四十四桥跨海，钢琴博物馆。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"鼓浪屿港仔后路"},{"spotId":"S3","name":"沙坡尾","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"沙坡尾是鼓浪屿最有代表性的看点，避风坞文艺街区，猫街涂鸦。攻略把它排进主线，时间留得最足。","notice":"避风坞文艺街区，猫街涂鸦。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"厦门市思明区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"沙茶面（人均28元）","description":"厦门 · 鼓浪屿的招牌是沙茶面，乌糖沙茶面本地人都认这家，点单照攻略不踩雷。","addr":"民族路"},{"title":"海蛎煎（人均25元）","description":"厦门 · 鼓浪屿的招牌是海蛎煎，莲欢海蛎煎本地人都认这家，点单照攻略不踩雷。","addr":"八市"},{"title":"土笋冻（人均15元）","description":"厦门 · 鼓浪屿的招牌是土笋冻，西门土笋冻本地人都认这家，点单照攻略不踩雷。","addr":"斗西路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","相机或运动相机","少量零食补给","墨镜与拍照道具","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["几月份去 厦门 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 厦门，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雁荡山纯攻略·省钱玩法','guide','温州 · 雁荡山','mountain','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',1200,600,2,'灵峰 / 大龙湫 / 方洞栈道 —— 纯攻略助你玩透雁荡山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「雁荡山」两日慢旅行——山岳。雁荡山铁皮石斛有名。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 温州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴温州","description":"集合出发，大巴直达雁荡山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"灵峰","description":"抵达后首游灵峰，日景夜景两相宜，夫妻峰剪影。","addr":"乐清市雁荡山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐雁荡山石斑鱼（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大龙湫","description":"早起人少，大龙湫精华时段，190米瀑布，雨后最壮。","addr":"雁荡山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香鱼，人均48元，补充体力。","addr":"大龙湫下","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"方洞栈道","description":"午后游览方洞栈道，悬崖栈道悬空百米。","addr":"雁荡山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"灵峰","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"灵峰是雁荡山最有代表性的看点，日景夜景两相宜，夫妻峰剪影。攻略把它排进主线，时间留得最足。","notice":"日景夜景两相宜，夫妻峰剪影。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"乐清市雁荡山"},{"spotId":"S2","name":"大龙湫","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"大龙湫是雁荡山最有代表性的看点，190米瀑布，雨后最壮。攻略把它排进主线，时间留得最足。","notice":"190米瀑布，雨后最壮。这个点位上午光线最好。","durationMinutes":90,"addr":"雁荡山"},{"spotId":"S3","name":"方洞栈道","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"方洞栈道是雁荡山最有代表性的看点，悬崖栈道悬空百米。攻略把它排进主线，时间留得最足。","notice":"悬崖栈道悬空百米。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"雁荡山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"雁荡山石斑鱼（人均58元）","description":"温州 · 雁荡山的招牌是雁荡山石斑鱼，山溪鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"响岭头村"},{"title":"香鱼（人均48元）","description":"温州 · 雁荡山的招牌是香鱼，溪鱼农家本地人都认这家，点单照攻略不踩雷。","addr":"大龙湫下"},{"title":"雁茗茶（人均25元）","description":"温州 · 雁荡山的招牌是雁茗茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"灵峰景区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","相机或运动相机","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 温州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄山宏村纯攻略·避坑版','guide','黄山 · 黄山宏村','mountain','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2990,1600,2,'黄山光明顶 / 西海大峡谷 / 宏村 —— 纯攻略助你玩透黄山宏村精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「黄山宏村」三日深度游——山岳。徽墨歙砚文房收藏佳品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 黄山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黄山，抵达后办理入住、熟悉周边环境。","addr":"黄山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄山光明顶","description":"下午首站黄山光明顶，调整状态进入旅行节奏，看日出云海的主峰平台。","addr":"黄山市黄山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黄山一带氛围拉满，晚餐臭鳜鱼人均78元。","addr":"屯溪老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西海大峡谷","description":"全天主景点西海大峡谷，网红小火车，峡谷栈道惊险。","addr":"黄山风景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐毛豆腐（人均20元），早点休息。","addr":"宏村月沼旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"宏村","description":"收官宏村，月沼南湖水墨徽州，写生圣地。","addr":"黟县宏村镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐黄山烧饼后集合返程，三日旅程圆满。","addr":"汤口镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄山光明顶","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"黄山光明顶是黄山宏村最有代表性的看点，看日出云海的主峰平台。攻略把它排进主线，时间留得最足。","notice":"看日出云海的主峰平台。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"黄山市黄山区"},{"spotId":"S2","name":"西海大峡谷","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"西海大峡谷是黄山宏村最有代表性的看点，网红小火车，峡谷栈道惊险。攻略把它排进主线，时间留得最足。","notice":"网红小火车，峡谷栈道惊险。这个点位上午光线最好。","durationMinutes":240,"addr":"黄山风景区"},{"spotId":"S3","name":"宏村","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"宏村是黄山宏村最有代表性的看点，月沼南湖水墨徽州，写生圣地。攻略把它排进主线，时间留得最足。","notice":"月沼南湖水墨徽州，写生圣地。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"黟县宏村镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"臭鳜鱼（人均78元）","description":"黄山 · 黄山宏村的招牌是臭鳜鱼，老街第一楼本地人都认这家，点单照攻略不踩雷。","addr":"屯溪老街"},{"title":"毛豆腐（人均20元）","description":"黄山 · 黄山宏村的招牌是毛豆腐，徽州小吃本地人都认这家，点单照攻略不踩雷。","addr":"宏村月沼旁"},{"title":"黄山烧饼（人均12元）","description":"黄山 · 黄山宏村的招牌是黄山烧饼，救驾烧饼本地人都认这家，点单照攻略不踩雷。","addr":"汤口镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","少量零食补给","换洗衣物与外套（早晚温差）","保温水杯与少量现金","相机或运动相机","墨镜与拍照道具","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 黄山，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙门石窟纯攻略·深度指南','guide','洛阳 · 龙门石窟','red','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',990,500,7,'龙门石窟 / 白马寺 / 洛邑古城 —— 纯攻略助你玩透龙门石窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙门石窟」两日慢旅行——人文。洛阳牡丹饼花香浓郁。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 洛阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴洛阳","description":"集合出发，大巴直达龙门石窟，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"龙门石窟","description":"抵达后首游龙门石窟，卢舍那大佛，夜游灯光版。","addr":"洛阳市洛龙区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐水席（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"白马寺","description":"早起人少，白马寺精华时段，中国第一古刹，国际佛殿。","addr":"洛阳市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牛肉汤，人均15元，补充体力。","addr":"瀍河区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"洛邑古城","description":"午后游览洛邑古城，汉服打卡圣地，夜景。","addr":"老城区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"龙门石窟","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"龙门石窟是龙门石窟最有代表性的看点，卢舍那大佛，夜游灯光版。攻略把它排进主线，时间留得最足。","notice":"卢舍那大佛，夜游灯光版。这个点位上午光线最好。","durationMinutes":180,"addr":"洛阳市洛龙区"},{"spotId":"S2","name":"白马寺","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=cr