INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('平遥古城纯攻略·周末版','guide','晋中 · 平遥古城','ancient_town','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',2990,1600,1,'平遥古城墙 / 日升昌票号 / 协同庆地下金库 —— 纯攻略助你玩透平遥古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「平遥古城」三日深度游——古镇。平遥推光漆器手工至极。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 晋中"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往晋中，抵达后办理入住、熟悉周边环境。","addr":"晋中市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"平遥古城墙","description":"下午首站平遥古城墙，调整状态进入旅行节奏，完整明代城墙，骑行一周。","addr":"晋中市平遥县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游晋中一带氛围拉满，晚餐平遥牛肉人均45元。","addr":"古城南大街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"日升昌票号","description":"全天主景点日升昌票号，中国第一家票号，晋商传奇。","addr":"古城西大街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐碗托（人均12元），早点休息。","addr":"城隍庙街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"协同庆地下金库","description":"收官协同庆地下金库，探秘地下金库。","addr":"古城市楼旁","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐莜面栲栳栳后集合返程，三日旅程圆满。","addr":"西大街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"平遥古城墙","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"平遥古城墙是平遥古城最有代表性的看点，完整明代城墙，骑行一周。攻略把它排进主线，时间留得最足。","notice":"完整明代城墙，骑行一周。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"晋中市平遥县"},{"spotId":"S2","name":"日升昌票号","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"日升昌票号是平遥古城最有代表性的看点，中国第一家票号，晋商传奇。攻略把它排进主线，时间留得最足。","notice":"中国第一家票号，晋商传奇。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"古城西大街"},{"spotId":"S3","name":"协同庆地下金库","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"协同庆地下金库是平遥古城最有代表性的看点，探秘地下金库。攻略把它排进主线，时间留得最足。","notice":"探秘地下金库。这个点位上午光线最好。","durationMinutes":60,"addr":"古城市楼旁"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"平遥牛肉（人均45元）","description":"晋中 · 平遥古城的招牌是平遥牛肉，冠云专卖店本地人都认这家，点单照攻略不踩雷。","addr":"古城南大街"},{"title":"碗托（人均12元）","description":"晋中 · 平遥古城的招牌是碗托，碗托娘子本地人都认这家，点单照攻略不踩雷。","addr":"城隍庙街"},{"title":"莜面栲栳栳（人均28元）","description":"晋中 · 平遥古城的招牌是莜面栲栳栳，晋菜馆本地人都认这家，点单照攻略不踩雷。","addr":"西大街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）","少量零食补给","轻便雨衣或折叠伞","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意"],"faqs":[["当地有什么必吃？","到了 晋中，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('北戴河阿那亚纯攻略·亲子篇','guide','秦皇岛 · 北戴河阿那亚','sea','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',2990,1600,6,'阿那亚礼堂 / 鸽子窝公园 / 山海关天下第一关 —— 纯攻略助你玩透北戴河阿那亚精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「北戴河阿那亚」两日慢旅行——海滨。北戴河干海参实惠。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 秦皇岛"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴秦皇岛","description":"集合出发，大巴直达北戴河阿那亚，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"阿那亚礼堂","description":"抵达后首游阿那亚礼堂，海边白色礼堂，孤独图书馆。","addr":"秦皇岛市昌黎县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐海鲜烧烤（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"鸽子窝公园","description":"早起人少，鸽子窝公园精华时段，观鸟湿地日出圣地。","addr":"北戴河区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐四条包子，人均12元，补充体力。","addr":"山海关","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"山海关天下第一关","description":"午后游览山海关天下第一关，长城入海老龙头。","addr":"山海关区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"阿那亚礼堂","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"阿那亚礼堂是北戴河阿那亚最有代表性的看点，海边白色礼堂，孤独图书馆。攻略把它排进主线，时间留得最足。","notice":"海边白色礼堂，孤独图书馆。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"秦皇岛市昌黎县"},{"spotId":"S2","name":"鸽子窝公园","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"鸽子窝公园是北戴河阿那亚最有代表性的看点，观鸟湿地日出圣地。攻略把它排进主线，时间留得最足。","notice":"观鸟湿地日出圣地。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"北戴河区"},{"spotId":"S3","name":"山海关天下第一关","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"山海关天下第一关是北戴河阿那亚最有代表性的看点，长城入海老龙头。攻略把它排进主线，时间留得最足。","notice":"长城入海老龙头。这个点位上午光线最好。","durationMinutes":150,"addr":"山海关区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜烧烤（人均68元）","description":"秦皇岛 · 北戴河阿那亚的招牌是海鲜烧烤，刘庄夜市本地人都认这家，点单照攻略不踩雷。","addr":"北戴河刘庄"},{"title":"四条包子（人均12元）","description":"秦皇岛 · 北戴河阿那亚的招牌是四条包子，四条包子铺本地人都认这家，点单照攻略不踩雷。","addr":"山海关"},{"title":"杨肠子（人均25元）","description":"秦皇岛 · 北戴河阿那亚的招牌是杨肠子，火腿肠老字号本地人都认这家，点单照攻略不踩雷。","addr":"北戴河"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","换洗衣物与外套（早晚温差）","少量零食补给","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意"],"faqs":[["到达 秦皇岛 的交通方便吗？","推荐先到 秦皇岛，再打车或景区直通车前往核心景区；自驾导航直接搜北戴河阿那亚即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 秦皇岛，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('洪崖洞夜景纯攻略·摄影机位','guide','渝中 · 洪崖洞夜景','food','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1990,1000,3,'洪崖洞 / 长江索道 / 山城步道 —— 纯攻略助你玩透洪崖洞夜景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「洪崖洞夜景」三日深度游——美食。重庆火锅底料真空包装。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 渝中"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往渝中，抵达后办理入住、熟悉周边环境。","addr":"渝中市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"洪崖洞","description":"下午首站洪崖洞，调整状态进入旅行节奏，千与千寻同款夜景，对岸拍全景。","addr":"渝中区嘉陵江畔","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游渝中一带氛围拉满，晚餐重庆火锅人均98元。","addr":"解放碑","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长江索道","description":"全天主景点长江索道，空中横渡长江，排队1小时。","addr":"渝中区新华路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐重庆小面（人均15元），早点休息。","addr":"民生路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"山城步道","description":"收官山城步道，第三步道悬空栈道看老重庆。","addr":"渝中区中兴路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸辣粉后集合返程，三日旅程圆满。","addr":"八一路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"洪崖洞","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"洪崖洞是洪崖洞夜景最有代表性的看点，千与千寻同款夜景，对岸拍全景。攻略把它排进主线，时间留得最足。","notice":"千与千寻同款夜景，对岸拍全景。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"渝中区嘉陵江畔"},{"spotId":"S2","name":"长江索道","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"长江索道是洪崖洞夜景最有代表性的看点，空中横渡长江，排队1小时。攻略把它排进主线，时间留得最足。","notice":"空中横渡长江，排队1小时。这个点位上午光线最好。","durationMinutes":60,"addr":"渝中区新华路"},{"spotId":"S3","name":"山城步道","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"山城步道是洪崖洞夜景最有代表性的看点，第三步道悬空栈道看老重庆。攻略把它排进主线，时间留得最足。","notice":"第三步道悬空栈道看老重庆。这个点位上午光线最好。","durationMinutes":120,"addr":"渝中区中兴路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"重庆火锅（人均98元）","description":"渝中 · 洪崖洞夜景的招牌是重庆火锅，佩姐老火锅本地人都认这家，点单照攻略不踩雷。","addr":"解放碑"},{"title":"重庆小面（人均15元）","description":"渝中 · 洪崖洞夜景的招牌是重庆小面，花市豌杂面本地人都认这家，点单照攻略不踩雷。","addr":"民生路"},{"title":"酸辣粉（人均12元）","description":"渝中 · 洪崖洞夜景的招牌是酸辣粉，好又来酸辣粉本地人都认这家，点单照攻略不踩雷。","addr":"八一路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","墨镜与拍照道具","保温水杯与少量现金","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["几月份去 渝中 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 渝中 的交通方便吗？","推荐先到 渝中，再打车或景区直通车前往核心景区；自驾导航直接搜洪崖洞夜景即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('赛里木湖纯攻略·美食清单','guide','伊犁 · 赛里木湖','water','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1990,1000,2,'赛里木湖 / 果子沟大桥 / 霍尔果斯口岸 —— 纯攻略助你玩透赛里木湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「赛里木湖」两日慢旅行——水景。伊犁薰衣草精油真香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 伊犁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴伊犁","description":"集合出发，大巴直达赛里木湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"赛里木湖","description":"抵达后首游赛里木湖，大西洋最后一滴眼泪，环湖骑行。","addr":"博乐市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐高白鲑（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"果子沟大桥","description":"早起人少，果子沟大桥精华时段，空中巨龙，观景台打卡。","addr":"霍城县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤包子，人均10元，补充体力。","addr":"果子沟","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"霍尔果斯口岸","description":"午后游览霍尔果斯口岸，中哈边境免税购物。","addr":"霍尔果斯市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"赛里木湖","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"赛里木湖是赛里木湖最有代表性的看点，大西洋最后一滴眼泪，环湖骑行。攻略把它排进主线，时间留得最足。","notice":"大西洋最后一滴眼泪，环湖骑行。这个点位上午光线最好。","durationMinutes":240,"addr":"博乐市"},{"spotId":"S2","name":"果子沟大桥","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"果子沟大桥是赛里木湖最有代表性的看点，空中巨龙，观景台打卡。攻略把它排进主线，时间留得最足。","notice":"空中巨龙，观景台打卡。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"霍城县"},{"spotId":"S3","name":"霍尔果斯口岸","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"霍尔果斯口岸是赛里木湖最有代表性的看点，中哈边境免税购物。攻略把它排进主线，时间留得最足。","notice":"中哈边境免税购物。这个点位上午光线最好。","durationMinutes":120,"addr":"霍尔果斯市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"高白鲑（人均88元）","description":"伊犁 · 赛里木湖的招牌是高白鲑，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"赛里木湖"},{"title":"烤包子（人均10元）","description":"伊犁 · 赛里木湖的招牌是烤包子，维族馕坑本地人都认这家，点单照攻略不踩雷。","addr":"果子沟"},{"title":"马奶酒（人均25元）","description":"伊犁 · 赛里木湖的招牌是马奶酒，牧民家本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","墨镜与拍照道具","少量零食补给","保温水杯与少量现金","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 伊犁 的交通方便吗？","推荐先到 伊犁，再打车或景区直通车前往核心景区；自驾导航直接搜赛里木湖即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('长白山纯攻略·自由行手册','guide','延边 · 长白山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',990,500,2,'天池北坡 / 长白瀑布 / 绿渊潭 —— 纯攻略助你玩透长白山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「长白山」三日深度游——山岳。长白山林下参滋补。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"吉林 · 延边"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往延边，抵达后办理入住、熟悉周边环境。","addr":"延边市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"天池北坡","description":"下午首站天池北坡，调整状态进入旅行节奏，长白山主峰天池，天气好才能见。","addr":"延边州安图县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游延边一带氛围拉满，晚餐朝鲜冷面人均22元。","addr":"二道白河镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长白瀑布","description":"全天主景点长白瀑布，68米瀑布与温泉煮蛋。","addr":"北坡景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐石锅拌饭（人均28元），早点休息。","addr":"延吉市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"绿渊潭","description":"收官绿渊潭，碧绿水潭与飞瀑。","addr":"北坡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐温泉煮蛋后集合返程，三日旅程圆满。","addr":"北坡","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"天池北坡","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"天池北坡是长白山最有代表性的看点，长白山主峰天池，天气好才能见。攻略把它排进主线，时间留得最足。","notice":"长白山主峰天池，天气好才能见。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"延边州安图县"},{"spotId":"S2","name":"长白瀑布","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"长白瀑布是长白山最有代表性的看点，68米瀑布与温泉煮蛋。攻略把它排进主线，时间留得最足。","notice":"68米瀑布与温泉煮蛋。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"北坡景区"},{"spotId":"S3","name":"绿渊潭","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"绿渊潭是长白山最有代表性的看点，碧绿水潭与飞瀑。攻略把它排进主线，时间留得最足。","notice":"碧绿水潭与飞瀑。这个点位上午光线最好。","durationMinutes":60,"addr":"北坡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"朝鲜冷面（人均22元）","description":"延边 · 长白山的招牌是朝鲜冷面，服务大楼冷面本地人都认这家，点单照攻略不踩雷。","addr":"二道白河镇"},{"title":"石锅拌饭（人均28元）","description":"延边 · 长白山的招牌是石锅拌饭，金达莱餐厅本地人都认这家，点单照攻略不踩雷。","addr":"延吉市"},{"title":"温泉煮蛋（人均10元）","description":"延边 · 长白山的招牌是温泉煮蛋，瀑布温泉口本地人都认这家，点单照攻略不踩雷。","addr":"北坡"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","相机或运动相机","墨镜与拍照道具","身份证件与手机充电宝","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 延边，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('井冈山纯攻略·省钱玩法2','guide','吉安 · 井冈山','red','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,7,'黄洋界 / 茨坪革命旧址群 / 龙潭 —— 纯攻略助你玩透井冈山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「井冈山」两日慢旅行——人文。井冈山竹制工艺品轻便好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 吉安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴吉安","description":"集合出发，大巴直达井冈山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄洋界","description":"抵达后首游黄洋界，保卫战旧址，云海出现率高。","addr":"井冈山市黄洋界景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红米饭南瓜汤（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"茨坪革命旧址群","description":"早起人少，茨坪革命旧址群精华时段，旧址集中，步行串游。","addr":"井冈山市茨坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐井冈烟笋，人均38元，补充体力。","addr":"黄洋界山下餐馆","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙潭","description":"午后游览龙潭，五潭十八瀑，索道省力。","addr":"井冈山龙潭景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄洋界","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"黄洋界是井冈山最有代表性的看点，保卫战旧址，云海出现率高。攻略把它排进主线，时间留得最足。","notice":"保卫战旧址，云海出现率高。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"井冈山市黄洋界景区"},{"spotId":"S2","name":"茨坪革命旧址群","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"茨坪革命旧址群是井冈山最有代表性的看点，旧址集中，步行串游。攻略把它排进主线，时间留得最足。","notice":"旧址集中，步行串游。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"井冈山市茨坪镇"},{"spotId":"S3","name":"龙潭","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"龙潭是井冈山最有代表性的看点，五潭十八瀑，索道省力。攻略把它排进主线，时间留得最足。","notice":"五潭十八瀑，索道省力。这个点位上午光线最好。","durationMinutes":180,"addr":"井冈山龙潭景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红米饭南瓜汤（人均45元）","description":"吉安 · 井冈山的招牌是红米饭南瓜汤，老乡家常菜本地人都认这家，点单照攻略不踩雷。","addr":"茨坪天街"},{"title":"井冈烟笋（人均38元）","description":"吉安 · 井冈山的招牌是井冈烟笋，山上饭庄本地人都认这家，点单照攻略不踩雷。","addr":"黄洋界山下餐馆"},{"title":"石鸡炖汤（人均88元）","description":"吉安 · 井冈山的招牌是石鸡炖汤，龙潭农庄本地人都认这家，点单照攻略不踩雷。","addr":"龙潭景区入口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","身份证件与手机充电宝","少量零食补给","常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 吉安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大觉山纯攻略·避坑版2','guide','抚州 · 大觉山','adventure','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',2990,1600,9,'大觉山漂流 / 大觉岩寺 / 古镇影视城 —— 纯攻略助你玩透大觉山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大觉山」三日深度游——探险地。资溪面包是当地人的骄傲。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 抚州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往抚州，抵达后办理入住、熟悉周边环境。","addr":"抚州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大觉山漂流","description":"下午首站大觉山漂流，调整状态进入旅行节奏，华东第一漂，全程3.5公里带好换洗衣。","addr":"资溪县大觉山景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游抚州一带氛围拉满，晚餐资溪面包人均15元。","addr":"资溪县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大觉岩寺","description":"全天主景点大觉岩寺，悬崖上的古寺，索道直达。","addr":"大觉山主峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐笋干烧肉（人均48元），早点休息。","addr":"大觉山游客中心","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古镇影视城","description":"收官古镇影视城，仿宋古镇，拍照出片。","addr":"大觉山脚下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐发酵豆腐后集合返程，三日旅程圆满。","addr":"影视城内街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大觉山漂流","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"大觉山漂流是大觉山最有代表性的看点，华东第一漂，全程3.5公里带好换洗衣。攻略把它排进主线，时间留得最足。","notice":"华东第一漂，全程3.5公里带好换洗衣。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"资溪县大觉山景区"},{"spotId":"S2","name":"大觉岩寺","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大觉岩寺是大觉山最有代表性的看点，悬崖上的古寺，索道直达。攻略把它排进主线，时间留得最足。","notice":"悬崖上的古寺，索道直达。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"大觉山主峰"},{"spotId":"S3","name":"古镇影视城","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"古镇影视城是大觉山最有代表性的看点，仿宋古镇，拍照出片。攻略把它排进主线，时间留得最足。","notice":"仿宋古镇，拍照出片。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"大觉山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"资溪面包（人均15元）","description":"抚州 · 大觉山的招牌是资溪面包，面包之乡旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"资溪县城"},{"title":"笋干烧肉（人均48元）","description":"抚州 · 大觉山的招牌是笋干烧肉，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"大觉山游客中心"},{"title":"发酵豆腐（人均18元）","description":"抚州 · 大觉山的招牌是发酵豆腐，古镇豆坊本地人都认这家，点单照攻略不踩雷。","addr":"影视城内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","少量零食补给","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 抚州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 抚州 的交通方便吗？","推荐先到 抚州，再打车或景区直通车前往核心景区；自驾导航直接搜大觉山即可。"],["当地有什么必吃？","到了 抚州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳阳楼洞庭湖纯攻略·深度指南2','guide','岳阳 · 岳阳楼洞庭湖','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1990,1000,2,'岳阳楼 / 君山岛 / 圣安寺 —— 纯攻略助你玩透岳阳楼洞庭湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「岳阳楼洞庭湖」两日慢旅行——水景。君山银针是十大名茶之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 岳阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴岳阳","description":"集合出发，大巴直达岳阳楼洞庭湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"岳阳楼","description":"抵达后首游岳阳楼，洞庭天下水岳阳天下楼，背岳阳楼记免票。","addr":"岳阳市岳阳楼区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐洞庭鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"君山岛","description":"早起人少，君山岛精华时段，湘妃竹与银针茶的故乡。","addr":"洞庭湖君山岛","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐君山银针鸡片，人均68元，补充体力。","addr":"君山岛上","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"圣安寺","description":"午后游览圣安寺，古塔与湖景同框。","addr":"岳阳市南湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"岳阳楼","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"岳阳楼是岳阳楼洞庭湖最有代表性的看点，洞庭天下水岳阳天下楼，背岳阳楼记免票。攻略把它排进主线，时间留得最足。","notice":"洞庭天下水岳阳天下楼，背岳阳楼记免票。这个点位上午光线最好。","durationMinutes":90,"addr":"岳阳市岳阳楼区"},{"spotId":"S2","name":"君山岛","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"君山岛是岳阳楼洞庭湖最有代表性的看点，湘妃竹与银针茶的故乡。攻略把它排进主线，时间留得最足。","notice":"湘妃竹与银针茶的故乡。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"洞庭湖君山岛"},{"spotId":"S3","name":"圣安寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"圣安寺是岳阳楼洞庭湖最有代表性的看点，古塔与湖景同框。攻略把它排进主线，时间留得最足。","notice":"古塔与湖景同框。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"岳阳市南湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"洞庭鱼头（人均78元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是洞庭鱼头，巴陵全鱼席本地人都认这家，点单照攻略不踩雷。","addr":"岳阳楼景区旁"},{"title":"君山银针鸡片（人均68元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是君山银针鸡片，茶宴馆本地人都认这家，点单照攻略不踩雷。","addr":"君山岛上"},{"title":"岳阳虾饼（人均10元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是岳阳虾饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"汴河街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('元阳哈尼梯田纯攻略·周末版2','guide','红河 · 元阳哈尼梯田','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',1990,1000,1,'多依树梯田 / 老虎嘴梯田 / 箐口哈尼民俗村 —— 纯攻略助你玩透元阳哈尼梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「元阳哈尼梯田」三日深度游——古村落。元阳红米营养丰富。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 红河"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往红河，抵达后办理入住、熟悉周边环境。","addr":"红河市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"多依树梯田","description":"下午首站多依树梯田，调整状态进入旅行节奏，日出云海最佳观赏点，提前1小时占位。","addr":"元阳县新街镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游红河一带氛围拉满，晚餐哈尼梯田红米人均35元。","addr":"多依树村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"老虎嘴梯田","description":"全天主景点老虎嘴梯田，日落时梯田变金色。","addr":"元阳县攀枝花乡","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐梯田鱼（人均58元），早点休息。","addr":"箐口村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"箐口哈尼民俗村","description":"收官箐口哈尼民俗村，蘑菇房与梯田同框。","addr":"元阳县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐竹筒鸡后集合返程，三日旅程圆满。","addr":"新街镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"多依树梯田","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"多依树梯田是元阳哈尼梯田最有代表性的看点，日出云海最佳观赏点，提前1小时占位。攻略把它排进主线，时间留得最足。","notice":"日出云海最佳观赏点，提前1小时占位。这个点位上午光线最好。","durationMinutes":120,"addr":"元阳县新街镇"},{"spotId":"S2","name":"老虎嘴梯田","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"老虎嘴梯田是元阳哈尼梯田最有代表性的看点，日落时梯田变金色。攻略把它排进主线，时间留得最足。","notice":"日落时梯田变金色。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"元阳县攀枝花乡"},{"spotId":"S3","name":"箐口哈尼民俗村","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"箐口哈尼民俗村是元阳哈尼梯田最有代表性的看点，蘑菇房与梯田同框。攻略把它排进主线，时间留得最足。","notice":"蘑菇房与梯田同框。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"元阳县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"哈尼梯田红米（人均35元）","description":"红河 · 元阳哈尼梯田的招牌是哈尼梯田红米，农家餐厅本地人都认这家，点单照攻略不踩雷。","addr":"多依树村"},{"title":"梯田鱼（人均58元）","description":"红河 · 元阳哈尼梯田的招牌是梯田鱼，村中渔家本地人都认这家，点单照攻略不踩雷。","addr":"箐口村"},{"title":"竹筒鸡（人均68元）","description":"红河 · 元阳哈尼梯田的招牌是竹筒鸡，哈尼农家本地人都认这家，点单照攻略不踩雷。","addr":"新街镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","相机或运动相机","身份证件与手机充电宝","轻便雨衣或折叠伞","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 红河 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('四姑娘山纯攻略·亲子篇2','guide','阿坝 · 四姑娘山','mountain','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,2,'双桥沟 / 长坪沟 / 猫鼻梁 —— 纯攻略助你玩透四姑娘山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「四姑娘山」两日慢旅行——山岳。四姑娘山沙棘汁酸爽提神。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达四姑娘山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"双桥沟","description":"抵达后首游双桥沟，坐观光车看雪山峡谷，最省力。","addr":"四姑娘山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏式火锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"长坪沟","description":"早起人少，长坪沟精华时段，木栈道进山，幺妹峰侧面。","addr":"四姑娘山镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牦牛肉干，人均45元，补充体力。","addr":"镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"猫鼻梁","description":"午后游览猫鼻梁，四峰全景最佳机位。","addr":"去四姑娘山路途","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"双桥沟","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"双桥沟是四姑娘山最有代表性的看点，坐观光车看雪山峡谷，最省力。攻略把它排进主线，时间留得最足。","notice":"坐观光车看雪山峡谷，最省力。这个点位上午光线最好。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S2","name":"长坪沟","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"长坪沟是四姑娘山最有代表性的看点，木栈道进山，幺妹峰侧面。攻略把它排进主线，时间留得最足。","notice":"木栈道进山，幺妹峰侧面。这个点位上午光线最好。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S3","name":"猫鼻梁","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"猫鼻梁是四姑娘山最有代表性的看点，四峰全景最佳机位。攻略把它排进主线，时间留得最足。","notice":"四峰全景最佳机位。周边有休息区与补给点，随时停留。","durationMinutes":30,"addr":"去四姑娘山路途"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏式火锅（人均78元）","description":"阿坝 · 四姑娘山的招牌是藏式火锅，日隆镇餐馆本地人都认这家，点单照攻略不踩雷。","addr":"四姑娘山镇"},{"title":"牦牛肉干（人均45元）","description":"阿坝 · 四姑娘山的招牌是牦牛肉干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"镇主街"},{"title":"酥油茶（人均15元）","description":"阿坝 · 四姑娘山的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"长坪沟口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机","轻便雨衣或折叠伞","身份证件与手机充电宝","防晒霜与遮阳帽","保温水杯与少量现金","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 阿坝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌蒙大草原纯攻略·摄影机位2','guide','六盘水 · 乌蒙大草原','camp','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',2500,1300,10,'乌蒙大草原 / 野玉海 / 娘娘山 —— 纯攻略助你玩透乌蒙大草原精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「乌蒙大草原」三日深度游——露营地。六盘水刺梨维C之王。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 六盘水"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往六盘水，抵达后办理入住、熟悉周边环境。","addr":"六盘水市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"乌蒙大草原","description":"下午首站乌蒙大草原，调整状态进入旅行节奏，云上花海佛光，露营星空。","addr":"六盘水市盘州市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游六盘水一带氛围拉满，晚餐水城烙锅人均45元。","addr":"水城区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"野玉海","description":"全天主景点野玉海，海坪彝族小镇与观光小火车。","addr":"水城区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊肉粉（人均15元），早点休息。","addr":"盘州市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"娘娘山","description":"收官娘娘山，高原湿地与温泉。","addr":"盘州市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐刺梨汁后集合返程，三日旅程圆满。","addr":"全区通用","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"乌蒙大草原","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"乌蒙大草原是乌蒙大草原最有代表性的看点，云上花海佛光，露营星空。攻略把它排进主线，时间留得最足。","notice":"云上花海佛光，露营星空。这个点位上午光线最好。","durationMinutes":180,"addr":"六盘水市盘州市"},{"spotId":"S2","name":"野玉海","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"野玉海是乌蒙大草原最有代表性的看点，海坪彝族小镇与观光小火车。攻略把它排进主线，时间留得最足。","notice":"海坪彝族小镇与观光小火车。这个点位上午光线最好。","durationMinutes":150,"addr":"水城区"},{"spotId":"S3","name":"娘娘山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"娘娘山是乌蒙大草原最有代表性的看点，高原湿地与温泉。攻略把它排进主线，时间留得最足。","notice":"高原湿地与温泉。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"盘州市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水城烙锅（人均45元）","description":"六盘水 · 乌蒙大草原的招牌是水城烙锅，烙锅一条街本地人都认这家，点单照攻略不踩雷。","addr":"水城区"},{"title":"羊肉粉（人均15元）","description":"六盘水 · 乌蒙大草原的招牌是羊肉粉，元坤羊肉粉本地人都认这家，点单照攻略不踩雷。","addr":"盘州市"},{"title":"刺梨汁（人均10元）","description":"六盘水 · 乌蒙大草原的招牌是刺梨汁，维C宝饮品本地人都认这家，点单照攻略不踩雷。","addr":"全区通用"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机","少量零食补给","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","防晒霜与遮阳帽"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 六盘水 的交通方便吗？","推荐先到 六盘水，再打车或景区直通车前往核心景区；自驾导航直接搜乌蒙大草原即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武夷山纯攻略·美食清单2','guide','南平 · 武夷山','mountain','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',1990,1000,2,'九曲溪竹筏 / 天游峰 / 大红袍景区 —— 纯攻略助你玩透武夷山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武夷山」两日慢旅行——山岳。正岩大红袍认准九龙窠。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 南平"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南平","description":"集合出发，大巴直达武夷山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"九曲溪竹筏","description":"抵达后首游九曲溪竹筏，90分钟漂流过九曲十八弯。","addr":"武夷山市星村镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐武夷山熏鹅（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天游峰","description":"早起人少，天游峰精华时段，闽山第一峰，云窝上看溪湾。","addr":"武夷山风景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐紫溪粉，人均15元，补充体力。","addr":"三姑街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大红袍景区","description":"午后游览大红袍景区，母树大红袍，岩谷花香步道。","addr":"武夷山九龙窠","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"九曲溪竹筏","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"九曲溪竹筏是武夷山最有代表性的看点，90分钟漂流过九曲十八弯。攻略把它排进主线，时间留得最足。","notice":"90分钟漂流过九曲十八弯。这个点位上午光线最好。","durationMinutes":180,"addr":"武夷山市星村镇"},{"spotId":"S2","name":"天游峰","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"天游峰是武夷山最有代表性的看点，闽山第一峰，云窝上看溪湾。攻略把它排进主线，时间留得最足。","notice":"闽山第一峰，云窝上看溪湾。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"武夷山风景区"},{"spotId":"S3","name":"大红袍景区","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"大红袍景区是武夷山最有代表性的看点，母树大红袍，岩谷花香步道。攻略把它排进主线，时间留得最足。","notice":"母树大红袍，岩谷花香步道。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"武夷山九龙窠"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"武夷山熏鹅（人均48元）","description":"南平 · 武夷山的招牌是武夷山熏鹅，岚谷熏鹅店本地人都认这家，点单照攻略不踩雷。","addr":"度假区"},{"title":"紫溪粉（人均15元）","description":"南平 · 武夷山的招牌是紫溪粉，小吃店本地人都认这家，点单照攻略不踩雷。","addr":"三姑街"},{"title":"文公菜（人均58元）","description":"南平 · 武夷山的招牌是文公菜，朱子家宴本地人都认这家，点单照攻略不踩雷。","addr":"武夷宫旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","换洗衣物与外套（早晚温差）","保温水杯与少量现金","常用药品（肠胃药/创可贴）","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 南平 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('莫干山纯攻略·自由行手册2','guide','湖州 · 莫干山','village','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',990,500,1,'莫干山风景区 / 庾村文化市集 / 下渚湖湿地公园 —— 纯攻略助你玩透莫干山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「莫干山」三日深度游——古村落。莫干山黄芽茶清雅。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 湖州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往湖州，抵达后办理入住、熟悉周边环境。","addr":"湖州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫干山风景区","description":"下午首站莫干山风景区，调整状态进入旅行节奏，民国别墅群与竹海，剑池飞瀑。","addr":"湖州市德清县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游湖州一带氛围拉满，晚餐笋干烧肉人均58元。","addr":"莫干山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"庾村文化市集","description":"全天主景点庾村文化市集，文创小铺与骑行路线。","addr":"德清县莫干山镇","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐竹林土鸡煲（人均88元），早点休息。","addr":"劳岭村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"下渚湖湿地公园","description":"收官下渚湖湿地公园，朱鹮栖息地，芦苇迷宫。","addr":"德清县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐德清醉鱼后集合返程，三日旅程圆满。","addr":"下渚湖","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫干山风景区","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"莫干山风景区是莫干山最有代表性的看点，民国别墅群与竹海，剑池飞瀑。攻略把它排进主线，时间留得最足。","notice":"民国别墅群与竹海，剑池飞瀑。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"湖州市德清县"},{"spotId":"S2","name":"庾村文化市集","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"庾村文化市集是莫干山最有代表性的看点，文创小铺与骑行路线。攻略把它排进主线，时间留得最足。","notice":"文创小铺与骑行路线。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"德清县莫干山镇"},{"spotId":"S3","name":"下渚湖湿地公园","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"下渚湖湿地公园是莫干山最有代表性的看点，朱鹮栖息地，芦苇迷宫。攻略把它排进主线，时间留得最足。","notice":"朱鹮栖息地，芦苇迷宫。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"德清县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"笋干烧肉（人均58元）","description":"湖州 · 莫干山的招牌是笋干烧肉，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"莫干山镇"},{"title":"竹林土鸡煲（人均88元）","description":"湖州 · 莫干山的招牌是竹林土鸡煲，民宿餐厅本地人都认这家，点单照攻略不踩雷。","addr":"劳岭村"},{"title":"德清醉鱼（人均38元）","description":"湖州 · 莫干山的招牌是德清醉鱼，水产馆本地人都认这家，点单照攻略不踩雷。","addr":"下渚湖"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","少量零食补给","保温水杯与少量现金","轻便雨衣或折叠伞","墨镜与拍照道具","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 湖州 的交通方便吗？","推荐先到 湖州，再打车或景区直通车前往核心景区；自驾导航直接搜莫干山即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九华山纯攻略·省钱玩法2','guide','池州 · 九华山','mountain','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',2990,1600,2,'肉身宝殿 / 百岁宫 / 花台栈道 —— 纯攻略助你玩透九华山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九华山」两日慢旅行——山岳。九华黄精是养生佳品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 池州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴池州","description":"集合出发，大巴直达九华山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"肉身宝殿","description":"抵达后首游肉身宝殿，地藏菩萨道场核心，99米地藏圣像。","addr":"池州市青阳县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐九华素斋（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"百岁宫","description":"早起人少，百岁宫精华时段，缆车直达，天然肉身佛。","addr":"九华街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐石耳炖鸡，人均78元，补充体力。","addr":"柯村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"花台栈道","description":"午后游览花台栈道，云海佛光频出。","addr":"九华山高空栈道","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"肉身宝殿","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"肉身宝殿是九华山最有代表性的看点，地藏菩萨道场核心，99米地藏圣像。攻略把它排进主线，时间留得最足。","notice":"地藏菩萨道场核心，99米地藏圣像。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"池州市青阳县"},{"spotId":"S2","name":"百岁宫","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"百岁宫是九华山最有代表性的看点，缆车直达，天然肉身佛。攻略把它排进主线，时间留得最足。","notice":"缆车直达，天然肉身佛。这个点位上午光线最好。","durationMinutes":90,"addr":"九华街"},{"spotId":"S3","name":"花台栈道","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"花台栈道是九华山最有代表性的看点，云海佛光频出。攻略把它排进主线，时间留得最足。","notice":"云海佛光频出。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"九华山高空栈道"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"九华素斋（人均38元）","description":"池州 · 九华山的招牌是九华素斋，化城寺素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"九华街"},{"title":"石耳炖鸡（人均78元）","description":"池州 · 九华山的招牌是石耳炖鸡，山间农家本地人都认这家，点单照攻略不踩雷。","addr":"柯村"},{"title":"黄精茶（人均30元）","description":"池州 · 九华山的招牌是黄精茶，特产店本地人都认这家，点单照攻略不踩雷。","addr":"九华新街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","少量零食补给","保温水杯与少量现金","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 池州 的交通方便吗？","推荐先到 池州，再打车或景区直通车前往核心景区；自驾导航直接搜九华山即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云台山纯攻略·避坑版2','guide','焦作 · 云台山','water','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',990,500,2,'红石峡 / 茱萸峰 / 潭瀑峡 —— 纯攻略助你玩透云台山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「云台山」三日深度游——水景。铁棍山药焦作温县最好。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 焦作"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往焦作，抵达后办理入住、熟悉周边环境。","addr":"焦作市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"红石峡","description":"下午首站红石峡，调整状态进入旅行节奏，红岩碧水盆景峡谷，人再多也值。","addr":"焦作市修武县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游焦作一带氛围拉满，晚餐驴肉面人均28元。","addr":"云台山岸上镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"茱萸峰","description":"全天主景点茱萸峰，王维遥知兄弟登高处。","addr":"云台山主峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐山药炖排骨（人均58元），早点休息。","addr":"修武县城","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"潭瀑峡","description":"收官潭瀑峡，三步一泉五步一瀑。","addr":"云台山","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐松花蛋后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"红石峡","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"红石峡是云台山最有代表性的看点，红岩碧水盆景峡谷，人再多也值。攻略把它排进主线，时间留得最足。","notice":"红岩碧水盆景峡谷，人再多也值。这个点位上午光线最好。","durationMinutes":180,"addr":"焦作市修武县"},{"spotId":"S2","name":"茱萸峰","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"茱萸峰是云台山最有代表性的看点，王维遥知兄弟登高处。攻略把它排进主线，时间留得最足。","notice":"王维遥知兄弟登高处。这个点位上午光线最好。","durationMinutes":180,"addr":"云台山主峰"},{"spotId":"S3","name":"潭瀑峡","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"潭瀑峡是云台山最有代表性的看点，三步一泉五步一瀑。攻略把它排进主线，时间留得最足。","notice":"三步一泉五步一瀑。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"云台山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉面（人均28元）","description":"焦作 · 云台山的招牌是驴肉面，修武驴肉馆本地人都认这家，点单照攻略不踩雷。","addr":"云台山岸上镇"},{"title":"山药炖排骨（人均58元）","description":"焦作 · 云台山的招牌是山药炖排骨，怀山药宴本地人都认这家，点单照攻略不踩雷。","addr":"修武县城"},{"title":"松花蛋（人均20元）","description":"焦作 · 云台山的招牌是松花蛋，特产店本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","墨镜与拍照道具","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["到达 焦作 的交通方便吗？","推荐先到 焦作，再打车或景区直通车前往核心景区；自驾导航直接搜云台山即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五台山纯攻略·深度指南2','guide','忻州 · 五台山','mountain','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1500,800,2,'五爷庙 / 黛螺顶 / 显通寺 —— 纯攻略助你玩透五台山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「五台山」两日慢旅行——山岳。五台山台蘑干货珍贵。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 忻州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴忻州","description":"集合出发，大巴直达五台山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"五爷庙","description":"抵达后首游五爷庙，香火最旺许愿灵验，早去。","addr":"忻州市五台县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐台蘑炖山鸡（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"黛螺顶","description":"早起人少，黛螺顶精华时段，小朝台1080级台阶。","addr":"五台山台怀镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐莜面窝窝，人均22元，补充体力。","addr":"五台山镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"显通寺","description":"午后游览显通寺，五台山开山寺，铜殿铜塔。","addr":"台怀镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"五爷庙","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"五爷庙是五台山最有代表性的看点，香火最旺许愿灵验，早去。攻略把它排进主线，时间留得最足。","notice":"香火最旺许愿灵验，早去。这个点位上午光线最好。","durationMinutes":90,"addr":"忻州市五台县"},{"spotId":"S2","name":"黛螺顶","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"黛螺顶是五台山最有代表性的看点，小朝台1080级台阶。攻略把它排进主线，时间留得最足。","notice":"小朝台1080级台阶。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"五台山台怀镇"},{"spotId":"S3","name":"显通寺","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"显通寺是五台山最有代表性的看点，五台山开山寺，铜殿铜塔。攻略把它排进主线，时间留得最足。","notice":"五台山开山寺，铜殿铜塔。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"台怀镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"台蘑炖山鸡（人均88元）","description":"忻州 · 五台山的招牌是台蘑炖山鸡，山珍馆本地人都认这家，点单照攻略不踩雷。","addr":"台怀镇"},{"title":"莜面窝窝（人均22元）","description":"忻州 · 五台山的招牌是莜面窝窝，农家菜本地人都认这家，点单照攻略不踩雷。","addr":"五台山镇"},{"title":"素斋（人均28元）","description":"忻州 · 五台山的招牌是素斋，塔院寺素斋本地人都认这家，点单照攻略不踩雷。","addr":"塔院寺旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙面陈家祠纯攻略·周末版2','guide','广州 · 沙面陈家祠','food','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',990,500,3,'陈家祠 / 沙面岛 / 永庆坊 —— 纯攻略助你玩透沙面陈家祠精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「沙面陈家祠」三日深度游——美食。广式腊味礼盒最体面。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 广州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往广州，抵达后办理入住、熟悉周边环境。","addr":"广州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"陈家祠","description":"下午首站陈家祠，调整状态进入旅行节奏，岭南建筑木雕巅峰。","addr":"广州市荔湾区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游广州一带氛围拉满，晚餐肠粉人均15元。","addr":"上九路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"沙面岛","description":"全天主景点沙面岛，欧陆建筑群，拍照圣地。","addr":"荔湾区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐虾饺（人均28元），早点休息。","addr":"第十甫路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"永庆坊","description":"收官永庆坊，西关骑楼与粤剧艺术博物馆。","addr":"恩宁路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐双皮奶后集合返程，三日旅程圆满。","addr":"第十甫路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"陈家祠","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"陈家祠是沙面陈家祠最有代表性的看点，岭南建筑木雕巅峰。攻略把它排进主线，时间留得最足。","notice":"岭南建筑木雕巅峰。这个点位上午光线最好。","durationMinutes":90,"addr":"广州市荔湾区"},{"spotId":"S2","name":"沙面岛","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"沙面岛是沙面陈家祠最有代表性的看点，欧陆建筑群，拍照圣地。攻略把它排进主线，时间留得最足。","notice":"欧陆建筑群，拍照圣地。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"荔湾区"},{"spotId":"S3","name":"永庆坊","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"永庆坊是沙面陈家祠最有代表性的看点，西关骑楼与粤剧艺术博物馆。攻略把它排进主线，时间留得最足。","notice":"西关骑楼与粤剧艺术博物馆。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"恩宁路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肠粉（人均15元）","description":"广州 · 沙面陈家祠的招牌是肠粉，银记肠粉本地人都认这家，点单照攻略不踩雷。","addr":"上九路"},{"title":"虾饺（人均28元）","description":"广州 · 沙面陈家祠的招牌是虾饺，陶陶居本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"},{"title":"双皮奶（人均15元）","description":"广州 · 沙面陈家祠的招牌是双皮奶，南信牛奶甜品本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","相机或运动相机","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","少量零食补给","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 广州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武隆天坑纯攻略·亲子篇2','guide','武隆 · 武隆天坑','adventure','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',1990,1000,9,'天生三桥 / 仙女山 / 龙水峡地缝 —— 纯攻略助你玩透武隆天坑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武隆天坑」两日慢旅行——探险地。武隆羊角豆干麻辣够味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 武隆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴武隆","description":"集合出发，大巴直达武隆天坑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"天生三桥","description":"抵达后首游天生三桥，变形金刚取景地，天福官驿。","addr":"武隆区仙女山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐碗碗羊肉（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"仙女山","description":"早起人少，仙女山精华时段，南国第一牧原，草原骑马。","addr":"武隆区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐江口鱼，人均58元，补充体力。","addr":"江口镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙水峡地缝","description":"午后游览龙水峡地缝，80米深地缝一线天光。","addr":"仙女山镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"天生三桥","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"天生三桥是武隆天坑最有代表性的看点，变形金刚取景地，天福官驿。攻略把它排进主线，时间留得最足。","notice":"变形金刚取景地，天福官驿。这个点位上午光线最好。","durationMinutes":180,"addr":"武隆区仙女山镇"},{"spotId":"S2","name":"仙女山","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"仙女山是武隆天坑最有代表性的看点，南国第一牧原，草原骑马。攻略把它排进主线，时间留得最足。","notice":"南国第一牧原，草原骑马。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"武隆区"},{"spotId":"S3","name":"龙水峡地缝","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"龙水峡地缝是武隆天坑最有代表性的看点，80米深地缝一线天光。攻略把它排进主线，时间留得最足。","notice":"80米深地缝一线天光。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"仙女山镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"碗碗羊肉（人均38元）","description":"武隆 · 武隆天坑的招牌是碗碗羊肉，武隆碗碗羊肉本地人都认这家，点单照攻略不踩雷。","addr":"仙女山镇"},{"title":"江口鱼（人均58元）","description":"武隆 · 武隆天坑的招牌是江口鱼，乌江鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"江口镇"},{"title":"羊角豆干（人均15元）","description":"武隆 · 武隆天坑的招牌是羊角豆干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"武隆城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","常用药品（肠胃药/创可贴）","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["到达 武隆 的交通方便吗？","推荐先到 武隆，再打车或景区直通车前往核心景区；自驾导航直接搜武隆天坑即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('天山天池纯攻略·摄影机位2','guide','昌吉 · 天山天池','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',2500,1300,2,'天山天池 / 马牙山 / 西小天池 —— 纯攻略助你玩透天山天池精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「天山天池」三日深度游——山岳。天山雪莲泡酒有讲究。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 昌吉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往昌吉，抵达后办理入住、熟悉周边环境。","addr":"昌吉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"天山天池","description":"下午首站天山天池，调整状态进入旅行节奏，博格达峰雪影与瑶池传说。","addr":"阜康市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游昌吉一带氛围拉满，晚餐新疆大盘鸡人均68元。","addr":"阜康市","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"马牙山","description":"全天主景点马牙山，石林与云海，索道直达。","addr":"天池西侧","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐馕坑肉（人均25元），早点休息。","addr":"天池镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"西小天池","description":"收官西小天池，飞龙潭瀑布。","addr":"天池盘山路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸奶粽子后集合返程，三日旅程圆满。","addr":"阜康夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"天山天池","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"天山天池是天山天池最有代表性的看点，博格达峰雪影与瑶池传说。攻略把它排进主线，时间留得最足。","notice":"博格达峰雪影与瑶池传说。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"阜康市"},{"spotId":"S2","name":"马牙山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"马牙山是天山天池最有代表性的看点，石林与云海，索道直达。攻略把它排进主线，时间留得最足。","notice":"石林与云海，索道直达。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"天池西侧"},{"spotId":"S3","name":"西小天池","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"西小天池是天山天池最有代表性的看点，飞龙潭瀑布。攻略把它排进主线，时间留得最足。","notice":"飞龙潭瀑布。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"天池盘山路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新疆大盘鸡（人均68元）","description":"昌吉 · 天山天池的招牌是新疆大盘鸡，血站大盘鸡本地人都认这家，点单照攻略不踩雷。","addr":"阜康市"},{"title":"馕坑肉（人均25元）","description":"昌吉 · 天山天池的招牌是馕坑肉，馕王本地人都认这家，点单照攻略不踩雷。","addr":"天池镇"},{"title":"酸奶粽子（人均12元）","description":"昌吉 · 天山天池的招牌是酸奶粽子，夜市甜品本地人都认这家，点单照攻略不踩雷。","addr":"阜康夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","轻便雨衣或折叠伞","相机或运动相机","少量零食补给","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","保温水杯与少量现金","换洗衣物与外套（早晚温差）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 昌吉，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('八达岭长城纯攻略·美食清单2','guide','延庆 · 八达岭长城','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1500,800,7,'八达岭长城 / 明十三陵 / 居庸关花海 —— 纯攻略助你玩透八达岭长城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「八达岭长城」两日慢旅行——人文。北京果脯礼盒送长辈。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"北京 · 延庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延庆","description":"集合出发，大巴直达八达岭长城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"八达岭长城","description":"抵达后首游八达岭长城，好汉坡北八楼，缆车上下。","addr":"延庆区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐春饼宴（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"明十三陵","description":"早起人少，明十三陵精华时段，定陵地宫探秘。","addr":"昌平区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐火盆锅豆腐宴，人均48元，补充体力。","addr":"八达岭镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"居庸关花海","description":"午后游览居庸关花海，开往春天的列车。","addr":"昌平区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"八达岭长城","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"八达岭长城是八达岭长城最有代表性的看点，好汉坡北八楼，缆车上下。攻略把它排进主线，时间留得最足。","notice":"好汉坡北八楼，缆车上下。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"延庆区"},{"spotId":"S2","name":"明十三陵","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"明十三陵是八达岭长城最有代表性的看点，定陵地宫探秘。攻略把它排进主线，时间留得最足。","notice":"定陵地宫探秘。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"昌平区"},{"spotId":"S3","name":"居庸关花海","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"居庸关花海是八达岭长城最有代表性的看点，开往春天的列车。攻略把它排进主线，时间留得最足。","notice":"开往春天的列车。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"昌平区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"春饼宴（人均38元）","description":"延庆 · 八达岭长城的招牌是春饼宴，柳沟村豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"延庆柳沟"},{"title":"火盆锅豆腐宴（人均48元）","description":"延庆 · 八达岭长城的招牌是火盆锅豆腐宴，农家院本地人都认这家，点单照攻略不踩雷。","addr":"八达岭镇"},{"title":"玫瑰饼（人均15元）","description":"延庆 · 八达岭长城的招牌是玫瑰饼，妙峰山糕点本地人都认这家，点单照攻略不踩雷。","addr":"昌平"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","少量零食补给","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","相机或运动相机","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 延庆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('庐山纯攻略·自由行手册2','guide','九江 · 庐山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',990,500,2,'锦绣谷 / 三叠泉 / 如琴湖花径 —— 纯攻略助你玩透庐山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「庐山」三日深度游——山岳。庐山云雾茶记得认准原产地标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 九江"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往九江，抵达后办理入住、熟悉周边环境。","addr":"九江市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"锦绣谷","description":"下午首站锦绣谷，调整状态进入旅行节奏，云雾多发地段，下午常被云海包裹。","addr":"庐山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游九江一带氛围拉满，晚餐庐山三石宴人均128元。","addr":"牯岭镇河西路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"三叠泉","description":"全天主景点三叠泉，不到三叠泉不算庐山客，往返台阶多。","addr":"庐山东南麓","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐茶饼（人均12元），早点休息。","addr":"牯岭镇正街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"如琴湖花径","description":"收官如琴湖花径，清晨人少出片，环湖半小时。","addr":"牯岭镇西侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐石耳炖鸡汤后集合返程，三日旅程圆满。","addr":"如琴湖旁农家","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"锦绣谷","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"锦绣谷是庐山最有代表性的看点，云雾多发地段，下午常被云海包裹。攻略把它排进主线，时间留得最足。","notice":"云雾多发地段，下午常被云海包裹。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"庐山风景区"},{"spotId":"S2","name":"三叠泉","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"三叠泉是庐山最有代表性的看点，不到三叠泉不算庐山客，往返台阶多。攻略把它排进主线，时间留得最足。","notice":"不到三叠泉不算庐山客，往返台阶多。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"庐山东南麓"},{"spotId":"S3","name":"如琴湖花径","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"如琴湖花径是庐山最有代表性的看点，清晨人少出片，环湖半小时。攻略把它排进主线，时间留得最足。","notice":"清晨人少出片，环湖半小时。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"牯岭镇西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"庐山三石宴（人均128元）","description":"九江 · 庐山的招牌是庐山三石宴，牯岭镇饭馆本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇河西路"},{"title":"茶饼（人均12元）","description":"九江 · 庐山的招牌是茶饼，云中街区小店本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇正街"},{"title":"石耳炖鸡汤（人均98元）","description":"九江 · 庐山的招牌是石耳炖鸡汤，山中食府本地人都认这家，点单照攻略不踩雷。","addr":"如琴湖旁农家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","身份证件与手机充电宝","保温水杯与少量现金","相机或运动相机","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","防晒霜与遮阳帽"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 九江 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('通天岩郁孤台纯攻略·省钱玩法2','guide','赣州 · 通天岩郁孤台','red','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1990,1000,7,'通天岩 / 郁孤台 / 关西新围 —— 纯攻略助你玩透通天岩郁孤台精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「通天岩郁孤台」两日慢旅行——人文。赣南脐橙11月最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 赣州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴赣州","description":"集合出发，大巴直达通天岩郁孤台，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"通天岩","description":"抵达后首游通天岩，江南最大石窟群，丹岩丹霞。","addr":"赣州市章贡区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐赣南小炒鱼（人均42元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"郁孤台","description":"早起人少，郁孤台精华时段，辛弃疾词中圣地，宋城墙。","addr":"章贡区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐艾米果，人均10元，补充体力。","addr":"郁孤台街区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"关西新围","description":"午后游览关西新围，东方古堡围屋。","addr":"龙南市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"通天岩","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"通天岩是通天岩郁孤台最有代表性的看点，江南最大石窟群，丹岩丹霞。攻略把它排进主线，时间留得最足。","notice":"江南最大石窟群，丹岩丹霞。这个点位上午光线最好。","durationMinutes":150,"addr":"赣州市章贡区"},{"spotId":"S2","name":"郁孤台","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"郁孤台是通天岩郁孤台最有代表性的看点，辛弃疾词中圣地，宋城墙。攻略把它排进主线，时间留得最足。","notice":"辛弃疾词中圣地，宋城墙。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"章贡区"},{"spotId":"S3","name":"关西新围","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"关西新围是通天岩郁孤台最有代表性的看点，东方古堡围屋。攻略把它排进主线，时间留得最足。","notice":"东方古堡围屋。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙南市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"赣南小炒鱼（人均42元）","description":"赣州 · 通天岩郁孤台的招牌是赣南小炒鱼，赣州客家菜本地人都认这家，点单照攻略不踩雷。","addr":"章贡区"},{"title":"艾米果（人均10元）","description":"赣州 · 通天岩郁孤台的招牌是艾米果，街头点心本地人都认这家，点单照攻略不踩雷。","addr":"郁孤台街区"},{"title":"黄元米果（人均18元）","description":"赣州 · 通天岩郁孤台的招牌是黄元米果，赣南农家本地人都认这家，点单照攻略不踩雷。","addr":"龙南市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","身份证件与手机充电宝","墨镜与拍照道具","相机或运动相机","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('桃花源纯攻略·避坑版2','guide','常德 · 桃花源','village','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,1,'桃花源古镇 / 桃源山 / 五柳湖 —— 纯攻略助你玩透桃花源精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「桃花源」三日深度游——古村落。桃源大叶茶配擂茶绝了。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 常德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往常德，抵达后办理入住、熟悉周边环境。","addr":"常德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"桃花源古镇","description":"下午首站桃花源古镇，调整状态进入旅行节奏，秦溪秦谷还原桃花源记场景。","addr":"常德市桃源县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游常德一带氛围拉满，晚餐常德米粉人均18元。","addr":"桃源县漳江镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"桃源山","description":"全天主景点桃源山，水府阁俯瞰沅江。","addr":"桃花源景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐擂茶（人均35元），早点休息。","addr":"桃花源古镇内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"五柳湖","description":"收官五柳湖，落英缤纷打卡点。","addr":"桃花源核心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桃源鸡后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"桃花源古镇","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"桃花源古镇是桃花源最有代表性的看点，秦溪秦谷还原桃花源记场景。攻略把它排进主线，时间留得最足。","notice":"秦溪秦谷还原桃花源记场景。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"常德市桃源县"},{"spotId":"S2","name":"桃源山","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"桃源山是桃花源最有代表性的看点，水府阁俯瞰沅江。攻略把它排进主线，时间留得最足。","notice":"水府阁俯瞰沅江。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"桃花源景区"},{"spotId":"S3","name":"五柳湖","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"五柳湖是桃花源最有代表性的看点，落英缤纷打卡点。攻略把它排进主线，时间留得最足。","notice":"落英缤纷打卡点。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"桃花源核心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"常德米粉（人均18元）","description":"常德 · 桃花源的招牌是常德米粉，刘聋子粉馆本地人都认这家，点单照攻略不踩雷。","addr":"桃源县漳江镇"},{"title":"擂茶（人均35元）","description":"常德 · 桃花源的招牌是擂茶，秦溪擂茶馆本地人都认这家，点单照攻略不踩雷。","addr":"桃花源古镇内"},{"title":"桃源鸡（人均68元）","description":"常德 · 桃花源的招牌是桃源鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","少量零食补给","相机或运动相机","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 常德 的交通方便吗？","推荐先到 常德，再打车或景区直通车前往核心景区；自驾导航直接搜桃花源即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('普者黑纯攻略·深度指南2','guide','文山 · 普者黑','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1200,600,2,'青龙山 / 天鹅湖 / 仙人洞村 —— 纯攻略助你玩透普者黑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普者黑」两日慢旅行——水景。丘北辣椒香而不辣。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 文山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴文山","description":"集合出发，大巴直达普者黑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青龙山","description":"抵达后首游青龙山，登顶看万亩荷塘全景。","addr":"丘北县普者黑村","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐醉虾（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天鹅湖","description":"早起人少，天鹅湖精华时段，候鸟与荷塘，乘船打水仗。","addr":"普者黑景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐荷叶宴，人均68元，补充体力。","addr":"天鹅湖边","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"仙人洞村","description":"午后游览仙人洞村，撒尼人村落，民宿夜色美。","addr":"普者黑湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青龙山","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"青龙山是普者黑最有代表性的看点，登顶看万亩荷塘全景。攻略把它排进主线，时间留得最足。","notice":"登顶看万亩荷塘全景。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"丘北县普者黑村"},{"spotId":"S2","name":"天鹅湖","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"天鹅湖是普者黑最有代表性的看点，候鸟与荷塘，乘船打水仗。攻略把它排进主线，时间留得最足。","notice":"候鸟与荷塘，乘船打水仗。这个点位上午光线最好。","durationMinutes":180,"addr":"普者黑景区"},{"spotId":"S3","name":"仙人洞村","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"仙人洞村是普者黑最有代表性的看点，撒尼人村落，民宿夜色美。攻略把它排进主线，时间留得最足。","notice":"撒尼人村落，民宿夜色美。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"普者黑湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"醉虾（人均48元）","description":"文山 · 普者黑的招牌是醉虾，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"普者黑村"},{"title":"荷叶宴（人均68元）","description":"文山 · 普者黑的招牌是荷叶宴，荷香餐厅本地人都认这家，点单照攻略不踩雷。","addr":"天鹅湖边"},{"title":"丘北辣椒鸡（人均58元）","description":"文山 · 普者黑的招牌是丘北辣椒鸡，辣椒主题馆本地人都认这家，点单照攻略不踩雷。","addr":"丘北县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 文山 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 文山 的交通方便吗？","推荐先到 文山，再打车或景区直通车前往核心景区；自驾导航直接搜普者黑即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('蜀南竹海纯攻略·周末版2','guide','宜宾 · 蜀南竹海','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',990,500,1,'蜀南竹海 / 李庄古镇 / 兴文石海 —— 纯攻略助你玩透蜀南竹海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「蜀南竹海」三日深度游——古村落。竹荪竹笋干货轻便。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 宜宾"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜宾，抵达后办理入住、熟悉周边环境。","addr":"宜宾市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜀南竹海","description":"下午首站蜀南竹海，调整状态进入旅行节奏，忘忧谷翡翠长廊，竹林深处人家。","addr":"宜宾市长宁县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜宾一带氛围拉满，晚餐全竹宴人均68元。","addr":"蜀南竹海","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"李庄古镇","description":"全天主景点李庄古镇，万里长江第一古镇，抗战文化。","addr":"翠屏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐李庄白肉（人均42元），早点休息。","addr":"李庄古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"兴文石海","description":"收官兴文石海，天坑石林与僰人文化。","addr":"兴文县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐燃面后集合返程，三日旅程圆满。","addr":"宜宾市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜀南竹海","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"蜀南竹海是蜀南竹海最有代表性的看点，忘忧谷翡翠长廊，竹林深处人家。攻略把它排进主线，时间留得最足。","notice":"忘忧谷翡翠长廊，竹林深处人家。这个点位上午光线最好。","durationMinutes":240,"addr":"宜宾市长宁县"},{"spotId":"S2","name":"李庄古镇","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"李庄古镇是蜀南竹海最有代表性的看点，万里长江第一古镇，抗战文化。攻略把它排进主线，时间留得最足。","notice":"万里长江第一古镇，抗战文化。这个点位上午光线最好。","durationMinutes":150,"addr":"翠屏区"},{"spotId":"S3","name":"兴文石海","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"兴文石海是蜀南竹海最有代表性的看点，天坑石林与僰人文化。攻略把它排进主线，时间留得最足。","notice":"天坑石林与僰人文化。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"兴文县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"全竹宴（人均68元）","description":"宜宾 · 蜀南竹海的招牌是全竹宴，竹海人家本地人都认这家，点单照攻略不踩雷。","addr":"蜀南竹海"},{"title":"李庄白肉（人均42元）","description":"宜宾 · 蜀南竹海的招牌是李庄白肉，李庄老店本地人都认这家，点单照攻略不踩雷。","addr":"李庄古镇"},{"title":"燃面（人均12元）","description":"宜宾 · 蜀南竹海的招牌是燃面，刘臣街燃面本地人都认这家，点单照攻略不踩雷。","addr":"宜宾市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","相机或运动相机","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","少量零食补给","轻便雨衣或折叠伞","墨镜与拍照道具","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 宜宾 的交通方便吗？","推荐先到 宜宾，再打车或景区直通车前往核心景区；自驾导航直接搜蜀南竹海即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 宜宾，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阳朔漓江纯攻略·亲子篇2','guide','桂林 · 阳朔漓江','water','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1500,800,2,'兴坪漓江 / 遇龙河 / 西街 —— 纯攻略助你玩透阳朔漓江精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阳朔漓江」两日慢旅行——水景。阳朔金桔个大超甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴桂林","description":"集合出发，大巴直达阳朔漓江，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"兴坪漓江","description":"抵达后首游兴坪漓江，20元人民币背景，老寨山看全景。","addr":"阳朔县兴坪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐啤酒鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"遇龙河","description":"早起人少，遇龙河精华时段，竹筏漂流，工农桥日落。","addr":"阳朔县遇龙河","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐桂林米粉，人均12元，补充体力。","addr":"兴坪老街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"西街","description":"午后游览西街，老外扎堆的千年老街。","addr":"阳朔县西街","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"兴坪漓江","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"兴坪漓江是阳朔漓江最有代表性的看点，20元人民币背景，老寨山看全景。攻略把它排进主线，时间留得最足。","notice":"20元人民币背景，老寨山看全景。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"阳朔县兴坪镇"},{"spotId":"S2","name":"遇龙河","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"遇龙河是阳朔漓江最有代表性的看点，竹筏漂流，工农桥日落。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流，工农桥日落。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"阳朔县遇龙河"},{"spotId":"S3","name":"西街","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"西街是阳朔漓江最有代表性的看点，老外扎堆的千年老街。攻略把它排进主线，时间留得最足。","notice":"老外扎堆的千年老街。这个点位上午光线最好。","durationMinutes":120,"addr":"阳朔县西街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"啤酒鱼（人均68元）","description":"桂林 · 阳朔漓江的招牌是啤酒鱼，谢大姐啤酒鱼本地人都认这家，点单照攻略不踩雷。","addr":"西街口"},{"title":"桂林米粉（人均12元）","description":"桂林 · 阳朔漓江的招牌是桂林米粉，崇善米粉本地人都认这家，点单照攻略不踩雷。","addr":"兴坪老街"},{"title":"田螺酿（人均38元）","description":"桂林 · 阳朔漓江的招牌是田螺酿，阳朔农家本地人都认这家，点单照攻略不踩雷。","addr":"遇龙河边"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","墨镜与拍照道具","少量零食补给","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 桂林 的交通方便吗？","推荐先到 桂林，再打车或景区直通车前往核心景区；自驾导航直接搜阳朔漓江即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 桂林，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南靖土楼纯攻略·摄影机位2','guide','漳州 · 南靖土楼','village','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1990,1000,1,'田螺坑土楼群 / 裕昌楼 / 云水谣古镇 —— 纯攻略助你玩透南靖土楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「南靖土楼」三日深度游——古村落。土楼红茶岩韵悠长。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 漳州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往漳州，抵达后办理入住、熟悉周边环境。","addr":"漳州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"田螺坑土楼群","description":"下午首站田螺坑土楼群，调整状态进入旅行节奏，四菜一汤观景台，夜景更美。","addr":"南靖县书洋镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游漳州一带氛围拉满，晚餐土楼农家菜人均48元。","addr":"田螺坑下观景台","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"裕昌楼","description":"全天主景点裕昌楼，700年东歪西斜奇楼。","addr":"南靖县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐梅菜扣肉（人均42元），早点休息。","addr":"云水谣古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"云水谣古镇","description":"收官云水谣古镇，千年榕树与水车，电影取景地。","addr":"南靖县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糍粑后集合返程，三日旅程圆满。","addr":"裕昌楼前","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"田螺坑土楼群","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"田螺坑土楼群是南靖土楼最有代表性的看点，四菜一汤观景台，夜景更美。攻略把它排进主线，时间留得最足。","notice":"四菜一汤观景台，夜景更美。这个点位上午光线最好。","durationMinutes":120,"addr":"南靖县书洋镇"},{"spotId":"S2","name":"裕昌楼","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"裕昌楼是南靖土楼最有代表性的看点，700年东歪西斜奇楼。攻略把它排进主线，时间留得最足。","notice":"700年东歪西斜奇楼。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"南靖县"},{"spotId":"S3","name":"云水谣古镇","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"云水谣古镇是南靖土楼最有代表性的看点，千年榕树与水车，电影取景地。攻略把它排进主线，时间留得最足。","notice":"千年榕树与水车，电影取景地。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"南靖县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土楼农家菜（人均48元）","description":"漳州 · 南靖土楼的招牌是土楼农家菜，客家土菜馆本地人都认这家，点单照攻略不踩雷。","addr":"田螺坑下观景台"},{"title":"梅菜扣肉（人均42元）","description":"漳州 · 南靖土楼的招牌是梅菜扣肉，云水谣饭庄本地人都认这家，点单照攻略不踩雷。","addr":"云水谣古镇"},{"title":"糍粑（人均12元）","description":"漳州 · 南靖土楼的招牌是糍粑，土楼小吃本地人都认这家，点单照攻略不踩雷。","addr":"裕昌楼前"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","轻便雨衣或折叠伞","墨镜与拍照道具","少量零食补给","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 漳州 的交通方便吗？","推荐先到 漳州，再打车或景区直通车前往核心景区；自驾导航直接搜南靖土楼即可。"],["当地有什么必吃？","到了 漳州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('千岛湖纯攻略·美食清单2','guide','淳安 · 千岛湖','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,2,'中心湖区 / 东南湖区 / 文渊狮城 —— 纯攻略助你玩透千岛湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「千岛湖」两日慢旅行——水景。千岛湖有机鱼头认证标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 淳安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴淳安","description":"集合出发，大巴直达千岛湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中心湖区","description":"抵达后首游中心湖区，梅峰岛看千岛全景，缆车省力。","addr":"淳安县千岛湖镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐千岛湖鱼头（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"东南湖区","description":"早起人少，东南湖区精华时段，黄山尖九岛串联水道。","addr":"千岛湖","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山核桃，人均45元，补充体力。","addr":"渔街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"文渊狮城","description":"午后游览文渊狮城，水下古城复刻，夜游有戏。","addr":"姜家镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中心湖区","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"中心湖区是千岛湖最有代表性的看点，梅峰岛看千岛全景，缆车省力。攻略把它排进主线，时间留得最足。","notice":"梅峰岛看千岛全景，缆车省力。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"淳安县千岛湖镇"},{"spotId":"S2","name":"东南湖区","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"东南湖区是千岛湖最有代表性的看点，黄山尖九岛串联水道。攻略把它排进主线，时间留得最足。","notice":"黄山尖九岛串联水道。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"千岛湖"},{"spotId":"S3","name":"文渊狮城","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"文渊狮城是千岛湖最有代表性的看点，水下古城复刻，夜游有戏。攻略把它排进主线，时间留得最足。","notice":"水下古城复刻，夜游有戏。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"姜家镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"千岛湖鱼头（人均128元）","description":"淳安 · 千岛湖的招牌是千岛湖鱼头，淳牌鱼头馆本地人都认这家，点单照攻略不踩雷。","addr":"千岛湖镇新安大街"},{"title":"山核桃（人均45元）","description":"淳安 · 千岛湖的招牌是山核桃，特产店本地人都认这家，点单照攻略不踩雷。","addr":"渔街"},{"title":"艾草粿（人均10元）","description":"淳安 · 千岛湖的招牌是艾草粿，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"秀水街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 淳安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 淳安 的交通方便吗？","推荐先到 淳安，再打车或景区直通车前往核心景区；自驾导航直接搜千岛湖即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('东湖黄鹤楼纯攻略·自由行手册2','guide','武汉 · 东湖黄鹤楼','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',2500,1300,2,'黄鹤楼 / 东湖绿道 / 昙华林 —— 纯攻略助你玩透东湖黄鹤楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「东湖黄鹤楼」三日深度游——水景。武汉鸭脖真空包装好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 武汉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往武汉，抵达后办理入住、熟悉周边环境。","addr":"武汉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄鹤楼","description":"下午首站黄鹤楼，调整状态进入旅行节奏，天下江山第一楼，夜景灯光秀。","addr":"武汉市武昌区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游武汉一带氛围拉满，晚餐热干面人均12元。","addr":"户部巷","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"东湖绿道","description":"全天主景点东湖绿道，骑行湖中道，磨山樱园。","addr":"武昌区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐豆皮（人均18元），早点休息。","addr":"大智路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"昙华林","description":"收官昙华林，老教堂与文创小店。","addr":"武昌区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐武昌鱼后集合返程，三日旅程圆满。","addr":"昙华林","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄鹤楼","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"黄鹤楼是东湖黄鹤楼最有代表性的看点，天下江山第一楼，夜景灯光秀。攻略把它排进主线，时间留得最足。","notice":"天下江山第一楼，夜景灯光秀。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"武汉市武昌区"},{"spotId":"S2","name":"东湖绿道","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"东湖绿道是东湖黄鹤楼最有代表性的看点，骑行湖中道，磨山樱园。攻略把它排进主线，时间留得最足。","notice":"骑行湖中道，磨山樱园。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"武昌区"},{"spotId":"S3","name":"昙华林","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"昙华林是东湖黄鹤楼最有代表性的看点，老教堂与文创小店。攻略把它排进主线，时间留得最足。","notice":"老教堂与文创小店。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"武昌区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"热干面（人均12元）","description":"武汉 · 东湖黄鹤楼的招牌是热干面，蔡林记本地人都认这家，点单照攻略不踩雷。","addr":"户部巷"},{"title":"豆皮（人均18元）","description":"武汉 · 东湖黄鹤楼的招牌是豆皮，老通城本地人都认这家，点单照攻略不踩雷。","addr":"大智路"},{"title":"武昌鱼（人均68元）","description":"武汉 · 东湖黄鹤楼的招牌是武昌鱼，湖锦酒楼本地人都认这家，点单照攻略不踩雷。","addr":"昙华林"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","防晒霜与遮阳帽","少量零食补给","墨镜与拍照道具","轻便雨衣或折叠伞","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('少林寺纯攻略·省钱玩法2','guide','登封 · 少林寺','adventure','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,9,'少林寺常住院 / 三皇寨 / 嵩阳书院 —— 纯攻略助你玩透少林寺精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「少林寺」两日慢旅行——探险地。少林寺佛珠开光要理性。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 登封"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴登封","description":"集合出发，大巴直达少林寺，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"少林寺常住院","description":"抵达后首游少林寺常住院，塔林与武术表演，达摩面壁洞。","addr":"登封市嵩山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐少林素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三皇寨","description":"早起人少，三皇寨精华时段，悬空栈道看书册崖。","addr":"嵩山少室山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐登封焖子，人均28元，补充体力。","addr":"登封市区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"嵩阳书院","description":"午后游览嵩阳书院，四大书院之一。","addr":"登封市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"少林寺常住院","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"少林寺常住院是少林寺最有代表性的看点，塔林与武术表演，达摩面壁洞。攻略把它排进主线，时间留得最足。","notice":"塔林与武术表演，达摩面壁洞。这个点位上午光线最好。","durationMinutes":180,"addr":"登封市嵩山"},{"spotId":"S2","name":"三皇寨","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"三皇寨是少林寺最有代表性的看点，悬空栈道看书册崖。攻略把它排进主线，时间留得最足。","notice":"悬空栈道看书册崖。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"嵩山少室山"},{"spotId":"S3","name":"嵩阳书院","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"嵩阳书院是少林寺最有代表性的看点，四大书院之一。攻略把它排进主线，时间留得最足。","notice":"四大书院之一。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"登封市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"少林素斋（人均48元）","description":"登封 · 少林寺的招牌是少林素斋，寺内素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"少林寺内"},{"title":"登封焖子（人均28元）","description":"登封 · 少林寺的招牌是登封焖子，老字号本地人都认这家，点单照攻略不踩雷。","addr":"登封市区"},{"title":"焦盖烧饼（人均8元）","description":"登封 · 少林寺的招牌是焦盖烧饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"嵩阳书院旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","墨镜与拍照道具","相机或运动相机","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 登封 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云冈石窟纯攻略·避坑版2','guide','大同 · 云冈石窟','red','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',990,500,7,'云冈石窟 / 大同古城墙 / 悬空寺 —— 纯攻略助你玩透云冈石窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「云冈石窟」三日深度游——人文。大同煤雕工艺独特。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 大同"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大同，抵达后办理入住、熟悉周边环境。","addr":"大同市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"云冈石窟","description":"下午首站云冈石窟，调整状态进入旅行节奏，昙曜五窟露天大佛，北魏气象。","addr":"大同市云冈区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大同一带氛围拉满，晚餐刀削面人均15元。","addr":"大同市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大同古城墙","description":"全天主景点大同古城墙，夜景灯光，骑行城墙。","addr":"平城区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊杂粉（人均18元），早点休息。","addr":"鼓楼东街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"悬空寺","description":"收官悬空寺，峭壁上的千年古寺。","addr":"浑源县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐黄糕后集合返程，三日旅程圆满。","addr":"浑源县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"云冈石窟","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"云冈石窟是云冈石窟最有代表性的看点，昙曜五窟露天大佛，北魏气象。攻略把它排进主线，时间留得最足。","notice":"昙曜五窟露天大佛，北魏气象。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大同市云冈区"},{"spotId":"S2","name":"大同古城墙","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"大同古城墙是云冈石窟最有代表性的看点，夜景灯光，骑行城墙。攻略把它排进主线，时间留得最足。","notice":"夜景灯光，骑行城墙。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"平城区"},{"spotId":"S3","name":"悬空寺","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"悬空寺是云冈石窟最有代表性的看点，峭壁上的千年古寺。攻略把它排进主线，时间留得最足。","notice":"峭壁上的千年古寺。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"浑源县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"刀削面（人均15元）","description":"大同 · 云冈石窟的招牌是刀削面，东方削面本地人都认这家，点单照攻略不踩雷。","addr":"大同市区"},{"title":"羊杂粉（人均18元）","description":"大同 · 云冈石窟的招牌是羊杂粉，老字号羊杂本地人都认这家，点单照攻略不踩雷。","addr":"鼓楼东街"},{"title":"黄糕（人均10元）","description":"大同 · 云冈石窟的招牌是黄糕，黍面糕铺本地人都认这家，点单照攻略不踩雷。","addr":"浑源县"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","相机或运动相机"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 大同 的交通方便吗？","推荐先到 大同，再打车或景区直通车前往核心景区；自驾导航直接搜云冈石窟即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丹霞山纯攻略·深度指南2','guide','韶关 · 丹霞山','adventure','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1200,600,9,'长老峰 / 阳元石 / 翔龙湖 —— 纯攻略助你玩透丹霞山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「丹霞山」两日慢旅行——探险地。丹霞山白毛茶清甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 韶关"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴韶关","description":"集合出发，大巴直达丹霞山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"长老峰","description":"抵达后首游长老峰，丹霞地貌命名地，观日亭日出。","addr":"韶关市仁化县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐冷水猪肚（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"阳元石","description":"早起人少，阳元石精华时段，天然奇石打卡。","addr":"丹霞山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐炒山坑螺，人均38元，补充体力。","addr":"周田镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"翔龙湖","description":"午后游览翔龙湖，水上丹霞乘船。","addr":"丹霞山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"长老峰","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"长老峰是丹霞山最有代表性的看点，丹霞地貌命名地，观日亭日出。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌命名地，观日亭日出。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"韶关市仁化县"},{"spotId":"S2","name":"阳元石","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"阳元石是丹霞山最有代表性的看点，天然奇石打卡。攻略把它排进主线，时间留得最足。","notice":"天然奇石打卡。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"丹霞山"},{"spotId":"S3","name":"翔龙湖","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"翔龙湖是丹霞山最有代表性的看点，水上丹霞乘船。攻略把它排进主线，时间留得最足。","notice":"水上丹霞乘船。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"丹霞山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"冷水猪肚（人均48元）","description":"韶关 · 丹霞山的招牌是冷水猪肚，仁化农家菜本地人都认这家，点单照攻略不踩雷。","addr":"丹霞山镇"},{"title":"炒山坑螺（人均38元）","description":"韶关 · 丹霞山的招牌是炒山坑螺，山坑鱼小馆本地人都认这家，点单照攻略不踩雷。","addr":"周田镇"},{"title":"酸笋鸭（人均58元）","description":"韶关 · 丹霞山的招牌是酸笋鸭，韶关客家菜本地人都认这家，点单照攻略不踩雷。","addr":"仁化县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","少量零食补给","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","相机或运动相机","墨镜与拍照道具","身份证件与手机充电宝"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 韶关，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('敦煌莫高窟纯攻略·周末版2','guide','酒泉 · 敦煌莫高窟','red','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1990,1000,7,'莫高窟 / 鸣沙山月牙泉 / 沙洲夜市 —— 纯攻略助你玩透敦煌莫高窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「敦煌莫高窟」三日深度游——人文。敦煌夜光杯工艺品别致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 酒泉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往酒泉，抵达后办理入住、熟悉周边环境。","addr":"酒泉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫高窟","description":"下午首站莫高窟，调整状态进入旅行节奏，千年壁画宝库，A类票提前约。","addr":"敦煌市鸣沙山东麓","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游酒泉一带氛围拉满，晚餐驴肉黄面人均28元。","addr":"滨河世纪家园","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"鸣沙山月牙泉","description":"全天主景点鸣沙山月牙泉，沙漠绿洲，骆驼队与滑沙。","addr":"敦煌市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐胡羊焖饼（人均58元），早点休息。","addr":"沙洲路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙洲夜市","description":"收官沙洲夜市，驴肉黄面与夜市淘货。","addr":"敦煌市区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏皮水后集合返程，三日旅程圆满。","addr":"沙洲夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫高窟","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"莫高窟是敦煌莫高窟最有代表性的看点，千年壁画宝库，A类票提前约。攻略把它排进主线，时间留得最足。","notice":"千年壁画宝库，A类票提前约。周边有休息区与补给点，随时停留。","durationMinutes