INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳麓山橘子洲纯攻略·摄影机位2','guide','长沙 · 岳麓山橘子洲','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,2,'岳麓山 / 橘子洲头 / 太平老街 —— 纯攻略助你玩透岳麓山橘子洲精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「岳麓山橘子洲」三日深度游——山岳。长沙湘绣摆件精致好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 长沙"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往长沙，抵达后办理入住、熟悉周边环境。","addr":"长沙市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"岳麓山","description":"下午首站岳麓山，调整状态进入旅行节奏，爱晚亭秋色最美，索道下山省力。","addr":"长沙市岳麓区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游长沙一带氛围拉满，晚餐茶颜悦色人均18元。","addr":"太平老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"橘子洲头","description":"全天主景点橘子洲头，青年毛泽东雕像打卡，小火车代步。","addr":"长沙市橘子洲景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐文和友臭豆腐（人均15元），早点休息。","addr":"海信广场","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"太平老街","description":"收官太平老街，臭豆腐与糖油粑粑的主场。","addr":"长沙市天心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糖油粑粑后集合返程，三日旅程圆满。","addr":"坡子街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"岳麓山","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"岳麓山是岳麓山橘子洲最有代表性的看点，爱晚亭秋色最美，索道下山省力。攻略把它排进主线，时间留得最足。","notice":"爱晚亭秋色最美，索道下山省力。这个点位上午光线最好。","durationMinutes":180,"addr":"长沙市岳麓区"},{"spotId":"S2","name":"橘子洲头","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"橘子洲头是岳麓山橘子洲最有代表性的看点，青年毛泽东雕像打卡，小火车代步。攻略把它排进主线，时间留得最足。","notice":"青年毛泽东雕像打卡，小火车代步。这个点位上午光线最好。","durationMinutes":120,"addr":"长沙市橘子洲景区"},{"spotId":"S3","name":"太平老街","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"太平老街是岳麓山橘子洲最有代表性的看点，臭豆腐与糖油粑粑的主场。攻略把它排进主线，时间留得最足。","notice":"臭豆腐与糖油粑粑的主场。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"长沙市天心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"茶颜悦色（人均18元）","description":"长沙 · 岳麓山橘子洲的招牌是茶颜悦色，太平街店本地人都认这家，点单照攻略不踩雷。","addr":"太平老街"},{"title":"文和友臭豆腐（人均15元）","description":"长沙 · 岳麓山橘子洲的招牌是文和友臭豆腐，文和友本地人都认这家，点单照攻略不踩雷。","addr":"海信广场"},{"title":"糖油粑粑（人均8元）","description":"长沙 · 岳麓山橘子洲的招牌是糖油粑粑，李公庙糖油粑粑本地人都认这家，点单照攻略不踩雷。","addr":"坡子街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","换洗衣物与外套（早晚温差）","少量零食补给","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["几月份去 长沙 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丽江古城玉龙雪山纯攻略·美食清单2','guide','丽江 · 丽江古城玉龙雪山','mountain','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',990,500,2,'玉龙雪山 / 蓝月谷 / 丽江古城 —— 纯攻略助你玩透丽江古城玉龙雪山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「丽江古城玉龙雪山」两日慢旅行——山岳。雪山玫瑰饼是最热手信。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 丽江"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴丽江","description":"集合出发，大巴直达丽江古城玉龙雪山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"玉龙雪山","description":"抵达后首游玉龙雪山，大索道直达4506米，租羽绒服买氧气瓶。","addr":"丽江市玉龙县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐腊排骨火锅（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"蓝月谷","description":"早起人少，蓝月谷精华时段，牛奶蓝湖水，电瓶车游三湖。","addr":"玉龙雪山脚下","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐鸡豆凉粉，人均10元，补充体力。","addr":"四方街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"丽江古城","description":"午后游览丽江古城，四方街打跳，狮子山看全景。","addr":"古城区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"玉龙雪山","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"玉龙雪山是丽江古城玉龙雪山最有代表性的看点，大索道直达4506米，租羽绒服买氧气瓶。攻略把它排进主线，时间留得最足。","notice":"大索道直达4506米，租羽绒服买氧气瓶。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"丽江市玉龙县"},{"spotId":"S2","name":"蓝月谷","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"蓝月谷是丽江古城玉龙雪山最有代表性的看点，牛奶蓝湖水，电瓶车游三湖。攻略把它排进主线，时间留得最足。","notice":"牛奶蓝湖水，电瓶车游三湖。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"玉龙雪山脚下"},{"spotId":"S3","name":"丽江古城","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"丽江古城是丽江古城玉龙雪山最有代表性的看点，四方街打跳，狮子山看全景。攻略把它排进主线，时间留得最足。","notice":"四方街打跳，狮子山看全景。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"古城区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"腊排骨火锅（人均68元）","description":"丽江 · 丽江古城玉龙雪山的招牌是腊排骨火锅，象山市场本地人都认这家，点单照攻略不踩雷。","addr":"古城区象山街"},{"title":"鸡豆凉粉（人均10元）","description":"丽江 · 丽江古城玉龙雪山的招牌是鸡豆凉粉，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"四方街"},{"title":"丽江粑粑（人均12元）","description":"丽江 · 丽江古城玉龙雪山的招牌是丽江粑粑，忠义市场本地人都认这家，点单照攻略不踩雷。","addr":"忠义市场内"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","身份证件与手机充电宝","少量零食补给","保温水杯与少量现金","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 丽江 的交通方便吗？","推荐先到 丽江，再打车或景区直通车前往核心景区；自驾导航直接搜丽江古城玉龙雪山即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('稻城亚丁纯攻略·自由行手册2','guide','甘孜 · 稻城亚丁','plateau','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',990,500,2,'牛奶海 / 五色海 / 冲古寺草坪 —— 纯攻略助你玩透稻城亚丁精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「稻城亚丁」三日深度游——高原。高原反应别逞强慢慢走。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 甘孜"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往甘孜，抵达后办理入住、熟悉周边环境。","addr":"甘孜市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"牛奶海","description":"下午首站牛奶海，调整状态进入旅行节奏，海拔4600，马帮或徒步，量力而行。","addr":"稻城县香格里拉镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游甘孜一带氛围拉满，晚餐松茸炖鸡人均128元。","addr":"亚丁村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"五色海","description":"全天主景点五色海，最后一百步最陡，景色值得。","addr":"牛奶海上方","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酥油茶（人均15元），早点休息。","addr":"香格里拉镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"冲古寺草坪","description":"收官冲古寺草坪，仙乃日倒影机位。","addr":"亚丁村","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐高原土豆后集合返程，三日旅程圆满。","addr":"洛绒牛场补给点","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"牛奶海","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"牛奶海是稻城亚丁最有代表性的看点，海拔4600，马帮或徒步，量力而行。攻略把它排进主线，时间留得最足。","notice":"海拔4600，马帮或徒步，量力而行。提前10分钟到，避开旅行团大部队。","durationMinutes":360,"addr":"稻城县香格里拉镇"},{"spotId":"S2","name":"五色海","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"五色海是稻城亚丁最有代表性的看点，最后一百步最陡，景色值得。攻略把它排进主线，时间留得最足。","notice":"最后一百步最陡，景色值得。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"牛奶海上方"},{"spotId":"S3","name":"冲古寺草坪","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"冲古寺草坪是稻城亚丁最有代表性的看点，仙乃日倒影机位。攻略把它排进主线，时间留得最足。","notice":"仙乃日倒影机位。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"亚丁村"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松茸炖鸡（人均128元）","description":"甘孜 · 稻城亚丁的招牌是松茸炖鸡，亚丁村民宿本地人都认这家，点单照攻略不踩雷。","addr":"亚丁村"},{"title":"酥油茶（人均15元）","description":"甘孜 · 稻城亚丁的招牌是酥油茶，藏家小屋本地人都认这家，点单照攻略不踩雷。","addr":"香格里拉镇"},{"title":"高原土豆（人均10元）","description":"甘孜 · 稻城亚丁的招牌是高原土豆，小卖部熟食本地人都认这家，点单照攻略不踩雷。","addr":"洛绒牛场补给点"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","相机或运动相机","轻便雨衣或折叠伞","墨镜与拍照道具","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 甘孜 的交通方便吗？","推荐先到 甘孜，再打车或景区直通车前往核心景区；自驾导航直接搜稻城亚丁即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 甘孜 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('西江千户苗寨纯攻略·省钱玩法2','guide','黔东南 · 西江千户苗寨','village','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,1,'西江观景台 / 一号风雨桥 / 嘎歌古巷 —— 纯攻略助你玩透西江千户苗寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「西江千户苗寨」两日慢旅行——古村落。苗银手镯按克计价别按件。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔东南","description":"集合出发，大巴直达西江千户苗寨，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"西江观景台","description":"抵达后首游西江观景台，万家灯火夜景，天黑后1小时最佳。","addr":"雷山县西江镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐苗家酸汤鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"一号风雨桥","description":"早起人少，一号风雨桥精华时段，苗家歌舞表演互动。","addr":"西江苗寨","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐糯米饭，人均10元，补充体力。","addr":"风雨桥头","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"嘎歌古巷","description":"午后游览嘎歌古巷，非遗银饰刺绣工坊。","addr":"西江苗寨","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"西江观景台","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"西江观景台是西江千户苗寨最有代表性的看点，万家灯火夜景，天黑后1小时最佳。攻略把它排进主线，时间留得最足。","notice":"万家灯火夜景，天黑后1小时最佳。这个点位上午光线最好。","durationMinutes":120,"addr":"雷山县西江镇"},{"spotId":"S2","name":"一号风雨桥","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"一号风雨桥是西江千户苗寨最有代表性的看点，苗家歌舞表演互动。攻略把它排进主线，时间留得最足。","notice":"苗家歌舞表演互动。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"西江苗寨"},{"spotId":"S3","name":"嘎歌古巷","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"嘎歌古巷是西江千户苗寨最有代表性的看点，非遗银饰刺绣工坊。攻略把它排进主线，时间留得最足。","notice":"非遗银饰刺绣工坊。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"西江苗寨"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"苗家酸汤鱼（人均68元）","description":"黔东南 · 西江千户苗寨的招牌是苗家酸汤鱼，阿浓苗家本地人都认这家，点单照攻略不踩雷。","addr":"西江主街"},{"title":"糯米饭（人均10元）","description":"黔东南 · 西江千户苗寨的招牌是糯米饭，苗家早餐摊本地人都认这家，点单照攻略不踩雷。","addr":"风雨桥头"},{"title":"米豆腐（人均12元）","description":"黔东南 · 西江千户苗寨的招牌是米豆腐，古巷小吃本地人都认这家，点单照攻略不踩雷。","addr":"嘎歌古巷"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","保温水杯与少量现金","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 黔东南，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('德天跨国瀑布纯攻略·避坑版2','guide','崇左 · 德天跨国瀑布','water','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,2,'德天瀑布 / 明仕田园 / 53号界碑 —— 纯攻略助你玩透德天跨国瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「德天跨国瀑布」三日深度游——水景。崇左酸嘢开胃解腻。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 崇左"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往崇左，抵达后办理入住、熟悉周边环境。","addr":"崇左市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"德天瀑布","description":"下午首站德天瀑布，调整状态进入旅行节奏，亚洲第一跨国瀑布，竹筏近观。","addr":"大新县硕龙镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游崇左一带氛围拉满，晚餐越式卷粉人均12元。","addr":"硕龙镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"明仕田园","description":"全天主景点明仕田园，小桂林田园风光，骑行环线。","addr":"大新县明仕村","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐烤香猪（人均58元），早点休息。","addr":"德天游客中心","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"53号界碑","description":"收官53号界碑，中越边境打卡。","addr":"德天景区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸嘢后集合返程，三日旅程圆满。","addr":"明仕田园","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"德天瀑布","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"德天瀑布是德天跨国瀑布最有代表性的看点，亚洲第一跨国瀑布，竹筏近观。攻略把它排进主线，时间留得最足。","notice":"亚洲第一跨国瀑布，竹筏近观。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"大新县硕龙镇"},{"spotId":"S2","name":"明仕田园","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"明仕田园是德天跨国瀑布最有代表性的看点，小桂林田园风光，骑行环线。攻略把它排进主线，时间留得最足。","notice":"小桂林田园风光，骑行环线。这个点位上午光线最好。","durationMinutes":180,"addr":"大新县明仕村"},{"spotId":"S3","name":"53号界碑","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"53号界碑是德天跨国瀑布最有代表性的看点，中越边境打卡。攻略把它排进主线，时间留得最足。","notice":"中越边境打卡。这个点位上午光线最好。","durationMinutes":60,"addr":"德天景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"越式卷粉（人均12元）","description":"崇左 · 德天跨国瀑布的招牌是越式卷粉，边关小吃本地人都认这家，点单照攻略不踩雷。","addr":"硕龙镇"},{"title":"烤香猪（人均58元）","description":"崇左 · 德天跨国瀑布的招牌是烤香猪，壮乡风味本地人都认这家，点单照攻略不踩雷。","addr":"德天游客中心"},{"title":"酸嘢（人均10元）","description":"崇左 · 德天跨国瀑布的招牌是酸嘢，水果酸摊本地人都认这家，点单照攻略不踩雷。","addr":"明仕田园"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","墨镜与拍照道具","相机或运动相机","保温水杯与少量现金","身份证件与手机充电宝","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌镇西栅纯攻略·深度指南2','guide','嘉兴 · 乌镇西栅','ancient_town','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1990,1000,1,'乌镇西栅 / 木心美术馆 / 南浔古镇 —— 纯攻略助你玩透乌镇西栅精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「乌镇西栅」两日慢旅行——古镇。乌镇蓝印花布制品雅致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 嘉兴"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴嘉兴","description":"集合出发，大巴直达乌镇西栅，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乌镇西栅","description":"抵达后首游乌镇西栅，夜景封神，染坊与书院。","addr":"桐乡市乌镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红烧羊肉（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"木心美术馆","description":"早起人少，木心美术馆精华时段，建筑与展览双重享受。","addr":"西栅景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐定胜糕，人均10元，补充体力。","addr":"乌镇南栅","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南浔古镇","description":"午后游览南浔古镇，人少水乡，百间楼原生。","addr":"湖州南浔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乌镇西栅","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"乌镇西栅是乌镇西栅最有代表性的看点，夜景封神，染坊与书院。攻略把它排进主线，时间留得最足。","notice":"夜景封神，染坊与书院。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"桐乡市乌镇"},{"spotId":"S2","name":"木心美术馆","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"木心美术馆是乌镇西栅最有代表性的看点，建筑与展览双重享受。攻略把它排进主线，时间留得最足。","notice":"建筑与展览双重享受。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"西栅景区"},{"spotId":"S3","name":"南浔古镇","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"南浔古镇是乌镇西栅最有代表性的看点，人少水乡，百间楼原生。攻略把它排进主线，时间留得最足。","notice":"人少水乡，百间楼原生。这个点位上午光线最好。","durationMinutes":150,"addr":"湖州南浔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红烧羊肉（人均45元）","description":"嘉兴 · 乌镇西栅的招牌是红烧羊肉，书生羊肉面本地人都认这家，点单照攻略不踩雷。","addr":"西栅大街"},{"title":"定胜糕（人均10元）","description":"嘉兴 · 乌镇西栅的招牌是定胜糕，小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"乌镇南栅"},{"title":"白水鱼（人均58元）","description":"嘉兴 · 乌镇西栅的招牌是白水鱼，水乡渔家本地人都认这家，点单照攻略不踩雷。","addr":"南浔百间楼"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","少量零食补给","轻便雨衣或折叠伞","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 嘉兴 的交通方便吗？","推荐先到 嘉兴，再打车或景区直通车前往核心景区；自驾导航直接搜乌镇西栅即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('瘦西湖纯攻略·周末版2','guide','扬州 · 瘦西湖','water','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',1500,800,2,'瘦西湖 / 个园 / 东关街 —— 纯攻略助你玩透瘦西湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「瘦西湖」三日深度游——水景。扬州漆器螺钿最精美。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 扬州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往扬州，抵达后办理入住、熟悉周边环境。","addr":"扬州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"瘦西湖","description":"下午首站瘦西湖，调整状态进入旅行节奏，两堤花柳全依水，五亭桥白塔。","addr":"扬州市邗江区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游扬州一带氛围拉满，晚餐蟹粉狮子头人均68元。","addr":"念四路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"个园","description":"全天主景点个园，四季假山一园看尽。","addr":"东关街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐扬州炒饭（人均28元），早点休息。","addr":"东关街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"东关街","description":"收官东关街，千年古街，夜色灯笼。","addr":"广陵区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐烫干丝后集合返程，三日旅程圆满。","addr":"得胜桥","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"瘦西湖","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"瘦西湖是瘦西湖最有代表性的看点，两堤花柳全依水，五亭桥白塔。攻略把它排进主线，时间留得最足。","notice":"两堤花柳全依水，五亭桥白塔。这个点位上午光线最好。","durationMinutes":180,"addr":"扬州市邗江区"},{"spotId":"S2","name":"个园","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"个园是瘦西湖最有代表性的看点，四季假山一园看尽。攻略把它排进主线，时间留得最足。","notice":"四季假山一园看尽。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"东关街"},{"spotId":"S3","name":"东关街","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"东关街是瘦西湖最有代表性的看点，千年古街，夜色灯笼。攻略把它排进主线，时间留得最足。","notice":"千年古街，夜色灯笼。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"广陵区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蟹粉狮子头（人均68元）","description":"扬州 · 瘦西湖的招牌是蟹粉狮子头，食为天本地人都认这家，点单照攻略不踩雷。","addr":"念四路"},{"title":"扬州炒饭（人均28元）","description":"扬州 · 瘦西湖的招牌是扬州炒饭，老字号本地人都认这家，点单照攻略不踩雷。","addr":"东关街"},{"title":"烫干丝（人均22元）","description":"扬州 · 瘦西湖的招牌是烫干丝，富春茶社本地人都认这家，点单照攻略不踩雷。","addr":"得胜桥"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金","相机或运动相机","身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三峡人家纯攻略·亲子篇2','guide','宜昌 · 三峡人家','water','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,2,'三峡人家 / 三峡大坝 / 清江画廊 —— 纯攻略助你玩透三峡人家精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「三峡人家」两日慢旅行——水景。宜昌柑橘橙都好吃。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 宜昌"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宜昌","description":"集合出发，大巴直达三峡人家，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"三峡人家","description":"抵达后首游三峡人家，灯影石与龙进溪，土家婚俗表演。","addr":"宜昌市夷陵区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐峡口肥鱼（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三峡大坝","description":"早起人少，三峡大坝精华时段，国之重器，坛子岭俯瞰。","addr":"夷陵区三斗坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐懒豆腐，人均28元，补充体力。","addr":"三峡人家景区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"清江画廊","description":"午后游览清江画廊，乘船入画，巴人发源地。","addr":"长阳县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"三峡人家","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"三峡人家是三峡人家最有代表性的看点，灯影石与龙进溪，土家婚俗表演。攻略把它排进主线，时间留得最足。","notice":"灯影石与龙进溪，土家婚俗表演。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"宜昌市夷陵区"},{"spotId":"S2","name":"三峡大坝","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"三峡大坝是三峡人家最有代表性的看点，国之重器，坛子岭俯瞰。攻略把它排进主线，时间留得最足。","notice":"国之重器，坛子岭俯瞰。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"夷陵区三斗坪镇"},{"spotId":"S3","name":"清江画廊","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"清江画廊是三峡人家最有代表性的看点，乘船入画，巴人发源地。攻略把它排进主线，时间留得最足。","notice":"乘船入画，巴人发源地。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"长阳县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"峡口肥鱼（人均88元）","description":"宜昌 · 三峡人家的招牌是峡口肥鱼，江边鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"三斗坪"},{"title":"懒豆腐（人均28元）","description":"宜昌 · 三峡人家的招牌是懒豆腐，土家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"三峡人家景区"},{"title":"清江银鱼（人均45元）","description":"宜昌 · 三峡人家的招牌是清江银鱼，水产馆本地人都认这家，点单照攻略不踩雷。","addr":"长阳县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","相机或运动相机","身份证件与手机充电宝","墨镜与拍照道具","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('华山纯攻略·摄影机位2','guide','渭南 · 华山','adventure','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1990,1000,9,'东峰朝阳峰 / 西峰莲花峰 / 苍龙岭 —— 纯攻略助你玩透华山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「华山」三日深度游——探险地。华山论剑碑打卡要排队。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 渭南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往渭南，抵达后办理入住、熟悉周边环境。","addr":"渭南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"东峰朝阳峰","description":"下午首站东峰朝阳峰，调整状态进入旅行节奏，长空栈道与鹞子翻身，排队2小时。","addr":"华阴市华山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游渭南一带氛围拉满，晚餐大刀面人均18元。","addr":"华阴市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西峰莲花峰","description":"全天主景点西峰莲花峰，索道直达，斧劈石传说。","addr":"华山最美峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐踅面（人均15元），早点休息。","addr":"华山脚下","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"苍龙岭","description":"收官苍龙岭，岭脊如龙，两侧深渊。","addr":"华山中段","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐秦镇米皮后集合返程，三日旅程圆满。","addr":"玉泉院旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"东峰朝阳峰","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"东峰朝阳峰是华山最有代表性的看点，长空栈道与鹞子翻身，排队2小时。攻略把它排进主线，时间留得最足。","notice":"长空栈道与鹞子翻身，排队2小时。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"华阴市华山风景区"},{"spotId":"S2","name":"西峰莲花峰","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"西峰莲花峰是华山最有代表性的看点，索道直达，斧劈石传说。攻略把它排进主线，时间留得最足。","notice":"索道直达，斧劈石传说。这个点位上午光线最好。","durationMinutes":180,"addr":"华山最美峰"},{"spotId":"S3","name":"苍龙岭","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"苍龙岭是华山最有代表性的看点，岭脊如龙，两侧深渊。攻略把它排进主线，时间留得最足。","notice":"岭脊如龙，两侧深渊。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"华山中段"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"大刀面（人均18元）","description":"渭南 · 华山的招牌是大刀面，华阴老字号本地人都认这家，点单照攻略不踩雷。","addr":"华阴市区"},{"title":"踅面（人均15元）","description":"渭南 · 华山的招牌是踅面，合阳踅面本地人都认这家，点单照攻略不踩雷。","addr":"华山脚下"},{"title":"秦镇米皮（人均12元）","description":"渭南 · 华山的招牌是秦镇米皮，老秦镇本地人都认这家，点单照攻略不踩雷。","addr":"玉泉院旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","相机或运动相机","防晒霜与遮阳帽","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 渭南 的交通方便吗？","推荐先到 渭南，再打车或景区直通车前往核心景区；自驾导航直接搜华山即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('曲阜三孔纯攻略·美食清单2','guide','济宁 · 曲阜三孔','red','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',1200,600,7,'孔庙 / 孔府 / 孔林 —— 纯攻略助你玩透曲阜三孔精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「曲阜三孔」两日慢旅行——人文。曲阜楷木雕如意吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 济宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴济宁","description":"集合出发，大巴直达曲阜三孔，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"孔庙","description":"抵达后首游孔庙，祭孔大典地，古柏森森。","addr":"济宁市曲阜市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐孔府菜（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"孔府","description":"早起人少，孔府精华时段，天下第一家，后花园。","addr":"曲阜","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山东煎饼，人均10元，补充体力。","addr":"鼓楼街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"孔林","description":"午后游览孔林，至圣林，孔子墓。","addr":"曲阜","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"孔庙","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"孔庙是曲阜三孔最有代表性的看点，祭孔大典地，古柏森森。攻略把它排进主线，时间留得最足。","notice":"祭孔大典地，古柏森森。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"济宁市曲阜市"},{"spotId":"S2","name":"孔府","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"孔府是曲阜三孔最有代表性的看点，天下第一家，后花园。攻略把它排进主线，时间留得最足。","notice":"天下第一家，后花园。这个点位上午光线最好。","durationMinutes":90,"addr":"曲阜"},{"spotId":"S3","name":"孔林","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"孔林是曲阜三孔最有代表性的看点，至圣林，孔子墓。攻略把它排进主线，时间留得最足。","notice":"至圣林，孔子墓。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"曲阜"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"孔府菜（人均88元）","description":"济宁 · 曲阜三孔的招牌是孔府菜，阙里宾舍本地人都认这家，点单照攻略不踩雷。","addr":"曲阜孔庙旁"},{"title":"山东煎饼（人均10元）","description":"济宁 · 曲阜三孔的招牌是山东煎饼，煎饼卷本地人都认这家，点单照攻略不踩雷。","addr":"鼓楼街"},{"title":"羊肉泡粥（人均28元）","description":"济宁 · 曲阜三孔的招牌是羊肉泡粥，羊肉泡粥馆本地人都认这家，点单照攻略不踩雷。","addr":"曲阜市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","少量零食补给","轻便雨衣或折叠伞","相机或运动相机","保温水杯与少量现金","墨镜与拍照道具","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('亚龙湾蜈支洲纯攻略·自由行手册2','guide','三亚 · 亚龙湾蜈支洲','sea','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1990,1000,6,'蜈支洲岛 / 亚龙湾热带天堂森林公园 / 后海村 —— 纯攻略助你玩透亚龙湾蜈支洲精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「亚龙湾蜈支洲」三日深度游——海滨。三亚贵妃芒香甜多汁。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 三亚"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往三亚，抵达后办理入住、熟悉周边环境。","addr":"三亚市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜈支洲岛","description":"下午首站蜈支洲岛，调整状态进入旅行节奏，中国马尔代夫，潜水胜地。","addr":"三亚市海棠区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游三亚一带氛围拉满，晚餐椰子鸡人均78元。","addr":"后海村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"亚龙湾热带天堂森林公园","description":"全天主景点亚龙湾热带天堂森林公园，过江龙索道，电影取景地。","addr":"亚龙湾","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐清补凉（人均15元），早点休息。","addr":"第一市场","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"后海村","description":"收官后海村，冲浪初学者天堂，夜市。","addr":"海棠湾","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐海鲜加工后集合返程，三日旅程圆满。","addr":"新民街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜈支洲岛","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"蜈支洲岛是亚龙湾蜈支洲最有代表性的看点，中国马尔代夫，潜水胜地。攻略把它排进主线，时间留得最足。","notice":"中国马尔代夫，潜水胜地。这个点位上午光线最好。","durationMinutes":300,"addr":"三亚市海棠区"},{"spotId":"S2","name":"亚龙湾热带天堂森林公园","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"亚龙湾热带天堂森林公园是亚龙湾蜈支洲最有代表性的看点，过江龙索道，电影取景地。攻略把它排进主线，时间留得最足。","notice":"过江龙索道，电影取景地。这个点位上午光线最好。","durationMinutes":180,"addr":"亚龙湾"},{"spotId":"S3","name":"后海村","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"后海村是亚龙湾蜈支洲最有代表性的看点，冲浪初学者天堂，夜市。攻略把它排进主线，时间留得最足。","notice":"冲浪初学者天堂，夜市。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"海棠湾"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"椰子鸡（人均78元）","description":"三亚 · 亚龙湾蜈支洲的招牌是椰子鸡，萌哒哒椰子鸡本地人都认这家，点单照攻略不踩雷。","addr":"后海村"},{"title":"清补凉（人均15元）","description":"三亚 · 亚龙湾蜈支洲的招牌是清补凉，一馨清补凉本地人都认这家，点单照攻略不踩雷。","addr":"第一市场"},{"title":"海鲜加工（人均98元）","description":"三亚 · 亚龙湾蜈支洲的招牌是海鲜加工，第一市场本地人都认这家，点单照攻略不踩雷。","addr":"新民街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","轻便雨衣或折叠伞","相机或运动相机","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","墨镜与拍照道具","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["到达 三亚 的交通方便吗？","推荐先到 三亚，再打车或景区直通车前往核心景区；自驾导航直接搜亚龙湾蜈支洲即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 三亚，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'这一程，山水都在替你说话。','on');
