INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滨海路金石滩纯攻略·避坑版2','guide','大连 · 滨海路金石滩','sea','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2990,1600,6,'滨海路木栈道 / 金石滩国家地质公园 / 星海广场 —— 纯攻略助你玩透滨海路金石滩精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「滨海路金石滩」三日深度游——海滨。大连海参干货首选。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"辽宁 · 大连"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大连，抵达后办理入住、熟悉周边环境。","addr":"大连市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"滨海路木栈道","description":"下午首站滨海路木栈道，调整状态进入旅行节奏，山海相依城市步道，北大桥日落。","addr":"大连市中山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大连一带氛围拉满，晚餐海鲜焖子人均48元。","addr":"滨海路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"金石滩国家地质公园","description":"全天主景点金石滩国家地质公园，恐龙探海奇石，龟裂石。","addr":"金州区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海胆蒸蛋（人均68元），早点休息。","addr":"老虎滩","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"星海广场","description":"收官星海广场，亚洲最大城市广场，夜景。","addr":"沙河口区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐铁板鱿鱼后集合返程，三日旅程圆满。","addr":"西安路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"滨海路木栈道","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"滨海路木栈道是滨海路金石滩最有代表性的看点，山海相依城市步道，北大桥日落。攻略把它排进主线，时间留得最足。","notice":"山海相依城市步道，北大桥日落。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"大连市中山区"},{"spotId":"S2","name":"金石滩国家地质公园","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"金石滩国家地质公园是滨海路金石滩最有代表性的看点，恐龙探海奇石，龟裂石。攻略把它排进主线，时间留得最足。","notice":"恐龙探海奇石，龟裂石。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"金州区"},{"spotId":"S3","name":"星海广场","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"星海广场是滨海路金石滩最有代表性的看点，亚洲最大城市广场，夜景。攻略把它排进主线，时间留得最足。","notice":"亚洲最大城市广场，夜景。这个点位上午光线最好。","durationMinutes":60,"addr":"沙河口区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜焖子（人均48元）","description":"大连 · 滨海路金石滩的招牌是海鲜焖子，品海楼本地人都认这家，点单照攻略不踩雷。","addr":"滨海路"},{"title":"海胆蒸蛋（人均68元）","description":"大连 · 滨海路金石滩的招牌是海胆蒸蛋，日丰园本地人都认这家，点单照攻略不踩雷。","addr":"老虎滩"},{"title":"铁板鱿鱼（人均25元）","description":"大连 · 滨海路金石滩的招牌是铁板鱿鱼，中央大道夜市本地人都认这家，点单照攻略不踩雷。","addr":"西安路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","少量零食补给","保温水杯与少量现金","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 大连，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三清山纯攻略·深度指南2','guide','上饶 · 三清山','mountain','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',2500,1300,2,'南清园 / 阳光海岸 / 万寿园 —— 纯攻略助你玩透三清山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「三清山」两日慢旅行——山岳。三清山猴头菇干货是手信首选。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴上饶","description":"集合出发，大巴直达三清山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"南清园","description":"抵达后首游南清园，巨蟒出山、东方女神都在这条环线，台阶多备水。","addr":"三清山风景区南门","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐石鸡汤锅（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"阳光海岸","description":"早起人少，阳光海岸精华时段，栈道悬空，恐高走东线缓冲段。","addr":"三清山高空栈道","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐野艾果，人均10元，补充体力。","addr":"南山索道下站旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"万寿园","description":"午后游览万寿园，坡缓树多，适合收尾慢慢走。","addr":"三清山南部入口","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"南清园","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"南清园是三清山最有代表性的看点，巨蟒出山、东方女神都在这条环线，台阶多备水。攻略把它排进主线，时间留得最足。","notice":"巨蟒出山、东方女神都在这条环线，台阶多备水。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"三清山风景区南门"},{"spotId":"S2","name":"阳光海岸","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"阳光海岸是三清山最有代表性的看点，栈道悬空，恐高走东线缓冲段。攻略把它排进主线，时间留得最足。","notice":"栈道悬空，恐高走东线缓冲段。这个点位上午光线最好。","durationMinutes":150,"addr":"三清山高空栈道"},{"spotId":"S3","name":"万寿园","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"万寿园是三清山最有代表性的看点，坡缓树多，适合收尾慢慢走。攻略把它排进主线，时间留得最足。","notice":"坡缓树多，适合收尾慢慢走。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"三清山南部入口"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"石鸡汤锅（人均58元）","description":"上饶 · 三清山的招牌是石鸡汤锅，山脚农家菜本地人都认这家，点单照攻略不踩雷。","addr":"三清山外双溪服务区"},{"title":"野艾果（人均10元）","description":"上饶 · 三清山的招牌是野艾果，路边农家本地人都认这家，点单照攻略不踩雷。","addr":"南山索道下站旁"},{"title":"三清山烧饼（人均8元）","description":"上饶 · 三清山的招牌是三清山烧饼，南清园补给点本地人都认这家，点单照攻略不踩雷。","addr":"登山途中补给站"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","相机或运动相机","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 上饶 的交通方便吗？","推荐先到 上饶，再打车或景区直通车前往核心景区；自驾导航直接搜三清山即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('明月山纯攻略·周末版2','guide','宜春 · 明月山','mountain','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1990,1000,2,'青云栈道 / 云谷飞瀑 / 温汤镇古井泉街 —— 纯攻略助你玩透明月山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「明月山」三日深度游——山岳。温汤富硒温泉蛋一元一个。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 宜春"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜春，抵达后办理入住、熟悉周边环境。","addr":"宜春市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"青云栈道","description":"下午首站青云栈道，调整状态进入旅行节奏，悬空栈道绕山腰，云雾天如仙境。","addr":"明月山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜春一带氛围拉满，晚餐温泉豆腐人均48元。","addr":"温汤镇古井旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"云谷飞瀑","description":"全天主景点云谷飞瀑，宜春八景之一，负氧离子爆表。","addr":"明月山核心景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐慈化鸡爪（人均22元），早点休息。","addr":"温汤镇主街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"温汤镇古井泉街","description":"收官温汤镇古井泉街，富硒温泉足浴28元一位，晚上泡最解乏。","addr":"袁州区温汤镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐扎粉后集合返程，三日旅程圆满。","addr":"古井泉街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"青云栈道","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"青云栈道是明月山最有代表性的看点，悬空栈道绕山腰，云雾天如仙境。攻略把它排进主线，时间留得最足。","notice":"悬空栈道绕山腰，云雾天如仙境。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"明月山风景区"},{"spotId":"S2","name":"云谷飞瀑","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"云谷飞瀑是明月山最有代表性的看点，宜春八景之一，负氧离子爆表。攻略把它排进主线，时间留得最足。","notice":"宜春八景之一，负氧离子爆表。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"明月山核心景区"},{"spotId":"S3","name":"温汤镇古井泉街","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"温汤镇古井泉街是明月山最有代表性的看点，富硒温泉足浴28元一位，晚上泡最解乏。攻略把它排进主线，时间留得最足。","notice":"富硒温泉足浴28元一位，晚上泡最解乏。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"袁州区温汤镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"温泉豆腐（人均48元）","description":"宜春 · 明月山的招牌是温泉豆腐，温汤镇豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇古井旁"},{"title":"慈化鸡爪（人均22元）","description":"宜春 · 明月山的招牌是慈化鸡爪，宜春小吃店本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇主街"},{"title":"扎粉（人均15元）","description":"宜春 · 明月山的招牌是扎粉，宜春扎粉店本地人都认这家，点单照攻略不踩雷。","addr":"古井泉街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","墨镜与拍照道具","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","少量零食补给","身份证件与手机充电宝","换洗衣物与外套（早晚温差）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 宜春，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南岳衡山纯攻略·亲子篇2','guide','衡阳 · 南岳衡山','mountain','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',1500,800,2,'祝融峰 / 南岳大庙 / 藏经殿 —— 纯攻略助你玩透南岳衡山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「南岳衡山」两日慢旅行——山岳。南岳香文化用品别乱买。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 衡阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴衡阳","description":"集合出发，大巴直达南岳衡山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"祝融峰","description":"抵达后首游祝融峰，五岳最高峰观日出，山顶租赁军大衣。","addr":"南岳区衡山风景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐南岳素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"南岳大庙","description":"早起人少，南岳大庙精华时段，江南第一庙，香火极旺。","addr":"南岳区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐观音笋，人均38元，补充体力。","addr":"半山亭","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"藏经殿","description":"午后游览藏经殿，幽谷深林中的古刹。","addr":"衡山半山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"祝融峰","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"祝融峰是南岳衡山最有代表性的看点，五岳最高峰观日出，山顶租赁军大衣。攻略把它排进主线，时间留得最足。","notice":"五岳最高峰观日出，山顶租赁军大衣。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"南岳区衡山风景区"},{"spotId":"S2","name":"南岳大庙","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"南岳大庙是南岳衡山最有代表性的看点，江南第一庙，香火极旺。攻略把它排进主线，时间留得最足。","notice":"江南第一庙，香火极旺。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"南岳区"},{"spotId":"S3","name":"藏经殿","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"藏经殿是南岳衡山最有代表性的看点，幽谷深林中的古刹。攻略把它排进主线，时间留得最足。","notice":"幽谷深林中的古刹。这个点位上午光线最好。","durationMinutes":90,"addr":"衡山半山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"南岳素斋（人均48元）","description":"衡阳 · 南岳衡山的招牌是南岳素斋，大庙素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"南岳大庙旁"},{"title":"观音笋（人均38元）","description":"衡阳 · 南岳衡山的招牌是观音笋，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"半山亭"},{"title":"衡山云雾茶（人均30元）","description":"衡阳 · 南岳衡山的招牌是衡山云雾茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"南岳镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","少量零食补给","相机或运动相机","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["到达 衡阳 的交通方便吗？","推荐先到 衡阳，再打车或景区直通车前往核心景区；自驾导航直接搜南岳衡山即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 衡阳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('香格里拉纯攻略·摄影机位2','guide','迪庆 · 香格里拉','plateau','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1990,1000,2,'普达措国家公园 / 松赞林寺 / 独克宗古城 —— 纯攻略助你玩透香格里拉精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「香格里拉」三日深度游——高原。牦牛肉干认准风干原味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 迪庆"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往迪庆，抵达后办理入住、熟悉周边环境。","addr":"迪庆市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"普达措国家公园","description":"下午首站普达措国家公园，调整状态进入旅行节奏，属都湖栈道环湖，高原慢慢走。","addr":"香格里拉市建塘镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游迪庆一带氛围拉满，晚餐牦牛肉火锅人均88元。","addr":"独克宗古城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"松赞林寺","description":"全天主景点松赞林寺，小布达拉宫，顺时针转寺。","addr":"香格里拉市佛屏山前","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酥油茶（人均20元），早点休息。","addr":"古城内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"独克宗古城","description":"收官独克宗古城，转世界最大转经筒，夜景美。","addr":"香格里拉市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐青稞饼后集合返程，三日旅程圆满。","addr":"池慈卡街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"普达措国家公园","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"普达措国家公园是香格里拉最有代表性的看点，属都湖栈道环湖，高原慢慢走。攻略把它排进主线，时间留得最足。","notice":"属都湖栈道环湖，高原慢慢走。这个点位上午光线最好。","durationMinutes":240,"addr":"香格里拉市建塘镇"},{"spotId":"S2","name":"松赞林寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"松赞林寺是香格里拉最有代表性的看点，小布达拉宫，顺时针转寺。攻略把它排进主线，时间留得最足。","notice":"小布达拉宫，顺时针转寺。这个点位上午光线最好。","durationMinutes":120,"addr":"香格里拉市佛屏山前"},{"spotId":"S3","name":"独克宗古城","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"独克宗古城是香格里拉最有代表性的看点，转世界最大转经筒，夜景美。攻略把它排进主线，时间留得最足。","notice":"转世界最大转经筒，夜景美。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"香格里拉市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉火锅（人均88元）","description":"迪庆 · 香格里拉的招牌是牦牛肉火锅，市井牦牛火锅本地人都认这家，点单照攻略不踩雷。","addr":"独克宗古城"},{"title":"酥油茶（人均20元）","description":"迪庆 · 香格里拉的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"青稞饼（人均12元）","description":"迪庆 · 香格里拉的招牌是青稞饼，藏式饼铺本地人都认这家，点单照攻略不踩雷。","addr":"池慈卡街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","少量零食补给","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 迪庆 的交通方便吗？","推荐先到 迪庆，再打车或景区直通车前往核心景区；自驾导航直接搜香格里拉即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('峨眉山乐山大佛纯攻略·美食清单2','guide','乐山 · 峨眉山乐山大佛','mountain','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1500,800,2,'乐山大佛 / 峨眉山金顶 / 清音阁 —— 纯攻略助你玩透峨眉山乐山大佛精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「峨眉山乐山大佛」两日慢旅行——山岳。峨眉雪芽茶清甜回甘。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 乐山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴乐山","description":"集合出发，大巴直达峨眉山乐山大佛，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乐山大佛","description":"抵达后首游乐山大佛，九曲栈道近距离看大佛脚背。","addr":"乐山市凌云路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐钵钵鸡（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"峨眉山金顶","description":"早起人少，峨眉山金顶精华时段，十方普贤金像，云海日出。","addr":"峨眉山市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐甜皮鸭，人均28元，补充体力。","addr":"乐山张公桥","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"清音阁","description":"午后游览清音阁，双桥清音，平路好走。","addr":"峨眉山低山区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乐山大佛","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"乐山大佛是峨眉山乐山大佛最有代表性的看点，九曲栈道近距离看大佛脚背。攻略把它排进主线，时间留得最足。","notice":"九曲栈道近距离看大佛脚背。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"乐山市凌云路"},{"spotId":"S2","name":"峨眉山金顶","coverUrl":"https://images.unsplash.com/ph