INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('梵净山纯攻略·自由行手册2','guide','铜仁 · 梵净山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',2500,1300,2,'红云金顶 / 蘑菇石 / 承恩寺 —— 纯攻略助你玩透梵净山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「梵净山」三日深度游——山岳。梵净山藤茶甘甜养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 铜仁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往铜仁，抵达后办理入住、熟悉周边环境。","addr":"铜仁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"红云金顶","description":"下午首站红云金顶，调整状态进入旅行节奏，海拔2493双峰寺庙，爬铁索上天桥。","addr":"铜仁市江口县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游铜仁一带氛围拉满，晚餐江口豆腐干人均28元。","addr":"梵净山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"蘑菇石","description":"全天主景点蘑菇石，10亿年奇石，排队打卡。","addr":"梵净山标志性景观","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐米虾（人均48元），早点休息。","addr":"太平镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"承恩寺","description":"收官承恩寺，明代古刹，云海时分最妙。","addr":"金顶下方","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐天麻炖鸡后集合返程，三日旅程圆满。","addr":"江口县城","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"红云金顶","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"红云金顶是梵净山最有代表性的看点，海拔2493双峰寺庙，爬铁索上天桥。攻略把它排进主线，时间留得最足。","notice":"海拔2493双峰寺庙，爬铁索上天桥。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"铜仁市江口县"},{"spotId":"S2","name":"蘑菇石","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"蘑菇石是梵净山最有代表性的看点，10亿年奇石，排队打卡。攻略把它排进主线，时间留得最足。","notice":"10亿年奇石，排队打卡。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"梵净山标志性景观"},{"spotId":"S3","name":"承恩寺","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"承恩寺是梵净山最有代表性的看点，明代古刹，云海时分最妙。攻略把它排进主线，时间留得最足。","notice":"明代古刹，云海时分最妙。这个点位上午光线最好。","durationMinutes":60,"addr":"金顶下方"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"江口豆腐干（人均28元）","description":"铜仁 · 梵净山的招牌是江口豆腐干，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"梵净山镇"},{"title":"米虾（人均48元）","description":"铜仁 · 梵净山的招牌是米虾，河鲜馆本地人都认这家，点单照攻略不踩雷。","addr":"太平镇"},{"title":"天麻炖鸡（人均88元）","description":"铜仁 · 梵净山的招牌是天麻炖鸡，药膳馆本地人都认这家，点单照攻略不踩雷。","addr":"江口县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","轻便雨衣或折叠伞","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["到达 铜仁 的交通方便吗？","推荐先到 铜仁，再打车或景区直通车前往核心景区；自驾导航直接搜梵净山即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 铜仁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('程阳八寨纯攻略·省钱玩法2','guide','柳州 · 程阳八寨','village','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1990,1000,1,'程阳八寨 / 三江侗天宫 / 窑埠古镇 —— 纯攻略助你玩透程阳八寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「程阳八寨」两日慢旅行——古村落。柳州螺蛳粉袋装正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 柳州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴柳州","description":"集合出发，大巴直达程阳八寨，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"程阳八寨","description":"抵达后首游程阳八寨，风雨桥鼓楼，侗族百家宴。","addr":"柳州市三江县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐螺蛳粉（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三江侗天宫","description":"早起人少，三江侗天宫精华时段，侗族文化大观。","addr":"三江县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐百家宴，人均58元，补充体力。","addr":"程阳八寨","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"窑埠古镇","description":"午后游览窑埠古镇，百里柳江夜景起点。","addr":"柳州市区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"程阳八寨","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"程阳八寨是程阳八寨最有代表性的看点，风雨桥鼓楼，侗族百家宴。攻略把它排进主线，时间留得最足。","notice":"风雨桥鼓楼，侗族百家宴。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"柳州市三江县"},{"spotId":"S2","name":"三江侗天宫","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"三江侗天宫是程阳八寨最有代表性的看点，侗族文化大观。攻略把它排进主线，时间留得最足。","notice":"侗族文化大观。这个点位上午光线最好。","durationMinutes":90,"addr":"三江县"},{"spotId":"S3","name":"窑埠古镇","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"窑埠古镇是程阳八寨最有代表性的看点，百里柳江夜景起点。攻略把它排进主线，时间留得最足。","notice":"百里柳江夜景起点。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"柳州市区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"螺蛳粉（人均15元）","description":"柳州 · 程阳八寨的招牌是螺蛳粉，爱民螺蛳粉本地人都认这家，点单照攻略不踩雷。","addr":"柳州市区"},{"title":"百家宴（人均58元）","description":"柳州 · 程阳八寨的招牌是百家宴，程阳八寨本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"},{"title":"打油茶（人均20元）","description":"柳州 · 程阳八寨的招牌是打油茶，寨中茶楼本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","少量零食补给","墨镜与拍照道具","保温水杯与少量现金","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 柳州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('普陀山纯攻略·避坑版2','guide','舟山 · 普陀山','sea','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,6,'普济寺 / 南海观音 / 百步沙 —— 纯攻略助你玩透普陀山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普陀山」三日深度游——海滨。普陀佛茶清香回甘。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 舟山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往舟山，抵达后办理入住、熟悉周边环境。","addr":"舟山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"普济寺","description":"下午首站普济寺，调整状态进入旅行节奏，普陀山主刹，香花券5元。","addr":"舟山市普陀区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游舟山一带氛围拉满，晚餐海鲜面人均38元。","addr":"沈家门渔港","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"南海观音","description":"全天主景点南海观音，33米观音立像，海天佛国。","addr":"普陀山南端","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐普陀佛茶（人均30元），早点休息。","addr":"普济寺旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"百步沙","description":"收官百步沙，看日出踩沙滩。","addr":"普陀山","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐素斋后集合返程，三日旅程圆满。","addr":"普济寺边","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"普济寺","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"普济寺是普陀山最有代表性的看点，普陀山主刹，香花券5元。攻略把它排进主线，时间留得最足。","notice":"普陀山主刹，香花券5元。这个点位上午光线最好。","durationMinutes":120,"addr":"舟山市普陀区"},{"spotId