INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('太湖鼋头渚纯攻略·深度指南2','guide','无锡 · 太湖鼋头渚','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,2,'鼋头渚 / 灵山大佛 / 南长街 —— 纯攻略助你玩透太湖鼋头渚精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「太湖鼋头渚」两日慢旅行——水景。惠山泥人阿福最喜庆。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 无锡"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴无锡","description":"集合出发，大巴直达太湖鼋头渚，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"鼋头渚","description":"抵达后首游鼋头渚，太湖第一名胜，樱花季封神。","addr":"无锡市滨湖区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐无锡小笼（人均22元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"灵山大佛","description":"早起人少，灵山大佛精华时段，88米大佛，梵宫震撼。","addr":"滨湖区马山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酱排骨，人均48元，补充体力。","addr":"中山路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南长街","description":"午后游览南长街，古运河夜色，清名桥倒影。","addr":"梁溪区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"鼋头渚","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"鼋头渚是太湖鼋头渚最有代表性的看点，太湖第一名胜，樱花季封神。攻略把它排进主线，时间留得最足。","notice":"太湖第一名胜，樱花季封神。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"无锡市滨湖区"},{"spotId":"S2","name":"灵山大佛","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"灵山大佛是太湖鼋头渚最有代表性的看点，88米大佛，梵宫震撼。攻略把它排进主线，时间留得最足。","notice":"88米大佛，梵宫震撼。这个点位上午光线最好。","durationMinutes":180,"addr":"滨湖区马山"},{"spotId":"S3","name":"南长街","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"南长街是太湖鼋头渚最有代表性的看点，古运河夜色，清名桥倒影。攻略把它排进主线，时间留得最足。","notice":"古运河夜色，清名桥倒影。这个点位上午光线最好。","durationMinutes":120,"addr":"梁溪区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"无锡小笼（人均22元）","description":"无锡 · 太湖鼋头渚的招牌是无锡小笼，熙盛源本地人都认这家，点单照攻略不踩雷。","addr":"南禅寺"},{"title":"酱排骨（人均48元）","description":"无锡 · 太湖鼋头渚的招牌是酱排骨，三凤桥本地人都认这家，点单照攻略不踩雷。","addr":"中山路"},{"title":"太湖三白（人均98元）","description":"无锡 · 太湖鼋头渚的招牌是太湖三白，渔人码头本地人都认这家，点单照攻略不踩雷。","addr":"鼋头渚旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","少量零食补给","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 无锡 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九宫山隐水洞纯攻略·周末版2','guide','咸宁 · 九宫山隐水洞','mountain','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',1500,800,2,'九宫山 / 隐水洞 / 刘家桥古民居 —— 纯攻略助你玩透九宫山隐水洞精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九宫山隐水洞」三日深度游——山岳。咸宁桂花蜜香甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 咸宁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往咸宁，抵达后办理入住、熟悉周边环境。","addr":"咸宁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"九宫山","description":"下午首站九宫山，调整状态进入旅行节奏，云中湖避暑胜地，闯王陵。","addr":"咸宁市通山县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游咸宁一带氛围拉满，晚餐贺胜桥鸡汤人均58元。","addr":"咸安区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"隐水洞","description":"全天主景点隐水洞，水路旱路双游线溶洞。","addr":"通山县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐桂花糕（人均15元），早点休息。","addr":"温泉城区","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"刘家桥古民居","description":"收官刘家桥古民居，明清廊桥古民居。","addr":"咸安区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐通山合菜面后集合返程，三日旅程圆满。","addr":"通山县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"九宫山","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"九宫山是九宫山隐水洞最有代表性的看点，云中湖避暑胜地，闯王陵。攻略把它排进主线，时间留得最足。","notice":"云中湖避暑胜地，闯王陵。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"咸宁市通山县"},{"spotId":"S2","name":"隐水洞","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"隐水洞是九宫山隐水洞最有代表性的看点，水路旱路双游线溶洞。攻略把它排进主线，时间留得最足。","notice":"水路旱路双游线溶洞。这个点位上午光线最好。","durationMinutes":150,"addr":"通山县"},{"spotId":"S3","name":"刘家桥古民居","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"刘家桥古民居是九宫山隐水洞最有代表性的看点，明清廊桥古民居。攻略把它排进主线，时间留得最足。","notice":"明清廊桥古民居。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"咸安区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"贺胜桥鸡汤（人均58元）","description":"咸宁 · 九宫山隐水洞的招牌是贺胜桥鸡汤，贺胜桥土鸡馆本地人都认这家，点单照攻略不踩雷。","addr":"咸安区"},{"title":"桂花糕（人均15元）","description":"咸宁 · 九宫山隐水洞的招牌是桂花糕，桂花之乡本地人都认这家，点单照攻略不踩雷。","addr":"温泉城区"},{"title":"通山合菜面（人均28元）","description":"咸宁 · 九宫山隐水洞的招牌是通山合菜面，通山农家本地人都认这家，点单照攻略不踩雷。","addr":"通山县"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","身份证件与手机充电宝","保温水杯与少量现金","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('壶口瀑布纯攻略·亲子篇2','guide','延安 · 壶口瀑布','red','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,7,'壶口瀑布 / 宝塔山 / 枣园革命旧址 —— 纯攻略助你玩透壶口瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「壶口瀑布」两日慢旅行——人文。延安小米熬粥最养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 延安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延安","description":"集合出发，大巴直达壶口瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"壶口瀑布","description":"抵达后首游壶口瀑布，黄河之水天上来，旱地行船遗址。","addr":"延安市宜川县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐油馍馍（人均10元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"宝塔山","description":"早起人少，宝塔山精华时段，延安地标灯光秀。","addr":"延安市宝塔区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐羊杂碎，人均25元，补充体力。","addr":"宝塔区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"枣园革命旧址","description":"午后游览枣园革命旧址，窑洞与历史课堂。","addr":"宝塔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"壶口瀑布","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"壶口瀑布是壶口瀑布最有代表性的看点，黄河之水天上来，旱地行船遗址。攻略把它排进主线，时间留得最足。","notice":"黄河之水天上来，旱地行船遗址。这个点位上午光线最好。","durationMinutes":150,"addr":"延安市宜川县"},{"spotId":"S2","name":"宝塔山","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?au