INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('避暑山庄纯攻略·摄影机位2','guide','承德 · 避暑山庄','village','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',990,500,1,'避暑山庄 / 普宁寺 / 磬锤峰 —— 纯攻略助你玩透避暑山庄精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「避暑山庄」三日深度游——古村落。承德木雕核桃吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 承德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往承德，抵达后办理入住、熟悉周边环境。","addr":"承德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"避暑山庄","description":"下午首站避暑山庄，调整状态进入旅行节奏，皇家园林之最，山区乘车看小布达拉。","addr":"承德市双桥区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游承德一带氛围拉满，晚餐御土荷叶鸡人均38元。","addr":"承德市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"普宁寺","description":"全天主景点普宁寺，大佛寺千手千眼观音。","addr":"承德市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐荞面饸饹（人均18元），早点休息。","addr":"山庄东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"磬锤峰","description":"收官磬锤峰，棒槌山奇观，索道往返。","addr":"承德市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏仁茶后集合返程，三日旅程圆满。","addr":"二仙居","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"避暑山庄","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"避暑山庄是避暑山庄最有代表性的看点，皇家园林之最，山区乘车看小布达拉。攻略把它排进主线，时间留得最足。","notice":"皇家园林之最，山区乘车看小布达拉。这个点位上午光线最好。","durationMinutes":240,"addr":"承德市双桥区"},{"spotId":"S2","name":"普宁寺","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"普宁寺是避暑山庄最有代表性的看点，大佛寺千手千眼观音。攻略把它排进主线，时间留得最足。","notice":"大佛寺千手千眼观音。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"承德市"},{"spotId":"S3","name":"磬锤峰","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"磬锤峰是避暑山庄最有代表性的看点，棒槌山奇观，索道往返。攻略把它排进主线，时间留得最足。","notice":"棒槌山奇观，索道往返。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"承德市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"御土荷叶鸡（人均38元）","description":"承德 · 避暑山庄的招牌是御土荷叶鸡，老三羊汤本地人都认这家，点单照攻略不踩雷。","addr":"承德市区"},{"title":"荞面饸饹（人均18元）","description":"承德 · 避暑山庄的招牌是荞面饸饹，莜面馆本地人都认这家，点单照攻略不踩雷。","addr":"山庄东路"},{"title":"杏仁茶（人均10元）","description":"承德 · 避暑山庄的招牌是杏仁茶，小吃街本地人都认这家，点单照攻略不踩雷。","addr":"二仙居"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","保温水杯与少量现金","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 承德 的交通方便吗？","推荐先到 承德，再打车或景区直通车前往核心景区；自驾导航直接搜避暑山庄即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('日月湾冲浪纯攻略·美食清单2','guide','万宁 · 日月湾冲浪','sea','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,6,'日月湾 / 石梅湾 / 兴隆热带植物园 —— 纯攻略助你玩透日月湾冲浪精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「日月湾冲浪」两日慢旅行——海滨。兴隆炭烧咖啡回香浓。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 万宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴万宁","description":"集合出发，大巴直达日月湾冲浪，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"日月湾","description":"抵达后首游日月湾，国家冲浪队训练地，新手教程2小时。","addr":"万宁市礼纪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐和乐蟹（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"石梅湾","description":"早起人少，石梅湾精华时段，加井岛浮潜，凤凰九里书屋。","addr":"万宁市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐东山羊，人均88元，补充体力。","addr":"万城镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"兴隆热带植物园","description":"午后游览兴隆热带植物园，咖啡可可巧克力之旅。","addr":"兴隆镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"日月湾","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"日月湾是日月湾冲浪最有代表性的看点，国家冲浪队训练地，新手教程2小时。攻略把它排进主线，时间留得最足。","notice":"国家冲浪队训练地，新手教程2小时。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"万宁市礼纪镇"},{"spotId":"S2","name":"石梅湾","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"石梅湾是日月湾冲浪最有代表性的看点，加井岛浮潜，凤凰九里书屋。攻略把它排进主线，时间留得最足。","notice":"加井岛浮潜，凤凰九里书屋。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"万宁市"},{"spotId":"S3","name":"兴隆热带植物园","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"兴隆热带植物园是日月湾冲浪最有代表性的看点，咖啡可可巧克力之旅。攻略把它排进主线，时间留得最足。","notice":"咖啡可可巧克力之旅。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"兴隆镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"和乐蟹（人均88元）","description":"万宁 · 日月湾冲浪的招牌是和乐蟹，渔家海鲜本地人都认这家，点单照攻略不踩雷。","addr":"东澳镇"},{"title":"东山羊（人均88元）","description":"万宁 · 日月湾冲浪的招牌是东山羊，东山羊庄本地人都认这家，点单照攻略不踩雷。","addr":"万城镇"},{"title":"兴隆咖啡（人均25元）","description":"万宁 · 日月湾冲浪的招牌是兴隆咖啡，咖啡庄园本地人都认这家，点单照攻略不踩雷。","addr":"兴隆镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","相机或运动相机","轻便雨衣或折叠伞","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","保温水杯与少量现金","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('喀纳斯纯攻略·自由行手册2','guide','阿勒泰 · 喀纳斯','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',2990,1600,2,'喀纳斯湖 / 禾木村 / 白哈巴 —— 纯攻略助你玩透喀纳斯精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「喀纳斯」三日深度游——水景。喀纳斯冷水鱼干风味独特。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 阿勒泰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往阿勒泰，抵达后办理入住、熟悉周边环境。","addr":"阿勒泰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"喀纳斯湖","description":"下午首站喀纳斯湖，调整状态进入旅行节奏，三湾晨雾与湖怪传说，观鱼台俯瞰。","addr":"布尔津县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游阿勒泰一带氛围拉满，晚餐烤全羊人均128元。","addr":"禾木村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"禾木村","description":"全天主景点禾木村，图瓦人村落，白桦林晨雾。","addr":"喀纳斯景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐手抓饭（人均35元），早点休息。","addr":"贾登峪","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"白哈巴","description":"收官白哈巴，中哈边境原始村落。","addr":"哈巴河县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐奶茶后集合返程，三日旅程圆满。","addr":"白哈巴","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"喀纳斯湖","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"喀纳斯湖是喀纳斯最有代表性的看点，三湾晨雾与湖怪传说，观鱼台俯瞰。攻略把它排进主线，时间留得最足。","notice":"三湾晨雾与湖怪传说，观鱼台俯瞰。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"布尔津县"},{"spotId":"S2","name":"禾木村","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"禾木村是喀纳斯最有代表性的看点，图瓦人村落，白桦林晨雾。攻略把它排进主线，时间留得最足。","notice":"图瓦人村落，白桦林晨雾。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"喀纳斯景区"},{"spotId":"S3","name":"白哈巴","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"白哈巴是喀纳斯最有代表性的看点，中哈边境原始村落。攻略把它排进主线，时间留得最足。","notice":"中哈边境原始村落。这个点位上午光线最好。","durationMinutes":120,"addr":"哈巴河县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤全羊（人均128元）","description":"阿勒泰 · 喀纳斯的招牌是烤全羊，图瓦人家本地人都认这家，点单照攻略不踩雷。","addr":"禾木村"},{"title":"手抓饭（人均35元）","description":"阿勒泰 · 喀纳斯的招牌是手抓饭，别克餐厅本地人都认这家，点单照攻略不踩雷。","addr":"贾登峪"},{"title":"奶茶（人均20元）","description":"阿勒泰 · 喀纳斯的招牌是奶茶，哈萨克毡房本地人都认这家，点单照攻略不踩雷。","addr":"白哈巴"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机","墨镜与拍照道具","轻便雨衣或折叠伞","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["到达 阿勒泰 的交通方便吗？","推荐先到 阿勒泰，再打车或景区直通车前往核心景区；自驾导航直接搜喀纳斯即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('中央大街冰雪纯攻略·省钱玩法2','guide','哈尔滨 · 中央大街冰雪','art','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,5,'中央大街 / 圣索菲亚大教堂 / 松花江防洪纪念塔 —— 纯攻略助你玩透中央大街冰雪精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「中央大街冰雪」两日慢旅行——文艺。哈尔滨红肠真空好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"黑龙江 · 哈尔滨"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴哈尔滨","description":"集合出发，大巴直达中央大街冰雪，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中央大街","description":"抵达后首游中央大街，百年面包石街道，马迭尔冰棍。","addr":"哈尔滨市道里区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐锅包肉（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"圣索菲亚大教堂","description":"早起人少，圣索菲亚大教堂精华时段，拜占庭绿顶，鸽子广场。","addr":"透笼街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐哈尔滨红肠，人均25元，补充体力。","addr":"中央大街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"松花江防洪纪念塔","description":"午后游览松花江防洪纪念塔，冬季冰上活动集合地。","addr":"道里区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中央大街","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"中央大街是中央大街冰雪最有代表性的看点，百年面包石街道，马迭尔冰棍。攻略把它排进主线，时间留得最足。","notice":"百年面包石街道，马迭尔冰棍。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"哈尔滨市道里区"},{"spotId":"S2","name":"圣索菲亚大教堂","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"圣索菲亚大教堂是中央大街冰雪最有代表性的看点，拜占庭绿顶，鸽子广场。攻略把它排进主线，时间留得最足。","notice":"拜占庭绿顶，鸽子广场。这个点位上午光线最好。","durationMinutes":60,"addr":"透笼街"},{"spotId":"S3","name":"松花江防洪纪念塔","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"松花江防洪纪念塔是中央大街冰雪最有代表性的看点，冬季冰上活动集合地。攻略把它排进主线，时间留得最足。","notice":"冬季冰上活动集合地。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"道里区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"锅包肉（人均48元）","description":"哈尔滨 · 中央大街冰雪的招牌是锅包肉，老厨家本地人都认这家，点单照攻略不踩雷。","addr":"友谊路"},{"title":"哈尔滨红肠（人均25元）","description":"哈尔滨 · 中央大街冰雪的招牌是哈尔滨红肠，秋林里道斯本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"},{"title":"格瓦斯（人均12元）","description":"哈尔滨 · 中央大街冰雪的招牌是格瓦斯，马迭尔冷饮厅本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 哈尔滨 的交通方便吗？","推荐先到 哈尔滨，再打车或景区直通车前往核心景区；自驾导航直接搜中央大街冰雪即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武功山纯攻略·避坑版2','guide','萍乡 · 武功山','mountain','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2500,1300,2,'金顶 / 发云界 / 玻璃栈道 —— 纯攻略助你玩透武功山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武功山」三日深度游——山岳。武功山泉水豆腐宴别错过。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往萍乡，抵达后办理入住、熟悉周边环境。","addr":"萍乡市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，日出云海核心位，山顶比山下冷10度。","addr":"武功山风景区金顶","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游萍乡一带氛围拉满，晚餐萍乡小炒肉人均42元。","addr":"武功山游客中心旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"发云界","description":"全天主景点发云界，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐艾米古（人均10元），早点休息。","addr":"金顶驿站","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"玻璃栈道","description":"收官玻璃栈道，栈道限流，旺季排30分钟。","addr":"武功山吊马桩","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐紫红米粉后集合返程，三日旅程圆满。","addr":"武功山镇主街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。这个点位上午光线最好。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","身份证件与手机充电宝","防晒霜与遮阳帽","保温水杯与少量现金","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 萍乡 的交通方便吗？","推荐先到 萍乡，再打车或景区直通车前往核心景区；自驾导航直接搜武功山即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('仙女湖纯攻略·深度指南2','guide','新余 · 仙女湖','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,2,'仙女湖主体湖区 / 圣集寺 / 龙王阁 —— 纯攻略助你玩透仙女湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「仙女湖」两日慢旅行——水景。新余蜜桔十月后最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 新余"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴新余","description":"集合出发，大巴直达仙女湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"仙女湖主体湖区","description":"抵达后首游仙女湖主体湖区，坐船跳岛游，爱情岛最热门。","addr":"新余市渝水区仙女湖大道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐仙女湖鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"圣集寺","description":"早起人少，圣集寺精华时段，湖畔禅意，人少清净。","addr":"仙女湖钤阳湖畔","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐新余蜜桔鸡，人均58元，补充体力。","addr":"景区出口农家乐","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙王阁","description":"午后游览龙王阁，登阁看千岛湖景。","addr":"仙女湖最高点","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"仙女湖主体湖区","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"仙女湖主体湖区是仙女湖最有代表性的看点，坐船跳岛游，爱情岛最热门。攻略把它排进主线，时间留得最足。","notice":"坐船跳岛游，爱情岛最热门。这个点位上午光线最好。","durationMinutes":180,"addr":"新余市渝水区仙女湖大道"},{"spotId":"S2","name":"圣集寺","coverUrl":"https://images.unsplash.com/photo-1500530855697-