INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('崀山纯攻略·周末版2','guide','邵阳 · 崀山','adventure','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',990,500,9,'辣椒峰 / 天一巷 / 扶夷江竹筏 —— 纯攻略助你玩透崀山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「崀山」三日深度游——探险地。新宁脐橙秋冬正当季。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 邵阳"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往邵阳，抵达后办理入住、熟悉周边环境。","addr":"邵阳市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"辣椒峰","description":"下午首站辣椒峰，调整状态进入旅行节奏，丹霞地貌标志峰，远观近爬两相宜。","addr":"新宁县崀山景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游邵阳一带氛围拉满，晚餐崀山腊肉人均52元。","addr":"崀山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天一巷","description":"全天主景点天一巷，一线天最窄处仅33厘米。","addr":"崀山丹霞巷谷","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐血酱鸭（人均58元），早点休息。","addr":"新宁县城","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"扶夷江竹筏","description":"收官扶夷江竹筏，竹筏漂流看丹霞倒影。","addr":"崀山水上游线","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐脐橙后集合返程，三日旅程圆满。","addr":"崀山脚下果园","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"辣椒峰","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"辣椒峰是崀山最有代表性的看点，丹霞地貌标志峰，远观近爬两相宜。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌标志峰，远观近爬两相宜。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"新宁县崀山景区"},{"spotId":"S2","name":"天一巷","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"天一巷是崀山最有代表性的看点，一线天最窄处仅33厘米。攻略把它排进主线，时间留得最足。","notice":"一线天最窄处仅33厘米。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"崀山丹霞巷谷"},{"spotId":"S3","name":"扶夷江竹筏","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"扶夷江竹筏是崀山最有代表性的看点，竹筏漂流看丹霞倒影。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流看丹霞倒影。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"崀山水上游线"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"崀山腊肉（人均52元）","description":"邵阳 · 崀山的招牌是崀山腊肉，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"崀山镇"},{"title":"血酱鸭（人均58元）","description":"邵阳 · 崀山的招牌是血酱鸭，邵阳风味馆本地人都认这家，点单照攻略不踩雷。","addr":"新宁县城"},{"title":"脐橙（人均10元）","description":"邵阳 · 崀山的招牌是脐橙，果园直购本地人都认这家，点单照攻略不踩雷。","addr":"崀山脚下果园"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","相机或运动相机","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","少量零食补给","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('告庄西双景纯攻略·亲子篇2','guide','西双版纳 · 告庄西双景','sea','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',1500,800,6,'告庄星光夜市 / 曼听公园 / 中科院热带植物园 —— 纯攻略助你玩透告庄西双景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「告庄西双景」两日慢旅行——海滨。版纳小粒咖啡香浓不酸。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 西双版纳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴西双版纳","description":"集合出发，大巴直达告庄西双景，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"告庄星光夜市","description":"抵达后首游告庄星光夜市，大金塔下的东南亚最大夜市。","addr":"景洪市告庄西双景","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐菠萝饭（人均25元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"曼听公园","description":"早起人少，曼听公园精华时段，总佛寺相邻，晚场篝火晚会。","addr":"景洪市曼听路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香茅草烤鱼，人均48元，补充体力。","addr":"告庄内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"中科院热带植物园","description":"午后游览中科院热带植物园，王莲上坐一坐，热气球拍照。","addr":"勐腊县勐仑镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"告庄星光夜市","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"告庄星光夜市是告庄西双景最有代表性的看点，大金塔下的东南亚最大夜市。攻略把它排进主线，时间留得最足。","notice":"大金塔下的东南亚最大夜市。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"景洪市告庄西双景"},{"spotId":"S2","name":"曼听公园","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"曼听公园是告庄西双景最有代表性的看点，总佛寺相邻，晚场篝火晚会。攻略把它排进主线，时间留得最足。","notice":"总佛寺相邻，晚场篝火晚会。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"景洪市曼听路"},{"spotId":"S3","name":"中科院热带植物园","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"中科院热带植物园是告庄西双景最有代表性的看点，王莲上坐一坐，热气球拍照。攻略把它排进主线，时间留得最足。","notice":"王莲上坐一坐，热气球拍照。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"勐腊县勐仑镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"菠萝饭（人均25元）","description":"西双版纳 · 告庄西双景的招牌是菠萝饭，夜市傣味摊本地人都认这家，点单照攻略不踩雷。","addr":"星光夜市"},{"title":"香茅草烤鱼（人均48元）","description":"西双版纳 · 告庄西双景的招牌是香茅草烤鱼，曼飞龙烤鸡本地人都认这家，点单照攻略不踩雷。","addr":"告庄内"},{"title":"泡鲁达（人均15元）","description":"西双版纳 · 告庄西双景的招牌是泡鲁达，傣家甜品店本地人都认这家，点单照攻略不踩雷。","addr":"大金塔旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机","轻便雨衣或折叠伞","防晒霜与遮阳帽"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 西双版纳 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阆中古城纯攻略·摄影机位2','guide','南充 · 阆中古城','ancient_town','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,1,'阆中古城 / 华光楼 / 锦屏山 —— 纯攻略助你玩透阆中古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阆中古城」三日深度游——古镇。保宁醋是四大名醋之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 南充"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往南充，抵达后办理入住、熟悉周边环境。","addr":"南充市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"阆中古城","description":"下午首站阆中古城，调整状态进入旅行节奏，四大古城之一，张飞庙贡院联票。","addr":"南充市阆中市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游南充一带氛围拉满，晚餐张飞牛肉人均45元。","addr":"古城北街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"华光楼","description":"全天主景点华光楼，登楼看嘉陵江三面环抱。","addr":"古城上华街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐保宁醋（人均20元），早点休息。","addr":"古城内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"锦屏山","description":"收官锦屏山，观古城全景最佳位。","addr":"古城对岸","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐油香后集合返程，三日旅程圆满。","addr":"下沙河街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"阆中古城","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"阆中古城是阆中古城最有代表性的看点，四大古城之一，张飞庙贡院联票。攻略把它排进主线，时间留得最足。","notice":"四大古城之一，张飞庙贡院联票。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"南充市阆中市"},{"spotId":"S2","name":"华光楼","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"华光楼是阆中古城最有代表性的看点，登楼看嘉陵江三面环抱。攻略把它排进主线，时间留得最足。","notice":"登楼看嘉陵江三面环抱。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"古城上华街"},{"spotId":"S3","name":"锦屏山","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"锦屏山是阆中古城最有代表性的看点，观古城全景最佳位。攻略把它排进主线，时间留得最足。","notice":"观古城全景最佳位。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"古城对岸"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"张飞牛肉（人均45元）","description":"南充 · 阆中古城的招牌是张飞牛肉，张飞牛肉旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"古城北街"},{"title":"保宁醋（人均20元）","description":"南充 · 阆中古城的招牌是保宁醋，醋文化博览馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"油香（人均8元）","description":"南充 · 阆中古城的招牌是油香，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"下沙河街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","墨镜与拍照道具","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 南充 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 南充，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('镇远古镇纯攻略·美食清单2','guide','黔东南 · 镇远古镇','ancient_town','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1200,600,1,'青龙洞 / 舞阳河 / 石屏山 —— 纯攻略助你玩透镇远古镇精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「镇远古镇」两日慢旅行——古镇。镇远蓝染布艺越洗越好看。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔东南","description":"集合出发，大巴直达镇远古镇，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青龙洞","description":"抵达后首游青龙洞，贴崖古建筑群，对望古城。","addr":"镇远县中和山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐酸汤鱼（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"舞阳河","description":"早起人少，舞阳河精华时段，乘船看孔雀开屏峰。","addr":"镇远县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐陈年道菜，人均30元，补充体力。","addr":"古镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"石屏山","description":"午后游览石屏山，俯瞰太极古城全景。","addr":"古城北侧","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青龙洞","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"青龙洞是镇远古镇最有代表性的看点，贴崖古建筑群，对望古城。攻略把它排进主线，时间留得最足。","notice":"贴崖古建筑群，对望古城。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"镇远县中和山"},{"spotId":"S2","name":"舞阳河","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"舞阳河是镇远古镇最有代表性的看点，乘船看孔雀开屏峰。攻略把它排进主线，时间留得最足。","notice":"乘船看孔雀开屏峰。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"镇远县"},{"spotId":"S3","name":"石屏山","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"石屏山是镇远古镇最有代表性的看点，俯瞰太极古城全景。攻略把它排进主线，时间留得最足。","notice":"俯瞰太极古城全景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"古城北侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均58元）","description":"黔东南 · 镇远古镇的招牌是酸汤鱼，古城酸汤馆本地人都认这家，点单照攻略不踩雷。","addr":"兴隆街"},{"title":"陈年道菜（人均30元）","description":"黔东南 · 镇远古镇的招牌是陈年道菜，老字号本地人都认这家，点单照攻略不踩雷。","addr":"古镇主街"},{"title":"苗家腊肉（人均48元）","description":"黔东南 · 镇远古镇的招牌是苗家腊肉，河畔农家本地人都认这家，点单照攻略不踩雷。","addr":"舞阳河畔"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","墨镜与拍照道具","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["几月份去 黔东南 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('鼓浪屿纯攻略·自由行手册2','guide','厦门 · 鼓浪屿','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',2500,1300,6,'日光岩 / 菽庄花园 / 沙坡尾 —— 纯攻略助你玩透鼓浪屿精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「鼓浪屿」三日深度游——海滨。厦门馅饼老字号最正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 厦门"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往厦门，抵达后办理入住、熟悉周边环境。","addr":"厦门市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"日光岩","description":"下午首站日光岩，调整状态进入旅行节奏，全岛最高点看红瓦绿树海景。","addr":"鼓浪屿龙头山路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游厦门一带氛围拉满，晚餐沙茶面人均28元。","addr":"民族路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"菽庄花园","description":"全天主景点菽庄花园，四十四桥跨海，钢琴博物馆。","addr":"鼓浪屿港仔后路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海蛎煎（人均25元），早点休息。","addr":"八市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙坡尾","description":"收官沙坡尾，避风坞文艺街区，猫街涂鸦。","addr":"厦门市思明区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐土笋冻后集合返程，三日旅程圆满。","addr":"斗西路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"日光岩","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"日光岩是鼓浪屿最有代表性的看点，全岛最高点看红瓦绿树海景。攻略把它排进主线，时间留得最足。","notice":"全岛最高点看红瓦绿树海景。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"鼓浪屿龙头山路"},{"spotId":"S2","name":"菽庄花园","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"菽庄花园是鼓浪屿最有代表性的看点，四十四桥跨海，钢琴博物馆。攻略把它排进主线，时间留得最足。","notice":"四十四桥跨海，钢琴博物馆。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"鼓浪屿港仔后路"},{"spotId":"S3","name":"沙坡尾","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"沙坡尾是鼓浪屿最有代表性的看点，避风坞文艺街区，猫街涂鸦。攻略把它排进主线，时间留得最足。","notice":"避风坞文艺街区，猫街涂鸦。这个点位上午光线最好。","durationMinutes":120,"addr":"厦门市思明区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"沙茶面（人均28元）","description":"厦门 · 鼓浪屿的招牌是沙茶面，乌糖沙茶面本地人都认这家，点单照攻略不踩雷。","addr":"民族路"},{"title":"海蛎煎（人均25元）","description":"厦门 · 鼓浪屿的招牌是海蛎煎，莲欢海蛎煎本地人都认这家，点单照攻略不踩雷。","addr":"八市"},{"title":"土笋冻（人均15元）","description":"厦门 · 鼓浪屿的招牌是土笋冻，西门土笋冻本地人都认这家，点单照攻略不踩雷。","addr":"斗西路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","少量零食补给","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","相机或运动相机","墨镜与拍照道具","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 厦门，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雁荡山纯攻略·省钱玩法2','guide','温州 · 雁荡山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1990,1000,2,'灵峰 / 大龙湫 / 方洞栈道 —— 纯攻略助你玩透雁荡山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「雁荡山」两日慢旅行——山岳。雁荡山铁皮石斛有名。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 温州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴温州","description":"集合出发，大巴直达雁荡山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"灵峰","description":"抵达后首游灵峰，日景夜景两相宜，夫妻峰剪影。","addr":"乐清市雁荡山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐雁荡山石斑鱼（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大龙湫","description":"早起人少，大龙湫精华时段，190米瀑布，雨后最壮。","addr":"雁荡山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香鱼，人均48元，补充体力。","addr":"大龙湫下","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"方洞栈道","description":"午后游览方洞栈道，悬崖栈道悬空百米。","addr":"雁荡山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"灵峰","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"灵峰是雁荡山最有代表性的看点，日景夜景两相宜，夫妻峰剪影。攻略把它排进主线，时间留得最足。","notice":"日景夜景两相宜，夫妻峰剪影。这个点位上午光线最好。","durationMinutes":120,"addr":"乐清市雁荡山"},{"spotId":"S2","name":"大龙湫","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=