INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄山宏村纯攻略·避坑版2','guide','黄山 · 黄山宏村','mountain','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',990,500,2,'黄山光明顶 / 西海大峡谷 / 宏村 —— 纯攻略助你玩透黄山宏村精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「黄山宏村」三日深度游——山岳。徽墨歙砚文房收藏佳品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 黄山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黄山，抵达后办理入住、熟悉周边环境。","addr":"黄山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄山光明顶","description":"下午首站黄山光明顶，调整状态进入旅行节奏，看日出云海的主峰平台。","addr":"黄山市黄山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黄山一带氛围拉满，晚餐臭鳜鱼人均78元。","addr":"屯溪老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西海大峡谷","description":"全天主景点西海大峡谷，网红小火车，峡谷栈道惊险。","addr":"黄山风景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐毛豆腐（人均20元），早点休息。","addr":"宏村月沼旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"宏村","description":"收官宏村，月沼南湖水墨徽州，写生圣地。","addr":"黟县宏村镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐黄山烧饼后集合返程，三日旅程圆满。","addr":"汤口镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄山光明顶","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"黄山光明顶是黄山宏村最有代表性的看点，看日出云海的主峰平台。攻略把它排进主线，时间留得最足。","notice":"看日出云海的主峰平台。这个点位上午光线最好。","durationMinutes":300,"addr":"黄山市黄山区"},{"spotId":"S2","name":"西海大峡谷","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"西海大峡谷是黄山宏村最有代表性的看点，网红小火车，峡谷栈道惊险。攻略把它排进主线，时间留得最足。","notice":"网红小火车，峡谷栈道惊险。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"黄山风景区"},{"spotId":"S3","name":"宏村","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"宏村是黄山宏村最有代表性的看点，月沼南湖水墨徽州，写生圣地。攻略把它排进主线，时间留得最足。","notice":"月沼南湖水墨徽州，写生圣地。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"黟县宏村镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"臭鳜鱼（人均78元）","description":"黄山 · 黄山宏村的招牌是臭鳜鱼，老街第一楼本地人都认这家，点单照攻略不踩雷。","addr":"屯溪老街"},{"title":"毛豆腐（人均20元）","description":"黄山 · 黄山宏村的招牌是毛豆腐，徽州小吃本地人都认这家，点单照攻略不踩雷。","addr":"宏村月沼旁"},{"title":"黄山烧饼（人均12元）","description":"黄山 · 黄山宏村的招牌是黄山烧饼，救驾烧饼本地人都认这家，点单照攻略不踩雷。","addr":"汤口镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金","常用药品（肠胃药/创可贴）","少量零食补给","换洗衣物与外套（早晚温差）","相机或运动相机","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 黄山，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙门石窟纯攻略·深度指南2','guide','洛阳 · 龙门石窟','red','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,7,'龙门石窟 / 白马寺 / 洛邑古城 —— 纯攻略助你玩透龙门石窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙门石窟」两日慢旅行——人文。洛阳牡丹饼花香浓郁。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 洛阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴洛阳","description":"集合出发，大巴直达龙门石窟，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"龙门石窟","description":"抵达后首游龙门石窟，卢舍那大佛，夜游灯光版。","addr":"洛阳市洛龙区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐水席（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"白马寺","description":"早起人少，白马寺精华时段，中国第一古刹，国际佛殿。","addr":"洛阳市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牛肉汤，人均15元，补充体力。","addr":"瀍河区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"洛邑古城","description":"午后游览洛邑古城，汉服打卡圣地，夜景。","addr":"老城区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"龙门石窟","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"龙门石窟是龙门石窟最有代表性的看点，卢舍那大佛，夜游灯光版。攻略把它排进主线，时间留得最足。","notice":"卢舍那大佛，夜游灯光版。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"洛阳市洛龙区"},{"spotId":"S2","name":"白马寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"白马寺是龙门石窟最有代表性的看点，中国第一古刹，国际佛殿。攻略把它排进主线，时间留得最足。","notice":"中国第一古刹，国际佛殿。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"洛阳市"},{"spotId":"S3","name":"洛邑古城","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"洛邑古城是龙门石窟最有代表性的看点，汉服打卡圣地，夜景。攻略把它排进主线，时间留得最足。","notice":"汉服打卡圣地，夜景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"老城区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水席（人均88元）","description":"洛阳 · 龙门石窟的招牌是水席，真不同本地人都认这家，点单照攻略不踩雷。","addr":"老城区"},{"title":"牛肉汤（人均15元）","description":"洛阳 · 龙门石窟的招牌是牛肉汤，马杰山牛肉汤本地人都认这家，点单照攻略不踩雷。","addr":"瀍河区"},{"title":"不翻汤（人均12元）","description":"洛阳 · 龙门石窟的招牌是不翻汤，十字街夜市本地人都认这家，点单照攻略不踩雷。","addr":"老城十字街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","少量零食补给","防晒霜与遮阳帽","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 洛阳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('平遥古城纯攻略·周末版2','guide','晋中 · 平遥古城','ancient_town','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',990,500,1,'平遥古城墙 / 日升昌票号 / 协同庆地下金库 —— 纯攻略助你玩透平遥古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「平遥古城」三日深度游——古镇。平遥推光漆器手工至极。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 晋中"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往晋中，抵达后办理入住、熟悉周边环境。","addr":"晋中市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"平遥古城墙","description":"下午首站平遥古城墙，调整状态进入旅行节奏，完整明代城墙，骑行一周。","addr":"晋中市平遥县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游晋中一带氛围拉满，晚餐平遥牛肉人均45元。","addr":"古城南大街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"日升昌票号","description":"全天主景点日升昌票号，中国第一家票号，晋商传奇。","addr":"古城西大街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐碗托（人均12元），早点休息。","addr":"城隍庙街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"协同庆地下金库","description":"收官协同庆地下金库，探秘地下金库。","addr":"古城市楼旁","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐莜面栲栳栳后集合返程，三日旅程圆满。","addr":"西大街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"平遥古城墙","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"平遥古城墙是平遥古城最有代表性的看点，完整明代城墙，骑行一周。攻略把它排进主线，时间留得最足。","notice":"完整明代城墙，骑行一周。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"晋中市平遥县"},{"spotId":"S2","name":"日升昌票号","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"日升昌票号是平遥古城最有代表性的看点，中国第一家票号，晋商传奇。攻略把它排进主线，时间留得最足。","notice":"中国第一家票号，晋商传奇。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"古城西大街"},{"spotId":"S3","name":"协同庆地下金库","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"协同庆地下金库是平遥古城最有代表性的看点，探秘地下金库。攻略把它排进主线，时间留得最足。","notice":"探秘地下金库。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"古城市楼旁"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"平遥牛肉（人均45元）","description":"晋中 · 平遥古城的招牌是平遥牛肉，冠云专卖店本地人都认这家，点单照攻略不踩雷。","addr":"古城南大街"},{"title":"碗托（人均12元）","description":"晋中 · 平遥古城的招牌是碗托，碗托娘子本地人都认这家，点单照攻略不踩雷。","addr":"城隍庙街"},{"title":"莜面栲栳栳（人均28元）","description":"晋中 · 平遥古城的招牌是莜面栲栳栳，晋菜馆本地人都认这家，点单照攻略不踩雷。","addr":"西大街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","身份证件与手机充电宝","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图"],"faqs":[["当地有什么必吃？","到了 晋中，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 晋中 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('北戴河阿那亚纯攻略·亲子篇2','guide','秦皇岛 · 北戴河阿那亚','sea','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,6,'阿那亚礼堂 / 鸽子窝公园 / 山海关天下第一关 —— 纯攻略助你玩透北戴河阿那亚精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「北戴河阿那亚」两日慢旅行——海滨。北戴河干海参实惠。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 秦皇岛"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴秦皇岛","description":"集合出发，大巴直达北戴河阿那亚，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"阿那亚礼堂","description":"抵达后首游阿那亚礼堂，海边白色礼堂，孤独图书馆。","addr":"秦皇岛市昌黎县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐海鲜烧烤（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"鸽子窝公园","description":"早起人少，鸽子窝公园精华时段，观鸟湿地日出圣地。","addr":"北戴河区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐四条包子，人均12元，补充体力。","addr":"山海关","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"山海关天下第一关","description":"午后游览山海关天下第一关，长城入海老龙头。","addr":"山海关区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"阿那亚礼堂","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"阿那亚礼堂是北戴河阿那亚最有代表性的看点，海边白色礼堂，孤独图书馆。攻略把它排进主线，时间留得最足。","notice":"海边白色礼堂，孤独图书馆。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"秦皇岛市昌黎县"},{"spotId":"S2","name":"鸽子窝公园","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"鸽子窝公园是北戴河阿那亚最有代表性的看点，观鸟湿地日出圣地。攻略把它排进主线，时间留得最足。","notice":"观鸟湿地日出圣地。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"北戴河区"},{"spotId":"S3","name":"山海关天下第一关","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"山海关天下第一关是北戴河阿那亚最有代表性的看点，长城入海老龙头。攻略把它排进主线，时间留得最足。","notice":"长城入海老龙头。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"山海关区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜烧烤（人均68元）","description":"秦皇岛 · 北戴河阿那亚的招牌是海鲜烧烤，刘庄夜市本地人都认这家，点单照攻略不踩雷。","addr":"北戴河刘庄"},{"title":"四条包子（人均12元）","description":"秦皇岛 · 北戴河阿那亚的招牌是四条包子，四条包子铺本地人都认这家，点单照攻略不踩雷。","addr":"山海关"},{"title":"杨肠子（人均25元）","description":"秦皇岛 · 北戴河阿那亚的招牌是杨肠子，火腿肠老字号本地人都认这家，点单照攻略不踩雷。","addr":"北戴河"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","相机或运动相机","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","常用药品（肠胃药/创可贴）","保温水杯与少量现金","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 秦皇岛 的交通方便吗？","推荐先到 秦皇岛，再打车或景区直通车前往核心景区；自驾导航直接搜北戴河阿那亚即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('洪崖洞夜景纯攻略·摄影机位2','guide','渝中 · 洪崖洞夜景','food','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1200,600,3,'洪崖洞 / 长江索道 / 山城步道 —— 纯攻略助你玩透洪崖洞夜景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「洪崖洞夜景」三日深度游——美食。重庆火锅底料真空包装。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 渝中"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往渝中，抵达后办理入住、熟悉周边环境。","addr":"渝中市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"洪崖洞","description":"下午首站洪崖洞，调整状态进入旅行节奏，千与千寻同款夜景，对岸拍全景。","addr":"渝中区嘉陵江畔","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游渝中一带氛围拉满，晚餐重庆火锅人均98元。","addr":"解放碑","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长江索道","description":"全天主景点长江索道，空中横渡长江，排队1小时。","addr":"渝中区新华路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐重庆小面（人均15元），早点休息。","addr":"民生路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"山城步道","description":"收官山城步道，第三步道悬空栈道看老重庆。","addr":"渝中区中兴路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸辣粉后集合返程，三日旅程圆满。","addr":"八一路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"洪崖洞","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"洪崖洞是洪崖洞夜景最有代表性的看点，千与千寻同款夜景，对岸拍全景。攻略把它排进主线，时间留得最足。","notice":"千与千寻同款夜景，对岸拍全景。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"渝中区嘉陵江畔"},{"spotId":"S2","name":"长江索道","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"长江索道是洪崖洞夜景最有代表性的看点，空中横渡长江，排队1小时。攻略把它排进主线，时间留得最足。","notice":"空中横渡长江，排队1小时。这个点位上午光线最好。","durationMinutes":60,"addr":"渝中区新华路"},{"spotId":"S3","name":"山城步道","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"山城步道是洪崖洞夜景最有代表性的看点，第三步道悬空栈道看老重庆。攻略把它排进主线，时间留得最足。","notice":"第三步道悬空栈道看老重庆。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"渝中区中兴路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"重庆火锅（人均98元）","description":"渝中 · 洪崖洞夜景的招牌是重庆火锅，佩姐老火锅本地人都认这家，点单照攻略不踩雷。","addr":"解放碑"},{"title":"重庆小面（人均15元）","description":"渝中 · 洪崖洞夜景的招牌是重庆小面，花市豌杂面本地人都认这家，点单照攻略不踩雷。","addr":"民生路"},{"title":"酸辣粉（人均12元）","description":"渝中 · 洪崖洞夜景的招牌是酸辣粉，好又来酸辣粉本地人都认这家，点单照攻略不踩雷。","addr":"八一路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","轻便雨衣或折叠伞","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","少量零食补给","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('赛里木湖纯攻略·美食清单2','guide','伊犁 · 赛里木湖','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',2500,1300,2,'赛里木湖 / 果子沟大桥 / 霍尔果斯口岸 —— 纯攻略助你玩透赛里木湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「赛里木湖」两日慢旅行——水景。伊犁薰衣草精油真香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 伊犁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴伊犁","description":"集合出发，大巴直达赛里木湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"赛里木湖","description":"抵达后首游赛里木湖，大西洋最后一滴眼泪，环湖骑行。","addr":"博乐市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐高白鲑（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"果子沟大桥","description":"早起人少，果子沟大桥精华时段，空中巨龙，观景台打卡。","addr":"霍城县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤包子，人均10元，补充体力。","addr":"果子沟","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"霍尔果斯口岸","description":"午后游览霍尔果斯口岸，中哈边境免税购物。","addr":"霍尔果斯市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"赛里木湖","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"赛里木湖是赛里木湖最有代表性的看点，大西洋最后一滴眼泪，环湖骑行。攻略把它排进主线，时间留得最足。","notice":"大西洋最后一滴眼泪，环湖骑行。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"博乐市"},{"spotId":"S2","name":"果子沟大桥","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"果子沟大桥是赛里木湖最有代表性的看点，空中巨龙，观景台打卡。攻略把它排进主线，时间留得最足。","notice":"空中巨龙，观景台打卡。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"霍城县"},{"spotId":"S3","name":"霍尔果斯口岸","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"霍尔果斯口岸是赛里木湖最有代表性的看点，中哈边境免税购物。攻略把它排进主线，时间留得最足。","notice":"中哈边境免税购物。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"霍尔果斯市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"高白鲑（人均88元）","description":"伊犁 · 赛里木湖的招牌是高白鲑，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"赛里木湖"},{"title":"烤包子（人均10元）","description":"伊犁 · 赛里木湖的招牌是烤包子，维族馕坑本地人都认这家，点单照攻略不踩雷。","addr":"果子沟"},{"title":"马奶酒（人均25元）","description":"伊犁 · 赛里木湖的招牌是马奶酒，牧民家本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","相机或运动相机","墨镜与拍照道具","防晒霜与遮阳帽","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 伊犁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 伊犁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('长白山纯攻略·自由行手册2','guide','延边 · 长白山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1990,1000,2,'天池北坡 / 长白瀑布 / 绿渊潭 —— 纯攻略助你玩透长白山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「长白山」三日深度游——山岳。长白山林下参滋补。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"吉林 · 延边"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往延边，抵达后办理入住、熟悉周边环境。","addr":"延边市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"天池北坡","description":"下午首站天池北坡，调整状态进入旅行节奏，长白山主峰天池，天气好才能见。","addr":"延边州安图县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游延边一带氛围拉满，晚餐朝鲜冷面人均22元。","addr":"二道白河镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长白瀑布","description":"全天主景点长白瀑布，68米瀑布与温泉煮蛋。","addr":"北坡景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐石锅拌饭（人均28元），早点休息。","addr":"延吉市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"绿渊潭","description":"收官绿渊潭，碧绿水潭与飞瀑。","addr":"北坡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐温泉煮蛋后集合返程，三日旅程圆满。","addr":"北坡","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"天池北坡","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"天池北坡是长白山最有代表性的看点，长白山主峰天池，天气好才能见。攻略把它排进主线，时间留得最足。","notice":"长白山主峰天池，天气好才能见。这个点位上午光线最好。","durationMinutes":240,"addr":"延边州安图县"},{"spotId":"S2","name":"长白瀑布","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"长白瀑布是长白山最有代表性的看点，68米瀑布与温泉煮蛋。攻略把它排进主线，时间留得最足。","notice":"68米瀑布与温泉煮蛋。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"北坡景区"},{"spotId":"S3","name":"绿渊潭","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"绿渊潭是长白山最有代表性的看点，碧绿水潭与飞瀑。攻略把它排进主线，时间留得最足。","notice":"碧绿水潭与飞瀑。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"北坡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"朝鲜冷面（人均22元）","description":"延边 · 长白山的招牌是朝鲜冷面，服务大楼冷面本地人都认这家，点单照攻略不踩雷。","addr":"二道白河镇"},{"title":"石锅拌饭（人均28元）","description":"延边 · 长白山的招牌是石锅拌饭，金达莱餐厅本地人都认这家，点单照攻略不踩雷。","addr":"延吉市"},{"title":"温泉煮蛋（人均10元）","description":"延边 · 长白山的招牌是温泉煮蛋，瀑布温泉口本地人都认这家，点单照攻略不踩雷。","addr":"北坡"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","防晒霜与遮阳帽","少量零食补给","相机或运动相机","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 延边 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('井冈山纯攻略·省钱玩法3','guide','吉安 · 井冈山','red','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,7,'黄洋界 / 茨坪革命旧址群 / 龙潭 —— 纯攻略助你玩透井冈山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「井冈山」两日慢旅行——人文。井冈山竹制工艺品轻便好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 吉安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴吉安","description":"集合出发，大巴直达井冈山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄洋界","description":"抵达后首游黄洋界，保卫战旧址，云海出现率高。","addr":"井冈山市黄洋界景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红米饭南瓜汤（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"茨坪革命旧址群","description":"早起人少，茨坪革命旧址群精华时段，旧址集中，步行串游。","addr":"井冈山市茨坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐井冈烟笋，人均38元，补充体力。","addr":"黄洋界山下餐馆","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙潭","description":"午后游览龙潭，五潭十八瀑，索道省力。","addr":"井冈山龙潭景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄洋界","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"黄洋界是井冈山最有代表性的看点，保卫战旧址，云海出现率高。攻略把它排进主线，时间留得最足。","notice":"保卫战旧址，云海出现率高。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"井冈山市黄洋界景区"},{"spotId":"S2","name":"茨坪革命旧址群","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"茨坪革命旧址群是井冈山最有代表性的看点，旧址集中，步行串游。攻略把它排进主线，时间留得最足。","notice":"旧址集中，步行串游。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"井冈山市茨坪镇"},{"spotId":"S3","name":"龙潭","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"龙潭是井冈山最有代表性的看点，五潭十八瀑，索道省力。攻略把它排进主线，时间留得最足。","notice":"五潭十八瀑，索道省力。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"井冈山龙潭景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红米饭南瓜汤（人均45元）","description":"吉安 · 井冈山的招牌是红米饭南瓜汤，老乡家常菜本地人都认这家，点单照攻略不踩雷。","addr":"茨坪天街"},{"title":"井冈烟笋（人均38元）","description":"吉安 · 井冈山的招牌是井冈烟笋，山上饭庄本地人都认这家，点单照攻略不踩雷。","addr":"黄洋界山下餐馆"},{"title":"石鸡炖汤（人均88元）","description":"吉安 · 井冈山的招牌是石鸡炖汤，龙潭农庄本地人都认这家，点单照攻略不踩雷。","addr":"龙潭景区入口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","常用药品（肠胃药/创可贴）","墨镜与拍照道具","防晒霜与遮阳帽","保温水杯与少量现金","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 吉安 的交通方便吗？","推荐先到 吉安，再打车或景区直通车前往核心景区；自驾导航直接搜井冈山即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 吉安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大觉山纯攻略·避坑版3','guide','抚州 · 大觉山','adventure','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2990,1600,9,'大觉山漂流 / 大觉岩寺 / 古镇影视城 —— 纯攻略助你玩透大觉山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大觉山」三日深度游——探险地。资溪面包是当地人的骄傲。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 抚州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往抚州，抵达后办理入住、熟悉周边环境。","addr":"抚州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大觉山漂流","description":"下午首站大觉山漂流，调整状态进入旅行节奏，华东第一漂，全程3.5公里带好换洗衣。","addr":"资溪县大觉山景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游抚州一带氛围拉满，晚餐资溪面包人均15元。","addr":"资溪县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大觉岩寺","description":"全天主景点大觉岩寺，悬崖上的古寺，索道直达。","addr":"大觉山主峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐笋干烧肉（人均48元），早点休息。","addr":"大觉山游客中心","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古镇影视城","description":"收官古镇影视城，仿宋古镇，拍照出片。","addr":"大觉山脚下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐发酵豆腐后集合返程，三日旅程圆满。","addr":"影视城内街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大觉山漂流","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"大觉山漂流是大觉山最有代表性的看点，华东第一漂，全程3.5公里带好换洗衣。攻略把它排进主线，时间留得最足。","notice":"华东第一漂，全程3.5公里带好换洗衣。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"资溪县大觉山景区"},{"spotId":"S2","name":"大觉岩寺","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大觉岩寺是大觉山最有代表性的看点，悬崖上的古寺，索道直达。攻略把它排进主线，时间留得最足。","notice":"悬崖上的古寺，索道直达。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"大觉山主峰"},{"spotId":"S3","name":"古镇影视城","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"古镇影视城是大觉山最有代表性的看点，仿宋古镇，拍照出片。攻略把它排进主线，时间留得最足。","notice":"仿宋古镇，拍照出片。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"大觉山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"资溪面包（人均15元）","description":"抚州 · 大觉山的招牌是资溪面包，面包之乡旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"资溪县城"},{"title":"笋干烧肉（人均48元）","description":"抚州 · 大觉山的招牌是笋干烧肉，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"大觉山游客中心"},{"title":"发酵豆腐（人均18元）","description":"抚州 · 大觉山的招牌是发酵豆腐，古镇豆坊本地人都认这家，点单照攻略不踩雷。","addr":"影视城内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","墨镜与拍照道具","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["几月份去 抚州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 抚州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳阳楼洞庭湖纯攻略·深度指南3','guide','岳阳 · 岳阳楼洞庭湖','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,2,'岳阳楼 / 君山岛 / 圣安寺 —— 纯攻略助你玩透岳阳楼洞庭湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「岳阳楼洞庭湖」两日慢旅行——水景。君山银针是十大名茶之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 岳阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴岳阳","description":"集合出发，大巴直达岳阳楼洞庭湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"岳阳楼","description":"抵达后首游岳阳楼，洞庭天下水岳阳天下楼，背岳阳楼记免票。","addr":"岳阳市岳阳楼区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐洞庭鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"君山岛","description":"早起人少，君山岛精华时段，湘妃竹与银针茶的故乡。","addr":"洞庭湖君山岛","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐君山银针鸡片，人均68元，补充体力。","addr":"君山岛上","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"圣安寺","description":"午后游览圣安寺，古塔与湖景同框。","addr":"岳阳市南湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"岳阳楼","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"岳阳楼是岳阳楼洞庭湖最有代表性的看点，洞庭天下水岳阳天下楼，背岳阳楼记免票。攻略把它排进主线，时间留得最足。","notice":"洞庭天下水岳阳天下楼，背岳阳楼记免票。这个点位上午光线最好。","durationMinutes":90,"addr":"岳阳市岳阳楼区"},{"spotId":"S2","name":"君山岛","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"君山岛是岳阳楼洞庭湖最有代表性的看点，湘妃竹与银针茶的故乡。攻略把它排进主线，时间留得最足。","notice":"湘妃竹与银针茶的故乡。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"洞庭湖君山岛"},{"spotId":"S3","name":"圣安寺","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"圣安寺是岳阳楼洞庭湖最有代表性的看点，古塔与湖景同框。攻略把它排进主线，时间留得最足。","notice":"古塔与湖景同框。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"岳阳市南湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"洞庭鱼头（人均78元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是洞庭鱼头，巴陵全鱼席本地人都认这家，点单照攻略不踩雷。","addr":"岳阳楼景区旁"},{"title":"君山银针鸡片（人均68元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是君山银针鸡片，茶宴馆本地人都认这家，点单照攻略不踩雷。","addr":"君山岛上"},{"title":"岳阳虾饼（人均10元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是岳阳虾饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"汴河街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","相机或运动相机","常用药品（肠胃药/创可贴）","少量零食补给","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 岳阳 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 岳阳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('元阳哈尼梯田纯攻略·周末版3','guide','红河 · 元阳哈尼梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1990,1000,1,'多依树梯田 / 老虎嘴梯田 / 箐口哈尼民俗村 —— 纯攻略助你玩透元阳哈尼梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「元阳哈尼梯田」三日深度游——古村落。元阳红米营养丰富。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 红河"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往红河，抵达后办理入住、熟悉周边环境。","addr":"红河市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"多依树梯田","description":"下午首站多依树梯田，调整状态进入旅行节奏，日出云海最佳观赏点，提前1小时占位。","addr":"元阳县新街镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游红河一带氛围拉满，晚餐哈尼梯田红米人均35元。","addr":"多依树村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"老虎嘴梯田","description":"全天主景点老虎嘴梯田，日落时梯田变金色。","addr":"元阳县攀枝花乡","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐梯田鱼（人均58元），早点休息。","addr":"箐口村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"箐口哈尼民俗村","description":"收官箐口哈尼民俗村，蘑菇房与梯田同框。","addr":"元阳县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐竹筒鸡后集合返程，三日旅程圆满。","addr":"新街镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"多依树梯田","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"多依树梯田是元阳哈尼梯田最有代表性的看点，日出云海最佳观赏点，提前1小时占位。攻略把它排进主线，时间留得最足。","notice":"日出云海最佳观赏点，提前1小时占位。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"元阳县新街镇"},{"spotId":"S2","name":"老虎嘴梯田","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"老虎嘴梯田是元阳哈尼梯田最有代表性的看点，日落时梯田变金色。攻略把它排进主线，时间留得最足。","notice":"日落时梯田变金色。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"元阳县攀枝花乡"},{"spotId":"S3","name":"箐口哈尼民俗村","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"箐口哈尼民俗村是元阳哈尼梯田最有代表性的看点，蘑菇房与梯田同框。攻略把它排进主线，时间留得最足。","notice":"蘑菇房与梯田同框。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"元阳县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"哈尼梯田红米（人均35元）","description":"红河 · 元阳哈尼梯田的招牌是哈尼梯田红米，农家餐厅本地人都认这家，点单照攻略不踩雷。","addr":"多依树村"},{"title":"梯田鱼（人均58元）","description":"红河 · 元阳哈尼梯田的招牌是梯田鱼，村中渔家本地人都认这家，点单照攻略不踩雷。","addr":"箐口村"},{"title":"竹筒鸡（人均68元）","description":"红河 · 元阳哈尼梯田的招牌是竹筒鸡，哈尼农家本地人都认这家，点单照攻略不踩雷。","addr":"新街镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道"],"faqs":[["到达 红河 的交通方便吗？","推荐先到 红河，再打车或景区直通车前往核心景区；自驾导航直接搜元阳哈尼梯田即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('四姑娘山纯攻略·亲子篇3','guide','阿坝 · 四姑娘山','mountain','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',990,500,2,'双桥沟 / 长坪沟 / 猫鼻梁 —— 纯攻略助你玩透四姑娘山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「四姑娘山」两日慢旅行——山岳。四姑娘山沙棘汁酸爽提神。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达四姑娘山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"双桥沟","description":"抵达后首游双桥沟，坐观光车看雪山峡谷，最省力。","addr":"四姑娘山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏式火锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"长坪沟","description":"早起人少，长坪沟精华时段，木栈道进山，幺妹峰侧面。","addr":"四姑娘山镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牦牛肉干，人均45元，补充体力。","addr":"镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"猫鼻梁","description":"午后游览猫鼻梁，四峰全景最佳机位。","addr":"去四姑娘山路途","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"双桥沟","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"双桥沟是四姑娘山最有代表性的看点，坐观光车看雪山峡谷，最省力。攻略把它排进主线，时间留得最足。","notice":"坐观光车看雪山峡谷，最省力。这个点位上午光线最好。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S2","name":"长坪沟","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=