INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌蒙大草原纯攻略·摄影机位3','guide','六盘水 · 乌蒙大草原','camp','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1990,1000,10,'乌蒙大草原 / 野玉海 / 娘娘山 —— 纯攻略助你玩透乌蒙大草原精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「乌蒙大草原」三日深度游——露营地。六盘水刺梨维C之王。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 六盘水"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往六盘水，抵达后办理入住、熟悉周边环境。","addr":"六盘水市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"乌蒙大草原","description":"下午首站乌蒙大草原，调整状态进入旅行节奏，云上花海佛光，露营星空。","addr":"六盘水市盘州市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游六盘水一带氛围拉满，晚餐水城烙锅人均45元。","addr":"水城区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"野玉海","description":"全天主景点野玉海，海坪彝族小镇与观光小火车。","addr":"水城区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊肉粉（人均15元），早点休息。","addr":"盘州市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"娘娘山","description":"收官娘娘山，高原湿地与温泉。","addr":"盘州市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐刺梨汁后集合返程，三日旅程圆满。","addr":"全区通用","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"乌蒙大草原","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"乌蒙大草原是乌蒙大草原最有代表性的看点，云上花海佛光，露营星空。攻略把它排进主线，时间留得最足。","notice":"云上花海佛光，露营星空。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"六盘水市盘州市"},{"spotId":"S2","name":"野玉海","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"野玉海是乌蒙大草原最有代表性的看点，海坪彝族小镇与观光小火车。攻略把它排进主线，时间留得最足。","notice":"海坪彝族小镇与观光小火车。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"水城区"},{"spotId":"S3","name":"娘娘山","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"娘娘山是乌蒙大草原最有代表性的看点，高原湿地与温泉。攻略把它排进主线，时间留得最足。","notice":"高原湿地与温泉。这个点位上午光线最好。","durationMinutes":120,"addr":"盘州市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水城烙锅（人均45元）","description":"六盘水 · 乌蒙大草原的招牌是水城烙锅，烙锅一条街本地人都认这家，点单照攻略不踩雷。","addr":"水城区"},{"title":"羊肉粉（人均15元）","description":"六盘水 · 乌蒙大草原的招牌是羊肉粉，元坤羊肉粉本地人都认这家，点单照攻略不踩雷。","addr":"盘州市"},{"title":"刺梨汁（人均10元）","description":"六盘水 · 乌蒙大草原的招牌是刺梨汁，维C宝饮品本地人都认这家，点单照攻略不踩雷。","addr":"全区通用"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","防晒霜与遮阳帽","墨镜与拍照道具","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待"],"faqs":[["到达 六盘水 的交通方便吗？","推荐先到 六盘水，再打车或景区直通车前往核心景区；自驾导航直接搜乌蒙大草原即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 六盘水 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武夷山纯攻略·美食清单3','guide','南平 · 武夷山','mountain','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',2990,1600,2,'九曲溪竹筏 / 天游峰 / 大红袍景区 —— 纯攻略助你玩透武夷山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武夷山」两日慢旅行——山岳。正岩大红袍认准九龙窠。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 南平"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南平","description":"集合出发，大巴直达武夷山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"九曲溪竹筏","description":"抵达后首游九曲溪竹筏，90分钟漂流过九曲十八弯。","addr":"武夷山市星村镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐武夷山熏鹅（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天游峰","description":"早起人少，天游峰精华时段，闽山第一峰，云窝上看溪湾。","addr":"武夷山风景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐紫溪粉，人均15元，补充体力。","addr":"三姑街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大红袍景区","description":"午后游览大红袍景区，母树大红袍，岩谷花香步道。","addr":"武夷山九龙窠","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"九曲溪竹筏","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"九曲溪竹筏是武夷山最有代表性的看点，90分钟漂流过九曲十八弯。攻略把它排进主线，时间留得最足。","notice":"90分钟漂流过九曲十八弯。这个点位上午光线最好。","durationMinutes":180,"addr":"武夷山市星村镇"},{"spotId":"S2","name":"天游峰","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"天游峰是武夷山最有代表性的看点，闽山第一峰，云窝上看溪湾。攻略把它排进主线，时间留得最足。","notice":"闽山第一峰，云窝上看溪湾。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"武夷山风景区"},{"spotId":"S3","name":"大红袍景区","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"大红袍景区是武夷山最有代表性的看点，母树大红袍，岩谷花香步道。攻略把它排进主线，时间留得最足。","notice":"母树大红袍，岩谷花香步道。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"武夷山九龙窠"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"武夷山熏鹅（人均48元）","description":"南平 · 武夷山的招牌是武夷山熏鹅，岚谷熏鹅店本地人都认这家，点单照攻略不踩雷。","addr":"度假区"},{"title":"紫溪粉（人均15元）","description":"南平 · 武夷山的招牌是紫溪粉，小吃店本地人都认这家，点单照攻略不踩雷。","addr":"三姑街"},{"title":"文公菜（人均58元）","description":"南平 · 武夷山的招牌是文公菜，朱子家宴本地人都认这家，点单照攻略不踩雷。","addr":"武夷宫旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","换洗衣物与外套（早晚温差）","墨镜与拍照道具","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('莫干山纯攻略·自由行手册3','guide','湖州 · 莫干山','village','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',2500,1300,1,'莫干山风景区 / 庾村文化市集 / 下渚湖湿地公园 —— 纯攻略助你玩透莫干山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「莫干山」三日深度游——古村落。莫干山黄芽茶清雅。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 湖州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往湖州，抵达后办理入住、熟悉周边环境。","addr":"湖州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫干山风景区","description":"下午首站莫干山风景区，调整状态进入旅行节奏，民国别墅群与竹海，剑池飞瀑。","addr":"湖州市德清县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游湖州一带氛围拉满，晚餐笋干烧肉人均58元。","addr":"莫干山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"庾村文化市集","description":"全天主景点庾村文化市集，文创小铺与骑行路线。","addr":"德清县莫干山镇","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐竹林土鸡煲（人均88元），早点休息。","addr":"劳岭村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"下渚湖湿地公园","description":"收官下渚湖湿地公园，朱鹮栖息地，芦苇迷宫。","addr":"德清县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐德清醉鱼后集合返程，三日旅程圆满。","addr":"下渚湖","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫干山风景区","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"莫干山风景区是莫干山最有代表性的看点，民国别墅群与竹海，剑池飞瀑。攻略把它排进主线，时间留得最足。","notice":"民国别墅群与竹海，剑池飞瀑。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"湖州市德清县"},{"spotId":"S2","name":"庾村文化市集","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"庾村文化市集是莫干山最有代表性的看点，文创小铺与骑行路线。攻略把它排进主线，时间留得最足。","notice":"文创小铺与骑行路线。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"德清县莫干山镇"},{"spotId":"S3","name":"下渚湖湿地公园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"下渚湖湿地公园是莫干山最有代表性的看点，朱鹮栖息地，芦苇迷宫。攻略把它排进主线，时间留得最足。","notice":"朱鹮栖息地，芦苇迷宫。这个点位上午光线最好。","durationMinutes":120,"addr":"德清县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"笋干烧肉（人均58元）","description":"湖州 · 莫干山的招牌是笋干烧肉，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"莫干山镇"},{"title":"竹林土鸡煲（人均88元）","description":"湖州 · 莫干山的招牌是竹林土鸡煲，民宿餐厅本地人都认这家，点单照攻略不踩雷。","addr":"劳岭村"},{"title":"德清醉鱼（人均38元）","description":"湖州 · 莫干山的招牌是德清醉鱼，水产馆本地人都认这家，点单照攻略不踩雷。","addr":"下渚湖"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具","保温水杯与少量现金","轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）","身份证件与手机充电宝"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九华山纯攻略·省钱玩法3','guide','池州 · 九华山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,2,'肉身宝殿 / 百岁宫 / 花台栈道 —— 纯攻略助你玩透九华山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九华山」两日慢旅行——山岳。九华黄精是养生佳品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 池州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴池州","description":"集合出发，大巴直达九华山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"肉身宝殿","description":"抵达后首游肉身宝殿，地藏菩萨道场核心，99米地藏圣像。","addr":"池州市青阳县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐九华素斋（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"百岁宫","description":"早起人少，百岁宫精华时段，缆车直达，天然肉身佛。","addr":"九华街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐石耳炖鸡，人均78元，补充体力。","addr":"柯村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"花台栈道","description":"午后游览花台栈道，云海佛光频出。","addr":"九华山高空栈道","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"肉身宝殿","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"肉身宝殿是九华山最有代表性的看点，地藏菩萨道场核心，99米地藏圣像。攻略把它排进主线，时间留得最足。","notice":"地藏菩萨道场核心，99米地藏圣像。这个点位上午光线最好。","durationMinutes":180,"addr":"池州市青阳县"},{"spotId":"S2","name":"百岁宫","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"百岁宫是九华山最有代表性的看点，缆车直达，天然肉身佛。攻略把它排进主线，时间留得最足。","notice":"缆车直达，天然肉身佛。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"九华街"},{"spotId":"S3","name":"花台栈道","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"花台栈道是九华山最有代表性的看点，云海佛光频出。攻略把它排进主线，时间留得最足。","notice":"云海佛光频出。这个点位上午光线最好。","durationMinutes":120,"addr":"九华山高空栈道"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"九华素斋（人均38元）","description":"池州 · 九华山的招牌是九华素斋，化城寺素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"九华街"},{"title":"石耳炖鸡（人均78元）","description":"池州 · 九华山的招牌是石耳炖鸡，山间农家本地人都认这家，点单照攻略不踩雷。","addr":"柯村"},{"title":"黄精茶（人均30元）","description":"池州 · 九华山的招牌是黄精茶，特产店本地人都认这家，点单照攻略不踩雷。","addr":"九华新街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","少量零食补给","舒适徒步鞋（防滑鞋底）","相机或运动相机","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云台山纯攻略·避坑版3','guide','焦作 · 云台山','water','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',2500,1300,2,'红石峡 / 茱萸峰 / 潭瀑峡 —— 纯攻略助你玩透云台山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「云台山」三日深度游——水景。铁棍山药焦作温县最好。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 焦作"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往焦作，抵达后办理入住、熟悉周边环境。","addr":"焦作市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"红石峡","description":"下午首站红石峡，调整状态进入旅行节奏，红岩碧水盆景峡谷，人再多也值。","addr":"焦作市修武县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游焦作一带氛围拉满，晚餐驴肉面人均28元。","addr":"云台山岸上镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"茱萸峰","description":"全天主景点茱萸峰，王维遥知兄弟登高处。","addr":"云台山主峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐山药炖排骨（人均58元），早点休息。","addr":"修武县城","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"潭瀑峡","description":"收官潭瀑峡，三步一泉五步一瀑。","addr":"云台山","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐松花蛋后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"红石峡","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"红石峡是云台山最有代表性的看点，红岩碧水盆景峡谷，人再多也值。攻略把它排进主线，时间留得最足。","notice":"红岩碧水盆景峡谷，人再多也值。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"焦作市修武县"},{"spotId":"S2","name":"茱萸峰","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"茱萸峰是云台山最有代表性的看点，王维遥知兄弟登高处。攻略把它排进主线，时间留得最足。","notice":"王维遥知兄弟登高处。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"云台山主峰"},{"spotId":"S3","name":"潭瀑峡","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"潭瀑峡是云台山最有代表性的看点，三步一泉五步一瀑。攻略把它排进主线，时间留得最足。","notice":"三步一泉五步一瀑。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"云台山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉面（人均28元）","description":"焦作 · 云台山的招牌是驴肉面，修武驴肉馆本地人都认这家，点单照攻略不踩雷。","addr":"云台山岸上镇"},{"title":"山药炖排骨（人均58元）","description":"焦作 · 云台山的招牌是山药炖排骨，怀山药宴本地人都认这家，点单照攻略不踩雷。","addr":"修武县城"},{"title":"松花蛋（人均20元）","description":"焦作 · 云台山的招牌是松花蛋，特产店本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具","身份证件与手机充电宝","保温水杯与少量现金","少量零食补给","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 焦作，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五台山纯攻略·深度指南3','guide','忻州 · 五台山','mountain','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',2990,1600,2,'五爷庙 / 黛螺顶 / 显通寺 —— 纯攻略助你玩透五台山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「五台山」两日慢旅行——山岳。五台山台蘑干货珍贵。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 忻州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴忻州","description":"集合出发，大巴直达五台山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"五爷庙","description":"抵达后首游五爷庙，香火最旺许愿灵验，早去。","addr":"忻州市五台县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐台蘑炖山鸡（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"黛螺顶","description":"早起人少，黛螺顶精华时段，小朝台1080级台阶。","addr":"五台山台怀镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐莜面窝窝，人均22元，补充体力。","addr":"五台山镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"显通寺","description":"午后游览显通寺，五台山开山寺，铜殿铜塔。","addr":"台怀镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"五爷庙","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"五爷庙是五台山最有代表性的看点，香火最旺许愿灵验，早去。攻略把它排进主线，时间留得最足。","notice":"香火最旺许愿灵验，早去。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"忻州市五台县"},{"spotId":"S2","name":"黛螺顶","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"黛螺顶是五台山最有代表性的看点，小朝台1080级台阶。攻略把它排进主线，时间留得最足。","notice":"小朝台1080级台阶。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"五台山台怀镇"},{"spotId":"S3","name":"显通寺","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"显通寺是五台山最有代表性的看点，五台山开山寺，铜殿铜塔。攻略把它排进主线，时间留得最足。","notice":"五台山开山寺，铜殿铜塔。这个点位上午光线最好。","durationMinutes":90,"addr":"台怀镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"台蘑炖山鸡（人均88元）","description":"忻州 · 五台山的招牌是台蘑炖山鸡，山珍馆本地人都认这家，点单照攻略不踩雷。","addr":"台怀镇"},{"title":"莜面窝窝（人均22元）","description":"忻州 · 五台山的招牌是莜面窝窝，农家菜本地人都认这家，点单照攻略不踩雷。","addr":"五台山镇"},{"title":"素斋（人均28元）","description":"忻州 · 五台山的招牌是素斋，塔院寺素斋本地人都认这家，点单照攻略不踩雷。","addr":"塔院寺旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","墨镜与拍照道具","相机或运动相机","常用药品（肠胃药/创可贴）","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 忻州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙面陈家祠纯攻略·周末版3','guide','广州 · 沙面陈家祠','food','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',2500,1300,3,'陈家祠 / 沙面岛 / 永庆坊 —— 纯攻略助你玩透沙面陈家祠精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「沙面陈家祠」三日深度游——美食。广式腊味礼盒最体面。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 广州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往广州，抵达后办理入住、熟悉周边环境。","addr":"广州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"陈家祠","description":"下午首站陈家祠，调整状态进入旅行节奏，岭南建筑木雕巅峰。","addr":"广州市荔湾区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游广州一带氛围拉满，晚餐肠粉人均15元。","addr":"上九路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"沙面岛","description":"全天主景点沙面岛，欧陆建筑群，拍照圣地。","addr":"荔湾区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐虾饺（人均28元），早点休息。","addr":"第十甫路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"永庆坊","description":"收官永庆坊，西关骑楼与粤剧艺术博物馆。","addr":"恩宁路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐双皮奶后集合返程，三日旅程圆满。","addr":"第十甫路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"陈家祠","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"陈家祠是沙面陈家祠最有代表性的看点，岭南建筑木雕巅峰。攻略把它排进主线，时间留得最足。","notice":"岭南建筑木雕巅峰。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"广州市荔湾区"},{"spotId":"S2","name":"沙面岛","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"沙面岛是沙面陈家祠最有代表性的看点，欧陆建筑群，拍照圣地。攻略把它排进主线，时间留得最足。","notice":"欧陆建筑群，拍照圣地。这个点位上午光线最好。","durationMinutes":120,"addr":"荔湾区"},{"spotId":"S3","name":"永庆坊","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"永庆坊是沙面陈家祠最有代表性的看点，西关骑楼与粤剧艺术博物馆。攻略把它排进主线，时间留得最足。","notice":"西关骑楼与粤剧艺术博物馆。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"恩宁路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肠粉（人均15元）","description":"广州 · 沙面陈家祠的招牌是肠粉，银记肠粉本地人都认这家，点单照攻略不踩雷。","addr":"上九路"},{"title":"虾饺（人均28元）","description":"广州 · 沙面陈家祠的招牌是虾饺，陶陶居本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"},{"title":"双皮奶（人均15元）","description":"广州 · 沙面陈家祠的招牌是双皮奶，南信牛奶甜品本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具","身份证件与手机充电宝","轻便雨衣或折叠伞","保温水杯与少量现金","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武隆天坑纯攻略·亲子篇3','guide','武隆 · 武隆天坑','adventure','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,9,'天生三桥 / 仙女山 / 龙水峡地缝 —— 纯攻略助你玩透武隆天坑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武隆天坑」两日慢旅行——探险地。武隆羊角豆干麻辣够味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 武隆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴武隆","description":"集合出发，大巴直达武隆天坑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"天生三桥","description":"抵达后首游天生三桥，变形金刚取景地，天福官驿。","addr":"武隆区仙女山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐碗碗羊肉（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"仙女山","description":"早起人少，仙女山精华时段，南国第一牧原，草原骑马。","addr":"武隆区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐江口鱼，人均58元，补充体力。","addr":"江口镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙水峡地缝","description":"午后游览龙水峡地缝，80米深地缝一线天光。","addr":"仙女山镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"天生三桥","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"天生三桥是武隆天坑最有代表性的看点，变形金刚取景地，天福官驿。攻略把它排进主线，时间留得最足。","notice":"变形金刚取景地，天福官驿。这个点位上午光线最好。","durationMinutes":180,"addr":"武隆区仙女山镇"},{"spotId":"S2","name":"仙女山","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"仙女山是武隆天坑最有代表性的看点，南国第一牧原，草原骑马。攻略把它排进主线，时间留得最足。","notice":"南国第一牧原，草原骑马。这个点位上午光线最好。","durationMinutes":180,"addr":"武隆区"},{"spotId":"S3","name":"龙水峡地缝","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"龙水峡地缝是武隆天坑最有代表性的看点，80米深地缝一线天光。攻略把它排进主线，时间留得最足。","notice":"80米深地缝一线天光。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"仙女山镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"碗碗羊肉（人均38元）","description":"武隆 · 武隆天坑的招牌是碗碗羊肉，武隆碗碗羊肉本地人都认这家，点单照攻略不踩雷。","addr":"仙女山镇"},{"title":"江口鱼（人均58元）","description":"武隆 · 武隆天坑的招牌是江口鱼，乌江鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"江口镇"},{"title":"羊角豆干（人均15元）","description":"武隆 · 武隆天坑的招牌是羊角豆干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"武隆城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","保温水杯与少量现金","墨镜与拍照道具","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 武隆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 武隆 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
