INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('八达岭长城纯攻略·美食清单3','guide','延庆 · 八达岭长城','red','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',1500,800,7,'八达岭长城 / 明十三陵 / 居庸关花海 —— 纯攻略助你玩透八达岭长城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「八达岭长城」两日慢旅行——人文。北京果脯礼盒送长辈。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"北京 · 延庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延庆","description":"集合出发，大巴直达八达岭长城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"八达岭长城","description":"抵达后首游八达岭长城，好汉坡北八楼，缆车上下。","addr":"延庆区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐春饼宴（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"明十三陵","description":"早起人少，明十三陵精华时段，定陵地宫探秘。","addr":"昌平区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐火盆锅豆腐宴，人均48元，补充体力。","addr":"八达岭镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"居庸关花海","description":"午后游览居庸关花海，开往春天的列车。","addr":"昌平区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"八达岭长城","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"八达岭长城是八达岭长城最有代表性的看点，好汉坡北八楼，缆车上下。攻略把它排进主线，时间留得最足。","notice":"好汉坡北八楼，缆车上下。这个点位上午光线最好。","durationMinutes":240,"addr":"延庆区"},{"spotId":"S2","name":"明十三陵","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"明十三陵是八达岭长城最有代表性的看点，定陵地宫探秘。攻略把它排进主线，时间留得最足。","notice":"定陵地宫探秘。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"昌平区"},{"spotId":"S3","name":"居庸关花海","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"居庸关花海是八达岭长城最有代表性的看点，开往春天的列车。攻略把它排进主线，时间留得最足。","notice":"开往春天的列车。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"昌平区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"春饼宴（人均38元）","description":"延庆 · 八达岭长城的招牌是春饼宴，柳沟村豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"延庆柳沟"},{"title":"火盆锅豆腐宴（人均48元）","description":"延庆 · 八达岭长城的招牌是火盆锅豆腐宴，农家院本地人都认这家，点单照攻略不踩雷。","addr":"八达岭镇"},{"title":"玫瑰饼（人均15元）","description":"延庆 · 八达岭长城的招牌是玫瑰饼，妙峰山糕点本地人都认这家，点单照攻略不踩雷。","addr":"昌平"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["墨镜与拍照道具","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('庐山纯攻略·自由行手册3','guide','九江 · 庐山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',990,500,2,'锦绣谷 / 三叠泉 / 如琴湖花径 —— 纯攻略助你玩透庐山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「庐山」三日深度游——山岳。庐山云雾茶记得认准原产地标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 九江"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往九江，抵达后办理入住、熟悉周边环境。","addr":"九江市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"锦绣谷","description":"下午首站锦绣谷，调整状态进入旅行节奏，云雾多发地段，下午常被云海包裹。","addr":"庐山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游九江一带氛围拉满，晚餐庐山三石宴人均128元。","addr":"牯岭镇河西路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"三叠泉","description":"全天主景点三叠泉，不到三叠泉不算庐山客，往返台阶多。","addr":"庐山东南麓","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐茶饼（人均12元），早点休息。","addr":"牯岭镇正街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"如琴湖花径","description":"收官如琴湖花径，清晨人少出片，环湖半小时。","addr":"牯岭镇西侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐石耳炖鸡汤后集合返程，三日旅程圆满。","addr":"如琴湖旁农家","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"锦绣谷","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"锦绣谷是庐山最有代表性的看点，云雾多发地段，下午常被云海包裹。攻略把它排进主线，时间留得最足。","notice":"云雾多发地段，下午常被云海包裹。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"庐山风景区"},{"spotId":"S2","name":"三叠泉","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"三叠泉是庐山最有代表性的看点，不到三叠泉不算庐山客，往返台阶多。攻略把它排进主线，时间留得最足。","notice":"不到三叠泉不算庐山客，往返台阶多。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"庐山东南麓"},{"spotId":"S3","name":"如琴湖花径","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"如琴湖花径是庐山最有代表性的看点，清晨人少出片，环湖半小时。攻略把它排进主线，时间留得最足。","notice":"清晨人少出片，环湖半小时。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"牯岭镇西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"庐山三石宴（人均128元）","description":"九江 · 庐山的招牌是庐山三石宴，牯岭镇饭馆本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇河西路"},{"title":"茶饼（人均12元）","description":"九江 · 庐山的招牌是茶饼，云中街区小店本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇正街"},{"title":"石耳炖鸡汤（人均98元）","description":"九江 · 庐山的招牌是石耳炖鸡汤，山中食府本地人都认这家，点单照攻略不踩雷。","addr":"如琴湖旁农家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","防晒霜与遮阳帽","保温水杯与少量现金","常用药品（肠胃药/创可贴）","少量零食补给","舒适徒步鞋（防滑鞋底）","相机或运动相机","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 九江，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 九江 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('通天岩郁孤台纯攻略·省钱玩法3','guide','赣州 · 通天岩郁孤台','red','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',1990,1000,7,'通天岩 / 郁孤台 / 关西新围 —— 纯攻略助你玩透通天岩郁孤台精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「通天岩郁孤台」两日慢旅行——人文。赣南脐橙11月最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 赣州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴赣州","description":"集合出发，大巴直达通天岩郁孤台，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"通天岩","description":"抵达后首游通天岩，江南最大石窟群，丹岩丹霞。","addr":"赣州市章贡区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐赣南小炒鱼（人均42元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"郁孤台","description":"早起人少，郁孤台精华时段，辛弃疾词中圣地，宋城墙。","addr":"章贡区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐艾米果，人均10元，补充体力。","addr":"郁孤台街区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"关西新围","description":"午后游览关西新围，东方古堡围屋。","addr":"龙南市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"通天岩","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"通天岩是通天岩郁孤台最有代表性的看点，江南最大石窟群，丹岩丹霞。攻略把它排进主线，时间留得最足。","notice":"江南最大石窟群，丹岩丹霞。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"赣州市章贡区"},{"spotId":"S2","name":"郁孤台","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"郁孤台是通天岩郁孤台最有代表性的看点，辛弃疾词中圣地，宋城墙。攻略把它排进主线，时间留得最足。","notice":"辛弃疾词中圣地，宋城墙。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"章贡区"},{"spotId":"S3","name":"关西新围","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"关西新围是通天岩郁孤台最有代表性的看点，东方古堡围屋。攻略把它排进主线，时间留得最足。","notice":"东方古堡围屋。这个点位上午光线最好。","durationMinutes":120,"addr":"龙南市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"赣南小炒鱼（人均42元）","description":"赣州 · 通天岩郁孤台的招牌是赣南小炒鱼，赣州客家菜本地人都认这家，点单照攻略不踩雷。","addr":"章贡区"},{"title":"艾米果（人均10元）","description":"赣州 · 通天岩郁孤台的招牌是艾米果，街头点心本地人都认这家，点单照攻略不踩雷。","addr":"郁孤台街区"},{"title":"黄元米果（人均18元）","description":"赣州 · 通天岩郁孤台的招牌是黄元米果，赣南农家本地人都认这家，点单照攻略不踩雷。","addr":"龙南市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","换洗衣物与外套（早晚温差）","少量零食补给","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","相机或运动相机","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 赣州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('桃花源纯攻略·避坑版3','guide','常德 · 桃花源','village','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',1200,600,1,'桃花源古镇 / 桃源山 / 五柳湖 —— 纯攻略助你玩透桃花源精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「桃花源」三日深度游——古村落。桃源大叶茶配擂茶绝了。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 常德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往常德，抵达后办理入住、熟悉周边环境。","addr":"常德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"桃花源古镇","description":"下午首站桃花源古镇，调整状态进入旅行节奏，秦溪秦谷还原桃花源记场景。","addr":"常德市桃源县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游常德一带氛围拉满，晚餐常德米粉人均18元。","addr":"桃源县漳江镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"桃源山","description":"全天主景点桃源山，水府阁俯瞰沅江。","addr":"桃花源景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐擂茶（人均35元），早点休息。","addr":"桃花源古镇内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"五柳湖","description":"收官五柳湖，落英缤纷打卡点。","addr":"桃花源核心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桃源鸡后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"桃花源古镇","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"桃花源古镇是桃花源最有代表性的看点，秦溪秦谷还原桃花源记场景。攻略把它排进主线，时间留得最足。","notice":"秦溪秦谷还原桃花源记场景。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"常德市桃源县"},{"spotId":"S2","name":"桃源山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"桃源山是桃花源最有代表性的看点，水府阁俯瞰沅江。攻略把它排进主线，时间留得最足。","notice":"水府阁俯瞰沅江。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"桃花源景区"},{"spotId":"S3","name":"五柳湖","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"五柳湖是桃花源最有代表性的看点，落英缤纷打卡点。攻略把它排进主线，时间留得最足。","notice":"落英缤纷打卡点。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"桃花源核心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"常德米粉（人均18元）","description":"常德 · 桃花源的招牌是常德米粉，刘聋子粉馆本地人都认这家，点单照攻略不踩雷。","addr":"桃源县漳江镇"},{"title":"擂茶（人均35元）","description":"常德 · 桃花源的招牌是擂茶，秦溪擂茶馆本地人都认这家，点单照攻略不踩雷。","addr":"桃花源古镇内"},{"title":"桃源鸡（人均68元）","description":"常德 · 桃花源的招牌是桃源鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["墨镜与拍照道具","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","相机或运动相机","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["几月份去 常德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('普者黑纯攻略·深度指南3','guide','文山 · 普者黑','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',990,500,2,'青龙山 / 天鹅湖 / 仙人洞村 —— 纯攻略助你玩透普者黑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普者黑」两日慢旅行——水景。丘北辣椒香而不辣。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 文山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴文山","description":"集合出发，大巴直达普者黑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青龙山","description":"抵达后首游青龙山，登顶看万亩荷塘全景。","addr":"丘北县普者黑村","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐醉虾（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天鹅湖","description":"早起人少，天鹅湖精华时段，候鸟与荷塘，乘船打水仗。","addr":"普者黑景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐荷叶宴，人均68元，补充体力。","addr":"天鹅湖边","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"仙人洞村","description":"午后游览仙人洞村，撒尼人村落，民宿夜色美。","addr":"普者黑湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青龙山","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"青龙山是普者黑最有代表性的看点，登顶看万亩荷塘全景。攻略把它排进主线，时间留得最足。","notice":"登顶看万亩荷塘全景。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"丘北县普者黑村"},{"spotId":"S2","name":"天鹅湖","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"天鹅湖是普者黑最有代表性的看点，候鸟与荷塘，乘船打水仗。攻略把它排进主线，时间留得最足。","notice":"候鸟与荷塘，乘船打水仗。这个点位上午光线最好。","durationMinutes":180,"addr":"普者黑景区"},{"spotId":"S3","name":"仙人洞村","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"仙人洞村是普者黑最有代表性的看点，撒尼人村落，民宿夜色美。攻略把它排进主线，时间留得最足。","notice":"撒尼人村落，民宿夜色美。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"普者黑湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"醉虾（人均48元）","description":"文山 · 普者黑的招牌是醉虾，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"普者黑村"},{"title":"荷叶宴（人均68元）","description":"文山 · 普者黑的招牌是荷叶宴，荷香餐厅本地人都认这家，点单照攻略不踩雷。","addr":"天鹅湖边"},{"title":"丘北辣椒鸡（人均58元）","description":"文山 · 普者黑的招牌是丘北辣椒鸡，辣椒主题馆本地人都认这家，点单照攻略不踩雷。","addr":"丘北县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","身份证件与手机充电宝","少量零食补给","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 文山 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('蜀南竹海纯攻略·周末版3','guide','宜宾 · 蜀南竹海','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1990,1000,1,'蜀南竹海 / 李庄古镇 / 兴文石海 —— 纯攻略助你玩透蜀南竹海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「蜀南竹海」三日深度游——古村落。竹荪竹笋干货轻便。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 宜宾"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜宾，抵达后办理入住、熟悉周边环境。","addr":"宜宾市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜀南竹海","description":"下午首站蜀南竹海，调整状态进入旅行节奏，忘忧谷翡翠长廊，竹林深处人家。","addr":"宜宾市长宁县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜宾一带氛围拉满，晚餐全竹宴人均68元。","addr":"蜀南竹海","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"李庄古镇","description":"全天主景点李庄古镇，万里长江第一古镇，抗战文化。","addr":"翠屏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐李庄白肉（人均42元），早点休息。","addr":"李庄古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"兴文石海","description":"收官兴文石海，天坑石林与僰人文化。","addr":"兴文县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐燃面后集合返程，三日旅程圆满。","addr":"宜宾市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜀南竹海","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"蜀南竹海是蜀南竹海最有代表性的看点，忘忧谷翡翠长廊，竹林深处人家。攻略把它排进主线，时间留得最足。","notice":"忘忧谷翡翠长廊，竹林深处人家。这个点位上午光线最好。","durationMinutes":240,"addr":"宜宾市长宁县"},{"spotId":"S2","name":"李庄古镇","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"李庄古镇是蜀南竹海最有代表性的看点，万里长江第一古镇，抗战文化。攻略把它排进主线，时间留得最足。","notice":"万里长江第一古镇，抗战文化。这个点位上午光线最好。","durationMinutes":150,"addr":"翠屏区"},{"spotId":"S3","name":"兴文石海","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"兴文石海是蜀南竹海最有代表性的看点，天坑石林与僰人文化。攻略把它排进主线，时间留得最足。","notice":"天坑石林与僰人文化。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"兴文县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"全竹宴（人均68元）","description":"宜宾 · 蜀南竹海的招牌是全竹宴，竹海人家本地人都认这家，点单照攻略不踩雷。","addr":"蜀南竹海"},{"title":"李庄白肉（人均42元）","description":"宜宾 · 蜀南竹海的招牌是李庄白肉，李庄老店本地人都认这家，点单照攻略不踩雷。","addr":"李庄古镇"},{"title":"燃面（人均12元）","description":"宜宾 · 蜀南竹海的招牌是燃面，刘臣街燃面本地人都认这家，点单照攻略不踩雷。","addr":"宜宾市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","少量零食补给","轻便雨衣或折叠伞","相机或运动相机","常用药品（肠胃药/创可贴）","墨镜与拍照道具","身份证件与手机充电宝","换洗衣物与外套（早晚温差）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["当地有什么必吃？","到了 宜宾，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阳朔漓江纯攻略·亲子篇3','guide','桂林 · 阳朔漓江','water','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',990,500,2,'兴坪漓江 / 遇龙河 / 西街 —— 纯攻略助你玩透阳朔漓江精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阳朔漓江」两日慢旅行——水景。阳朔金桔个大超甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴桂林","description":"集合出发，大巴直达阳朔漓江，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"兴坪漓江","description":"抵达后首游兴坪漓江，20元人民币背景，老寨山看全景。","addr":"阳朔县兴坪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐啤酒鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"遇龙河","description":"早起人少，遇龙河精华时段，竹筏漂流，工农桥日落。","addr":"阳朔县遇龙河","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐桂林米粉，人均12元，补充体力。","addr":"兴坪老街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"西街","description":"午后游览西街，老外扎堆的千年老街。","addr":"阳朔县西街","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"兴坪漓江","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"兴坪漓江是阳朔漓江最有代表性的看点，20元人民币背景，老寨山看全景。攻略把它排进主线，时间留得最足。","notice":"20元人民币背景，老寨山看全景。这个点位上午光线最好。","durationMinutes":180,"addr":"阳朔县兴坪镇"},{"spotId":"S2","name":"遇龙河","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"遇龙河是阳朔漓江最有代表性的看点，竹筏漂流，工农桥日落。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流，工农桥日落。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"阳朔县遇龙河"},{"spotId":"S3","name":"西街","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"西街是阳朔漓江最有代表性的看点，老外扎堆的千年老街。攻略把它排进主线，时间留得最足。","notice":"老外扎堆的千年老街。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"阳朔县西街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"啤酒鱼（人均68元）","description":"桂林 · 阳朔漓江的招牌是啤酒鱼，谢大姐啤酒鱼本地人都认这家，点单照攻略不踩雷。","addr":"西街口"},{"title":"桂林米粉（人均12元）","description":"桂林 · 阳朔漓江的招牌是桂林米粉，崇善米粉本地人都认这家，点单照攻略不踩雷。","addr":"兴坪老街"},{"title":"田螺酿（人均38元）","description":"桂林 · 阳朔漓江的招牌是田螺酿，阳朔农家本地人都认这家，点单照攻略不踩雷。","addr":"遇龙河边"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 桂林，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 桂林 的交通方便吗？","推荐先到 桂林，再打车或景区直通车前往核心景区；自驾导航直接搜阳朔漓江即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南靖土楼纯攻略·摄影机位3','guide','漳州 · 南靖土楼','village','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',2500,1300,1,'田螺坑土楼群 / 裕昌楼 / 云水谣古镇 —— 纯攻略助你玩透南靖土楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「南靖土楼」三日深度游——古村落。土楼红茶岩韵悠长。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 漳州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往漳州，抵达后办理入住、熟悉周边环境。","addr":"漳州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"田螺坑土楼群","description":"下午首站田螺坑土楼群，调整状态进入旅行节奏，四菜一汤观景台，夜景更美。","addr":"南靖县书洋镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游漳州一带氛围拉满，晚餐土楼农家菜人均48元。","addr":"田螺坑下观景台","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"裕昌楼","description":"全天主景点裕昌楼，700年东歪西斜奇楼。","addr":"南靖县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐梅菜扣肉（人均42元），早点休息。","addr":"云水谣古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"云水谣古镇","description":"收官云水谣古镇，千年榕树与水车，电影取景地。","addr":"南靖县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糍粑后集合返程，三日旅程圆满。","addr":"裕昌楼前","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"田螺坑土楼群","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"田螺坑土楼群是南靖土楼最有代表性的看点，四菜一汤观景台，夜景更美。攻略把它排进主线，时间留得最足。","notice":"四菜一汤观景台，夜景更美。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"南靖县书洋镇"},{"spotId":"S2","name":"裕昌楼","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"裕昌楼是南靖土楼最有代表性的看点，700年东歪西斜奇楼。攻略把它排进主线，时间留得最足。","notice":"700年东歪西斜奇楼。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"南靖县"},{"spotId":"S3","name":"云水谣古镇","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"云水谣古镇是南靖土楼最有代表性的看点，千年榕树与水车，电影取景地。攻略把它排进主线，时间留得最足。","notice":"千年榕树与水车，电影取景地。这个点位上午光线最好。","durationMinutes":150,"addr":"南靖县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土楼农家菜（人均48元）","description":"漳州 · 南靖土楼的招牌是土楼农家菜，客家土菜馆本地人都认这家，点单照攻略不踩雷。","addr":"田螺坑下观景台"},{"title":"梅菜扣肉（人均42元）","description":"漳州 · 南靖土楼的招牌是梅菜扣肉，云水谣饭庄本地人都认这家，点单照攻略不踩雷。","addr":"云水谣古镇"},{"title":"糍粑（人均12元）","description":"漳州 · 南靖土楼的招牌是糍粑，土楼小吃本地人都认这家，点单照攻略不踩雷。","addr":"裕昌楼前"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","少量零食补给","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 漳州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 漳州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('千岛湖纯攻略·美食清单3','guide','淳安 · 千岛湖','water','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1500,800,2,'中心湖区 / 东南湖区 / 文渊狮城 —— 纯攻略助你玩透千岛湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「千岛湖」两日慢旅行——水景。千岛湖有机鱼头认证标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 淳安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴淳安","description":"集合出发，大巴直达千岛湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中心湖区","description":"抵达后首游中心湖区，梅峰岛看千岛全景，缆车省力。","addr":"淳安县千岛湖镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐千岛湖鱼头（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"东南湖区","description":"早起人少，东南湖区精华时段，黄山尖九岛串联水道。","addr":"千岛湖","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山核桃，人均45元，补充体力。","addr":"渔街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"文渊狮城","description":"午后游览文渊狮城，水下古城复刻，夜游有戏。","addr":"姜家镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中心湖区","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"中心湖区是千岛湖最有代表性的看点，梅峰岛看千岛全景，缆车省力。攻略把它排进主线，时间留得最足。","notice":"梅峰岛看千岛全景，缆车省力。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"淳安县千岛湖镇"},{"spotId":"S2","name":"东南湖区","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"东南湖区是千岛湖最有代表性的看点，黄山尖九岛串联水道。攻略把它排进主线，时间留得最足。","notice":"黄山尖九岛串联水道。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"千岛湖"},{"spotId":"S3","name":"文渊狮城","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"文渊狮城是千岛湖最有代表性的看点，水下古城复刻，夜游有戏。攻略把它排进主线，时间留得最足。","notice":"水下古城复刻，夜游有戏。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"姜家镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"千岛湖鱼头（人均128元）","description":"淳安 · 千岛湖的招牌是千岛湖鱼头，淳牌鱼头馆本地人都认这家，点单照攻略不踩雷。","addr":"千岛湖镇新安大街"},{"title":"山核桃（人均45元）","description":"淳安 · 千岛湖的招牌是山核桃，特产店本地人都认这家，点单照攻略不踩雷。","addr":"渔街"},{"title":"艾草粿（人均10元）","description":"淳安 · 千岛湖的招牌是艾草粿，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"秀水街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('东湖黄鹤楼纯攻略·自由行手册3','guide','武汉 · 东湖黄鹤楼','water','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1990,1000,2,'黄鹤楼 / 东湖绿道 / 昙华林 —— 纯攻略助你玩透东湖黄鹤楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「东湖黄鹤楼」三日深度游——水景。武汉鸭脖真空包装好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 武汉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往武汉，抵达后办理入住、熟悉周边环境。","addr":"武汉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄鹤楼","description":"下午首站黄鹤楼，调整状态进入旅行节奏，天下江山第一楼，夜景灯光秀。","addr":"武汉市武昌区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游武汉一带氛围拉满，晚餐热干面人均12元。","addr":"户部巷","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"东湖绿道","description":"全天主景点东湖绿道，骑行湖中道，磨山樱园。","addr":"武昌区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐豆皮（人均18元），早点休息。","addr":"大智路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"昙华林","description":"收官昙华林，老教堂与文创小店。","addr":"武昌区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐武昌鱼后集合返程，三日旅程圆满。","addr":"昙华林","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄鹤楼","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"黄鹤楼是东湖黄鹤楼最有代表性的看点，天下江山第一楼，夜景灯光秀。攻略把它排进主线，时间留得最足。","notice":"天下江山第一楼，夜景灯光秀。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"武汉市武昌区"},{"spotId":"S2","name":"东湖绿道","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"东湖绿道是东湖黄鹤楼最有代表性的看点，骑行湖中道，磨山樱园。攻略把它排进主线，时间留得最足。","notice":"骑行湖中道，磨山樱园。这个点位上午光线最好。","durationMinutes":180,"addr":"武昌区"},{"spotId":"S3","name":"昙华林","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"昙华林是东湖黄鹤楼最有代表性的看点，老教堂与文创小店。攻略把它排进主线，时间留得最足。","notice":"老教堂与文创小店。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"武昌区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"热干面（人均12元）","description":"武汉 · 东湖黄鹤楼的招牌是热干面，蔡林记本地人都认这家，点单照攻略不踩雷。","addr":"户部巷"},{"title":"豆皮（人均18元）","description":"武汉 · 东湖黄鹤楼的招牌是豆皮，老通城本地人都认这家，点单照攻略不踩雷。","addr":"大智路"},{"title":"武昌鱼（人均68元）","description":"武汉 · 东湖黄鹤楼的招牌是武昌鱼，湖锦酒楼本地人都认这家，点单照攻略不踩雷。","addr":"昙华林"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 武汉 的交通方便吗？","推荐先到 武汉，再打车或景区直通车前往核心景区；自驾导航直接搜东湖黄鹤楼即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('少林寺纯攻略·省钱玩法3','guide','登封 · 少林寺','adventure','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1990,1000,9,'少林寺常住院 / 三皇寨 / 嵩阳书院 —— 纯攻略助你玩透少林寺精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「少林寺」两日慢旅行——探险地。少林寺佛珠开光要理性。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 登封"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴登封","description":"集合出发，大巴直达少林寺，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"少林寺常住院","description":"抵达后首游少林寺常住院，塔林与武术表演，达摩面壁洞。","addr":"登封市嵩山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐少林素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三皇寨","description":"早起人少，三皇寨精华时段，悬空栈道看书册崖。","addr":"嵩山少室山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐登封焖子，人均28元，补充体力。","addr":"登封市区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"嵩阳书院","description":"午后游览嵩阳书院，四大书院之一。","addr":"登封市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"少林寺常住院","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"少林寺常住院是少林寺最有代表性的看点，塔林与武术表演，达摩面壁洞。攻略把它排进主线，时间留得最足。","notice":"塔林与武术表演，达摩面壁洞。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"登封市嵩山"},{"spotId":"S2","name":"三皇寨","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"三皇寨是少林寺最有代表性的看点，悬空栈道看书册崖。攻略把它排进主线，时间留得最足。","notice":"悬空栈道看书册崖。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"嵩山少室山"},{"spotId":"S3","name":"嵩阳书院","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"嵩阳书院是少林寺最有代表性的看点，四大书院之一。攻略把它排进主线，时间留得最足。","notice":"四大书院之一。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"登封市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"少林素斋（人均48元）","description":"登封 · 少林寺的招牌是少林素斋，寺内素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"少林寺内"},{"title":"登封焖子（人均28元）","description":"登封 · 少林寺的招牌是登封焖子，老字号本地人都认这家，点单照攻略不踩雷。","addr":"登封市区"},{"title":"焦盖烧饼（人均8元）","description":"登封 · 少林寺的招牌是焦盖烧饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"嵩阳书院旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","轻便雨衣或折叠伞","相机或运动相机","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 登封 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云冈石窟纯攻略·避坑版3','guide','大同 · 云冈石窟','red','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',990,500,7,'云冈石窟 / 大同古城墙 / 悬空寺 —— 纯攻略助你玩透云冈石窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「云冈石窟」三日深度游——人文。大同煤雕工艺独特。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 大同"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大同，抵达后办理入住、熟悉周边环境。","addr":"大同市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"云冈石窟","description":"下午首站云冈石窟，调整状态进入旅行节奏，昙曜五窟露天大佛，北魏气象。","addr":"大同市云冈区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大同一带氛围拉满，晚餐刀削面人均15元。","addr":"大同市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大同古城墙","description":"全天主景点大同古城墙，夜景灯光，骑行城墙。","addr":"平城区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊杂粉（人均18元），早点休息。","addr":"鼓楼东街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"悬空寺","description":"收官悬空寺，峭壁上的千年古寺。","addr":"浑源县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐黄糕后集合返程，三日旅程圆满。","addr":"浑源县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"云冈石窟","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"云冈石窟是云冈石窟最有代表性的看点，昙曜五窟露天大佛，北魏气象。攻略把它排进主线，时间留得最足。","notice":"昙曜五窟露天大佛，北魏气象。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"大同市云冈区"},{"spotId":"S2","name":"大同古城墙","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"大同古城墙是云冈石窟最有代表性的看点，夜景灯光，骑行城墙。攻略把它排进主线，时间留得最足。","notice":"夜景灯光，骑行城墙。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"平城区"},{"spotId":"S3","name":"悬空寺","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"悬空寺是云冈石窟最有代表性的看点，峭壁上的千年古寺。攻略把它排进主线，时间留得最足。","notice":"峭壁上的千年古寺。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"浑源县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"刀削面（人均15元）","description":"大同 · 云冈石窟的招牌是刀削面，东方削面本地人都认这家，点单照攻略不踩雷。","addr":"大同市区"},{"title":"羊杂粉（人均18元）","description":"大同 · 云冈石窟的招牌是羊杂粉，老字号羊杂本地人都认这家，点单照攻略不踩雷。","addr":"鼓楼东街"},{"title":"黄糕（人均10元）","description":"大同 · 云冈石窟的招牌是黄糕，黍面糕铺本地人都认这家，点单照攻略不踩雷。","addr":"浑源县"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","相机或运动相机","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 大同 的交通方便吗？","推荐先到 大同，再打车或景区直通车前往核心景区；自驾导航直接搜云冈石窟即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丹霞山纯攻略·深度指南3','guide','韶关 · 丹霞山','adventure','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,9,'长老峰 / 阳元石 / 翔龙湖 —— 纯攻略助你玩透丹霞山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「丹霞山」两日慢旅行——探险地。丹霞山白毛茶清甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 韶关"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴韶关","description":"集合出发，大巴直达丹霞山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"长老峰","description":"抵达后首游长老峰，丹霞地貌命名地，观日亭日出。","addr":"韶关市仁化县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐冷水猪肚（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"阳元石","description":"早起人少，阳元石精华时段，天然奇石打卡。","addr":"丹霞山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐炒山坑螺，人均38元，补充体力。","addr":"周田镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"翔龙湖","description":"午后游览翔龙湖，水上丹霞乘船。","addr":"丹霞山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"长老峰","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"长老峰是丹霞山最有代表性的看点，丹霞地貌命名地，观日亭日出。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌命名地，观日亭日出。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"韶关市仁化县"},{"spotId":"S2","name":"阳元石","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"阳元石是丹霞山最有代表性的看点，天然奇石打卡。攻略把它排进主线，时间留得最足。","notice":"天然奇石打卡。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"丹霞山"},{"spotId":"S3","name":"翔龙湖","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"翔龙湖是丹霞山最有代表性的看点，水上丹霞乘船。攻略把它排进主线，时间留得最足。","notice":"水上丹霞乘船。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"丹霞山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"冷水猪肚（人均48元）","description":"韶关 · 丹霞山的招牌是冷水猪肚，仁化农家菜本地人都认这家，点单照攻略不踩雷。","addr":"丹霞山镇"},{"title":"炒山坑螺（人均38元）","description":"韶关 · 丹霞山的招牌是炒山坑螺，山坑鱼小馆本地人都认这家，点单照攻略不踩雷。","addr":"周田镇"},{"title":"酸笋鸭（人均58元）","description":"韶关 · 丹霞山的招牌是酸笋鸭，韶关客家菜本地人都认这家，点单照攻略不踩雷。","addr":"仁化县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","相机或运动相机","身份证件与手机充电宝","少量零食补给","换洗衣物与外套（早晚温差）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('敦煌莫高窟纯攻略·周末版3','guide','酒泉 · 敦煌莫高窟','red','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',990,500,7,'莫高窟 / 鸣沙山月牙泉 / 沙洲夜市 —— 纯攻略助你玩透敦煌莫高窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「敦煌莫高窟」三日深度游——人文。敦煌夜光杯工艺品别致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 酒泉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往酒泉，抵达后办理入住、熟悉周边环境。","addr":"酒泉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫高窟","description":"下午首站莫高窟，调整状态进入旅行节奏，千年壁画宝库，A类票提前约。","addr":"敦煌市鸣沙山东麓","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游酒泉一带氛围拉满，晚餐驴肉黄面人均28元。","addr":"滨河世纪家园","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"鸣沙山月牙泉","description":"全天主景点鸣沙山月牙泉，沙漠绿洲，骆驼队与滑沙。","addr":"敦煌市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐胡羊焖饼（人均58元），早点休息。","addr":"沙洲路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙洲夜市","description":"收官沙洲夜市，驴肉黄面与夜市淘货。","addr":"敦煌市区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏皮水后集合返程，三日旅程圆满。","addr":"沙洲夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫高窟","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"莫高窟是敦煌莫高窟最有代表性的看点，千年壁画宝库，A类票提前约。攻略把它排进主线，时间留得最足。","notice":"千年壁画宝库，A类票提前约。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"敦煌市鸣沙山东麓"},{"spotId":"S2","name":"鸣沙山月牙泉","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"鸣沙山月牙泉是敦煌莫高窟最有代表性的看点，沙漠绿洲，骆驼队与滑沙。攻略把它排进主线，时间留得最足。","notice":"沙漠绿洲，骆驼队与滑沙。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"敦煌市"},{"spotId":"S3","name":"沙洲夜市","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"沙洲夜市是敦煌莫高窟最有代表性的看点，驴肉黄面与夜市淘货。攻略把它排进主线，时间留得最足。","notice":"驴肉黄面与夜市淘货。这个点位上午光线最好。","durationMinutes":120,"addr":"敦煌市区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉黄面（人均28元）","description":"酒泉 · 敦煌莫高窟的招牌是驴肉黄面，顺张驴肉黄面馆本地人都认这家，点单照攻略不踩雷。","addr":"滨河世纪家园"},{"title":"胡羊焖饼（人均58元）","description":"酒泉 · 敦煌莫高窟的招牌是胡羊焖饼，靖远尕六美味羊羔肉本地人都认这家，点单照攻略不踩雷。","addr":"沙洲路"},{"title":"杏皮水（人均8元）","description":"酒泉 · 敦煌莫高窟的招牌是杏皮水，夜市摊位本地人都认这家，点单照攻略不踩雷。","addr":"沙洲夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["几月份去 酒泉 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 酒泉 的交通方便吗？","推荐先到 酒泉，再打车或景区直通车前往核心景区；自驾导航直接搜敦煌莫高窟即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('布达拉宫纯攻略·亲子篇3','guide','拉萨 · 布达拉宫','plateau','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,2,'布达拉宫 / 大昭寺 / 色拉寺 —— 纯攻略助你玩透布达拉宫精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「布达拉宫」两日慢旅行——高原。拉萨转经筒小件最好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 拉萨"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴拉萨","description":"集合出发，大巴直达布达拉宫，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"布达拉宫","description":"抵达后首游布达拉宫，海拔3700宫殿，提前一天预约。","addr":"拉萨市城关区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏面（人均12元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大昭寺","description":"早起人少，大昭寺精华时段，八廓街转经道，藏地心脏。","addr":"老城区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤牦牛肉，人均68元，补充体力。","addr":"八角东南角","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"色拉寺","description":"午后游览色拉寺，辩经下午3点开始，场面壮观。","addr":"城北","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"布达拉宫","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"布达拉宫是布达拉宫最有代表性的看点，海拔3700宫殿，提前一天预约。攻略把它排进主线，时间留得最足。","notice":"海拔3700宫殿，提前一天预约。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"拉萨市城关区"},{"spotId":"S2","name":"大昭寺","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"大昭寺是布达拉宫最有代表性的看点，八廓街转经道，藏地心脏。攻略把它排进主线，时间留得最足。","notice":"八廓街转经道，藏地心脏。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"老城区"},{"spotId":"S3","name":"色拉寺","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"色拉寺是布达拉宫最有代表性的看点，辩经下午3点开始，场面壮观。攻略把它排进主线，时间留得最足。","notice":"辩经下午3点开始，场面壮观。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"城北"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏面（人均12元）","description":"拉萨 · 布达拉宫的招牌是藏面，光明港琼甜茶馆本地人都认这家，点单照攻略不踩雷。","addr":"八廓街"},{"title":"烤牦牛肉（人均68元）","description":"拉萨 · 布达拉宫的招牌是烤牦牛肉，玛吉阿米本地人都认这家，点单照攻略不踩雷。","addr":"八角东南角"},{"title":"青稞酒（人均30元）","description":"拉萨 · 布达拉宫的招牌是青稞酒，藏家宴本地人都认这家，点单照攻略不踩雷。","addr":"藏医院路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具","相机或运动相机","常用药品（肠胃药/创可贴）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 拉萨，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五大道瓷房子纯攻略·摄影机位3','guide','和平 · 五大道瓷房子','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',990,500,5,'五大道 / 瓷房子 / 古文化街 —— 纯攻略助你玩透五大道瓷房子精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「五大道瓷房子」三日深度游——文艺。天津泥人张彩塑传神。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"天津 · 和平"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往和平，抵达后办理入住、熟悉周边环境。","addr":"和平市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"五大道","description":"下午首站五大道，调整状态进入旅行节奏，万国建筑博览会，马车游。","addr":"天津市和平区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游和平一带氛围拉满，晚餐煎饼果子人均10元。","addr":"和平区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"瓷房子","description":"全天主景点瓷房子，7亿瓷片房子，白天看外观。","addr":"和平区赤峰道","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐狗不理包子（人均45元），早点休息。","addr":"山东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古文化街","description":"收官古文化街，泥人张杨柳青年画。","addr":"南开区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐耳朵眼炸糕后集合返程，三日旅程圆满。","addr":"古文化街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"五大道","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"五大道是五大道瓷房子最有代表性的看点，万国建筑博览会，马车游。攻略把它排进主线，时间留得最足。","notice":"万国建筑博览会，马车游。这个点位上午光线最好。","durationMinutes":150,"addr":"天津市和平区"},{"spotId":"S2","name":"瓷房子","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"瓷房子是五大道瓷房子最有代表性的看点，7亿瓷片房子，白天看外观。攻略把它排进主线，时间留得最足。","notice":"7亿瓷片房子，白天看外观。这个点位上午光线最好。","durationMinutes":30,"addr":"和平区赤峰道"},{"spotId":"S3","name":"古文化街","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"古文化街是五大道瓷房子最有代表性的看点，泥人张杨柳青年画。攻略把它排进主线，时间留得最足。","notice":"泥人张杨柳青年画。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"南开区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"煎饼果子（人均10元）","description":"和平 · 五大道瓷房子的招牌是煎饼果子，南楼煎饼本地人都认这家，点单照攻略不踩雷。","addr":"和平区"},{"title":"狗不理包子（人均45元）","description":"和平 · 五大道瓷房子的招牌是狗不理包子，狗不理总店本地人都认这家，点单照攻略不踩雷。","addr":"山东路"},{"title":"耳朵眼炸糕（人均8元）","description":"和平 · 五大道瓷房子的招牌是耳朵眼炸糕，耳朵眼总店本地人都认这家，点单照攻略不踩雷。","addr":"古文化街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 和平，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 和平 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 和平 的交通方便吗？","推荐先到 和平，再打车或景区直通车前往核心景区；自驾导航直接搜五大道瓷房子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙虎山纯攻略·美食清单3','guide','鹰潭 · 龙虎山','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',1990,1000,2,'仙水岩 / 泸溪河竹筏 / 上清古镇 —— 纯攻略助你玩透龙虎山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙虎山」两日慢旅行——水景。龙虎山道教养生茶值得带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 鹰潭"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴鹰潭","description":"集合出发，大巴直达龙虎山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"仙水岩","description":"抵达后首游仙水岩，悬棺表演一天四场，提前占前排。","addr":"龙虎山仙水岩景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐天师板栗烧鸡（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"泸溪河竹筏","description":"早起人少，泸溪河竹筏精华时段，顺流漂90分钟，防晒必做。","addr":"龙虎山竹筏码头","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐泸溪河鱼，人均58元，补充体力。","addr":"竹筏码头旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"上清古镇","description":"午后游览上清古镇，天师府在此，古街人少。","addr":"龙虎山上清镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"仙水岩","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"仙水岩是龙虎山最有代表性的看点，悬棺表演一天四场，提前占前排。攻略把它排进主线，时间留得最足。","notice":"悬棺表演一天四场，提前占前排。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"龙虎山仙水岩景区"},{"spotId":"S2","name":"泸溪河竹筏","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"泸溪河竹筏是龙虎山最有代表性的看点，顺流漂90分钟，防晒必做。攻略把它排进主线，时间留得最足。","notice":"顺流漂90分钟，防晒必做。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"龙虎山竹筏码头"},{"spotId":"S3","name":"上清古镇","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"上清古镇是龙虎山最有代表性的看点，天师府在此，古街人少。攻略把它排进主线，时间留得最足。","notice":"天师府在此，古街人少。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"龙虎山上清镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"天师板栗烧鸡（人均68元）","description":"鹰潭 · 龙虎山的招牌是天师板栗烧鸡，上清古镇饭店本地人都认这家，点单照攻略不踩雷。","addr":"上清古镇长街"},{"title":"泸溪河鱼（人均58元）","description":"鹰潭 · 龙虎山的招牌是泸溪河鱼，仙水岩渔家本地人都认这家，点单照攻略不踩雷。","addr":"竹筏码头旁"},{"title":"上清豆腐（人均20元）","description":"鹰潭 · 龙虎山的招牌是上清豆腐，古镇豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"上清古街中段"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["几月份去 鹰潭 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 鹰潭 的交通方便吗？","推荐先到 鹰潭，再打车或景区直通车前往核心景区；自驾导航直接搜龙虎山即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('张家界国家森林公园纯攻略·自由行手册3','guide','张家界 · 张家界国家森林公园','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1500,800,2,'袁家界 / 天子山 / 金鞭溪 —— 纯攻略助你玩透张家界国家森林公园精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「张家界国家森林公园」三日深度游——山岳。张家界莓茶降火神器。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 张家界"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往张家界，抵达后办理入住、熟悉周边环境。","addr":"张家界市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"袁家界","description":"下午首站袁家界，调整状态进入旅行节奏，阿凡达悬浮山原型，百龙天梯上山。","addr":"武陵源区森林公园","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游张家界一带氛围拉满，晚餐三下锅人均58元。","addr":"武陵源汽车站旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天子山","description":"全天主景点天子山，御笔峰日落绝佳，贺龙公园顺路。","addr":"武陵源天子山景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土家腊肉（人均48元），早点休息。","addr":"溪布街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"金鞭溪","description":"收官金鞭溪，全程7.5公里平路，溪边猕猴抢食注意。","addr":"森林公园大氧吧广场","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐岩耳炖土鸡后集合返程，三日旅程圆满。","addr":"森林公园门票站","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"袁家界","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"袁家界是张家界国家森林公园最有代表性的看点，阿凡达悬浮山原型，百龙天梯上山。攻略把它排进主线，时间留得最足。","notice":"阿凡达悬浮山原型，百龙天梯上山。这个点位上午光线最好。","durationMinutes":180,"addr":"武陵源区森林公园"},{"spotId":"S2","name":"天子山","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"天子山是张家界国家森林公园最有代表性的看点，御笔峰日落绝佳，贺龙公园顺路。攻略把它排进主线，时间留得最足。","notice":"御笔峰日落绝佳，贺龙公园顺路。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"武陵源天子山景区"},{"spotId":"S3","name":"金鞭溪","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"金鞭溪是张家界国家森林公园最有代表性的看点，全程7.5公里平路，溪边猕猴抢食注意。攻略把它排进主线，时间留得最足。","notice":"全程7.5公里平路，溪边猕猴抢食注意。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"森林公园大氧吧广场"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"三下锅（人均58元）","description":"张家界 · 张家界国家森林公园的招牌是三下锅，胡师傅三下锅本地人都认这家，点单照攻略不踩雷。","addr":"武陵源汽车站旁"},{"title":"土家腊肉（人均48元）","description":"张家界 · 张家界国家森林公园的招牌是土家腊肉，湘西腊肉馆本地人都认这家，点单照攻略不踩雷。","addr":"溪布街"},{"title":"岩耳炖土鸡（人均88元）","description":"张家界 · 张家界国家森林公园的招牌是岩耳炖土鸡，山里人家本地人都认这家，点单照攻略不踩雷。","addr":"森林公园门票站"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","少量零食补给","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","保温水杯与少量现金","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('紫鹊界梯田纯攻略·省钱玩法3','guide','娄底 · 紫鹊界梯田','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,1,'紫鹊界梯田 / 正龙古村 / 梅山龙宫 —— 纯攻略助你玩透紫鹊界梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「紫鹊界梯田」两日慢旅行——古村落。新化黄精茶养生。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 娄底"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴娄底","description":"集合出发，大巴直达紫鹊界梯田，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"紫鹊界梯田","description":"抵达后首游紫鹊界梯田，两千年秦人梯田，月牙山八仙过海。","addr":"娄底市新化县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐新化三合汤（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"正龙古村","description":"早起人少，正龙古村精华时段，干栏式板屋村落。","addr":"紫鹊界脚下","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐杯子糕，人均10元，补充体力。","addr":"紫鹊界","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"梅山龙宫","description":"午后游览梅山龙宫，地下溶洞暗河乘船。","addr":"新化县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"紫鹊界梯田","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"紫鹊界梯田是紫鹊界梯田最有代表性的看点，两千年秦人梯田，月牙山八仙过海。攻略把它排进主线，时间留得最足。","notice":"两千年秦人梯田，月牙山八仙过海。这个点位上午光线最好。","durationMinutes":180,"addr":"娄底市新化县"},{"spotId":"S2","name":"正龙古村","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"正龙古村是紫鹊界梯田最有代表性的看点，干栏式板屋村落。攻略把它排进主线，时间留得最足。","notice":"干栏式板屋村落。这个点位上午光线最好。","durationMinutes":90,"addr":"紫鹊界脚下"},{"spotId":"S3","name":"梅山龙宫","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"梅山龙宫是紫鹊界梯田最有代表性的看点，地下溶洞暗河乘船。攻略把它排进主线，时间留得最足。","notice":"地下溶洞暗河乘船。这个点位上午光线最好。","durationMinutes":150,"addr":"新化县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新化三合汤（人均38元）","description":"娄底 · 紫鹊界梯田的招牌是新化三合汤，老字号三合汤本地人都认这家，点单照攻略不踩雷。","addr":"新化县城"},{"title":"杯子糕（人均10元）","description":"娄底 · 紫鹊界梯田的招牌是杯子糕，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"紫鹊界"},{"title":"柴火腊肉（人均45元）","description":"娄底 · 紫鹊界梯田的招牌是柴火腊肉，农家直购本地人都认这家，点单照攻略不踩雷。","addr":"正龙古村"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","墨镜与拍照道具","少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 娄底 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大熊猫基地都江堰纯攻略·避坑版3','guide','成都 · 大熊猫基地都江堰','food','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2500,1300,3,'大熊猫繁育研究基地 / 都江堰 / 南桥夜啤酒 —— 纯攻略助你玩透大熊猫基地都江堰精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大熊猫基地都江堰」三日深度游——美食。郫县豆瓣是川菜之魂。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 成都"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往成都，抵达后办理入住、熟悉周边环境。","addr":"成都市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大熊猫繁育研究基地","description":"下午首站大熊猫繁育研究基地，调整状态进入旅行节奏，早8点开园直奔月亮产房，熊猫最活跃。","addr":"成华区外北熊猫大道","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游成都一带氛围拉满，晚餐火锅人均110元。","addr":"建设路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"都江堰","description":"全天主景点都江堰，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。","addr":"都江堰市公园路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐串串香（人均65元），早点休息。","addr":"玉林路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"南桥夜啤酒","description":"收官南桥夜啤酒，岷江水上的夜风与美食。","addr":"都江堰市南桥","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐钟水饺后集合返程，三日旅程圆满。","addr":"人民公园旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大熊猫繁育研究基地","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大熊猫繁育研究基地是大熊猫基地都江堰最有代表性的看点，早8点开园直奔月亮产房，熊猫最活跃。攻略把它排进主线，时间留得最足。","notice":"早8点开园直奔月亮产房，熊猫最活跃。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"成华区外北熊猫大道"},{"spotId":"S2","name":"都江堰","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"都江堰是大熊猫基地都江堰最有代表性的看点，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。攻略把它排进主线，时间留得最足。","notice":"鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。这个点位上午光线最好。","durationMinutes":180,"addr":"都江堰市公园路"},{"spotId":"S3","name":"南桥夜啤酒","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"南桥夜啤酒是大熊猫基地都江堰最有代表性的看点，岷江水上的夜风与美食。攻略把它排进主线，时间留得最足。","notice":"岷江水上的夜风与美食。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"都江堰市南桥"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"火锅（人均110元）","description":"成都 · 大熊猫基地都江堰的招牌是火锅，蜀大侠本地人都认这家，点单照攻略不踩雷。","addr":"建设路"},{"title":"串串香（人均65元）","description":"成都 · 大熊猫基地都江堰的招牌是串串香，马路边边本地人都认这家，点单照攻略不踩雷。","addr":"玉林路"},{"title":"钟水饺（人均15元）","description":"成都 · 大熊猫基地都江堰的招牌是钟水饺，老字号小吃本地人都认这家，点单照攻略不踩雷。","addr":"人民公园旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）","保温水杯与少量现金","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 成都，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄果树瀑布纯攻略·深度指南3','guide','安顺 · 黄果树瀑布','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',2500,1300,2,'黄果树大瀑布 / 天星桥 / 陡坡塘 —— 纯攻略助你玩透黄果树瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「黄果树瀑布」两日慢旅行——水景。安顺三刀是传统名点。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 安顺"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴安顺","description":"集合出发，大巴直达黄果树瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄果树大瀑布","description":"抵达后首游黄果树大瀑布，亚洲最大瀑布，水帘洞穿瀑而过。","addr":"安顺市镇宁县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐夺夺粉（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天星桥","description":"早起人少，天星桥精华时段，石景水上盆景，数生步趣味。","addr":"黄果树景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐裹卷，人均12元，补充体力。","addr":"黄果树镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"陡坡塘","description":"午后游览陡坡塘，西游记片尾取景地。","addr":"黄果树景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄果树大瀑布","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"黄果树大瀑布是黄果树瀑布最有代表性的看点，亚洲最大瀑布，水帘洞穿瀑而过。攻略把它排进主线，时间留得最足。","notice":"亚洲最大瀑布，水帘洞穿瀑而过。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"安顺市镇宁县"},{"spotId":"S2","name":"天星桥","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"天星桥是黄果树瀑布最有代表性的看点，石景水上盆景，数生步趣味。攻略把它排进主线，时间留得最足。","notice":"石景水上盆景，数生步趣味。这个点位上午光线最好。","durationMinutes":120,"addr":"黄果树景区"},{"spotId":"S3","name":"陡坡塘","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"陡坡塘是黄果树瀑布最有代表性的看点，西游记片尾取景地。攻略把它排进主线，时间留得最足。","notice":"西游记片尾取景地。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"黄果树景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"夺夺粉（人均35元）","description":"安顺 · 黄果树瀑布的招牌是夺夺粉，安顺小吃街本地人都认这家，点单照攻略不踩雷。","addr":"安顺市区"},{"title":"裹卷（人均12元）","description":"安顺 · 黄果树瀑布的招牌是裹卷，苗岭小吃本地人都认这家，点单照攻略不踩雷。","addr":"黄果树镇"},{"title":"布依农家餐（人均48元）","description":"安顺 · 黄果树瀑布的招牌是布依农家餐，石头寨本地人都认这家，点单照攻略不踩雷。","addr":"石头寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","墨镜与拍照道具","防晒霜与遮阳帽"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 安顺 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 安顺 的交通方便吗？","推荐先到 安顺，再打车或景区直通车前往核心景区；自驾导航直接搜黄果树瀑布即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙脊梯田纯攻略·周末版3','guide','桂林 · 龙脊梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',2990,1600,1,'平安寨七星伴月 / 金坑大寨 / 黄洛红瑶寨 —— 纯攻略助你玩透龙脊梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙脊梯田」三日深度游——古村落。龙脊辣椒酱拌饭一绝。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往桂林，抵达后办理入住、熟悉周边环境。","addr":"桂林市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"平安寨七星伴月","description":"下午首站平安寨七星伴月，调整状态进入旅行节奏，经典梯田观景台，徒步30分钟。","addr":"龙胜县龙脊镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游桂林一带氛围拉满，晚餐竹筒饭人均25元。","addr":"平安寨","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"金坑大寨","description":"全天主景点金坑大寨，缆车直达3号观景点，日落最佳。","addr":"龙脊梯田金坑","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土鸡煲（人均68元），早点休息。","addr":"金坑梯田","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"黄洛红瑶寨","description":"收官黄洛红瑶寨，天下第一长发村表演。","addr":"龙脊山下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐龙脊茶后集合返程，三日旅程圆满。","addr":"黄洛瑶寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"平安寨七星伴月","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"平安寨七星伴月是龙脊梯田最有代表性的看点，经典梯田观景台，徒步30分钟。攻略把它排进主线，时间留得最足。","notice":"经典梯田观景台，徒步30分钟。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙胜县龙脊镇"},{"spotId":"S2","name":"金坑大寨","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"金坑大寨是龙脊梯田最有代表性的看点，缆车直达3号观景点，日落最佳。攻略把它排进主线，时间留得最足。","notice":"缆车直达3号观景点，日落最佳。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"龙脊梯田金坑"},{"spotId":"S3","name":"黄洛红瑶寨","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"黄洛红瑶寨是龙脊梯田最有代表性的看点，天下第一长发村表演。攻略把它排进主线，时间留得最足。","notice":"天下第一长发村表演。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"龙脊山下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"竹筒饭（人均25元）","description":"桂林 · 龙脊梯田的招牌是竹筒饭，梯田农家本地人都认这家，点单照攻略不踩雷。","addr":"平安寨"},{"title":"土鸡煲（人均68元）","description":"桂林 · 龙脊梯田的招牌是土鸡煲，大寨农家本地人都认这家，点单照攻略不踩雷。","addr":"金坑梯田"},{"title":"龙脊茶（人均20元）","description":"桂林 · 龙脊梯田的招牌是龙脊茶，茶农家本地人都认这家，点单照攻略不踩雷。","addr":"黄洛瑶寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","相机或运动相机","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 桂林，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('霞浦滩涂纯攻略·亲子篇3','guide','宁德 · 霞浦滩涂','photography','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',2500,1300,12,'北岐滩涂 / 杨家溪 / 东壁日落 —— 纯攻略助你玩透霞浦滩涂精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「霞浦滩涂」两日慢旅行——摄影胜地。霞浦紫菜海带全国第一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 宁德"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宁德","description":"集合出发，大巴直达霞浦滩涂，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"北岐滩涂","description":"抵达后首游北岐滩涂，日出紫菜架光影，摄影圣地。","addr":"霞浦县松港街道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐霞浦剑蛏（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"杨家溪","description":"早起人少，杨家溪精华时段，千年枫榕树群，牛群穿雾。","addr":"霞浦县牙城镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐海带排骨汤，人均38元，补充体力。","addr":"北岐村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"东壁日落","description":"午后游览东壁日落，落日渔船归航机位。","addr":"霞浦县三沙镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"北岐滩涂","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"北岐滩涂是霞浦滩涂最有代表性的看点，日出紫菜架光影，摄影圣地。攻略把它排进主线，时间留得最足。","notice":"日出紫菜架光影，摄影圣地。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"霞浦县松港街道"},{"spotId":"S2","name":"杨家溪","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"杨家溪是霞浦滩涂最有代表性的看点，千年枫榕树群，牛群穿雾。攻略把它排进主线，时间留得最足。","notice":"千年枫榕树群，牛群穿雾。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"霞浦县牙城镇"},{"spotId":"S3","name":"东壁日落","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"东壁日落是霞浦滩涂最有代表性的看点，落日渔船归航机位。攻略把它排进主线，时间留得最足。","notice":"落日渔船归航机位。这个点位上午光线最好。","durationMinutes":90,"addr":"霞浦县三沙镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"霞浦剑蛏（人均68元）","description":"宁德 · 霞浦滩涂的招牌是霞浦剑蛏，海鲜大排档本地人都认这家，点单照攻略不踩雷。","addr":"三沙镇"},{"title":"海带排骨汤（人均38元）","description":"宁德 · 霞浦滩涂的招牌是海带排骨汤，渔家菜本地人都认这家，点单照攻略不踩雷。","addr":"北岐村"},{"title":"糊汤（人均10元）","description":"宁德 · 霞浦滩涂的招牌是糊汤，街头早点本地人都认这家，点单照攻略不踩雷。","addr":"霞浦县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","相机或运动相机","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","少量零食补给","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 宁德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 宁德，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 宁德 的交通方便吗？","推荐先到 宁德，再打车或景区直通车前往核心景区；自驾导航直接搜霞浦滩涂即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('拙政园林纯攻略·摄影机位3','guide','苏州 · 拙政园林','art','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,5,'拙政园 / 平江路 / 虎丘 —— 纯攻略助你玩透拙政园林精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「拙政园林」三日深度游——文艺。苏绣团扇工艺最精。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 苏州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往苏州，抵达后办理入住、熟悉周边环境。","addr":"苏州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"拙政园","description":"下午首站拙政园，调整状态进入旅行节奏，江南园林之母，人再多也值得。","addr":"苏州市姑苏区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游苏州一带氛围拉满，晚餐松鼠桂鱼人均128元。","addr":"太监弄","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"平江路","description":"全天主景点平江路，小桥流水人家，评弹声里喝茶。","addr":"姑苏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蟹粉小笼（人均25元），早点休息。","addr":"临顿路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"虎丘","description":"收官虎丘，吴中第一名胜，斜塔传奇。","addr":"姑苏区山塘街","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桂花糕后集合返程，三日旅程圆满。","addr":"山塘街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"拙政园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"拙政园是拙政园林最有代表性的看点，江南园林之母，人再多也值得。攻略把它排进主线，时间留得最足。","notice":"江南园林之母，人再多也值得。这个点位上午光线最好。","durationMinutes":150,"addr":"苏州市姑苏区"},{"spotId":"S2","name":"平江路","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"平江路是拙政园林最有代表性的看点，小桥流水人家，评弹声里喝茶。攻略把它排进主线，时间留得最足。","notice":"小桥流水人家，评弹声里喝茶。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"姑苏区"},{"spotId":"S3","name":"虎丘","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"虎丘是拙政园林最有代表性的看点，吴中第一名胜，斜塔传奇。攻略把它排进主线，时间留得最足。","notice":"吴中第一名胜，斜塔传奇。这个点位上午光线最好。","durationMinutes":90,"addr":"姑苏区山塘街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松鼠桂鱼（人均128元）","description":"苏州 · 拙政园林的招牌是松鼠桂鱼，得月楼本地人都认这家，点单照攻略不踩雷。","addr":"太监弄"},{"title":"蟹粉小笼（人均25元）","description":"苏州 · 拙政园林的招牌是蟹粉小笼，哑巴生煎本地人都认这家，点单照攻略不踩雷。","addr":"临顿路"},{"title":"桂花糕（人均15元）","description":"苏州 · 拙政园林的招牌是桂花糕，采芝斋本地人都认这家，点单照攻略不踩雷。","addr":"山塘街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","保温水杯与少量现金","常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 苏州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('恩施大峡谷纯攻略·美食清单3','guide','恩施 · 恩施大峡谷','adventure','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1500,800,9,'七星寨 / 云龙地缝 / 梭布垭石林 —— 纯攻略助你玩透恩施大峡谷精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「恩施大峡谷」两日慢旅行——探险地。恩施玉露茶古法蒸青。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 恩施"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴恩施","description":"集合出发，大巴直达恩施大峡谷，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七星寨","description":"抵达后首游七星寨，一炷香奇观，云龙地缝联游。","addr":"恩施市沐抚街道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐土家腊蹄子（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"云龙地缝","description":"早起人少，云龙地缝精华时段，U型地缝瀑布成群。","addr":"大峡谷景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐合渣，人均28元，补充体力。","addr":"沐抚镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"梭布垭石林","description":"午后游览梭布垭石林，戴冠石林迷宫。","addr":"恩施市太阳河乡","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七星寨","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"七星寨是恩施大峡谷最有代表性的看点，一炷香奇观，云龙地缝联游。攻略把它排进主线，时间留得最足。","notice":"一炷香奇观，云龙地缝联游。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"恩施市沐抚街道"},{"spotId":"S2","name":"云龙地缝","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"云龙地缝是恩施大峡谷最有代表性的看点，U型地缝瀑布成群。攻略把它排进主线，时间留得最足。","notice":"U型地缝瀑布成群。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"大峡谷景区"},{"spotId":"S3","name":"梭布垭石林","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"梭布垭石林是恩施大峡谷最有代表性的看点，戴冠石林迷宫。攻略把它排进主线，时间留得最足。","notice":"戴冠石林迷宫。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"恩施市太阳河乡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土家腊蹄子（人均58元）","description":"恩施 · 恩施大峡谷的招牌是土家腊蹄子，张关合渣本地人都认这家，点单照攻略不踩雷。","addr":"恩施市区"},{"title":"合渣（人均28元）","description":"恩施 · 恩施大峡谷的招牌是合渣，土家合渣馆本地人都认这家，点单照攻略不踩雷。","addr":"沐抚镇"},{"title":"土豆饭（人均22元）","description":"恩施 · 恩施大峡谷的招牌是土豆饭，农家本地人都认这家，点单照攻略不踩雷。","addr":"大峡谷游客中心"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","相机或运动相机","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('老君山纯攻略·自由行手册3','guide','栾川 · 老君山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1500,800,2,'金顶道观群 / 十里画屏 / 追梦谷 —— 纯攻略助你玩透老君山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「老君山」三日深度游——山岳。老君山高山茶清冽。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 栾川"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往栾川，抵达后办理入住、熟悉周边环境。","addr":"栾川市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶道观群","description":"下午首站金顶道观群，调整状态进入旅行节奏，云海雪景封神，远赴人间惊鸿宴。","addr":"洛阳市栾川县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游栾川一带氛围拉满，晚餐栾川豆腐人均28元。","addr":"栾川县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"十里画屏","description":"全天主景点十里画屏，滑道下山，省膝盖。","addr":"老君山石林","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蝌蚪面（人均18元），早点休息。","addr":"鸡冠洞乡","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"追梦谷","description":"收官追梦谷，溪瀑竹林轻松线。","addr":"老君山脚下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐玉米糁汤后集合返程，三日旅程圆满。","addr":"景区民宿","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶道观群","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"金顶道观群是老君山最有代表性的看点，云海雪景封神，远赴人间惊鸿宴。攻略把它排进主线，时间留得最足。","notice":"云海雪景封神，远赴人间惊鸿宴。这个点位上午光线最好。","durationMinutes":300,"addr":"洛阳市栾川县"},{"spotId":"S2","name":"十里画屏","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"十里画屏是老君山最有代表性的看点，滑道下山，省膝盖。攻略把它排进主线，时间留得最足。","notice":"滑道下山，省膝盖。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"老君山石林"},{"spotId":"S3","name":"追梦谷","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"追梦谷是老君山最有代表性的看点，溪瀑竹林轻松线。攻略把它排进主线，时间留得最足。","notice":"溪瀑竹林轻松线。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"老君山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"栾川豆腐（人均28元）","description":"栾川 · 老君山的招牌是栾川豆腐，山城豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"栾川县城"},{"title":"蝌蚪面（人均18元）","description":"栾川 · 老君山的招牌是蝌蚪面，老君山农家本地人都认这家，点单照攻略不踩雷。","addr":"鸡冠洞乡"},{"title":"玉米糁汤（人均10元）","description":"栾川 · 老君山的招牌是玉米糁汤，农家早餐本地人都认这家，点单照攻略不踩雷。","addr":"景区民宿"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具","防晒霜与遮阳帽","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
