INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武当山纯攻略·摄影机位3','guide','十堰 · 武当山','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,2,'金顶 / 南岩宫 / 紫霄宫 —— 纯攻略助你玩透武当山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武当山」三日深度游——山岳。武当道茶甘醇。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 十堰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往十堰，抵达后办理入住、熟悉周边环境。","addr":"十堰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，武当之巅金殿，转运台。","addr":"十堰市丹江口","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游十堰一带氛围拉满，晚餐道家素斋人均48元。","addr":"武当山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"南岩宫","description":"全天主景点南岩宫，龙头香悬崖奇观。","addr":"武当山南岩","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐武当冻豆腐（人均38元），早点休息。","addr":"南岩","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"紫霄宫","description":"收官紫霄宫，皇家道观规制。","addr":"武当山展旗峰","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐太极养生汤后集合返程，三日旅程圆满。","addr":"紫霄宫旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武当山最有代表性的看点，武当之巅金殿，转运台。攻略把它排进主线，时间留得最足。","notice":"武当之巅金殿，转运台。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"十堰市丹江口"},{"spotId":"S2","name":"南岩宫","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"南岩宫是武当山最有代表性的看点，龙头香悬崖奇观。攻略把它排进主线，时间留得最足。","notice":"龙头香悬崖奇观。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"武当山南岩"},{"spotId":"S3","name":"紫霄宫","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"紫霄宫是武当山最有代表性的看点，皇家道观规制。攻略把它排进主线，时间留得最足。","notice":"皇家道观规制。这个点位上午光线最好。","durationMinutes":90,"addr":"武当山展旗峰"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"道家素斋（人均48元）","description":"十堰 · 武当山的招牌是道家素斋，太子坡素斋本地人都认这家，点单照攻略不踩雷。","addr":"武当山镇"},{"title":"武当冻豆腐（人均38元）","description":"十堰 · 武当山的招牌是武当冻豆腐，山间餐馆本地人都认这家，点单照攻略不踩雷。","addr":"南岩"},{"title":"太极养生汤（人均68元）","description":"十堰 · 武当山的招牌是太极养生汤，道医药膳本地人都认这家，点单照攻略不踩雷。","addr":"紫霄宫旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","轻便雨衣或折叠伞","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 十堰 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('兵马俑城墙纯攻略·美食清单3','guide','西安 · 兵马俑城墙','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1500,800,7,'秦始皇兵马俑 / 西安城墙 / 大唐不夜城 —— 纯攻略助你玩透兵马俑城墙精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「兵马俑城墙」两日慢旅行——人文。兵马俑文创手办很火。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 西安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴西安","description":"集合出发，大巴直达兵马俑城墙，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"秦始皇兵马俑","description":"抵达后首游秦始皇兵马俑，一号坑震撼，讲解必请。","addr":"西安市临潼区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐肉夹馍（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"西安城墙","description":"早起人少，西安城墙精华时段，骑行环城14公里，日落最美。","addr":"碑林区南门","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐biangbiang面，人均22元，补充体力。","addr":"南院门","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大唐不夜城","description":"午后游览大唐不夜城，不倒翁小姐姐与灯光夜市。","addr":"雁塔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"秦始皇兵马俑","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"秦始皇兵马俑是兵马俑城墙最有代表性的看点，一号坑震撼，讲解必请。攻略把它排进主线，时间留得最足。","notice":"一号坑震撼，讲解必请。这个点位上午光线最好。","durationMinutes":240,"addr":"西安市临潼区"},{"spotId":"S2","name":"西安城墙","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"西安城墙是兵马俑城墙最有代表性的看点，骑行环城14公里，日落最美。攻略把它排进主线，时间留得最足。","notice":"骑行环城14公里，日落最美。这个点位上午光线最好。","durationMinutes":150,"addr":"碑林区南门"},{"spotId":"S3","name":"大唐不夜城","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"大唐不夜城是兵马俑城墙最有代表性的看点，不倒翁小姐姐与灯光夜市。攻略把它排进主线，时间留得最足。","notice":"不倒翁小姐姐与灯光夜市。这个点位上午光线最好。","durationMinutes":150,"addr":"雁塔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肉夹馍（人均15元）","description":"西安 · 兵马俑城墙的招牌是肉夹馍，子午路张记本地人都认这家，点单照攻略不踩雷。","addr":"临潼区"},{"title":"biangbiang面（人均22元）","description":"西安 · 兵马俑城墙的招牌是biangbiang面，老碗会本地人都认这家，点单照攻略不踩雷。","addr":"南院门"},{"title":"羊肉泡馍（人均45元）","description":"西安 · 兵马俑城墙的招牌是羊肉泡馍，老孙家本地人都认这家，点单照攻略不踩雷。","addr":"东关正街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","少量零食补给","相机或运动相机","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 西安，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 西安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('栈桥崂山纯攻略·自由行手册3','guide','青岛 · 栈桥崂山','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1200,600,6,'栈桥 / 崂山仰口 / 八大关 —— 纯攻略助你玩透栈桥崂山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「栈桥崂山」三日深度游——海滨。青岛啤酒原浆当天最新鲜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 青岛"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往青岛，抵达后办理入住、熟悉周边环境。","addr":"青岛市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"栈桥","description":"下午首站栈桥，调整状态进入旅行节奏，回澜阁海鸥季，夜色灯光。","addr":"青岛市市南区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游青岛一带氛围拉满，晚餐海鲜水饺人均58元。","addr":"闽江路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"崂山仰口","description":"全天主景点崂山仰口，海上第一名山，觅天洞。","addr":"崂山区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐野馄饨（人均15元），早点休息。","addr":"登州路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"八大关","description":"收官八大关，万国建筑与梧桐，秋天最美。","addr":"市南区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐崂山菇炖鸡后集合返程，三日旅程圆满。","addr":"仰口湾","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"栈桥","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"栈桥是栈桥崂山最有代表性的看点，回澜阁海鸥季，夜色灯光。攻略把它排进主线，时间留得最足。","notice":"回澜阁海鸥季，夜色灯光。这个点位上午光线最好。","durationMinutes":60,"addr":"青岛市市南区"},{"spotId":"S2","name":"崂山仰口","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"崂山仰口是栈桥崂山最有代表性的看点，海上第一名山，觅天洞。攻略把它排进主线，时间留得最足。","notice":"海上第一名山，觅天洞。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"崂山区"},{"spotId":"S3","name":"八大关","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"八大关是栈桥崂山最有代表性的看点，万国建筑与梧桐，秋天最美。攻略把它排进主线，时间留得最足。","notice":"万国建筑与梧桐，秋天最美。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"市南区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜水饺（人均58元）","description":"青岛 · 栈桥崂山的招牌是海鲜水饺，船歌鱼水饺本地人都认这家，点单照攻略不踩雷。","addr":"闽江路"},{"title":"野馄饨（人均15元）","description":"青岛 · 栈桥崂山的招牌是野馄饨，夜市馄饨摊本地人都认这家，点单照攻略不踩雷。","addr":"登州路"},{"title":"崂山菇炖鸡（人均68元）","description":"青岛 · 栈桥崂山的招牌是崂山菇炖鸡，山海农家本地人都认这家，点单照攻略不踩雷。","addr":"仰口湾"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","身份证件与手机充电宝","相机或运动相机","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 青岛 的交通方便吗？","推荐先到 青岛，再打车或景区直通车前往核心景区；自驾导航直接搜栈桥崂山即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七星岩纯攻略·省钱玩法3','guide','肇庆 · 七星岩','water','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1200,600,2,'七星岩 / 鼎湖山 / 紫云谷 —— 纯攻略助你玩透七星岩精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「七星岩」两日慢旅行——水景。端砚四大名砚之首。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 肇庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴肇庆","description":"集合出发，大巴直达七星岩，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七星岩","description":"抵达后首游七星岩，岭南第一奇观，湖山相映。","addr":"肇庆市端州区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐裹蒸粽（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"鼎湖山","description":"早起人少，鼎湖山精华时段，北回归线上的绿宝石，庆云寺。","addr":"鼎湖区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐文庆鲤，人均68元，补充体力。","addr":"鼎湖区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"紫云谷","description":"午后游览紫云谷，端砚石产地，溪水清凉。","addr":"羚羊峡","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七星岩","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"七星岩是七星岩最有代表性的看点，岭南第一奇观，湖山相映。攻略把它排进主线，时间留得最足。","notice":"岭南第一奇观，湖山相映。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"肇庆市端州区"},{"spotId":"S2","name":"鼎湖山","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"鼎湖山是七星岩最有代表性的看点，北回归线上的绿宝石，庆云寺。攻略把它排进主线，时间留得最足。","notice":"北回归线上的绿宝石，庆云寺。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"鼎湖区"},{"spotId":"S3","name":"紫云谷","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"紫云谷是七星岩最有代表性的看点，端砚石产地，溪水清凉。攻略把它排进主线，时间留得最足。","notice":"端砚石产地，溪水清凉。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"羚羊峡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"裹蒸粽（人均15元）","description":"肇庆 · 七星岩的招牌是裹蒸粽，皇中皇本地人都认这家，点单照攻略不踩雷。","addr":"端州区"},{"title":"文庆鲤（人均68元）","description":"肇庆 · 七星岩的招牌是文庆鲤，文庆鲤餐馆本地人都认这家，点单照攻略不踩雷。","addr":"鼎湖区"},{"title":"茶油鸡（人均48元）","description":"肇庆 · 七星岩的招牌是茶油鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"七星岩东门"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","保温水杯与少量现金","少量零食补给","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 肇庆 的交通方便吗？","推荐先到 肇庆，再打车或景区直通车前往核心景区；自驾导航直接搜七星岩即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('青海湖茶卡纯攻略·避坑版3','guide','海南州 · 青海湖茶卡','plateau','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,2,'二郎剑景区 / 茶卡盐湖 / 日月山 —— 纯攻略助你玩透青海湖茶卡精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「青海湖茶卡」三日深度游——高原。青海湖黄蘑菇炖汤鲜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"青海 · 海南州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往海南州，抵达后办理入住、熟悉周边环境。","addr":"海南州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"二郎剑景区","description":"下午首站二郎剑景区，调整状态进入旅行节奏，油菜花与蓝湖，骑行湖岸。","addr":"共和县青海湖南岸","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游海南州一带氛围拉满，晚餐老酸奶人均10元。","addr":"环湖公路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"茶卡盐湖","description":"全天主景点茶卡盐湖，天空之镜，赤脚下盐滩。","addr":"乌兰县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊肉汤（人均35元），早点休息。","addr":"黑马河乡","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"日月山","description":"收官日月山，文成公主进藏口，倒淌河。","addr":"湟源县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糌粑后集合返程，三日旅程圆满。","addr":"茶卡镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"二郎剑景区","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"二郎剑景区是青海湖茶卡最有代表性的看点，油菜花与蓝湖，骑行湖岸。攻略把它排进主线，时间留得最足。","notice":"油菜花与蓝湖，骑行湖岸。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"共和县青海湖南岸"},{"spotId":"S2","name":"茶卡盐湖","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"茶卡盐湖是青海湖茶卡最有代表性的看点，天空之镜，赤脚下盐滩。攻略把它排进主线，时间留得最足。","notice":"天空之镜，赤脚下盐滩。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"乌兰县"},{"spotId":"S3","name":"日月山","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"日月山是青海湖茶卡最有代表性的看点，文成公主进藏口，倒淌河。攻略把它排进主线，时间留得最足。","notice":"文成公主进藏口，倒淌河。这个点位上午光线最好。","durationMinutes":90,"addr":"湟源县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"老酸奶（人均10元）","description":"海南州 · 青海湖茶卡的招牌是老酸奶，青海老酸奶本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"},{"title":"羊肉汤（人均35元）","description":"海南州 · 青海湖茶卡的招牌是羊肉汤，藏家羊汤本地人都认这家，点单照攻略不踩雷。","addr":"黑马河乡"},{"title":"糌粑（人均20元）","description":"海南州 · 青海湖茶卡的招牌是糌粑，牧民家访本地人都认这家，点单照攻略不踩雷。","addr":"茶卡镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","相机或运动相机","墨镜与拍照道具","换洗衣物与外套（早晚温差）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('呼伦贝尔草原纯攻略·深度指南3','guide','呼伦贝尔 · 呼伦贝尔草原','village','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1200,600,1,'莫日格勒河 / 额尔古纳湿地 / 恩和俄罗斯族乡 —— 纯攻略助你玩透呼伦贝尔草原精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「呼伦贝尔草原」两日慢旅行——古村落。呼伦贝尔风干牛肉原味香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"内蒙古 · 呼伦贝尔"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴呼伦贝尔","description":"集合出发，大巴直达呼伦贝尔草原，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"莫日格勒河","description":"抵达后首游莫日格勒河，天下第一曲水，断崖机位。","addr":"陈巴尔虎旗","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐烤羊腿（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"额尔古纳湿地","description":"早起人少，额尔古纳湿地精华时段，亚洲第一湿地，日落金色。","addr":"额尔古纳市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐蒙古锅茶，人均35元，补充体力。","addr":"陈巴尔虎旗","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"恩和俄罗斯族乡","description":"午后游览恩和俄罗斯族乡，木刻楞小屋与列巴。","addr":"额尔古纳市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"莫日格勒河","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"莫日格勒河是呼伦贝尔草原最有代表性的看点，天下第一曲水，断崖机位。攻略把它排进主线，时间留得最足。","notice":"天下第一曲水，断崖机位。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"陈巴尔虎旗"},{"spotId":"S2","name":"额尔古纳湿地","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"额尔古纳湿地是呼伦贝尔草原最有代表性的看点，亚洲第一湿地，日落金色。攻略把它排进主线，时间留得最足。","notice":"亚洲第一湿地，日落金色。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"额尔古纳市"},{"spotId":"S3","name":"恩和俄罗斯族乡","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"恩和俄罗斯族乡是呼伦贝尔草原最有代表性的看点，木刻楞小屋与列巴。攻略把它排进主线，时间留得最足。","notice":"木刻楞小屋与列巴。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"额尔古纳市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤羊腿（人均128元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是烤羊腿，草原牧民人家本地人都认这家，点单照攻略不踩雷。","addr":"黑山头镇"},{"title":"蒙古锅茶（人均35元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是蒙古锅茶，牧户家访本地人都认这家，点单照攻略不踩雷。","addr":"陈巴尔虎旗"},{"title":"俄罗斯列巴（人均15元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是俄罗斯列巴，恩和列巴坊本地人都认这家，点单照攻略不踩雷。","addr":"恩和乡"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","少量零食补给","换洗衣物与外套（早晚温差）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["当地有什么必吃？","到了 呼伦贝尔，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 呼伦贝尔 的交通方便吗？","推荐先到 呼伦贝尔，再打车或景区直通车前往核心景区；自驾导航直接搜呼伦贝尔草原即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 呼伦贝尔 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('婺源篁岭纯攻略·周末版3','guide','上饶 · 婺源篁岭','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',990,500,1,'晒秋人家 / 垒心桥 / 梯田花海 —— 纯攻略助你玩透婺源篁岭精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「婺源篁岭」三日深度游——古村落。婺源荷包红鲤鱼可真空打包带回家。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往上饶，抵达后办理入住、熟悉周边环境。","addr":"上饶市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"晒秋人家","description":"下午首站晒秋人家，调整状态进入旅行节奏，晒秋最佳拍摄位在天街中层，上午顺光。","addr":"婺源县江湾镇篁岭村","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游上饶一带氛围拉满，晚餐蒸汽糕人均28元。","addr":"篁岭天街中段","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"垒心桥","description":"全天主景点垒心桥，桥面风大，手机拿稳。","addr":"篁岭景区索道上站","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐清明果（人均15元），早点休息。","addr":"篁岭古村巷内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"梯田花海","description":"收官梯田花海，春季油菜花、秋季稻浪，两季都出片。","addr":"篁岭村北坡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐荷包红鲤鱼后集合返程，三日旅程圆满。","addr":"篁岭村口第一家","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"晒秋人家","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"晒秋人家是婺源篁岭最有代表性的看点，晒秋最佳拍摄位在天街中层，上午顺光。攻略把它排进主线，时间留得最足。","notice":"晒秋最佳拍摄位在天街中层，上午顺光。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"婺源县江湾镇篁岭村"},{"spotId":"S2","name":"垒心桥","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"垒心桥是婺源篁岭最有代表性的看点，桥面风大，手机拿稳。攻略把它排进主线，时间留得最足。","notice":"桥面风大，手机拿稳。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"篁岭景区索道上站"},{"spotId":"S3","name":"梯田花海","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"梯田花海是婺源篁岭最有代表性的看点，春季油菜花、秋季稻浪，两季都出片。攻略把它排进主线，时间留得最足。","notice":"春季油菜花、秋季稻浪，两季都出片。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"篁岭村北坡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蒸汽糕（人均28元）","description":"上饶 · 婺源篁岭的招牌是蒸汽糕，天街食府本地人都认这家，点单照攻略不踩雷。","addr":"篁岭天街中段"},{"title":"清明果（人均15元）","description":"上饶 · 婺源篁岭的招牌是清明果，晒秋人家小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"篁岭古村巷内"},{"title":"荷包红鲤鱼（人均68元）","description":"上饶 · 婺源篁岭的招牌是荷包红鲤鱼，篁岭酒楼本地人都认这家，点单照攻略不踩雷。","addr":"篁岭村口第一家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","墨镜与拍照道具","相机或运动相机"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 上饶，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 上饶 的交通方便吗？","推荐先到 上饶，再打车或景区直通车前往核心景区；自驾导航直接搜婺源篁岭即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('陶溪川纯攻略·亲子篇3','guide','景德镇 · 陶溪川','art','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,5,'陶溪川文创街区 / 古窑民俗博览区 / 雕塑瓷厂乐天市集 —— 纯攻略助你玩透陶溪川精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「陶溪川」两日慢旅行——文艺。景德镇薄胎瓷碗轻巧又体面。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 景德镇"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴景德镇","description":"集合出发，大巴直达陶溪川，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"陶溪川文创街区","description":"抵达后首游陶溪川文创街区，夜市周五六日开，手作摊最好逛。","addr":"珠山区新厂西路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐饺子粑（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"古窑民俗博览区","description":"早起人少，古窑民俗博览区精华时段，看柴窑镇窑复烧，拉坯体验要排队。","addr":"昌江区枫树山蟠龙岗","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐冷粉，人均12元，补充体力。","addr":"人民广场附近","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"雕塑瓷厂乐天市集","description":"午后游览雕塑瓷厂乐天市集，周六上午开市，淘手作好物。","addr":"新厂东路139号","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"陶溪川文创街区","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"陶溪川文创街区是陶溪川最有代表性的看点，夜市周五六日开，手作摊最好逛。攻略把它排进主线，时间留得最足。","notice":"夜市周五六日开，手作摊最好逛。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"珠山区新厂西路"},{"spotId":"S2","name":"古窑民俗博览区","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"古窑民俗博览区是陶溪川最有代表性的看点，看柴窑镇窑复烧，拉坯体验要排队。攻略把它排进主线，时间留得最足。","notice":"看柴窑镇窑复烧，拉坯体验要排队。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"昌江区枫树山蟠龙岗"},{"spotId":"S3","name":"雕塑瓷厂乐天市集","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"雕塑瓷厂乐天市集是陶溪川最有代表性的看点，周六上午开市，淘手作好物。攻略把它排进主线，时间留得最足。","notice":"周六上午开市，淘手作好物。这个点位上午光线最好。","durationMinutes":90,"addr":"新厂东路139号"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"饺子粑（人均15元）","description":"景德镇 · 陶溪川的招牌是饺子粑，老字号小吃店本地人都认这家，点单照攻略不踩雷。","addr":"中山北路"},{"title":"冷粉（人均12元）","description":"景德镇 · 陶溪川的招牌是冷粉，景德镇冷粉店本地人都认这家，点单照攻略不踩雷。","addr":"人民广场附近"},{"title":"碱水粑炒鸡蛋（人均28元）","description":"景德镇 · 陶溪川的招牌是碱水粑炒鸡蛋，瓷都家常菜本地人都认这家，点单照攻略不踩雷。","addr":"陶溪川周边小馆"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","墨镜与拍照道具","身份证件与手机充电宝","轻便雨衣或折叠伞","保温水杯与少量现金","少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["到达 景德镇 的交通方便吗？","推荐先到 景德镇，再打车或景区直通车前往核心景区；自驾导航直接搜陶溪川即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳麓山橘子洲纯攻略·摄影机位3','guide','长沙 · 岳麓山橘子洲','mountain','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1500,800,2,'岳麓山 / 橘子洲头 / 太平老街 —— 纯攻略助你玩透岳麓山橘子洲精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「岳麓山橘子洲」三日深度游——山岳。长沙湘绣摆件精致好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 长沙"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往长沙，抵达后办理入住、熟悉周边环境。","addr":"长沙市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"岳麓山","description":"下午首站岳麓山，调整状态进入旅行节奏，爱晚亭秋色最美，索道下山省力。","addr":"长沙市岳麓区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游长沙一带氛围拉满，晚餐茶颜悦色人均18元。","addr":"太平老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"橘子洲头","description":"全天主景点橘子洲头，青年毛泽东雕像打卡，小火车代步。","addr":"长沙市橘子洲景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐文和友臭豆腐（人均15元），早点休息。","addr":"海信广场","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"太平老街","description":"收官太平老街，臭豆腐与糖油粑粑的主场。","addr":"长沙市天心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糖油粑粑后集合返程，三日旅程圆满。","addr":"坡子街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"岳麓山","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"岳麓山是岳麓山橘子洲最有代表性的看点，爱晚亭秋色最美，索道下山省力。攻略把它排进主线，时间留得最足。","notice":"爱晚亭秋色最美，索道下山省力。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"长沙市岳麓区"},{"spotId":"S2","name":"橘子洲头","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"橘子洲头是岳麓山橘子洲最有代表性的看点，青年毛泽东雕像打卡，小火车代步。攻略把它排进主线，时间留得最足。","notice":"青年毛泽东雕像打卡，小火车代步。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"长沙市橘子洲景区"},{"spotId":"S3","name":"太平老街","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"太平老街是岳麓山橘子洲最有代表性的看点，臭豆腐与糖油粑粑的主场。攻略把它排进主线，时间留得最足。","notice":"臭豆腐与糖油粑粑的主场。这个点位上午光线最好。","durationMinutes":120,"addr":"长沙市天心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"茶颜悦色（人均18元）","description":"长沙 · 岳麓山橘子洲的招牌是茶颜悦色，太平街店本地人都认这家，点单照攻略不踩雷。","addr":"太平老街"},{"title":"文和友臭豆腐（人均15元）","description":"长沙 · 岳麓山橘子洲的招牌是文和友臭豆腐，文和友本地人都认这家，点单照攻略不踩雷。","addr":"海信广场"},{"title":"糖油粑粑（人均8元）","description":"长沙 · 岳麓山橘子洲的招牌是糖油粑粑，李公庙糖油粑粑本地人都认这家，点单照攻略不踩雷。","addr":"坡子街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","相机或运动相机","身份证件与手机充电宝","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丽江古城玉龙雪山纯攻略·美食清单3','guide','丽江 · 丽江古城玉龙雪山','mountain','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,2,'玉龙雪山 / 蓝月谷 / 丽江古城 —— 纯攻略助你玩透丽江古城玉龙雪山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「丽江古城玉龙雪山」两日慢旅行——山岳。雪山玫瑰饼是最热手信。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 丽江"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴丽江","description":"集合出发，大巴直达丽江古城玉龙雪山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"玉龙雪山","description":"抵达后首游玉龙雪山，大索道直达4506米，租羽绒服买氧气瓶。","addr":"丽江市玉龙县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐腊排骨火锅（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"蓝月谷","description":"早起人少，蓝月谷精华时段，牛奶蓝湖水，电瓶车游三湖。","addr":"玉龙雪山脚下","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐鸡豆凉粉，人均10元，补充体力。","addr":"四方街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"丽江古城","description":"午后游览丽江古城，四方街打跳，狮子山看全景。","addr":"古城区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"玉龙雪山","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"玉龙雪山是丽江古城玉龙雪山最有代表性的看点，大索道直达4506米，租羽绒服买氧气瓶。攻略把它排进主线，时间留得最足。","notice":"大索道直达4506米，租羽绒服买氧气瓶。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"丽江市玉龙县"},{"spotId":"S2","name":"蓝月谷","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"蓝月谷是丽江古城玉龙雪山最有代表性的看点，牛奶蓝湖水，电瓶车游三湖。攻略把它排进主线，时间留得最足。","notice":"牛奶蓝湖水，电瓶车游三湖。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"玉龙雪山脚下"},{"spotId":"S3","name":"丽江古城","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"丽江古城是丽江古城玉龙雪山最有代表性的看点，四方街打跳，狮子山看全景。攻略把它排进主线，时间留得最足。","notice":"四方街打跳，狮子山看全景。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"古城区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"腊排骨火锅（人均68元）","description":"丽江 · 丽江古城玉龙雪山的招牌是腊排骨火锅，象山市场本地人都认这家，点单照攻略不踩雷。","addr":"古城区象山街"},{"title":"鸡豆凉粉（人均10元）","description":"丽江 · 丽江古城玉龙雪山的招牌是鸡豆凉粉，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"四方街"},{"title":"丽江粑粑（人均12元）","description":"丽江 · 丽江古城玉龙雪山的招牌是丽江粑粑，忠义市场本地人都认这家，点单照攻略不踩雷。","addr":"忠义市场内"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","相机或运动相机","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["当地有什么必吃？","到了 丽江，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 丽江 的交通方便吗？","推荐先到 丽江，再打车或景区直通车前往核心景区；自驾导航直接搜丽江古城玉龙雪山即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('稻城亚丁纯攻略·自由行手册3','guide','甘孜 · 稻城亚丁','plateau','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',2500,1300,2,'牛奶海 / 五色海 / 冲古寺草坪 —— 纯攻略助你玩透稻城亚丁精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「稻城亚丁」三日深度游——高原。高原反应别逞强慢慢走。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 甘孜"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往甘孜，抵达后办理入住、熟悉周边环境。","addr":"甘孜市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"牛奶海","description":"下午首站牛奶海，调整状态进入旅行节奏，海拔4600，马帮或徒步，量力而行。","addr":"稻城县香格里拉镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游甘孜一带氛围拉满，晚餐松茸炖鸡人均128元。","addr":"亚丁村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"五色海","description":"全天主景点五色海，最后一百步最陡，景色值得。","addr":"牛奶海上方","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酥油茶（人均15元），早点休息。","addr":"香格里拉镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"冲古寺草坪","description":"收官冲古寺草坪，仙乃日倒影机位。","addr":"亚丁村","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐高原土豆后集合返程，三日旅程圆满。","addr":"洛绒牛场补给点","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"牛奶海","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"牛奶海是稻城亚丁最有代表性的看点，海拔4600，马帮或徒步，量力而行。攻略把它排进主线，时间留得最足。","notice":"海拔4600，马帮或徒步，量力而行。拍照记得留神脚下台阶。","durationMinutes":360,"addr":"稻城县香格里拉镇"},{"spotId":"S2","name":"五色海","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"五色海是稻城亚丁最有代表性的看点，最后一百步最陡，景色值得。攻略把它排进主线，时间留得最足。","notice":"最后一百步最陡，景色值得。这个点位上午光线最好。","durationMinutes":60,"addr":"牛奶海上方"},{"spotId":"S3","name":"冲古寺草坪","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"冲古寺草坪是稻城亚丁最有代表性的看点，仙乃日倒影机位。攻略把它排进主线，时间留得最足。","notice":"仙乃日倒影机位。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"亚丁村"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松茸炖鸡（人均128元）","description":"甘孜 · 稻城亚丁的招牌是松茸炖鸡，亚丁村民宿本地人都认这家，点单照攻略不踩雷。","addr":"亚丁村"},{"title":"酥油茶（人均15元）","description":"甘孜 · 稻城亚丁的招牌是酥油茶，藏家小屋本地人都认这家，点单照攻略不踩雷。","addr":"香格里拉镇"},{"title":"高原土豆（人均10元）","description":"甘孜 · 稻城亚丁的招牌是高原土豆，小卖部熟食本地人都认这家，点单照攻略不踩雷。","addr":"洛绒牛场补给点"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","身份证件与手机充电宝","相机或运动相机","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","少量零食补给","保温水杯与少量现金"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["几月份去 甘孜 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 甘孜 的交通方便吗？","推荐先到 甘孜，再打车或景区直通车前往核心景区；自驾导航直接搜稻城亚丁即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('西江千户苗寨纯攻略·省钱玩法3','guide','黔东南 · 西江千户苗寨','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,1,'西江观景台 / 一号风雨桥 / 嘎歌古巷 —— 纯攻略助你玩透西江千户苗寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「西江千户苗寨」两日慢旅行——古村落。苗银手镯按克计价别按件。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔东南","description":"集合出发，大巴直达西江千户苗寨，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"西江观景台","description":"抵达后首游西江观景台，万家灯火夜景，天黑后1小时最佳。","addr":"雷山县西江镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐苗家酸汤鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"一号风雨桥","description":"早起人少，一号风雨桥精华时段，苗家歌舞表演互动。","addr":"西江苗寨","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐糯米饭，人均10元，补充体力。","addr":"风雨桥头","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"嘎歌古巷","description":"午后游览嘎歌古巷，非遗银饰刺绣工坊。","addr":"西江苗寨","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"西江观景台","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"西江观景台是西江千户苗寨最有代表性的看点，万家灯火夜景，天黑后1小时最佳。攻略把它排进主线，时间留得最足。","notice":"万家灯火夜景，天黑后1小时最佳。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"雷山县西江镇"},{"spotId":"S2","name":"一号风雨桥","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"一号风雨桥是西江千户苗寨最有代表性的看点，苗家歌舞表演互动。攻略把它排进主线，时间留得最足。","notice":"苗家歌舞表演互动。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"西江苗寨"},{"spotId":"S3","name":"嘎歌古巷","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"嘎歌古巷是西江千户苗寨最有代表性的看点，非遗银饰刺绣工坊。攻略把它排进主线，时间留得最足。","notice":"非遗银饰刺绣工坊。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"西江苗寨"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"苗家酸汤鱼（人均68元）","description":"黔东南 · 西江千户苗寨的招牌是苗家酸汤鱼，阿浓苗家本地人都认这家，点单照攻略不踩雷。","addr":"西江主街"},{"title":"糯米饭（人均10元）","description":"黔东南 · 西江千户苗寨的招牌是糯米饭，苗家早餐摊本地人都认这家，点单照攻略不踩雷。","addr":"风雨桥头"},{"title":"米豆腐（人均12元）","description":"黔东南 · 西江千户苗寨的招牌是米豆腐，古巷小吃本地人都认这家，点单照攻略不踩雷。","addr":"嘎歌古巷"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","少量零食补给","防晒霜与遮阳帽","身份证件与手机充电宝","保温水杯与少量现金","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 黔东南 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 黔东南，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('德天跨国瀑布纯攻略·避坑版3','guide','崇左 · 德天跨国瀑布','water','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',990,500,2,'德天瀑布 / 明仕田园 / 53号界碑 —— 纯攻略助你玩透德天跨国瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「德天跨国瀑布」三日深度游——水景。崇左酸嘢开胃解腻。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 崇左"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往崇左，抵达后办理入住、熟悉周边环境。","addr":"崇左市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"德天瀑布","description":"下午首站德天瀑布，调整状态进入旅行节奏，亚洲第一跨国瀑布，竹筏近观。","addr":"大新县硕龙镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游崇左一带氛围拉满，晚餐越式卷粉人均12元。","addr":"硕龙镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"明仕田园","description":"全天主景点明仕田园，小桂林田园风光，骑行环线。","addr":"大新县明仕村","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐烤香猪（人均58元），早点休息。","addr":"德天游客中心","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"53号界碑","description":"收官53号界碑，中越边境打卡。","addr":"德天景区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸嘢后集合返程，三日旅程圆满。","addr":"明仕田园","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"德天瀑布","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"德天瀑布是德天跨国瀑布最有代表性的看点，亚洲第一跨国瀑布，竹筏近观。攻略把它排进主线，时间留得最足。","notice":"亚洲第一跨国瀑布，竹筏近观。这个点位上午光线最好。","durationMinutes":180,"addr":"大新县硕龙镇"},{"spotId":"S2","name":"明仕田园","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"明仕田园是德天跨国瀑布最有代表性的看点，小桂林田园风光，骑行环线。攻略把它排进主线，时间留得最足。","notice":"小桂林田园风光，骑行环线。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大新县明仕村"},{"spotId":"S3","name":"53号界碑","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"53号界碑是德天跨国瀑布最有代表性的看点，中越边境打卡。攻略把它排进主线，时间留得最足。","notice":"中越边境打卡。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"德天景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"越式卷粉（人均12元）","description":"崇左 · 德天跨国瀑布的招牌是越式卷粉，边关小吃本地人都认这家，点单照攻略不踩雷。","addr":"硕龙镇"},{"title":"烤香猪（人均58元）","description":"崇左 · 德天跨国瀑布的招牌是烤香猪，壮乡风味本地人都认这家，点单照攻略不踩雷。","addr":"德天游客中心"},{"title":"酸嘢（人均10元）","description":"崇左 · 德天跨国瀑布的招牌是酸嘢，水果酸摊本地人都认这家，点单照攻略不踩雷。","addr":"明仕田园"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","保温水杯与少量现金","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","身份证件与手机充电宝","相机或运动相机","少量零食补给","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 崇左 的交通方便吗？","推荐先到 崇左，再打车或景区直通车前往核心景区；自驾导航直接搜德天跨国瀑布即可。"],["几月份去 崇左 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌镇西栅纯攻略·深度指南3','guide','嘉兴 · 乌镇西栅','ancient_town','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',990,500,1,'乌镇西栅 / 木心美术馆 / 南浔古镇 —— 纯攻略助你玩透乌镇西栅精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「乌镇西栅」两日慢旅行——古镇。乌镇蓝印花布制品雅致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 嘉兴"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴嘉兴","description":"集合出发，大巴直达乌镇西栅，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乌镇西栅","description":"抵达后首游乌镇西栅，夜景封神，染坊与书院。","addr":"桐乡市乌镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红烧羊肉（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"木心美术馆","description":"早起人少，木心美术馆精华时段，建筑与展览双重享受。","addr":"西栅景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐定胜糕，人均10元，补充体力。","addr":"乌镇南栅","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南浔古镇","description":"午后游览南浔古镇，人少水乡，百间楼原生。","addr":"湖州南浔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乌镇西栅","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"乌镇西栅是乌镇西栅最有代表性的看点，夜景封神，染坊与书院。攻略把它排进主线，时间留得最足。","notice":"夜景封神，染坊与书院。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"桐乡市乌镇"},{"spotId":"S2","name":"木心美术馆","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"木心美术馆是乌镇西栅最有代表性的看点，建筑与展览双重享受。攻略把它排进主线，时间留得最足。","notice":"建筑与展览双重享受。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"西栅景区"},{"spotId":"S3","name":"南浔古镇","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"南浔古镇是乌镇西栅最有代表性的看点，人少水乡，百间楼原生。攻略把它排进主线，时间留得最足。","notice":"人少水乡，百间楼原生。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"湖州南浔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红烧羊肉（人均45元）","description":"嘉兴 · 乌镇西栅的招牌是红烧羊肉，书生羊肉面本地人都认这家，点单照攻略不踩雷。","addr":"西栅大街"},{"title":"定胜糕（人均10元）","description":"嘉兴 · 乌镇西栅的招牌是定胜糕，小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"乌镇南栅"},{"title":"白水鱼（人均58元）","description":"嘉兴 · 乌镇西栅的招牌是白水鱼，水乡渔家本地人都认这家，点单照攻略不踩雷。","addr":"南浔百间楼"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","墨镜与拍照道具","保温水杯与少量现金","轻便雨衣或折叠伞","相机或运动相机","身份证件与手机充电宝","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'慢一点，风景才来得及认识你。','on');
