INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三峡人家纯攻略·亲子篇3','guide','宜昌 · 三峡人家','water','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',990,500,2,'三峡人家 / 三峡大坝 / 清江画廊 —— 纯攻略助你玩透三峡人家精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「三峡人家」两日慢旅行——水景。宜昌柑橘橙都好吃。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 宜昌"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宜昌","description":"集合出发，大巴直达三峡人家，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"三峡人家","description":"抵达后首游三峡人家，灯影石与龙进溪，土家婚俗表演。","addr":"宜昌市夷陵区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐峡口肥鱼（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三峡大坝","description":"早起人少，三峡大坝精华时段，国之重器，坛子岭俯瞰。","addr":"夷陵区三斗坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐懒豆腐，人均28元，补充体力。","addr":"三峡人家景区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"清江画廊","description":"午后游览清江画廊，乘船入画，巴人发源地。","addr":"长阳县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"三峡人家","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"三峡人家是三峡人家最有代表性的看点，灯影石与龙进溪，土家婚俗表演。攻略把它排进主线，时间留得最足。","notice":"灯影石与龙进溪，土家婚俗表演。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"宜昌市夷陵区"},{"spotId":"S2","name":"三峡大坝","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"三峡大坝是三峡人家最有代表性的看点，国之重器，坛子岭俯瞰。攻略把它排进主线，时间留得最足。","notice":"国之重器，坛子岭俯瞰。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"夷陵区三斗坪镇"},{"spotId":"S3","name":"清江画廊","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"清江画廊是三峡人家最有代表性的看点，乘船入画，巴人发源地。攻略把它排进主线，时间留得最足。","notice":"乘船入画，巴人发源地。这个点位上午光线最好。","durationMinutes":180,"addr":"长阳县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"峡口肥鱼（人均88元）","description":"宜昌 · 三峡人家的招牌是峡口肥鱼，江边鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"三斗坪"},{"title":"懒豆腐（人均28元）","description":"宜昌 · 三峡人家的招牌是懒豆腐，土家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"三峡人家景区"},{"title":"清江银鱼（人均45元）","description":"宜昌 · 三峡人家的招牌是清江银鱼，水产馆本地人都认这家，点单照攻略不踩雷。","addr":"长阳县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","相机或运动相机","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 宜昌 的交通方便吗？","推荐先到 宜昌，再打车或景区直通车前往核心景区；自驾导航直接搜三峡人家即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('华山纯攻略·摄影机位3','guide','渭南 · 华山','adventure','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,9,'东峰朝阳峰 / 西峰莲花峰 / 苍龙岭 —— 纯攻略助你玩透华山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「华山」三日深度游——探险地。华山论剑碑打卡要排队。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 渭南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往渭南，抵达后办理入住、熟悉周边环境。","addr":"渭南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"东峰朝阳峰","description":"下午首站东峰朝阳峰，调整状态进入旅行节奏，长空栈道与鹞子翻身，排队2小时。","addr":"华阴市华山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游渭南一带氛围拉满，晚餐大刀面人均18元。","addr":"华阴市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西峰莲花峰","description":"全天主景点西峰莲花峰，索道直达，斧劈石传说。","addr":"华山最美峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐踅面（人均15元），早点休息。","addr":"华山脚下","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"苍龙岭","description":"收官苍龙岭，岭脊如龙，两侧深渊。","addr":"华山中段","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐秦镇米皮后集合返程，三日旅程圆满。","addr":"玉泉院旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"东峰朝阳峰","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"东峰朝阳峰是华山最有代表性的看点，长空栈道与鹞子翻身，排队2小时。攻略把它排进主线，时间留得最足。","notice":"长空栈道与鹞子翻身，排队2小时。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"华阴市华山风景区"},{"spotId":"S2","name":"西峰莲花峰","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"西峰莲花峰是华山最有代表性的看点，索道直达，斧劈石传说。攻略把它排进主线，时间留得最足。","notice":"索道直达，斧劈石传说。这个点位上午光线最好。","durationMinutes":180,"addr":"华山最美峰"},{"spotId":"S3","name":"苍龙岭","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"苍龙岭是华山最有代表性的看点，岭脊如龙，两侧深渊。攻略把它排进主线，时间留得最足。","notice":"岭脊如龙，两侧深渊。这个点位上午光线最好。","durationMinutes":90,"addr":"华山中段"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"大刀面（人均18元）","description":"渭南 · 华山的招牌是大刀面，华阴老字号本地人都认这家，点单照攻略不踩雷。","addr":"华阴市区"},{"title":"踅面（人均15元）","description":"渭南 · 华山的招牌是踅面，合阳踅面本地人都认这家，点单照攻略不踩雷。","addr":"华山脚下"},{"title":"秦镇米皮（人均12元）","description":"渭南 · 华山的招牌是秦镇米皮，老秦镇本地人都认这家，点单照攻略不踩雷。","addr":"玉泉院旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","相机或运动相机","换洗衣物与外套（早晚温差）","保温水杯与少量现金","防晒霜与遮阳帽","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('曲阜三孔纯攻略·美食清单3','guide','济宁 · 曲阜三孔','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',2500,1300,7,'孔庙 / 孔府 / 孔林 —— 纯攻略助你玩透曲阜三孔精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「曲阜三孔」两日慢旅行——人文。曲阜楷木雕如意吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 济宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴济宁","description":"集合出发，大巴直达曲阜三孔，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"孔庙","description":"抵达后首游孔庙，祭孔大典地，古柏森森。","addr":"济宁市曲阜市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐孔府菜（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"孔府","description":"早起人少，孔府精华时段，天下第一家，后花园。","addr":"曲阜","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山东煎饼，人均10元，补充体力。","addr":"鼓楼街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"孔林","description":"午后游览孔林，至圣林，孔子墓。","addr":"曲阜","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"孔庙","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"孔庙是曲阜三孔最有代表性的看点，祭孔大典地，古柏森森。攻略把它排进主线，时间留得最足。","notice":"祭孔大典地，古柏森森。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"济宁市曲阜市"},{"spotId":"S2","name":"孔府","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","hi