INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('亚龙湾蜈支洲纯攻略·自由行手册3','guide','三亚 · 亚龙湾蜈支洲','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',990,500,6,'蜈支洲岛 / 亚龙湾热带天堂森林公园 / 后海村 —— 纯攻略助你玩透亚龙湾蜈支洲精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「亚龙湾蜈支洲」三日深度游——海滨。三亚贵妃芒香甜多汁。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 三亚"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往三亚，抵达后办理入住、熟悉周边环境。","addr":"三亚市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜈支洲岛","description":"下午首站蜈支洲岛，调整状态进入旅行节奏，中国马尔代夫，潜水胜地。","addr":"三亚市海棠区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游三亚一带氛围拉满，晚餐椰子鸡人均78元。","addr":"后海村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"亚龙湾热带天堂森林公园","description":"全天主景点亚龙湾热带天堂森林公园，过江龙索道，电影取景地。","addr":"亚龙湾","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐清补凉（人均15元），早点休息。","addr":"第一市场","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"后海村","description":"收官后海村，冲浪初学者天堂，夜市。","addr":"海棠湾","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐海鲜加工后集合返程，三日旅程圆满。","addr":"新民街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜈支洲岛","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"蜈支洲岛是亚龙湾蜈支洲最有代表性的看点，中国马尔代夫，潜水胜地。攻略把它排进主线，时间留得最足。","notice":"中国马尔代夫，潜水胜地。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"三亚市海棠区"},{"spotId":"S2","name":"亚龙湾热带天堂森林公园","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"亚龙湾热带天堂森林公园是亚龙湾蜈支洲最有代表性的看点，过江龙索道，电影取景地。攻略把它排进主线，时间留得最足。","notice":"过江龙索道，电影取景地。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"亚龙湾"},{"spotId":"S3","name":"后海村","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"后海村是亚龙湾蜈支洲最有代表性的看点，冲浪初学者天堂，夜市。攻略把它排进主线，时间留得最足。","notice":"冲浪初学者天堂，夜市。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"海棠湾"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"椰子鸡（人均78元）","description":"三亚 · 亚龙湾蜈支洲的招牌是椰子鸡，萌哒哒椰子鸡本地人都认这家，点单照攻略不踩雷。","addr":"后海村"},{"title":"清补凉（人均15元）","description":"三亚 · 亚龙湾蜈支洲的招牌是清补凉，一馨清补凉本地人都认这家，点单照攻略不踩雷。","addr":"第一市场"},{"title":"海鲜加工（人均98元）","description":"三亚 · 亚龙湾蜈支洲的招牌是海鲜加工，第一市场本地人都认这家，点单照攻略不踩雷。","addr":"新民街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","少量零食补给","防晒霜与遮阳帽","相机或运动相机","墨镜与拍照道具","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('塔尔寺纯攻略·省钱玩法3','guide','西宁 · 塔尔寺','red','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1990,1000,7,'塔尔寺 / 东关清真大寺 / 青海省博物馆 —— 纯攻略助你玩透塔尔寺精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「塔尔寺」两日慢旅行——人文。西宁牦牛绒围巾暖和。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"青海 · 西宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴西宁","description":"集合出发，大巴直达塔尔寺，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"塔尔寺","description":"抵达后首游塔尔寺，酥油花壁画堆绣三绝。","addr":"湟中区鲁沙尔镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐手抓羊肉（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"东关清真大寺","description":"早起人少，东关清真大寺精华时段，西北四大清真寺之一。","addr":"西宁市城东区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酿皮，人均12元，补充体力。","addr":"莫家街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"青海省博物馆","description":"午后游览青海省博物馆，了解高原文明。","addr":"城西区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"塔尔寺","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"塔尔寺是塔尔寺最有代表性的看点，酥油花壁画堆绣三绝。攻略把它排进主线，时间留得最足。","notice":"酥油花壁画堆绣三绝。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"湟中区鲁沙尔镇"},{"spotId":"S2","name":"东关清真大寺","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"东关清真大寺是塔尔寺最有代表性的看点，西北四大清真寺之一。攻略把它排进主线，时间留得最足。","notice":"西北四大清真寺之一。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"西宁市城东区"},{"spotId":"S3","name":"青海省博物馆","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"青海省博物馆是塔尔寺最有代表性的看点，了解高原文明。攻略把它排进主线，时间留得最足。","notice":"了解高原文明。这个点位上午光线最好。","durationMinutes":90,"addr":"城西区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"手抓羊肉（人均58元）","description":"西宁 · 塔尔寺的招牌是手抓羊肉，益鑫手抓本地人都认这家，点单照攻略不踩雷。","addr":"礼让街"},{"title":"酿皮（人均12元）","description":"西宁 · 塔尔寺的招牌是酿皮，马忠食府本地人都认这家，点单照攻略不踩雷。","addr":"莫家街"},{"title":"甜醅（人均8元）","description":"西宁 · 塔尔寺的招牌是甜醅，小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"水井巷"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","轻便雨衣或折叠伞","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","少量零食补给","常用药品（肠胃药/创可贴）","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["几月份去 西宁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 西宁 的交通方便吗？","推荐先到 西宁，再打车或景区直通车前往核心景区；自驾导航直接搜塔尔寺即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滨海路金石滩纯攻略·避坑版3','guide','大连 · 滨海路金石滩','sea','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',990,500,6,'滨海路木栈道 / 金石滩国家地质公园 / 星海广场 —— 纯攻略助你玩透滨海路金石滩精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「滨海路金石滩」三日深度游——海滨。大连海参干货首选。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"辽宁 · 大连"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大连，抵达后办理入住、熟悉周边环境。","addr":"大连市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"滨海路木栈道","description":"下午首站滨海路木栈道，调整状态进入旅行节奏，山海相依城市步道，北大桥日落。","addr":"大连市中山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大连一带氛围拉满，晚餐海鲜焖子人均48元。","addr":"滨海路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"金石滩国家地质公园","description":"全天主景点金石滩国家地质公园，恐龙探海奇石，龟裂石。","addr":"金州区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海胆蒸蛋（人均68元），早点休息。","addr":"老虎滩","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"星海广场","description":"收官星海广场，亚洲最大城市广场，夜景。","addr":"沙河口区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐铁板鱿鱼后集合返程，三日旅程圆满。","addr":"西安路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"滨海路木栈道","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"滨海路木栈道是滨海路金石滩最有代表性的看点，山海相依城市步道，北大桥日落。攻略把它排进主线，时间留得最足。","notice":"山海相依城市步道，北大桥日落。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大连市中山区"},{"spotId":"S2","name":"金石滩国家地质公园","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"金石滩国家地质公园是滨海路金石滩最有代表性的看点，恐龙探海奇石，龟裂石。攻略把它排进主线，时间留得最足。","notice":"恐龙探海奇石，龟裂石。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"金州区"},{"spotId":"S3","name":"星海广场","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"星海广场是滨海路金石滩最有代表性的看点，亚洲最大城市广场，夜景。攻略把它排进主线，时间留得最足。","notice":"亚洲最大城市广场，夜景。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"沙河口区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜焖子（人均48元）","description":"大连 · 滨海路金石滩的招牌是海鲜焖子，品海楼本地人都认这家，点单照攻略不踩雷。","addr":"滨海路"},{"title":"海胆蒸蛋（人均68元）","description":"大连 · 滨海路金石滩的招牌是海胆蒸蛋，日丰园本地人都认这家，点单照攻略不踩雷。","addr":"老虎滩"},{"title":"铁板鱿鱼（人均25元）","description":"大连 · 滨海路金石滩的招牌是铁板鱿鱼，中央大道夜市本地人都认这家，点单照攻略不踩雷。","addr":"西安路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","防晒霜与遮阳帽","轻便雨衣或折叠伞","墨镜与拍照道具","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 大连，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 大连 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三清山纯攻略·深度指南3','guide','上饶 · 三清山','mountain','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1990,1000,2,'南清园 / 阳光海岸 / 万寿园 —— 纯攻略助你玩透三清山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「三清山」两日慢旅行——山岳。三清山猴头菇干货是手信首选。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴上饶","description":"集合出发，大巴直达三清山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"南清园","description":"抵达后首游南清园，巨蟒出山、东方女神都在这条环线，台阶多备水。","addr":"三清山风景区南门","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐石鸡汤锅（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"阳光海岸","description":"早起人少，阳光海岸精华时段，栈道悬空，恐高走东线缓冲段。","addr":"三清山高空栈道","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐野艾果，人均10元，补充体力。","addr":"南山索道下站旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"万寿园","description":"午后游览万寿园，坡缓树多，适合收尾慢慢走。","addr":"三清山南部入口","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"南清园","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"南清园是三清山最有代表性的看点，巨蟒出山、东方女神都在这条环线，台阶多备水。攻略把它排进主线，时间留得最足。","notice":"巨蟒出山、东方女神都在这条环线，台阶多备水。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"三清山风景区南门"},{"spotId":"S2","name":"阳光海岸","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"阳光海岸是三清山最有代表性的看点，栈道悬空，恐高走东线缓冲段。攻略把它排进主线，时间留得最足。","notice":"栈道悬空，恐高走东线缓冲段。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"三清山高空栈道"},{"spotId":"S3","name":"万寿园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"万寿园是三清山最有代表性的看点，坡缓树多，适合收尾慢慢走。攻略把它排进主线，时间留得最足。","notice":"坡缓树多，适合收尾慢慢走。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"三清山南部入口"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"石鸡汤锅（人均58元）","description":"上饶 · 三清山的招牌是石鸡汤锅，山脚农家菜本地人都认这家，点单照攻略不踩雷。","addr":"三清山外双溪服务区"},{"title":"野艾果（人均10元）","description":"上饶 · 三清山的招牌是野艾果，路边农家本地人都认这家，点单照攻略不踩雷。","addr":"南山索道下站旁"},{"title":"三清山烧饼（人均8元）","description":"上饶 · 三清山的招牌是三清山烧饼，南清园补给点本地人都认这家，点单照攻略不踩雷。","addr":"登山途中补给站"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","身份证件与手机充电宝","保温水杯与少量现金","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["到达 上饶 的交通方便吗？","推荐先到 上饶，再打车或景区直通车前往核心景区；自驾导航直接搜三清山即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 上饶，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('明月山纯攻略·周末版3','guide','宜春 · 明月山','mountain','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',990,500,2,'青云栈道 / 云谷飞瀑 / 温汤镇古井泉街 —— 纯攻略助你玩透明月山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「明月山」三日深度游——山岳。温汤富硒温泉蛋一元一个。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 宜春"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜春，抵达后办理入住、熟悉周边环境。","addr":"宜春市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"青云栈道","description":"下午首站青云栈道，调整状态进入旅行节奏，悬空栈道绕山腰，云雾天如仙境。","addr":"明月山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜春一带氛围拉满，晚餐温泉豆腐人均48元。","addr":"温汤镇古井旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"云谷飞瀑","description":"全天主景点云谷飞瀑，宜春八景之一，负氧离子爆表。","addr":"明月山核心景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐慈化鸡爪（人均22元），早点休息。","addr":"温汤镇主街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"温汤镇古井泉街","description":"收官温汤镇古井泉街，富硒温泉足浴28元一位，晚上泡最解乏。","addr":"袁州区温汤镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐扎粉后集合返程，三日旅程圆满。","addr":"古井泉街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"青云栈道","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"青云栈道是明月山最有代表性的看点，悬空栈道绕山腰，云雾天如仙境。攻略把它排进主线，时间留得最足。","notice":"悬空栈道绕山腰，云雾天如仙境。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"明月山风景区"},{"spotId":"S2","name":"云谷飞瀑","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"云谷飞瀑是明月山最有代表性的看点，宜春八景之一，负氧离子爆表。攻略把它排进主线，时间留得最足。","notice":"宜春八景之一，负氧离子爆表。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"明月山核心景区"},{"spotId":"S3","name":"温汤镇古井泉街","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"温汤镇古井泉街是明月山最有代表性的看点，富硒温泉足浴28元一位，晚上泡最解乏。攻略把它排进主线，时间留得最足。","notice":"富硒温泉足浴28元一位，晚上泡最解乏。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"袁州区温汤镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"温泉豆腐（人均48元）","description":"宜春 · 明月山的招牌是温泉豆腐，温汤镇豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇古井旁"},{"title":"慈化鸡爪（人均22元）","description":"宜春 · 明月山的招牌是慈化鸡爪，宜春小吃店本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇主街"},{"title":"扎粉（人均15元）","description":"宜春 · 明月山的招牌是扎粉，宜春扎粉店本地人都认这家，点单照攻略不踩雷。","addr":"古井泉街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","相机或运动相机","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 宜春，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南岳衡山纯攻略·亲子篇3','guide','衡阳 · 南岳衡山','mountain','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,2,'祝融峰 / 南岳大庙 / 藏经殿 —— 纯攻略助你玩透南岳衡山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「南岳衡山」两日慢旅行——山岳。南岳香文化用品别乱买。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 衡阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴衡阳","description":"集合出发，大巴直达南岳衡山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"祝融峰","description":"抵达后首游祝融峰，五岳最高峰观日出，山顶租赁军大衣。","addr":"南岳区衡山风景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐南岳素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"南岳大庙","description":"早起人少，南岳大庙精华时段，江南第一庙，香火极旺。","addr":"南岳区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐观音笋，人均38元，补充体力。","addr":"半山亭","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"藏经殿","description":"午后游览藏经殿，幽谷深林中的古刹。","addr":"衡山半山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"祝融峰","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"祝融峰是南岳衡山最有代表性的看点，五岳最高峰观日出，山顶租赁军大衣。攻略把它排进主线，时间留得最足。","notice":"五岳最高峰观日出，山顶租赁军大衣。这个点位上午光线最好。","durationMinutes":240,"addr":"南岳区衡山风景区"},{"spotId":"S2","name":"南岳大庙","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"南岳大庙是南岳衡山最有代表性的看点，江南第一庙，香火极旺。攻略把它排进主线，时间留得最足。","notice":"江南第一庙，香火极旺。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"南岳区"},{"spotId":"S3","name":"藏经殿","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"藏经殿是南岳衡山最有代表性的看点，幽谷深林中的古刹。攻略把它排进主线，时间留得最足。","notice":"幽谷深林中的古刹。这个点位上午光线最好。","durationMinutes":90,"addr":"衡山半山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"南岳素斋（人均48元）","description":"衡阳 · 南岳衡山的招牌是南岳素斋，大庙素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"南岳大庙旁"},{"title":"观音笋（人均38元）","description":"衡阳 · 南岳衡山的招牌是观音笋，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"半山亭"},{"title":"衡山云雾茶（人均30元）","description":"衡阳 · 南岳衡山的招牌是衡山云雾茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"南岳镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","相机或运动相机","常用药品（肠胃药/创可贴）","保温水杯与少量现金","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["到达 衡阳 的交通方便吗？","推荐先到 衡阳，再打车或景区直通车前往核心景区；自驾导航直接搜南岳衡山即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('香格里拉纯攻略·摄影机位3','guide','迪庆 · 香格里拉','plateau','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1200,600,2,'普达措国家公园 / 松赞林寺 / 独克宗古城 —— 纯攻略助你玩透香格里拉精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「香格里拉」三日深度游——高原。牦牛肉干认准风干原味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 迪庆"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往迪庆，抵达后办理入住、熟悉周边环境。","addr":"迪庆市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"普达措国家公园","description":"下午首站普达措国家公园，调整状态进入旅行节奏，属都湖栈道环湖，高原慢慢走。","addr":"香格里拉市建塘镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游迪庆一带氛围拉满，晚餐牦牛肉火锅人均88元。","addr":"独克宗古城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"松赞林寺","description":"全天主景点松赞林寺，小布达拉宫，顺时针转寺。","addr":"香格里拉市佛屏山前","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酥油茶（人均20元），早点休息。","addr":"古城内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"独克宗古城","description":"收官独克宗古城，转世界最大转经筒，夜景美。","addr":"香格里拉市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐青稞饼后集合返程，三日旅程圆满。","addr":"池慈卡街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"普达措国家公园","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"普达措国家公园是香格里拉最有代表性的看点，属都湖栈道环湖，高原慢慢走。攻略把它排进主线，时间留得最足。","notice":"属都湖栈道环湖，高原慢慢走。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"香格里拉市建塘镇"},{"spotId":"S2","name":"松赞林寺","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"松赞林寺是香格里拉最有代表性的看点，小布达拉宫，顺时针转寺。攻略把它排进主线，时间留得最足。","notice":"小布达拉宫，顺时针转寺。这个点位上午光线最好。","durationMinutes":120,"addr":"香格里拉市佛屏山前"},{"spotId":"S3","name":"独克宗古城","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"独克宗古城是香格里拉最有代表性的看点，转世界最大转经筒，夜景美。攻略把它排进主线，时间留得最足。","notice":"转世界最大转经筒，夜景美。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"香格里拉市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉火锅（人均88元）","description":"迪庆 · 香格里拉的招牌是牦牛肉火锅，市井牦牛火锅本地人都认这家，点单照攻略不踩雷。","addr":"独克宗古城"},{"title":"酥油茶（人均20元）","description":"迪庆 · 香格里拉的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"青稞饼（人均12元）","description":"迪庆 · 香格里拉的招牌是青稞饼，藏式饼铺本地人都认这家，点单照攻略不踩雷。","addr":"池慈卡街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 迪庆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('峨眉山乐山大佛纯攻略·美食清单3','guide','乐山 · 峨眉山乐山大佛','mountain','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,2,'乐山大佛 / 峨眉山金顶 / 清音阁 —— 纯攻略助你玩透峨眉山乐山大佛精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「峨眉山乐山大佛」两日慢旅行——山岳。峨眉雪芽茶清甜回甘。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 乐山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴乐山","description":"集合出发，大巴直达峨眉山乐山大佛，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乐山大佛","description":"抵达后首游乐山大佛，九曲栈道近距离看大佛脚背。","addr":"乐山市凌云路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐钵钵鸡（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"峨眉山金顶","description":"早起人少，峨眉山金顶精华时段，十方普贤金像，云海日出。","addr":"峨眉山市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐甜皮鸭，人均28元，补充体力。","addr":"乐山张公桥","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"清音阁","description":"午后游览清音阁，双桥清音，平路好走。","addr":"峨眉山低山区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乐山大佛","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"乐山大佛是峨眉山乐山大佛最有代表性的看点，九曲栈道近距离看大佛脚背。攻略把它排进主线，时间留得最足。","notice":"九曲栈道近距离看大佛脚背。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"乐山市凌云路"},{"spotId":"S2","name":"峨眉山金顶","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"峨眉山金顶是峨眉山乐山大佛最有代表性的看点，十方普贤金像，云海日出。攻略把它排进主线，时间留得最足。","notice":"十方普贤金像，云海日出。这个点位上午光线最好。","durationMinutes":300,"addr":"峨眉山市"},{"spotId":"S3","name":"清音阁","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"清音阁是峨眉山乐山大佛最有代表性的看点，双桥清音，平路好走。攻略把它排进主线，时间留得最足。","notice":"双桥清音，平路好走。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"峨眉山低山区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"钵钵鸡（人均35元）","description":"乐山 · 峨眉山乐山大佛的招牌是钵钵鸡，叶婆婆本地人都认这家，点单照攻略不踩雷。","addr":"乐山港"},{"title":"甜皮鸭（人均28元）","description":"乐山 · 峨眉山乐山大佛的招牌是甜皮鸭，赵鸭子本地人都认这家，点单照攻略不踩雷。","addr":"乐山张公桥"},{"title":"豆腐脑（人均12元）","description":"乐山 · 峨眉山乐山大佛的招牌是豆腐脑，峨眉豆腐脑本地人都认这家，点单照攻略不踩雷。","addr":"峨眉市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","保温水杯与少量现金","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","相机或运动相机","防晒霜与遮阳帽","墨镜与拍照道具","少量零食补给"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 乐山，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('梵净山纯攻略·自由行手册3','guide','铜仁 · 梵净山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1200,600,2,'红云金顶 / 蘑菇石 / 承恩寺 —— 纯攻略助你玩透梵净山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「梵净山」三日深度游——山岳。梵净山藤茶甘甜养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 铜仁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往铜仁，抵达后办理入住、熟悉周边环境。","addr":"铜仁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"红云金顶","description":"下午首站红云金顶，调整状态进入旅行节奏，海拔2493双峰寺庙，爬铁索上天桥。","addr":"铜仁市江口县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游铜仁一带氛围拉满，晚餐江口豆腐干人均28元。","addr":"梵净山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"蘑菇石","description":"全天主景点蘑菇石，10亿年奇石，排队打卡。","addr":"梵净山标志性景观","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐米虾（人均48元），早点休息。","addr":"太平镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"承恩寺","description":"收官承恩寺，明代古刹，云海时分最妙。","addr":"金顶下方","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐天麻炖鸡后集合返程，三日旅程圆满。","addr":"江口县城","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"红云金顶","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"红云金顶是梵净山最有代表性的看点，海拔2493双峰寺庙，爬铁索上天桥。攻略把它排进主线，时间留得最足。","notice":"海拔2493双峰寺庙，爬铁索上天桥。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"铜仁市江口县"},{"spotId":"S2","name":"蘑菇石","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"蘑菇石是梵净山最有代表性的看点，10亿年奇石，排队打卡。攻略把它排进主线，时间留得最足。","notice":"10亿年奇石，排队打卡。这个点位上午光线最好。","durationMinutes":60,"addr":"梵净山标志性景观"},{"spotId":"S3","name":"承恩寺","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"承恩寺是梵净山最有代表性的看点，明代古刹，云海时分最妙。攻略把它排进主线，时间留得最足。","notice":"明代古刹，云海时分最妙。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"金顶下方"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"江口豆腐干（人均28元）","description":"铜仁 · 梵净山的招牌是江口豆腐干，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"梵净山镇"},{"title":"米虾（人均48元）","description":"铜仁 · 梵净山的招牌是米虾，河鲜馆本地人都认这家，点单照攻略不踩雷。","addr":"太平镇"},{"title":"天麻炖鸡（人均88元）","description":"铜仁 · 梵净山的招牌是天麻炖鸡，药膳馆本地人都认这家，点单照攻略不踩雷。","addr":"江口县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","保温水杯与少量现金","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道"],"faqs":[["到达 铜仁 的交通方便吗？","推荐先到 铜仁，再打车或景区直通车前往核心景区；自驾导航直接搜梵净山即可。"],["几月份去 铜仁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('程阳八寨纯攻略·省钱玩法3','guide','柳州 · 程阳八寨','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,1,'程阳八寨 / 三江侗天宫 / 窑埠古镇 —— 纯攻略助你玩透程阳八寨精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「程阳八寨」两日慢旅行——古村落。柳州螺蛳粉袋装正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 柳州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴柳州","description":"集合出发，大巴直达程阳八寨，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"程阳八寨","description":"抵达后首游程阳八寨，风雨桥鼓楼，侗族百家宴。","addr":"柳州市三江县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐螺蛳粉（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三江侗天宫","description":"早起人少，三江侗天宫精华时段，侗族文化大观。","addr":"三江县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐百家宴，人均58元，补充体力。","addr":"程阳八寨","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"窑埠古镇","description":"午后游览窑埠古镇，百里柳江夜景起点。","addr":"柳州市区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"程阳八寨","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"程阳八寨是程阳八寨最有代表性的看点，风雨桥鼓楼，侗族百家宴。攻略把它排进主线，时间留得最足。","notice":"风雨桥鼓楼，侗族百家宴。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"柳州市三江县"},{"spotId":"S2","name":"三江侗天宫","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"三江侗天宫是程阳八寨最有代表性的看点，侗族文化大观。攻略把它排进主线，时间留得最足。","notice":"侗族文化大观。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"三江县"},{"spotId":"S3","name":"窑埠古镇","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"窑埠古镇是程阳八寨最有代表性的看点，百里柳江夜景起点。攻略把它排进主线，时间留得最足。","notice":"百里柳江夜景起点。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"柳州市区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"螺蛳粉（人均15元）","description":"柳州 · 程阳八寨的招牌是螺蛳粉，爱民螺蛳粉本地人都认这家，点单照攻略不踩雷。","addr":"柳州市区"},{"title":"百家宴（人均58元）","description":"柳州 · 程阳八寨的招牌是百家宴，程阳八寨本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"},{"title":"打油茶（人均20元）","description":"柳州 · 程阳八寨的招牌是打油茶，寨中茶楼本地人都认这家，点单照攻略不踩雷。","addr":"程阳八寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","防晒霜与遮阳帽","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 柳州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 柳州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('普陀山纯攻略·避坑版3','guide','舟山 · 普陀山','sea','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',990,500,6,'普济寺 / 南海观音 / 百步沙 —— 纯攻略助你玩透普陀山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普陀山」三日深度游——海滨。普陀佛茶清香回甘。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 舟山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往舟山，抵达后办理入住、熟悉周边环境。","addr":"舟山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"普济寺","description":"下午首站普济寺，调整状态进入旅行节奏，普陀山主刹，香花券5元。","addr":"舟山市普陀区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游舟山一带氛围拉满，晚餐海鲜面人均38元。","addr":"沈家门渔港","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"南海观音","description":"全天主景点南海观音，33米观音立像，海天佛国。","addr":"普陀山南端","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐普陀佛茶（人均30元），早点休息。","addr":"普济寺旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"百步沙","description":"收官百步沙，看日出踩沙滩。","addr":"普陀山","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐素斋后集合返程，三日旅程圆满。","addr":"普济寺边","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"普济寺","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"普济寺是普陀山最有代表性的看点，普陀山主刹，香花券5元。攻略把它排进主线，时间留得最足。","notice":"普陀山主刹，香花券5元。这个点位上午光线最好。","durationMinutes":120,"addr":"舟山市普陀区"},{"spotId":"S2","name":"南海观音","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"南海观音是普陀山最有代表性的看点，33米观音立像，海天佛国。攻略把它排进主线，时间留得最足。","notice":"33米观音立像，海天佛国。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"普陀山南端"},{"spotId":"S3","name":"百步沙","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"百步沙是普陀山最有代表性的看点，看日出踩沙滩。攻略把它排进主线，时间留得最足。","notice":"看日出踩沙滩。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"普陀山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜面（人均38元）","description":"舟山 · 普陀山的招牌是海鲜面，沈家门夜排档本地人都认这家，点单照攻略不踩雷。","addr":"沈家门渔港"},{"title":"普陀佛茶（人均30元）","description":"舟山 · 普陀山的招牌是普陀佛茶，茶室体验本地人都认这家，点单照攻略不踩雷。","addr":"普济寺旁"},{"title":"素斋（人均28元）","description":"舟山 · 普陀山的招牌是素斋，三圣堂素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"普济寺边"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","换洗衣物与外套（早晚温差）","墨镜与拍照道具","保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 舟山，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('太湖鼋头渚纯攻略·深度指南3','guide','无锡 · 太湖鼋头渚','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,2,'鼋头渚 / 灵山大佛 / 南长街 —— 纯攻略助你玩透太湖鼋头渚精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「太湖鼋头渚」两日慢旅行——水景。惠山泥人阿福最喜庆。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 无锡"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴无锡","description":"集合出发，大巴直达太湖鼋头渚，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"鼋头渚","description":"抵达后首游鼋头渚，太湖第一名胜，樱花季封神。","addr":"无锡市滨湖区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐无锡小笼（人均22元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"灵山大佛","description":"早起人少，灵山大佛精华时段，88米大佛，梵宫震撼。","addr":"滨湖区马山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酱排骨，人均48元，补充体力。","addr":"中山路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南长街","description":"午后游览南长街，古运河夜色，清名桥倒影。","addr":"梁溪区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"鼋头渚","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"鼋头渚是太湖鼋头渚最有代表性的看点，太湖第一名胜，樱花季封神。攻略把它排进主线，时间留得最足。","notice":"太湖第一名胜，樱花季封神。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"无锡市滨湖区"},{"spotId":"S2","name":"灵山大佛","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"灵山大佛是太湖鼋头渚最有代表性的看点，88米大佛，梵宫震撼。攻略把它排进主线，时间留得最足。","notice":"88米大佛，梵宫震撼。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"滨湖区马山"},{"spotId":"S3","name":"南长街","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"南长街是太湖鼋头渚最有代表性的看点，古运河夜色，清名桥倒影。攻略把它排进主线，时间留得最足。","notice":"古运河夜色，清名桥倒影。这个点位上午光线最好。","durationMinutes":120,"addr":"梁溪区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"无锡小笼（人均22元）","description":"无锡 · 太湖鼋头渚的招牌是无锡小笼，熙盛源本地人都认这家，点单照攻略不踩雷。","addr":"南禅寺"},{"title":"酱排骨（人均48元）","description":"无锡 · 太湖鼋头渚的招牌是酱排骨，三凤桥本地人都认这家，点单照攻略不踩雷。","addr":"中山路"},{"title":"太湖三白（人均98元）","description":"无锡 · 太湖鼋头渚的招牌是太湖三白，渔人码头本地人都认这家，点单照攻略不踩雷。","addr":"鼋头渚旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","少量零食补给","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 无锡 的交通方便吗？","推荐先到 无锡，再打车或景区直通车前往核心景区；自驾导航直接搜太湖鼋头渚即可。"],["当地有什么必吃？","到了 无锡，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九宫山隐水洞纯攻略·周末版3','guide','咸宁 · 九宫山隐水洞','mountain','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1200,600,2,'九宫山 / 隐水洞 / 刘家桥古民居 —— 纯攻略助你玩透九宫山隐水洞精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九宫山隐水洞」三日深度游——山岳。咸宁桂花蜜香甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 咸宁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往咸宁，抵达后办理入住、熟悉周边环境。","addr":"咸宁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"九宫山","description":"下午首站九宫山，调整状态进入旅行节奏，云中湖避暑胜地，闯王陵。","addr":"咸宁市通山县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游咸宁一带氛围拉满，晚餐贺胜桥鸡汤人均58元。","addr":"咸安区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"隐水洞","description":"全天主景点隐水洞，水路旱路双游线溶洞。","addr":"通山县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐桂花糕（人均15元），早点休息。","addr":"温泉城区","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"刘家桥古民居","description":"收官刘家桥古民居，明清廊桥古民居。","addr":"咸安区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐通山合菜面后集合返程，三日旅程圆满。","addr":"通山县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"九宫山","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"九宫山是九宫山隐水洞最有代表性的看点，云中湖避暑胜地，闯王陵。攻略把它排进主线，时间留得最足。","notice":"云中湖避暑胜地，闯王陵。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"咸宁市通山县"},{"spotId":"S2","name":"隐水洞","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"隐水洞是九宫山隐水洞最有代表性的看点，水路旱路双游线溶洞。攻略把它排进主线，时间留得最足。","notice":"水路旱路双游线溶洞。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"通山县"},{"spotId":"S3","name":"刘家桥古民居","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"刘家桥古民居是九宫山隐水洞最有代表性的看点，明清廊桥古民居。攻略把它排进主线，时间留得最足。","notice":"明清廊桥古民居。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"咸安区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"贺胜桥鸡汤（人均58元）","description":"咸宁 · 九宫山隐水洞的招牌是贺胜桥鸡汤，贺胜桥土鸡馆本地人都认这家，点单照攻略不踩雷。","addr":"咸安区"},{"title":"桂花糕（人均15元）","description":"咸宁 · 九宫山隐水洞的招牌是桂花糕，桂花之乡本地人都认这家，点单照攻略不踩雷。","addr":"温泉城区"},{"title":"通山合菜面（人均28元）","description":"咸宁 · 九宫山隐水洞的招牌是通山合菜面，通山农家本地人都认这家，点单照攻略不踩雷。","addr":"通山县"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","墨镜与拍照道具","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 咸宁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('壶口瀑布纯攻略·亲子篇3','guide','延安 · 壶口瀑布','red','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',2500,1300,7,'壶口瀑布 / 宝塔山 / 枣园革命旧址 —— 纯攻略助你玩透壶口瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「壶口瀑布」两日慢旅行——人文。延安小米熬粥最养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 延安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延安","description":"集合出发，大巴直达壶口瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"壶口瀑布","description":"抵达后首游壶口瀑布，黄河之水天上来，旱地行船遗址。","addr":"延安市宜川县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐油馍馍（人均10元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"宝塔山","description":"早起人少，宝塔山精华时段，延安地标灯光秀。","addr":"延安市宝塔区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐羊杂碎，人均25元，补充体力。","addr":"宝塔区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"枣园革命旧址","description":"午后游览枣园革命旧址，窑洞与历史课堂。","addr":"宝塔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"壶口瀑布","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"壶口瀑布是壶口瀑布最有代表性的看点，黄河之水天上来，旱地行船遗址。攻略把它排进主线，时间留得最足。","notice":"黄河之水天上来，旱地行船遗址。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"延安市宜川县"},{"spotId":"S2","name":"宝塔山","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"宝塔山是壶口瀑布最有代表性的看点，延安地标灯光秀。攻略把它排进主线，时间留得最足。","notice":"延安地标灯光秀。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"延安市宝塔区"},{"spotId":"S3","name":"枣园革命旧址","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"枣园革命旧址是壶口瀑布最有代表性的看点，窑洞与历史课堂。攻略把它排进主线，时间留得最足。","notice":"窑洞与历史课堂。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"宝塔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"油馍馍（人均10元）","description":"延安 · 壶口瀑布的招牌是油馍馍，延安小吃本地人都认这家，点单照攻略不踩雷。","addr":"枣园路口"},{"title":"羊杂碎（人均25元）","description":"延安 · 壶口瀑布的招牌是羊杂碎，陕北羊汤馆本地人都认这家，点单照攻略不踩雷。","addr":"宝塔区"},{"title":"洋芋擦擦（人均18元）","description":"延安 · 壶口瀑布的招牌是洋芋擦擦，陕北农家本地人都认这家，点单照攻略不踩雷。","addr":"宜川县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","相机或运动相机","轻便雨衣或折叠伞","少量零食补给","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待"],"faqs":[["当地有什么必吃？","到了 延安，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 延安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('避暑山庄纯攻略·摄影机位3','guide','承德 · 避暑山庄','village','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,1,'避暑山庄 / 普宁寺 / 磬锤峰 —— 纯攻略助你玩透避暑山庄精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「避暑山庄」三日深度游——古村落。承德木雕核桃吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 承德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往承德，抵达后办理入住、熟悉周边环境。","addr":"承德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"避暑山庄","description":"下午首站避暑山庄，调整状态进入旅行节奏，皇家园林之最，山区乘车看小布达拉。","addr":"承德市双桥区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游承德一带氛围拉满，晚餐御土荷叶鸡人均38元。","addr":"承德市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"普宁寺","description":"全天主景点普宁寺，大佛寺千手千眼观音。","addr":"承德市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐荞面饸饹（人均18元），早点休息。","addr":"山庄东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"磬锤峰","description":"收官磬锤峰，棒槌山奇观，索道往返。","addr":"承德市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏仁茶后集合返程，三日旅程圆满。","addr":"二仙居","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"避暑山庄","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"避暑山庄是避暑山庄最有代表性的看点，皇家园林之最，山区乘车看小布达拉。攻略把它排进主线，时间留得最足。","notice":"皇家园林之最，山区乘车看小布达拉。这个点位上午光线最好。","durationMinutes":240,"addr":"承德市双桥区"},{"spotId":"S2","name":"普宁寺","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"普宁寺是避暑山庄最有代表性的看点，大佛寺千手千眼观音。攻略把它排进主线，时间留得最足。","notice":"大佛寺千手千眼观音。这个点位上午光线最好。","durationMinutes":90,"addr":"承德市"},{"spotId":"S3","name":"磬锤峰","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"磬锤峰是避暑山庄最有代表性的看点，棒槌山奇观，索道往返。攻略把它排进主线，时间留得最足。","notice":"棒槌山奇观，索道往返。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"承德市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"御土荷叶鸡（人均38元）","description":"承德 · 避暑山庄的招牌是御土荷叶鸡，老三羊汤本地人都认这家，点单照攻略不踩雷。","addr":"承德市区"},{"title":"荞面饸饹（人均18元）","description":"承德 · 避暑山庄的招牌是荞面饸饹，莜面馆本地人都认这家，点单照攻略不踩雷。","addr":"山庄东路"},{"title":"杏仁茶（人均10元）","description":"承德 · 避暑山庄的招牌是杏仁茶，小吃街本地人都认这家，点单照攻略不踩雷。","addr":"二仙居"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","身份证件与手机充电宝","保温水杯与少量现金","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 承德 的交通方便吗？","推荐先到 承德，再打车或景区直通车前往核心景区；自驾导航直接搜避暑山庄即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('日月湾冲浪纯攻略·美食清单3','guide','万宁 · 日月湾冲浪','sea','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',990,500,6,'日月湾 / 石梅湾 / 兴隆热带植物园 —— 纯攻略助你玩透日月湾冲浪精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「日月湾冲浪」两日慢旅行——海滨。兴隆炭烧咖啡回香浓。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 万宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴万宁","description":"集合出发，大巴直达日月湾冲浪，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"日月湾","description":"抵达后首游日月湾，国家冲浪队训练地，新手教程2小时。","addr":"万宁市礼纪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐和乐蟹（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"石梅湾","description":"早起人少，石梅湾精华时段，加井岛浮潜，凤凰九里书屋。","addr":"万宁市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐东山羊，人均88元，补充体力。","addr":"万城镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"兴隆热带植物园","description":"午后游览兴隆热带植物园，咖啡可可巧克力之旅。","addr":"兴隆镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"日月湾","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"日月湾是日月湾冲浪最有代表性的看点，国家冲浪队训练地，新手教程2小时。攻略把它排进主线，时间留得最足。","notice":"国家冲浪队训练地，新手教程2小时。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"万宁市礼纪镇"},{"spotId":"S2","name":"石梅湾","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"石梅湾是日月湾冲浪最有代表性的看点，加井岛浮潜，凤凰九里书屋。攻略把它排进主线，时间留得最足。","notice":"加井岛浮潜，凤凰九里书屋。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"万宁市"},{"spotId":"S3","name":"兴隆热带植物园","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"兴隆热带植物园是日月湾冲浪最有代表性的看点，咖啡可可巧克力之旅。攻略把它排进主线，时间留得最足。","notice":"咖啡可可巧克力之旅。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"兴隆镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"和乐蟹（人均88元）","description":"万宁 · 日月湾冲浪的招牌是和乐蟹，渔家海鲜本地人都认这家，点单照攻略不踩雷。","addr":"东澳镇"},{"title":"东山羊（人均88元）","description":"万宁 · 日月湾冲浪的招牌是东山羊，东山羊庄本地人都认这家，点单照攻略不踩雷。","addr":"万城镇"},{"title":"兴隆咖啡（人均25元）","description":"万宁 · 日月湾冲浪的招牌是兴隆咖啡，咖啡庄园本地人都认这家，点单照攻略不踩雷。","addr":"兴隆镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","换洗衣物与外套（早晚温差）","墨镜与拍照道具","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 万宁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('喀纳斯纯攻略·自由行手册3','guide','阿勒泰 · 喀纳斯','water','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',2500,1300,2,'喀纳斯湖 / 禾木村 / 白哈巴 —— 纯攻略助你玩透喀纳斯精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「喀纳斯」三日深度游——水景。喀纳斯冷水鱼干风味独特。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 阿勒泰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往阿勒泰，抵达后办理入住、熟悉周边环境。","addr":"阿勒泰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"喀纳斯湖","description":"下午首站喀纳斯湖，调整状态进入旅行节奏，三湾晨雾与湖怪传说，观鱼台俯瞰。","addr":"布尔津县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游阿勒泰一带氛围拉满，晚餐烤全羊人均128元。","addr":"禾木村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"禾木村","description":"全天主景点禾木村，图瓦人村落，白桦林晨雾。","addr":"喀纳斯景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐手抓饭（人均35元），早点休息。","addr":"贾登峪","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"白哈巴","description":"收官白哈巴，中哈边境原始村落。","addr":"哈巴河县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐奶茶后集合返程，三日旅程圆满。","addr":"白哈巴","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"喀纳斯湖","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"喀纳斯湖是喀纳斯最有代表性的看点，三湾晨雾与湖怪传说，观鱼台俯瞰。攻略把它排进主线，时间留得最足。","notice":"三湾晨雾与湖怪传说，观鱼台俯瞰。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"布尔津县"},{"spotId":"S2","name":"禾木村","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"禾木村是喀纳斯最有代表性的看点，图瓦人村落，白桦林晨雾。攻略把它排进主线，时间留得最足。","notice":"图瓦人村落，白桦林晨雾。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"喀纳斯景区"},{"spotId":"S3","name":"白哈巴","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"白哈巴是喀纳斯最有代表性的看点，中哈边境原始村落。攻略把它排进主线，时间留得最足。","notice":"中哈边境原始村落。这个点位上午光线最好。","durationMinutes":120,"addr":"哈巴河县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤全羊（人均128元）","description":"阿勒泰 · 喀纳斯的招牌是烤全羊，图瓦人家本地人都认这家，点单照攻略不踩雷。","addr":"禾木村"},{"title":"手抓饭（人均35元）","description":"阿勒泰 · 喀纳斯的招牌是手抓饭，别克餐厅本地人都认这家，点单照攻略不踩雷。","addr":"贾登峪"},{"title":"奶茶（人均20元）","description":"阿勒泰 · 喀纳斯的招牌是奶茶，哈萨克毡房本地人都认这家，点单照攻略不踩雷。","addr":"白哈巴"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["墨镜与拍照道具","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["当地有什么必吃？","到了 阿勒泰，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 阿勒泰 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 阿勒泰 的交通方便吗？","推荐先到 阿勒泰，再打车或景区直通车前往核心景区；自驾导航直接搜喀纳斯即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
