INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武功山纯攻略·避坑版3','guide','萍乡 · 武功山','mountain','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,2,'金顶 / 发云界 / 玻璃栈道 —— 纯攻略助你玩透武功山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武功山」三日深度游——山岳。武功山泉水豆腐宴别错过。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往萍乡，抵达后办理入住、熟悉周边环境。","addr":"萍乡市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，日出云海核心位，山顶比山下冷10度。","addr":"武功山风景区金顶","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游萍乡一带氛围拉满，晚餐萍乡小炒肉人均42元。","addr":"武功山游客中心旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"发云界","description":"全天主景点发云界，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐艾米古（人均10元），早点休息。","addr":"金顶驿站","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"玻璃栈道","description":"收官玻璃栈道，栈道限流，旺季排30分钟。","addr":"武功山吊马桩","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐紫红米粉后集合返程，三日旅程圆满。","addr":"武功山镇主街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。这个点位上午光线最好。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","墨镜与拍照道具","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["当地有什么必吃？","到了 萍乡，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 萍乡 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 萍乡 的交通方便吗？","推荐先到 萍乡，再打车或景区直通车前往核心景区；自驾导航直接搜武功山即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('仙女湖纯攻略·深度指南3','guide','新余 · 仙女湖','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,2,'仙女湖主体湖区 / 圣集寺 / 龙王阁 —— 纯攻略助你玩透仙女湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「仙女湖」两日慢旅行——水景。新余蜜桔十月后最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 新余"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴新余","description":"集合出发，大巴直达仙女湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"仙女湖主体湖区","description":"抵达后首游仙女湖主体湖区，坐船跳岛游，爱情岛最热门。","addr":"新余市渝水区仙女湖大道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐仙女湖鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"圣集寺","description":"早起人少，圣集寺精华时段，湖畔禅意，人少清净。","addr":"仙女湖钤阳湖畔","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐新余蜜桔鸡，人均58元，补充体力。","addr":"景区出口农家乐","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙王阁","description":"午后游览龙王阁，登阁看千岛湖景。","addr":"仙女湖最高点","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"仙女湖主体湖区","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"仙女湖主体湖区是仙女湖最有代表性的看点，坐船跳岛游，爱情岛最热门。攻略把它排进主线，时间留得最足。","notice":"坐船跳岛游，爱情岛最热门。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"新余市渝水区仙女湖大道"},{"spotId":"S2","name":"圣集寺","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"圣集寺是仙女湖最有代表性的看点，湖畔禅意，人少清净。攻略把它排进主线，时间留得最足。","notice":"湖畔禅意，人少清净。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"仙女湖钤阳湖畔"},{"spotId":"S3","name":"龙王阁","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"龙王阁是仙女湖最有代表性的看点，登阁看千岛湖景。攻略把它排进主线，时间留得最足。","notice":"登阁看千岛湖景。这个点位上午光线最好。","durationMinutes":60,"addr":"仙女湖最高点"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"仙女湖鱼头（人均78元）","description":"新余 · 仙女湖的招牌是仙女湖鱼头，湖畔渔村本地人都认这家，点单照攻略不踩雷。","addr":"仙女湖码头渔家街"},{"title":"新余蜜桔鸡（人均58元）","description":"新余 · 仙女湖的招牌是新余蜜桔鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口农家乐"},{"title":"水北豆腐（人均25元）","description":"新余 · 仙女湖的招牌是水北豆腐，老豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"新余城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["墨镜与拍照道具","相机或运动相机","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 新余 的交通方便吗？","推荐先到 新余，再打车或景区直通车前往核心景区；自驾导航直接搜仙女湖即可。"],["当地有什么必吃？","到了 新余，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
