INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('洪崖洞夜景纯攻略·摄影机位3','guide','渝中 · 洪崖洞夜景','food','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1990,1000,3,'洪崖洞 / 长江索道 / 山城步道 —— 纯攻略助你玩透洪崖洞夜景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「洪崖洞夜景」三日深度游——美食。重庆火锅底料真空包装。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 渝中"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往渝中，抵达后办理入住、熟悉周边环境。","addr":"渝中市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"洪崖洞","description":"下午首站洪崖洞，调整状态进入旅行节奏，千与千寻同款夜景，对岸拍全景。","addr":"渝中区嘉陵江畔","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游渝中一带氛围拉满，晚餐重庆火锅人均98元。","addr":"解放碑","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长江索道","description":"全天主景点长江索道，空中横渡长江，排队1小时。","addr":"渝中区新华路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐重庆小面（人均15元），早点休息。","addr":"民生路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"山城步道","description":"收官山城步道，第三步道悬空栈道看老重庆。","addr":"渝中区中兴路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸辣粉后集合返程，三日旅程圆满。","addr":"八一路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"洪崖洞","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"洪崖洞是洪崖洞夜景最有代表性的看点，千与千寻同款夜景，对岸拍全景。攻略把它排进主线，时间留得最足。","notice":"千与千寻同款夜景，对岸拍全景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"渝中区嘉陵江畔"},{"spotId":"S2","name":"长江索道","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"长江索道是洪崖洞夜景最有代表性的看点，空中横渡长江，排队1小时。攻略把它排进主线，时间留得最足。","notice":"空中横渡长江，排队1小时。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"渝中区新华路"},{"spotId":"S3","name":"山城步道","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"山城步道是洪崖洞夜景最有代表性的看点，第三步道悬空栈道看老重庆。攻略把它排进主线，时间留得最足。","notice":"第三步道悬空栈道看老重庆。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"渝中区中兴路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"重庆火锅（人均98元）","description":"渝中 · 洪崖洞夜景的招牌是重庆火锅，佩姐老火锅本地人都认这家，点单照攻略不踩雷。","addr":"解放碑"},{"title":"重庆小面（人均15元）","description":"渝中 · 洪崖洞夜景的招牌是重庆小面，花市豌杂面本地人都认这家，点单照攻略不踩雷。","addr":"民生路"},{"title":"酸辣粉（人均12元）","description":"渝中 · 洪崖洞夜景的招牌是酸辣粉，好又来酸辣粉本地人都认这家，点单照攻略不踩雷。","addr":"八一路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","身份证件与手机充电宝","保温水杯与少量现金","相机或运动相机","防晒霜与遮阳帽","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 渝中 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('赛里木湖纯攻略·美食清单3','guide','伊犁 · 赛里木湖','water','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1990,1000,2,'赛里木湖 / 果子沟大桥 / 霍尔果斯口岸 —— 纯攻略助你玩透赛里木湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「赛里木湖」两日慢旅行——水景。伊犁薰衣草精油真香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 伊犁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴伊犁","description":"集合出发，大巴直达赛里木湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"赛里木湖","description":"抵达后首游赛里木湖，大西洋最后一滴眼泪，环湖骑行。","addr":"博乐市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐高白鲑（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"果子沟大桥","description":"早起人少，果子沟大桥精华时段，空中巨龙，观景台打卡。","addr":"霍城县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤包子，人均10元，补充体力。","addr":"果子沟","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"霍尔果斯口岸","description":"午后游览霍尔果斯口岸，中哈边境免税购物。","addr":"霍尔果斯市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"赛里木湖","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"赛里木湖是赛里木湖最有代表性的看点，大西洋最后一滴眼泪，环湖骑行。攻略把它排进主线，时间留得最足。","notice":"大西洋最后一滴眼泪，环湖骑行。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"博乐市"},{"spotId":"S2","name":"果子沟大桥","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"果子沟大桥是赛里木湖最有代表性的看点，空中巨龙，观景台打卡。攻略把它排进主线，时间留得最足。","notice":"空中巨龙，观景台打卡。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"霍城县"},{"spotId":"S3","name":"霍尔果斯口岸","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"霍尔果斯口岸是赛里木湖最有代表性的看点，中哈边境免税购物。攻略把它排进主线，时间留得最足。","notice":"中哈边境免税购物。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"霍尔果斯市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"高白鲑（人均88元）","description":"伊犁 · 赛里木湖的招牌是高白鲑，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"赛里木湖"},{"title":"烤包子（人均10元）","description":"伊犁 · 赛里木湖的招牌是烤包子，维族馕坑本地人都认这家，点单照攻略不踩雷。","addr":"果子沟"},{"title":"马奶酒（人均25元）","description":"伊犁 · 赛里木湖的招牌是马奶酒，牧民家本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","相机或运动相机","少量零食补给","换洗衣物与外套（早晚温差）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["几月份去 伊犁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('长白山纯攻略·自由行手册3','guide','延边 · 长白山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1990,1000,2,'天池北坡 / 长白瀑布 / 绿渊潭 —— 纯攻略助你玩透长白山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「长白山」三日深度游——山岳。长白山林下参滋补。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"吉林 · 延边"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往延边，抵达后办理入住、熟悉周边环境。","addr":"延边市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"天池北坡","description":"下午首站天池北坡，调整状态进入旅行节奏，长白山主峰天池，天气好才能见。","addr":"延边州安图县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游延边一带氛围拉满，晚餐朝鲜冷面人均22元。","addr":"二道白河镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长白瀑布","description":"全天主景点长白瀑布，68米瀑布与温泉煮蛋。","addr":"北坡景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐石锅拌饭（人均28元），早点休息。","addr":"延吉市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"绿渊潭","description":"收官绿渊潭，碧绿水潭与飞瀑。","addr":"北坡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐温泉煮蛋后集合返程，三日旅程圆满。","addr":"北坡","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"天池北坡","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"天池北坡是长白山最有代表性的看点，长白山主峰天池，天气好才能见。攻略把它排进主线，时间留得最足。","notice":"长白山主峰天池，天气好才能见。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"延边州安图县"},{"spotId":"S2","name":"长白瀑布","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"长白瀑布是长白山最有代表性的看点，68米瀑布与温泉煮蛋。攻略把它排进主线，时间留得最足。","notice":"68米瀑布与温泉煮蛋。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"北坡景区"},{"spotId":"S3","name":"绿渊潭","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"绿渊潭是长白山最有代表性的看点，碧绿水潭与飞瀑。攻略把它排进主线，时间留得最足。","notice":"碧绿水潭与飞瀑。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"北坡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"朝鲜冷面（人均22元）","description":"延边 · 长白山的招牌是朝鲜冷面，服务大楼冷面本地人都认这家，点单照攻略不踩雷。","addr":"二道白河镇"},{"title":"石锅拌饭（人均28元）","description":"延边 · 长白山的招牌是石锅拌饭，金达莱餐厅本地人都认这家，点单照攻略不踩雷。","addr":"延吉市"},{"title":"温泉煮蛋（人均10元）","description":"延边 · 长白山的招牌是温泉煮蛋，瀑布温泉口本地人都认这家，点单照攻略不踩雷。","addr":"北坡"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","墨镜与拍照道具","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","保温水杯与少量现金","相机或运动相机","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 延边，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('井冈山纯攻略·省钱玩法4','guide','吉安 · 井冈山','red','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',1990,1000,7,'黄洋界 / 茨坪革命旧址群 / 龙潭 —— 纯攻略助你玩透井冈山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「井冈山」两日慢旅行——人文。井冈山竹制工艺品轻便好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 吉安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴吉安","description":"集合出发，大巴直达井冈山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄洋界","description":"抵达后首游黄洋界，保卫战旧址，云海出现率高。","addr":"井冈山市黄洋界景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红米饭南瓜汤（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"茨坪革命旧址群","description":"早起人少，茨坪革命旧址群精华时段，旧址集中，步行串游。","addr":"井冈山市茨坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐井冈烟笋，人均38元，补充体力。","addr":"黄洋界山下餐馆","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙潭","description":"午后游览龙潭，五潭十八瀑，索道省力。","addr":"井冈山龙潭景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄洋界","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"黄洋界是井冈山最有代表性的看点，保卫战旧址，云海出现率高。攻略把它排进主线，时间留得最足。","notice":"保卫战旧址，云海出现率高。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"井冈山市黄洋界景区"},{"spotId":"S2","name":"茨坪革命旧址群","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"茨坪革命旧址群是井冈山最有代表性的看点，旧址集中，步行串游。攻略把它排进主线，时间留得最足。","notice":"旧址集中，步行串游。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"井冈山市茨坪镇"},{"spotId":"S3","name":"龙潭","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"龙潭是井冈山最有代表性的看点，五潭十八瀑，索道省力。攻略把它排进主线，时间留得最足。","notice":"五潭十八瀑，索道省力。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"井冈山龙潭景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红米饭南瓜汤（人均45元）","description":"吉安 · 井冈山的招牌是红米饭南瓜汤，老乡家常菜本地人都认这家，点单照攻略不踩雷。","addr":"茨坪天街"},{"title":"井冈烟笋（人均38元）","description":"吉安 · 井冈山的招牌是井冈烟笋，山上饭庄本地人都认这家，点单照攻略不踩雷。","addr":"黄洋界山下餐馆"},{"title":"石鸡炖汤（人均88元）","description":"吉安 · 井冈山的招牌是石鸡炖汤，龙潭农庄本地人都认这家，点单照攻略不踩雷。","addr":"龙潭景区入口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","少量零食补给","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 吉安 的交通方便吗？","推荐先到 吉安，再打车或景区直通车前往核心景区；自驾导航直接搜井冈山即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大觉山纯攻略·避坑版4','guide','抚州 · 大觉山','adventure','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',990,500,9,'大觉山漂流 / 大觉岩寺 / 古镇影视城 —— 纯攻略助你玩透大觉山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大觉山」三日深度游——探险地。资溪面包是当地人的骄傲。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 抚州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往抚州，抵达后办理入住、熟悉周边环境。","addr":"抚州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大觉山漂流","description":"下午首站大觉山漂流，调整状态进入旅行节奏，华东第一漂，全程3.5公里带好换洗衣。","addr":"资溪县大觉山景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游抚州一带氛围拉满，晚餐资溪面包人均15元。","addr":"资溪县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大觉岩寺","description":"全天主景点大觉岩寺，悬崖上的古寺，索道直达。","addr":"大觉山主峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐笋干烧肉（人均48元），早点休息。","addr":"大觉山游客中心","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古镇影视城","description":"收官古镇影视城，仿宋古镇，拍照出片。","addr":"大觉山脚下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐发酵豆腐后集合返程，三日旅程圆满。","addr":"影视城内街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大觉山漂流","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"大觉山漂流是大觉山最有代表性的看点，华东第一漂，全程3.5公里带好换洗衣。攻略把它排进主线，时间留得最足。","notice":"华东第一漂，全程3.5公里带好换洗衣。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"资溪县大觉山景区"},{"spotId":"S2","name":"大觉岩寺","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"大觉岩寺是大觉山最有代表性的看点，悬崖上的古寺，索道直达。攻略把它排进主线，时间留得最足。","notice":"悬崖上的古寺，索道直达。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"大觉山主峰"},{"spotId":"S3","name":"古镇影视城","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"古镇影视城是大觉山最有代表性的看点，仿宋古镇，拍照出片。攻略把它排进主线，时间留得最足。","notice":"仿宋古镇，拍照出片。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"大觉山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"资溪面包（人均15元）","description":"抚州 · 大觉山的招牌是资溪面包，面包之乡旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"资溪县城"},{"title":"笋干烧肉（人均48元）","description":"抚州 · 大觉山的招牌是笋干烧肉，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"大觉山游客中心"},{"title":"发酵豆腐（人均18元）","description":"抚州 · 大觉山的招牌是发酵豆腐，古镇豆坊本地人都认这家，点单照攻略不踩雷。","addr":"影视城内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","相机或运动相机","少量零食补给","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳阳楼洞庭湖纯攻略·深度指南4','guide','岳阳 · 岳阳楼洞庭湖','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1990,1000,2,'岳阳楼 / 君山岛 / 圣安寺 —— 纯攻略助你玩透岳阳楼洞庭湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「岳阳楼洞庭湖」两日慢旅行——水景。君山银针是十大名茶之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 岳阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴岳阳","description":"集合出发，大巴直达岳阳楼洞庭湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"岳阳楼","description":"抵达后首游岳阳楼，洞庭天下水岳阳天下楼，背岳阳楼记免票。","addr":"岳阳市岳阳楼区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐洞庭鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"君山岛","description":"早起人少，君山岛精华时段，湘妃竹与银针茶的故乡。","addr":"洞庭湖君山岛","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐君山银针鸡片，人均68元，补充体力。","addr":"君山岛上","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"圣安寺","description":"午后游览圣安寺，古塔与湖景同框。","addr":"岳阳市南湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"岳阳楼","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"岳阳楼是岳阳楼洞庭湖最有代表性的看点，洞庭天下水岳阳天下楼，背岳阳楼记免票。攻略把它排进主线，时间留得最足。","notice":"洞庭天下水岳阳天下楼，背岳阳楼记免票。这个点位上午光线最好。","durationMinutes":90,"addr":"岳阳市岳阳楼区"},{"spotId":"S2","name":"君山岛","coverUrl":"https://images.unsplash.com/photo