INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武隆天坑纯攻略·亲子篇4','guide','武隆 · 武隆天坑','adventure','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',990,500,9,'天生三桥 / 仙女山 / 龙水峡地缝 —— 纯攻略助你玩透武隆天坑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武隆天坑」两日慢旅行——探险地。武隆羊角豆干麻辣够味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 武隆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴武隆","description":"集合出发，大巴直达武隆天坑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"天生三桥","description":"抵达后首游天生三桥，变形金刚取景地，天福官驿。","addr":"武隆区仙女山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐碗碗羊肉（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"仙女山","description":"早起人少，仙女山精华时段，南国第一牧原，草原骑马。","addr":"武隆区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐江口鱼，人均58元，补充体力。","addr":"江口镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙水峡地缝","description":"午后游览龙水峡地缝，80米深地缝一线天光。","addr":"仙女山镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"天生三桥","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"天生三桥是武隆天坑最有代表性的看点，变形金刚取景地，天福官驿。攻略把它排进主线，时间留得最足。","notice":"变形金刚取景地，天福官驿。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"武隆区仙女山镇"},{"spotId":"S2","name":"仙女山","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"仙女山是武隆天坑最有代表性的看点，南国第一牧原，草原骑马。攻略把它排进主线，时间留得最足。","notice":"南国第一牧原，草原骑马。这个点位上午光线最好。","durationMinutes":180,"addr":"武隆区"},{"spotId":"S3","name":"龙水峡地缝","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"龙水峡地缝是武隆天坑最有代表性的看点，80米深地缝一线天光。攻略把它排进主线，时间留得最足。","notice":"80米深地缝一线天光。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"仙女山镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"碗碗羊肉（人均38元）","description":"武隆 · 武隆天坑的招牌是碗碗羊肉，武隆碗碗羊肉本地人都认这家，点单照攻略不踩雷。","addr":"仙女山镇"},{"title":"江口鱼（人均58元）","description":"武隆 · 武隆天坑的招牌是江口鱼，乌江鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"江口镇"},{"title":"羊角豆干（人均15元）","description":"武隆 · 武隆天坑的招牌是羊角豆干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"武隆城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）","少量零食补给","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","保温水杯与少量现金"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 武隆 的交通方便吗？","推荐先到 武隆，再打车或景区直通车前往核心景区；自驾导航直接搜武隆天坑即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('天山天池纯攻略·摄影机位4','guide','昌吉 · 天山天池','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,2,'天山天池 / 马牙山 / 西小天池 —— 纯攻略助你玩透天山天池精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「天山天池」三日深度游——山岳。天山雪莲泡酒有讲究。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 昌吉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往昌吉，抵达后办理入住、熟悉周边环境。","addr":"昌吉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"天山天池","description":"下午首站天山天池，调整状态进入旅行节奏，博格达峰雪影与瑶池传说。","addr":"阜康市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游昌吉一带氛围拉满，晚餐新疆大盘鸡人均68元。","addr":"阜康市","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"马牙山","description":"全天主景点马牙山，石林与云海，索道直达。","addr":"天池西侧","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐馕坑肉（人均25元），早点休息。","addr":"天池镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"西小天池","description":"收官西小天池，飞龙潭瀑布。","addr":"天池盘山路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸奶粽子后集合返程，三日旅程圆满。","addr":"阜康夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"天山天池","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"天山天池是天山天池最有代表性的看点，博格达峰雪影与瑶池传说。攻略把它排进主线，时间留得最足。","notice":"博格达峰雪影与瑶池传说。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"阜康市"},{"spotId":"S2","name":"马牙山","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"马牙山是天山天池最有代表性的看点，石林与云海，索道直达。攻略把它排进主线，时间留得最足。","notice":"石林与云海，索道直达。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"天池西侧"},{"spotId":"S3","name":"西小天池","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"西小天池是天山天池最有代表性的看点，飞龙潭瀑布。攻略把它排进主线，时间留得最足。","notice":"飞龙潭瀑布。这个点位上午光线最好。","durationMinutes":60,"addr":"天池盘山路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新疆大盘鸡（人均68元）","description":"昌吉 · 天山天池的招牌是新疆大盘鸡，血站大盘鸡本地人都认这家，点单照攻略不踩雷。","addr":"阜康市"},{"title":"馕坑肉（人均25元）","description":"昌吉 · 天山天池的招牌是馕坑肉，馕王本地人都认这家，点单照攻略不踩雷。","addr":"天池镇"},{"title":"酸奶粽子（人均12元）","description":"昌吉 · 天山天池的招牌是酸奶粽子，夜市甜品本地人都认这家，点单照攻略不踩雷。","addr":"阜康夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","少量零食补给","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","墨镜与拍照道具","相机或运动相机","身份证件与手机充电宝","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 昌吉 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('八达岭长城纯攻略·美食清单4','guide','延庆 · 八达岭长城','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1200,600,7,'八达岭长城 / 明十三陵 / 居庸关花海 —— 纯攻略助你玩透八达岭长城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「八达岭长城」两日慢旅行——人文。北京果脯礼盒送长辈。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"北京 · 延庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延庆","description":"集合出发，大巴直达八达岭长城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"八达岭长城","description":"抵达后首游八达岭长城，好汉坡北八楼，缆车上下。","addr":"延庆区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐春饼宴（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"明十三陵","description":"早起人少，明十三陵精华时段，定陵地宫探秘。","addr":"昌平区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐火盆锅豆腐宴，人均48元，补充体力。","addr":"八达岭镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"居庸关花海","description":"午后游览居庸关花海，开往春天的列车。","addr":"昌平区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"八达岭长城","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"八达岭长城是八达岭长城最有代表性的看点，好汉坡北八楼，缆车上下。攻略把它排进主线，时间留得最足。","notice":"好汉坡北八楼，缆车上下。这个点位上午光线最好。","durationMinutes":240,"addr":"延庆区"},{"spotId":"S2","name":"明十三陵","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"明十三陵是八达岭长城最有代表性的看点，定陵地宫探秘。攻略把它排进主线，时间留得最足。","notice":"定陵地宫探秘。这个点位上午光线最好。","durationMinutes":120,"addr":"昌平区"},{"spotId":"S3","name":"居庸关花海","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"居庸关花海是八达岭长城最有代表性的看点，开往春天的列车。攻略把它排进主线，时间留得最足。","notice":"开往春天的列车。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"昌平区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"春饼宴（人均38元）","description":"延庆 · 八达岭长城的招牌是春饼宴，柳沟村豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"延庆柳沟"},{"title":"火盆锅豆腐宴（人均48元）","description":"延庆 · 八达岭长城的招牌是火盆锅豆腐宴，农家院本地人都认这家，点单照攻略不踩雷。","addr":"八达岭镇"},{"title":"玫瑰饼（人均15元）","description":"延庆 · 八达岭长城的招牌是玫瑰饼，妙峰山糕点本地人都认这家，点单照攻略不踩雷。","addr":"昌平"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 延庆 的交通方便吗？","推荐先到 延庆，再打车或景区直通车前往核心景区；自驾导航直接搜八达岭长城即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('庐山纯攻略·自由行手册4','guide','九江 · 庐山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',2500,1300,2,'锦绣谷 / 三叠泉 / 如琴湖花径 —— 纯攻略助你玩透庐山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「庐山」三日深度游——山岳。庐山云雾茶记得认准原产地标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 九江"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往九江，抵达后办理入住、熟悉周边环境。","addr":"九江市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"锦绣谷","description":"下午首站锦绣谷，调整状态进入旅行节奏，云雾多发地段，下午常被云海包裹。","addr":"庐山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游九江一带氛围拉满，晚餐庐山三石宴人均128元。","addr":"牯岭镇河西路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"三叠泉","description":"全天主景点三叠泉，不到三叠泉不算庐山客，往返台阶多。","addr":"庐山东南麓","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐茶饼（人均12元），早点休息。","addr":"牯岭镇正街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"如琴湖花径","description":"收官如琴湖花径，清晨人少出片，环湖半小时。","addr":"牯岭镇西侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐石耳炖鸡汤后集合返程，三日旅程圆满。","addr":"如琴湖旁农家","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"锦绣谷","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"锦绣谷是庐山最有代表性的看点，云雾多发地段，下午常被云海包裹。攻略把它排进主线，时间留得最足。","notice":"云雾多发地段，下午常被云海包裹。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"庐山风景区"},{"spotId":"S2","name":"三叠泉","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"三叠泉是庐山最有代表性的看点，不到三叠泉不算庐山客，往返台阶多。攻略把它排进主线，时间留得最足。","notice":"不到三叠泉不算庐山客，往返台阶多。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"庐山东南麓"},{"spotId":"S3","name":"如琴湖花径","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"如琴湖花径是庐山最有代表性的看点，清晨人少出片，环湖半小时。攻略把它排进主线，时间留得最足。","notice":"清晨人少出片，环湖半小时。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"牯岭镇西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"庐山三石宴（人均128元）","description":"九江 · 庐山的招牌是庐山三石宴，牯岭镇饭馆本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇河西路"},{"title":"茶饼（人均12元）","description":"九江 · 庐山的招牌是茶饼，云中街区小店本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇正街"},{"title":"石耳炖鸡汤（人均98元）","description":"九江 · 庐山的招牌是石耳炖鸡汤，山中食府本地人都认这家，点单照攻略不踩雷。","addr":"如琴湖旁农家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","墨镜与拍照道具","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","相机或运动相机","轻便雨衣或折叠伞","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 九江 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 九江，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('通天岩郁孤台纯攻略·省钱玩法4','guide','赣州 · 通天岩郁孤台','red','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,7,'通天岩 / 郁孤台 / 关西新围 —— 纯攻略助你玩透通天岩郁孤台精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「通天岩郁孤台」两日慢旅行——人文。赣南脐橙11月最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 赣州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴赣州","description":"集合出发，大巴直达通天岩郁孤台，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"通天岩","description":"抵达后首游通天岩，江南最大石窟群，丹岩丹霞。","addr":"赣州市章贡区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐赣南小炒鱼（人均42元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"郁孤台","description":"早起人少，郁孤台精华时段，辛弃疾词中圣地，宋城墙。","addr":"章贡区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐艾米果，人均10元，补充体力。","addr":"郁孤台街区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"关西新围","description":"午后游览关西新围，东方古堡围屋。","addr":"龙南市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"通天岩","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"通天岩是通天岩郁孤台最有代表性的看点，江南最大石窟群，丹岩丹霞。攻略把它排进主线，时间留得最足。","notice":"江南最大石窟群，丹岩丹霞。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"赣州市章贡区"},{"spotId":"S2","name":"郁孤台","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"郁孤台是通天岩郁孤台最有代表性的看点，辛弃疾词中圣地，宋城墙。攻略把它排进主线，时间留得最足。","notice":"辛弃疾词中圣地，宋城墙。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"章贡区"},{"spotId":"S3","name":"关西新围","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"关西新围是通天岩郁孤台最有代表性的看点，东方古堡围屋。攻略把它排进主线，时间留得最足。","notice":"东方古堡围屋。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"龙南市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"赣南小炒鱼（人均42元）","description":"赣州 · 通天岩郁孤台的招牌是赣南小炒鱼，赣州客家菜本地人都认这家，点单照攻略不踩雷。","addr":"章贡区"},{"title":"艾米果（人均10元）","description":"赣州 · 通天岩郁孤台的招牌是艾米果，街头点心本地人都认这家，点单照攻略不踩雷。","addr":"郁孤台街区"},{"title":"黄元米果（人均18元）","description":"赣州 · 通天岩郁孤台的招牌是黄元米果，赣南农家本地人都认这家，点单照攻略不踩雷。","addr":"龙南市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","身份证件与手机充电宝","墨镜与拍照道具","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('桃花源纯攻略·避坑版4','guide','常德 · 桃花源','village','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',2990,1600,1,'桃花源古镇 / 桃源山 / 五柳湖 —— 纯攻略助你玩透桃花源精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「桃花源」三日深度游——古村落。桃源大叶茶配擂茶绝了。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 常德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往常德，抵达后办理入住、熟悉周边环境。","addr":"常德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"桃花源古镇","description":"下午首站桃花源古镇，调整状态进入旅行节奏，秦溪秦谷还原桃花源记场景。","addr":"常德市桃源县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游常德一带氛围拉满，晚餐常德米粉人均18元。","addr":"桃源县漳江镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"桃源山","description":"全天主景点桃源山，水府阁俯瞰沅江。","addr":"桃花源景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐擂茶（人均35元），早点休息。","addr":"桃花源古镇内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"五柳湖","description":"收官五柳湖，落英缤纷打卡点。","addr":"桃花源核心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桃源鸡后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"桃花源古镇","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"桃花源古镇是桃花源最有代表性的看点，秦溪秦谷还原桃花源记场景。攻略把它排进主线，时间留得最足。","notice":"秦溪秦谷还原桃花源记场景。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"常德市桃源县"},{"spotId":"S2","name":"桃源山","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"桃源山是桃花源最有代表性的看点，水府阁俯瞰沅江。攻略把它排进主线，时间留得最足。","notice":"水府阁俯瞰沅江。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"桃花源景区"},{"spotId":"S3","name":"五柳湖","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"五柳湖是桃花源最有代表性的看点，落英缤纷打卡点。攻略把它排进主线，时间留得最足。","notice":"落英缤纷打卡点。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"桃花源核心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"常德米粉（人均18元）","description":"常德 · 桃花源的招牌是常德米粉，刘聋子粉馆本地人都认这家，点单照攻略不踩雷。","addr":"桃源县漳江镇"},{"title":"擂茶（人均35元）","description":"常德 · 桃花源的招牌是擂茶，秦溪擂茶馆本地人都认这家，点单照攻略不踩雷。","addr":"桃花源古镇内"},{"title":"桃源鸡（人均68元）","description":"常德 · 桃花源的招牌是桃源鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","保温水杯与少量现金","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","相机或运动相机","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('普者黑纯攻略·深度指南4','guide','文山 · 普者黑','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1990,1000,2,'青龙山 / 天鹅湖 / 仙人洞村 —— 纯攻略助你玩透普者黑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普者黑」两日慢旅行——水景。丘北辣椒香而不辣。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 文山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴文山","description":"集合出发，大巴直达普者黑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青龙山","description":"抵达后首游青龙山，登顶看万亩荷塘全景。","addr":"丘北县普者黑村","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐醉虾（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天鹅湖","description":"早起人少，天鹅湖精华时段，候鸟与荷塘，乘船打水仗。","addr":"普者黑景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐荷叶宴，人均68元，补充体力。","addr":"天鹅湖边","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"仙人洞村","description":"午后游览仙人洞村，撒尼人村落，民宿夜色美。","addr":"普者黑湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青龙山","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"青龙山是普者黑最有代表性的看点，登顶看万亩荷塘全景。攻略把它排进主线，时间留得最足。","notice":"登顶看万亩荷塘全景。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"丘北县普者黑村"},{"spotId":"S2","name":"天鹅湖","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"天鹅湖是普者黑最有代表性的看点，候鸟与荷塘，乘船打水仗。攻略把它排进主线，时间留得最足。","notice":"候鸟与荷塘，乘船打水仗。这个点位上午光线最好。","durationMinutes":180,"addr":"普者黑景区"},{"spotId":"S3","name":"仙人洞村","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"仙人洞村是普者黑最有代表性的看点，撒尼人村落，民宿夜色美。攻略把它排进主线，时间留得最足。","notice":"撒尼人村落，民宿夜色美。这个点位上午光线最好。","durationMinutes":120,"addr":"普者黑湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"醉虾（人均48元）","description":"文山 · 普者黑的招牌是醉虾，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"普者黑村"},{"title":"荷叶宴（人均68元）","description":"文山 · 普者黑的招牌是荷叶宴，荷香餐厅本地人都认这家，点单照攻略不踩雷。","addr":"天鹅湖边"},{"title":"丘北辣椒鸡（人均58元）","description":"文山 · 普者黑的招牌是丘北辣椒鸡，辣椒主题馆本地人都认这家，点单照攻略不踩雷。","addr":"丘北县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","相机或运动相机","少量零食补给","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 文山 的交通方便吗？","推荐先到 文山，再打车或景区直通车前往核心景区；自驾导航直接搜普者黑即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('蜀南竹海纯攻略·周末版4','guide','宜宾 · 蜀南竹海','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',2990,1600,1,'蜀南竹海 / 李庄古镇 / 兴文石海 —— 纯攻略助你玩透蜀南竹海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「蜀南竹海」三日深度游——古村落。竹荪竹笋干货轻便。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 宜宾"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜宾，抵达后办理入住、熟悉周边环境。","addr":"宜宾市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜀南竹海","description":"下午首站蜀南竹海，调整状态进入旅行节奏，忘忧谷翡翠长廊，竹林深处人家。","addr":"宜宾市长宁县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜宾一带氛围拉满，晚餐全竹宴人均68元。","addr":"蜀南竹海","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"李庄古镇","description":"全天主景点李庄古镇，万里长江第一古镇，抗战文化。","addr":"翠屏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐李庄白肉（人均42元），早点休息。","addr":"李庄古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"兴文石海","description":"收官兴文石海，天坑石林与僰人文化。","addr":"兴文县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐燃面后集合返程，三日旅程圆满。","addr":"宜宾市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜀南竹海","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"蜀南竹海是蜀南竹海最有代表性的看点，忘忧谷翡翠长廊，竹林深处人家。攻略把它排进主线，时间留得最足。","notice":"忘忧谷翡翠长廊，竹林深处人家。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"宜宾市长宁县"},{"spotId":"S2","name":"李庄古镇","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"李庄古镇是蜀南竹海最有代表性的看点，万里长江第一古镇，抗战文化。攻略把它排进主线，时间留得最足。","notice":"万里长江第一古镇，抗战文化。这个点位上午光线最好。","durationMinutes":150,"addr":"翠屏区"},{"spotId":"S3","name":"兴文石海","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"兴文石海是蜀南竹海最有代表性的看点，天坑石林与僰人文化。攻略把它排进主线，时间留得最足。","notice":"天坑石林与僰人文化。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"兴文县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"全竹宴（人均68元）","description":"宜宾 · 蜀南竹海的招牌是全竹宴，竹海人家本地人都认这家，点单照攻略不踩雷。","addr":"蜀南竹海"},{"title":"李庄白肉（人均42元）","description":"宜宾 · 蜀南竹海的招牌是李庄白肉，李庄老店本地人都认这家，点单照攻略不踩雷。","addr":"李庄古镇"},{"title":"燃面（人均12元）","description":"宜宾 · 蜀南竹海的招牌是燃面，刘臣街燃面本地人都认这家，点单照攻略不踩雷。","addr":"宜宾市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["当地有什么必吃？","到了 宜宾，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 宜宾 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阳朔漓江纯攻略·亲子篇4','guide','桂林 · 阳朔漓江','water','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',2500,1300,2,'兴坪漓江 / 遇龙河 / 西街 —— 纯攻略助你玩透阳朔漓江精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阳朔漓江」两日慢旅行——水景。阳朔金桔个大超甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴桂林","description":"集合出发，大巴直达阳朔漓江，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"兴坪漓江","description":"抵达后首游兴坪漓江，20元人民币背景，老寨山看全景。","addr":"阳朔县兴坪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐啤酒鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"遇龙河","description":"早起人少，遇龙河精华时段，竹筏漂流，工农桥日落。","addr":"阳朔县遇龙河","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐桂林米粉，人均12元，补充体力。","addr":"兴坪老街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"西街","description":"午后游览西街，老外扎堆的千年老街。","addr":"阳朔县西街","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"兴坪漓江","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"兴坪漓江是阳朔漓江最有代表性的看点，20元人民币背景，老寨山看全景。攻略把它排进主线，时间留得最足。","notice":"20元人民币背景，老寨山看全景。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"阳朔县兴坪镇"},{"spotId":"S2","name":"遇龙河","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"遇龙河是阳朔漓江最有代表性的看点，竹筏漂流，工农桥日落。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流，工农桥日落。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"阳朔县遇龙河"},{"spotId":"S3","name":"西街","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"西街是阳朔漓江最有代表性的看点，老外扎堆的千年老街。攻略把它排进主线，时间留得最足。","notice":"老外扎堆的千年老街。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"阳朔县西街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"啤酒鱼（人均68元）","description":"桂林 · 阳朔漓江的招牌是啤酒鱼，谢大姐啤酒鱼本地人都认这家，点单照攻略不踩雷。","addr":"西街口"},{"title":"桂林米粉（人均12元）","description":"桂林 · 阳朔漓江的招牌是桂林米粉，崇善米粉本地人都认这家，点单照攻略不踩雷。","addr":"兴坪老街"},{"title":"田螺酿（人均38元）","description":"桂林 · 阳朔漓江的招牌是田螺酿，阳朔农家本地人都认这家，点单照攻略不踩雷。","addr":"遇龙河边"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机","保温水杯与少量现金","少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南靖土楼纯攻略·摄影机位4','guide','漳州 · 南靖土楼','village','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',990,500,1,'田螺坑土楼群 / 裕昌楼 / 云水谣古镇 —— 纯攻略助你玩透南靖土楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「南靖土楼」三日深度游——古村落。土楼红茶岩韵悠长。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 漳州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往漳州，抵达后办理入住、熟悉周边环境。","addr":"漳州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"田螺坑土楼群","description":"下午首站田螺坑土楼群，调整状态进入旅行节奏，四菜一汤观景台，夜景更美。","addr":"南靖县书洋镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游漳州一带氛围拉满，晚餐土楼农家菜人均48元。","addr":"田螺坑下观景台","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"裕昌楼","description":"全天主景点裕昌楼，700年东歪西斜奇楼。","addr":"南靖县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐梅菜扣肉（人均42元），早点休息。","addr":"云水谣古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"云水谣古镇","description":"收官云水谣古镇，千年榕树与水车，电影取景地。","addr":"南靖县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糍粑后集合返程，三日旅程圆满。","addr":"裕昌楼前","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"田螺坑土楼群","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"田螺坑土楼群是南靖土楼最有代表性的看点，四菜一汤观景台，夜景更美。攻略把它排进主线，时间留得最足。","notice":"四菜一汤观景台，夜景更美。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"南靖县书洋镇"},{"spotId":"S2","name":"裕昌楼","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"裕昌楼是南靖土楼最有代表性的看点，700年东歪西斜奇楼。攻略把它排进主线，时间留得最足。","notice":"700年东歪西斜奇楼。这个点位上午光线最好。","durationMinutes":90,"addr":"南靖县"},{"spotId":"S3","name":"云水谣古镇","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"云水谣古镇是南靖土楼最有代表性的看点，千年榕树与水车，电影取景地。攻略把它排进主线，时间留得最足。","notice":"千年榕树与水车，电影取景地。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"南靖县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土楼农家菜（人均48元）","description":"漳州 · 南靖土楼的招牌是土楼农家菜，客家土菜馆本地人都认这家，点单照攻略不踩雷。","addr":"田螺坑下观景台"},{"title":"梅菜扣肉（人均42元）","description":"漳州 · 南靖土楼的招牌是梅菜扣肉，云水谣饭庄本地人都认这家，点单照攻略不踩雷。","addr":"云水谣古镇"},{"title":"糍粑（人均12元）","description":"漳州 · 南靖土楼的招牌是糍粑，土楼小吃本地人都认这家，点单照攻略不踩雷。","addr":"裕昌楼前"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","相机或运动相机","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意"],"faqs":[["当地有什么必吃？","到了 漳州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 漳州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('千岛湖纯攻略·美食清单4','guide','淳安 · 千岛湖','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',2500,1300,2,'中心湖区 / 东南湖区 / 文渊狮城 —— 纯攻略助你玩透千岛湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「千岛湖」两日慢旅行——水景。千岛湖有机鱼头认证标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 淳安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴淳安","description":"集合出发，大巴直达千岛湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中心湖区","description":"抵达后首游中心湖区，梅峰岛看千岛全景，缆车省力。","addr":"淳安县千岛湖镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐千岛湖鱼头（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"东南湖区","description":"早起人少，东南湖区精华时段，黄山尖九岛串联水道。","addr":"千岛湖","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山核桃，人均45元，补充体力。","addr":"渔街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"文渊狮城","description":"午后游览文渊狮城，水下古城复刻，夜游有戏。","addr":"姜家镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中心湖区","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"中心湖区是千岛湖最有代表性的看点，梅峰岛看千岛全景，缆车省力。攻略把它排进主线，时间留得最足。","notice":"梅峰岛看千岛全景，缆车省力。这个点位上午光线最好。","durationMinutes":240,"addr":"淳安县千岛湖镇"},{"spotId":"S2","name":"东南湖区","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"东南湖区是千岛湖最有代表性的看点，黄山尖九岛串联水道。攻略把它排进主线，时间留得最足。","notice":"黄山尖九岛串联水道。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"千岛湖"},{"spotId":"S3","name":"文渊狮城","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"文渊狮城是千岛湖最有代表性的看点，水下古城复刻，夜游有戏。攻略把它排进主线，时间留得最足。","notice":"水下古城复刻，夜游有戏。这个点位上午光线最好。","durationMinutes":120,"addr":"姜家镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"千岛湖鱼头（人均128元）","description":"淳安 · 千岛湖的招牌是千岛湖鱼头，淳牌鱼头馆本地人都认这家，点单照攻略不踩雷。","addr":"千岛湖镇新安大街"},{"title":"山核桃（人均45元）","description":"淳安 · 千岛湖的招牌是山核桃，特产店本地人都认这家，点单照攻略不踩雷。","addr":"渔街"},{"title":"艾草粿（人均10元）","description":"淳安 · 千岛湖的招牌是艾草粿，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"秀水街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","少量零食补给","墨镜与拍照道具","相机或运动相机","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 淳安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('东湖黄鹤楼纯攻略·自由行手册4','guide','武汉 · 东湖黄鹤楼','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',990,500,2,'黄鹤楼 / 东湖绿道 / 昙华林 —— 纯攻略助你玩透东湖黄鹤楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「东湖黄鹤楼」三日深度游——水景。武汉鸭脖真空包装好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 武汉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往武汉，抵达后办理入住、熟悉周边环境。","addr":"武汉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄鹤楼","description":"下午首站黄鹤楼，调整状态进入旅行节奏，天下江山第一楼，夜景灯光秀。","addr":"武汉市武昌区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游武汉一带氛围拉满，晚餐热干面人均12元。","addr":"户部巷","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"东湖绿道","description":"全天主景点东湖绿道，骑行湖中道，磨山樱园。","addr":"武昌区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐豆皮（人均18元），早点休息。","addr":"大智路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"昙华林","description":"收官昙华林，老教堂与文创小店。","addr":"武昌区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐武昌鱼后集合返程，三日旅程圆满。","addr":"昙华林","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄鹤楼","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"黄鹤楼是东湖黄鹤楼最有代表性的看点，天下江山第一楼，夜景灯光秀。攻略把它排进主线，时间留得最足。","notice":"天下江山第一楼，夜景灯光秀。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"武汉市武昌