INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('壶口瀑布纯攻略·亲子篇4','guide','延安 · 壶口瀑布','red','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',1990,1000,7,'壶口瀑布 / 宝塔山 / 枣园革命旧址 —— 纯攻略助你玩透壶口瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「壶口瀑布」两日慢旅行——人文。延安小米熬粥最养人。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 延安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延安","description":"集合出发，大巴直达壶口瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"壶口瀑布","description":"抵达后首游壶口瀑布，黄河之水天上来，旱地行船遗址。","addr":"延安市宜川县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐油馍馍（人均10元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"宝塔山","description":"早起人少，宝塔山精华时段，延安地标灯光秀。","addr":"延安市宝塔区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐羊杂碎，人均25元，补充体力。","addr":"宝塔区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"枣园革命旧址","description":"午后游览枣园革命旧址，窑洞与历史课堂。","addr":"宝塔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"壶口瀑布","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"壶口瀑布是壶口瀑布最有代表性的看点，黄河之水天上来，旱地行船遗址。攻略把它排进主线，时间留得最足。","notice":"黄河之水天上来，旱地行船遗址。这个点位上午光线最好。","durationMinutes":150,"addr":"延安市宜川县"},{"spotId":"S2","name":"宝塔山","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"宝塔山是壶口瀑布最有代表性的看点，延安地标灯光秀。攻略把它排进主线，时间留得最足。","notice":"延安地标灯光秀。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"延安市宝塔区"},{"spotId":"S3","name":"枣园革命旧址","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"枣园革命旧址是壶口瀑布最有代表性的看点，窑洞与历史课堂。攻略把它排进主线，时间留得最足。","notice":"窑洞与历史课堂。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"宝塔区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"油馍馍（人均10元）","description":"延安 · 壶口瀑布的招牌是油馍馍，延安小吃本地人都认这家，点单照攻略不踩雷。","addr":"枣园路口"},{"title":"羊杂碎（人均25元）","description":"延安 · 壶口瀑布的招牌是羊杂碎，陕北羊汤馆本地人都认这家，点单照攻略不踩雷。","addr":"宝塔区"},{"title":"洋芋擦擦（人均18元）","description":"延安 · 壶口瀑布的招牌是洋芋擦擦，陕北农家本地人都认这家，点单照攻略不踩雷。","addr":"宜川县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","墨镜与拍照道具","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽","少量零食补给","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 延安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 延安 的交通方便吗？","推荐先到 延安，再打车或景区直通车前往核心景区；自驾导航直接搜壶口瀑布即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('避暑山庄纯攻略·摄影机位4','guide','承德 · 避暑山庄','village','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',990,500,1,'避暑山庄 / 普宁寺 / 磬锤峰 —— 纯攻略助你玩透避暑山庄精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「避暑山庄」三日深度游——古村落。承德木雕核桃吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 承德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往承德，抵达后办理入住、熟悉周边环境。","addr":"承德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"避暑山庄","description":"下午首站避暑山庄，调整状态进入旅行节奏，皇家园林之最，山区乘车看小布达拉。","addr":"承德市双桥区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游承德一带氛围拉满，晚餐御土荷叶鸡人均38元。","addr":"承德市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"普宁寺","description":"全天主景点普宁寺，大佛寺千手千眼观音。","addr":"承德市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐荞面饸饹（人均18元），早点休息。","addr":"山庄东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"磬锤峰","description":"收官磬锤峰，棒槌山奇观，索道往返。","addr":"承德市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏仁茶后集合返程，三日旅程圆满。","addr":"二仙居","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"避暑山庄","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"避暑山庄是避暑山庄最有代表性的看点，皇家园林之最，山区乘车看小布达拉。攻略把它排进主线，时间留得最足。","notice":"皇家园林之最，山区乘车看小布达拉。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"承德市双桥区"},{"spotId":"S2","name":"普宁寺","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"普宁寺是避暑山庄最有代表性的看点，大佛寺千手千眼观音。攻略把它排进主线，时间留得最足。","notice":"大佛寺千手千眼观音。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"承德市"},{"spotId":"S3","name":"磬锤峰","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"磬锤峰是避暑山庄最有代表性的看点，棒槌山奇观，索道往返。攻略把它排进主线，时间留得最足。","notice":"棒槌山奇观，索道往返。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"承德市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"御土荷叶鸡（人均38元）","description":"承德 · 避暑山庄的招牌是御土荷叶鸡，老三羊汤本地人都认这家，点单照攻略不踩雷。","addr":"承德市区"},{"title":"荞面饸饹（人均18元）","description":"承德 · 避暑山庄的招牌是荞面饸饹，莜面馆本地人都认这家，点单照攻略不踩雷。","addr":"山庄东路"},{"title":"杏仁茶（人均10元）","description":"承德 · 避暑山庄的招牌是杏仁茶，小吃街本地人都认这家，点单照攻略不踩雷。","addr":"二仙居"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","相机或运动相机","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 承德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('日月湾冲浪纯攻略·美食清单4','guide','万宁 · 日月湾冲浪','sea','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,6,'日月湾 / 石梅湾 / 兴隆热带植物园 —— 纯攻略助你玩透日月湾冲浪精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「日月湾冲浪」两日慢旅行——海滨。兴隆炭烧咖啡回香浓。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 万宁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴万宁","description":"集合出发，大巴直达日月湾冲浪，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"日月湾","description":"抵达后首游日月湾，国家冲浪队训练地，新手教程2小时。","addr":"万宁市礼纪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐和乐蟹（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"石梅湾","description":"早起人少，石梅湾精华时段，加井岛浮潜，凤凰九里书屋。","addr":"万宁市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐东山羊，人均88元，补充体力。","addr":"万城镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"兴隆热带植物园","description":"午后游览兴隆热带植物园，咖啡可可巧克力之旅。","addr":"兴隆镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"日月湾","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"日月湾是日月湾冲浪最有代表性的看点，国家冲浪队训练地，新手教程2小时。攻略把它排进主线，时间留得最足。","notice":"国家冲浪队训练地，新手教程2小时。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"万宁市礼纪镇"},{"spotId":"S2","name":"石梅湾","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"石梅湾是日月湾冲浪最有代表性的看点，加井岛浮潜，凤凰九里书屋。攻略把它排进主线，时间留得最足。","notice":"加井岛浮潜，凤凰九里书屋。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"万宁市"},{"spotId":"S3","name":"兴隆热带植物园","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"兴隆热带植物园是日月湾冲浪最有代表性的看点，咖啡可可巧克力之旅。攻略把它排进主线，时间留得最足。","notice":"咖啡可可巧克力之旅。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"兴隆镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"和乐蟹（人均88元）","description":"万宁 · 日月湾冲浪的招牌是和乐蟹，渔家海鲜本地人都认这家，点单照攻略不踩雷。","addr":"东澳镇"},{"title":"东山羊（人均88元）","description":"万宁 · 日月湾冲浪的招牌是东山羊，东山羊庄本地人都认这家，点单照攻略不踩雷。","addr":"万城镇"},{"title":"兴隆咖啡（人均25元）","description":"万宁 · 日月湾冲浪的招牌是兴隆咖啡，咖啡庄园本地人都认这家，点单照攻略不踩雷。","addr":"兴隆镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","相机或运动相机","轻便雨衣或折叠伞","墨镜与拍照道具","少量零食补给","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 万宁 的交通方便吗？","推荐先到 万宁，再打车或景区直通车前往核心景区；自驾导航直接搜日月湾冲浪即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 万宁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('喀纳斯纯攻略·自由行手册4','guide','阿勒泰 · 喀纳斯','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1990,1000,2,'喀纳斯湖 / 禾木村 / 白哈巴 —— 纯攻略助你玩透喀纳斯精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「喀纳斯」三日深度游——水景。喀纳斯冷水鱼干风味独特。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 阿勒泰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往阿勒泰，抵达后办理入住、熟悉周边环境。","addr":"阿勒泰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"喀纳斯湖","description":"下午首站喀纳斯湖，调整状态进入旅行节奏，三湾晨雾与湖怪传说，观鱼台俯瞰。","addr":"布尔津县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游阿勒泰一带氛围拉满，晚餐烤全羊人均128元。","addr":"禾木村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"禾木村","description":"全天主景点禾木村，图瓦人村落，白桦林晨雾。","addr":"喀纳斯景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐手抓饭（人均35元），早点休息。","addr":"贾登峪","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"白哈巴","description":"收官白哈巴，中哈边境原始村落。","addr":"哈巴河县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐奶茶后集合返程，三日旅程圆满。","addr":"白哈巴","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"喀纳斯湖","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"喀纳斯湖是喀纳斯最有代表性的看点，三湾晨雾与湖怪传说，观鱼台俯瞰。攻略把它排进主线，时间留得最足。","notice":"三湾晨雾与湖怪传说，观鱼台俯瞰。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"布尔津县"},{"spotId":"S2","name":"禾木村","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"禾木村是喀纳斯最有代表性的看点，图瓦人村落，白桦林晨雾。攻略把它排进主线，时间留得最足。","notice":"图瓦人村落，白桦林晨雾。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"喀纳斯景区"},{"spotId":"S3","name":"白哈巴","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"白哈巴是喀纳斯最有代表性的看点，中哈边境原始村落。攻略把它排进主线，时间留得最足。","notice":"中哈边境原始村落。这个点位上午光线最好。","durationMinutes":120,"addr":"哈巴河县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤全羊（人均128元）","description":"阿勒泰 · 喀纳斯的招牌是烤全羊，图瓦人家本地人都认这家，点单照攻略不踩雷。","addr":"禾木村"},{"title":"手抓饭（人均35元）","description":"阿勒泰 · 喀纳斯的招牌是手抓饭，别克餐厅本地人都认这家，点单照攻略不踩雷。","addr":"贾登峪"},{"title":"奶茶（人均20元）","description":"阿勒泰 · 喀纳斯的招牌是奶茶，哈萨克毡房本地人都认这家，点单照攻略不踩雷。","addr":"白哈巴"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","少量零食补给","墨镜与拍照道具","换洗衣物与外套（早晚温差）","相机或运动相机","身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 阿勒泰，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('中央大街冰雪纯攻略·省钱玩法4','guide','哈尔滨 · 中央大街冰雪','art','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,5,'中央大街 / 圣索菲亚大教堂 / 松花江防洪纪念塔 —— 纯攻略助你玩透中央大街冰雪精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「中央大街冰雪」两日慢旅行——文艺。哈尔滨红肠真空好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"黑龙江 · 哈尔滨"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴哈尔滨","description":"集合出发，大巴直达中央大街冰雪，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中央大街","description":"抵达后首游中央大街，百年面包石街道，马迭尔冰棍。","addr":"哈尔滨市道里区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐锅包肉（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"圣索菲亚大教堂","description":"早起人少，圣索菲亚大教堂精华时段，拜占庭绿顶，鸽子广场。","addr":"透笼街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐哈尔滨红肠，人均25元，补充体力。","addr":"中央大街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"松花江防洪纪念塔","description":"午后游览松花江防洪纪念塔，冬季冰上活动集合地。","addr":"道里区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中央大街","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"中央大街是中央大街冰雪最有代表性的看点，百年面包石街道，马迭尔冰棍。攻略把它排进主线，时间留得最足。","notice":"百年面包石街道，马迭尔冰棍。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"哈尔滨市道里区"},{"spotId":"S2","name":"圣索菲亚大教堂","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"圣索菲亚大教堂是中央大街冰雪最有代表性的看点，拜占庭绿顶，鸽子广场。攻略把它排进主线，时间留得最足。","notice":"拜占庭绿顶，鸽子广场。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"透笼街"},{"spotId":"S3","name":"松花江防洪纪念塔","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"松花江防洪纪念塔是中央大街冰雪最有代表性的看点，冬季冰上活动集合地。攻略把它排进主线，时间留得最足。","notice":"冬季冰上活动集合地。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"道里区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"锅包肉（人均48元）","description":"哈尔滨 · 中央大街冰雪的招牌是锅包肉，老厨家本地人都认这家，点单照攻略不踩雷。","addr":"友谊路"},{"title":"哈尔滨红肠（人均25元）","description":"哈尔滨 · 中央大街冰雪的招牌是哈尔滨红肠，秋林里道斯本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"},{"title":"格瓦斯（人均12元）","description":"哈尔滨 · 中央大街冰雪的招牌是格瓦斯，马迭尔冷饮厅本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","相机或运动相机","轻便雨衣或折叠伞","少量零食补给","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 哈尔滨，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 哈尔滨 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武功山纯攻略·避坑版4','guide','萍乡 · 武功山','mountain','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',1200,600,2,'金顶 / 发云界 / 玻璃栈道 —— 纯攻略助你玩透武功山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武功山」三日深度游——山岳。武功山泉水豆腐宴别错过。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往萍乡，抵达后办理入住、熟悉周边环境。","addr":"萍乡市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，日出云海核心位，山顶比山下冷10度。","addr":"武功山风景区金顶","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游萍乡一带氛围拉满，晚餐萍乡小炒肉人均42元。","addr":"武功山游客中心旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"发云界","description":"全天主景点发云界，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐艾米古（人均10元），早点休息。","addr":"金顶驿站","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"玻璃栈道","description":"收官玻璃栈道，栈道限流，旺季排30分钟。","addr":"武功山吊马桩","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐紫红米粉后集合返程，三日旅程圆满。","addr":"武功山镇主街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","身份证件与手机充电宝","轻便雨衣或折叠伞","相机或运动相机","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('仙女湖纯攻略·深度指南4','guide','新余 · 仙女湖','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1500,800,2,'仙女湖主体湖区 / 圣集寺 / 龙王阁 —— 纯攻略助你玩透仙女湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「仙女湖」两日慢旅行——水景。新余蜜桔十月后最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 新余"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴新余","description":"集合出发，大巴直达仙女湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"仙女湖主体湖区","description":"抵达后首游仙女湖主体湖区，坐船跳岛游，爱情岛最热门。","addr":"新余市渝水区仙女湖大道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐仙女湖鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"圣集寺","description":"早起人少，圣集寺精华时段，湖畔禅意，人少清净。","addr":"仙女湖钤阳湖畔","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐新余蜜桔鸡，人均58元，补充体力。","addr":"景区出口农家乐","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙王阁","description":"午后游览龙王阁，登阁看千岛湖景。","addr":"仙女湖最高点","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"仙女湖主体湖区","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"仙女湖主体湖区是仙女湖最有代表性的看点，坐船跳岛游，爱情岛最热门。攻略把它排进主线，时间留得最足。","notice":"坐船跳岛游，爱情岛最热门。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"新余市渝水区仙女湖大道"},{"spotId":"S2","name":"圣集寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"圣集寺是仙女湖最有代表性的看点，湖畔禅意，人少清净。攻略把它排进主线，时间留得最足。","notice":"湖畔禅意，人少清净。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"仙女湖钤阳湖畔"},{"spotId":"S3","name":"龙王阁","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"龙王阁是仙女湖最有代表性的看点，登阁看千岛湖景。攻略把它排进主线，时间留得最足。","notice":"登阁看千岛湖景。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"仙女湖最高点"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"仙女湖鱼头（人均78元）","description":"新余 · 仙女湖的招牌是仙女湖鱼头，湖畔渔村本地人都认这家，点单照攻略不踩雷。","addr":"仙女湖码头渔家街"},{"title":"新余蜜桔鸡（人均58元）","description":"新余 · 仙女湖的招牌是新余蜜桔鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口农家乐"},{"title":"水北豆腐（人均25元）","description":"新余 · 仙女湖的招牌是水北豆腐，老豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"新余城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","少量零食补给","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 新余 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('崀山纯攻略·周末版4','guide','邵阳 · 崀山','adventure','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',990,500,9,'辣椒峰 / 天一巷 / 扶夷江竹筏 —— 纯攻略助你玩透崀山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「崀山」三日深度游——探险地。新宁脐橙秋冬正当季。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 邵阳"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往邵阳，抵达后办理入住、熟悉周边环境。","addr":"邵阳市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"辣椒峰","description":"下午首站辣椒峰，调整状态进入旅行节奏，丹霞地貌标志峰，远观近爬两相宜。","addr":"新宁县崀山景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游邵阳一带氛围拉满，晚餐崀山腊肉人均52元。","addr":"崀山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天一巷","description":"全天主景点天一巷，一线天最窄处仅33厘米。","addr":"崀山丹霞巷谷","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐血酱鸭（人均58元），早点休息。","addr":"新宁县城","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"扶夷江竹筏","description":"收官扶夷江竹筏，竹筏漂流看丹霞倒影。","addr":"崀山水上游线","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐脐橙后集合返程，三日旅程圆满。","addr":"崀山脚下果园","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"辣椒峰","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"辣椒峰是崀山最有代表性的看点，丹霞地貌标志峰，远观近爬两相宜。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌标志峰，远观近爬两相宜。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"新宁县崀山景区"},{"spotId":"S2","name":"天一巷","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"天一巷是崀山最有代表性的看点，一线天最窄处仅33厘米。攻略把它排进主线，时间留得最足。","notice":"一线天最窄处仅33厘米。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"崀山丹霞巷谷"},{"spotId":"S3","name":"扶夷江竹筏","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"扶夷江竹筏是崀山最有代表性的看点，竹筏漂流看丹霞倒影。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流看丹霞倒影。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"崀山水上游线"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"崀山腊肉（人均52元）","description":"邵阳 · 崀山的招牌是崀山腊肉，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"崀山镇"},{"title":"血酱鸭（人均58元）","description":"邵阳 · 崀山的招牌是血酱鸭，邵阳风味馆本地人都认这家，点单照攻略不踩雷。","addr":"新宁县城"},{"title":"脐橙（人均10元）","description":"邵阳 · 崀山的招牌是脐橙，果园直购本地人都认这家，点单照攻略不踩雷。","addr":"崀山脚下果园"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","身份证件与手机充电宝","墨镜与拍照道具","少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）","保温水杯与少量现金","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 邵阳 的交通方便吗？","推荐先到 邵阳，再打车或景区直通车前往核心景区；自驾导航直接搜崀山即可。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('告庄西双景纯攻略·亲子篇4','guide','西双版纳 · 告庄西双景','sea','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',1990,1000,6,'告庄星光夜市 / 曼听公园 / 中科院热带植物园 —— 纯攻略助你玩透告庄西双景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「告庄西双景」两日慢旅行——海滨。版纳小粒咖啡香浓不酸。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 西双版纳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴西双版纳","description":"集合出发，大巴直达告庄西双景，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"告庄星光夜市","description":"抵达后首游告庄星光夜市，大金塔下的东南亚最大夜市。","addr":"景洪市告庄西双景","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐菠萝饭（人均25元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"曼听公园","description":"早起人少，曼听公园精华时段，总佛寺相邻，晚场篝火晚会。","addr":"景洪市曼听路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香茅草烤鱼，人均48元，补充体力。","addr":"告庄内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"中科院热带植物园","description":"午后游览中科院热带植物园，王莲上坐一坐，热气球拍照。","addr":"勐腊县勐仑镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"告庄星光夜市","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"告庄星光夜市是告庄西双景最有代表性的看点，大金塔下的东南亚最大夜市。攻略把它排进主线，时间留得最足。","notice":"大金塔下的东南亚最大夜市。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"景洪市告庄西双景"},{"spotId":"S2","name":"曼听公园","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"曼听公园是告庄西双景最有代表性的看点，总佛寺相邻，晚场篝火晚会。攻略把它排进主线，时间留得最足。","notice":"总佛寺相邻，晚场篝火晚会。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"景洪市曼听路"},{"spotId":"S3","name":"中科院热带植物园","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"中科院热带植物园是告庄西双景最有代表性的看点，王莲上坐一坐，热气球拍照。攻略把它排进主线，时间留得最足。","notice":"王莲上坐一坐，热气球拍照。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"勐腊县勐仑镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"菠萝饭（人均25元）","description":"西双版纳 · 告庄西双景的招牌是菠萝饭，夜市傣味摊本地人都认这家，点单照攻略不踩雷。","addr":"星光夜市"},{"title":"香茅草烤鱼（人均48元）","description":"西双版纳 · 告庄西双景的招牌是香茅草烤鱼，曼飞龙烤鸡本地人都认这家，点单照攻略不踩雷。","addr":"告庄内"},{"title":"泡鲁达（人均15元）","description":"西双版纳 · 告庄西双景的招牌是泡鲁达，傣家甜品店本地人都认这家，点单照攻略不踩雷。","addr":"大金塔旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","相机或运动相机","少量零食补给","换洗衣物与外套（早晚温差）","保温水杯与少量现金","墨镜与拍照道具","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["当地有什么必吃？","到了 西双版纳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 西双版纳 的交通方便吗？","推荐先到 西双版纳，再打车或景区直通车前往核心景区；自驾导航直接搜告庄西双景即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阆中古城纯攻略·摄影机位4','guide','南充 · 阆中古城','ancient_town','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1500,800,1,'阆中古城 / 华光楼 / 锦屏山 —— 纯攻略助你玩透阆中古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阆中古城」三日深度游——古镇。保宁醋是四大名醋之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 南充"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往南充，抵达后办理入住、熟悉周边环境。","addr":"南充市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"阆中古城","description":"下午首站阆中古城，调整状态进入旅行节奏，四大古城之一，张飞庙贡院联票。","addr":"南充市阆中市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游南充一带氛围拉满，晚餐张飞牛肉人均45元。","addr":"古城北街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"华光楼","description":"全天主景点华光楼，登楼看嘉陵江三面环抱。","addr":"古城上华街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐保宁醋（人均20元），早点休息。","addr":"古城内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"锦屏山","description":"收官锦屏山，观古城全景最佳位。","addr":"古城对岸","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐油香后集合返程，三日旅程圆满。","addr":"下沙河街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"阆中古城","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"阆中古城是阆中古城最有代表性的看点，四大古城之一，张飞庙贡院联票。攻略把它排进主线，时间留得最足。","notice":"四大古城之一，张飞庙贡院联票。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"南充市阆中市"},{"spotId":"S2","name":"华光楼","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"华光楼是阆中古城最有代表性的看点，登楼看嘉陵江三面环抱。攻略把它排进主线，时间留得最足。","notice":"登楼看嘉陵江三面环抱。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"古城上华街"},{"spotId":"S3","name":"锦屏山","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"锦屏山是阆中古城最有代表性的看点，观古城全景最佳位。攻略把它排进主线，时间留得最足。","notice":"观古城全景最佳位。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"古城对岸"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"张飞牛肉（人均45元）","description":"南充 · 阆中古城的招牌是张飞牛肉，张飞牛肉旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"古城北街"},{"title":"保宁醋（人均20元）","description":"南充 · 阆中古城的招牌是保宁醋，醋文化博览馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"油香（人均8元）","description":"南充 · 阆中古城的招牌是油香，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"下沙河街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","少量零食补给","相机或运动相机","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 南充 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 南充 的交通方便吗？","推荐先到 南充，再打车或景区直通车前往核心景区；自驾导航直接搜阆中古城即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('镇远古镇纯攻略·美食清单4','guide','黔东南 · 镇远古镇','ancient_town','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',990,500,1,'青龙洞 / 舞阳河 / 石屏山 —— 纯攻略助你玩透镇远古镇精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「镇远古镇」两日慢旅行——古镇。镇远蓝染布艺越洗越好看。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔东南","description":"集合出发，大巴直达镇远古镇，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青龙洞","description":"抵达后首游青龙洞，贴崖古建筑群，对望古城。","addr":"镇远县中和山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐酸汤鱼（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"舞阳河","description":"早起人少，舞阳河精华时段，乘船看孔雀开屏峰。","addr":"镇远县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐陈年道菜，人均30元，补充体力。","addr":"古镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"石屏山","description":"午后游览石屏山，俯瞰太极古城全景。","addr":"古城北侧","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青龙洞","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"青龙洞是镇远古镇最有代表性的看点，贴崖古建筑群，对望古城。攻略把它排进主线，时间留得最足。","notice":"贴崖古建筑群，对望古城。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"镇远县中和山"},{"spotId":"S2","name":"舞阳河","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"舞阳河是镇远古镇最有代表性的看点，乘船看孔雀开屏峰。攻略把它排进主线，时间留得最足。","notice":"乘船看孔雀开屏峰。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"镇远县"},{"spotId":"S3","name":"石屏山","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"石屏山是镇远古镇最有代表性的看点，俯瞰太极古城全景。攻略把它排进主线，时间留得最足。","notice":"俯瞰太极古城全景。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"古城北侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均58元）","description":"黔东南 · 镇远古镇的招牌是酸汤鱼，古城酸汤馆本地人都认这家，点单照攻略不踩雷。","addr":"兴隆街"},{"title":"陈年道菜（人均30元）","description":"黔东南 · 镇远古镇的招牌是陈年道菜，老字号本地人都认这家，点单照攻略不踩雷。","addr":"古镇主街"},{"title":"苗家腊肉（人均48元）","description":"黔东南 · 镇远古镇的招牌是苗家腊肉，河畔农家本地人都认这家，点单照攻略不踩雷。","addr":"舞阳河畔"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","换洗衣物与外套（早晚温差）","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('鼓浪屿纯攻略·自由行手册4','guide','厦门 · 鼓浪屿','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',2990,1600,6,'日光岩 / 菽庄花园 / 沙坡尾 —— 纯攻略助你玩透鼓浪屿精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「鼓浪屿」三日深度游——海滨。厦门馅饼老字号最正宗。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 厦门"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往厦门，抵达后办理入住、熟悉周边环境。","addr":"厦门市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"日光岩","description":"下午首站日光岩，调整状态进入旅行节奏，全岛最高点看红瓦绿树海景。","addr":"鼓浪屿龙头山路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游厦门一带氛围拉满，晚餐沙茶面人均28元。","addr":"民族路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"菽庄花园","description":"全天主景点菽庄花园，四十四桥跨海，钢琴博物馆。","addr":"鼓浪屿港仔后路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海蛎煎（人均25元），早点休息。","addr":"八市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙坡尾","description":"收官沙坡尾，避风坞文艺街区，猫街涂鸦。","addr":"厦门市思明区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐土笋冻后集合返程，三日旅程圆满。","addr":"斗西路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"日光岩","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"日光岩是鼓浪屿最有代表性的看点，全岛最高点看红瓦绿树海景。攻略把它排进主线，时间留得最足。","notice":"全岛最高点看红瓦绿树海景。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"鼓浪屿龙头山路"},{"spotId":"S2","name":"菽庄花园","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"菽庄花园是鼓浪屿最有代表性的看点，四十四桥跨海，钢琴博物馆。攻略把它排进主线，时间留得最足。","notice":"四十四桥跨海，钢琴博物馆。这个点位上午光线最好。","durationMinutes":120,"addr":"鼓浪屿港仔后路"},{"spotId":"S3","name":"沙坡尾","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"沙坡尾是鼓浪屿最有代表性的看点，避风坞文艺街区，猫街涂鸦。攻略把它排进主线，时间留得最足。","notice":"避风坞文艺街区，猫街涂鸦。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"厦门市思明区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"沙茶面（人均28元）","description":"厦门 · 鼓浪屿的招牌是沙茶面，乌糖沙茶面本地人都认这家，点单照攻略不踩雷。","addr":"民族路"},{"title":"海蛎煎（人均25元）","description":"厦门 · 鼓浪屿的招牌是海蛎煎，莲欢海蛎煎本地人都认这家，点单照攻略不踩雷。","addr":"八市"},{"title":"土笋冻（人均15元）","description":"厦门 · 鼓浪屿的招牌是土笋冻，西门土笋冻本地人都认这家，点单照攻略不踩雷。","addr":"斗西路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","保温水杯与少量现金","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具","相机或运动相机"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["到达 厦门 的交通方便吗？","推荐先到 厦门，再打车或景区直通车前往核心景区；自驾导航直接搜鼓浪屿即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 厦门，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雁荡山纯攻略·省钱玩法4','guide','温州 · 雁荡山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,2,'灵峰 / 大龙湫 / 方洞栈道 —— 纯攻略助你玩透雁荡山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「雁荡山」两日慢旅行——山岳。雁荡山铁皮石斛有名。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 温州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴温州","description":"集合出发，大巴直达雁荡山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"灵峰","description":"抵达后首游灵峰，日景夜景两相宜，夫妻峰剪影。","addr":"乐清市雁荡山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐雁荡山石斑鱼（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大龙湫","description":"早起人少，大龙湫精华时段，190米瀑布，雨后最壮。","addr":"雁荡山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香鱼，人均48元，补充体力。","addr":"大龙湫下","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"方洞栈道","description":"午后游览方洞栈道，悬崖栈道悬空百米。","addr":"雁荡山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"灵峰","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"灵峰是雁荡山最有代表性的看点，日景夜景两相宜，夫妻峰剪影。攻略把它排进主线，时间留得最足。","notice":"日景夜景两相宜，夫妻峰剪影。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"乐清市雁荡山"},{"spotId":"S2","name":"大龙湫","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大龙湫是雁荡山最有代表性的看点，190米瀑布，雨后最壮。攻略把它排进主线，时间留得最足。","notice":"190米瀑布，雨后最壮。这个点位上午光线最好。","durationMinutes":90,"addr":"雁荡山"},{"spotId":"S3","name":"方洞栈道","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"方洞栈道是雁荡山最有代表性的看点，悬崖栈道悬空百米。攻略把它排进主线，时间留得最足。","notice":"悬崖栈道悬空百米。这个点位上午光线最好。","durationMinutes":120,"addr":"雁荡山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"雁荡山石斑鱼（人均58元）","description":"温州 · 雁荡山的招牌是雁荡山石斑鱼，山溪鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"响岭头村"},{"title":"香鱼（人均48元）","description":"温州 · 雁荡山的招牌是香鱼，溪鱼农家本地人都认这家，点单照攻略不踩雷。","addr":"大龙湫下"},{"title":"雁茗茶（人均25元）","description":"温州 · 雁荡山的招牌是雁茗茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"灵峰景区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","相机或运动相机","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 温州 的交通方便吗？","推荐先到 温州，再打车或景区直通车前往核心景区；自驾导航直接搜雁荡山即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄山宏村纯攻略·避坑版4','guide','黄山 · 黄山宏村','mountain','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',990,500,2,'黄山光明顶 / 西海大峡谷 / 宏村 —— 纯攻略助你玩透黄山宏村精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「黄山宏村」三日深度游——山岳。徽墨歙砚文房收藏佳品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 黄山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黄山，抵达后办理入住、熟悉周边环境。","addr":"黄山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄山光明顶","description":"下午首站黄山光明顶，调整状态进入旅行节奏，看日出云海的主峰平台。","addr":"黄山市黄山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黄山一带氛围拉满，晚餐臭鳜鱼人均78元。","addr":"屯溪老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西海大峡谷","description":"全天主景点西海大峡谷，网红小火车，峡谷栈道惊险。","addr":"黄山风景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐毛豆腐（人均20元），早点休息。","addr":"宏村月沼旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"宏村","description":"收官宏村，月沼南湖水墨徽州，写生圣地。","addr":"黟县宏村镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐黄山烧饼后集合返程，三日旅程圆满。","addr":"汤口镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄山光明顶","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"黄山光明顶是黄山宏村最有代表性的看点，看日出云海的主峰平台。攻略把它排进主线，时间留得最足。","notice":"看日出云海的主峰平台。这个点位上午光线最好。","durationMinutes":300,"addr":"黄山市黄山区"},{"spotId":"S2","name":"西海大峡谷","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"西海大峡谷是黄山宏村最有代表性的看点，网红小火车，峡谷栈道惊险。攻略把它排进主线，时间留得最足。","notice":"网红小火车，峡谷栈道惊险。这个点位上午光线最好。","durationMinutes":240,"addr":"黄山风景区"},{"spotId":"S3","name":"宏村","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"宏村是黄山宏村最有代表性的看点，月沼南湖水墨徽州，写生圣地。攻略把它排进主线，时间留得最足。","notice":"月沼南湖水墨徽州，写生圣地。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"黟县宏村镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"臭鳜鱼（人均78元）","description":"黄山 · 黄山宏村的招牌是臭鳜鱼，老街第一楼本地人都认这家，点单照攻略不踩雷。","addr":"屯溪老街"},{"title":"毛豆腐（人均20元）","description":"黄山 · 黄山宏村的招牌是毛豆腐，徽州小吃本地人都认这家，点单照攻略不踩雷。","addr":"宏村月沼旁"},{"title":"黄山烧饼（人均12元）","description":"黄山 · 黄山宏村的招牌是黄山烧饼，救驾烧饼本地人都认这家，点单照攻略不踩雷。","addr":"汤口镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","相机或运动相机","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","少量零食补给","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待"],"faqs":[["当地有什么必吃？","到了 黄山，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 黄山 的交通方便吗？","推荐先到 黄山，再打车或景区直通车前往核心景区；自驾导航直接搜黄山宏村即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 黄山 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙门石窟纯攻略·深度指南4','guide','洛阳 · 龙门石窟','red','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,7,'龙门石窟 / 白马寺 / 洛邑古城 —— 纯攻略助你玩透龙门石窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙门石窟」两日慢旅行——人文。洛阳牡丹饼花香浓郁。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 洛阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴洛阳","description":"集合出发，大巴直达龙门石窟，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"龙门石窟","description":"抵达后首游龙门石窟，卢舍那大佛，夜游灯光版。","addr":"洛阳市洛龙区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐水席（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"白马寺","description":"早起人少，白马寺精华时段，中国第一古刹，国际佛殿。","addr":"洛阳市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牛肉汤，人均15元，补充体力。","addr":"瀍河区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"洛邑古城","description":"午后游览洛邑古城，汉服打卡圣地，夜景。","addr":"老城区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"龙门石窟","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"龙门石窟是龙门石窟最有代表性的看点，卢舍那大佛，夜游灯光版。攻略把它排进主线，时间留得最足。","notice":"卢舍那大佛，夜游灯光版。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"洛阳市洛龙区"},{"spotId":"S2","name":"白马寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"白马寺是龙门石窟最有代表性的看点，中国第一古刹，国际佛殿。攻略把它排进主线，时间留得最足。","notice":"中国第一古刹，国际佛殿。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"洛阳市"},{"spotId":"S3","name":"洛邑古城","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"洛邑古城是龙门石窟最有代表性的看点，汉服打卡圣地，夜景。攻略把它排进主线，时间留得最足。","notice":"汉服打卡圣地，夜景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"老城区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水席（人均88元）","description":"洛阳 · 龙门石窟的招牌是水席，真不同本地人都认这家，点单照攻略不踩雷。","addr":"老城区"},{"title":"牛肉汤（人均15元）","description":"洛阳 · 龙门石窟的招牌是牛肉汤，马杰山牛肉汤本地人都认这家，点单照攻略不踩雷。","addr":"瀍河区"},{"title":"不翻汤（人均12元）","description":"洛阳 · 龙门石窟的招牌是不翻汤，十字街夜市本地人都认这家，点单照攻略不踩雷。","addr":"老城十字街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","墨镜与拍照道具","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","保温水杯与少量现金","身份证件与手机充电宝","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 洛阳 的交通方便吗？","推荐先到 洛阳，再打车或景区直通车前往核心景区；自驾导航直接搜龙门石窟即可。"],["当地有什么必吃？","到了 洛阳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('平遥古城纯攻略·周末版4','guide','晋中 · 平遥古城','ancient_town','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',990,500,1,'平遥古城墙 / 日升昌票号 / 协同庆地下金库 —— 纯攻略助你玩透平遥古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「平遥古城」三日深度游——古镇。平遥推光漆器手工至极。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 晋中"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往晋中，抵达后办理入住、熟悉周边环境。","addr":"晋中市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"平遥古城墙","description":"下午首站平遥古城墙，调整状态进入旅行节奏，完整明代城墙，骑行一周。","addr":"晋中市平遥县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游晋中一带氛围拉满，晚餐平遥牛肉人均45元。","addr":"古城南大街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"日升昌票号","description":"全天主景点日升昌票号，中国第一家票号，晋商传奇。","addr":"古城西大街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐碗托（人均12元），早点休息。","addr":"城隍庙街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"协同庆地下金库","description":"收官协同庆地下金库，探秘地下金库。","addr":"古城市楼旁","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐莜面栲栳栳后集合返程，三日旅程圆满。","addr":"西大街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"平遥古城墙","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"平遥古城墙是平遥古城最有代表性的看点，完整明代城墙，骑行一周。攻略把它排进主线，时间留得最足。","notice":"完整明代城墙，骑行一周。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"晋中市平遥县"},{"spotId":"S2","name":"日升昌票号","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"日升昌票号是平遥古城最有代表性的看点，中国第一家票号，晋商传奇。攻略把它排进主线，时间留得最足。","notice":"中国第一家票号，晋商传奇。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"古城西大街"},{"spotId":"S3","name":"协同庆地下金库","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"协同庆地下金库是平遥古城最有代表性的看点，探秘地下金库。攻略把它排进主线，时间留得最足。","notice":"探秘地下金库。这个点位上午光线最好。","durationMinutes":60,"addr":"古城市楼旁"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"平遥牛肉（人均45元）","description":"晋中 · 平遥古城的招牌是平遥牛肉，冠云专卖店本地人都认这家，点单照攻略不踩雷。","addr":"古城南大街"},{"title":"碗托（人均12元）","description":"晋中 · 平遥古城的招牌是碗托，碗托娘子本地人都认这家，点单照攻略不踩雷。","addr":"城隍庙街"},{"title":"莜面栲栳栳（人均28元）","description":"晋中 · 平遥古城的招牌是莜面栲栳栳，晋菜馆本地人都认这家，点单照攻略不踩雷。","addr":"西大街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具","保温水杯与少量现金","防晒霜与遮阳帽","少量零食补给","常用药品（肠胃药/创可贴）","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 晋中 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('北戴河阿那亚纯攻略·亲子篇4','guide','秦皇岛 · 北戴河阿那亚','sea','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',2990,1600,6,'阿那亚礼堂 / 鸽子窝公园 / 山海关天下第一关 —— 纯攻略助你玩透北戴河阿那亚精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「北戴河阿那亚」两日慢旅行——海滨。北戴河干海参实惠。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 秦皇岛"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴秦皇岛","description":"集合出发，大巴直达北戴河阿那亚，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"阿那亚礼堂","description":"抵达后首游阿那亚礼堂，海边白色礼堂，孤独图书馆。","addr":"秦皇岛市昌黎县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐海鲜烧烤（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"鸽子窝公园","description":"早起人少，鸽子窝公园精华时段，观鸟湿地日出圣地。","addr":"北戴河区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐四条包子，人均12元，补充体力。","addr":"山海关","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"山海关天下第一关","description":"午后游览山海关天下第一关，长城入海老龙头。","addr":"山海关区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"阿那亚礼堂","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"阿那亚礼堂是北戴河阿那亚最有代表性的看点，海边白色礼堂，孤独图书馆。攻略把它排进主线，时间留得最足。","notice":"海边白色礼堂，孤独图书馆。这个点位上午光线最好。","durationMinutes":120,"addr":"秦皇岛市昌黎县"},{"spotId":"S2","name":"鸽子窝公园","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"鸽子窝公园是北戴河阿那亚最有代表性的看点，观鸟湿地日出圣地。攻略把它排进主线，时间留得最足。","notice":"观鸟湿地日出圣地。这个点位上午光线最好。","durationMinutes":90,"addr":"北戴河区"},{"spotId":"S3","name":"山海关天下第一关","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"山海关天下第一关是北戴河阿那亚最有代表性的看点，长城入海老龙头。攻略把它排进主线，时间留得最足。","notice":"长城入海老龙头。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"山海关区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜烧烤（人均68元）","description":"秦皇岛 · 北戴河阿那亚的招牌是海鲜烧烤，刘庄夜市本地人都认这家，点单照攻略不踩雷。","addr":"北戴河刘庄"},{"title":"四条包子（人均12元）","description":"秦皇岛 · 北戴河阿那亚的招牌是四条包子，四条包子铺本地人都认这家，点单照攻略不踩雷。","addr":"山海关"},{"title":"杨肠子（人均25元）","description":"秦皇岛 · 北戴河阿那亚的招牌是杨肠子，火腿肠老字号本地人都认这家，点单照攻略不踩雷。","addr":"北戴河"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","少量零食补给","身份证件与手机充电宝","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["几月份去 秦皇岛 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('洪崖洞夜景纯攻略·摄影机位4','guide','渝中 · 洪崖洞夜景','food','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1500,800,3,'洪崖洞 / 长江索道 / 山城步道 —— 纯攻略助你玩透洪崖洞夜景精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「洪崖洞夜景」三日深度游——美食。重庆火锅底料真空包装。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 渝中"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往渝中，抵达后办理入住、熟悉周边环境。","addr":"渝中市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"洪崖洞","description":"下午首站洪崖洞，调整状态进入旅行节奏，千与千寻同款夜景，对岸拍全景。","addr":"渝中区嘉陵江畔","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游渝中一带氛围拉满，晚餐重庆火锅人均98元。","addr":"解放碑","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长江索道","description":"全天主景点长江索道，空中横渡长江，排队1小时。","addr":"渝中区新华路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐重庆小面（人均15元），早点休息。","addr":"民生路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"山城步道","description":"收官山城步道，第三步道悬空栈道看老重庆。","addr":"渝中区中兴路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸辣粉后集合返程，三日旅程圆满。","addr":"八一路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"洪崖洞","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"洪崖洞是洪崖洞夜景最有代表性的看点，千与千寻同款夜景，对岸拍全景。攻略把它排进主线，时间留得最足。","notice":"千与千寻同款夜景，对岸拍全景。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"渝中区嘉陵江畔"},{"spotId":"S2","name":"长江索道","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"长江索道是洪崖洞夜景最有代表性的看点，空中横渡长江，排队1小时。攻略把它排进主线，时间留得最足。","notice":"空中横渡长江，排队1小时。这个点位上午光线最好。","durationMinutes":60,"addr":"渝中区新华路"},{"spotId":"S3","name":"山城步道","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"山城步道是洪崖洞夜景最有代表性的看点，第三步道悬空栈道看老重庆。攻略把它排进主线，时间留得最足。","notice":"第三步道悬空栈道看老重庆。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"渝中区中兴路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"重庆火锅（人均98元）","description":"渝中 · 洪崖洞夜景的招牌是重庆火锅，佩姐老火锅本地人都认这家，点单照攻略不踩雷。","addr":"解放碑"},{"title":"重庆小面（人均15元）","description":"渝中 · 洪崖洞夜景的招牌是重庆小面，花市豌杂面本地人都认这家，点单照攻略不踩雷。","addr":"民生路"},{"title":"酸辣粉（人均12元）","description":"渝中 · 洪崖洞夜景的招牌是酸辣粉，好又来酸辣粉本地人都认这家，点单照攻略不踩雷。","addr":"八一路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机","防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 渝中 的交通方便吗？","推荐先到 渝中，再打车或景区直通车前往核心景区；自驾导航直接搜洪崖洞夜景即可。"],["当地有什么必吃？","到了 渝中，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('赛里木湖纯攻略·美食清单4','guide','伊犁 · 赛里木湖','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,2,'赛里木湖 / 果子沟大桥 / 霍尔果斯口岸 —— 纯攻略助你玩透赛里木湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「赛里木湖」两日慢旅行——水景。伊犁薰衣草精油真香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 伊犁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴伊犁","description":"集合出发，大巴直达赛里木湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"赛里木湖","description":"抵达后首游赛里木湖，大西洋最后一滴眼泪，环湖骑行。","addr":"博乐市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐高白鲑（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"果子沟大桥","description":"早起人少，果子沟大桥精华时段，空中巨龙，观景台打卡。","addr":"霍城县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤包子，人均10元，补充体力。","addr":"果子沟","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"霍尔果斯口岸","description":"午后游览霍尔果斯口岸，中哈边境免税购物。","addr":"霍尔果斯市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"赛里木湖","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"赛里木湖是赛里木湖最有代表性的看点，大西洋最后一滴眼泪，环湖骑行。攻略把它排进主线，时间留得最足。","notice":"大西洋最后一滴眼泪，环湖骑行。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"博乐市"},{"spotId":"S2","name":"果子沟大桥","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"果子沟大桥是赛里木湖最有代表性的看点，空中巨龙，观景台打卡。攻略把它排进主线，时间留得最足。","notice":"空中巨龙，观景台打卡。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"霍城县"},{"spotId":"S3","name":"霍尔果斯口岸","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"霍尔果斯口岸是赛里木湖最有代表性的看点，中哈边境免税购物。攻略把它排进主线，时间留得最足。","notice":"中哈边境免税购物。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"霍尔果斯市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"高白鲑（人均88元）","description":"伊犁 · 赛里木湖的招牌是高白鲑，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"赛里木湖"},{"title":"烤包子（人均10元）","description":"伊犁 · 赛里木湖的招牌是烤包子，维族馕坑本地人都认这家，点单照攻略不踩雷。","addr":"果子沟"},{"title":"马奶酒（人均25元）","description":"伊犁 · 赛里木湖的招牌是马奶酒，牧民家本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","少量零食补给","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["到达 伊犁 的交通方便吗？","推荐先到 伊犁，再打车或景区直通车前往核心景区；自驾导航直接搜赛里木湖即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 伊犁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('长白山纯攻略·自由行手册4','guide','延边 · 长白山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',2990,1600,2,'天池北坡 / 长白瀑布 / 绿渊潭 —— 纯攻略助你玩透长白山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「长白山」三日深度游——山岳。长白山林下参滋补。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"吉林 · 延边"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往延边，抵达后办理入住、熟悉周边环境。","addr":"延边市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"天池北坡","description":"下午首站天池北坡，调整状态进入旅行节奏，长白山主峰天池，天气好才能见。","addr":"延边州安图县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游延边一带氛围拉满，晚餐朝鲜冷面人均22元。","addr":"二道白河镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"长白瀑布","description":"全天主景点长白瀑布，68米瀑布与温泉煮蛋。","addr":"北坡景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐石锅拌饭（人均28元），早点休息。","addr":"延吉市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"绿渊潭","description":"收官绿渊潭，碧绿水潭与飞瀑。","addr":"北坡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐温泉煮蛋后集合返程，三日旅程圆满。","addr":"北坡","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"天池北坡","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"天池北坡是长白山最有代表性的看点，长白山主峰天池，天气好才能见。攻略把它排进主线，时间留得最足。","notice":"长白山主峰天池，天气好才能见。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"延边州安图县"},{"spotId":"S2","name":"长白瀑布","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"长白瀑布是长白山最有代表性的看点，68米瀑布与温泉煮蛋。攻略把它排进主线，时间留得最足。","notice":"68米瀑布与温泉煮蛋。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"北坡景区"},{"spotId":"S3","name":"绿渊潭","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"绿渊潭是长白山最有代表性的看点，碧绿水潭与飞瀑。攻略把它排进主线，时间留得最足。","notice":"碧绿水潭与飞瀑。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"北坡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"朝鲜冷面（人均22元）","description":"延边 · 长白山的招牌是朝鲜冷面，服务大楼冷面本地人都认这家，点单照攻略不踩雷。","addr":"二道白河镇"},{"title":"石锅拌饭（人均28元）","description":"延边 · 长白山的招牌是石锅拌饭，金达莱餐厅本地人都认这家，点单照攻略不踩雷。","addr":"延吉市"},{"title":"温泉煮蛋（人均10元）","description":"延边 · 长白山的招牌是温泉煮蛋，瀑布温泉口本地人都认这家，点单照攻略不踩雷。","addr":"北坡"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","相机或运动相机","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('井冈山纯攻略·省钱玩法5','guide','吉安 · 井冈山','red','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',1990,1000,7,'黄洋界 / 茨坪革命旧址群 / 龙潭 —— 纯攻略助你玩透井冈山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「井冈山」两日慢旅行——人文。井冈山竹制工艺品轻便好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 吉安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴吉安","description":"集合出发，大巴直达井冈山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄洋界","description":"抵达后首游黄洋界，保卫战旧址，云海出现率高。","addr":"井冈山市黄洋界景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红米饭南瓜汤（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"茨坪革命旧址群","description":"早起人少，茨坪革命旧址群精华时段，旧址集中，步行串游。","addr":"井冈山市茨坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐井冈烟笋，人均38元，补充体力。","addr":"黄洋界山下餐馆","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙潭","description":"午后游览龙潭，五潭十八瀑，索道省力。","addr":"井冈山龙潭景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄洋界","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"黄洋界是井冈山最有代表性的看点，保卫战旧址，云海出现率高。攻略把它排进主线，时间留得最足。","notice":"保卫战旧址，云海出现率高。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"井冈山市黄洋界景区"},{"spotId":"S2","name":"茨坪革命旧址群","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"茨坪革命旧址群是井冈山最有代表性的看点，旧址集中，步行串游。攻略把它排进主线，时间留得最足。","notice":"旧址集中，步行串游。这个点位上午光线最好。","durationMinutes":150,"addr":"井冈山市茨坪镇"},{"spotId":"S3","name":"龙潭","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"龙潭是井冈山最有代表性的看点，五潭十八瀑，索道省力。攻略把它排进主线，时间留得最足。","notice":"五潭十八瀑，索道省力。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"井冈山龙潭景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红米饭南瓜汤（人均45元）","description":"吉安 · 井冈山的招牌是红米饭南瓜汤，老乡家常菜本地人都认这家，点单照攻略不踩雷。","addr":"茨坪天街"},{"title":"井冈烟笋（人均38元）","description":"吉安 · 井冈山的招牌是井冈烟笋，山上饭庄本地人都认这家，点单照攻略不踩雷。","addr":"黄洋界山下餐馆"},{"title":"石鸡炖汤（人均88元）","description":"吉安 · 井冈山的招牌是石鸡炖汤，龙潭农庄本地人都认这家，点单照攻略不踩雷。","addr":"龙潭景区入口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","少量零食补给","身份证件与手机充电宝","防晒霜与遮阳帽","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 吉安 的交通方便吗？","推荐先到 吉安，再打车或景区直通车前往核心景区；自驾导航直接搜井冈山即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大觉山纯攻略·避坑版5','guide','抚州 · 大觉山','adventure','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',990,500,9,'大觉山漂流 / 大觉岩寺 / 古镇影视城 —— 纯攻略助你玩透大觉山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大觉山」三日深度游——探险地。资溪面包是当地人的骄傲。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 抚州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往抚州，抵达后办理入住、熟悉周边环境。","addr":"抚州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大觉山漂流","description":"下午首站大觉山漂流，调整状态进入旅行节奏，华东第一漂，全程3.5公里带好换洗衣。","addr":"资溪县大觉山景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游抚州一带氛围拉满，晚餐资溪面包人均15元。","addr":"资溪县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大觉岩寺","description":"全天主景点大觉岩寺，悬崖上的古寺，索道直达。","addr":"大觉山主峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐笋干烧肉（人均48元），早点休息。","addr":"大觉山游客中心","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古镇影视城","description":"收官古镇影视城，仿宋古镇，拍照出片。","addr":"大觉山脚下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐发酵豆腐后集合返程，三日旅程圆满。","addr":"影视城内街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大觉山漂流","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"大觉山漂流是大觉山最有代表性的看点，华东第一漂，全程3.5公里带好换洗衣。攻略把它排进主线，时间留得最足。","notice":"华东第一漂，全程3.5公里带好换洗衣。这个点位上午光线最好。","durationMinutes":180,"addr":"资溪县大觉山景区"},{"spotId":"S2","name":"大觉岩寺","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"大觉岩寺是大觉山最有代表性的看点，悬崖上的古寺，索道直达。攻略把它排进主线，时间留得最足。","notice":"悬崖上的古寺，索道直达。这个点位上午光线最好。","durationMinutes":120,"addr":"大觉山主峰"},{"spotId":"S3","name":"古镇影视城","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"古镇影视城是大觉山最有代表性的看点，仿宋古镇，拍照出片。攻略把它排进主线，时间留得最足。","notice":"仿宋古镇，拍照出片。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"大觉山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"资溪面包（人均15元）","description":"抚州 · 大觉山的招牌是资溪面包，面包之乡旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"资溪县城"},{"title":"笋干烧肉（人均48元）","description":"抚州 · 大觉山的招牌是笋干烧肉，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"大觉山游客中心"},{"title":"发酵豆腐（人均18元）","description":"抚州 · 大觉山的招牌是发酵豆腐，古镇豆坊本地人都认这家，点单照攻略不踩雷。","addr":"影视城内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","少量零食补给","保温水杯与少量现金","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 抚州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳阳楼洞庭湖纯攻略·深度指南5','guide','岳阳 · 岳阳楼洞庭湖','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,2,'岳阳楼 / 君山岛 / 圣安寺 —— 纯攻略助你玩透岳阳楼洞庭湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「岳阳楼洞庭湖」两日慢旅行——水景。君山银针是十大名茶之一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 岳阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴岳阳","description":"集合出发，大巴直达岳阳楼洞庭湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"岳阳楼","description":"抵达后首游岳阳楼，洞庭天下水岳阳天下楼，背岳阳楼记免票。","addr":"岳阳市岳阳楼区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐洞庭鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"君山岛","description":"早起人少，君山岛精华时段，湘妃竹与银针茶的故乡。","addr":"洞庭湖君山岛","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐君山银针鸡片，人均68元，补充体力。","addr":"君山岛上","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"圣安寺","description":"午后游览圣安寺，古塔与湖景同框。","addr":"岳阳市南湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"岳阳楼","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"岳阳楼是岳阳楼洞庭湖最有代表性的看点，洞庭天下水岳阳天下楼，背岳阳楼记免票。攻略把它排进主线，时间留得最足。","notice":"洞庭天下水岳阳天下楼，背岳阳楼记免票。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"岳阳市岳阳楼区"},{"spotId":"S2","name":"君山岛","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"君山岛是岳阳楼洞庭湖最有代表性的看点，湘妃竹与银针茶的故乡。攻略把它排进主线，时间留得最足。","notice":"湘妃竹与银针茶的故乡。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"洞庭湖君山岛"},{"spotId":"S3","name":"圣安寺","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"圣安寺是岳阳楼洞庭湖最有代表性的看点，古塔与湖景同框。攻略把它排进主线，时间留得最足。","notice":"古塔与湖景同框。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"岳阳市南湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"洞庭鱼头（人均78元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是洞庭鱼头，巴陵全鱼席本地人都认这家，点单照攻略不踩雷。","addr":"岳阳楼景区旁"},{"title":"君山银针鸡片（人均68元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是君山银针鸡片，茶宴馆本地人都认这家，点单照攻略不踩雷。","addr":"君山岛上"},{"title":"岳阳虾饼（人均10元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是岳阳虾饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"汴河街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('元阳哈尼梯田纯攻略·周末版5','guide','红河 · 元阳哈尼梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',2500,1300,1,'多依树梯田 / 老虎嘴梯田 / 箐口哈尼民俗村 —— 纯攻略助你玩透元阳哈尼梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「元阳哈尼梯田」三日深度游——古村落。元阳红米营养丰富。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 红河"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往红河，抵达后办理入住、熟悉周边环境。","addr":"红河市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"多依树梯田","description":"下午首站多依树梯田，调整状态进入旅行节奏，日出云海最佳观赏点，提前1小时占位。","addr":"元阳县新街镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游红河一带氛围拉满，晚餐哈尼梯田红米人均35元。","addr":"多依树村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"老虎嘴梯田","description":"全天主景点老虎嘴梯田，日落时梯田变金色。","addr":"元阳县攀枝花乡","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐梯田鱼（人均58元），早点休息。","addr":"箐口村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"箐口哈尼民俗村","description":"收官箐口哈尼民俗村，蘑菇房与梯田同框。","addr":"元阳县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐竹筒鸡后集合返程，三日旅程圆满。","addr":"新街镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"多依树梯田","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"多依树梯田是元阳哈尼梯田最有代表性的看点，日出云海最佳观赏点，提前1小时占位。攻略把它排进主线，时间留得最足。","notice":"日出云海最佳观赏点，提前1小时占位。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"元阳县新街镇"},{"spotId":"S2","name":"老虎嘴梯田","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"老虎嘴梯田是元阳哈尼梯田最有代表性的看点，日落时梯田变金色。攻略把它排进主线，时间留得最足。","notice":"日落时梯田变金色。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"元阳县攀枝花乡"},{"spotId":"S3","name":"箐口哈尼民俗村","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"箐口哈尼民俗村是元阳哈尼梯田最有代表性的看点，蘑菇房与梯田同框。攻略把它排进主线，时间留得最足。","notice":"蘑菇房与梯田同框。这个点位上午光线最好。","durationMinutes":90,"addr":"元阳县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"哈尼梯田红米（人均35元）","description":"红河 · 元阳哈尼梯田的招牌是哈尼梯田红米，农家餐厅本地人都认这家，点单照攻略不踩雷。","addr":"多依树村"},{"title":"梯田鱼（人均58元）","description":"红河 · 元阳哈尼梯田的招牌是梯田鱼，村中渔家本地人都认这家，点单照攻略不踩雷。","addr":"箐口村"},{"title":"竹筒鸡（人均68元）","description":"红河 · 元阳哈尼梯田的招牌是竹筒鸡，哈尼农家本地人都认这家，点单照攻略不踩雷。","addr":"新街镇"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","墨镜与拍照道具","保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["几月份去 红河 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('四姑娘山纯攻略·亲子篇5','guide','阿坝 · 四姑娘山','mountain','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',990,500,2,'双桥沟 / 长坪沟 / 猫鼻梁 —— 纯攻略助你玩透四姑娘山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「四姑娘山」两日慢旅行——山岳。四姑娘山沙棘汁酸爽提神。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达四姑娘山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"双桥沟","description":"抵达后首游双桥沟，坐观光车看雪山峡谷，最省力。","addr":"四姑娘山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏式火锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"长坪沟","description":"早起人少，长坪沟精华时段，木栈道进山，幺妹峰侧面。","addr":"四姑娘山镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牦牛肉干，人均45元，补充体力。","addr":"镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"猫鼻梁","description":"午后游览猫鼻梁，四峰全景最佳机位。","addr":"去四姑娘山路途","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"双桥沟","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"双桥沟是四姑娘山最有代表性的看点，坐观光车看雪山峡谷，最省力。攻略把它排进主线，时间留得最足。","notice":"坐观光车看雪山峡谷，最省力。这个点位上午光线最好。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S2","name":"长坪沟","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"长坪沟是四姑娘山最有代表性的看点，木栈道进山，幺妹峰侧面。攻略把它排进主线，时间留得最足。","notice":"木栈道进山，幺妹峰侧面。这个点位上午光线最好。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S3","name":"猫鼻梁","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"猫鼻梁是四姑娘山最有代表性的看点，四峰全景最佳机位。攻略把它排进主线，时间留得最足。","notice":"四峰全景最佳机位。这个点位上午光线最好。","durationMinutes":30,"addr":"去四姑娘山路途"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏式火锅（人均78元）","description":"阿坝 · 四姑娘山的招牌是藏式火锅，日隆镇餐馆本地人都认这家，点单照攻略不踩雷。","addr":"四姑娘山镇"},{"title":"牦牛肉干（人均45元）","description":"阿坝 · 四姑娘山的招牌是牦牛肉干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"镇主街"},{"title":"酥油茶（人均15元）","description":"阿坝 · 四姑娘山的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"长坪沟口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","保温水杯与少量现金","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 阿坝 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 阿坝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌蒙大草原纯攻略·摄影机位5','guide','六盘水 · 乌蒙大草原','camp','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',2500,1300,10,'乌蒙大草原 / 野玉海 / 娘娘山 —— 纯攻略助你玩透乌蒙大草原精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「乌蒙大草原」三日深度游——露营地。六盘水刺梨维C之王。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 六盘水"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往六盘水，抵达后办理入住、熟悉周边环境。","addr":"六盘水市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"乌蒙大草原","description":"下午首站乌蒙大草原，调整状态进入旅行节奏，云上花海佛光，露营星空。","addr":"六盘水市盘州市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游六盘水一带氛围拉满，晚餐水城烙锅人均45元。","addr":"水城区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"野玉海","description":"全天主景点野玉海，海坪彝族小镇与观光小火车。","addr":"水城区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊肉粉（人均15元），早点休息。","addr":"盘州市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"娘娘山","description":"收官娘娘山，高原湿地与温泉。","addr":"盘州市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐刺梨汁后集合返程，三日旅程圆满。","addr":"全区通用","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"乌蒙大草原","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"乌蒙大草原是乌蒙大草原最有代表性的看点，云上花海佛光，露营星空。攻略把它排进主线，时间留得最足。","notice":"云上花海佛光，露营星空。这个点位上午光线最好。","durationMinutes":180,"addr":"六盘水市盘州市"},{"spotId":"S2","name":"野玉海","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"野玉海是乌蒙大草原最有代表性的看点，海坪彝族小镇与观光小火车。攻略把它排进主线，时间留得最足。","notice":"海坪彝族小镇与观光小火车。这个点位上午光线最好。","durationMinutes":150,"addr":"水城区"},{"spotId":"S3","name":"娘娘山","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"娘娘山是乌蒙大草原最有代表性的看点，高原湿地与温泉。攻略把它排进主线，时间留得最足。","notice":"高原湿地与温泉。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"盘州市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水城烙锅（人均45元）","description":"六盘水 · 乌蒙大草原的招牌是水城烙锅，烙锅一条街本地人都认这家，点单照攻略不踩雷。","addr":"水城区"},{"title":"羊肉粉（人均15元）","description":"六盘水 · 乌蒙大草原的招牌是羊肉粉，元坤羊肉粉本地人都认这家，点单照攻略不踩雷。","addr":"盘州市"},{"title":"刺梨汁（人均10元）","description":"六盘水 · 乌蒙大草原的招牌是刺梨汁，维C宝饮品本地人都认这家，点单照攻略不踩雷。","addr":"全区通用"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机","墨镜与拍照道具","保温水杯与少量现金","少量零食补给","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 六盘水 的交通方便吗？","推荐先到 六盘水，再打车或景区直通车前往核心景区；自驾导航直接搜乌蒙大草原即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武夷山纯攻略·美食清单5','guide','南平 · 武夷山','mountain','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1990,1000,2,'九曲溪竹筏 / 天游峰 / 大红袍景区 —— 纯攻略助你玩透武夷山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武夷山」两日慢旅行——山岳。正岩大红袍认准九龙窠。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 南平"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南平","description":"集合出发，大巴直达武夷山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"九曲溪竹筏","description":"抵达后首游九曲溪竹筏，90分钟漂流过九曲十八弯。","addr":"武夷山市星村镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐武夷山熏鹅（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天游峰","description":"早起人少，天游峰精华时段，闽山第一峰，云窝上看溪湾。","addr":"武夷山风景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐紫溪粉，人均15元，补充体力。","addr":"三姑街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大红袍景区","description":"午后游览大红袍景区，母树大红袍，岩谷花香步道。","addr":"武夷山九龙窠","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"九曲溪竹筏","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"九曲溪竹筏是武夷山最有代表性的看点，90分钟漂流过九曲十八弯。攻略把它排进主线，时间留得最足。","notice":"90分钟漂流过九曲十八弯。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"武夷山市星村镇"},{"spotId":"S2","name":"天游峰","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"天游峰是武夷山最有代表性的看点，闽山第一峰，云窝上看溪湾。攻略把它排进主线，时间留得最足。","notice":"闽山第一峰，云窝上看溪湾。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"武夷山风景区"},{"spotId":"S3","name":"大红袍景区","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"大红袍景区是武夷山最有代表性的看点，母树大红袍，岩谷花香步道。攻略把它排进主线，时间留得最足。","notice":"母树大红袍，岩谷花香步道。这个点位上午光线最好。","durationMinutes":90,"addr":"武夷山九龙窠"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"武夷山熏鹅（人均48元）","description":"南平 · 武夷山的招牌是武夷山熏鹅，岚谷熏鹅店本地人都认这家，点单照攻略不踩雷。","addr":"度假区"},{"title":"紫溪粉（人均15元）","description":"南平 · 武夷山的招牌是紫溪粉，小吃店本地人都认这家，点单照攻略不踩雷。","addr":"三姑街"},{"title":"文公菜（人均58元）","description":"南平 · 武夷山的招牌是文公菜，朱子家宴本地人都认这家，点单照攻略不踩雷。","addr":"武夷宫旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","舒适徒步鞋（防滑鞋底）","相机或运动相机","墨镜与拍照道具","轻便雨衣或折叠伞","身份证件与手机充电宝","保温水杯与少量现金","换洗衣物与外套（早晚温差）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('莫干山纯攻略·自由行手册5','guide','湖州 · 莫干山','village','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1200,600,1,'莫干山风景区 / 庾村文化市集 / 下渚湖湿地公园 —— 纯攻略助你玩透莫干山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「莫干山」三日深度游——古村落。莫干山黄芽茶清雅。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 湖州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往湖州，抵达后办理入住、熟悉周边环境。","addr":"湖州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫干山风景区","description":"下午首站莫干山风景区，调整状态进入旅行节奏，民国别墅群与竹海，剑池飞瀑。","addr":"湖州市德清县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游湖州一带氛围拉满，晚餐笋干烧肉人均58元。","addr":"莫干山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"庾村文化市集","description":"全天主景点庾村文化市集，文创小铺与骑行路线。","addr":"德清县莫干山镇","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐竹林土鸡煲（人均88元），早点休息。","addr":"劳岭村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"下渚湖湿地公园","description":"收官下渚湖湿地公园，朱鹮栖息地，芦苇迷宫。","addr":"德清县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐德清醉鱼后集合返程，三日旅程圆满。","addr":"下渚湖","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫干山风景区","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"莫干山风景区是莫干山最有代表性的看点，民国别墅群与竹海，剑池飞瀑。攻略把它排进主线，时间留得最足。","notice":"民国别墅群与竹海，剑池飞瀑。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"湖州市德清县"},{"spotId":"S2","name":"庾村文化市集","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"庾村文化市集是莫干山最有代表性的看点，文创小铺与骑行路线。攻略把它排进主线，时间留得最足。","notice":"文创小铺与骑行路线。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"德清县莫干山镇"},{"spotId":"S3","name":"下渚湖湿地公园","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"下渚湖湿地公园是莫干山最有代表性的看点，朱鹮栖息地，芦苇迷宫。攻略把它排进主线，时间留得最足。","notice":"朱鹮栖息地，芦苇迷宫。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"德清县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"笋干烧肉（人均58元）","description":"湖州 · 莫干山的招牌是笋干烧肉，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"莫干山镇"},{"title":"竹林土鸡煲（人均88元）","description":"湖州 · 莫干山的招牌是竹林土鸡煲，民宿餐厅本地人都认这家，点单照攻略不踩雷。","addr":"劳岭村"},{"title":"德清醉鱼（人均38元）","description":"湖州 · 莫干山的招牌是德清醉鱼，水产馆本地人都认这家，点单照攻略不踩雷。","addr":"下渚湖"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机","保温水杯与少量现金","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九华山纯攻略·省钱玩法5','guide','池州 · 九华山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,2,'肉身宝殿 / 百岁宫 / 花台栈道 —— 纯攻略助你玩透九华山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九华山」两日慢旅行——山岳。九华黄精是养生佳品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 池州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴池州","description":"集合出发，大巴直达九华山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"肉身宝殿","description":"抵达后首游肉身宝殿，地藏菩萨道场核心，99米地藏圣像。","addr":"池州市青阳县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐九华素斋（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"百岁宫","description":"早起人少，百岁宫精华时段，缆车直达，天然肉身佛。","addr":"九华街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐石耳炖鸡，人均78元，补充体力。","addr":"柯村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"花台栈道","description":"午后游览花台栈道，云海佛光频出。","addr":"九华山高空栈道","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"肉身宝殿","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"肉身宝殿是九华山最有代表性的看点，地藏菩萨道场核心，99米地藏圣像。攻略把它排进主线，时间留得最足。","notice":"地藏菩萨道场核心，99米地藏圣像。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"池州市青阳县"},{"spotId":"S2","name":"百岁宫","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"百岁宫是九华山最有代表性的看点，缆车直达，天然肉身佛。攻略把它排进主线，时间留得最足。","notice":"缆车直达，天然肉身佛。这个点位上午光线最好。","durationMinutes":90,"addr":"九华街"},{"spotId":"S3","name":"花台栈道","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"花台栈道是九华山最有代表性的看点，云海佛光频出。攻略把它排进主线，时间留得最足。","notice":"云海佛光频出。这个点位上午光线最好。","durationMinutes":120,"addr":"九华山高空栈道"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"九华素斋（人均38元）","description":"池州 · 九华山的招牌是九华素斋，化城寺素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"九华街"},{"title":"石耳炖鸡（人均78元）","description":"池州 · 九华山的招牌是石耳炖鸡，山间农家本地人都认这家，点单照攻略不踩雷。","addr":"柯村"},{"title":"黄精茶（人均30元）","description":"池州 · 九华山的招牌是黄精茶，特产店本地人都认这家，点单照攻略不踩雷。","addr":"九华新街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","相机或运动相机","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云台山纯攻略·避坑版5','guide','焦作 · 云台山','water','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1990,1000,2,'红石峡 / 茱萸峰 / 潭瀑峡 —— 纯攻略助你玩透云台山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「云台山」三日深度游——水景。铁棍山药焦作温县最好。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 焦作"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往焦作，抵达后办理入住、熟悉周边环境。","addr":"焦作市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"红石峡","description":"下午首站红石峡，调整状态进入旅行节奏，红岩碧水盆景峡谷，人再多也值。","addr":"焦作市修武县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游焦作一带氛围拉满，晚餐驴肉面人均28元。","addr":"云台山岸上镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"茱萸峰","description":"全天主景点茱萸峰，王维遥知兄弟登高处。","addr":"云台山主峰","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐山药炖排骨（人均58元），早点休息。","addr":"修武县城","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"潭瀑峡","description":"收官潭瀑峡，三步一泉五步一瀑。","addr":"云台山","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐松花蛋后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"红石峡","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"红石峡是云台山最有代表性的看点，红岩碧水盆景峡谷，人再多也值。攻略把它排进主线，时间留得最足。","notice":"红岩碧水盆景峡谷，人再多也值。这个点位上午光线最好。","durationMinutes":180,"addr":"焦作市修武县"},{"spotId":"S2","name":"茱萸峰","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"茱萸峰是云台山最有代表性的看点，王维遥知兄弟登高处。攻略把它排进主线，时间留得最足。","notice":"王维遥知兄弟登高处。这个点位上午光线最好。","durationMinutes":180,"addr":"云台山主峰"},{"spotId":"S3","name":"潭瀑峡","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"潭瀑峡是云台山最有代表性的看点，三步一泉五步一瀑。攻略把它排进主线，时间留得最足。","notice":"三步一泉五步一瀑。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"云台山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉面（人均28元）","description":"焦作 · 云台山的招牌是驴肉面，修武驴肉馆本地人都认这家，点单照攻略不踩雷。","addr":"云台山岸上镇"},{"title":"山药炖排骨（人均58元）","description":"焦作 · 云台山的招牌是山药炖排骨，怀山药宴本地人都认这家，点单照攻略不踩雷。","addr":"修武县城"},{"title":"松花蛋（人均20元）","description":"焦作 · 云台山的招牌是松花蛋，特产店本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","常用药品（肠胃药/创可贴）","墨镜与拍照道具","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五台山纯攻略·深度指南5','guide','忻州 · 五台山','mountain','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',990,500,2,'五爷庙 / 黛螺顶 / 显通寺 —— 纯攻略助你玩透五台山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「五台山」两日慢旅行——山岳。五台山台蘑干货珍贵。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 忻州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴忻州","description":"集合出发，大巴直达五台山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"五爷庙","description":"抵达后首游五爷庙，香火最旺许愿灵验，早去。","addr":"忻州市五台县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐台蘑炖山鸡（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"黛螺顶","description":"早起人少，黛螺顶精华时段，小朝台1080级台阶。","addr":"五台山台怀镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐莜面窝窝，人均22元，补充体力。","addr":"五台山镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"显通寺","description":"午后游览显通寺，五台山开山寺，铜殿铜塔。","addr":"台怀镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"五爷庙","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"五爷庙是五台山最有代表性的看点，香火最旺许愿灵验，早去。攻略把它排进主线，时间留得最足。","notice":"香火最旺许愿灵验，早去。这个点位上午光线最好。","durationMinutes":90,"addr":"忻州市五台县"},{"spotId":"S2","name":"黛螺顶","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"黛螺顶是五台山最有代表性的看点，小朝台1080级台阶。攻略把它排进主线，时间留得最足。","notice":"小朝台1080级台阶。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"五台山台怀镇"},{"spotId":"S3","name":"显通寺","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"显通寺是五台山最有代表性的看点，五台山开山寺，铜殿铜塔。攻略把它排进主线，时间留得最足。","notice":"五台山开山寺，铜殿铜塔。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"台怀镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"台蘑炖山鸡（人均88元）","description":"忻州 · 五台山的招牌是台蘑炖山鸡，山珍馆本地人都认这家，点单照攻略不踩雷。","addr":"台怀镇"},{"title":"莜面窝窝（人均22元）","description":"忻州 · 五台山的招牌是莜面窝窝，农家菜本地人都认这家，点单照攻略不踩雷。","addr":"五台山镇"},{"title":"素斋（人均28元）","description":"忻州 · 五台山的招牌是素斋，塔院寺素斋本地人都认这家，点单照攻略不踩雷。","addr":"塔院寺旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","少量零食补给","防晒霜与遮阳帽","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["几月份去 忻州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙面陈家祠纯攻略·周末版5','guide','广州 · 沙面陈家祠','food','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',2500,1300,3,'陈家祠 / 沙面岛 / 永庆坊 —— 纯攻略助你玩透沙面陈家祠精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「沙面陈家祠」三日深度游——美食。广式腊味礼盒最体面。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 广州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往广州，抵达后办理入住、熟悉周边环境。","addr":"广州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"陈家祠","description":"下午首站陈家祠，调整状态进入旅行节奏，岭南建筑木雕巅峰。","addr":"广州市荔湾区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游广州一带氛围拉满，晚餐肠粉人均15元。","addr":"上九路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"沙面岛","description":"全天主景点沙面岛，欧陆建筑群，拍照圣地。","addr":"荔湾区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐虾饺（人均28元），早点休息。","addr":"第十甫路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"永庆坊","description":"收官永庆坊，西关骑楼与粤剧艺术博物馆。","addr":"恩宁路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐双皮奶后集合返程，三日旅程圆满。","addr":"第十甫路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"陈家祠","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"陈家祠是沙面陈家祠最有代表性的看点，岭南建筑木雕巅峰。攻略把它排进主线，时间留得最足。","notice":"岭南建筑木雕巅峰。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"广州市荔湾区"},{"spotId":"S2","name":"沙面岛","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"沙面岛是沙面陈家祠最有代表性的看点，欧陆建筑群，拍照圣地。攻略把它排进主线，时间留得最足。","notice":"欧陆建筑群，拍照圣地。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"荔湾区"},{"spotId":"S3","name":"永庆坊","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"永庆坊是沙面陈家祠最有代表性的看点，西关骑楼与粤剧艺术博物馆。攻略把它排进主线，时间留得最足。","notice":"西关骑楼与粤剧艺术博物馆。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"恩宁路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肠粉（人均15元）","description":"广州 · 沙面陈家祠的招牌是肠粉，银记肠粉本地人都认这家，点单照攻略不踩雷。","addr":"上九路"},{"title":"虾饺（人均28元）","description":"广州 · 沙面陈家祠的招牌是虾饺，陶陶居本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"},{"title":"双皮奶（人均15元）","description":"广州 · 沙面陈家祠的招牌是双皮奶，南信牛奶甜品本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","少量零食补给","相机或运动相机","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 广州 的交通方便吗？","推荐先到 广州，再打车或景区直通车前往核心景区；自驾导航直接搜沙面陈家祠即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武隆天坑纯攻略·亲子篇5','guide','武隆 · 武隆天坑','adventure','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,9,'天生三桥 / 仙女山 / 龙水峡地缝 —— 纯攻略助你玩透武隆天坑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武隆天坑」两日慢旅行——探险地。武隆羊角豆干麻辣够味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 武隆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴武隆","description":"集合出发，大巴直达武隆天坑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"天生三桥","description":"抵达后首游天生三桥，变形金刚取景地，天福官驿。","addr":"武隆区仙女山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐碗碗羊肉（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"仙女山","description":"早起人少，仙女山精华时段，南国第一牧原，草原骑马。","addr":"武隆区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐江口鱼，人均58元，补充体力。","addr":"江口镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙水峡地缝","description":"午后游览龙水峡地缝，80米深地缝一线天光。","addr":"仙女山镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"天生三桥","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"天生三桥是武隆天坑最有代表性的看点，变形金刚取景地，天福官驿。攻略把它排进主线，时间留得最足。","notice":"变形金刚取景地，天福官驿。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"武隆区仙女山镇"},{"spotId":"S2","name":"仙女山","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"仙女山是武隆天坑最有代表性的看点，南国第一牧原，草原骑马。攻略把它排进主线，时间留得最足。","notice":"南国第一牧原，草原骑马。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"武隆区"},{"spotId":"S3","name":"龙水峡地缝","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"龙水峡地缝是武隆天坑最有代表性的看点，80米深地缝一线天光。攻略把它排进主线，时间留得最足。","notice":"80米深地缝一线天光。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"仙女山镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"碗碗羊肉（人均38元）","description":"武隆 · 武隆天坑的招牌是碗碗羊肉，武隆碗碗羊肉本地人都认这家，点单照攻略不踩雷。","addr":"仙女山镇"},{"title":"江口鱼（人均58元）","description":"武隆 · 武隆天坑的招牌是江口鱼，乌江鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"江口镇"},{"title":"羊角豆干（人均15元）","description":"武隆 · 武隆天坑的招牌是羊角豆干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"武隆城区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","少量零食补给","防晒霜与遮阳帽","身份证件与手机充电宝","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 武隆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('天山天池纯攻略·摄影机位5','guide','昌吉 · 天山天池','mountain','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',990,500,2,'天山天池 / 马牙山 / 西小天池 —— 纯攻略助你玩透天山天池精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「天山天池」三日深度游——山岳。天山雪莲泡酒有讲究。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 昌吉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往昌吉，抵达后办理入住、熟悉周边环境。","addr":"昌吉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"天山天池","description":"下午首站天山天池，调整状态进入旅行节奏，博格达峰雪影与瑶池传说。","addr":"阜康市","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游昌吉一带氛围拉满，晚餐新疆大盘鸡人均68元。","addr":"阜康市","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"马牙山","description":"全天主景点马牙山，石林与云海，索道直达。","addr":"天池西侧","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐馕坑肉（人均25元），早点休息。","addr":"天池镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"西小天池","description":"收官西小天池，飞龙潭瀑布。","addr":"天池盘山路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐酸奶粽子后集合返程，三日旅程圆满。","addr":"阜康夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"天山天池","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"天山天池是天山天池最有代表性的看点，博格达峰雪影与瑶池传说。攻略把它排进主线，时间留得最足。","notice":"博格达峰雪影与瑶池传说。这个点位上午光线最好。","durationMinutes":240,"addr":"阜康市"},{"spotId":"S2","name":"马牙山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"马牙山是天山天池最有代表性的看点，石林与云海，索道直达。攻略把它排进主线，时间留得最足。","notice":"石林与云海，索道直达。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"天池西侧"},{"spotId":"S3","name":"西小天池","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"西小天池是天山天池最有代表性的看点，飞龙潭瀑布。攻略把它排进主线，时间留得最足。","notice":"飞龙潭瀑布。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"天池盘山路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新疆大盘鸡（人均68元）","description":"昌吉 · 天山天池的招牌是新疆大盘鸡，血站大盘鸡本地人都认这家，点单照攻略不踩雷。","addr":"阜康市"},{"title":"馕坑肉（人均25元）","description":"昌吉 · 天山天池的招牌是馕坑肉，馕王本地人都认这家，点单照攻略不踩雷。","addr":"天池镇"},{"title":"酸奶粽子（人均12元）","description":"昌吉 · 天山天池的招牌是酸奶粽子，夜市甜品本地人都认这家，点单照攻略不踩雷。","addr":"阜康夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 昌吉，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('八达岭长城纯攻略·美食清单5','guide','延庆 · 八达岭长城','red','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',990,500,7,'八达岭长城 / 明十三陵 / 居庸关花海 —— 纯攻略助你玩透八达岭长城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「八达岭长城」两日慢旅行——人文。北京果脯礼盒送长辈。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"北京 · 延庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延庆","description":"集合出发，大巴直达八达岭长城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"八达岭长城","description":"抵达后首游八达岭长城，好汉坡北八楼，缆车上下。","addr":"延庆区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐春饼宴（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"明十三陵","description":"早起人少，明十三陵精华时段，定陵地宫探秘。","addr":"昌平区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐火盆锅豆腐宴，人均48元，补充体力。","addr":"八达岭镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"居庸关花海","description":"午后游览居庸关花海，开往春天的列车。","addr":"昌平区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"八达岭长城","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"八达岭长城是八达岭长城最有代表性的看点，好汉坡北八楼，缆车上下。攻略把它排进主线，时间留得最足。","notice":"好汉坡北八楼，缆车上下。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"延庆区"},{"spotId":"S2","name":"明十三陵","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"明十三陵是八达岭长城最有代表性的看点，定陵地宫探秘。攻略把它排进主线，时间留得最足。","notice":"定陵地宫探秘。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"昌平区"},{"spotId":"S3","name":"居庸关花海","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"居庸关花海是八达岭长城最有代表性的看点，开往春天的列车。攻略把它排进主线，时间留得最足。","notice":"开往春天的列车。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"昌平区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"春饼宴（人均38元）","description":"延庆 · 八达岭长城的招牌是春饼宴，柳沟村豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"延庆柳沟"},{"title":"火盆锅豆腐宴（人均48元）","description":"延庆 · 八达岭长城的招牌是火盆锅豆腐宴，农家院本地人都认这家，点单照攻略不踩雷。","addr":"八达岭镇"},{"title":"玫瑰饼（人均15元）","description":"延庆 · 八达岭长城的招牌是玫瑰饼，妙峰山糕点本地人都认这家，点单照攻略不踩雷。","addr":"昌平"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 延庆 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('庐山纯攻略·自由行手册5','guide','九江 · 庐山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',990,500,2,'锦绣谷 / 三叠泉 / 如琴湖花径 —— 纯攻略助你玩透庐山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「庐山」三日深度游——山岳。庐山云雾茶记得认准原产地标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 九江"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往九江，抵达后办理入住、熟悉周边环境。","addr":"九江市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"锦绣谷","description":"下午首站锦绣谷，调整状态进入旅行节奏，云雾多发地段，下午常被云海包裹。","addr":"庐山风景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游九江一带氛围拉满，晚餐庐山三石宴人均128元。","addr":"牯岭镇河西路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"三叠泉","description":"全天主景点三叠泉，不到三叠泉不算庐山客，往返台阶多。","addr":"庐山东南麓","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐茶饼（人均12元），早点休息。","addr":"牯岭镇正街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"如琴湖花径","description":"收官如琴湖花径，清晨人少出片，环湖半小时。","addr":"牯岭镇西侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐石耳炖鸡汤后集合返程，三日旅程圆满。","addr":"如琴湖旁农家","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"锦绣谷","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"锦绣谷是庐山最有代表性的看点，云雾多发地段，下午常被云海包裹。攻略把它排进主线，时间留得最足。","notice":"云雾多发地段，下午常被云海包裹。这个点位上午光线最好。","durationMinutes":120,"addr":"庐山风景区"},{"spotId":"S2","name":"三叠泉","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"三叠泉是庐山最有代表性的看点，不到三叠泉不算庐山客，往返台阶多。攻略把它排进主线，时间留得最足。","notice":"不到三叠泉不算庐山客，往返台阶多。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"庐山东南麓"},{"spotId":"S3","name":"如琴湖花径","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"如琴湖花径是庐山最有代表性的看点，清晨人少出片，环湖半小时。攻略把它排进主线，时间留得最足。","notice":"清晨人少出片，环湖半小时。这个点位上午光线最好。","durationMinutes":60,"addr":"牯岭镇西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"庐山三石宴（人均128元）","description":"九江 · 庐山的招牌是庐山三石宴，牯岭镇饭馆本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇河西路"},{"title":"茶饼（人均12元）","description":"九江 · 庐山的招牌是茶饼，云中街区小店本地人都认这家，点单照攻略不踩雷。","addr":"牯岭镇正街"},{"title":"石耳炖鸡汤（人均98元）","description":"九江 · 庐山的招牌是石耳炖鸡汤，山中食府本地人都认这家，点单照攻略不踩雷。","addr":"如琴湖旁农家"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","相机或运动相机","保温水杯与少量现金","少量零食补给","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 九江 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 九江，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('通天岩郁孤台纯攻略·省钱玩法5','guide','赣州 · 通天岩郁孤台','red','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',990,500,7,'通天岩 / 郁孤台 / 关西新围 —— 纯攻略助你玩透通天岩郁孤台精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「通天岩郁孤台」两日慢旅行——人文。赣南脐橙11月最甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 赣州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴赣州","description":"集合出发，大巴直达通天岩郁孤台，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"通天岩","description":"抵达后首游通天岩，江南最大石窟群，丹岩丹霞。","addr":"赣州市章贡区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐赣南小炒鱼（人均42元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"郁孤台","description":"早起人少，郁孤台精华时段，辛弃疾词中圣地，宋城墙。","addr":"章贡区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐艾米果，人均10元，补充体力。","addr":"郁孤台街区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"关西新围","description":"午后游览关西新围，东方古堡围屋。","addr":"龙南市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"通天岩","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"通天岩是通天岩郁孤台最有代表性的看点，江南最大石窟群，丹岩丹霞。攻略把它排进主线，时间留得最足。","notice":"江南最大石窟群，丹岩丹霞。这个点位上午光线最好。","durationMinutes":150,"addr":"赣州市章贡区"},{"spotId":"S2","name":"郁孤台","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"郁孤台是通天岩郁孤台最有代表性的看点，辛弃疾词中圣地，宋城墙。攻略把它排进主线，时间留得最足。","notice":"辛弃疾词中圣地，宋城墙。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"章贡区"},{"spotId":"S3","name":"关西新围","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"关西新围是通天岩郁孤台最有代表性的看点，东方古堡围屋。攻略把它排进主线，时间留得最足。","notice":"东方古堡围屋。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙南市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"赣南小炒鱼（人均42元）","description":"赣州 · 通天岩郁孤台的招牌是赣南小炒鱼，赣州客家菜本地人都认这家，点单照攻略不踩雷。","addr":"章贡区"},{"title":"艾米果（人均10元）","description":"赣州 · 通天岩郁孤台的招牌是艾米果，街头点心本地人都认这家，点单照攻略不踩雷。","addr":"郁孤台街区"},{"title":"黄元米果（人均18元）","description":"赣州 · 通天岩郁孤台的招牌是黄元米果，赣南农家本地人都认这家，点单照攻略不踩雷。","addr":"龙南市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","轻便雨衣或折叠伞","身份证件与手机充电宝","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","相机或运动相机","常用药品（肠胃药/创可贴）","少量零食补给"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["当地有什么必吃？","到了 赣州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('桃花源纯攻略·避坑版5','guide','常德 · 桃花源','village','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',1990,1000,1,'桃花源古镇 / 桃源山 / 五柳湖 —— 纯攻略助你玩透桃花源精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「桃花源」三日深度游——古村落。桃源大叶茶配擂茶绝了。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 常德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往常德，抵达后办理入住、熟悉周边环境。","addr":"常德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"桃花源古镇","description":"下午首站桃花源古镇，调整状态进入旅行节奏，秦溪秦谷还原桃花源记场景。","addr":"常德市桃源县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游常德一带氛围拉满，晚餐常德米粉人均18元。","addr":"桃源县漳江镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"桃源山","description":"全天主景点桃源山，水府阁俯瞰沅江。","addr":"桃花源景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐擂茶（人均35元），早点休息。","addr":"桃花源古镇内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"五柳湖","description":"收官五柳湖，落英缤纷打卡点。","addr":"桃花源核心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桃源鸡后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"桃花源古镇","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"桃花源古镇是桃花源最有代表性的看点，秦溪秦谷还原桃花源记场景。攻略把它排进主线，时间留得最足。","notice":"秦溪秦谷还原桃花源记场景。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"常德市桃源县"},{"spotId":"S2","name":"桃源山","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"桃源山是桃花源最有代表性的看点，水府阁俯瞰沅江。攻略把它排进主线，时间留得最足。","notice":"水府阁俯瞰沅江。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"桃花源景区"},{"spotId":"S3","name":"五柳湖","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"五柳湖是桃花源最有代表性的看点，落英缤纷打卡点。攻略把它排进主线，时间留得最足。","notice":"落英缤纷打卡点。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"桃花源核心区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"常德米粉（人均18元）","description":"常德 · 桃花源的招牌是常德米粉，刘聋子粉馆本地人都认这家，点单照攻略不踩雷。","addr":"桃源县漳江镇"},{"title":"擂茶（人均35元）","description":"常德 · 桃花源的招牌是擂茶，秦溪擂茶馆本地人都认这家，点单照攻略不踩雷。","addr":"桃花源古镇内"},{"title":"桃源鸡（人均68元）","description":"常德 · 桃花源的招牌是桃源鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","保温水杯与少量现金","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","相机或运动相机","舒适徒步鞋（防滑鞋底）","少量零食补给","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 常德 的交通方便吗？","推荐先到 常德，再打车或景区直通车前往核心景区；自驾导航直接搜桃花源即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 常德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('普者黑纯攻略·深度指南5','guide','文山 · 普者黑','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',2500,1300,2,'青龙山 / 天鹅湖 / 仙人洞村 —— 纯攻略助你玩透普者黑精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「普者黑」两日慢旅行——水景。丘北辣椒香而不辣。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 文山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴文山","description":"集合出发，大巴直达普者黑，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"青龙山","description":"抵达后首游青龙山，登顶看万亩荷塘全景。","addr":"丘北县普者黑村","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐醉虾（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天鹅湖","description":"早起人少，天鹅湖精华时段，候鸟与荷塘，乘船打水仗。","addr":"普者黑景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐荷叶宴，人均68元，补充体力。","addr":"天鹅湖边","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"仙人洞村","description":"午后游览仙人洞村，撒尼人村落，民宿夜色美。","addr":"普者黑湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"青龙山","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"青龙山是普者黑最有代表性的看点，登顶看万亩荷塘全景。攻略把它排进主线，时间留得最足。","notice":"登顶看万亩荷塘全景。这个点位上午光线最好。","durationMinutes":90,"addr":"丘北县普者黑村"},{"spotId":"S2","name":"天鹅湖","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"天鹅湖是普者黑最有代表性的看点，候鸟与荷塘，乘船打水仗。攻略把它排进主线，时间留得最足。","notice":"候鸟与荷塘，乘船打水仗。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"普者黑景区"},{"spotId":"S3","name":"仙人洞村","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"仙人洞村是普者黑最有代表性的看点，撒尼人村落，民宿夜色美。攻略把它排进主线，时间留得最足。","notice":"撒尼人村落，民宿夜色美。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"普者黑湖畔"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"醉虾（人均48元）","description":"文山 · 普者黑的招牌是醉虾，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"普者黑村"},{"title":"荷叶宴（人均68元）","description":"文山 · 普者黑的招牌是荷叶宴，荷香餐厅本地人都认这家，点单照攻略不踩雷。","addr":"天鹅湖边"},{"title":"丘北辣椒鸡（人均58元）","description":"文山 · 普者黑的招牌是丘北辣椒鸡，辣椒主题馆本地人都认这家，点单照攻略不踩雷。","addr":"丘北县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","保温水杯与少量现金","常用药品（肠胃药/创可贴）","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["几月份去 文山 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('蜀南竹海纯攻略·周末版5','guide','宜宾 · 蜀南竹海','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1500,800,1,'蜀南竹海 / 李庄古镇 / 兴文石海 —— 纯攻略助你玩透蜀南竹海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「蜀南竹海」三日深度游——古村落。竹荪竹笋干货轻便。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 宜宾"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜宾，抵达后办理入住、熟悉周边环境。","addr":"宜宾市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜀南竹海","description":"下午首站蜀南竹海，调整状态进入旅行节奏，忘忧谷翡翠长廊，竹林深处人家。","addr":"宜宾市长宁县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜宾一带氛围拉满，晚餐全竹宴人均68元。","addr":"蜀南竹海","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"李庄古镇","description":"全天主景点李庄古镇，万里长江第一古镇，抗战文化。","addr":"翠屏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐李庄白肉（人均42元），早点休息。","addr":"李庄古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"兴文石海","description":"收官兴文石海，天坑石林与僰人文化。","addr":"兴文县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐燃面后集合返程，三日旅程圆满。","addr":"宜宾市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜀南竹海","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"蜀南竹海是蜀南竹海最有代表性的看点，忘忧谷翡翠长廊，竹林深处人家。攻略把它排进主线，时间留得最足。","notice":"忘忧谷翡翠长廊，竹林深处人家。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"宜宾市长宁县"},{"spotId":"S2","name":"李庄古镇","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"李庄古镇是蜀南竹海最有代表性的看点，万里长江第一古镇，抗战文化。攻略把它排进主线，时间留得最足。","notice":"万里长江第一古镇，抗战文化。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"翠屏区"},{"spotId":"S3","name":"兴文石海","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"兴文石海是蜀南竹海最有代表性的看点，天坑石林与僰人文化。攻略把它排进主线，时间留得最足。","notice":"天坑石林与僰人文化。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"兴文县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"全竹宴（人均68元）","description":"宜宾 · 蜀南竹海的招牌是全竹宴，竹海人家本地人都认这家，点单照攻略不踩雷。","addr":"蜀南竹海"},{"title":"李庄白肉（人均42元）","description":"宜宾 · 蜀南竹海的招牌是李庄白肉，李庄老店本地人都认这家，点单照攻略不踩雷。","addr":"李庄古镇"},{"title":"燃面（人均12元）","description":"宜宾 · 蜀南竹海的招牌是燃面，刘臣街燃面本地人都认这家，点单照攻略不踩雷。","addr":"宜宾市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["当地有什么必吃？","到了 宜宾，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 宜宾 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阳朔漓江纯攻略·亲子篇5','guide','桂林 · 阳朔漓江','water','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',990,500,2,'兴坪漓江 / 遇龙河 / 西街 —— 纯攻略助你玩透阳朔漓江精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「阳朔漓江」两日慢旅行——水景。阳朔金桔个大超甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴桂林","description":"集合出发，大巴直达阳朔漓江，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"兴坪漓江","description":"抵达后首游兴坪漓江，20元人民币背景，老寨山看全景。","addr":"阳朔县兴坪镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐啤酒鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"遇龙河","description":"早起人少，遇龙河精华时段，竹筏漂流，工农桥日落。","addr":"阳朔县遇龙河","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐桂林米粉，人均12元，补充体力。","addr":"兴坪老街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"西街","description":"午后游览西街，老外扎堆的千年老街。","addr":"阳朔县西街","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"兴坪漓江","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"兴坪漓江是阳朔漓江最有代表性的看点，20元人民币背景，老寨山看全景。攻略把它排进主线，时间留得最足。","notice":"20元人民币背景，老寨山看全景。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"阳朔县兴坪镇"},{"spotId":"S2","name":"遇龙河","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"遇龙河是阳朔漓江最有代表性的看点，竹筏漂流，工农桥日落。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流，工农桥日落。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"阳朔县遇龙河"},{"spotId":"S3","name":"西街","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"西街是阳朔漓江最有代表性的看点，老外扎堆的千年老街。攻略把它排进主线，时间留得最足。","notice":"老外扎堆的千年老街。这个点位上午光线最好。","durationMinutes":120,"addr":"阳朔县西街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"啤酒鱼（人均68元）","description":"桂林 · 阳朔漓江的招牌是啤酒鱼，谢大姐啤酒鱼本地人都认这家，点单照攻略不踩雷。","addr":"西街口"},{"title":"桂林米粉（人均12元）","description":"桂林 · 阳朔漓江的招牌是桂林米粉，崇善米粉本地人都认这家，点单照攻略不踩雷。","addr":"兴坪老街"},{"title":"田螺酿（人均38元）","description":"桂林 · 阳朔漓江的招牌是田螺酿，阳朔农家本地人都认这家，点单照攻略不踩雷。","addr":"遇龙河边"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","相机或运动相机","防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","保温水杯与少量现金","常用药品（肠胃药/创可贴）","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南靖土楼纯攻略·摄影机位5','guide','漳州 · 南靖土楼','village','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',990,500,1,'田螺坑土楼群 / 裕昌楼 / 云水谣古镇 —— 纯攻略助你玩透南靖土楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「南靖土楼」三日深度游——古村落。土楼红茶岩韵悠长。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 漳州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往漳州，抵达后办理入住、熟悉周边环境。","addr":"漳州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"田螺坑土楼群","description":"下午首站田螺坑土楼群，调整状态进入旅行节奏，四菜一汤观景台，夜景更美。","addr":"南靖县书洋镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游漳州一带氛围拉满，晚餐土楼农家菜人均48元。","addr":"田螺坑下观景台","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"裕昌楼","description":"全天主景点裕昌楼，700年东歪西斜奇楼。","addr":"南靖县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐梅菜扣肉（人均42元），早点休息。","addr":"云水谣古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"云水谣古镇","description":"收官云水谣古镇，千年榕树与水车，电影取景地。","addr":"南靖县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糍粑后集合返程，三日旅程圆满。","addr":"裕昌楼前","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"田螺坑土楼群","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"田螺坑土楼群是南靖土楼最有代表性的看点，四菜一汤观景台，夜景更美。攻略把它排进主线，时间留得最足。","notice":"四菜一汤观景台，夜景更美。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"南靖县书洋镇"},{"spotId":"S2","name":"裕昌楼","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"裕昌楼是南靖土楼最有代表性的看点，700年东歪西斜奇楼。攻略把它排进主线，时间留得最足。","notice":"700年东歪西斜奇楼。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"南靖县"},{"spotId":"S3","name":"云水谣古镇","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"云水谣古镇是南靖土楼最有代表性的看点，千年榕树与水车，电影取景地。攻略把它排进主线，时间留得最足。","notice":"千年榕树与水车，电影取景地。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"南靖县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土楼农家菜（人均48元）","description":"漳州 · 南靖土楼的招牌是土楼农家菜，客家土菜馆本地人都认这家，点单照攻略不踩雷。","addr":"田螺坑下观景台"},{"title":"梅菜扣肉（人均42元）","description":"漳州 · 南靖土楼的招牌是梅菜扣肉，云水谣饭庄本地人都认这家，点单照攻略不踩雷。","addr":"云水谣古镇"},{"title":"糍粑（人均12元）","description":"漳州 · 南靖土楼的招牌是糍粑，土楼小吃本地人都认这家，点单照攻略不踩雷。","addr":"裕昌楼前"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具","身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 漳州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 漳州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 漳州 的交通方便吗？","推荐先到 漳州，再打车或景区直通车前往核心景区；自驾导航直接搜南靖土楼即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('千岛湖纯攻略·美食清单5','guide','淳安 · 千岛湖','water','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',1990,1000,2,'中心湖区 / 东南湖区 / 文渊狮城 —— 纯攻略助你玩透千岛湖精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「千岛湖」两日慢旅行——水景。千岛湖有机鱼头认证标志。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 淳安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴淳安","description":"集合出发，大巴直达千岛湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中心湖区","description":"抵达后首游中心湖区，梅峰岛看千岛全景，缆车省力。","addr":"淳安县千岛湖镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐千岛湖鱼头（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"东南湖区","description":"早起人少，东南湖区精华时段，黄山尖九岛串联水道。","addr":"千岛湖","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山核桃，人均45元，补充体力。","addr":"渔街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"文渊狮城","description":"午后游览文渊狮城，水下古城复刻，夜游有戏。","addr":"姜家镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中心湖区","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"中心湖区是千岛湖最有代表性的看点，梅峰岛看千岛全景，缆车省力。攻略把它排进主线，时间留得最足。","notice":"梅峰岛看千岛全景，缆车省力。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"淳安县千岛湖镇"},{"spotId":"S2","name":"东南湖区","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"东南湖区是千岛湖最有代表性的看点，黄山尖九岛串联水道。攻略把它排进主线，时间留得最足。","notice":"黄山尖九岛串联水道。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"千岛湖"},{"spotId":"S3","name":"文渊狮城","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"文渊狮城是千岛湖最有代表性的看点，水下古城复刻，夜游有戏。攻略把它排进主线，时间留得最足。","notice":"水下古城复刻，夜游有戏。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"姜家镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"千岛湖鱼头（人均128元）","description":"淳安 · 千岛湖的招牌是千岛湖鱼头，淳牌鱼头馆本地人都认这家，点单照攻略不踩雷。","addr":"千岛湖镇新安大街"},{"title":"山核桃（人均45元）","description":"淳安 · 千岛湖的招牌是山核桃，特产店本地人都认这家，点单照攻略不踩雷。","addr":"渔街"},{"title":"艾草粿（人均10元）","description":"淳安 · 千岛湖的招牌是艾草粿，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"秀水街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","身份证件与手机充电宝","少量零食补给","保温水杯与少量现金","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 淳安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('东湖黄鹤楼纯攻略·自由行手册5','guide','武汉 · 东湖黄鹤楼','water','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',1500,800,2,'黄鹤楼 / 东湖绿道 / 昙华林 —— 纯攻略助你玩透东湖黄鹤楼精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「东湖黄鹤楼」三日深度游——水景。武汉鸭脖真空包装好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 武汉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往武汉，抵达后办理入住、熟悉周边环境。","addr":"武汉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄鹤楼","description":"下午首站黄鹤楼，调整状态进入旅行节奏，天下江山第一楼，夜景灯光秀。","addr":"武汉市武昌区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游武汉一带氛围拉满，晚餐热干面人均12元。","addr":"户部巷","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"东湖绿道","description":"全天主景点东湖绿道，骑行湖中道，磨山樱园。","addr":"武昌区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐豆皮（人均18元），早点休息。","addr":"大智路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"昙华林","description":"收官昙华林，老教堂与文创小店。","addr":"武昌区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐武昌鱼后集合返程，三日旅程圆满。","addr":"昙华林","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄鹤楼","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"黄鹤楼是东湖黄鹤楼最有代表性的看点，天下江山第一楼，夜景灯光秀。攻略把它排进主线，时间留得最足。","notice":"天下江山第一楼，夜景灯光秀。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"武汉市武昌区"},{"spotId":"S2","name":"东湖绿道","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"东湖绿道是东湖黄鹤楼最有代表性的看点，骑行湖中道，磨山樱园。攻略把它排进主线，时间留得最足。","notice":"骑行湖中道，磨山樱园。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"武昌区"},{"spotId":"S3","name":"昙华林","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"昙华林是东湖黄鹤楼最有代表性的看点，老教堂与文创小店。攻略把它排进主线，时间留得最足。","notice":"老教堂与文创小店。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"武昌区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"热干面（人均12元）","description":"武汉 · 东湖黄鹤楼的招牌是热干面，蔡林记本地人都认这家，点单照攻略不踩雷。","addr":"户部巷"},{"title":"豆皮（人均18元）","description":"武汉 · 东湖黄鹤楼的招牌是豆皮，老通城本地人都认这家，点单照攻略不踩雷。","addr":"大智路"},{"title":"武昌鱼（人均68元）","description":"武汉 · 东湖黄鹤楼的招牌是武昌鱼，湖锦酒楼本地人都认这家，点单照攻略不踩雷。","addr":"昙华林"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","墨镜与拍照道具","轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('少林寺纯攻略·省钱玩法5','guide','登封 · 少林寺','adventure','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,9,'少林寺常住院 / 三皇寨 / 嵩阳书院 —— 纯攻略助你玩透少林寺精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「少林寺」两日慢旅行——探险地。少林寺佛珠开光要理性。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 登封"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴登封","description":"集合出发，大巴直达少林寺，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"少林寺常住院","description":"抵达后首游少林寺常住院，塔林与武术表演，达摩面壁洞。","addr":"登封市嵩山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐少林素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三皇寨","description":"早起人少，三皇寨精华时段，悬空栈道看书册崖。","addr":"嵩山少室山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐登封焖子，人均28元，补充体力。","addr":"登封市区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"嵩阳书院","description":"午后游览嵩阳书院，四大书院之一。","addr":"登封市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"少林寺常住院","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"少林寺常住院是少林寺最有代表性的看点，塔林与武术表演，达摩面壁洞。攻略把它排进主线，时间留得最足。","notice":"塔林与武术表演，达摩面壁洞。这个点位上午光线最好。","durationMinutes":180,"addr":"登封市嵩山"},{"spotId":"S2","name":"三皇寨","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"三皇寨是少林寺最有代表性的看点，悬空栈道看书册崖。攻略把它排进主线，时间留得最足。","notice":"悬空栈道看书册崖。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"嵩山少室山"},{"spotId":"S3","name":"嵩阳书院","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"嵩阳书院是少林寺最有代表性的看点，四大书院之一。攻略把它排进主线，时间留得最足。","notice":"四大书院之一。这个点位上午光线最好。","durationMinutes":90,"addr":"登封市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"少林素斋（人均48元）","description":"登封 · 少林寺的招牌是少林素斋，寺内素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"少林寺内"},{"title":"登封焖子（人均28元）","description":"登封 · 少林寺的招牌是登封焖子，老字号本地人都认这家，点单照攻略不踩雷。","addr":"登封市区"},{"title":"焦盖烧饼（人均8元）","description":"登封 · 少林寺的招牌是焦盖烧饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"嵩阳书院旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机","少量零食补给","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 登封 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 登封，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云冈石窟纯攻略·避坑版5','guide','大同 · 云冈石窟','red','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',990,500,7,'云冈石窟 / 大同古城墙 / 悬空寺 —— 纯攻略助你玩透云冈石窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「云冈石窟」三日深度游——人文。大同煤雕工艺独特。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 大同"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大同，抵达后办理入住、熟悉周边环境。","addr":"大同市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"云冈石窟","description":"下午首站云冈石窟，调整状态进入旅行节奏，昙曜五窟露天大佛，北魏气象。","addr":"大同市云冈区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大同一带氛围拉满，晚餐刀削面人均15元。","addr":"大同市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大同古城墙","description":"全天主景点大同古城墙，夜景灯光，骑行城墙。","addr":"平城区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊杂粉（人均18元），早点休息。","addr":"鼓楼东街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"悬空寺","description":"收官悬空寺，峭壁上的千年古寺。","addr":"浑源县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐黄糕后集合返程，三日旅程圆满。","addr":"浑源县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"云冈石窟","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"云冈石窟是云冈石窟最有代表性的看点，昙曜五窟露天大佛，北魏气象。攻略把它排进主线，时间留得最足。","notice":"昙曜五窟露天大佛，北魏气象。这个点位上午光线最好。","durationMinutes":180,"addr":"大同市云冈区"},{"spotId":"S2","name":"大同古城墙","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"大同古城墙是云冈石窟最有代表性的看点，夜景灯光，骑行城墙。攻略把它排进主线，时间留得最足。","notice":"夜景灯光，骑行城墙。这个点位上午光线最好。","durationMinutes":120,"addr":"平城区"},{"spotId":"S3","name":"悬空寺","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"悬空寺是云冈石窟最有代表性的看点，峭壁上的千年古寺。攻略把它排进主线，时间留得最足。","notice":"峭壁上的千年古寺。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"浑源县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"刀削面（人均15元）","description":"大同 · 云冈石窟的招牌是刀削面，东方削面本地人都认这家，点单照攻略不踩雷。","addr":"大同市区"},{"title":"羊杂粉（人均18元）","description":"大同 · 云冈石窟的招牌是羊杂粉，老字号羊杂本地人都认这家，点单照攻略不踩雷。","addr":"鼓楼东街"},{"title":"黄糕（人均10元）","description":"大同 · 云冈石窟的招牌是黄糕，黍面糕铺本地人都认这家，点单照攻略不踩雷。","addr":"浑源县"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","少量零食补给","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 大同 的交通方便吗？","推荐先到 大同，再打车或景区直通车前往核心景区；自驾导航直接搜云冈石窟即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 大同，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丹霞山纯攻略·深度指南5','guide','韶关 · 丹霞山','adventure','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1200,600,9,'长老峰 / 阳元石 / 翔龙湖 —— 纯攻略助你玩透丹霞山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「丹霞山」两日慢旅行——探险地。丹霞山白毛茶清甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 韶关"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴韶关","description":"集合出发，大巴直达丹霞山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"长老峰","description":"抵达后首游长老峰，丹霞地貌命名地，观日亭日出。","addr":"韶关市仁化县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐冷水猪肚（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"阳元石","description":"早起人少，阳元石精华时段，天然奇石打卡。","addr":"丹霞山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐炒山坑螺，人均38元，补充体力。","addr":"周田镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"翔龙湖","description":"午后游览翔龙湖，水上丹霞乘船。","addr":"丹霞山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"长老峰","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"长老峰是丹霞山最有代表性的看点，丹霞地貌命名地，观日亭日出。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌命名地，观日亭日出。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"韶关市仁化县"},{"spotId":"S2","name":"阳元石","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"阳元石是丹霞山最有代表性的看点，天然奇石打卡。攻略把它排进主线，时间留得最足。","notice":"天然奇石打卡。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"丹霞山"},{"spotId":"S3","name":"翔龙湖","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"翔龙湖是丹霞山最有代表性的看点，水上丹霞乘船。攻略把它排进主线，时间留得最足。","notice":"水上丹霞乘船。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"丹霞山"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"冷水猪肚（人均48元）","description":"韶关 · 丹霞山的招牌是冷水猪肚，仁化农家菜本地人都认这家，点单照攻略不踩雷。","addr":"丹霞山镇"},{"title":"炒山坑螺（人均38元）","description":"韶关 · 丹霞山的招牌是炒山坑螺，山坑鱼小馆本地人都认这家，点单照攻略不踩雷。","addr":"周田镇"},{"title":"酸笋鸭（人均58元）","description":"韶关 · 丹霞山的招牌是酸笋鸭，韶关客家菜本地人都认这家，点单照攻略不踩雷。","addr":"仁化县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","保温水杯与少量现金","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 韶关 的交通方便吗？","推荐先到 韶关，再打车或景区直通车前往核心景区；自驾导航直接搜丹霞山即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 韶关 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('敦煌莫高窟纯攻略·周末版5','guide','酒泉 · 敦煌莫高窟','red','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',2990,1600,7,'莫高窟 / 鸣沙山月牙泉 / 沙洲夜市 —— 纯攻略助你玩透敦煌莫高窟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「敦煌莫高窟」三日深度游——人文。敦煌夜光杯工艺品别致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 酒泉"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往酒泉，抵达后办理入住、熟悉周边环境。","addr":"酒泉市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫高窟","description":"下午首站莫高窟，调整状态进入旅行节奏，千年壁画宝库，A类票提前约。","addr":"敦煌市鸣沙山东麓","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游酒泉一带氛围拉满，晚餐驴肉黄面人均28元。","addr":"滨河世纪家园","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"鸣沙山月牙泉","description":"全天主景点鸣沙山月牙泉，沙漠绿洲，骆驼队与滑沙。","addr":"敦煌市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐胡羊焖饼（人均58元），早点休息。","addr":"沙洲路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙洲夜市","description":"收官沙洲夜市，驴肉黄面与夜市淘货。","addr":"敦煌市区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐杏皮水后集合返程，三日旅程圆满。","addr":"沙洲夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫高窟","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"莫高窟是敦煌莫高窟最有代表性的看点，千年壁画宝库，A类票提前约。攻略把它排进主线，时间留得最足。","notice":"千年壁画宝库，A类票提前约。这个点位上午光线最好。","durationMinutes":240,"addr":"敦煌市鸣沙山东麓"},{"spotId":"S2","name":"鸣沙山月牙泉","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"鸣沙山月牙泉是敦煌莫高窟最有代表性的看点，沙漠绿洲，骆驼队与滑沙。攻略把它排进主线，时间留得最足。","notice":"沙漠绿洲，骆驼队与滑沙。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"敦煌市"},{"spotId":"S3","name":"沙洲夜市","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"沙洲夜市是敦煌莫高窟最有代表性的看点，驴肉黄面与夜市淘货。攻略把它排进主线，时间留得最足。","notice":"驴肉黄面与夜市淘货。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"敦煌市区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉黄面（人均28元）","description":"酒泉 · 敦煌莫高窟的招牌是驴肉黄面，顺张驴肉黄面馆本地人都认这家，点单照攻略不踩雷。","addr":"滨河世纪家园"},{"title":"胡羊焖饼（人均58元）","description":"酒泉 · 敦煌莫高窟的招牌是胡羊焖饼，靖远尕六美味羊羔肉本地人都认这家，点单照攻略不踩雷。","addr":"沙洲路"},{"title":"杏皮水（人均8元）","description":"酒泉 · 敦煌莫高窟的招牌是杏皮水，夜市摊位本地人都认这家，点单照攻略不踩雷。","addr":"沙洲夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","墨镜与拍照道具","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 酒泉 的交通方便吗？","推荐先到 酒泉，再打车或景区直通车前往核心景区；自驾导航直接搜敦煌莫高窟即可。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('布达拉宫纯攻略·亲子篇5','guide','拉萨 · 布达拉宫','plateau','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',2990,1600,2,'布达拉宫 / 大昭寺 / 色拉寺 —— 纯攻略助你玩透布达拉宫精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「布达拉宫」两日慢旅行——高原。拉萨转经筒小件最好带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 拉萨"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴拉萨","description":"集合出发，大巴直达布达拉宫，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"布达拉宫","description":"抵达后首游布达拉宫，海拔3700宫殿，提前一天预约。","addr":"拉萨市城关区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏面（人均12元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大昭寺","description":"早起人少，大昭寺精华时段，八廓街转经道，藏地心脏。","addr":"老城区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤牦牛肉，人均68元，补充体力。","addr":"八角东南角","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"色拉寺","description":"午后游览色拉寺，辩经下午3点开始，场面壮观。","addr":"城北","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"布达拉宫","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"布达拉宫是布达拉宫最有代表性的看点，海拔3700宫殿，提前一天预约。攻略把它排进主线，时间留得最足。","notice":"海拔3700宫殿，提前一天预约。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"拉萨市城关区"},{"spotId":"S2","name":"大昭寺","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"大昭寺是布达拉宫最有代表性的看点，八廓街转经道，藏地心脏。攻略把它排进主线，时间留得最足。","notice":"八廓街转经道，藏地心脏。这个点位上午光线最好。","durationMinutes":120,"addr":"老城区"},{"spotId":"S3","name":"色拉寺","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"色拉寺是布达拉宫最有代表性的看点，辩经下午3点开始，场面壮观。攻略把它排进主线，时间留得最足。","notice":"辩经下午3点开始，场面壮观。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"城北"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏面（人均12元）","description":"拉萨 · 布达拉宫的招牌是藏面，光明港琼甜茶馆本地人都认这家，点单照攻略不踩雷。","addr":"八廓街"},{"title":"烤牦牛肉（人均68元）","description":"拉萨 · 布达拉宫的招牌是烤牦牛肉，玛吉阿米本地人都认这家，点单照攻略不踩雷。","addr":"八角东南角"},{"title":"青稞酒（人均30元）","description":"拉萨 · 布达拉宫的招牌是青稞酒，藏家宴本地人都认这家，点单照攻略不踩雷。","addr":"藏医院路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待"],"faqs":[["到达 拉萨 的交通方便吗？","推荐先到 拉萨，再打车或景区直通车前往核心景区；自驾导航直接搜布达拉宫即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 拉萨 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五大道瓷房子纯攻略·摄影机位5','guide','和平 · 五大道瓷房子','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',1990,1000,5,'五大道 / 瓷房子 / 古文化街 —— 纯攻略助你玩透五大道瓷房子精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「五大道瓷房子」三日深度游——文艺。天津泥人张彩塑传神。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"天津 · 和平"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往和平，抵达后办理入住、熟悉周边环境。","addr":"和平市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"五大道","description":"下午首站五大道，调整状态进入旅行节奏，万国建筑博览会，马车游。","addr":"天津市和平区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游和平一带氛围拉满，晚餐煎饼果子人均10元。","addr":"和平区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"瓷房子","description":"全天主景点瓷房子，7亿瓷片房子，白天看外观。","addr":"和平区赤峰道","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐狗不理包子（人均45元），早点休息。","addr":"山东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古文化街","description":"收官古文化街，泥人张杨柳青年画。","addr":"南开区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐耳朵眼炸糕后集合返程，三日旅程圆满。","addr":"古文化街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"五大道","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"五大道是五大道瓷房子最有代表性的看点，万国建筑博览会，马车游。攻略把它排进主线，时间留得最足。","notice":"万国建筑博览会，马车游。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"天津市和平区"},{"spotId":"S2","name":"瓷房子","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"瓷房子是五大道瓷房子最有代表性的看点，7亿瓷片房子，白天看外观。攻略把它排进主线，时间留得最足。","notice":"7亿瓷片房子，白天看外观。拍照记得留神脚下台阶。","durationMinutes":30,"addr":"和平区赤峰道"},{"spotId":"S3","name":"古文化街","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"古文化街是五大道瓷房子最有代表性的看点，泥人张杨柳青年画。攻略把它排进主线，时间留得最足。","notice":"泥人张杨柳青年画。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"南开区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"煎饼果子（人均10元）","description":"和平 · 五大道瓷房子的招牌是煎饼果子，南楼煎饼本地人都认这家，点单照攻略不踩雷。","addr":"和平区"},{"title":"狗不理包子（人均45元）","description":"和平 · 五大道瓷房子的招牌是狗不理包子，狗不理总店本地人都认这家，点单照攻略不踩雷。","addr":"山东路"},{"title":"耳朵眼炸糕（人均8元）","description":"和平 · 五大道瓷房子的招牌是耳朵眼炸糕，耳朵眼总店本地人都认这家，点单照攻略不踩雷。","addr":"古文化街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","相机或运动相机","墨镜与拍照道具","换洗衣物与外套（早晚温差）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意"],"faqs":[["当地有什么必吃？","到了 和平，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 和平 的交通方便吗？","推荐先到 和平，再打车或景区直通车前往核心景区；自驾导航直接搜五大道瓷房子即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙虎山纯攻略·美食清单5','guide','鹰潭 · 龙虎山','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',1990,1000,2,'仙水岩 / 泸溪河竹筏 / 上清古镇 —— 纯攻略助你玩透龙虎山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙虎山」两日慢旅行——水景。龙虎山道教养生茶值得带。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 鹰潭"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴鹰潭","description":"集合出发，大巴直达龙虎山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"仙水岩","description":"抵达后首游仙水岩，悬棺表演一天四场，提前占前排。","addr":"龙虎山仙水岩景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐天师板栗烧鸡（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"泸溪河竹筏","description":"早起人少，泸溪河竹筏精华时段，顺流漂90分钟，防晒必做。","addr":"龙虎山竹筏码头","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐泸溪河鱼，人均58元，补充体力。","addr":"竹筏码头旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"上清古镇","description":"午后游览上清古镇，天师府在此，古街人少。","addr":"龙虎山上清镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"仙水岩","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"仙水岩是龙虎山最有代表性的看点，悬棺表演一天四场，提前占前排。攻略把它排进主线，时间留得最足。","notice":"悬棺表演一天四场，提前占前排。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"龙虎山仙水岩景区"},{"spotId":"S2","name":"泸溪河竹筏","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"泸溪河竹筏是龙虎山最有代表性的看点，顺流漂90分钟，防晒必做。攻略把它排进主线，时间留得最足。","notice":"顺流漂90分钟，防晒必做。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"龙虎山竹筏码头"},{"spotId":"S3","name":"上清古镇","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"上清古镇是龙虎山最有代表性的看点，天师府在此，古街人少。攻略把它排进主线，时间留得最足。","notice":"天师府在此，古街人少。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙虎山上清镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"天师板栗烧鸡（人均68元）","description":"鹰潭 · 龙虎山的招牌是天师板栗烧鸡，上清古镇饭店本地人都认这家，点单照攻略不踩雷。","addr":"上清古镇长街"},{"title":"泸溪河鱼（人均58元）","description":"鹰潭 · 龙虎山的招牌是泸溪河鱼，仙水岩渔家本地人都认这家，点单照攻略不踩雷。","addr":"竹筏码头旁"},{"title":"上清豆腐（人均20元）","description":"鹰潭 · 龙虎山的招牌是上清豆腐，古镇豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"上清古街中段"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["保温水杯与少量现金","少量零食补给","墨镜与拍照道具","相机或运动相机","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["当地有什么必吃？","到了 鹰潭，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('张家界国家森林公园纯攻略·自由行手册5','guide','张家界 · 张家界国家森林公园','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1990,1000,2,'袁家界 / 天子山 / 金鞭溪 —— 纯攻略助你玩透张家界国家森林公园精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「张家界国家森林公园」三日深度游——山岳。张家界莓茶降火神器。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 张家界"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往张家界，抵达后办理入住、熟悉周边环境。","addr":"张家界市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"袁家界","description":"下午首站袁家界，调整状态进入旅行节奏，阿凡达悬浮山原型，百龙天梯上山。","addr":"武陵源区森林公园","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游张家界一带氛围拉满，晚餐三下锅人均58元。","addr":"武陵源汽车站旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天子山","description":"全天主景点天子山，御笔峰日落绝佳，贺龙公园顺路。","addr":"武陵源天子山景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土家腊肉（人均48元），早点休息。","addr":"溪布街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"金鞭溪","description":"收官金鞭溪，全程7.5公里平路，溪边猕猴抢食注意。","addr":"森林公园大氧吧广场","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐岩耳炖土鸡后集合返程，三日旅程圆满。","addr":"森林公园门票站","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"袁家界","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"袁家界是张家界国家森林公园最有代表性的看点，阿凡达悬浮山原型，百龙天梯上山。攻略把它排进主线，时间留得最足。","notice":"阿凡达悬浮山原型，百龙天梯上山。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"武陵源区森林公园"},{"spotId":"S2","name":"天子山","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"天子山是张家界国家森林公园最有代表性的看点，御笔峰日落绝佳，贺龙公园顺路。攻略把它排进主线，时间留得最足。","notice":"御笔峰日落绝佳，贺龙公园顺路。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"武陵源天子山景区"},{"spotId":"S3","name":"金鞭溪","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"金鞭溪是张家界国家森林公园最有代表性的看点，全程7.5公里平路，溪边猕猴抢食注意。攻略把它排进主线，时间留得最足。","notice":"全程7.5公里平路，溪边猕猴抢食注意。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"森林公园大氧吧广场"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"三下锅（人均58元）","description":"张家界 · 张家界国家森林公园的招牌是三下锅，胡师傅三下锅本地人都认这家，点单照攻略不踩雷。","addr":"武陵源汽车站旁"},{"title":"土家腊肉（人均48元）","description":"张家界 · 张家界国家森林公园的招牌是土家腊肉，湘西腊肉馆本地人都认这家，点单照攻略不踩雷。","addr":"溪布街"},{"title":"岩耳炖土鸡（人均88元）","description":"张家界 · 张家界国家森林公园的招牌是岩耳炖土鸡，山里人家本地人都认这家，点单照攻略不踩雷。","addr":"森林公园门票站"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","防晒霜与遮阳帽","轻便雨衣或折叠伞","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 张家界 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('紫鹊界梯田纯攻略·省钱玩法5','guide','娄底 · 紫鹊界梯田','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',2990,1600,1,'紫鹊界梯田 / 正龙古村 / 梅山龙宫 —— 纯攻略助你玩透紫鹊界梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「紫鹊界梯田」两日慢旅行——古村落。新化黄精茶养生。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 娄底"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴娄底","description":"集合出发，大巴直达紫鹊界梯田，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"紫鹊界梯田","description":"抵达后首游紫鹊界梯田，两千年秦人梯田，月牙山八仙过海。","addr":"娄底市新化县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐新化三合汤（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"正龙古村","description":"早起人少，正龙古村精华时段，干栏式板屋村落。","addr":"紫鹊界脚下","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐杯子糕，人均10元，补充体力。","addr":"紫鹊界","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"梅山龙宫","description":"午后游览梅山龙宫，地下溶洞暗河乘船。","addr":"新化县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"紫鹊界梯田","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"紫鹊界梯田是紫鹊界梯田最有代表性的看点，两千年秦人梯田，月牙山八仙过海。攻略把它排进主线，时间留得最足。","notice":"两千年秦人梯田，月牙山八仙过海。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"娄底市新化县"},{"spotId":"S2","name":"正龙古村","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"正龙古村是紫鹊界梯田最有代表性的看点，干栏式板屋村落。攻略把它排进主线，时间留得最足。","notice":"干栏式板屋村落。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"紫鹊界脚下"},{"spotId":"S3","name":"梅山龙宫","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"梅山龙宫是紫鹊界梯田最有代表性的看点，地下溶洞暗河乘船。攻略把它排进主线，时间留得最足。","notice":"地下溶洞暗河乘船。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"新化县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新化三合汤（人均38元）","description":"娄底 · 紫鹊界梯田的招牌是新化三合汤，老字号三合汤本地人都认这家，点单照攻略不踩雷。","addr":"新化县城"},{"title":"杯子糕（人均10元）","description":"娄底 · 紫鹊界梯田的招牌是杯子糕，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"紫鹊界"},{"title":"柴火腊肉（人均45元）","description":"娄底 · 紫鹊界梯田的招牌是柴火腊肉，农家直购本地人都认这家，点单照攻略不踩雷。","addr":"正龙古村"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","防晒霜与遮阳帽","相机或运动相机","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 娄底，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 娄底 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大熊猫基地都江堰纯攻略·避坑版5','guide','成都 · 大熊猫基地都江堰','food','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',2500,1300,3,'大熊猫繁育研究基地 / 都江堰 / 南桥夜啤酒 —— 纯攻略助你玩透大熊猫基地都江堰精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大熊猫基地都江堰」三日深度游——美食。郫县豆瓣是川菜之魂。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 成都"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往成都，抵达后办理入住、熟悉周边环境。","addr":"成都市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大熊猫繁育研究基地","description":"下午首站大熊猫繁育研究基地，调整状态进入旅行节奏，早8点开园直奔月亮产房，熊猫最活跃。","addr":"成华区外北熊猫大道","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游成都一带氛围拉满，晚餐火锅人均110元。","addr":"建设路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"都江堰","description":"全天主景点都江堰，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。","addr":"都江堰市公园路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐串串香（人均65元），早点休息。","addr":"玉林路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"南桥夜啤酒","description":"收官南桥夜啤酒，岷江水上的夜风与美食。","addr":"都江堰市南桥","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐钟水饺后集合返程，三日旅程圆满。","addr":"人民公园旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大熊猫繁育研究基地","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"大熊猫繁育研究基地是大熊猫基地都江堰最有代表性的看点，早8点开园直奔月亮产房，熊猫最活跃。攻略把它排进主线，时间留得最足。","notice":"早8点开园直奔月亮产房，熊猫最活跃。这个点位上午光线最好。","durationMinutes":240,"addr":"成华区外北熊猫大道"},{"spotId":"S2","name":"都江堰","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"都江堰是大熊猫基地都江堰最有代表性的看点，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。攻略把它排进主线，时间留得最足。","notice":"鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。这个点位上午光线最好。","durationMinutes":180,"addr":"都江堰市公园路"},{"spotId":"S3","name":"南桥夜啤酒","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"南桥夜啤酒是大熊猫基地都江堰最有代表性的看点，岷江水上的夜风与美食。攻略把它排进主线，时间留得最足。","notice":"岷江水上的夜风与美食。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"都江堰市南桥"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"火锅（人均110元）","description":"成都 · 大熊猫基地都江堰的招牌是火锅，蜀大侠本地人都认这家，点单照攻略不踩雷。","addr":"建设路"},{"title":"串串香（人均65元）","description":"成都 · 大熊猫基地都江堰的招牌是串串香，马路边边本地人都认这家，点单照攻略不踩雷。","addr":"玉林路"},{"title":"钟水饺（人均15元）","description":"成都 · 大熊猫基地都江堰的招牌是钟水饺，老字号小吃本地人都认这家，点单照攻略不踩雷。","addr":"人民公园旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","保温水杯与少量现金","换洗衣物与外套（早晚温差）","墨镜与拍照道具","防晒霜与遮阳帽","相机或运动相机","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["当地有什么必吃？","到了 成都，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄果树瀑布纯攻略·深度指南5','guide','安顺 · 黄果树瀑布','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1200,600,2,'黄果树大瀑布 / 天星桥 / 陡坡塘 —— 纯攻略助你玩透黄果树瀑布精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「黄果树瀑布」两日慢旅行——水景。安顺三刀是传统名点。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 安顺"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴安顺","description":"集合出发，大巴直达黄果树瀑布，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄果树大瀑布","description":"抵达后首游黄果树大瀑布，亚洲最大瀑布，水帘洞穿瀑而过。","addr":"安顺市镇宁县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐夺夺粉（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天星桥","description":"早起人少，天星桥精华时段，石景水上盆景，数生步趣味。","addr":"黄果树景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐裹卷，人均12元，补充体力。","addr":"黄果树镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"陡坡塘","description":"午后游览陡坡塘，西游记片尾取景地。","addr":"黄果树景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄果树大瀑布","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"黄果树大瀑布是黄果树瀑布最有代表性的看点，亚洲最大瀑布，水帘洞穿瀑而过。攻略把它排进主线，时间留得最足。","notice":"亚洲最大瀑布，水帘洞穿瀑而过。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"安顺市镇宁县"},{"spotId":"S2","name":"天星桥","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"天星桥是黄果树瀑布最有代表性的看点，石景水上盆景，数生步趣味。攻略把它排进主线，时间留得最足。","notice":"石景水上盆景，数生步趣味。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"黄果树景区"},{"spotId":"S3","name":"陡坡塘","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"陡坡塘是黄果树瀑布最有代表性的看点，西游记片尾取景地。攻略把它排进主线，时间留得最足。","notice":"西游记片尾取景地。这个点位上午光线最好。","durationMinutes":60,"addr":"黄果树景区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"夺夺粉（人均35元）","description":"安顺 · 黄果树瀑布的招牌是夺夺粉，安顺小吃街本地人都认这家，点单照攻略不踩雷。","addr":"安顺市区"},{"title":"裹卷（人均12元）","description":"安顺 · 黄果树瀑布的招牌是裹卷，苗岭小吃本地人都认这家，点单照攻略不踩雷。","addr":"黄果树镇"},{"title":"布依农家餐（人均48元）","description":"安顺 · 黄果树瀑布的招牌是布依农家餐，石头寨本地人都认这家，点单照攻略不踩雷。","addr":"石头寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","少量零食补给","身份证件与手机充电宝","轻便雨衣或折叠伞","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 安顺 的交通方便吗？","推荐先到 安顺，再打车或景区直通车前往核心景区；自驾导航直接搜黄果树瀑布即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙脊梯田纯攻略·周末版5','guide','桂林 · 龙脊梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1500,800,1,'平安寨七星伴月 / 金坑大寨 / 黄洛红瑶寨 —— 纯攻略助你玩透龙脊梯田精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「龙脊梯田」三日深度游——古村落。龙脊辣椒酱拌饭一绝。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往桂林，抵达后办理入住、熟悉周边环境。","addr":"桂林市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"平安寨七星伴月","description":"下午首站平安寨七星伴月，调整状态进入旅行节奏，经典梯田观景台，徒步30分钟。","addr":"龙胜县龙脊镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游桂林一带氛围拉满，晚餐竹筒饭人均25元。","addr":"平安寨","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"金坑大寨","description":"全天主景点金坑大寨，缆车直达3号观景点，日落最佳。","addr":"龙脊梯田金坑","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土鸡煲（人均68元），早点休息。","addr":"金坑梯田","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"黄洛红瑶寨","description":"收官黄洛红瑶寨，天下第一长发村表演。","addr":"龙脊山下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐龙脊茶后集合返程，三日旅程圆满。","addr":"黄洛瑶寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"平安寨七星伴月","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"平安寨七星伴月是龙脊梯田最有代表性的看点，经典梯田观景台，徒步30分钟。攻略把它排进主线，时间留得最足。","notice":"经典梯田观景台，徒步30分钟。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"龙胜县龙脊镇"},{"spotId":"S2","name":"金坑大寨","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"金坑大寨是龙脊梯田最有代表性的看点，缆车直达3号观景点，日落最佳。攻略把它排进主线，时间留得最足。","notice":"缆车直达3号观景点，日落最佳。这个点位上午光线最好。","durationMinutes":150,"addr":"龙脊梯田金坑"},{"spotId":"S3","name":"黄洛红瑶寨","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"黄洛红瑶寨是龙脊梯田最有代表性的看点，天下第一长发村表演。攻略把它排进主线，时间留得最足。","notice":"天下第一长发村表演。这个点位上午光线最好。","durationMinutes":60,"addr":"龙脊山下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"竹筒饭（人均25元）","description":"桂林 · 龙脊梯田的招牌是竹筒饭，梯田农家本地人都认这家，点单照攻略不踩雷。","addr":"平安寨"},{"title":"土鸡煲（人均68元）","description":"桂林 · 龙脊梯田的招牌是土鸡煲，大寨农家本地人都认这家，点单照攻略不踩雷。","addr":"金坑梯田"},{"title":"龙脊茶（人均20元）","description":"桂林 · 龙脊梯田的招牌是龙脊茶，茶农家本地人都认这家，点单照攻略不踩雷。","addr":"黄洛瑶寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","少量零食补给","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 桂林 的交通方便吗？","推荐先到 桂林，再打车或景区直通车前往核心景区；自驾导航直接搜龙脊梯田即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('霞浦滩涂纯攻略·亲子篇5','guide','宁德 · 霞浦滩涂','photography','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',1990,1000,12,'北岐滩涂 / 杨家溪 / 东壁日落 —— 纯攻略助你玩透霞浦滩涂精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「霞浦滩涂」两日慢旅行——摄影胜地。霞浦紫菜海带全国第一。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 宁德"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宁德","description":"集合出发，大巴直达霞浦滩涂，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"北岐滩涂","description":"抵达后首游北岐滩涂，日出紫菜架光影，摄影圣地。","addr":"霞浦县松港街道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐霞浦剑蛏（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"杨家溪","description":"早起人少，杨家溪精华时段，千年枫榕树群，牛群穿雾。","addr":"霞浦县牙城镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐海带排骨汤，人均38元，补充体力。","addr":"北岐村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"东壁日落","description":"午后游览东壁日落，落日渔船归航机位。","addr":"霞浦县三沙镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"北岐滩涂","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"北岐滩涂是霞浦滩涂最有代表性的看点，日出紫菜架光影，摄影圣地。攻略把它排进主线，时间留得最足。","notice":"日出紫菜架光影，摄影圣地。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"霞浦县松港街道"},{"spotId":"S2","name":"杨家溪","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"杨家溪是霞浦滩涂最有代表性的看点，千年枫榕树群，牛群穿雾。攻略把它排进主线，时间留得最足。","notice":"千年枫榕树群，牛群穿雾。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"霞浦县牙城镇"},{"spotId":"S3","name":"东壁日落","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"东壁日落是霞浦滩涂最有代表性的看点，落日渔船归航机位。攻略把它排进主线，时间留得最足。","notice":"落日渔船归航机位。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"霞浦县三沙镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"霞浦剑蛏（人均68元）","description":"宁德 · 霞浦滩涂的招牌是霞浦剑蛏，海鲜大排档本地人都认这家，点单照攻略不踩雷。","addr":"三沙镇"},{"title":"海带排骨汤（人均38元）","description":"宁德 · 霞浦滩涂的招牌是海带排骨汤，渔家菜本地人都认这家，点单照攻略不踩雷。","addr":"北岐村"},{"title":"糊汤（人均10元）","description":"宁德 · 霞浦滩涂的招牌是糊汤，街头早点本地人都认这家，点单照攻略不踩雷。","addr":"霞浦县城"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","常用药品（肠胃药/创可贴）","保温水杯与少量现金","轻便雨衣或折叠伞","少量零食补给","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('拙政园林纯攻略·摄影机位5','guide','苏州 · 拙政园林','art','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',1990,1000,5,'拙政园 / 平江路 / 虎丘 —— 纯攻略助你玩透拙政园林精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「拙政园林」三日深度游——文艺。苏绣团扇工艺最精。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 苏州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往苏州，抵达后办理入住、熟悉周边环境。","addr":"苏州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"拙政园","description":"下午首站拙政园，调整状态进入旅行节奏，江南园林之母，人再多也值得。","addr":"苏州市姑苏区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游苏州一带氛围拉满，晚餐松鼠桂鱼人均128元。","addr":"太监弄","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"平江路","description":"全天主景点平江路，小桥流水人家，评弹声里喝茶。","addr":"姑苏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蟹粉小笼（人均25元），早点休息。","addr":"临顿路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"虎丘","description":"收官虎丘，吴中第一名胜，斜塔传奇。","addr":"姑苏区山塘街","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桂花糕后集合返程，三日旅程圆满。","addr":"山塘街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"拙政园","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"拙政园是拙政园林最有代表性的看点，江南园林之母，人再多也值得。攻略把它排进主线，时间留得最足。","notice":"江南园林之母，人再多也值得。这个点位上午光线最好。","durationMinutes":150,"addr":"苏州市姑苏区"},{"spotId":"S2","name":"平江路","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"平江路是拙政园林最有代表性的看点，小桥流水人家，评弹声里喝茶。攻略把它排进主线，时间留得最足。","notice":"小桥流水人家，评弹声里喝茶。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"姑苏区"},{"spotId":"S3","name":"虎丘","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"虎丘是拙政园林最有代表性的看点，吴中第一名胜，斜塔传奇。攻略把它排进主线，时间留得最足。","notice":"吴中第一名胜，斜塔传奇。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"姑苏区山塘街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松鼠桂鱼（人均128元）","description":"苏州 · 拙政园林的招牌是松鼠桂鱼，得月楼本地人都认这家，点单照攻略不踩雷。","addr":"太监弄"},{"title":"蟹粉小笼（人均25元）","description":"苏州 · 拙政园林的招牌是蟹粉小笼，哑巴生煎本地人都认这家，点单照攻略不踩雷。","addr":"临顿路"},{"title":"桂花糕（人均15元）","description":"苏州 · 拙政园林的招牌是桂花糕，采芝斋本地人都认这家，点单照攻略不踩雷。","addr":"山塘街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 苏州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 苏州 的交通方便吗？","推荐先到 苏州，再打车或景区直通车前往核心景区；自驾导航直接搜拙政园林即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('恩施大峡谷纯攻略·美食清单5','guide','恩施 · 恩施大峡谷','adventure','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',990,500,9,'七星寨 / 云龙地缝 / 梭布垭石林 —— 纯攻略助你玩透恩施大峡谷精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「恩施大峡谷」两日慢旅行——探险地。恩施玉露茶古法蒸青。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 恩施"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴恩施","description":"集合出发，大巴直达恩施大峡谷，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七星寨","description":"抵达后首游七星寨，一炷香奇观，云龙地缝联游。","addr":"恩施市沐抚街道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐土家腊蹄子（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"云龙地缝","description":"早起人少，云龙地缝精华时段，U型地缝瀑布成群。","addr":"大峡谷景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐合渣，人均28元，补充体力。","addr":"沐抚镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"梭布垭石林","description":"午后游览梭布垭石林，戴冠石林迷宫。","addr":"恩施市太阳河乡","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七星寨","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"七星寨是恩施大峡谷最有代表性的看点，一炷香奇观，云龙地缝联游。攻略把它排进主线，时间留得最足。","notice":"一炷香奇观，云龙地缝联游。这个点位上午光线最好。","durationMinutes":300,"addr":"恩施市沐抚街道"},{"spotId":"S2","name":"云龙地缝","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"云龙地缝是恩施大峡谷最有代表性的看点，U型地缝瀑布成群。攻略把它排进主线，时间留得最足。","notice":"U型地缝瀑布成群。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大峡谷景区"},{"spotId":"S3","name":"梭布垭石林","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"梭布垭石林是恩施大峡谷最有代表性的看点，戴冠石林迷宫。攻略把它排进主线，时间留得最足。","notice":"戴冠石林迷宫。这个点位上午光线最好。","durationMinutes":150,"addr":"恩施市太阳河乡"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土家腊蹄子（人均58元）","description":"恩施 · 恩施大峡谷的招牌是土家腊蹄子，张关合渣本地人都认这家，点单照攻略不踩雷。","addr":"恩施市区"},{"title":"合渣（人均28元）","description":"恩施 · 恩施大峡谷的招牌是合渣，土家合渣馆本地人都认这家，点单照攻略不踩雷。","addr":"沐抚镇"},{"title":"土豆饭（人均22元）","description":"恩施 · 恩施大峡谷的招牌是土豆饭，农家本地人都认这家，点单照攻略不踩雷。","addr":"大峡谷游客中心"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","相机或运动相机","保温水杯与少量现金","身份证件与手机充电宝","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 恩施 的交通方便吗？","推荐先到 恩施，再打车或景区直通车前往核心景区；自驾导航直接搜恩施大峡谷即可。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('老君山纯攻略·自由行手册5','guide','栾川 · 老君山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',2500,1300,2,'金顶道观群 / 十里画屏 / 追梦谷 —— 纯攻略助你玩透老君山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「老君山」三日深度游——山岳。老君山高山茶清冽。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 栾川"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往栾川，抵达后办理入住、熟悉周边环境。","addr":"栾川市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶道观群","description":"下午首站金顶道观群，调整状态进入旅行节奏，云海雪景封神，远赴人间惊鸿宴。","addr":"洛阳市栾川县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游栾川一带氛围拉满，晚餐栾川豆腐人均28元。","addr":"栾川县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"十里画屏","description":"全天主景点十里画屏，滑道下山，省膝盖。","addr":"老君山石林","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蝌蚪面（人均18元），早点休息。","addr":"鸡冠洞乡","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"追梦谷","description":"收官追梦谷，溪瀑竹林轻松线。","addr":"老君山脚下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐玉米糁汤后集合返程，三日旅程圆满。","addr":"景区民宿","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶道观群","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"金顶道观群是老君山最有代表性的看点，云海雪景封神，远赴人间惊鸿宴。攻略把它排进主线，时间留得最足。","notice":"云海雪景封神，远赴人间惊鸿宴。提前10分钟到，避开旅行团大部队。","durationMinutes":300,"addr":"洛阳市栾川县"},{"spotId":"S2","name":"十里画屏","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"十里画屏是老君山最有代表性的看点，滑道下山，省膝盖。攻略把它排进主线，时间留得最足。","notice":"滑道下山，省膝盖。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"老君山石林"},{"spotId":"S3","name":"追梦谷","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"追梦谷是老君山最有代表性的看点，溪瀑竹林轻松线。攻略把它排进主线，时间留得最足。","notice":"溪瀑竹林轻松线。这个点位上午光线最好。","durationMinutes":120,"addr":"老君山脚下"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"栾川豆腐（人均28元）","description":"栾川 · 老君山的招牌是栾川豆腐，山城豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"栾川县城"},{"title":"蝌蚪面（人均18元）","description":"栾川 · 老君山的招牌是蝌蚪面，老君山农家本地人都认这家，点单照攻略不踩雷。","addr":"鸡冠洞乡"},{"title":"玉米糁汤（人均10元）","description":"栾川 · 老君山的招牌是玉米糁汤，农家早餐本地人都认这家，点单照攻略不踩雷。","addr":"景区民宿"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1125,"required":false},{"name":"住宿参考","amount":875,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["轻便雨衣或折叠伞","防晒霜与遮阳帽","墨镜与拍照道具","常用药品（肠胃药/创可贴）","少量零食补给","舒适徒步鞋（防滑鞋底）","相机或运动相机","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 栾川 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('泰山纯攻略·省钱玩法5','guide','泰安 · 泰山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',990,500,2,'玉皇顶 / 十八盘 / 岱庙 —— 纯攻略助你玩透泰山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「泰山」两日慢旅行——山岳。泰山墨玉平安扣吉祥。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 泰安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴泰安","description":"集合出发，大巴直达泰山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"玉皇顶","description":"抵达后首游玉皇顶，五岳之首看日出，夜爬经典。","addr":"泰安市泰山区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐泰安煎饼（人均12元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"十八盘","description":"早起人少，十八盘精华时段，1600级台阶，紧十八慢十八。","addr":"泰山中天门","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐豆腐宴，人均38元，补充体力。","addr":"岱庙旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"岱庙","description":"午后游览岱庙，历代帝王封禅起点。","addr":"泰山区东岳大街","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"玉皇顶","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"玉皇顶是泰山最有代表性的看点，五岳之首看日出，夜爬经典。攻略把它排进主线，时间留得最足。","notice":"五岳之首看日出，夜爬经典。周边有休息区与补给点，随时停留。","durationMinutes":360,"addr":"泰安市泰山区"},{"spotId":"S2","name":"十八盘","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"十八盘是泰山最有代表性的看点，1600级台阶，紧十八慢十八。攻略把它排进主线，时间留得最足。","notice":"1600级台阶，紧十八慢十八。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"泰山中天门"},{"spotId":"S3","name":"岱庙","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"岱庙是泰山最有代表性的看点，历代帝王封禅起点。攻略把它排进主线，时间留得最足。","notice":"历代帝王封禅起点。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"泰山区东岳大街"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"泰安煎饼（人均12元）","description":"泰安 · 泰山的招牌是泰安煎饼，煎饼卷大葱本地人都认这家，点单照攻略不踩雷。","addr":"红门路"},{"title":"豆腐宴（人均38元）","description":"泰安 · 泰山的招牌是豆腐宴，岱庙豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"岱庙旁"},{"title":"赤鳞鱼（人均68元）","description":"泰安 · 泰山的招牌是赤鳞鱼，山溪鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"中天门"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","保温水杯与少量现金","少量零食补给","舒适徒步鞋（防滑鞋底）","相机或运动相机","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('潮州古城纯攻略·避坑版5','guide','潮州 · 潮州古城','food','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',1200,600,3,'广济桥 / 牌坊街 / 韩文公祠 —— 纯攻略助你玩透潮州古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「潮州古城」三日深度游——美食。潮州手拉朱泥壶雅致。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 潮州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往潮州，抵达后办理入住、熟悉周边环境。","addr":"潮州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"广济桥","description":"下午首站广济桥，调整状态进入旅行节奏，十八梭船廿四洲，灯光秀。","addr":"潮州市湘桥区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游潮州一带氛围拉满，晚餐牛肉火锅人均88元。","addr":"官塘镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"牌坊街","description":"全天主景点牌坊街，23座古牌坊，手拉壶体验。","addr":"湘桥区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蚝烙（人均25元），早点休息。","addr":"西马路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"韩文公祠","description":"收官韩文公祠，纪念韩愈，笔架山对望。","addr":"韩江东岸","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐鸭母捻后集合返程，三日旅程圆满。","addr":"牌坊街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"广济桥","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"广济桥是潮州古城最有代表性的看点，十八梭船廿四洲，灯光秀。攻略把它排进主线，时间留得最足。","notice":"十八梭船廿四洲，灯光秀。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"潮州市湘桥区"},{"spotId":"S2","name":"牌坊街","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"牌坊街是潮州古城最有代表性的看点，23座古牌坊，手拉壶体验。攻略把它排进主线，时间留得最足。","notice":"23座古牌坊，手拉壶体验。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"湘桥区"},{"spotId":"S3","name":"韩文公祠","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"韩文公祠是潮州古城最有代表性的看点，纪念韩愈，笔架山对望。攻略把它排进主线，时间留得最足。","notice":"纪念韩愈，笔架山对望。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"韩江东岸"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牛肉火锅（人均88元）","description":"潮州 · 潮州古城的招牌是牛肉火锅，官塘兄弟本地人都认这家，点单照攻略不踩雷。","addr":"官塘镇"},{"title":"蚝烙（人均25元）","description":"潮州 · 潮州古城的招牌是蚝烙，老柯蚝烙本地人都认这家，点单照攻略不踩雷。","addr":"西马路"},{"title":"鸭母捻（人均12元）","description":"潮州 · 潮州古城的招牌是鸭母捻，胡荣泉本地人都认这家，点单照攻略不踩雷。","addr":"牌坊街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":540,"required":false},{"name":"住宿参考","amount":420,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","相机或运动相机","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 潮州 的交通方便吗？","推荐先到 潮州，再打车或景区直通车前往核心景区；自驾导航直接搜潮州古城即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七彩丹霞纯攻略·深度指南5','guide','张掖 · 七彩丹霞','photography','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',1500,800,12,'七彩丹霞 / 平山湖大峡谷 / 马蹄寺 —— 纯攻略助你玩透七彩丹霞精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「七彩丹霞」两日慢旅行——摄影胜地。张掖圆梨啤特有风味。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 张掖"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴张掖","description":"集合出发，大巴直达七彩丹霞，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七彩丹霞","description":"抵达后首游七彩丹霞，上帝的调色盘，4号观景台日落。","addr":"张掖市临泽县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐搓鱼面（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"平山湖大峡谷","description":"早起人少，平山湖大峡谷精华时段，张掖版科罗拉多，越野车深入。","addr":"甘州区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐炒炮，人均18元，补充体力。","addr":"大佛寺旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"马蹄寺","description":"午后游览马蹄寺，石窟与裕固族风情。","addr":"肃南县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七彩丹霞","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"七彩丹霞是七彩丹霞最有代表性的看点，上帝的调色盘，4号观景台日落。攻略把它排进主线，时间留得最足。","notice":"上帝的调色盘，4号观景台日落。这个点位上午光线最好。","durationMinutes":180,"addr":"张掖市临泽县"},{"spotId":"S2","name":"平山湖大峡谷","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"平山湖大峡谷是七彩丹霞最有代表性的看点，张掖版科罗拉多，越野车深入。攻略把它排进主线，时间留得最足。","notice":"张掖版科罗拉多，越野车深入。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"甘州区"},{"spotId":"S3","name":"马蹄寺","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"马蹄寺是七彩丹霞最有代表性的看点，石窟与裕固族风情。攻略把它排进主线，时间留得最足。","notice":"石窟与裕固族风情。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"肃南县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"搓鱼面（人均15元）","description":"张掖 · 七彩丹霞的招牌是搓鱼面，张掖搓鱼子本地人都认这家，点单照攻略不踩雷。","addr":"甘州区"},{"title":"炒炮（人均18元）","description":"张掖 · 七彩丹霞的招牌是炒炮，孙记炒炮本地人都认这家，点单照攻略不踩雷。","addr":"大佛寺旁"},{"title":"牛肉小饭（人均12元）","description":"张掖 · 七彩丹霞的招牌是牛肉小饭，早市小饭馆本地人都认这家，点单照攻略不踩雷。","addr":"南关市场"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","少量零食补给","换洗衣物与外套（早晚温差）","身份证件与手机充电宝"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 张掖，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雅鲁藏布大峡谷纯攻略·周末版5','guide','林芝 · 雅鲁藏布大峡谷','plateau','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',1990,1000,2,'南迦巴瓦观景台 / 雅鲁藏布大峡谷 / 鲁朗林海 —— 纯攻略助你玩透雅鲁藏布大峡谷精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「雅鲁藏布大峡谷」三日深度游——高原。林芝松茸6-8月最鲜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 林芝"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往林芝，抵达后办理入住、熟悉周边环境。","addr":"林芝市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"南迦巴瓦观景台","description":"下午首站南迦巴瓦观景台，调整状态进入旅行节奏，羞女峰十人九不遇，直白村最近。","addr":"米林县派镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游林芝一带氛围拉满，晚餐鲁朗石锅鸡人均128元。","addr":"鲁朗镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"雅鲁藏布大峡谷","description":"全天主景点雅鲁藏布大峡谷，世界最深深峡，换乘游览。","addr":"林芝市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐藏香猪（人均58元），早点休息。","addr":"派镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"鲁朗林海","description":"收官鲁朗林海，东方瑞士，石锅鸡之乡。","addr":"鲁朗镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐松茸炖藏鸡后集合返程，三日旅程圆满。","addr":"林芝市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"南迦巴瓦观景台","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"南迦巴瓦观景台是雅鲁藏布大峡谷最有代表性的看点，羞女峰十人九不遇，直白村最近。攻略把它排进主线，时间留得最足。","notice":"羞女峰十人九不遇，直白村最近。这个点位上午光线最好。","durationMinutes":120,"addr":"米林县派镇"},{"spotId":"S2","name":"雅鲁藏布大峡谷","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"雅鲁藏布大峡谷是雅鲁藏布大峡谷最有代表性的看点，世界最深深峡，换乘游览。攻略把它排进主线，时间留得最足。","notice":"世界最深深峡，换乘游览。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"林芝市"},{"spotId":"S3","name":"鲁朗林海","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"鲁朗林海是雅鲁藏布大峡谷最有代表性的看点，东方瑞士，石锅鸡之乡。攻略把它排进主线，时间留得最足。","notice":"东方瑞士，石锅鸡之乡。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"鲁朗镇"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"鲁朗石锅鸡（人均128元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是鲁朗石锅鸡，石锅鸡总店本地人都认这家，点单照攻略不踩雷。","addr":"鲁朗镇"},{"title":"藏香猪（人均58元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是藏香猪，工布藏餐本地人都认这家，点单照攻略不踩雷。","addr":"派镇"},{"title":"松茸炖藏鸡（人均98元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是松茸炖藏鸡，林芝菌菇宴本地人都认这家，点单照攻略不踩雷。","addr":"林芝市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","相机或运动相机","保温水杯与少量现金","墨镜与拍照道具","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 林芝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙坡头纯攻略·亲子篇5','guide','中卫 · 沙坡头','adventure','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',990,500,9,'沙坡头 / 通湖草原 / 66号公路 —— 纯攻略助你玩透沙坡头精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「沙坡头」两日慢旅行——探险地。中卫硒砂瓜甜到心里。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"宁夏 · 中卫"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴中卫","description":"集合出发，大巴直达沙坡头，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"沙坡头","description":"抵达后首游沙坡头，黄河飞索与羊皮筏子，沙漠骑骆驼。","addr":"中卫市沙坡头区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐硒砂瓜（人均10元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"通湖草原","description":"早起人少，通湖草原精华时段，沙漠营地篝火晚会。","addr":"阿拉善左旗","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐黄河大鲤鱼，人均58元，补充体力。","addr":"景区旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"66号公路","description":"午后游览66号公路，网红沙漠公路打卡。","addr":"中卫市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"沙坡头","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"沙坡头是沙坡头最有代表性的看点，黄河飞索与羊皮筏子，沙漠骑骆驼。攻略把它排进主线，时间留得最足。","notice":"黄河飞索与羊皮筏子，沙漠骑骆驼。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"中卫市沙坡头区"},{"spotId":"S2","name":"通湖草原","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"通湖草原是沙坡头最有代表性的看点，沙漠营地篝火晚会。攻略把它排进主线，时间留得最足。","notice":"沙漠营地篝火晚会。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"阿拉善左旗"},{"spotId":"S3","name":"66号公路","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"66号公路是沙坡头最有代表性的看点，网红沙漠公路打卡。攻略把它排进主线，时间留得最足。","notice":"网红沙漠公路打卡。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"中卫市"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"硒砂瓜（人均10元）","description":"中卫 · 沙坡头的招牌是硒砂瓜，路边瓜摊本地人都认这家，点单照攻略不踩雷。","addr":"沙坡头"},{"title":"黄河大鲤鱼（人均58元）","description":"中卫 · 沙坡头的招牌是黄河大鲤鱼，沙坡头渔村本地人都认这家，点单照攻略不踩雷。","addr":"景区旁"},{"title":"手抓滩羊（人均68元）","description":"中卫 · 沙坡头的招牌是手抓滩羊，夏华火锅本地人都认这家，点单照攻略不踩雷。","addr":"中卫市区"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","身份证件与手机充电宝","相机或运动相机","墨镜与拍照道具","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","保温水杯与少量现金","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滕王阁纯攻略·摄影机位5','guide','南昌 · 滕王阁','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',990,500,5,'滕王阁 / 万寿宫历史文化街区 / 秋水广场 —— 纯攻略助你玩透滕王阁精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「滕王阁」三日深度游——文艺。南昌瓷板画是独特纪念品。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 南昌"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往南昌，抵达后办理入住、熟悉周边环境。","addr":"南昌市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"滕王阁","description":"下午首站滕王阁，调整状态进入旅行节奏，落霞与孤鹜齐名的主阁，登顶看赣江。","addr":"南昌市东湖区仿古街58号","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游南昌一带氛围拉满，晚餐瓦罐汤人均18元。","addr":"万寿宫街区巷口","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"万寿宫历史文化街区","description":"全天主景点万寿宫历史文化街区，夜市烟火气，白天逛老建筑。","addr":"西湖区中山路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐拌粉（人均12元），早点休息。","addr":"中山路支巷","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"秋水广场","description":"收官秋水广场，亚洲最大音乐喷泉群，晚上两场。","addr":"红谷滩区赣江中大道","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐白糖糕后集合返程，三日旅程圆满。","addr":"万寿宫内街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"滕王阁","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"滕王阁是滕王阁最有代表性的看点，落霞与孤鹜齐名的主阁，登顶看赣江。攻略把它排进主线，时间留得最足。","notice":"落霞与孤鹜齐名的主阁，登顶看赣江。这个点位上午光线最好。","durationMinutes":120,"addr":"南昌市东湖区仿古街58号"},{"spotId":"S2","name":"万寿宫历史文化街区","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"万寿宫历史文化街区是滕王阁最有代表性的看点，夜市烟火气，白天逛老建筑。攻略把它排进主线，时间留得最足。","notice":"夜市烟火气，白天逛老建筑。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"西湖区中山路"},{"spotId":"S3","name":"秋水广场","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"秋水广场是滕王阁最有代表性的看点，亚洲最大音乐喷泉群，晚上两场。攻略把它排进主线，时间留得最足。","notice":"亚洲最大音乐喷泉群，晚上两场。这个点位上午光线最好。","durationMinutes":60,"addr":"红谷滩区赣江中大道"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"瓦罐汤（人均18元）","description":"南昌 · 滕王阁的招牌是瓦罐汤，民间瓦罐汤店本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫街区巷口"},{"title":"拌粉（人均12元）","description":"南昌 · 滕王阁的招牌是拌粉，南昌拌粉总店本地人都认这家，点单照攻略不踩雷。","addr":"中山路支巷"},{"title":"白糖糕（人均8元）","description":"南昌 · 滕王阁的招牌是白糖糕，老字号糕点铺本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫内街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","相机或运动相机","常用药品（肠胃药/创可贴）","保温水杯与少量现金","防晒霜与遮阳帽","少量零食补给","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["到达 南昌 的交通方便吗？","推荐先到 南昌，再打车或景区直通车前往核心景区；自驾导航直接搜滕王阁即可。"],["当地有什么必吃？","到了 南昌，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('凤凰古城纯攻略·美食清单5','guide','湘西 · 凤凰古城','ancient_town','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',1990,1000,1,'沱江跳岩 / 沈从文故居 / 南华山 —— 纯攻略助你玩透凤凰古城精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「凤凰古城」两日慢旅行——古镇。凤凰银饰认准足银999。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 湘西"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴湘西","description":"集合出发，大巴直达凤凰古城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"沱江跳岩","description":"抵达后首游沱江跳岩，清晨雾气中的吊脚楼最出片。","addr":"凤凰古城沱江北门","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐血粑鸭（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"沈从文故居","description":"早起人少，沈从文故居精华时段，文学爱好者必打卡，讲解值得请。","addr":"凤凰古城中营街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐苗家酸汤鱼，人均68元，补充体力。","addr":"沱江边吊脚楼","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南华山","description":"午后游览南华山，登高俯瞰全城夜景。","addr":"凤凰城南","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"沱江跳岩","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"沱江跳岩是凤凰古城最有代表性的看点，清晨雾气中的吊脚楼最出片。攻略把它排进主线，时间留得最足。","notice":"清晨雾气中的吊脚楼最出片。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"凤凰古城沱江北门"},{"spotId":"S2","name":"沈从文故居","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"沈从文故居是凤凰古城最有代表性的看点，文学爱好者必打卡，讲解值得请。攻略把它排进主线，时间留得最足。","notice":"文学爱好者必打卡，讲解值得请。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"凤凰古城中营街"},{"spotId":"S3","name":"南华山","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"南华山是凤凰古城最有代表性的看点，登高俯瞰全城夜景。攻略把它排进主线，时间留得最足。","notice":"登高俯瞰全城夜景。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"凤凰城南"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"血粑鸭（人均58元）","description":"湘西 · 凤凰古城的招牌是血粑鸭，凤凰老字号本地人都认这家，点单照攻略不踩雷。","addr":"虹桥东路"},{"title":"苗家酸汤鱼（人均68元）","description":"湘西 · 凤凰古城的招牌是苗家酸汤鱼，古城酸汤鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"沱江边吊脚楼"},{"title":"凤凰姜糖（人均15元）","description":"湘西 · 凤凰古城的招牌是凤凰姜糖，老街姜糖铺本地人都认这家，点单照攻略不踩雷。","addr":"东正街"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","相机或运动相机","保温水杯与少量现金","墨镜与拍照道具","少量零食补给","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 湘西 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大理古城洱海纯攻略·自由行手册5','guide','大理 · 大理古城洱海','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',1990,1000,2,'洱海生态廊道 / 大理古城 / 崇圣寺三塔 —— 纯攻略助你玩透大理古城洱海精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「大理古城洱海」三日深度游——水景。喜洲粑粑现烤的最香。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 大理"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大理，抵达后办理入住、熟悉周边环境。","addr":"大理市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"洱海生态廊道","description":"下午首站洱海生态廊道，调整状态进入旅行节奏，租电动车骑行，S湾拍倒影。","addr":"大理市环海西路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大理一带氛围拉满，晚餐白族三道茶人均48元。","addr":"喜洲古镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大理古城","description":"全天主景点大理古城，洋人街与五华楼，夜晚酒吧街热闹。","addr":"大理市一塔路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐砂锅鱼（人均78元），早点休息。","addr":"才村码头","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"崇圣寺三塔","description":"收官崇圣寺三塔，大理地标，倒影公园拍三塔。","addr":"大理市三塔路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐乳扇后集合返程，三日旅程圆满。","addr":"古城人民路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"洱海生态廊道","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"洱海生态廊道是大理古城洱海最有代表性的看点，租电动车骑行，S湾拍倒影。攻略把它排进主线，时间留得最足。","notice":"租电动车骑行，S湾拍倒影。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大理市环海西路"},{"spotId":"S2","name":"大理古城","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"大理古城是大理古城洱海最有代表性的看点，洋人街与五华楼，夜晚酒吧街热闹。攻略把它排进主线，时间留得最足。","notice":"洋人街与五华楼，夜晚酒吧街热闹。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"大理市一塔路"},{"spotId":"S3","name":"崇圣寺三塔","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"崇圣寺三塔是大理古城洱海最有代表性的看点，大理地标，倒影公园拍三塔。攻略把它排进主线，时间留得最足。","notice":"大理地标，倒影公园拍三塔。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"大理市三塔路"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"白族三道茶（人均48元）","description":"大理 · 大理古城洱海的招牌是白族三道茶，严家大院本地人都认这家，点单照攻略不踩雷。","addr":"喜洲古镇"},{"title":"砂锅鱼（人均78元）","description":"大理 · 大理古城洱海的招牌是砂锅鱼，大理砂锅鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"才村码头"},{"title":"乳扇（人均12元）","description":"大理 · 大理古城洱海的招牌是乳扇，杨记乳扇本地人都认这家，点单照攻略不踩雷。","addr":"古城人民路"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","少量零食补给","相机或运动相机","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 大理 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九寨沟纯攻略·省钱玩法5','guide','阿坝 · 九寨沟','water','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',1990,1000,2,'五花海 / 诺日朗瀑布 / 长海 —— 纯攻略助你玩透九寨沟精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九寨沟」两日慢旅行——水景。九寨沟牦牛酸奶值得尝。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达九寨沟，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"五花海","description":"抵达后首游五花海，九寨精华，孔雀河道顺光最美。","addr":"九寨沟县漳扎镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐牦牛肉汤锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"诺日朗瀑布","description":"早起人少，诺日朗瀑布精华时段，中国最宽钙华瀑布。","addr":"九寨沟中心站","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐青稞酒，人均30元，补充体力。","addr":"藏寨","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"长海","description":"午后游览长海，最大海子，雪山倒影。","addr":"九寨沟则查洼沟","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"五花海","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"五花海是九寨沟最有代表性的看点，九寨精华，孔雀河道顺光最美。攻略把它排进主线，时间留得最足。","notice":"九寨精华，孔雀河道顺光最美。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"九寨沟县漳扎镇"},{"spotId":"S2","name":"诺日朗瀑布","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"诺日朗瀑布是九寨沟最有代表性的看点，中国最宽钙华瀑布。攻略把它排进主线，时间留得最足。","notice":"中国最宽钙华瀑布。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"九寨沟中心站"},{"spotId":"S3","name":"长海","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"长海是九寨沟最有代表性的看点，最大海子，雪山倒影。攻略把它排进主线，时间留得最足。","notice":"最大海子，雪山倒影。这个点位上午光线最好。","durationMinutes":90,"addr":"九寨沟则查洼沟"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉汤锅（人均78元）","description":"阿坝 · 九寨沟的招牌是牦牛肉汤锅，沟口藏家本地人都认这家，点单照攻略不踩雷。","addr":"漳扎镇"},{"title":"青稞酒（人均30元）","description":"阿坝 · 九寨沟的招牌是青稞酒，藏家体验本地人都认这家，点单照攻略不踩雷。","addr":"藏寨"},{"title":"糌粑（人均20元）","description":"阿坝 · 九寨沟的招牌是糌粑，藏族人家本地人都认这家，点单照攻略不踩雷。","addr":"树正寨"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","相机或运动相机","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 阿坝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('荔波小七孔纯攻略·避坑版5','guide','黔南 · 荔波小七孔','water','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',990,500,2,'小七孔古桥 / 卧龙潭 / 大七孔 —— 纯攻略助你玩透荔波小七孔精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「荔波小七孔」三日深度游——水景。荔波青梅制品酸甜开胃。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黔南，抵达后办理入住、熟悉周边环境。","addr":"黔南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"小七孔古桥","description":"下午首站小七孔古桥，调整状态进入旅行节奏，68级跌水瀑布起点，绿宝石湖水。","addr":"荔波县小七孔镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黔南一带氛围拉满，晚餐酸汤鱼人均68元。","addr":"荔波县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"卧龙潭","description":"全天主景点卧龙潭，蓝到不真实的深潭，漂流出片。","addr":"小七孔景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐杨梅汤（人均10元），早点休息。","addr":"小七孔镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"大七孔","description":"收官大七孔，天生桥鬼斧神工。","addr":"荔波县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糯米排骨后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"小七孔古桥","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"小七孔古桥是荔波小七孔最有代表性的看点，68级跌水瀑布起点，绿宝石湖水。攻略把它排进主线，时间留得最足。","notice":"68级跌水瀑布起点，绿宝石湖水。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"荔波县小七孔镇"},{"spotId":"S2","name":"卧龙潭","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"卧龙潭是荔波小七孔最有代表性的看点，蓝到不真实的深潭，漂流出片。攻略把它排进主线，时间留得最足。","notice":"蓝到不真实的深潭，漂流出片。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"小七孔景区"},{"spotId":"S3","name":"大七孔","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"大七孔是荔波小七孔最有代表性的看点，天生桥鬼斧神工。攻略把它排进主线，时间留得最足。","notice":"天生桥鬼斧神工。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"荔波县"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均68元）","description":"黔南 · 荔波小七孔的招牌是酸汤鱼，凯里酸汤鱼本地人都认这家，点单照攻略不踩雷。","addr":"荔波县城"},{"title":"杨梅汤（人均10元）","description":"黔南 · 荔波小七孔的招牌是杨梅汤，街边饮品本地人都认这家，点单照攻略不踩雷。","addr":"小七孔镇"},{"title":"糯米排骨（人均42元）","description":"黔南 · 荔波小七孔的招牌是糯米排骨，布依农家本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":445,"required":false},{"name":"住宿参考","amount":346,"required":false},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","相机或运动相机","轻便雨衣或折叠伞","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 黔南 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('涠洲岛纯攻略·深度指南5','guide','北海 · 涠洲岛','sea','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,6,'鳄鱼山火山公园 / 五彩滩 / 滴水丹屏 —— 纯攻略助你玩透涠洲岛精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「涠洲岛」两日慢旅行——海滨。涠洲岛香蕉又软又甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 北海"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴北海","description":"集合出发，大巴直达涠洲岛，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"鳄鱼山火山公园","description":"抵达后首游鳄鱼山火山公园，火山地质地貌，灯塔海景。","addr":"涠洲岛南湾","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐海鲜大餐（人均98元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"五彩滩","description":"早起人少，五彩滩精华时段，退潮时火山岩纹理最美。","addr":"涠洲岛东岸","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香蕉猪，人均58元，补充体力。","addr":"滴水村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"滴水丹屏","description":"午后游览滴水丹屏，日落圣地，海水退潮捡贝壳。","addr":"涠洲岛西侧","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"鳄鱼山火山公园","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"鳄鱼山火山公园是涠洲岛最有代表性的看点，火山地质地貌，灯塔海景。攻略把它排进主线，时间留得最足。","notice":"火山地质地貌，灯塔海景。这个点位上午光线最好。","durationMinutes":180,"addr":"涠洲岛南湾"},{"spotId":"S2","name":"五彩滩","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"五彩滩是涠洲岛最有代表性的看点，退潮时火山岩纹理最美。攻略把它排进主线，时间留得最足。","notice":"退潮时火山岩纹理最美。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"涠洲岛东岸"},{"spotId":"S3","name":"滴水丹屏","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"滴水丹屏是涠洲岛最有代表性的看点，日落圣地，海水退潮捡贝壳。攻略把它排进主线，时间留得最足。","notice":"日落圣地，海水退潮捡贝壳。这个点位上午光线最好。","durationMinutes":90,"addr":"涠洲岛西侧"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜大餐（人均98元）","description":"北海 · 涠洲岛的招牌是海鲜大餐，南湾海鲜市场加工本地人都认这家，点单照攻略不踩雷。","addr":"南湾街"},{"title":"香蕉猪（人均58元）","description":"北海 · 涠洲岛的招牌是香蕉猪，岛民农家本地人都认这家，点单照攻略不踩雷。","addr":"滴水村"},{"title":"椰子冻（人均15元）","description":"北海 · 涠洲岛的招牌是椰子冻，夜市摊本地人都认这家，点单照攻略不踩雷。","addr":"南湾夜市"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","少量零食补给","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('西湖灵隐纯攻略·周末版5','guide','杭州 · 西湖灵隐','water','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1990,1000,2,'西湖断桥苏堤 / 灵隐寺飞来峰 / 龙井村 —— 纯攻略助你玩透西湖灵隐精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「西湖灵隐」三日深度游——水景。明前龙井茶农直购最划算。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约6000步，爬升平缓","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 杭州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往杭州，抵达后办理入住、熟悉周边环境。","addr":"杭州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"西湖断桥苏堤","description":"下午首站西湖断桥苏堤，调整状态进入旅行节奏，清晨环湖骑行，断桥残雪碑打卡。","addr":"杭州市西湖区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游杭州一带氛围拉满，晚餐西湖醋鱼人均98元。","addr":"孤山路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"灵隐寺飞来峰","description":"全天主景点灵隐寺飞来峰，石窟造像与古刹，香火鼎盛。","addr":"西湖区灵隐路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐龙井虾仁（人均58元），早点休息。","addr":"西湖天地","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"龙井村","description":"收官龙井村，茶山徒步至九溪十八涧。","addr":"西湖区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐片儿川后集合返程，三日旅程圆满。","addr":"中山中路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"西湖断桥苏堤","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"西湖断桥苏堤是西湖灵隐最有代表性的看点，清晨环湖骑行，断桥残雪碑打卡。攻略把它排进主线，时间留得最足。","notice":"清晨环湖骑行，断桥残雪碑打卡。拍照记得留神脚下台阶。","du