INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('夫子庙中山陵纯攻略·亲子篇5','guide','南京 · 夫子庙中山陵','red','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',2990,1600,7,'中山陵 / 夫子庙秦淮河 / 明孝陵石象路 —— 纯攻略助你玩透夫子庙中山陵精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「夫子庙中山陵」两日慢旅行——人文。南京雨花石送小朋友最爱。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约8000步","transitText":"攻略含大交通方案","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 南京"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南京","description":"集合出发，大巴直达夫子庙中山陵，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"中山陵","description":"抵达后首游中山陵，392级台阶，民国气势。","addr":"南京市玄武区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐盐水鸭（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"夫子庙秦淮河","description":"早起人少，夫子庙秦淮河精华时段，夜泊秦淮，画舫灯影。","addr":"秦淮区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐鸭血粉丝汤，人均18元，补充体力。","addr":"老门东","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"明孝陵石象路","description":"午后游览明孝陵石象路，秋日梧桐大道封神。","addr":"玄武区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"中山陵","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"中山陵是夫子庙中山陵最有代表性的看点，392级台阶，民国气势。攻略把它排进主线，时间留得最足。","notice":"392级台阶，民国气势。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"南京市玄武区"},{"spotId":"S2","name":"夫子庙秦淮河","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"夫子庙秦淮河是夫子庙中山陵最有代表性的看点，夜泊秦淮，画舫灯影。攻略把它排进主线，时间留得最足。","notice":"夜泊秦淮，画舫灯影。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"秦淮区"},{"spotId":"S3","name":"明孝陵石象路","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"明孝陵石象路是夫子庙中山陵最有代表性的看点，秋日梧桐大道封神。攻略把它排进主线，时间留得最足。","notice":"秋日梧桐大道封神。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"玄武区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"盐水鸭（人均45元）","description":"南京 · 夫子庙中山陵的招牌是盐水鸭，桂花鸭专卖店本地人都认这家，点单照攻略不踩雷。","addr":"夫子庙"},{"title":"鸭血粉丝汤（人均18元）","description":"南京 · 夫子庙中山陵的招牌是鸭血粉丝汤，回味本地人都认这家，点单照攻略不踩雷。","addr":"老门东"},{"title":"汤包（人均22元）","description":"南京 · 夫子庙中山陵的招牌是汤包，鸡鸣汤包本地人都认这家，点单照攻略不踩雷。","addr":"科巷"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","少量零食补给","保温水杯与少量现金","相机或运动相机","换洗衣物与外套（早晚温差）","墨镜与拍照道具","常用药品（肠胃药/创可贴）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 南京 的交通方便吗？","推荐先到 南京，再打车或景区直通车前往核心景区；自驾导航直接搜夫子庙中山陵即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武当山纯攻略·摄影机位5','guide','十堰 · 武当山','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',2990,1600,2,'金顶 / 南岩宫 / 紫霄宫 —— 纯攻略助你玩透武当山精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「武当山」三日深度游——山岳。武当道茶甘醇。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 十堰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往十堰，抵达后办理入住、熟悉周边环境。","addr":"十堰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，武当之巅金殿，转运台。","addr":"十堰市丹江口","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游十堰一带氛围拉满，晚餐道家素斋人均48元。","addr":"武当山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"南岩宫","description":"全天主景点南岩宫，龙头香悬崖奇观。","addr":"武当山南岩","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐武当冻豆腐（人均38元），早点休息。","addr":"南岩","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"紫霄宫","description":"收官紫霄宫，皇家道观规制。","addr":"武当山展旗峰","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐太极养生汤后集合返程，三日旅程圆满。","addr":"紫霄宫旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武当山最有代表性的看点，武当之巅金殿，转运台。攻略把它排进主线，时间留得最足。","notice":"武当之巅金殿，转运台。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"十堰市丹江口"},{"spotId":"S2","name":"南岩宫","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"南岩宫是武当山最有代表性的看点，龙头香悬崖奇观。攻略把它排进主线，时间留得最足。","notice":"龙头香悬崖奇观。这个点位上午光线最好。","durationMinutes":120,"addr":"武当山南岩"},{"spotId":"S3","name":"紫霄宫","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"紫霄宫是武当山最有代表性的看点，皇家道观规制。攻略把它排进主线，时间留得最足。","notice":"皇家道观规制。这个点位上午光线最好。","durationMinutes":90,"addr":"武当山展旗峰"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"道家素斋（人均48元）","description":"十堰 · 武当山的招牌是道家素斋，太子坡素斋本地人都认这家，点单照攻略不踩雷。","addr":"武当山镇"},{"title":"武当冻豆腐（人均38元）","description":"十堰 · 武当山的招牌是武当冻豆腐，山间餐馆本地人都认这家，点单照攻略不踩雷。","addr":"南岩"},{"title":"太极养生汤（人均68元）","description":"十堰 · 武当山的招牌是太极养生汤，道医药膳本地人都认这家，点单照攻略不踩雷。","addr":"紫霄宫旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":1345,"required":false},{"name":"住宿参考","amount":1046,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","墨镜与拍照道具","保温水杯与少量现金","身份证件与手机充电宝","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["到达 十堰 的交通方便吗？","推荐先到 十堰，再打车或景区直通车前往核心景区；自驾导航直接搜武当山即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
