INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('太湖鼋头渚纯攻略·深度指南5','guide','无锡 · 太湖鼋头渚','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',1990,1000,2,'鼋头渚 / 灵山大佛 / 南长街 —— 纯攻略助你玩透太湖鼋头渚精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「太湖鼋头渚」两日慢旅行——水景。惠山泥人阿福最喜庆。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约10000步","transitText":"攻略含大交通方案","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 无锡"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴无锡","description":"集合出发，大巴直达太湖鼋头渚，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"鼋头渚","description":"抵达后首游鼋头渚，太湖第一名胜，樱花季封神。","addr":"无锡市滨湖区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐无锡小笼（人均22元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"灵山大佛","description":"早起人少，灵山大佛精华时段，88米大佛，梵宫震撼。","addr":"滨湖区马山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酱排骨，人均48元，补充体力。","addr":"中山路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南长街","description":"午后游览南长街，古运河夜色，清名桥倒影。","addr":"梁溪区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"鼋头渚","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"鼋头渚是太湖鼋头渚最有代表性的看点，太湖第一名胜，樱花季封神。攻略把它排进主线，时间留得最足。","notice":"太湖第一名胜，樱花季封神。这个点位上午光线最好。","durationMinutes":180,"addr":"无锡市滨湖区"},{"spotId":"S2","name":"灵山大佛","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"灵山大佛是太湖鼋头渚最有代表性的看点，88米大佛，梵宫震撼。攻略把它排进主线，时间留得最足。","notice":"88米大佛，梵宫震撼。这个点位上午光线最好。","durationMinutes":180,"addr":"滨湖区马山"},{"spotId":"S3","name":"南长街","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"南长街是太湖鼋头渚最有代表性的看点，古运河夜色，清名桥倒影。攻略把它排进主线，时间留得最足。","notice":"古运河夜色，清名桥倒影。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"梁溪区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"无锡小笼（人均22元）","description":"无锡 · 太湖鼋头渚的招牌是无锡小笼，熙盛源本地人都认这家，点单照攻略不踩雷。","addr":"南禅寺"},{"title":"酱排骨（人均48元）","description":"无锡 · 太湖鼋头渚的招牌是酱排骨，三凤桥本地人都认这家，点单照攻略不踩雷。","addr":"中山路"},{"title":"太湖三白（人均98元）","description":"无锡 · 太湖鼋头渚的招牌是太湖三白，渔人码头本地人都认这家，点单照攻略不踩雷。","addr":"鼋头渚旁"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":895,"required":false},{"name":"住宿参考","amount":696,"required":false},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","墨镜与拍照道具","防晒霜与遮阳帽","相机或运动相机","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["几月份去 无锡 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 无锡，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九宫山隐水洞纯攻略·周末版5','guide','咸宁 · 九宫山隐水洞','mountain','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',1500,800,2,'九宫山 / 隐水洞 / 刘家桥古民居 —— 纯攻略助你玩透九宫山隐水洞精髓','["逐时段行程攻略", "美食避坑清单", "交通购票指南"]','{"overview":"「九宫山隐水洞」三日深度游——山岳。咸宁桂花蜜香甜。本攻略按guide玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"行程自理，攻略给你完整路线图","walkText":"累计步行约12000步，量力而行","transitText":"攻略含大交通方案","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 咸宁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"纯攻略（行程自理）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往咸宁，抵达后办理入住、熟悉周边环境。","addr":"咸宁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"九宫山","description":"下午首站九宫山，调整状态进入旅行节奏，云中湖避暑胜地，闯王陵。","addr":"咸宁市通山县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游咸宁一带氛围拉满，晚餐贺胜桥鸡汤人均58元。","addr":"咸安区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"隐水洞","description":"全天主景点隐水洞，水路旱路双游线溶洞。","addr":"通山县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐桂花糕（人均15元），早点休息。","addr":"温泉城区","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"刘家桥古民居","description":"收官刘家桥古民居，明清廊桥古民居。","addr":"咸安区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐通山合菜面后集合返程，三日旅程圆满。","addr":"通山县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"九宫山","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"九宫山是九宫山隐水洞最有代表性的看点，云中湖避暑胜地，闯王陵。攻略把它排进主线，时间留得最足。","notice":"云中湖避暑胜地，闯王陵。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"咸宁市通山县"},{"spotId":"S2","name":"隐水洞","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"隐水洞是九宫山隐水洞最有代表性的看点，水路旱路双游线溶洞。攻略把它排进主线，时间留得最足。","notice":"水路旱路双游线溶洞。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"通山县"},{"spotId":"S3","name":"刘家桥古民居","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"刘家桥古民居是九宫山隐水洞最有代表性的看点，明清廊桥古民居。攻略把它排进主线，时间留得最足。","notice":"明清廊桥古民居。这个点位上午光线最好。","durationMinutes":90,"addr":"咸安区"}],"transport":[{"title":"往返交通","description":"攻略含大交通方案，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"贺胜桥鸡汤（人均58元）","description":"咸宁 · 九宫山隐水洞的招牌是贺胜桥鸡汤，贺胜桥土鸡馆本地人都认这家，点单照攻略不踩雷。","addr":"咸安区"},{"title":"桂花糕（人均15元）","description":"咸宁 · 九宫山隐水洞的招牌是桂花糕，桂花之乡本地人都认这家，点单照攻略不踩雷。","addr":"温泉城区"},{"title":"通山合菜面（人均28元）","description":"咸宁 · 九宫山隐水洞的招牌是通山合菜面，通山农家本地人都认这家，点单照攻略不踩雷。","addr":"通山县"}],"lodging":[{"title":"住宿建议","description":"推荐住宿片区周边特色民宿/酒店，建议选评分4.8以上，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":false},{"name":"门票参考","amount":675,"required":false},{"name":"住宿参考","amount":525,"required":false},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","少量零食补给","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 咸宁 的交通方便吗？","推荐先到 咸宁，再打车或景区直通车前往核心景区；自驾导航直接搜九宫山隐水洞即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('壶口瀑布微度假一日','nearby','延安 · 壶口瀑布','red','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',24300,13300,7,'壶口瀑布 / 宝塔山 / 枣园革命旧址 —— 一张票打包壶口瀑布精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「壶口瀑布」一日轻旅行——人文。延安小米熬粥最养人。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 延安"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"延安集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"壶口瀑布游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"壶口瀑布","description":"首站直达壶口瀑布，黄河之水天上来，旱地行船遗址。建议停留120分钟，跟着攻略动线走省一半时间。","addr":"延安市宜川县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排延安小吃——人均约10元，油馍馍是本地招牌，点菜照着攻略走。","addr":"枣园路口","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"宝塔山","description":"午后游览宝塔山，延安地标灯光秀。","addr":"延安市宝塔区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"枣园革命旧址","description":"收官打卡枣园革命旧址，窑洞与历史课堂。随后自由活动，采购伴手礼。","addr":"宝塔区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"壶口瀑布","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"壶口瀑布是壶口瀑布最有代表性的看点，黄河之水天上来，旱地行船遗址。攻略把它排进主线，时间留得最足。","notice":"黄河之水天上来，旱地行船遗址。这个点位上午光线最好。","durationMinutes":150,"addr":"延安市宜川县"},{"spotId":"S2","name":"宝塔山","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"宝塔山是壶口瀑布最有代表性的看点，延安地标灯光秀。攻略把它排进主线，时间留得最足。","notice":"延安地标灯光秀。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"延安市宝塔区"},{"spotId":"S3","name":"枣园革命旧址","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"枣园革命旧址是壶口瀑布最有代表性的看点，窑洞与历史课堂。攻略把它排进主线，时间留得最足。","notice":"窑洞与历史课堂。这个点位上午光线最好。","durationMinutes":120,"addr":"宝塔区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"油馍馍（人均10元）","description":"延安 · 壶口瀑布的招牌是油馍馍，延安小吃本地人都认这家，点单照攻略不踩雷。","addr":"枣园路口"},{"title":"羊杂碎（人均25元）","description":"延安 · 壶口瀑布的招牌是羊杂碎，陕北羊汤馆本地人都认这家，点单照攻略不踩雷。","addr":"宝塔区"},{"title":"洋芋擦擦（人均18元）","description":"延安 · 壶口瀑布的招牌是洋芋擦擦，陕北农家本地人都认这家，点单照攻略不踩雷。","addr":"宜川县城"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10935,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","少量零食补给","墨镜与拍照道具","常用药品（肠胃药/创可贴）","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('避暑山庄慢游一日','nearby','承德 · 避暑山庄','village','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',22100,12100,1,'避暑山庄 / 普宁寺 / 磬锤峰 —— 一张票打包避暑山庄精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「避暑山庄」一日轻旅行——古村落。承德木雕核桃吉祥。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河北 · 承德"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"承德集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"避暑山庄游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"避暑山庄","description":"首站直达避暑山庄，皇家园林之最，山区乘车看小布达拉。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"承德市双桥区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排老三羊汤——人均约38元，御土荷叶鸡是本地招牌，点菜照着攻略走。","addr":"承德市区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"普宁寺","description":"午后游览普宁寺，大佛寺千手千眼观音。","addr":"承德市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"磬锤峰","description":"收官打卡磬锤峰，棒槌山奇观，索道往返。随后自由活动，采购伴手礼。","addr":"承德市","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"避暑山庄","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"避暑山庄是避暑山庄最有代表性的看点，皇家园林之最，山区乘车看小布达拉。攻略把它排进主线，时间留得最足。","notice":"皇家园林之最，山区乘车看小布达拉。这个点位上午光线最好。","durationMinutes":240,"addr":"承德市双桥区"},{"spotId":"S2","name":"普宁寺","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"普宁寺是避暑山庄最有代表性的看点，大佛寺千手千眼观音。攻略把它排进主线，时间留得最足。","notice":"大佛寺千手千眼观音。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"承德市"},{"spotId":"S3","name":"磬锤峰","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"磬锤峰是避暑山庄最有代表性的看点，棒槌山奇观，索道往返。攻略把它排进主线，时间留得最足。","notice":"棒槌山奇观，索道往返。这个点位上午光线最好。","durationMinutes":90,"addr":"承德市"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"御土荷叶鸡（人均38元）","description":"承德 · 避暑山庄的招牌是御土荷叶鸡，老三羊汤本地人都认这家，点单照攻略不踩雷。","addr":"承德市区"},{"title":"荞面饸饹（人均18元）","description":"承德 · 避暑山庄的招牌是荞面饸饹，莜面馆本地人都认这家，点单照攻略不踩雷。","addr":"山庄东路"},{"title":"杏仁茶（人均10元）","description":"承德 · 避暑山庄的招牌是杏仁茶，小吃街本地人都认这家，点单照攻略不踩雷。","addr":"二仙居"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9945,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机","少量零食补给","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('日月湾冲浪轻徒步一日','nearby','万宁 · 日月湾冲浪','sea','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',23600,12900,6,'日月湾 / 石梅湾 / 兴隆热带植物园 —— 一张票打包日月湾冲浪精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「日月湾冲浪」一日轻旅行——海滨。兴隆炭烧咖啡回香浓。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 万宁"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"万宁集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"日月湾冲浪游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"日月湾","description":"首站直达日月湾，国家冲浪队训练地，新手教程2小时。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"万宁市礼纪镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排渔家海鲜——人均约88元，和乐蟹是本地招牌，点菜照着攻略走。","addr":"东澳镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"石梅湾","description":"午后游览石梅湾，加井岛浮潜，凤凰九里书屋。","addr":"万宁市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"兴隆热带植物园","description":"收官打卡兴隆热带植物园，咖啡可可巧克力之旅。随后自由活动，采购伴手礼。","addr":"兴隆镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"日月湾","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"日月湾是日月湾冲浪最有代表性的看点，国家冲浪队训练地，新手教程2小时。攻略把它排进主线，时间留得最足。","notice":"国家冲浪队训练地，新手教程2小时。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"万宁市礼纪镇"},{"spotId":"S2","name":"石梅湾","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"石梅湾是日月湾冲浪最有代表性的看点，加井岛浮潜，凤凰九里书屋。攻略把它排进主线，时间留得最足。","notice":"加井岛浮潜，凤凰九里书屋。这个点位上午光线最好。","durationMinutes":180,"addr":"万宁市"},{"spotId":"S3","name":"兴隆热带植物园","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"兴隆热带植物园是日月湾冲浪最有代表性的看点，咖啡可可巧克力之旅。攻略把它排进主线，时间留得最足。","notice":"咖啡可可巧克力之旅。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"兴隆镇"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"和乐蟹（人均88元）","description":"万宁 · 日月湾冲浪的招牌是和乐蟹，渔家海鲜本地人都认这家，点单照攻略不踩雷。","addr":"东澳镇"},{"title":"东山羊（人均88元）","description":"万宁 · 日月湾冲浪的招牌是东山羊，东山羊庄本地人都认这家，点单照攻略不踩雷。","addr":"万城镇"},{"title":"兴隆咖啡（人均25元）","description":"万宁 · 日月湾冲浪的招牌是兴隆咖啡，咖啡庄园本地人都认这家，点单照攻略不踩雷。","addr":"兴隆镇"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10620,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","保温水杯与少量现金"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('喀纳斯精华一日','nearby','阿勒泰 · 喀纳斯','water','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',24100,13200,2,'喀纳斯湖 / 禾木村 / 白哈巴 —— 一张票打包喀纳斯精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「喀纳斯」一日轻旅行——水景。喀纳斯冷水鱼干风味独特。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 阿勒泰"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"阿勒泰集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"喀纳斯游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"喀纳斯湖","description":"首站直达喀纳斯湖，三湾晨雾与湖怪传说，观鱼台俯瞰。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"布尔津县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排图瓦人家——人均约128元，烤全羊是本地招牌，点菜照着攻略走。","addr":"禾木村","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"禾木村","description":"午后游览禾木村，图瓦人村落，白桦林晨雾。","addr":"喀纳斯景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"白哈巴","description":"收官打卡白哈巴，中哈边境原始村落。随后自由活动，采购伴手礼。","addr":"哈巴河县","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"喀纳斯湖","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"喀纳斯湖是喀纳斯最有代表性的看点，三湾晨雾与湖怪传说，观鱼台俯瞰。攻略把它排进主线，时间留得最足。","notice":"三湾晨雾与湖怪传说，观鱼台俯瞰。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"布尔津县"},{"spotId":"S2","name":"禾木村","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"禾木村是喀纳斯最有代表性的看点，图瓦人村落，白桦林晨雾。攻略把它排进主线，时间留得最足。","notice":"图瓦人村落，白桦林晨雾。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"喀纳斯景区"},{"spotId":"S3","name":"白哈巴","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"白哈巴是喀纳斯最有代表性的看点，中哈边境原始村落。攻略把它排进主线，时间留得最足。","notice":"中哈边境原始村落。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"哈巴河县"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤全羊（人均128元）","description":"阿勒泰 · 喀纳斯的招牌是烤全羊，图瓦人家本地人都认这家，点单照攻略不踩雷。","addr":"禾木村"},{"title":"手抓饭（人均35元）","description":"阿勒泰 · 喀纳斯的招牌是手抓饭，别克餐厅本地人都认这家，点单照攻略不踩雷。","addr":"贾登峪"},{"title":"奶茶（人均20元）","description":"阿勒泰 · 喀纳斯的招牌是奶茶，哈萨克毡房本地人都认这家，点单照攻略不踩雷。","addr":"白哈巴"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10845,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽","身份证件与手机充电宝","相机或运动相机","换洗衣物与外套（早晚温差）","少量零食补给","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 阿勒泰，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 阿勒泰 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
