INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武功山纯玩直通车','nearby','萍乡 · 武功山','mountain','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',15600,8500,2,'金顶 / 发云界 / 玻璃栈道 —— 一张票打包武功山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「武功山」一日轻旅行——山岳。武功山泉水豆腐宴别错过。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"萍乡集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"武功山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"金顶","description":"首站直达金顶，日出云海核心位，山顶比山下冷10度。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"武功山风景区金顶","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排山脚菜馆——人均约42元，萍乡小炒肉是本地招牌，点菜照着攻略走。","addr":"武功山游客中心旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"发云界","description":"午后游览发云界，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"玻璃栈道","description":"收官打卡玻璃栈道，栈道限流，旺季排30分钟。随后自由活动，采购伴手礼。","addr":"武功山吊马桩","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7020,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
