INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('崀山出片打卡线','nearby','邵阳 · 崀山','adventure','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',24700,13500,9,'辣椒峰 / 天一巷 / 扶夷江竹筏 —— 一张票打包崀山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「崀山」一日轻旅行——探险地。新宁脐橙秋冬正当季。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 邵阳"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"邵阳集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"崀山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"辣椒峰","description":"首站直达辣椒峰，丹霞地貌标志峰，远观近爬两相宜。建议停留120分钟，跟着攻略动线走省一半时间。","addr":"新宁县崀山景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排农家菜馆——人均约52元，崀山腊肉是本地招牌，点菜照着攻略走。","addr":"崀山镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"天一巷","description":"午后游览天一巷，一线天最窄处仅33厘米。","addr":"崀山丹霞巷谷","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"扶夷江竹筏","description":"收官打卡扶夷江竹筏，竹筏漂流看丹霞倒影。随后自由活动，采购伴手礼。","addr":"崀山水上游线","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"辣椒峰","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"辣椒峰是崀山最有代表性的看点，丹霞地貌标志峰，远观近爬两相宜。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌标志峰，远观近爬两相宜。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"新宁县崀山景区"},{"spotId":"S2","name":"天一巷","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"天一巷是崀山最有代表性的看点，一线天最窄处仅33厘米。攻略把它排进主线，时间留得最足。","notice":"一线天最窄处仅33厘米。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"崀山丹霞巷谷"},{"spotId":"S3","name":"扶夷江竹筏","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"扶夷江竹筏是崀山最有代表性的看点，竹筏漂流看丹霞倒影。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流看丹霞倒影。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"崀山水上游线"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"崀山腊肉（人均52元）","description":"邵阳 · 崀山的招牌是崀山腊肉，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"崀山镇"},{"title":"血酱鸭（人均58元）","description":"邵阳 · 崀山的招牌是血酱鸭，邵阳风味馆本地人都认这家，点单照攻略不踩雷。","addr":"新宁县城"},{"title":"脐橙（人均10元）","description":"邵阳 · 崀山的招牌是脐橙，果园直购本地人都认这家，点单照攻略不踩雷。","addr":"崀山脚下果园"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":11115,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","相机或运动相机","保温水杯与少量现金","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('告庄西双景亲子轻松线','nearby','西双版纳 · 告庄西双景','sea','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',27400,15000,6,'告庄星光夜市 / 曼听公园 / 中科院热带植物园 —— 一张票打包告庄西双景精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「告庄西双景」一日轻旅行——海滨。版纳小粒咖啡香浓不酸。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 西双版纳"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"西双版纳集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"告庄西双景游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"告庄星光夜市","description":"首站直达告庄星光夜市，大金塔下的东南亚最大夜市。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"景洪市告庄西双景","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排夜市傣味摊——人均约25元，菠萝饭是本地招牌，点菜照着攻略走。","addr":"星光夜市","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"曼听公园","description":"午后游览曼听公园，总佛寺相邻，晚场篝火晚会。","addr":"景洪市曼听路","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"中科院热带植物园","description":"收官打卡中科院热带植物园，王莲上坐一坐，热气球拍照。随后自由活动，采购伴手礼。","addr":"勐腊县勐仑镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"告庄星光夜市","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"告庄星光夜市是告庄西双景最有代表性的看点，大金塔下的东南亚最大夜市。攻略把它排进主线，时间留得最足。","notice":"大金塔下的东南亚最大夜市。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"景洪市告庄西双景"},{"spotId":"S2","name":"曼听公园","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"曼听公园是告庄西双景最有代表性的看点，总佛寺相邻，晚场篝火晚会。攻略把它排进主线，时间留得最足。","notice":"总佛寺相邻，晚场篝火晚会。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"景洪市曼听路"},{"spotId":"S3","name":"中科院热带植物园","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"中科院热带植物园是告庄西双景最有代表性的看点，王莲上坐一坐，热气球拍照。攻略把它排进主线，时间留得最足。","notice":"王莲上坐一坐，热气球拍照。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"勐腊县勐仑镇"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"菠萝饭（人均25元）","description":"西双版纳 · 告庄西双景的招牌是菠萝饭，夜市傣味摊本地人都认这家，点单照攻略不踩雷。","addr":"星光夜市"},{"title":"香茅草烤鱼（人均48元）","description":"西双版纳 · 告庄西双景的招牌是香茅草烤鱼，曼飞龙烤鸡本地人都认这家，点单照攻略不踩雷。","addr":"告庄内"},{"title":"泡鲁达（人均15元）","description":"西双版纳 · 告庄西双景的招牌是泡鲁达，傣家甜品店本地人都认这家，点单照攻略不踩雷。","addr":"大金塔旁"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12330,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","墨镜与拍照道具","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 西双版纳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 西双版纳 的交通方便吗？","推荐先到 西双版纳，再打车或景区直通车前往核心景区；自驾导航直接搜告庄西双景即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一程，山水都在替你说话。','on');
