INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('镇远古镇微度假一日','nearby','黔东南 · 镇远古镇','ancient_town','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',24600,13500,1,'青龙洞 / 舞阳河 / 石屏山 —— 一张票打包镇远古镇精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「镇远古镇」一日轻旅行——古镇。镇远蓝染布艺越洗越好看。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"黔东南集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"镇远古镇游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"青龙洞","description":"首站直达青龙洞，贴崖古建筑群，对望古城。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"镇远县中和山","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排古城酸汤馆——人均约58元，酸汤鱼是本地招牌，点菜照着攻略走。","addr":"兴隆街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"舞阳河","description":"午后游览舞阳河，乘船看孔雀开屏峰。","addr":"镇远县","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"石屏山","description":"收官打卡石屏山，俯瞰太极古城全景。随后自由活动，采购伴手礼。","addr":"古城北侧","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"青龙洞","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"青龙洞是镇远古镇最有代表性的看点，贴崖古建筑群，对望古城。攻略把它排进主线，时间留得最足。","notice":"贴崖古建筑群，对望古城。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"镇远县中和山"},{"spotId":"S2","name":"舞阳河","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"舞阳河是镇远古镇最有代表性的看点，乘船看孔雀开屏峰。攻略把它排进主线，时间留得最足。","notice":"乘船看孔雀开屏峰。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"镇远县"},{"spotId":"S3","name":"石屏山","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"石屏山是镇远古镇最有代表性的看点，俯瞰太极古城全景。攻略把它排进主线，时间留得最足。","notice":"俯瞰太极古城全景。这个点位上午光线最好。","durationMinutes":120,"addr":"古城北侧"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均58元）","description":"黔东南 · 镇远古镇的招牌是酸汤鱼，古城酸汤馆本地人都认这家，点单照攻略不踩雷。","addr":"兴隆街"},{"title":"陈年道菜（人均30元）","description":"黔东南 · 镇远古镇的招牌是陈年道菜，老字号本地人都认这家，点单照攻略不踩雷。","addr":"古镇主街"},{"title":"苗家腊肉（人均48元）","description":"黔东南 · 镇远古镇的招牌是苗家腊肉，河畔农家本地人都认这家，点单照攻略不踩雷。","addr":"舞阳河畔"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":11070,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","少量零食补给","相机或运动相机","墨镜与拍照道具"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('鼓浪屿慢游一日','nearby','厦门 · 鼓浪屿','sea','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',23000,12600,6,'日光岩 / 菽庄花园 / 沙坡尾 —— 一张票打包鼓浪屿精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「鼓浪屿」一日轻旅行——海滨。厦门馅饼老字号最正宗。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 厦门"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"厦门集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"鼓浪屿游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"日光岩","description":"首站直达日光岩，全岛最高点看红瓦绿树海景。建议停留72分钟，跟着攻略动线走省一半时间。","addr":"鼓浪屿龙头山路","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排乌糖沙茶面——人均约28元，沙茶面是本地招牌，点菜照着攻略走。","addr":"民族路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"菽庄花园","description":"午后游览菽庄花园，四十四桥跨海，钢琴博物馆。","addr":"鼓浪屿港仔后路","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"沙坡尾","description":"收官打卡沙坡尾，避风坞文艺街区，猫街涂鸦。随后自由活动，采购伴手礼。","addr":"厦门市思明区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"日光岩","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"日光岩是鼓浪屿最有代表性的看点，全岛最高点看红瓦绿树海景。攻略把它排进主线，时间留得最足。","notice":"全岛最高点看红瓦绿树海景。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"鼓浪屿龙头山路"},{"spotId":"S2","name":"菽庄花园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"菽庄花园是鼓浪屿最有代表性的看点，四十四桥跨海，钢琴博物馆。攻略把它排进主线，时间留得最足。","notice":"四十四桥跨海，钢琴博物馆。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"鼓浪屿港仔后路"},{"spotId":"S3","name":"沙坡尾","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"沙坡尾是鼓浪屿最有代表性的看点，避风坞文艺街区，猫街涂鸦。攻略把它排进主线，时间留得最足。","notice":"避风坞文艺街区，猫街涂鸦。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"厦门市思明区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"沙茶面（人均28元）","description":"厦门 · 鼓浪屿的招牌是沙茶面，乌糖沙茶面本地人都认这家，点单照攻略不踩雷。","addr":"民族路"},{"title":"海蛎煎（人均25元）","description":"厦门 · 鼓浪屿的招牌是海蛎煎，莲欢海蛎煎本地人都认这家，点单照攻略不踩雷。","addr":"八市"},{"title":"土笋冻（人均15元）","description":"厦门 · 鼓浪屿的招牌是土笋冻，西门土笋冻本地人都认这家，点单照攻略不踩雷。","addr":"斗西路"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10350,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","相机或运动相机","防晒霜与遮阳帽","少量零食补给","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雁荡山轻徒步一日','nearby','温州 · 雁荡山','mountain','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',28000,15400,2,'灵峰 / 大龙湫 / 方洞栈道 —— 一张票打包雁荡山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「雁荡山」一日轻旅行——山岳。雁荡山铁皮石斛有名。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 温州"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"温州集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"雁荡山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"灵峰","description":"首站直达灵峰，日景夜景两相宜，夫妻峰剪影。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"乐清市雁荡山","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排山溪鱼馆——人均约58元，雁荡山石斑鱼是本地招牌，点菜照着攻略走。","addr":"响岭头村","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"大龙湫","description":"午后游览大龙湫，190米瀑布，雨后最壮。","addr":"雁荡山","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"方洞栈道","description":"收官打卡方洞栈道，悬崖栈道悬空百米。随后自由活动，采购伴手礼。","addr":"雁荡山","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"灵峰","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"灵峰是雁荡山最有代表性的看点，日景夜景两相宜，夫妻峰剪影。攻略把它排进主线，时间留得最足。","notice":"日景夜景两相宜，夫妻峰剪影。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"乐清市雁荡山"},{"spotId":"S2","name":"大龙湫","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"大龙湫是雁荡山最有代表性的看点，190米瀑布，雨后最壮。攻略把它排进主线，时间留得最足。","notice":"190米瀑布，雨后最壮。这个点位上午光线最好。","durationMinutes":90,"addr":"雁荡山"},{"spotId":"S3","name":"方洞栈道","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"方洞栈道是雁荡山最有代表性的看点，悬崖栈道悬空百米。攻略把它排进主线，时间留得最足。","notice":"悬崖栈道悬空百米。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"雁荡山"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"雁荡山石斑鱼（人均58元）","description":"温州 · 雁荡山的招牌是雁荡山石斑鱼，山溪鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"响岭头村"},{"title":"香鱼（人均48元）","description":"温州 · 雁荡山的招牌是香鱼，溪鱼农家本地人都认这家，点单照攻略不踩雷。","addr":"大龙湫下"},{"title":"雁茗茶（人均25元）","description":"温州 · 雁荡山的招牌是雁茗茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"灵峰景区"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12600,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","相机或运动相机","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","身份证件与手机充电宝","墨镜与拍照道具","防晒霜与遮阳帽"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄山宏村精华一日','nearby','黄山 · 黄山宏村','mountain','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',13900,7600,2,'黄山光明顶 / 西海大峡谷 / 宏村 —— 一张票打包黄山宏村精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「黄山宏村」一日轻旅行——山岳。徽墨歙砚文房收藏佳品。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 黄山"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"黄山集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"黄山宏村游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"黄山光明顶","description":"首站直达黄山光明顶，看日出云海的主峰平台。建议停留240分钟，跟着攻略动线走省一半时间。","addr":"黄山市黄山区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排老街第一楼——人均约78元，臭鳜鱼是本地招牌，点菜照着攻略走。","addr":"屯溪老街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"西海大峡谷","description":"午后游览西海大峡谷，网红小火车，峡谷栈道惊险。","addr":"黄山风景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"宏村","description":"收官打卡宏村，月沼南湖水墨徽州，写生圣地。随后自由活动，采购伴手礼。","addr":"黟县宏村镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"黄山光明顶","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"黄山光明顶是黄山宏村最有代表性的看点，看日出云海的主峰平台。攻略把它排进主线，时间留得最足。","notice":"看日出云海的主峰平台。这个点位上午光线最好。","durationMinutes":300,"addr":"黄山市黄山区"},{"spotId":"S2","name":"西海大峡谷","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"西海大峡谷是黄山宏村最有代表性的看点，网红小火车，峡谷栈道惊险。攻略把它排进主线，时间留得最足。","notice":"网红小火车，峡谷栈道惊险。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"黄山风景区"},{"spotId":"S3","name":"宏村","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"宏村是黄山宏村最有代表性的看点，月沼南湖水墨徽州，写生圣地。攻略把它排进主线，时间留得最足。","notice":"月沼南湖水墨徽州，写生圣地。这个点位上午光线最好。","durationMinutes":150,"addr":"黟县宏村镇"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"臭鳜鱼（人均78元）","description":"黄山 · 黄山宏村的招牌是臭鳜鱼，老街第一楼本地人都认这家，点单照攻略不踩雷。","addr":"屯溪老街"},{"title":"毛豆腐（人均20元）","description":"黄山 · 黄山宏村的招牌是毛豆腐，徽州小吃本地人都认这家，点单照攻略不踩雷。","addr":"宏村月沼旁"},{"title":"黄山烧饼（人均12元）","description":"黄山 · 黄山宏村的招牌是黄山烧饼，救驾烧饼本地人都认这家，点单照攻略不踩雷。","addr":"汤口镇"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6255,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","墨镜与拍照道具","轻便雨衣或折叠伞","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","少量零食补给","相机或运动相机","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙门石窟治愈一日','nearby','洛阳 · 龙门石窟','red','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',14900,8100,7,'龙门石窟 / 白马寺 / 洛邑古城 —— 一张票打包龙门石窟精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「龙门石窟」一日轻旅行——人文。洛阳牡丹饼花香浓郁。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 洛阳"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"洛阳集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"龙门石窟游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"龙门石窟","description":"首站直达龙门石窟，卢舍那大佛，夜游灯光版。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"洛阳市洛龙区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排真不同——人均约88元，水席是本地招牌，点菜照着攻略走。","addr":"老城区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"白马寺","description":"午后游览白马寺，中国第一古刹，国际佛殿。","addr":"洛阳市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"洛邑古城","description":"收官打卡洛邑古城，汉服打卡圣地，夜景。随后自由活动，采购伴手礼。","addr":"老城区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"龙门石窟","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"龙门石窟是龙门石窟最有代表性的看点，卢舍那大佛，夜游灯光版。攻略把它排进主线，时间留得最足。","notice":"卢舍那大佛，夜游灯光版。这个点位上午光线最好。","durationMinutes":180,"addr":"洛阳市洛龙区"},{"spotId":"S2","name":"白马寺","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"白马寺是龙门石窟最有代表性的看点，中国第一古刹，国际佛殿。攻略把它排进主线，时间留得最足。","notice":"中国第一古刹，国际佛殿。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"洛阳市"},{"spotId":"S3","name":"洛邑古城","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"洛邑古城是龙门石窟最有代表性的看点，汉服打卡圣地，夜景。攻略把它排进主线，时间留得最足。","notice":"汉服打卡圣地，夜景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"老城区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水席（人均88元）","description":"洛阳 · 龙门石窟的招牌是水席，真不同本地人都认这家，点单照攻略不踩雷。","addr":"老城区"},{"title":"牛肉汤（人均15元）","description":"洛阳 · 龙门石窟的招牌是牛肉汤，马杰山牛肉汤本地人都认这家，点单照攻略不踩雷。","addr":"瀍河区"},{"title":"不翻汤（人均12元）","description":"洛阳 · 龙门石窟的招牌是不翻汤，十字街夜市本地人都认这家，点单照攻略不踩雷。","addr":"老城十字街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6705,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","少量零食补给","防晒霜与遮阳帽","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["几月份去 洛阳 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
