INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳阳楼洞庭湖轻徒步一日','nearby','岳阳 · 岳阳楼洞庭湖','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',16100,8800,2,'岳阳楼 / 君山岛 / 圣安寺 —— 一张票打包岳阳楼洞庭湖精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「岳阳楼洞庭湖」一日轻旅行——水景。君山银针是十大名茶之一。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 岳阳"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"岳阳集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"岳阳楼洞庭湖游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"岳阳楼","description":"首站直达岳阳楼，洞庭天下水岳阳天下楼，背岳阳楼记免票。建议停留72分钟，跟着攻略动线走省一半时间。","addr":"岳阳市岳阳楼区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排巴陵全鱼席——人均约78元，洞庭鱼头是本地招牌，点菜照着攻略走。","addr":"岳阳楼景区旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"君山岛","description":"午后游览君山岛，湘妃竹与银针茶的故乡。","addr":"洞庭湖君山岛","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"圣安寺","description":"收官打卡圣安寺，古塔与湖景同框。随后自由活动，采购伴手礼。","addr":"岳阳市南湖畔","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"岳阳楼","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"岳阳楼是岳阳楼洞庭湖最有代表性的看点，洞庭天下水岳阳天下楼，背岳阳楼记免票。攻略把它排进主线，时间留得最足。","notice":"洞庭天下水岳阳天下楼，背岳阳楼记免票。这个点位上午光线最好。","durationMinutes":90,"addr":"岳阳市岳阳楼区"},{"spotId":"S2","name":"君山岛","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","hig