INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阳朔漓江微度假一日','nearby','桂林 · 阳朔漓江','water','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',26900,14700,2,'兴坪漓江 / 遇龙河 / 西街 —— 一张票打包阳朔漓江精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「阳朔漓江」一日轻旅行——水景。阳朔金桔个大超甜。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"桂林集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"阳朔漓江游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"兴坪漓江","description":"首站直达兴坪漓江，20元人民币背景，老寨山看全景。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"阳朔县兴坪镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排谢大姐啤酒鱼——人均约68元，啤酒鱼是本地招牌，点菜照着攻略走。","addr":"西街口","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"遇龙河","description":"午后游览遇龙河，竹筏漂流，工农桥日落。","addr":"阳朔县遇龙河","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"西街","description":"收官打卡西街，老外扎堆的千年老街。随后自由活动，采购伴手礼。","addr":"阳朔县西街","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"兴坪漓江","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"兴坪漓江是阳朔漓江最有代表性的看点，20元人民币背景，老寨山看全景。攻略把它排进主线，时间留得最足。","notice":"20元人民币背景，老寨山看全景。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"阳朔县兴坪镇"},{"spotId":"S2","name":"遇龙河","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"遇龙河是阳朔漓江最有代表性的看点，竹筏漂流，工农桥日落。攻略把它排进主线，时间留得最足。","notice":"竹筏漂流，工农桥日落。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"阳朔县遇龙河"},{"spotId":"S3","name":"西街","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"西街是阳朔漓江最有代表性的看点，老外扎堆的千年老街。攻略把它排进主线，时间留得最足。","notice":"老外扎堆的千年老街。这个点位上午光线最好。","durationMinutes":120,"addr":"阳朔县西街"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"啤酒鱼（人均68元）","description":"桂林 · 阳朔漓江的招牌是啤酒鱼，谢大姐啤酒鱼本地人都认这家，点单照攻略不踩雷。","addr":"西街口"},{"title":"桂林米粉（人均12元）","description":"桂林 · 阳朔漓江的招牌是桂林米粉，崇善米粉本地人都认这家，点单照攻略不踩雷。","addr":"兴坪老街"},{"title":"田螺酿（人均38元）","description":"桂林 · 阳朔漓江的招牌是田螺酿，阳朔农家本地人都认这家，点单照攻略不踩雷。","addr":"遇龙河边"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12105,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","墨镜与拍照道具","相机或运动相机","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["到达 桂林 的交通方便吗？","推荐先到 桂林，再打车或景区直通车前往核心景区；自驾导航直接搜阳朔漓江即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
