INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('东湖黄鹤楼精华一日','nearby','武汉 · 东湖黄鹤楼','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',19000,10400,2,'黄鹤楼 / 东湖绿道 / 昙华林 —— 一张票打包东湖黄鹤楼精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「东湖黄鹤楼」一日轻旅行——水景。武汉鸭脖真空包装好带。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 武汉"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"武汉集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"东湖黄鹤楼游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"黄鹤楼","description":"首站直达黄鹤楼，天下江山第一楼，夜景灯光秀。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"武汉市武昌区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排蔡林记——人均约12元，热干面是本地招牌，点菜照着攻略走。","addr":"户部巷","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"东湖绿道","description":"午后游览东湖绿道，骑行湖中道，磨山樱园。","addr":"武昌区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"昙华林","description":"收官打卡昙华林，老教堂与文创小店。随后自由活动，采购伴手礼。","addr":"武昌区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"黄鹤楼","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"黄鹤楼是东湖黄鹤楼最有代表性的看点，天下江山第一楼，夜景灯光秀。攻略把它排进主线，时间留得最足。","notice":"天下江山第一楼，夜景灯光秀。这个点位上午光线最好。","durationMinutes":120,"addr":"武汉市武昌区"},{"spotId":"S2","name":"东湖绿道","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"东湖绿道是东湖黄鹤楼最有代表性的看点，骑行湖中道，磨山樱园。攻略把它排进主线，时间留得最足。","notice":"骑行湖中道，磨山樱园。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"武昌区"},{"spotId":"S3","name":"昙华林","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"昙华林是东湖黄鹤楼最有代表性的看点，老教堂与文创小店。攻略把它排进主线，时间留得最足。","notice":"老教堂与文创小店。这个点位上午光线最好。","durationMinutes":90,"addr":"武昌区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"热干面（人均12元）","description":"武汉 · 东湖黄鹤楼的招牌是热干面，蔡林记本地人都认这家，点单照攻略不踩雷。","addr":"户部巷"},{"title":"豆皮（人均18元）","description":"武汉 · 东湖黄鹤楼的招牌是豆皮，老通城本地人都认这家，点单照攻略不踩雷。","addr":"大智路"},{"title":"武昌鱼（人均68元）","description":"武汉 · 东湖黄鹤楼的招牌是武昌鱼，湖锦酒楼本地人都认这家，点单照攻略不踩雷。","addr":"昙华林"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8550,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽","相机或运动相机","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["当地有什么必吃？","到了 武汉，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 武汉 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
