INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('张家界国家森林公园慢游一日','nearby','张家界 · 张家界国家森林公园','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',28500,15600,2,'袁家界 / 天子山 / 金鞭溪 —— 一张票打包张家界国家森林公园精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「张家界国家森林公园」一日轻旅行——山岳。张家界莓茶降火神器。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 张家界"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"张家界集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"张家界国家森林公园游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"袁家界","description":"首站直达袁家界，阿凡达悬浮山原型，百龙天梯上山。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"武陵源区森林公园","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排胡师傅三下锅——人均约58元，三下锅是本地招牌，点菜照着攻略走。","addr":"武陵源汽车站旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"天子山","description":"午后游览天子山，御笔峰日落绝佳，贺龙公园顺路。","addr":"武陵源天子山景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"金鞭溪","description":"收官打卡金鞭溪，全程7.5公里平路，溪边猕猴抢食注意。随后自由活动，采购伴手礼。","addr":"森林公园大氧吧广场","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"袁家界","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"袁家界是张家界国家森林公园最有代表性的看点，阿凡达悬浮山原型，百龙天梯上山。攻略把它排进主线，时间留得最足。","notice":"阿凡达悬浮山原型，百龙天梯上山。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"武陵源区森林公园"},{"spotId":"S2","name":"天子山","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"天子山是张家界国家森林公园最有代表性的看点，御笔峰日落绝佳，贺龙公园顺路。攻略把它排进主线，时间留得最足。","notice":"御笔峰日落绝佳，贺龙公园顺路。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"武陵源天子山景区"},{"spotId":"S3","name":"金鞭溪","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"金鞭溪是张家界国家森林公园最有代表性的看点，全程7.5公里平路，溪边猕猴抢食注意。攻略把它排进主线，时间留得最足。","notice":"全程7.5公里平路，溪边猕猴抢食注意。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"森林公园大氧吧广场"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"三下锅（人均58元）","description":"张家界 · 张家界国家森林公园的招牌是三下锅，胡师傅三下锅本地人都认这家，点单照攻略不踩雷。","addr":"武陵源汽车站旁"},{"title":"土家腊肉（人均48元）","description":"张家界 · 张家界国家森林公园的招牌是土家腊肉，湘西腊肉馆本地人都认这家，点单照攻略不踩雷。","addr":"溪布街"},{"title":"岩耳炖土鸡（人均88元）","description":"张家界 · 张家界国家森林公园的招牌是岩耳炖土鸡，山里人家本地人都认这家，点单照攻略不踩雷。","addr":"森林公园门票站"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12825,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","墨镜与拍照道具","少量零食补给","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 张家界，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('紫鹊界梯田轻徒步一日','nearby','娄底 · 紫鹊界梯田','village','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',26100,14300,1,'紫鹊界梯田 / 正龙古村 / 梅山龙宫 —— 一张票打包紫鹊界梯田精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「紫鹊界梯田」一日轻旅行——古村落。新化黄精茶养生。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 娄底"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"娄底集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"紫鹊界梯田游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"紫鹊界梯田","description":"首站直达紫鹊界梯田，两千年秦人梯田，月牙山八仙过海。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"娄底市新化县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排老字号三合汤——人均约38元，新化三合汤是本地招牌，点菜照着攻略走。","addr":"新化县城","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"正龙古村","description":"午后游览正龙古村，干栏式板屋村落。","addr":"紫鹊界脚下","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"梅山龙宫","description":"收官打卡梅山龙宫，地下溶洞暗河乘船。随后自由活动，采购伴手礼。","addr":"新化县","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"紫鹊界梯田","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"紫鹊界梯田是紫鹊界梯田最有代表性的看点，两千年秦人梯田，月牙山八仙过海。攻略把它排进主线，时间留得最足。","notice":"两千年秦人梯田，月牙山八仙过海。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"娄底市新化县"},{"spotId":"S2","name":"正龙古村","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"正龙古村是紫鹊界梯田最有代表性的看点，干栏式板屋村落。攻略把它排进主线，时间留得最足。","notice":"干栏式板屋村落。这个点位上午光线最好。","durationMinutes":90,"addr":"紫鹊界脚下"},{"spotId":"S3","name":"梅山龙宫","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"梅山龙宫是紫鹊界梯田最有代表性的看点，地下溶洞暗河乘船。攻略把它排进主线，时间留得最足。","notice":"地下溶洞暗河乘船。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"新化县"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新化三合汤（人均38元）","description":"娄底 · 紫鹊界梯田的招牌是新化三合汤，老字号三合汤本地人都认这家，点单照攻略不踩雷。","addr":"新化县城"},{"title":"杯子糕（人均10元）","description":"娄底 · 紫鹊界梯田的招牌是杯子糕，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"紫鹊界"},{"title":"柴火腊肉（人均45元）","description":"娄底 · 紫鹊界梯田的招牌是柴火腊肉，农家直购本地人都认这家，点单照攻略不踩雷。","addr":"正龙古村"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":11745,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","少量零食补给","轻便雨衣或折叠伞","防晒霜与遮阳帽","保温水杯与少量现金","身份证件与手机充电宝","墨镜与拍照道具","换洗衣物与外套（早晚温差）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 娄底，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 娄底 的交通方便吗？","推荐先到 娄底，再打车或景区直通车前往核心景区；自驾导航直接搜紫鹊界梯田即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'好运藏在出发的行囊里。','on');
