INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雅鲁藏布大峡谷精华一日','nearby','林芝 · 雅鲁藏布大峡谷','plateau','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',23900,13100,2,'南迦巴瓦观景台 / 雅鲁藏布大峡谷 / 鲁朗林海 —— 一张票打包雅鲁藏布大峡谷精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「雅鲁藏布大峡谷」一日轻旅行——高原。林芝松茸6-8月最鲜。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 林芝"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"林芝集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"雅鲁藏布大峡谷游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"南迦巴瓦观景台","description":"首站直达南迦巴瓦观景台，羞女峰十人九不遇，直白村最近。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"米林县派镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排石锅鸡总店——人均约128元，鲁朗石锅鸡是本地招牌，点菜照着攻略走。","addr":"鲁朗镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"雅鲁藏布大峡谷","description":"午后游览雅鲁藏布大峡谷，世界最深深峡，换乘游览。","addr":"林芝市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"鲁朗林海","description":"收官打卡鲁朗林海，东方瑞士，石锅鸡之乡。随后自由活动，采购伴手礼。","addr":"鲁朗镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"南迦巴瓦观景台","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"南迦巴瓦观景台是雅鲁藏布大峡谷最有代表性的看点，羞女峰十人九不遇，直白村最近。攻略把它排进主线，时间留得最足。","notice":"羞女峰十人九不遇，直白村最近。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"米林县派镇"},{"spotId":"S2","name":"雅鲁藏布大峡谷","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?