INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙坡头治愈一日','nearby','中卫 · 沙坡头','adventure','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',24000,13200,9,'沙坡头 / 通湖草原 / 66号公路 —— 一张票打包沙坡头精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「沙坡头」一日轻旅行——探险地。中卫硒砂瓜甜到心里。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"宁夏 · 中卫"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"中卫集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"沙坡头游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"沙坡头","description":"首站直达沙坡头，黄河飞索与羊皮筏子，沙漠骑骆驼。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"中卫市沙坡头区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排路边瓜摊——人均约10元，硒砂瓜是本地招牌，点菜照着攻略走。","addr":"沙坡头","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"通湖草原","description":"午后游览通湖草原，沙漠营地篝火晚会。","addr":"阿拉善左旗","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"66号公路","description":"收官打卡66号公路，网红沙漠公路打卡。随后自由活动，采购伴手礼。","addr":"中卫市","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"沙坡头","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"沙坡头是沙坡头最有代表性的看点，黄河飞索与羊皮筏子，沙漠骑骆驼。攻略把它排进主线，时间留得最足。","notice":"黄河飞索与羊皮筏子，沙漠骑骆驼。这个点位上午光线最好。","durationMinutes":240,"addr":"中卫市沙坡头区"},{"spotId":"S2","name":"通湖草原","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"通湖草原是沙坡头最有代表性的看点，沙漠营地篝火晚会。攻略把它排进主线，时间留得最足。","notice":"沙漠营地篝火晚会。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"阿拉善左旗"},{"spotId":"S3","name":"66号公路","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"66号公路是沙坡头最有代表性的看点，网红沙漠公路打卡。攻略把它排进主线，时间留得最足。","notice":"网红沙漠公路打卡。这个点位上午光线最好。","durationMinutes":60,"addr":"中卫市"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"硒砂瓜（人均10元）","description":"中卫 · 沙坡头的招牌是硒砂瓜，路边瓜摊本地人都认这家，点单照攻略不踩雷。","addr":"沙坡头"},{"title":"黄河大鲤鱼（人均58元）","description":"中卫 · 沙坡头的招牌是黄河大鲤鱼，沙坡头渔村本地人都认这家，点单照攻略不踩雷。","addr":"景区旁"},{"title":"手抓滩羊（人均68元）","description":"中卫 · 沙坡头的招牌是手抓滩羊，夏华火锅本地人都认这家，点单照攻略不踩雷。","addr":"中卫市区"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10800,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 中卫 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 中卫，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
