INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('凤凰古城周末逃离线','nearby','湘西 · 凤凰古城','ancient_town','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',16600,9100,1,'沱江跳岩 / 沈从文故居 / 南华山 —— 一张票打包凤凰古城精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「凤凰古城」一日轻旅行——古镇。凤凰银饰认准足银999。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 湘西"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"湘西集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"凤凰古城游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"沱江跳岩","description":"首站直达沱江跳岩，清晨雾气中的吊脚楼最出片。建议停留72分钟，跟着攻略动线走省一半时间。","addr":"凤凰古城沱江北门","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排凤凰老字号——人均约58元，血粑鸭是本地招牌，点菜照着攻略走。","addr":"虹桥东路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"沈从文故居","description":"午后游览沈从文故居，文学爱好者必打卡，讲解值得请。","addr":"凤凰古城中营街","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"南华山","description":"收官打卡南华山，登高俯瞰全城夜景。随后自由活动，采购伴手礼。","addr":"凤凰城南","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"沱江跳岩","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"沱江跳岩是凤凰古城最有代表性的看点，清晨雾气中的吊脚楼最出片。攻略把它排进主线，时间留得最足。","notice":"清晨雾气中的吊脚楼最出片。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"凤凰古城沱江北门"},{"spotId":"S2","name":"沈从文故居","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"沈从文故居是凤凰古城最有代表性的看点，文学爱好者必打卡，讲解值得请。攻略把它排进主线，时间留得最足。","notice":"文学爱好者必打卡，讲解值得请。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"凤凰古城中营街"},{"spotId":"S3","name":"南华山","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"南华山是凤凰古城最有代表性的看点，登高俯瞰全城夜景。攻略把它排进主线，时间留得最足。","notice":"登高俯瞰全城夜景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"凤凰城南"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"血粑鸭（人均58元）","description":"湘西 · 凤凰古城的招牌是血粑鸭，凤凰老字号本地人都认这家，点单照攻略不踩雷。","addr":"虹桥东路"},{"title":"苗家酸汤鱼（人均68元）","description":"湘西 · 凤凰古城的招牌是苗家酸汤鱼，古城酸汤鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"沱江边吊脚楼"},{"title":"凤凰姜糖（人均15元）","description":"湘西 · 凤凰古城的招牌是凤凰姜糖，老街姜糖铺本地人都认这家，点单照攻略不踩雷。","addr":"东正街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7470,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","保温水杯与少量现金"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["到达 湘西 的交通方便吗？","推荐先到 湘西，再打车或景区直通车前往核心景区；自驾导航直接搜凤凰古城即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 湘西 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
