INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('栈桥崂山纯玩直通车','nearby','青岛 · 栈桥崂山','sea','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',22300,12200,6,'栈桥 / 崂山仰口 / 八大关 —— 一张票打包栈桥崂山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「栈桥崂山」一日轻旅行——海滨。青岛啤酒原浆当天最新鲜。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 青岛"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"青岛集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"栈桥崂山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"栈桥","description":"首站直达栈桥，回澜阁海鸥季，夜色灯光。建议停留48分钟，跟着攻略动线走省一半时间。","addr":"青岛市市南区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排船歌鱼水饺——人均约58元，海鲜水饺是本地招牌，点菜照着攻略走。","addr":"闽江路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"崂山仰口","description":"午后游览崂山仰口，海上第一名山，觅天洞。","addr":"崂山区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"八大关","description":"收官打卡八大关，万国建筑与梧桐，秋天最美。随后自由活动，采购伴手礼。","addr":"市南区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"栈桥","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"栈桥是栈桥崂山最有代表性的看点，回澜阁海鸥季，夜色灯光。攻略把它排进主线，时间留得最足。","notice":"回澜阁海鸥季，夜色灯光。这个点位上午光线最好。","durationMinutes":60,"addr":"青岛市市南区"},{"spotId":"S2","name":"崂山仰口","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"崂山仰口是栈桥崂山最有代表性的看点，海上第一名山，觅天洞。攻略把它排进主线，时间留得最足。","notice":"海上第一名山，觅天洞。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"崂山区"},{"spotId":"S3","name":"八大关","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"八大关是栈桥崂山最有代表性的看点，万国建筑与梧桐，秋天最美。攻略把它排进主线，时间留得最足。","notice":"万国建筑与梧桐，秋天最美。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"市南区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜水饺（人均58元）","description":"青岛 · 栈桥崂山的招牌是海鲜水饺，船歌鱼水饺本地人都认这家，点单照攻略不踩雷。","addr":"闽江路"},{"title":"野馄饨（人均15元）","description":"青岛 · 栈桥崂山的招牌是野馄饨，夜市馄饨摊本地人都认这家，点单照攻略不踩雷。","addr":"登州路"},{"title":"崂山菇炖鸡（人均68元）","description":"青岛 · 栈桥崂山的招牌是崂山菇炖鸡，山海农家本地人都认这家，点单照攻略不踩雷。","addr":"仰口湾"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10035,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","保温水杯与少量现金","少量零食补给","身份证件与手机充电宝"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 青岛 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七星岩周末逃离线','nearby','肇庆 · 七星岩','water','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',20300,11100,2,'七星岩 / 鼎湖山 / 紫云谷 —— 一张票打包七星岩精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「七星岩」一日轻旅行——水景。端砚四大名砚之首。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 肇庆"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"肇庆集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"七星岩游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"七星岩","description":"首站直达七星岩，岭南第一奇观，湖山相映。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"肇庆市端州区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排皇中皇——人均约15元，裹蒸粽是本地招牌，点菜照着攻略走。","addr":"端州区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"鼎湖山","description":"午后游览鼎湖山，北回归线上的绿宝石，庆云寺。","addr":"鼎湖区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"紫云谷","description":"收官打卡紫云谷，端砚石产地，溪水清凉。随后自由活动，采购伴手礼。","addr":"羚羊峡","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"七星岩","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"七星岩是七星岩最有代表性的看点，岭南第一奇观，湖山相映。攻略把它排进主线，时间留得最足。","notice":"岭南第一奇观，湖山相映。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"肇庆市端州区"},{"spotId":"S2","name":"鼎湖山","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"鼎湖山是七星岩最有代表性的看点，北回归线上的绿宝石，庆云寺。攻略把它排进主线，时间留得最足。","notice":"北回归线上的绿宝石，庆云寺。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"鼎湖区"},{"spotId":"S3","name":"紫云谷","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"紫云谷是七星岩最有代表性的看点，端砚石产地，溪水清凉。攻略把它排进主线，时间留得最足。","notice":"端砚石产地，溪水清凉。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"羚羊峡"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"裹蒸粽（人均15元）","description":"肇庆 · 七星岩的招牌是裹蒸粽，皇中皇本地人都认这家，点单照攻略不踩雷。","addr":"端州区"},{"title":"文庆鲤（人均68元）","description":"肇庆 · 七星岩的招牌是文庆鲤，文庆鲤餐馆本地人都认这家，点单照攻略不踩雷。","addr":"鼎湖区"},{"title":"茶油鸡（人均48元）","description":"肇庆 · 七星岩的招牌是茶油鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"七星岩东门"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9135,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","相机或运动相机","少量零食补给","防晒霜与遮阳帽","墨镜与拍照道具","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","身份证件与手机充电宝"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 肇庆 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 肇庆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 肇庆 的交通方便吗？","推荐先到 肇庆，再打车或景区直通车前往核心景区；自驾导航直接搜七星岩即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
