INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('呼伦贝尔草原亲子轻松线','nearby','呼伦贝尔 · 呼伦贝尔草原','village','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',21400,11700,1,'莫日格勒河 / 额尔古纳湿地 / 恩和俄罗斯族乡 —— 一张票打包呼伦贝尔草原精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「呼伦贝尔草原」一日轻旅行——古村落。呼伦贝尔风干牛肉原味香。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"内蒙古 · 呼伦贝尔"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"呼伦贝尔集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"呼伦贝尔草原游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"莫日格勒河","description":"首站直达莫日格勒河，天下第一曲水，断崖机位。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"陈巴尔虎旗","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排草原牧民人家——人均约128元，烤羊腿是本地招牌，点菜照着攻略走。","addr":"黑山头镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"额尔古纳湿地","description":"午后游览额尔古纳湿地，亚洲第一湿地，日落金色。","addr":"额尔古纳市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"恩和俄罗斯族乡","description":"收官打卡恩和俄罗斯族乡，木刻楞小屋与列巴。随后自由活动，采购伴手礼。","addr":"额尔古纳市","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"莫日格勒河","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"莫日格勒河是呼伦贝尔草原最有代表性的看点，天下第一曲水，断崖机位。攻略把它排进主线，时间留得最足。","notice":"天下第一曲水，断崖机位。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"陈巴尔虎旗"},{"spotId":"S2","name":"额尔古纳湿地","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=form