INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('瘦西湖出片打卡线','nearby','扬州 · 瘦西湖','water','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',15100,8300,2,'瘦西湖 / 个园 / 东关街 —— 一张票打包瘦西湖精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「瘦西湖」一日轻旅行——水景。扬州漆器螺钿最精美。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 扬州"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"扬州集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"瘦西湖游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"瘦西湖","description":"首站直达瘦西湖，两堤花柳全依水，五亭桥白塔。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"扬州市邗江区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排食为天——人均约68元，蟹粉狮子头是本地招牌，点菜照着攻略走。","addr":"念四路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"个园","description":"午后游览个园，四季假山一园看尽。","addr":"东关街","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"东关街","description":"收官打卡东关街，千年古街，夜色灯笼。随后自由活动，采购伴手礼。","addr":"广陵区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"瘦西湖","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"瘦西湖是瘦西湖最有代表性的看点，两堤花柳全依水，五亭桥白塔。攻略把它排进主线，时间留得最足。","notice":"两堤花柳全依水，五亭桥白塔。这个点位上午光线最好。","durationMinutes":180,"addr":"扬州市邗江区"},{"spotId":"S2","name":"个园","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"个园是瘦西湖最有代表性的看点，四季假山一园看尽。攻略把它排进主线，时间留得最足。","notice":"四季假山一园看尽。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"东关街"},{"spotId":"S3","name":"东关街","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"东关街是瘦西湖最有代表性的看点，千年古街，夜色灯笼。攻略把它排进主线，时间留得最足。","notice":"千年古街，夜色灯笼。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"广陵区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蟹粉狮子头（人均68元）","description":"扬州 · 瘦西湖的招牌是蟹粉狮子头，食为天本地人都认这家，点单照攻略不踩雷。","addr":"念四路"},{"title":"扬州炒饭（人均28元）","description":"扬州 · 瘦西湖的招牌是扬州炒饭，老字号本地人都认这家，点单照攻略不踩雷。","addr":"东关街"},{"title":"烫干丝（人均22元）","description":"扬州 · 瘦西湖的招牌是烫干丝，富春茶社本地人都认这家，点单照攻略不踩雷。","addr":"得胜桥"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6795,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["少量零食补给","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","防晒霜与遮阳帽"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["当地有什么必吃？","到了 扬州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 扬州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'好运藏在出发的行囊里。','on');
