INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('曲阜三孔微度假一日','nearby','济宁 · 曲阜三孔','red','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',25400,13900,7,'孔庙 / 孔府 / 孔林 —— 一张票打包曲阜三孔精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「曲阜三孔」一日轻旅行——人文。曲阜楷木雕如意吉祥。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 济宁"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"济宁集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"曲阜三孔游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"孔庙","description":"首站直达孔庙，祭孔大典地，古柏森森。建议停留120分钟，跟着攻略动线走省一半时间。","addr":"济宁市曲阜市","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排阙里宾舍——人均约88元，孔府菜是本地招牌，点菜照着攻略走。","addr":"曲阜孔庙旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"孔府","description":"午后游览孔府，天下第一家，后花园。","addr":"曲阜","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"孔林","description":"收官打卡孔林，至圣林，孔子墓。随后自由活动，采购伴手礼。","addr":"曲阜","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"孔庙","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"孔庙是曲阜三孔最有代表性的看点，祭孔大典地，古柏森森。攻略把它排进主线，时间留得最足。","notice":"祭孔大典地，古柏森森。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"济宁市曲阜市"},{"spotId":"S2","name":"孔府","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"孔府是曲阜三孔最有代表性的看点，天下第一家，后花园。攻略把它排进主线，时间留得最足。","notice":"天下第一家，后花园。这个点位上午光线最好。","durationMinutes":90,"addr":"曲阜"},{"spotId":"S3","name":"孔林","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"孔林是曲阜三孔最有代表性的看点，至圣林，孔子墓。攻略把它排进主线，时间留得最足。","notice":"至圣林，孔子墓。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"曲阜"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"孔府菜（人均88元）","description":"济宁 · 曲阜三孔的招牌是孔府菜，阙里宾舍本地人都认这家，点单照攻略不踩雷。","addr":"曲阜孔庙旁"},{"title":"山东煎饼（人均10元）","description":"济宁 · 曲阜三孔的招牌是山东煎饼，煎饼卷本地人都认这家，点单照攻略不踩雷。","addr":"鼓楼街"},{"title":"羊肉泡粥（人均28元）","description":"济宁 · 曲阜三孔的招牌是羊肉泡粥，羊肉泡粥馆本地人都认这家，点单照攻略不踩雷。","addr":"曲阜市区"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":11430,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","相机或运动相机","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["到达 济宁 的交通方便吗？","推荐先到 济宁，再打车或景区直通车前往核心景区；自驾导航直接搜曲阜三孔即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 济宁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('亚龙湾蜈支洲慢游一日','nearby','三亚 · 亚龙湾蜈支洲','sea','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',20700,11300,6,'蜈支洲岛 / 亚龙湾热带天堂森林公园 / 后海村 —— 一张票打包亚龙湾蜈支洲精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「亚龙湾蜈支洲」一日轻旅行——海滨。三亚贵妃芒香甜多汁。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 三亚"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"三亚集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"亚龙湾蜈支洲游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"蜈支洲岛","description":"首站直达蜈支洲岛，中国马尔代夫，潜水胜地。建议停留240分钟，跟着攻略动线走省一半时间。","addr":"三亚市海棠区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排萌哒哒椰子鸡——人均约78元，椰子鸡是本地招牌，点菜照着攻略走。","addr":"后海村","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"亚龙湾热带天堂森林公园","description":"午后游览亚龙湾热带天堂森林公园，过江龙索道，电影取景地。","addr":"亚龙湾","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"后海村","description":"收官打卡后海村，冲浪初学者天堂，夜市。随后自由活动，采购伴手礼。","addr":"海棠湾","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"蜈支洲岛","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"蜈支洲岛是亚龙湾蜈支洲最有代表性的看点，中国马尔代夫，潜水胜地。攻略把它排进主线，时间留得最足。","notice":"中国马尔代夫，潜水胜地。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"三亚市海棠区"},{"spotId":"S2","name":"亚龙湾热带天堂森林公园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"亚龙湾热带天堂森林公园是亚龙湾蜈支洲最有代表性的看点，过江龙索道，电影取景地。攻略把它排进主线，时间留得最足。","notice":"过江龙索道，电影取景地。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"亚龙湾"},{"spotId":"S3","name":"后海村","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"后海村是亚龙湾蜈支洲最有代表性的看点，冲浪初学者天堂，夜市。攻略把它排进主线，时间留得最足。","notice":"冲浪初学者天堂，夜市。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"海棠湾"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"椰子鸡（人均78元）","description":"三亚 · 亚龙湾蜈支洲的招牌是椰子鸡，萌哒哒椰子鸡本地人都认这家，点单照攻略不踩雷。","addr":"后海村"},{"title":"清补凉（人均15元）","description":"三亚 · 亚龙湾蜈支洲的招牌是清补凉，一馨清补凉本地人都认这家，点单照攻略不踩雷。","addr":"第一市场"},{"title":"海鲜加工（人均98元）","description":"三亚 · 亚龙湾蜈支洲的招牌是海鲜加工，第一市场本地人都认这家，点单照攻略不踩雷。","addr":"新民街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9315,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","防晒霜与遮阳帽","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 三亚，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 三亚 的交通方便吗？","推荐先到 三亚，再打车或景区直通车前往核心景区；自驾导航直接搜亚龙湾蜈支洲即可。"]]}',2,'这一程，山水都在替你说话。','on');
