INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滨海路金石滩精华一日','nearby','大连 · 滨海路金石滩','sea','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',22800,12500,6,'滨海路木栈道 / 金石滩国家地质公园 / 星海广场 —— 一张票打包滨海路金石滩精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「滨海路金石滩」一日轻旅行——海滨。大连海参干货首选。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"辽宁 · 大连"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"大连集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"滨海路金石滩游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"滨海路木栈道","description":"首站直达滨海路木栈道，山海相依城市步道，北大桥日落。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"大连市中山区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排品海楼——人均约48元，海鲜焖子是本地招牌，点菜照着攻略走。","addr":"滨海路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"金石滩国家地质公园","description":"午后游览金石滩国家地质公园，恐龙探海奇石，龟裂石。","addr":"金州区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"星海广场","description":"收官打卡星海广场，亚洲最大城市广场，夜景。随后自由活动，采购伴手礼。","addr":"沙河口区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"滨海路木栈道","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"滨海路木栈道是滨海路金石滩最有代表性的看点，山海相依城市步道，北大桥日落。攻略把它排进主线，时间留得最足。","notice":"山海相依城市步道，北大桥日落。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大连市中山区"},{"spotId":"S2","name":"金石滩国家地质公园","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"金石滩国家地质公园是滨海路金石滩最有代表性的看点，恐龙探海奇石，龟裂石。攻略把它排进主线，时间留得最足。","notice":"恐龙探海奇石，龟裂石。这个点位上午光线最好。","durationMinutes":150,"addr":"金州区"},{"spotId":"S3","name":"星海广场","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"星海广场是滨海路金石滩最有代表性的看点，亚洲最大城市广场，夜景。攻略把它排进主线，时间留得最足。","notice":"亚洲最大城市广场，夜景。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"沙河口区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜焖子（人均48元）","description":"大连 · 滨海路金石滩的招牌是海鲜焖子，品海楼本地人都认这家，点单照攻略不踩雷。","addr":"滨海路"},{"title":"海胆蒸蛋（人均68元）","description":"大连 · 滨海路金石滩的招牌是海胆蒸蛋，日丰园本地人都认这家，点单照攻略不踩雷。","addr":"老虎滩"},{"title":"铁板鱿鱼（人均25元）","description":"大连 · 滨海路金石滩的招牌是铁板鱿鱼，中央大道夜市本地人都认这家，点单照攻略不踩雷。","addr":"西安路"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10260,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","轻便雨衣或折叠伞","墨镜与拍照道具","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 大连 的交通方便吗？","推荐先到 大连，再打车或景区直通车前往核心景区；自驾导航直接搜滨海路金石滩即可。"],["几月份去 大连 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三清山治愈一日','nearby','上饶 · 三清山','mountain','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',27400,15000,2,'南清园 / 阳光海岸 / 万寿园 —— 一张票打包三清山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「三清山」一日轻旅行——山岳。三清山猴头菇干货是手信首选。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"上饶集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"三清山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"南清园","description":"首站直达南清园，巨蟒出山、东方女神都在这条环线，台阶多备水。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"三清山风景区南门","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排山脚农家菜——人均约58元，石鸡汤锅是本地招牌，点菜照着攻略走。","addr":"三清山外双溪服务区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"阳光海岸","description":"午后游览阳光海岸，栈道悬空，恐高走东线缓冲段。","addr":"三清山高空栈道","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"万寿园","description":"收官打卡万寿园，坡缓树多，适合收尾慢慢走。随后自由活动，采购伴手礼。","addr":"三清山南部入口","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"南清园","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"南清园是三清山最有代表性的看点，巨蟒出山、东方女神都在这条环线，台阶多备水。攻略把它排进主线，时间留得最足。","notice":"巨蟒出山、东方女神都在这条环线，台阶多备水。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"三清山风景区南门"},{"spotId":"S2","name":"阳光海岸","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"阳光海岸是三清山最有代表性的看点，栈道悬空，恐高走东线缓冲段。攻略把它排进主线，时间留得最足。","notice":"栈道悬空，恐高走东线缓冲段。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"三清山高空栈道"},{"spotId":"S3","name":"万寿园","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"万寿园是三清山最有代表性的看点，坡缓树多，适合收尾慢慢走。攻略把它排进主线，时间留得最足。","notice":"坡缓树多，适合收尾慢慢走。这个点位上午光线最好。","durationMinutes":90,"addr":"三清山南部入口"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"石鸡汤锅（人均58元）","description":"上饶 · 三清山的招牌是石鸡汤锅，山脚农家菜本地人都认这家，点单照攻略不踩雷。","addr":"三清山外双溪服务区"},{"title":"野艾果（人均10元）","description":"上饶 · 三清山的招牌是野艾果，路边农家本地人都认这家，点单照攻略不踩雷。","addr":"南山索道下站旁"},{"title":"三清山烧饼（人均8元）","description":"上饶 · 三清山的招牌是三清山烧饼，南清园补给点本地人都认这家，点单照攻略不踩雷。","addr":"登山途中补给站"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12330,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","相机或运动相机","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道"],"faqs":[["几月份去 上饶 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 上饶，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('明月山纯玩直通车','nearby','宜春 · 明月山','mountain','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',21000,11500,2,'青云栈道 / 云谷飞瀑 / 温汤镇古井泉街 —— 一张票打包明月山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「明月山」一日轻旅行——山岳。温汤富硒温泉蛋一元一个。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 宜春"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"宜春集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"明月山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"青云栈道","description":"首站直达青云栈道，悬空栈道绕山腰，云雾天如仙境。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"明月山风景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排温汤镇豆腐宴——人均约48元，温泉豆腐是本地招牌，点菜照着攻略走。","addr":"温汤镇古井旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"云谷飞瀑","description":"午后游览云谷飞瀑，宜春八景之一，负氧离子爆表。","addr":"明月山核心景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"温汤镇古井泉街","description":"收官打卡温汤镇古井泉街，富硒温泉足浴28元一位，晚上泡最解乏。随后自由活动，采购伴手礼。","addr":"袁州区温汤镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"青云栈道","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"青云栈道是明月山最有代表性的看点，悬空栈道绕山腰，云雾天如仙境。攻略把它排进主线，时间留得最足。","notice":"悬空栈道绕山腰，云雾天如仙境。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"明月山风景区"},{"spotId":"S2","name":"云谷飞瀑","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"云谷飞瀑是明月山最有代表性的看点，宜春八景之一，负氧离子爆表。攻略把它排进主线，时间留得最足。","notice":"宜春八景之一，负氧离子爆表。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"明月山核心景区"},{"spotId":"S3","name":"温汤镇古井泉街","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"温汤镇古井泉街是明月山最有代表性的看点，富硒温泉足浴28元一位，晚上泡最解乏。攻略把它排进主线，时间留得最足。","notice":"富硒温泉足浴28元一位，晚上泡最解乏。这个点位上午光线最好。","durationMinutes":120,"addr":"袁州区温汤镇"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"温泉豆腐（人均48元）","description":"宜春 · 明月山的招牌是温泉豆腐，温汤镇豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇古井旁"},{"title":"慈化鸡爪（人均22元）","description":"宜春 · 明月山的招牌是慈化鸡爪，宜春小吃店本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇主街"},{"title":"扎粉（人均15元）","description":"宜春 · 明月山的招牌是扎粉，宜春扎粉店本地人都认这家，点单照攻略不踩雷。","addr":"古井泉街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9450,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","墨镜与拍照道具","少量零食补给","相机或运动相机","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["当地有什么必吃？","到了 宜春，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 宜春 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南岳衡山周末逃离线','nearby','衡阳 · 南岳衡山','mountain','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',23800,13000,2,'祝融峰 / 南岳大庙 / 藏经殿 —— 一张票打包南岳衡山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「南岳衡山」一日轻旅行——山岳。南岳香文化用品别乱买。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 衡阳"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"衡阳集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"南岳衡山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"祝融峰","description":"首站直达祝融峰，五岳最高峰观日出，山顶租赁军大衣。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"南岳区衡山风景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排大庙素斋馆——人均约48元，南岳素斋是本地招牌，点菜照着攻略走。","addr":"南岳大庙旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"南岳大庙","description":"午后游览南岳大庙，江南第一庙，香火极旺。","addr":"南岳区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"藏经殿","description":"收官打卡藏经殿，幽谷深林中的古刹。随后自由活动，采购伴手礼。","addr":"衡山半山","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"祝融峰","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"祝融峰是南岳衡山最有代表性的看点，五岳最高峰观日出，山顶租赁军大衣。攻略把它排进主线，时间留得最足。","notice":"五岳最高峰观日出，山顶租赁军大衣。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"南岳区衡山风景区"},{"spotId":"S2","name":"南岳大庙","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"南岳大庙是南岳衡山最有代表性的看点，江南第一庙，香火极旺。攻略把它排进主线，时间留得最足。","notice":"江南第一庙，香火极旺。这个点位上午光线最好。","durationMinutes":120,"addr":"南岳区"},{"spotId":"S3","name":"藏经殿","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"藏经殿是南岳衡山最有代表性的看点，幽谷深林中的古刹。攻略把它排进主线，时间留得最足。","notice":"幽谷深林中的古刹。这个点位上午光线最好。","durationMinutes":90,"addr":"衡山半山"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"南岳素斋（人均48元）","description":"衡阳 · 南岳衡山的招牌是南岳素斋，大庙素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"南岳大庙旁"},{"title":"观音笋（人均38元）","description":"衡阳 · 南岳衡山的招牌是观音笋，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"半山亭"},{"title":"衡山云雾茶（人均30元）","description":"衡阳 · 南岳衡山的招牌是衡山云雾茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"南岳镇"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10710,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","保温水杯与少量现金","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","少量零食补给","相机或运动相机","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["到达 衡阳 的交通方便吗？","推荐先到 衡阳，再打车或景区直通车前往核心景区；自驾导航直接搜南岳衡山即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('香格里拉出片打卡线','nearby','迪庆 · 香格里拉','plateau','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',15800,8600,2,'普达措国家公园 / 松赞林寺 / 独克宗古城 —— 一张票打包香格里拉精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「香格里拉」一日轻旅行——高原。牦牛肉干认准风干原味。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 迪庆"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"迪庆集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"香格里拉游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"普达措国家公园","description":"首站直达普达措国家公园，属都湖栈道环湖，高原慢慢走。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"香格里拉市建塘镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排市井牦牛火锅——人均约88元，牦牛肉火锅是本地招牌，点菜照着攻略走。","addr":"独克宗古城","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"松赞林寺","description":"午后游览松赞林寺，小布达拉宫，顺时针转寺。","addr":"香格里拉市佛屏山前","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"独克宗古城","description":"收官打卡独克宗古城，转世界最大转经筒，夜景美。随后自由活动，采购伴手礼。","addr":"香格里拉市","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"普达措国家公园","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"普达措国家公园是香格里拉最有代表性的看点，属都湖栈道环湖，高原慢慢走。攻略把它排进主线，时间留得最足。","notice":"属都湖栈道环湖，高原慢慢走。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"香格里拉市建塘镇"},{"spotId":"S2","name":"松赞林寺","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"松赞林寺是香格里拉最有代表性的看点，小布达拉宫，顺时针转寺。攻略把它排进主线，时间留得最足。","notice":"小布达拉宫，顺时针转寺。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"香格里拉市佛屏山前"},{"spotId":"S3","name":"独克宗古城","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"独克宗古城是香格里拉最有代表性的看点，转世界最大转经筒，夜景美。攻略把它排进主线，时间留得最足。","notice":"转世界最大转经筒，夜景美。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"香格里拉市"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉火锅（人均88元）","description":"迪庆 · 香格里拉的招牌是牦牛肉火锅，市井牦牛火锅本地人都认这家，点单照攻略不踩雷。","addr":"独克宗古城"},{"title":"酥油茶（人均20元）","description":"迪庆 · 香格里拉的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"青稞饼（人均12元）","description":"迪庆 · 香格里拉的招牌是青稞饼，藏式饼铺本地人都认这家，点单照攻略不踩雷。","addr":"池慈卡街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7110,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","相机或运动相机","轻便雨衣或折叠伞","身份证件与手机充电宝","墨镜与拍照道具","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["当地有什么必吃？","到了 迪庆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('峨眉山乐山大佛亲子轻松线','nearby','乐山 · 峨眉山乐山大佛','mountain','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',24000,13200,2,'乐山大佛 / 峨眉山金顶 / 清音阁 —— 一张票打包峨眉山乐山大佛精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「峨眉山乐山大佛」一日轻旅行——山岳。峨眉雪芽茶清甜回甘。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 乐山"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"乐山集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"峨眉山乐山大佛游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"乐山大佛","description":"首站直达乐山大佛，九曲栈道近距离看大佛脚背。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"乐山市凌云路","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排叶婆婆——人均约35元，钵钵鸡是本地招牌，点菜照着攻略走。","addr":"乐山港","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"峨眉山金顶","description":"午后游览峨眉山金顶，十方普贤金像，云海日出。","addr":"峨眉山市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"清音阁","description":"收官打卡清音阁，双桥清音，平路好走。随后自由活动，采购伴手礼。","addr":"峨眉山低山区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"乐山大佛","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"乐山大佛是峨眉山乐山大佛最有代表性的看点，九曲栈道近距离看大佛脚背。攻略把它排进主线，时间留得最足。","notice":"九曲栈道近距离看大佛脚背。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"乐山市凌云路"},{"spotId":"S2","name":"峨眉山金顶","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80