INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('日月湾冲浪周末逃离线','nearby','万宁 · 日月湾冲浪','sea','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',25100,13800,6,'日月湾 / 石梅湾 / 兴隆热带植物园 —— 一张票打包日月湾冲浪精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「日月湾冲浪」一日轻旅行——海滨。兴隆炭烧咖啡回香浓。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"海南 · 万宁"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"万宁集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"日月湾冲浪游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"日月湾","description":"首站直达日月湾，国家冲浪队训练地，新手教程2小时。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"万宁市礼纪镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排渔家海鲜——人均约88元，和乐蟹是本地招牌，点菜照着攻略走。","addr":"东澳镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"石梅湾","description":"午后游览石梅湾，加井岛浮潜，凤凰九里书屋。","addr":"万宁市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"兴隆热带植物园","description":"收官打卡兴隆热带植物园，咖啡可可巧克力之旅。随后自由活动，采购伴手礼。","addr":"兴隆镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"日月湾","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"日月湾是日月湾冲浪最有代表性的看点，国家冲浪队训练地，新手教程2小时。攻略把它排进主线，时间留得最足。","notice":"国家冲浪队训练地，新手教程2小时。这个点位上午光线最好。","durationMinutes":180,"addr":"万宁市礼纪镇"},{"spotId":"S2","name":"石梅湾","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights"