INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('中央大街冰雪亲子轻松线','nearby','哈尔滨 · 中央大街冰雪','art','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',22800,12500,5,'中央大街 / 圣索菲亚大教堂 / 松花江防洪纪念塔 —— 一张票打包中央大街冰雪精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「中央大街冰雪」一日轻旅行——文艺。哈尔滨红肠真空好带。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"黑龙江 · 哈尔滨"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"哈尔滨集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"中央大街冰雪游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"中央大街","description":"首站直达中央大街，百年面包石街道，马迭尔冰棍。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"哈尔滨市道里区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排老厨家——人均约48元，锅包肉是本地招牌，点菜照着攻略走。","addr":"友谊路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"圣索菲亚大教堂","description":"午后游览圣索菲亚大教堂，拜占庭绿顶，鸽子广场。","addr":"透笼街","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"松花江防洪纪念塔","description":"收官打卡松花江防洪纪念塔，冬季冰上活动集合地。随后自由活动，采购伴手礼。","addr":"道里区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"中央大街","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"中央大街是中央大街冰雪最有代表性的看点，百年面包石街道，马迭尔冰棍。攻略把它排进主线，时间留得最足。","notice":"百年面包石街道，马迭尔冰棍。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"哈尔滨市道里区"},{"spotId":"S2","name":"圣索菲亚大教堂","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"圣索菲亚大教堂是中央大街冰雪最有代表性的看点，拜占庭绿顶，鸽子广场。攻略把它排进主线，时间留得最足。","notice":"拜占庭绿顶，鸽子广场。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"透笼街"},{"spotId":"S3","name":"松花江防洪纪念塔","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"松花江防洪纪念塔是中央大街冰雪最有代表性的看点，冬季冰上活动集合地。攻略把它排进主线，时间留得最足。","notice":"冬季冰上活动集合地。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"道里区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"锅包肉（人均48元）","description":"哈尔滨 · 中央大街冰雪的招牌是锅包肉，老厨家本地人都认这家，点单照攻略不踩雷。","addr":"友谊路"},{"title":"哈尔滨红肠（人均25元）","description":"哈尔滨 · 中央大街冰雪的招牌是哈尔滨红肠，秋林里道斯本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"},{"title":"格瓦斯（人均12元）","description":"哈尔滨 · 中央大街冰雪的招牌是格瓦斯，马迭尔冷饮厅本地人都认这家，点单照攻略不踩雷。","addr":"中央大街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10260,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","保温水杯与少量现金","少量零食补给","换洗衣物与外套（早晚温差）","墨镜与拍照道具","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","相机或运动相机"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 哈尔滨 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武功山人文漫游线','nearby','萍乡 · 武功山','mountain','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',27500,15100,2,'金顶 / 发云界 / 玻璃栈道 —— 一张票打包武功山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「武功山」一日轻旅行——山岳。武功山泉水豆腐宴别错过。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"萍乡集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"武功山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"金顶","description":"首站直达金顶，日出云海核心位，山顶比山下冷10度。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"武功山风景区金顶","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排山脚菜馆——人均约42元，萍乡小炒肉是本地招牌，点菜照着攻略走。","addr":"武功山游客中心旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"发云界","description":"午后游览发云界，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"玻璃栈道","description":"收官打卡玻璃栈道，栈道限流，旺季排30分钟。随后自由活动，采购伴手礼。","addr":"武功山吊马桩","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12375,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","保温水杯与少量现金","防晒霜与遮阳帽","墨镜与拍照道具","相机或运动相机","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 萍乡，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
