INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('长白山精华一日','nearby','延边 · 长白山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',24400,13400,2,'天池北坡 / 长白瀑布 / 绿渊潭 —— 一张票打包长白山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「长白山」一日轻旅行——山岳。长白山林下参滋补。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"吉林 · 延边"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"延边集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"长白山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"天池北坡","description":"首站直达天池北坡，长白山主峰天池，天气好才能见。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"延边州安图县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排服务大楼冷面——人均约22元，朝鲜冷面是本地招牌，点菜照着攻略走。","addr":"二道白河镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"长白瀑布","description":"午后游览长白瀑布，68米瀑布与温泉煮蛋。","addr":"北坡景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"绿渊潭","description":"收官打卡绿渊潭，碧绿水潭与飞瀑。随后自由活动，采购伴手礼。","addr":"北坡","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"天池北坡","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"天池北坡是长白山最有代表性的看点，长白山主峰天池，天气好才能见。攻略把它排进主线，时间留得最足。","notice":"长白山主峰天池，天气好才能见。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"延边州安图县"},{"spotId":"S2","name":"长白瀑布","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"长白瀑布是长白山最有代表性的看点，68米瀑布与温泉煮蛋。攻略把它排进主线，时间留得最足。","notice":"68米瀑布与温泉煮蛋。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"北坡景区"},{"spotId":"S3","name":"绿渊潭","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"绿渊潭是长白山最有代表性的看点，碧绿水潭与飞瀑。攻略把它排进主线，时间留得最足。","notice":"碧绿水潭与飞瀑。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"北坡"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"朝鲜冷面（人均22元）","description":"延边 · 长白山的招牌是朝鲜冷面，服务大楼冷面本地人都认这家，点单照攻略不踩雷。","addr":"二道白河镇"},{"title":"石锅拌饭（人均28元）","description":"延边 · 长白山的招牌是石锅拌饭，金达莱餐厅本地人都认这家，点单照攻略不踩雷。","addr":"延吉市"},{"title":"温泉煮蛋（人均10元）","description":"延边 · 长白山的招牌是温泉煮蛋，瀑布温泉口本地人都认这家，点单照攻略不踩雷。","addr":"北坡"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10980,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 延边 的交通方便吗？","推荐先到 延边，再打车或景区直通车前往核心景区；自驾导航直接搜长白山即可。"],["当地有什么必吃？","到了 延边，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('井冈山治愈一日','nearby','吉安 · 井冈山','red','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',17200,9400,7,'黄洋界 / 茨坪革命旧址群 / 龙潭 —— 一张票打包井冈山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「井冈山」一日轻旅行——人文。井冈山竹制工艺品轻便好带。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 吉安"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"吉安集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"井冈山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"黄洋界","description":"首站直达黄洋界，保卫战旧址，云海出现率高。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"井冈山市黄洋界景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排老乡家常菜——人均约45元，红米饭南瓜汤是本地招牌，点菜照着攻略走。","addr":"茨坪天街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"茨坪革命旧址群","description":"午后游览茨坪革命旧址群，旧址集中，步行串游。","addr":"井冈山市茨坪镇","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"龙潭","description":"收官打卡龙潭，五潭十八瀑，索道省力。随后自由活动，采购伴手礼。","addr":"井冈山龙潭景区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"黄洋界","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"黄洋界是井冈山最有代表性的看点，保卫战旧址，云海出现率高。攻略把它排进主线，时间留得最足。","notice":"保卫战旧址，云海出现率高。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"井冈山市黄洋界景区"},{"spotId":"S2","name":"茨坪革命旧址群","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"茨坪革命旧址群是井冈山最有代表性的看点，旧址集中，步行串游。攻略把它排进主线，时间留得最足。","notice":"旧址集中，步行串游。这个点位上午光线最好。","durationMinutes":150,"addr":"井冈山市茨坪镇"},{"spotId":"S3","name":"龙潭","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"龙潭是井冈山最有代表性的看点，五潭十八瀑，索道省力。攻略把它排进主线，时间留得最足。","notice":"五潭十八瀑，索道省力。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"井冈山龙潭景区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红米饭南瓜汤（人均45元）","description":"吉安 · 井冈山的招牌是红米饭南瓜汤，老乡家常菜本地人都认这家，点单照攻略不踩雷。","addr":"茨坪天街"},{"title":"井冈烟笋（人均38元）","description":"吉安 · 井冈山的招牌是井冈烟笋，山上饭庄本地人都认这家，点单照攻略不踩雷。","addr":"黄洋界山下餐馆"},{"title":"石鸡炖汤（人均88元）","description":"吉安 · 井冈山的招牌是石鸡炖汤，龙潭农庄本地人都认这家，点单照攻略不踩雷。","addr":"龙潭景区入口"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7740,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","少量零食补给","身份证件与手机充电宝","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 吉安 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 吉安 的交通方便吗？","推荐先到 吉安，再打车或景区直通车前往核心景区；自驾导航直接搜井冈山即可。"]]}',2,'慢一点，风景才来得及认识你。','on');
