INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳阳楼洞庭湖周末逃离线','nearby','岳阳 · 岳阳楼洞庭湖','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',15900,8700,2,'岳阳楼 / 君山岛 / 圣安寺 —— 一张票打包岳阳楼洞庭湖精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「岳阳楼洞庭湖」一日轻旅行——水景。君山银针是十大名茶之一。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 岳阳"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"岳阳集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"岳阳楼洞庭湖游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"岳阳楼","description":"首站直达岳阳楼，洞庭天下水岳阳天下楼，背岳阳楼记免票。建议停留72分钟，跟着攻略动线走省一半时间。","addr":"岳阳市岳阳楼区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排巴陵全鱼席——人均约78元，洞庭鱼头是本地招牌，点菜照着攻略走。","addr":"岳阳楼景区旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"君山岛","description":"午后游览君山岛，湘妃竹与银针茶的故乡。","addr":"洞庭湖君山岛","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"圣安寺","description":"收官打卡圣安寺，古塔与湖景同框。随后自由活动，采购伴手礼。","addr":"岳阳市南湖畔","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"岳阳楼","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"岳阳楼是岳阳楼洞庭湖最有代表性的看点，洞庭天下水岳阳天下楼，背岳阳楼记免票。攻略把它排进主线，时间留得最足。","notice":"洞庭天下水岳阳天下楼，背岳阳楼记免票。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"岳阳市岳阳楼区"},{"spotId":"S2","name":"君山岛","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"君山岛是岳阳楼洞庭湖最有代表性的看点，湘妃竹与银针茶的故乡。攻略把它排进主线，时间留得最足。","notice":"湘妃竹与银针茶的故乡。这个点位上午光线最好。","durationMinutes":180,"addr":"洞庭湖君山岛"},{"spotId":"S3","name":"圣安寺","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"圣安寺是岳阳楼洞庭湖最有代表性的看点，古塔与湖景同框。攻略把它排进主线，时间留得最足。","notice":"古塔与湖景同框。这个点位上午光线最好。","durationMinutes":60,"addr":"岳阳市南湖畔"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"洞庭鱼头（人均78元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是洞庭鱼头，巴陵全鱼席本地人都认这家，点单照攻略不踩雷。","addr":"岳阳楼景区旁"},{"title":"君山银针鸡片（人均68元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是君山银针鸡片，茶宴馆本地人都认这家，点单照攻略不踩雷。","addr":"君山岛上"},{"title":"岳阳虾饼（人均10元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是岳阳虾饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"汴河街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7155,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","墨镜与拍照道具","防晒霜与遮阳帽","轻便雨衣或折叠伞","身份证件与手机充电宝","保温水杯与少量现金","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 岳阳 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('元阳哈尼梯田出片打卡线','nearby','红河 · 元阳哈尼梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',28100,15400,1,'多依树梯田 / 老虎嘴梯田 / 箐口哈尼民俗村 —— 一张票打包元阳哈尼梯田精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「元阳哈尼梯田」一日轻旅行——古村落。元阳红米营养丰富。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 红河"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"红河集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"元阳哈尼梯田游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"多依树梯田","description":"首站直达多依树梯田，日出云海最佳观赏点，提前1小时占位。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"元阳县新街镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排农家餐厅——人均约35元，哈尼梯田红米是本地招牌，点菜照着攻略走。","addr":"多依树村","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"老虎嘴梯田","description":"午后游览老虎嘴梯田，日落时梯田变金色。","addr":"元阳县攀枝花乡","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"箐口哈尼民俗村","description":"收官打卡箐口哈尼民俗村，蘑菇房与梯田同框。随后自由活动，采购伴手礼。","addr":"元阳县","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"多依树梯田","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"多依树梯田是元阳哈尼梯田最有代表性的看点，日出云海最佳观赏点，提前1小时占位。攻略把它排进主线，时间留得最足。","notice":"日出云海最佳观赏点，提前1小时占位。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"元阳县新街镇"},{"spotId":"S2","name":"老虎嘴梯田","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"老虎嘴梯田是元阳哈尼梯田最有代表性的看点，日落时梯田变金色。攻略把它排进主线，时间留得最足。","notice":"日落时梯田变金色。这个点位上午光线最好。","durationMinutes":120,"addr":"元阳县攀枝花乡"},{"spotId":"S3","name":"箐口哈尼民俗村","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"箐口哈尼民俗村是元阳哈尼梯田最有代表性的看点，蘑菇房与梯田同框。攻略把它排进主线，时间留得最足。","notice":"蘑菇房与梯田同框。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"元阳县"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"哈尼梯田红米（人均35元）","description":"红河 · 元阳哈尼梯田的招牌是哈尼梯田红米，农家餐厅本地人都认这家，点单照攻略不踩雷。","addr":"多依树村"},{"title":"梯田鱼（人均58元）","description":"红河 · 元阳哈尼梯田的招牌是梯田鱼，村中渔家本地人都认这家，点单照攻略不踩雷。","addr":"箐口村"},{"title":"竹筒鸡（人均68元）","description":"红河 · 元阳哈尼梯田的招牌是竹筒鸡，哈尼农家本地人都认这家，点单照攻略不踩雷。","addr":"新街镇"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12645,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","少量零食补给","身份证件与手机充电宝","相机或运动相机","保温水杯与少量现金","常用药品（肠胃药/创可贴）","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["当地有什么必吃？","到了 红河，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'这一程，山水都在替你说话。','on');
