INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('庐山人文漫游线','nearby','九江 · 庐山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',23200,12700,2,'锦绣谷 / 三叠泉 / 如琴湖花径 —— 一张票打包庐山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「庐山」一日轻旅行——山岳。庐山云雾茶记得认准原产地标志。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 九江"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"九江集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"庐山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"锦绣谷","description":"首站直达锦绣谷，云雾多发地段，下午常被云海包裹。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"庐山风景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排牯岭镇饭馆——人均约128元，庐山三石宴是本地招牌，点菜照着攻略走。","addr":"牯岭镇河西路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"三叠泉","description":"午后游览三叠泉，不到三叠泉不算庐山客，往返台阶多。","addr":"庐山东南麓","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"如琴湖花径","description":"收官打卡如琴湖花径，清晨人少出片，环湖半小时。随后自由活动，采购伴手礼。","addr":"牯岭镇西侧","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"锦绣谷","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"锦绣谷是庐山最有代表性的看点，云雾多发地段，下午常被云海包裹。攻略把它排进主线，时间留得最足。","notice":"云雾多发地段，下午常被云海包裹。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"庐山风景区"},{"spotId":"S2","name":"三叠泉","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights"