INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五大道瓷房子精华一日','nearby','和平 · 五大道瓷房子','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',14300,7800,5,'五大道 / 瓷房子 / 古文化街 —— 一张票打包五大道瓷房子精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「五大道瓷房子」一日轻旅行——文艺。天津泥人张彩塑传神。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"天津 · 和平"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"和平集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"五大道瓷房子游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"五大道","description":"首站直达五大道，万国建筑博览会，马车游。建议停留120分钟，跟着攻略动线走省一半时间。","addr":"天津市和平区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排南楼煎饼——人均约10元，煎饼果子是本地招牌，点菜照着攻略走。","addr":"和平区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"瓷房子","description":"午后游览瓷房子，7亿瓷片房子，白天看外观。","addr":"和平区赤峰道","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"古文化街","description":"收官打卡古文化街，泥人张杨柳青年画。随后自由活动，采购伴手礼。","addr":"南开区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"五大道","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"五大道是五大道瓷房子最有代表性的看点，万国建筑博览会，马车游。攻略把它排进主线，时间留得最足。","notice":"万国建筑博览会，马车游。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"天津市和平区"},{"spotId":"S2","name":"瓷房子","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"瓷房子是五大道瓷房子最有代表性的看点，7亿瓷片房子，白天看外观。攻略把它排进主线，时间留得最足。","notice":"7亿瓷片房子，白天看外观。周边有休息区与补给点，随时停留。","durationMinutes":30,"addr":"和平区赤峰道"},{"spotId":"S3","name":"古文化街","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"古文化街是五大道瓷房子最有代表性的看点，泥人张杨柳青年画。攻略把它排进主线，时间留得最足。","notice":"泥人张杨柳青年画。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"南开区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"煎饼果子（人均10元）","description":"和平 · 五大道瓷房子的招牌是煎饼果子，南楼煎饼本地人都认这家，点单照攻略不踩雷。","addr":"和平区"},{"title":"狗不理包子（人均45元）","description":"和平 · 五大道瓷房子的招牌是狗不理包子，狗不理总店本地人都认这家，点单照攻略不踩雷。","addr":"山东路"},{"title":"耳朵眼炸糕（人均8元）","description":"和平 · 五大道瓷房子的招牌是耳朵眼炸糕，耳朵眼总店本地人都认这家，点单照攻略不踩雷。","addr":"古文化街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6435,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","墨镜与拍照道具","轻便雨衣或折叠伞","少量零食补给","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 和平 的交通方便吗？","推荐先到 和平，再打车或景区直通车前往核心景区；自驾导航直接搜五大道瓷房子即可。"],["当地有什么必吃？","到了 和平，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙虎山治愈一日','nearby','鹰潭 · 龙虎山','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',18800,10300,2,'仙水岩 / 泸溪河竹筏 / 上清古镇 —— 一张票打包龙虎山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「龙虎山」一日轻旅行——水景。龙虎山道教养生茶值得带。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 鹰潭"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"鹰潭集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"龙虎山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"仙水岩","description":"首站直达仙水岩，悬棺表演一天四场，提前占前排。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"龙虎山仙水岩景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排上清古镇饭店——人均约68元，天师板栗烧鸡是本地招牌，点菜照着攻略走。","addr":"上清古镇长街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"泸溪河竹筏","description":"午后游览泸溪河竹筏，顺流漂90分钟，防晒必做。","addr":"龙虎山竹筏码头","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"上清古镇","description":"收官打卡上清古镇，天师府在此，古街人少。随后自由活动，采购伴手礼。","addr":"龙虎山上清镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"仙水岩","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"仙水岩是龙虎山最有代表性的看点，悬棺表演一天四场，提前占前排。攻略把它排进主线，时间留得最足。","notice":"悬棺表演一天四场，提前占前排。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"龙虎山仙水岩景区"},{"spotId":"S2","name":"泸溪河竹筏","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80",