INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙脊梯田人文漫游线','nearby','桂林 · 龙脊梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',22700,12400,1,'平安寨七星伴月 / 金坑大寨 / 黄洛红瑶寨 —— 一张票打包龙脊梯田精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「龙脊梯田」一日轻旅行——古村落。龙脊辣椒酱拌饭一绝。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"桂林集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"龙脊梯田游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"平安寨七星伴月","description":"首站直达平安寨七星伴月，经典梯田观景台，徒步30分钟。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"龙胜县龙脊镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排梯田农家——人均约25元，竹筒饭是本地招牌，点菜照着攻略走。","addr":"平安寨","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"金坑大寨","description":"午后游览金坑大寨，缆车直达3号观景点，日落最佳。","addr":"龙脊梯田金坑","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"黄洛红瑶寨","description":"收官打卡黄洛红瑶寨，天下第一长发村表演。随后自由活动，采购伴手礼。","addr":"龙脊山下","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"平安寨七星伴月","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"平安寨七星伴月是龙脊梯田最有代表性的看点，经典梯田观景台，徒步30分钟。攻略把它排进主线，时间留得最足。","notice":"经典梯田观景台，徒步30分钟。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙胜县龙脊镇"},{"spotId":"S2","name":"金坑大寨","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"金坑大寨是龙脊梯田最有代表性的看点，缆车直达3号观景点，日落最佳。攻略把它排进主线，时间留得最足。","notice":"缆车直达3号观景点，日落最佳。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"龙脊梯田金坑"},{"spotId":"S3","name":"黄洛红瑶寨","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"黄洛红瑶寨是龙脊梯田最有代表性的看点，天下第一长发村表演。攻略把它排进主线，时间留得最足。","notice":"天下第一长发村表演。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"龙脊山下"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"竹筒饭（人均25元）","description":"桂林 · 龙脊梯田的招牌是竹筒饭，梯田农家本地人都认这家，点单照攻略不踩雷。","addr":"平安寨"},{"title":"土鸡煲（人均68元）","description":"桂林 · 龙脊梯田的招牌是土鸡煲，大寨农家本地人都认这家，点单照攻略不踩雷。","addr":"金坑梯田"},{"title":"龙脊茶（人均20元）","description":"桂林 · 龙脊梯田的招牌是龙脊茶，茶农家本地人都认这家，点单照攻略不踩雷。","addr":"黄洛瑶寨"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10215,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","相机或运动相机","少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 桂林，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('霞浦滩涂微度假一日','nearby','宁德 · 霞浦滩涂','photography','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',17900,9800,12,'北岐滩涂 / 杨家溪 / 东壁日落 —— 一张票打包霞浦滩涂精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「霞浦滩涂」一日轻旅行——摄影胜地。霞浦紫菜海带全国第一。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 宁德"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"宁德集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"霞浦滩涂游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"北岐滩涂","description":"首站直达北岐滩涂，日出紫菜架光影，摄影圣地。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"霞浦县松港街道","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排海鲜大排档——人均约68元，霞浦剑蛏是本地招牌，点菜照着攻略走。","addr":"三沙镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"杨家溪","description":"午后游览杨家溪，千年枫榕树群，牛群穿雾。","addr":"霞浦县牙城镇","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"东壁日落","description":"收官打卡东壁日落，落日渔船归航机位。随后自由活动，采购伴手礼。","addr":"霞浦县三沙镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"北岐滩涂","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"北岐滩涂是霞浦滩涂最有代表性的看点，日出紫菜架光影，摄影圣地。攻略把它排进主线，时间留得最足。","notice":"日出紫菜架光影，摄影圣地。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"霞浦县松港街道"},{"spotId":"S2","name":"杨家溪","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlight