INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('恩施大峡谷轻徒步一日','nearby','恩施 · 恩施大峡谷','adventure','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',16300,8900,9,'七星寨 / 云龙地缝 / 梭布垭石林 —— 一张票打包恩施大峡谷精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「恩施大峡谷」一日轻旅行——探险地。恩施玉露茶古法蒸青。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 恩施"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"恩施集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"恩施大峡谷游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"七星寨","description":"首站直达七星寨，一炷香奇观，云龙地缝联游。建议停留240分钟，跟着攻略动线走省一半时间。","addr":"恩施市沐抚街道","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排张关合渣——人均约58元，土家腊蹄子是本地招牌，点菜照着攻略走。","addr":"恩施市区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"云龙地缝","description":"午后游览云龙地缝，U型地缝瀑布成群。","addr":"大峡谷景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"梭布垭石林","description":"收官打卡梭布垭石林，戴冠石林迷宫。随后自由活动，采购伴手礼。","addr":"恩施市太阳河乡","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"七星寨","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"七星寨是恩施大峡谷最有代表性的看点，一炷香奇观，云龙地缝联游。攻略把它排进主线，时间留得最足。","notice":"一炷香奇观，云龙地缝联游。这个点位上午光线最好。","durationMinutes":300,"addr":"恩施市沐抚街道"},{"spotId":"S2","name":"云龙地缝","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"云龙地缝是恩施大峡谷最有代表性的看点，U型地缝瀑布成群。攻略把它排进主线，时间留得最足。","notice":"U型地缝瀑布成群。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"大峡谷景区"},{"spotId":"S3","name":"梭布垭石林","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"梭布垭石林是恩施大峡谷最有代表性的看点，戴冠石林迷宫。攻略把它排进主线，时间留得最足。","notice":"戴冠石林迷宫。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"恩施市太阳河乡"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"土家腊蹄子（人均58元）","description":"恩施 · 恩施大峡谷的招牌是土家腊蹄子，张关合渣本地人都认这家，点单照攻略不踩雷。","addr":"恩施市区"},{"title":"合渣（人均28元）","description":"恩施 · 恩施大峡谷的招牌是合渣，土家合渣馆本地人都认这家，点单照攻略不踩雷。","addr":"沐抚镇"},{"title":"土豆饭（人均22元）","description":"恩施 · 恩施大峡谷的招牌是土豆饭，农家本地人都认这家，点单照攻略不踩雷。","addr":"大峡谷游客中心"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7335,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具","常用药品（肠胃药/创可贴）","相机或运动相机","少量零食补给","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('老君山精华一日','nearby','栾川 · 老君山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',25300,13900,2,'金顶道观群 / 十里画屏 / 追梦谷 —— 一张票打包老君山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「老君山」一日轻旅行——山岳。老君山高山茶清冽。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 栾川"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"栾川集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"老君山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"金顶道观群","description":"首站直达金顶道观群，云海雪景封神，远赴人间惊鸿宴。建议停留240分钟，跟着攻略动线走省一半时间。","addr":"洛阳市栾川县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排山城豆腐宴——人均约28元，栾川豆腐是本地招牌，点菜照着攻略走。","addr":"栾川县城","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"十里画屏","description":"午后游览十里画屏，滑道下山，省膝盖。","addr":"老君山石林","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"追梦谷","description":"收官打卡追梦谷，溪瀑竹林轻松线。随后自由活动，采购伴手礼。","addr":"老君山脚下","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"金顶道观群","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"金顶道观群是老君山最有代表性的看点，云海雪景封神，远赴人间惊鸿宴。攻略把它排进主线，时间留得最足。","notice":"云海雪景封神，远赴人间惊鸿宴。这个点位上午光线最好。","durationMinutes":300,"addr":"洛阳市栾川县"},{"spotId":"S2","name":"十里画屏","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"十里画屏是老君山最有代表性的看点，滑道下山，省膝盖。攻略把它排进主线，时间留得最足。","notice":"滑道下山，省膝盖。这个点位上午光线最好。","durationMinutes":120,"addr":"老君山石林"},{"spotId":"S3","name":"追梦谷","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"追梦谷是老君山最有代表性的看点，溪瀑竹林轻松线。攻略把它排进主线，时间留得最足。","notice":"溪瀑竹林轻松线。这个点位上午光线最好。","durationMinutes":120,"addr":"老君山脚下"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"栾川豆腐（人均28元）","description":"栾川 · 老君山的招牌是栾川豆腐，山城豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"栾川县城"},{"title":"蝌蚪面（人均18元）","description":"栾川 · 老君山的招牌是蝌蚪面，老君山农家本地人都认这家，点单照攻略不踩雷。","addr":"鸡冠洞乡"},{"title":"玉米糁汤（人均10元）","description":"栾川 · 老君山的招牌是玉米糁汤，农家早餐本地人都认这家，点单照攻略不踩雷。","addr":"景区民宿"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":11385,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","轻便雨衣或折叠伞","少量零食补给","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["当地有什么必吃？","到了 栾川，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一程，山水都在替你说话。','on');
