INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('潮州古城纯玩直通车','nearby','潮州 · 潮州古城','food','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',15000,8200,3,'广济桥 / 牌坊街 / 韩文公祠 —— 一张票打包潮州古城精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「潮州古城」一日轻旅行——美食。潮州手拉朱泥壶雅致。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 潮州"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"潮州集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"潮州古城游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"广济桥","description":"首站直达广济桥，十八梭船廿四洲，灯光秀。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"潮州市湘桥区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排官塘兄弟——人均约88元，牛肉火锅是本地招牌，点菜照着攻略走。","addr":"官塘镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"牌坊街","description":"午后游览牌坊街，23座古牌坊，手拉壶体验。","addr":"湘桥区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"韩文公祠","description":"收官打卡韩文公祠，纪念韩愈，笔架山对望。随后自由活动，采购伴手礼。","addr":"韩江东岸","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"广济桥","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"广济桥是潮州古城最有代表性的看点，十八梭船廿四洲，灯光秀。攻略把它排进主线，时间留得最足。","notice":"十八梭船廿四洲，灯光秀。这个点位上午光线最好。","durationMinutes":120,"addr":"潮州市湘桥区"},{"spotId":"S2","name":"牌坊街","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"牌坊街是潮州古城最有代表性的看点，23座古牌坊，手拉壶体验。攻略把它排进主线，时间留得最足。","notice":"23座古牌坊，手拉壶体验。这个点位上午光线最好。","durationMinutes":120,"addr":"湘桥区"},{"spotId":"S3","name":"韩文公祠","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"韩文公祠是潮州古城最有代表性的看点，纪念韩愈，笔架山对望。攻略把它排进主线，时间留得最足。","notice":"纪念韩愈，笔架山对望。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"韩江东岸"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牛肉火锅（人均88元）","description":"潮州 · 潮州古城的招牌是牛肉火锅，官塘兄弟本地人都认这家，点单照攻略不踩雷。","addr":"官塘镇"},{"title":"蚝烙（人均25元）","description":"潮州 · 潮州古城的招牌是蚝烙，老柯蚝烙本地人都认这家，点单照攻略不踩雷。","addr":"西马路"},{"title":"鸭母捻（人均12元）","description":"潮州 · 潮州古城的招牌是鸭母捻，胡荣泉本地人都认这家，点单照攻略不踩雷。","addr":"牌坊街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6750,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","保温水杯与少量现金","相机或运动相机","少量零食补给","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七彩丹霞周末逃离线','nearby','张掖 · 七彩丹霞','photography','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',15500,8500,12,'七彩丹霞 / 平山湖大峡谷 / 马蹄寺 —— 一张票打包七彩丹霞精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「七彩丹霞」一日轻旅行——摄影胜地。张掖圆梨啤特有风味。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 张掖"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"张掖集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"七彩丹霞游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"七彩丹霞","description":"首站直达七彩丹霞，上帝的调色盘，4号观景台日落。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"张掖市临泽县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排张掖搓鱼子——人均约15元，搓鱼面是本地招牌，点菜照着攻略走。","addr":"甘州区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"平山湖大峡谷","description":"午后游览平山湖大峡谷，张掖版科罗拉多，越野车深入。","addr":"甘州区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"马蹄寺","description":"收官打卡马蹄寺，石窟与裕固族风情。随后自由活动，采购伴手礼。","addr":"肃南县","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"七彩丹霞","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"七彩丹霞是七彩丹霞最有代表性的看点，上帝的调色盘，4号观景台日落。攻略把它排进主线，时间留得最足。","notice":"上帝的调色盘，4号观景台日落。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"张掖市临泽县"},{"spotId":"S2","name":"平山湖大峡谷","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"平山湖大峡谷是七彩丹霞最有代表性的看点，张掖版科罗拉多，越野车深入。攻略把它排进主线，时间留得最足。","notice":"张掖版科罗拉多，越野车深入。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"甘州区"},{"spotId":"S3","name":"马蹄寺","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"马蹄寺是七彩丹霞最有代表性的看点，石窟与裕固族风情。攻略把它排进主线，时间留得最足。","notice":"石窟与裕固族风情。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"肃南县"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"搓鱼面（人均15元）","description":"张掖 · 七彩丹霞的招牌是搓鱼面，张掖搓鱼子本地人都认这家，点单照攻略不踩雷。","addr":"甘州区"},{"title":"炒炮（人均18元）","description":"张掖 · 七彩丹霞的招牌是炒炮，孙记炒炮本地人都认这家，点单照攻略不踩雷。","addr":"大佛寺旁"},{"title":"牛肉小饭（人均12元）","description":"张掖 · 七彩丹霞的招牌是牛肉小饭，早市小饭馆本地人都认这家，点单照攻略不踩雷。","addr":"南关市场"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6975,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","少量零食补给","身份证件与手机充电宝","保温水杯与少量现金","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雅鲁藏布大峡谷出片打卡线','nearby','林芝 · 雅鲁藏布大峡谷','plateau','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',24900,13600,2,'南迦巴瓦观景台 / 雅鲁藏布大峡谷 / 鲁朗林海 —— 一张票打包雅鲁藏布大峡谷精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「雅鲁藏布大峡谷」一日轻旅行——高原。林芝松茸6-8月最鲜。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 林芝"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"林芝集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"雅鲁藏布大峡谷游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"南迦巴瓦观景台","description":"首站直达南迦巴瓦观景台，羞女峰十人九不遇，直白村最近。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"米林县派镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排石锅鸡总店——人均约128元，鲁朗石锅鸡是本地招牌，点菜照着攻略走。","addr":"鲁朗镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"雅鲁藏布大峡谷","description":"午后游览雅鲁藏布大峡谷，世界最深深峡，换乘游览。","addr":"林芝市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"鲁朗林海","description":"收官打卡鲁朗林海，东方瑞士，石锅鸡之乡。随后自由活动，采购伴手礼。","addr":"鲁朗镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"南迦巴瓦观景台","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"南迦巴瓦观景台是雅鲁藏布大峡谷最有代表性的看点，羞女峰十人九不遇，直白村最近。攻略把它排进主线，时间留得最足。","notice":"羞女峰十人九不遇，直白村最近。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"米林县派镇"},{"spotId":"S2","name":"雅鲁藏布大峡谷","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?aut