INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大理古城洱海慢游一日','nearby','大理 · 大理古城洱海','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',20200,11100,2,'洱海生态廊道 / 大理古城 / 崇圣寺三塔 —— 一张票打包大理古城洱海精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「大理古城洱海」一日轻旅行——水景。喜洲粑粑现烤的最香。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 大理"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"大理集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"大理古城洱海游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"洱海生态廊道","description":"首站直达洱海生态廊道，租电动车骑行，S湾拍倒影。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"大理市环海西路","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排严家大院——人均约48元，白族三道茶是本地招牌，点菜照着攻略走。","addr":"喜洲古镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"大理古城","description":"午后游览大理古城，洋人街与五华楼，夜晚酒吧街热闹。","addr":"大理市一塔路","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"崇圣寺三塔","description":"收官打卡崇圣寺三塔，大理地标，倒影公园拍三塔。随后自由活动，采购伴手礼。","addr":"大理市三塔路","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"洱海生态廊道","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"洱海生态廊道是大理古城洱海最有代表性的看点，租电动车骑行，S湾拍倒影。攻略把它排进主线，时间留得最足。","notice":"租电动车骑行，S湾拍倒影。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"大理市环海西路"},{"spotId":"S2","name":"大理古城","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"大理古城是大理古城洱海最有代表性的看点，洋人街与五华楼，夜晚酒吧街热闹。攻略把它排进主线，时间留得最足。","notice":"洋人街与五华楼，夜晚酒吧街热闹。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"大理市一塔路"},{"spotId":"S3","name":"崇圣寺三塔","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"崇圣寺三塔是大理古城洱海最有代表性的看点，大理地标，倒影公园拍三塔。攻略把它排进主线，时间留得最足。","notice":"大理地标，倒影公园拍三塔。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"大理市三塔路"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"白族三道茶（人均48元）","description":"大理 · 大理古城洱海的招牌是白族三道茶，严家大院本地人都认这家，点单照攻略不踩雷。","addr":"喜洲古镇"},{"title":"砂锅鱼（人均78元）","description":"大理 · 大理古城洱海的招牌是砂锅鱼，大理砂锅鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"才村码头"},{"title":"乳扇（人均12元）","description":"大理 · 大理古城洱海的招牌是乳扇，杨记乳扇本地人都认这家，点单照攻略不踩雷。","addr":"古城人民路"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9090,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","防晒霜与遮阳帽","墨镜与拍照道具","相机或运动相机","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 大理 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 大理 的交通方便吗？","推荐先到 大理，再打车或景区直通车前往核心景区；自驾导航直接搜大理古城洱海即可。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九寨沟轻徒步一日','nearby','阿坝 · 九寨沟','water','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',18500,10100,2,'五花海 / 诺日朗瀑布 / 长海 —— 一张票打包九寨沟精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「九寨沟」一日轻旅行——水景。九寨沟牦牛酸奶值得尝。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"阿坝集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"九寨沟游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"五花海","description":"首站直达五花海，九寨精华，孔雀河道顺光最美。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"九寨沟县漳扎镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排沟口藏家——人均约78元，牦牛肉汤锅是本地招牌，点菜照着攻略走。","addr":"漳扎镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"诺日朗瀑布","description":"午后游览诺日朗瀑布，中国最宽钙华瀑布。","addr":"九寨沟中心站","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"长海","description":"收官打卡长海，最大海子，雪山倒影。随后自由活动，采购伴手礼。","addr":"九寨沟则查洼沟","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"五花海","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"五花海是九寨沟最有代表性的看点，九寨精华，孔雀河道顺光最美。攻略把它排进主线，时间留得最足。","notice":"九寨精华，孔雀河道顺光最美。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"九寨沟县漳扎镇"},{"spotId":"S2","name":"诺日朗瀑布","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"诺日朗瀑布是九寨沟最有代表性的看点，中国最宽钙华瀑布。攻略把它排进主线，时间留得最足。","notice":"中国最宽钙华瀑布。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"九寨沟中心站"},{"spotId":"S3","name":"长海","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"长海是九寨沟最有代表性的看点，最大海子，雪山倒影。攻略把它排进主线，时间留得最足。","notice":"最大海子，雪山倒影。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"九寨沟则查洼沟"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉汤锅（人均78元）","description":"阿坝 · 九寨沟的招牌是牦牛肉汤锅，沟口藏家本地人都认这家，点单照攻略不踩雷。","addr":"漳扎镇"},{"title":"青稞酒（人均30元）","description":"阿坝 · 九寨沟的招牌是青稞酒，藏家体验本地人都认这家，点单照攻略不踩雷。","addr":"藏寨"},{"title":"糌粑（人均20元）","description":"阿坝 · 九寨沟的招牌是糌粑，藏族人家本地人都认这家，点单照攻略不踩雷。","addr":"树正寨"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8325,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","换洗衣物与外套（早晚温差）","墨镜与拍照道具","少量零食补给","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一程，山水都在替你说话。','on');
