INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武当山出片打卡线','nearby','十堰 · 武当山','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',13600,7400,2,'金顶 / 南岩宫 / 紫霄宫 —— 一张票打包武当山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「武当山」一日轻旅行——山岳。武当道茶甘醇。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 十堰"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"十堰集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"武当山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"金顶","description":"首站直达金顶，武当之巅金殿，转运台。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"十堰市丹江口","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排太子坡素斋——人均约48元，道家素斋是本地招牌，点菜照着攻略走。","addr":"武当山镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"南岩宫","description":"午后游览南岩宫，龙头香悬崖奇观。","addr":"武当山南岩","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"紫霄宫","description":"收官打卡紫霄宫，皇家道观规制。随后自由活动，采购伴手礼。","addr":"武当山展旗峰","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武当山最有代表性的看点，武当之巅金殿，转运台。攻略把它排进主线，时间留得最足。","notice":"武当之巅金殿，转运台。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"十堰市丹江口"},{"spotId":"S2","name":"南岩宫","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"南岩宫是武当山最有代表性的看点，龙头香悬崖奇观。攻略把它排进主线，时间留得最足。","notice":"龙头香悬崖奇观。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"武当山南岩"},{"spotId":"S3","name":"紫霄宫","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"紫霄宫是武当山最有代表性的看点，皇家道观规制。攻略把它排进主线，时间留得最足。","notice":"皇家道观规制。这个点位上午光线最好。","durationMinutes":90,"addr":"武当山展旗峰"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"道家素斋（人均48元）","description":"十堰 · 武当山的招牌是道家素斋，太子坡素斋本地人都认这家，点单照攻略不踩雷。","addr":"武当山镇"},{"title":"武当冻豆腐（人均38元）","description":"十堰 · 武当山的招牌是武当冻豆腐，山间餐馆本地人都认这家，点单照攻略不踩雷。","addr":"南岩"},{"title":"太极养生汤（人均68元）","description":"十堰 · 武当山的招牌是太极养生汤，道医药膳本地人都认这家，点单照攻略不踩雷。","addr":"紫霄宫旁"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6120,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金","少量零食补给","换洗衣物与外套（早晚温差）","墨镜与拍照道具","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('兵马俑城墙亲子轻松线','nearby','西安 · 兵马俑城墙','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',16700,9100,7,'秦始皇兵马俑 / 西安城墙 / 大唐不夜城 —— 一张票打包兵马俑城墙精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「兵马俑城墙」一日轻旅行——人文。兵马俑文创手办很火。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 西安"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"西安集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"兵马俑城墙游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"秦始皇兵马俑","description":"首站直达秦始皇兵马俑，一号坑震撼，讲解必请。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"西安市临潼区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排子午路张记——人均约15元，肉夹馍是本地招牌，点菜照着攻略走。","addr":"临潼区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"西安城墙","description":"午后游览西安城墙，骑行环城14公里，日落最美。","addr":"碑林区南门","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"大唐不夜城","description":"收官打卡大唐不夜城，不倒翁小姐姐与灯光夜市。随后自由活动，采购伴手礼。","addr":"雁塔区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"秦始皇兵马俑","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"秦始皇兵马俑是兵马俑城墙最有代表性的看点，一号坑震撼，讲解必请。攻略把它排进主线，时间留得最足。","notice":"一号坑震撼，讲解必请。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"西安市临潼区"},{"spotId":"S2","name":"西安城墙","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"西安城墙是兵马俑城墙最有代表性的看点，骑行环城14公里，日落最美。攻略把它排进主线，时间留得最足。","notice":"骑行环城14公里，日落最美。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"碑林区南门"},{"spotId":"S3","name":"大唐不夜城","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"大唐不夜城是兵马俑城墙最有代表性的看点，不倒翁小姐姐与灯光夜市。攻略把它排进主线，时间留得最足。","notice":"不倒翁小姐姐与灯光夜市。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"雁塔区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肉夹馍（人均15元）","description":"西安 · 兵马俑城墙的招牌是肉夹馍，子午路张记本地人都认这家，点单照攻略不踩雷。","addr":"临潼区"},{"title":"biangbiang面（人均22元）","description":"西安 · 兵马俑城墙的招牌是biangbiang面，老碗会本地人都认这家，点单照攻略不踩雷。","addr":"南院门"},{"title":"羊肉泡馍（人均45元）","description":"西安 · 兵马俑城墙的招牌是羊肉泡馍，老孙家本地人都认这家，点单照攻略不踩雷。","addr":"东关正街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7515,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","墨镜与拍照道具","少量零食补给","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 西安 的交通方便吗？","推荐先到 西安，再打车或景区直通车前往核心景区；自驾导航直接搜兵马俑城墙即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('栈桥崂山人文漫游线','nearby','青岛 · 栈桥崂山','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',20100,11000,6,'栈桥 / 崂山仰口 / 八大关 —— 一张票打包栈桥崂山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「栈桥崂山」一日轻旅行——海滨。青岛啤酒原浆当天最新鲜。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 青岛"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"青岛集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"栈桥崂山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"栈桥","description":"首站直达栈桥，回澜阁海鸥季，夜色灯光。建议停留48分钟，跟着攻略动线走省一半时间。","addr":"青岛市市南区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排船歌鱼水饺——人均约58元，海鲜水饺是本地招牌，点菜照着攻略走。","addr":"闽江路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"崂山仰口","description":"午后游览崂山仰口，海上第一名山，觅天洞。","addr":"崂山区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"八大关","description":"收官打卡八大关，万国建筑与梧桐，秋天最美。随后自由活动，采购伴手礼。","addr":"市南区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"栈桥","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"栈桥是栈桥崂山最有代表性的看点，回澜阁海鸥季，夜色灯光。攻略把它排进主线，时间留得最足。","notice":"回澜阁海鸥季，夜色灯光。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"青岛市市南区"},{"spotId":"S2","name":"崂山仰口","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"崂山仰口是栈桥崂山最有代表性的看点，海上第一名山，觅天洞。攻略把它排进主线，时间留得最足。","notice":"海上第一名山，觅天洞。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"崂山区"},{"spotId":"S3","name":"八大关","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"八大关是栈桥崂山最有代表性的看点，万国建筑与梧桐，秋天最美。攻略把它排进主线，时间留得最足。","notice":"万国建筑与梧桐，秋天最美。这个点位上午光线最好。","durationMinutes":120,"addr":"市南区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜水饺（人均58元）","description":"青岛 · 栈桥崂山的招牌是海鲜水饺，船歌鱼水饺本地人都认这家，点单照攻略不踩雷。","addr":"闽江路"},{"title":"野馄饨（人均15元）","description":"青岛 · 栈桥崂山的招牌是野馄饨，夜市馄饨摊本地人都认这家，点单照攻略不踩雷。","addr":"登州路"},{"title":"崂山菇炖鸡（人均68元）","description":"青岛 · 栈桥崂山的招牌是崂山菇炖鸡，山海农家本地人都认这家，点单照攻略不踩雷。","addr":"仰口湾"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9045,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","少量零食补给","相机或运动相机","身份证件与手机充电宝","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["到达 青岛 的交通方便吗？","推荐先到 青岛，再打车或景区直通车前往核心景区；自驾导航直接搜栈桥崂山即可。"],["当地有什么必吃？","到了 青岛，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 青岛 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七星岩微度假一日','nearby','肇庆 · 七星岩','water','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',13600,7400,2,'七星岩 / 鼎湖山 / 紫云谷 —— 一张票打包七星岩精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「七星岩」一日轻旅行——水景。端砚四大名砚之首。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 肇庆"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"肇庆集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"七星岩游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"七星岩","description":"首站直达七星岩，岭南第一奇观，湖山相映。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"肇庆市端州区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排皇中皇——人均约15元，裹蒸粽是本地招牌，点菜照着攻略走。","addr":"端州区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"鼎湖山","description":"午后游览鼎湖山，北回归线上的绿宝石，庆云寺。","addr":"鼎湖区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"紫云谷","description":"收官打卡紫云谷，端砚石产地，溪水清凉。随后自由活动，采购伴手礼。","addr":"羚羊峡","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"七星岩","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"七星岩是七星岩最有代表性的看点，岭南第一奇观，湖山相映。攻略把它排进主线，时间留得最足。","notice":"岭南第一奇观，湖山相映。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"肇庆市端州区"},{"spotId":"S2","name":"鼎湖山","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"鼎湖山是七星岩最有代表性的看点，北回归线上的绿宝石，庆云寺。攻略把它排进主线，时间留得最足。","notice":"北回归线上的绿宝石，庆云寺。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"鼎湖区"},{"spotId":"S3","name":"紫云谷","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"紫云谷是七星岩最有代表性的看点，端砚石产地，溪水清凉。攻略把它排进主线，时间留得最足。","notice":"端砚石产地，溪水清凉。这个点位上午光线最好。","durationMinutes":120,"addr":"羚羊峡"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"裹蒸粽（人均15元）","description":"肇庆 · 七星岩的招牌是裹蒸粽，皇中皇本地人都认这家，点单照攻略不踩雷。","addr":"端州区"},{"title":"文庆鲤（人均68元）","description":"肇庆 · 七星岩的招牌是文庆鲤，文庆鲤餐馆本地人都认这家，点单照攻略不踩雷。","addr":"鼎湖区"},{"title":"茶油鸡（人均48元）","description":"肇庆 · 七星岩的招牌是茶油鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"七星岩东门"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":6120,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","少量零食补给","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["当地有什么必吃？","到了 肇庆，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('青海湖茶卡慢游一日','nearby','海南州 · 青海湖茶卡','plateau','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',15800,8600,2,'二郎剑景区 / 茶卡盐湖 / 日月山 —— 一张票打包青海湖茶卡精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「青海湖茶卡」一日轻旅行——高原。青海湖黄蘑菇炖汤鲜。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"青海 · 海南州"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"海南州集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"青海湖茶卡游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"二郎剑景区","description":"首站直达二郎剑景区，油菜花与蓝湖，骑行湖岸。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"共和县青海湖南岸","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排青海老酸奶——人均约10元，老酸奶是本地招牌，点菜照着攻略走。","addr":"环湖公路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"茶卡盐湖","description":"午后游览茶卡盐湖，天空之镜，赤脚下盐滩。","addr":"乌兰县","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"日月山","description":"收官打卡日月山，文成公主进藏口，倒淌河。随后自由活动，采购伴手礼。","addr":"湟源县","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"二郎剑景区","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"二郎剑景区是青海湖茶卡最有代表性的看点，油菜花与蓝湖，骑行湖岸。攻略把它排进主线，时间留得最足。","notice":"油菜花与蓝湖，骑行湖岸。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"共和县青海湖南岸"},{"spotId":"S2","name":"茶卡盐湖","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"茶卡盐湖是青海湖茶卡最有代表性的看点，天空之镜，赤脚下盐滩。攻略把它排进主线，时间留得最足。","notice":"天空之镜，赤脚下盐滩。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"乌兰县"},{"spotId":"S3","name":"日月山","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"日月山是青海湖茶卡最有代表性的看点，文成公主进藏口，倒淌河。攻略把它排进主线，时间留得最足。","notice":"文成公主进藏口，倒淌河。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"湟源县"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"老酸奶（人均10元）","description":"海南州 · 青海湖茶卡的招牌是老酸奶，青海老酸奶本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"},{"title":"羊肉汤（人均35元）","description":"海南州 · 青海湖茶卡的招牌是羊肉汤，藏家羊汤本地人都认这家，点单照攻略不踩雷。","addr":"黑马河乡"},{"title":"糌粑（人均20元）","description":"海南州 · 青海湖茶卡的招牌是糌粑，牧民家访本地人都认这家，点单照攻略不踩雷。","addr":"茶卡镇"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7110,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","墨镜与拍照道具","防晒霜与遮阳帽","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["到达 海南州 的交通方便吗？","推荐先到 海南州，再打车或景区直通车前往核心景区；自驾导航直接搜青海湖茶卡即可。"],["几月份去 海南州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('呼伦贝尔草原轻徒步一日','nearby','呼伦贝尔 · 呼伦贝尔草原','village','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',25400,13900,1,'莫日格勒河 / 额尔古纳湿地 / 恩和俄罗斯族乡 —— 一张票打包呼伦贝尔草原精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「呼伦贝尔草原」一日轻旅行——古村落。呼伦贝尔风干牛肉原味香。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"内蒙古 · 呼伦贝尔"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"呼伦贝尔集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"呼伦贝尔草原游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"莫日格勒河","description":"首站直达莫日格勒河，天下第一曲水，断崖机位。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"陈巴尔虎旗","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排草原牧民人家——人均约128元，烤羊腿是本地招牌，点菜照着攻略走。","addr":"黑山头镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"额尔古纳湿地","description":"午后游览额尔古纳湿地，亚洲第一湿地，日落金色。","addr":"额尔古纳市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"恩和俄罗斯族乡","description":"收官打卡恩和俄罗斯族乡，木刻楞小屋与列巴。随后自由活动，采购伴手礼。","addr":"额尔古纳市","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"莫日格勒河","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"莫日格勒河是呼伦贝尔草原最有代表性的看点，天下第一曲水，断崖机位。攻略把它排进主线，时间留得最足。","notice":"天下第一曲水，断崖机位。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"陈巴尔虎旗"},{"spotId":"S2","name":"额尔古纳湿地","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=fo