INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('三清山亲子轻松线','nearby','上饶 · 三清山','mountain','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',28100,15400,2,'南清园 / 阳光海岸 / 万寿园 —— 一张票打包三清山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「三清山」一日轻旅行——山岳。三清山猴头菇干货是手信首选。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"上饶集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"三清山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"南清园","description":"首站直达南清园，巨蟒出山、东方女神都在这条环线，台阶多备水。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"三清山风景区南门","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排山脚农家菜——人均约58元，石鸡汤锅是本地招牌，点菜照着攻略走。","addr":"三清山外双溪服务区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"阳光海岸","description":"午后游览阳光海岸，栈道悬空，恐高走东线缓冲段。","addr":"三清山高空栈道","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"万寿园","description":"收官打卡万寿园，坡缓树多，适合收尾慢慢走。随后自由活动，采购伴手礼。","addr":"三清山南部入口","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"南清园","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"南清园是三清山最有代表性的看点，巨蟒出山、东方女神都在这条环线，台阶多备水。攻略把它排进主线，时间留得最足。","notice":"巨蟒出山、东方女神都在这条环线，台阶多备水。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"三清山风景区南门"},{"spotId":"S2","name":"阳光海岸","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"阳光海岸是三清山最有代表性的看点，栈道悬空，恐高走东线缓冲段。攻略把它排进主线，时间留得最足。","notice":"栈道悬空，恐高走东线缓冲段。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"三清山高空栈道"},{"spotId":"S3","name":"万寿园","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"万寿园是三清山最有代表性的看点，坡缓树多，适合收尾慢慢走。攻略把它排进主线，时间留得最足。","notice":"坡缓树多，适合收尾慢慢走。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"三清山南部入口"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"石鸡汤锅（人均58元）","description":"上饶 · 三清山的招牌是石鸡汤锅，山脚农家菜本地人都认这家，点单照攻略不踩雷。","addr":"三清山外双溪服务区"},{"title":"野艾果（人均10元）","description":"上饶 · 三清山的招牌是野艾果，路边农家本地人都认这家，点单照攻略不踩雷。","addr":"南山索道下站旁"},{"title":"三清山烧饼（人均8元）","description":"上饶 · 三清山的招牌是三清山烧饼，南清园补给点本地人都认这家，点单照攻略不踩雷。","addr":"登山途中补给站"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":12645,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["几月份去 上饶 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('明月山人文漫游线','nearby','宜春 · 明月山','mountain','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',24500,13400,2,'青云栈道 / 云谷飞瀑 / 温汤镇古井泉街 —— 一张票打包明月山精髓','["往返交通", "首道门票", "领队服务"]','{"overview":"「明月山」一日轻旅行——山岳。温汤富硒温泉蛋一元一个。本攻略按nearby玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"上午出发，傍晚返程，节奏轻松","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 宜春"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"宜春集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"明月山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"青云栈道","description":"首站直达青云栈道，悬空栈道绕山腰，云雾天如仙境。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"明月山风景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排温汤镇豆腐宴——人均约48元，温泉豆腐是本地招牌，点菜照着攻略走。","addr":"温汤镇古井旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"云谷飞瀑","description":"午后游览云谷飞瀑，宜春八景之一，负氧离子爆表。","addr":"明月山核心景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"温汤镇古井泉街","description":"收官打卡温汤镇古井泉街，富硒温泉足浴28元一位，晚上泡最解乏。随后自由活动，采购伴手礼。","addr":"袁州区温汤镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"青云栈道","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"青云栈道是明月山最有代表性的看点，悬空栈道绕山腰，云雾天如仙境。攻略把它排进主线，时间留得最足。","notice":"悬空栈道绕山腰，云雾天如仙境。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"明月山风景区"},{"spotId":"S2","name":"云谷飞瀑","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"云谷飞瀑是明月山最有代表性的看点，宜春八景之一，负氧离子爆表。攻略把它排进主线，时间留得最足。","notice":"宜春八景之一，负氧离子爆表。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"明月山核心景区"},{"spotId":"S3","name":"温汤镇古井泉街","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"温汤镇古井泉街是明月山最有代表性的看点，富硒温泉足浴28元一位，晚上泡最解乏。攻略把它排进主线，时间留得最足。","notice":"富硒温泉足浴28元一位，晚上泡最解乏。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"袁州区温汤镇"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"温泉豆腐（人均48元）","description":"宜春 · 明月山的招牌是温泉豆腐，温汤镇豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇古井旁"},{"title":"慈化鸡爪（人均22元）","description":"宜春 · 明月山的招牌是慈化鸡爪，宜春小吃店本地人都认这家，点单照攻略不踩雷。","addr":"温汤镇主街"},{"title":"扎粉（人均15元）","description":"宜春 · 明月山的招牌是扎粉，宜春扎粉店本地人都认这家，点单照攻略不踩雷。","addr":"古井泉街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":11025,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","少量零食补给","身份证件与手机充电宝","墨镜与拍照道具","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 宜春 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('南岳衡山深度二日','province','衡阳 · 南岳衡山','mountain','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',48900,26800,2,'祝融峰 / 南岳大庙 / 藏经殿 —— 一张票打包南岳衡山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「南岳衡山」两日慢旅行——山岳。南岳香文化用品别乱买。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 衡阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴衡阳","description":"集合出发，大巴直达南岳衡山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"祝融峰","description":"抵达后首游祝融峰，五岳最高峰观日出，山顶租赁军大衣。","addr":"南岳区衡山风景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐南岳素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"南岳大庙","description":"早起人少，南岳大庙精华时段，江南第一庙，香火极旺。","addr":"南岳区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐观音笋，人均38元，补充体力。","addr":"半山亭","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"藏经殿","description":"午后游览藏经殿，幽谷深林中的古刹。","addr":"衡山半山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"祝融峰","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"祝融峰是南岳衡山最有代表性的看点，五岳最高峰观日出，山顶租赁军大衣。攻略把它排进主线，时间留得最足。","notice":"五岳最高峰观日出，山顶租赁军大衣。这个点位上午光线最好。","durationMinutes":240,"addr":"南岳区衡山风景区"},{"spotId":"S2","name":"南岳大庙","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"南岳大庙是南岳衡山最有代表性的看点，江南第一庙，香火极旺。攻略把它排进主线，时间留得最足。","notice":"江南第一庙，香火极旺。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"南岳区"},{"spotId":"S3","name":"藏经殿","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"藏经殿是南岳衡山最有代表性的看点，幽谷深林中的古刹。攻略把它排进主线，时间留得最足。","notice":"幽谷深林中的古刹。这个点位上午光线最好。","durationMinutes":90,"addr":"衡山半山"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"南岳素斋（人均48元）","description":"衡阳 · 南岳衡山的招牌是南岳素斋，大庙素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"南岳大庙旁"},{"title":"观音笋（人均38元）","description":"衡阳 · 南岳衡山的招牌是观音笋，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"半山亭"},{"title":"衡山云雾茶（人均30元）","description":"衡阳 · 南岳衡山的招牌是衡山云雾茶，茶庄本地人都认这家，点单照攻略不踩雷。","addr":"南岳镇"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":22005,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","相机或运动相机","身份证件与手机充电宝","轻便雨衣或折叠伞","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["几月份去 衡阳 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('香格里拉经典二日','province','迪庆 · 香格里拉','plateau','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',46100,25300,2,'普达措国家公园 / 松赞林寺 / 独克宗古城 —— 一张票打包香格里拉精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「香格里拉」两日慢旅行——高原。牦牛肉干认准风干原味。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 迪庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴迪庆","description":"集合出发，大巴直达香格里拉，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"普达措国家公园","description":"抵达后首游普达措国家公园，属都湖栈道环湖，高原慢慢走。","addr":"香格里拉市建塘镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐牦牛肉火锅（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"松赞林寺","description":"早起人少，松赞林寺精华时段，小布达拉宫，顺时针转寺。","addr":"香格里拉市佛屏山前","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酥油茶，人均20元，补充体力。","addr":"古城内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"独克宗古城","description":"午后游览独克宗古城，转世界最大转经筒，夜景美。","addr":"香格里拉市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"普达措国家公园","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"普达措国家公园是香格里拉最有代表性的看点，属都湖栈道环湖，高原慢慢走。攻略把它排进主线，时间留得最足。","notice":"属都湖栈道环湖，高原慢慢走。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"香格里拉市建塘镇"},{"spotId":"S2","name":"松赞林寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"松赞林寺是香格里拉最有代表性的看点，小布达拉宫，顺时针转寺。攻略把它排进主线，时间留得最足。","notice":"小布达拉宫，顺时针转寺。这个点位上午光线最好。","durationMinutes":120,"addr":"香格里拉市佛屏山前"},{"spotId":"S3","name":"独克宗古城","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"独克宗古城是香格里拉最有代表性的看点，转世界最大转经筒，夜景美。攻略把它排进主线，时间留得最足。","notice":"转世界最大转经筒，夜景美。这个点位上午光线最好。","durationMinutes":120,"addr":"香格里拉市"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉火锅（人均88元）","description":"迪庆 · 香格里拉的招牌是牦牛肉火锅，市井牦牛火锅本地人都认这家，点单照攻略不踩雷。","addr":"独克宗古城"},{"title":"酥油茶（人均20元）","description":"迪庆 · 香格里拉的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"青稞饼（人均12元）","description":"迪庆 · 香格里拉的招牌是青稞饼，藏式饼铺本地人都认这家，点单照攻略不踩雷。","addr":"池慈卡街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":20745,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","相机或运动相机","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 迪庆 的交通方便吗？","推荐先到 迪庆，再打车或景区直通车前往核心景区；自驾导航直接搜香格里拉即可。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('峨眉山乐山大佛山水二日','province','乐山 · 峨眉山乐山大佛','mountain','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',49500,27200,2,'乐山大佛 / 峨眉山金顶 / 清音阁 —— 一张票打包峨眉山乐山大佛精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「峨眉山乐山大佛」两日慢旅行——山岳。峨眉雪芽茶清甜回甘。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 乐山"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴乐山","description":"集合出发，大巴直达峨眉山乐山大佛，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乐山大佛","description":"抵达后首游乐山大佛，九曲栈道近距离看大佛脚背。","addr":"乐山市凌云路","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐钵钵鸡（人均35元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"峨眉山金顶","description":"早起人少，峨眉山金顶精华时段，十方普贤金像，云海日出。","addr":"峨眉山市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐甜皮鸭，人均28元，补充体力。","addr":"乐山张公桥","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"清音阁","description":"午后游览清音阁，双桥清音，平路好走。","addr":"峨眉山低山区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乐山大佛","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"乐山大佛是峨眉山乐山大佛最有代表性的看点，九曲栈道近距离看大佛脚背。攻略把它排进主线，时间留得最足。","notice":"九曲栈道近距离看大佛脚背。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"乐山市凌云路"},{"spotId":"S2","name":"峨眉山金顶","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"峨眉山金顶是峨眉山乐山大佛最有代表性的看点，十方普贤金像，云海日出。攻略把它排进主线，时间留得最足。","notice":"十方普贤金像，云海日出。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"峨眉山市"},{"spotId":"S3","name":"清音阁","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"清音阁是峨眉山乐山大佛最有代表性的看点，双桥清音，平路好走。攻略把它排进主线，时间留得最足。","notice":"双桥清音，平路好走。这个点位上午光线最好。","durationMinutes":120,"addr":"峨眉山低山区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"钵钵鸡（人均35元）","description":"乐山 · 峨眉山乐山大佛的招牌是钵钵鸡，叶婆婆本地人都认这家，点单照攻略不踩雷。","addr":"乐山港"},{"title":"甜皮鸭（人均28元）","description":"乐山 · 峨眉山乐山大佛的招牌是甜皮鸭，赵鸭子本地人都认这家，点单照攻略不踩雷。","addr":"乐山张公桥"},{"title":"豆腐脑（人均12元）","description":"乐山 · 峨眉山乐山大佛的招牌是豆腐脑，峨眉豆腐脑本地人都认这家，点单照攻略不踩雷。","addr":"峨眉市区"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":22275,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","相机或运动相机","轻便雨衣或折叠伞","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
