INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武功山精华联游二日','province','萍乡 · 武功山','mountain','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',46100,25300,2,'金顶 / 发云界 / 玻璃栈道 —— 一张票打包武功山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「武功山」两日慢旅行——山岳。武功山泉水豆腐宴别错过。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 萍乡"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴萍乡","description":"集合出发，大巴直达武功山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"金顶","description":"抵达后首游金顶，日出云海核心位，山顶比山下冷10度。","addr":"武功山风景区金顶","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐萍乡小炒肉（人均42元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"发云界","description":"早起人少，发云界精华时段，高山草甸连绵，徒步精华段。","addr":"武功山发云界段","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐艾米古，人均10元，补充体力。","addr":"金顶驿站","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"玻璃栈道","description":"午后游览玻璃栈道，栈道限流，旺季排30分钟。","addr":"武功山吊马桩","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武功山最有代表性的看点，日出云海核心位，山顶比山下冷10度。攻略把它排进主线，时间留得最足。","notice":"日出云海核心位，山顶比山下冷10度。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"武功山风景区金顶"},{"spotId":"S2","name":"发云界","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"发云界是武功山最有代表性的看点，高山草甸连绵，徒步精华段。攻略把它排进主线，时间留得最足。","notice":"高山草甸连绵，徒步精华段。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"武功山发云界段"},{"spotId":"S3","name":"玻璃栈道","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"玻璃栈道是武功山最有代表性的看点，栈道限流，旺季排30分钟。攻略把它排进主线，时间留得最足。","notice":"栈道限流，旺季排30分钟。这个点位上午光线最好。","durationMinutes":60,"addr":"武功山吊马桩"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"萍乡小炒肉（人均42元）","description":"萍乡 · 武功山的招牌是萍乡小炒肉，山脚菜馆本地人都认这家，点单照攻略不踩雷。","addr":"武功山游客中心旁"},{"title":"艾米古（人均10元）","description":"萍乡 · 武功山的招牌是艾米古，山上补给点本地人都认这家，点单照攻略不踩雷。","addr":"金顶驿站"},{"title":"紫红米粉（人均15元）","description":"萍乡 · 武功山的招牌是紫红米粉，萍乡米粉店本地人都认这家，点单照攻略不踩雷。","addr":"武功山镇主街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":20745,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","墨镜与拍照道具","少量零食补给","防晒霜与遮阳帽","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图"],"faqs":[["几月份去 萍乡 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'慢一点，风景才来得及认识你。','on');
