INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('阆中古城经典二日','province','南充 · 阆中古城','ancient_town','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',39000,21400,1,'阆中古城 / 华光楼 / 锦屏山 —— 一张票打包阆中古城精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「阆中古城」两日慢旅行——古镇。保宁醋是四大名醋之一。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 南充"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南充","description":"集合出发，大巴直达阆中古城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"阆中古城","description":"抵达后首游阆中古城，四大古城之一，张飞庙贡院联票。","addr":"南充市阆中市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐张飞牛肉（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"华光楼","description":"早起人少，华光楼精华时段，登楼看嘉陵江三面环抱。","addr":"古城上华街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐保宁醋，人均20元，补充体力。","addr":"古城内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"锦屏山","description":"午后游览锦屏山，观古城全景最佳位。","addr":"古城对岸","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"阆中古城","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"阆中古城是阆中古城最有代表性的看点，四大古城之一，张飞庙贡院联票。攻略把它排进主线，时间留得最足。","notice":"四大古城之一，张飞庙贡院联票。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"南充市阆中市"},{"spotId":"S2","name":"华光楼","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"华光楼是阆中古城最有代表性的看点，登楼看嘉陵江三面环抱。攻略把它排进主线，时间留得最足。","notice":"登楼看嘉陵江三面环抱。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"古城上华街"},{"spotId":"S3","name":"锦屏山","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"锦屏山是阆中古城最有代表性的看点，观古城全景最佳位。攻略把它排进主线，时间留得最足。","notice":"观古城全景最佳位。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"古城对岸"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"张飞牛肉（人均45元）","description":"南充 · 阆中古城的招牌是张飞牛肉，张飞牛肉旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"古城北街"},{"title":"保宁醋（人均20元）","description":"南充 · 阆中古城的招牌是保宁醋，醋文化博览馆本地人都认这家，点单照攻略不踩雷。","addr":"古城内"},{"title":"油香（人均8元）","description":"南充 · 阆中古城的招牌是油香，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"下沙河街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":17550,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","墨镜与拍照道具","少量零食补给","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 南充 的交通方便吗？","推荐先到 南充，再打车或景区直通车前往核心景区；自驾导航直接搜阆中古城即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
