INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('洪崖洞夜景经典二日','province','渝中 · 洪崖洞夜景','food','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',45500,25000,3,'洪崖洞 / 长江索道 / 山城步道 —— 一张票打包洪崖洞夜景精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「洪崖洞夜景」两日慢旅行——美食。重庆火锅底料真空包装。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"重庆 · 渝中"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴渝中","description":"集合出发，大巴直达洪崖洞夜景，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"洪崖洞","description":"抵达后首游洪崖洞，千与千寻同款夜景，对岸拍全景。","addr":"渝中区嘉陵江畔","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐重庆火锅（人均98元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"长江索道","description":"早起人少，长江索道精华时段，空中横渡长江，排队1小时。","addr":"渝中区新华路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐重庆小面，人均15元，补充体力。","addr":"民生路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"山城步道","description":"午后游览山城步道，第三步道悬空栈道看老重庆。","addr":"渝中区中兴路","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"洪崖洞","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"洪崖洞是洪崖洞夜景最有代表性的看点，千与千寻同款夜景，对岸拍全景。攻略把它排进主线，时间留得最足。","notice":"千与千寻同款夜景，对岸拍全景。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"渝中区嘉陵江畔"},{"spotId":"S2","name":"长江索道","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"长江索道是洪崖洞夜景最有代表性的看点，空中横渡长江，排队1小时。攻略把它排进主线，时间留得最足。","notice":"空中横渡长江，排队1小时。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"渝中区新华路"},{"spotId":"S3","name":"山城步道","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"山城步道是洪崖洞夜景最有代表性的看点，第三步道悬空栈道看老重庆。攻略把它排进主线，时间留得最足。","notice":"第三步道悬空栈道看老重庆。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"渝中区中兴路"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"重庆火锅（人均98元）","description":"渝中 · 洪崖洞夜景的招牌是重庆火锅，佩姐老火锅本地人都认这家，点单照攻略不踩雷。","addr":"解放碑"},{"title":"重庆小面（人均15元）","description":"渝中 · 洪崖洞夜景的招牌是重庆小面，花市豌杂面本地人都认这家，点单照攻略不踩雷。","addr":"民生路"},{"title":"酸辣粉（人均12元）","description":"渝中 · 洪崖洞夜景的招牌是酸辣粉，好又来酸辣粉本地人都认这家，点单照攻略不踩雷。","addr":"八一路"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":20475,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["到达 渝中 的交通方便吗？","推荐先到 渝中，再打车或景区直通车前往核心景区；自驾导航直接搜洪崖洞夜景即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 渝中，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('赛里木湖山水二日','province','伊犁 · 赛里木湖','water','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',51000,28000,2,'赛里木湖 / 果子沟大桥 / 霍尔果斯口岸 —— 一张票打包赛里木湖精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「赛里木湖」两日慢旅行——水景。伊犁薰衣草精油真香。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"新疆 · 伊犁"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴伊犁","description":"集合出发，大巴直达赛里木湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"赛里木湖","description":"抵达后首游赛里木湖，大西洋最后一滴眼泪，环湖骑行。","addr":"博乐市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐高白鲑（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"果子沟大桥","description":"早起人少，果子沟大桥精华时段，空中巨龙，观景台打卡。","addr":"霍城县","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐烤包子，人均10元，补充体力。","addr":"果子沟","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"霍尔果斯口岸","description":"午后游览霍尔果斯口岸，中哈边境免税购物。","addr":"霍尔果斯市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"赛里木湖","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"赛里木湖是赛里木湖最有代表性的看点，大西洋最后一滴眼泪，环湖骑行。攻略把它排进主线，时间留得最足。","notice":"大西洋最后一滴眼泪，环湖骑行。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"博乐市"},{"spotId":"S2","name":"果子沟大桥","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"果子沟大桥是赛里木湖最有代表性的看点，空中巨龙，观景台打卡。攻略把它排进主线，时间留得最足。","notice":"空中巨龙，观景台打卡。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"霍城县"},{"spotId":"S3","name":"霍尔果斯口岸","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"霍尔果斯口岸是赛里木湖最有代表性的看点，中哈边境免税购物。攻略把它排进主线，时间留得最足。","notice":"中哈边境免税购物。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"霍尔果斯市"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"高白鲑（人均88元）","description":"伊犁 · 赛里木湖的招牌是高白鲑，湖畔渔家本地人都认这家，点单照攻略不踩雷。","addr":"赛里木湖"},{"title":"烤包子（人均10元）","description":"伊犁 · 赛里木湖的招牌是烤包子，维族馕坑本地人都认这家，点单照攻略不踩雷。","addr":"果子沟"},{"title":"马奶酒（人均25元）","description":"伊犁 · 赛里木湖的招牌是马奶酒，牧民家本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":22950,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["保温水杯与少量现金","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","相机或运动相机","墨镜与拍照道具","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["当地有什么必吃？","到了 伊犁，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 伊犁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('长白山人文二日','province','延边 · 长白山','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',50300,27600,2,'天池北坡 / 长白瀑布 / 绿渊潭 —— 一张票打包长白山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「长白山」两日慢旅行——山岳。长白山林下参滋补。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"吉林 · 延边"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴延边","description":"集合出发，大巴直达长白山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"天池北坡","description":"抵达后首游天池北坡，长白山主峰天池，天气好才能见。","addr":"延边州安图县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐朝鲜冷面（人均22元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"长白瀑布","description":"早起人少，长白瀑布精华时段，68米瀑布与温泉煮蛋。","addr":"北坡景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐石锅拌饭，人均28元，补充体力。","addr":"延吉市","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"绿渊潭","description":"午后游览绿渊潭，碧绿水潭与飞瀑。","addr":"北坡","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"天池北坡","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"天池北坡是长白山最有代表性的看点，长白山主峰天池，天气好才能见。攻略把它排进主线，时间留得最足。","notice":"长白山主峰天池，天气好才能见。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"延边州安图县"},{"spotId":"S2","name":"长白瀑布","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"长白瀑布是长白山最有代表性的看点，68米瀑布与温泉煮蛋。攻略把它排进主线，时间留得最足。","notice":"68米瀑布与温泉煮蛋。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"北坡景区"},{"spotId":"S3","name":"绿渊潭","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"绿渊潭是长白山最有代表性的看点，碧绿水潭与飞瀑。攻略把它排进主线，时间留得最足。","notice":"碧绿水潭与飞瀑。这个点位上午光线最好。","durationMinutes":60,"addr":"北坡"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"朝鲜冷面（人均22元）","description":"延边 · 长白山的招牌是朝鲜冷面，服务大楼冷面本地人都认这家，点单照攻略不踩雷。","addr":"二道白河镇"},{"title":"石锅拌饭（人均28元）","description":"延边 · 长白山的招牌是石锅拌饭，金达莱餐厅本地人都认这家，点单照攻略不踩雷。","addr":"延吉市"},{"title":"温泉煮蛋（人均10元）","description":"延边 · 长白山的招牌是温泉煮蛋，瀑布温泉口本地人都认这家，点单照攻略不踩雷。","addr":"北坡"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":22635,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","墨镜与拍照道具","常用药品（肠胃药/创可贴）","少量零食补给","保温水杯与少量现金","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意"],"faqs":[["到达 延边 的交通方便吗？","推荐先到 延边，再打车或景区直通车前往核心景区；自驾导航直接搜长白山即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('井冈山休闲二日','province','吉安 · 井冈山','red','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',42000,23100,7,'黄洋界 / 茨坪革命旧址群 / 龙潭 —— 一张票打包井冈山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「井冈山」两日慢旅行——人文。井冈山竹制工艺品轻便好带。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 吉安"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴吉安","description":"集合出发，大巴直达井冈山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"黄洋界","description":"抵达后首游黄洋界，保卫战旧址，云海出现率高。","addr":"井冈山市黄洋界景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红米饭南瓜汤（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"茨坪革命旧址群","description":"早起人少，茨坪革命旧址群精华时段，旧址集中，步行串游。","addr":"井冈山市茨坪镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐井冈烟笋，人均38元，补充体力。","addr":"黄洋界山下餐馆","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"龙潭","description":"午后游览龙潭，五潭十八瀑，索道省力。","addr":"井冈山龙潭景区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"黄洋界","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"黄洋界是井冈山最有代表性的看点，保卫战旧址，云海出现率高。攻略把它排进主线，时间留得最足。","notice":"保卫战旧址，云海出现率高。这个点位上午光线最好。","durationMinutes":120,"addr":"井冈山市黄洋界景区"},{"spotId":"S2","name":"茨坪革命旧址群","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"茨坪革命旧址群是井冈山最有代表性的看点，旧址集中，步行串游。攻略把它排进主线，时间留得最足。","notice":"旧址集中，步行串游。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"井冈山市茨坪镇"},{"spotId":"S3","name":"龙潭","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"龙潭是井冈山最有代表性的看点，五潭十八瀑，索道省力。攻略把它排进主线，时间留得最足。","notice":"五潭十八瀑，索道省力。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"井冈山龙潭景区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红米饭南瓜汤（人均45元）","description":"吉安 · 井冈山的招牌是红米饭南瓜汤，老乡家常菜本地人都认这家，点单照攻略不踩雷。","addr":"茨坪天街"},{"title":"井冈烟笋（人均38元）","description":"吉安 · 井冈山的招牌是井冈烟笋，山上饭庄本地人都认这家，点单照攻略不踩雷。","addr":"黄洋界山下餐馆"},{"title":"石鸡炖汤（人均88元）","description":"吉安 · 井冈山的招牌是石鸡炖汤，龙潭农庄本地人都认这家，点单照攻略不踩雷。","addr":"龙潭景区入口"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18900,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","保温水杯与少量现金","常用药品（肠胃药/创可贴）","少量零食补给","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","墨镜与拍照道具"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 吉安 的交通方便吗？","推荐先到 吉安，再打车或景区直通车前往核心景区；自驾导航直接搜井冈山即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大觉山精华联游二日','province','抚州 · 大觉山','adventure','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',46700,25600,9,'大觉山漂流 / 大觉岩寺 / 古镇影视城 —— 一张票打包大觉山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「大觉山」两日慢旅行——探险地。资溪面包是当地人的骄傲。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 抚州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴抚州","description":"集合出发，大巴直达大觉山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"大觉山漂流","description":"抵达后首游大觉山漂流，华东第一漂，全程3.5公里带好换洗衣。","addr":"资溪县大觉山景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐资溪面包（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大觉岩寺","description":"早起人少，大觉岩寺精华时段，悬崖上的古寺，索道直达。","addr":"大觉山主峰","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐笋干烧肉，人均48元，补充体力。","addr":"大觉山游客中心","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"古镇影视城","description":"午后游览古镇影视城，仿宋古镇，拍照出片。","addr":"大觉山脚下","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"大觉山漂流","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"大觉山漂流是大觉山最有代表性的看点，华东第一漂，全程3.5公里带好换洗衣。攻略把它排进主线，时间留得最足。","notice":"华东第一漂，全程3.5公里带好换洗衣。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"资溪县大觉山景区"},{"spotId":"S2","name":"大觉岩寺","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大觉岩寺是大觉山最有代表性的看点，悬崖上的古寺，索道直达。攻略把它排进主线，时间留得最足。","notice":"悬崖上的古寺，索道直达。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"大觉山主峰"},{"spotId":"S3","name":"古镇影视城","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"古镇影视城是大觉山最有代表性的看点，仿宋古镇，拍照出片。攻略把它排进主线，时间留得最足。","notice":"仿宋古镇，拍照出片。这个点位上午光线最好。","durationMinutes":90,"addr":"大觉山脚下"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"资溪面包（人均15元）","description":"抚州 · 大觉山的招牌是资溪面包，面包之乡旗舰店本地人都认这家，点单照攻略不踩雷。","addr":"资溪县城"},{"title":"笋干烧肉（人均48元）","description":"抚州 · 大觉山的招牌是笋干烧肉，山脚农家本地人都认这家，点单照攻略不踩雷。","addr":"大觉山游客中心"},{"title":"发酵豆腐（人均18元）","description":"抚州 · 大觉山的招牌是发酵豆腐，古镇豆坊本地人都认这家，点单照攻略不踩雷。","addr":"影视城内街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":21015,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","防晒霜与遮阳帽","少量零食补给","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 抚州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["到达 抚州 的交通方便吗？","推荐先到 抚州，再打车或景区直通车前往核心景区；自驾导航直接搜大觉山即可。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
