INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('四姑娘山深度二日','province','阿坝 · 四姑娘山','mountain','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',41000,22500,2,'双桥沟 / 长坪沟 / 猫鼻梁 —— 一张票打包四姑娘山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「四姑娘山」两日慢旅行——山岳。四姑娘山沙棘汁酸爽提神。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达四姑娘山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"双桥沟","description":"抵达后首游双桥沟，坐观光车看雪山峡谷，最省力。","addr":"四姑娘山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏式火锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"长坪沟","description":"早起人少，长坪沟精华时段，木栈道进山，幺妹峰侧面。","addr":"四姑娘山镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牦牛肉干，人均45元，补充体力。","addr":"镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"猫鼻梁","description":"午后游览猫鼻梁，四峰全景最佳机位。","addr":"去四姑娘山路途","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"双桥沟","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"双桥沟是四姑娘山最有代表性的看点，坐观光车看雪山峡谷，最省力。攻略把它排进主线，时间留得最足。","notice":"坐观光车看雪山峡谷，最省力。这个点位上午光线最好。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S2","name":"长坪沟","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"长坪沟是四姑娘山最有代表性的看点，木栈道进山，幺妹峰侧面。攻略把它排进主线，时间留得最足。","notice":"木栈道进山，幺妹峰侧面。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S3","name":"猫鼻梁","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"猫鼻梁是四姑娘山最有代表性的看点，四峰全景最佳机位。攻略把它排进主线，时间留得最足。","notice":"四峰全景最佳机位。拍照记得留神脚下台阶。","durationMinutes":30,"addr":"去四姑娘山路途"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏式火锅（人均78元）","description":"阿坝 · 四姑娘山的招牌是藏式火锅，日隆镇餐馆本地人都认这家，点单照攻略不踩雷。","addr":"四姑娘山镇"},{"title":"牦牛肉干（人均45元）","description":"阿坝 · 四姑娘山的招牌是牦牛肉干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"镇主街"},{"title":"酥油茶（人均15元）","description":"阿坝 · 四姑娘山的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"长坪沟口"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18450,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["相机或运动相机","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","少量零食补给","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","保温水杯与少量现金"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["到达 阿坝 的交通方便吗？","推荐先到 阿坝，再打车或景区直通车前往核心景区；自驾导航直接搜四姑娘山即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 阿坝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'这一次，把心跳交给山野。','on');
