INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('少林寺休闲二日','province','登封 · 少林寺','adventure','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',39700,21800,9,'少林寺常住院 / 三皇寨 / 嵩阳书院 —— 一张票打包少林寺精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「少林寺」两日慢旅行——探险地。少林寺佛珠开光要理性。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 登封"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴登封","description":"集合出发，大巴直达少林寺，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"少林寺常住院","description":"抵达后首游少林寺常住院，塔林与武术表演，达摩面壁洞。","addr":"登封市嵩山","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐少林素斋（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"三皇寨","description":"早起人少，三皇寨精华时段，悬空栈道看书册崖。","addr":"嵩山少室山","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐登封焖子，人均28元，补充体力。","addr":"登封市区","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"嵩阳书院","description":"午后游览嵩阳书院，四大书院之一。","addr":"登封市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"少林寺常住院","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"少林寺常住院是少林寺最有代表性的看点，塔林与武术表演，达摩面壁洞。攻略把它排进主线，时间留得最足。","notice":"塔林与武术表演，达摩面壁洞。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"登封市嵩山"},{"spotId":"S2","name":"三皇寨","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"三皇寨是少林寺最有代表性的看点，悬空栈道看书册崖。攻略把它排进主线，时间留得最足。","notice":"悬空栈道看书册崖。这个点位上午光线最好。","durationMinutes":240,"addr":"嵩山少室山"},{"spotId":"S3","name":"嵩阳书院","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"嵩阳书院是少林寺最有代表性的看点，四大书院之一。攻略把它排进主线，时间留得最足。","notice":"四大书院之一。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"登封市"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"少林素斋（人均48元）","description":"登封 · 少林寺的招牌是少林素斋，寺内素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"少林寺内"},{"title":"登封焖子（人均28元）","description":"登封 · 少林寺的招牌是登封焖子，老字号本地人都认这家，点单照攻略不踩雷。","addr":"登封市区"},{"title":"焦盖烧饼（人均8元）","description":"登封 · 少林寺的招牌是焦盖烧饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"嵩阳书院旁"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":17865,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","防晒霜与遮阳帽","墨镜与拍照道具","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","相机或运动相机"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云冈石窟精华联游二日','province','大同 · 云冈石窟','red','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',41700,22900,7,'云冈石窟 / 大同古城墙 / 悬空寺 —— 一张票打包云冈石窟精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「云冈石窟」两日慢旅行——人文。大同煤雕工艺独特。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 大同"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴大同","description":"集合出发，大巴直达云冈石窟，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"云冈石窟","description":"抵达后首游云冈石窟，昙曜五窟露天大佛，北魏气象。","addr":"大同市云冈区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐刀削面（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大同古城墙","description":"早起人少，大同古城墙精华时段，夜景灯光，骑行城墙。","addr":"平城区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐羊杂粉，人均18元，补充体力。","addr":"鼓楼东街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"悬空寺","description":"午后游览悬空寺，峭壁上的千年古寺。","addr":"浑源县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"云冈石窟","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"云冈石窟是云冈石窟最有代表性的看点，昙曜五窟露天大佛，北魏气象。攻略把它排进主线，时间留得最足。","notice":"昙曜五窟露天大佛，北魏气象。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"大同市云冈区"},{"spotId":"S2","name":"大同古城墙","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"大同古城墙是云冈石窟最有代表性的看点，夜景灯光，骑行城墙。攻略把它排进主线，时间留得最足。","notice":"夜景灯光，骑行城墙。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"平城区"},{"spotId":"S3","name":"悬空寺","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"悬空寺是云冈石窟最有代表性的看点，峭壁上的千年古寺。攻略把它排进主线，时间留得最足。","notice":"峭壁上的千年古寺。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"浑源县"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"刀削面（人均15元）","description":"大同 · 云冈石窟的招牌是刀削面，东方削面本地人都认这家，点单照攻略不踩雷。","addr":"大同市区"},{"title":"羊杂粉（人均18元）","description":"大同 · 云冈石窟的招牌是羊杂粉，老字号羊杂本地人都认这家，点单照攻略不踩雷。","addr":"鼓楼东街"},{"title":"黄糕（人均10元）","description":"大同 · 云冈石窟的招牌是黄糕，黍面糕铺本地人都认这家，点单照攻略不踩雷。","addr":"浑源县"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18765,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","墨镜与拍照道具","保温水杯与少量现金","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 大同 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 大同，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'慢一点，风景才来得及认识你。','on');
