INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大熊猫基地都江堰精华联游二日','province','成都 · 大熊猫基地都江堰','food','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',40300,22100,3,'大熊猫繁育研究基地 / 都江堰 / 南桥夜啤酒 —— 一张票打包大熊猫基地都江堰精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「大熊猫基地都江堰」两日慢旅行——美食。郫县豆瓣是川菜之魂。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 成都"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴成都","description":"集合出发，大巴直达大熊猫基地都江堰，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"大熊猫繁育研究基地","description":"抵达后首游大熊猫繁育研究基地，早8点开园直奔月亮产房，熊猫最活跃。","addr":"成华区外北熊猫大道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐火锅（人均110元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"都江堰","description":"早起人少，都江堰精华时段，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。","addr":"都江堰市公园路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐串串香，人均65元，补充体力。","addr":"玉林路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南桥夜啤酒","description":"午后游览南桥夜啤酒，岷江水上的夜风与美食。","addr":"都江堰市南桥","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"大熊猫繁育研究基地","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大熊猫繁育研究基地是大熊猫基地都江堰最有代表性的看点，早8点开园直奔月亮产房，熊猫最活跃。攻略把它排进主线，时间留得最足。","notice":"早8点开园直奔月亮产房，熊猫最活跃。这个点位上午光线最好。","durationMinutes":240,"addr":"成华区外北熊猫大道"},{"spotId":"S2","name":"都江堰","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"都江堰是大熊猫基地都江堰最有代表性的看点，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。攻略把它排进主线，时间留得最足。","notice":"鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。这个点位上午光线最好。","durationMinutes":180,"addr":"都江堰市公园路"},{"spotId":"S3","name":"南桥夜啤酒","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"南桥夜啤酒是大熊猫基地都江堰最有代表性的看点，岷江水上的夜风与美食。攻略把它排进主线，时间留得最足。","notice":"岷江水上的夜风与美食。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"都江堰市南桥"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"火锅（人均110元）","description":"成都 · 大熊猫基地都江堰的招牌是火锅，蜀大侠本地人都认这家，点单照攻略不踩雷。","addr":"建设路"},{"title":"串串香（人均65元）","description":"成都 · 大熊猫基地都江堰的招牌是串串香，马路边边本地人都认这家，点单照攻略不踩雷。","addr":"玉林路"},{"title":"钟水饺（人均15元）","description":"成都 · 大熊猫基地都江堰的招牌是钟水饺，老字号小吃本地人都认这家，点单照攻略不踩雷。","addr":"人民公园旁"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18135,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","墨镜与拍照道具","保温水杯与少量现金","身份证件与手机充电宝","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["几月份去 成都 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 成都，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
