INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('霞浦滩涂深度二日','province','宁德 · 霞浦滩涂','photography','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',40500,22200,12,'北岐滩涂 / 杨家溪 / 东壁日落 —— 一张票打包霞浦滩涂精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「霞浦滩涂」两日慢旅行——摄影胜地。霞浦紫菜海带全国第一。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 宁德"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴宁德","description":"集合出发，大巴直达霞浦滩涂，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"北岐滩涂","description":"抵达后首游北岐滩涂，日出紫菜架光影，摄影圣地。","addr":"霞浦县松港街道","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐霞浦剑蛏（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"杨家溪","description":"早起人少，杨家溪精华时段，千年枫榕树群，牛群穿雾。","addr":"霞浦县牙城镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐海带排骨汤，人均38元，补充体力。","addr":"北岐村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"东壁日落","description":"午后游览东壁日落，落日渔船归航机位。","addr":"霞浦县三沙镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"北岐滩涂","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"北岐滩涂是霞浦滩涂最有代表性的看点，日出紫菜架光影，摄影圣地。攻略把它排进主线，时间留得最足。","notice":"日出紫菜架光影，摄影圣地。这个点位上午光线最好。","durationMinutes":120,"addr":"霞浦县松港街道"},{"spotId":"S2","name":"杨家溪","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"杨家溪是霞浦滩涂最有代表性的看点，千年枫榕树群，牛群穿雾。攻略把它排进主线，时间留得最足。","notice":"千年枫榕树群，牛群穿雾。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"霞浦县牙城镇"},{"spotId":"S3","name":"东壁日落","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"东壁日落是霞浦滩涂最有代表性的看点，落日渔船归航机位。攻略把它排进主线，时间留得最足。","notice":"落日渔船归航机位。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"霞浦县三沙镇"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"霞浦剑蛏（人均68元）","description":"宁德 · 霞浦滩涂的招牌是霞浦剑蛏，海鲜大排档本地人都认这家，点单照攻略不踩雷。","addr":"三沙镇"},{"title":"海带排骨汤（人均38元）","description":"宁德 · 霞浦滩涂的招牌是海带排骨汤，渔家菜本地人都认这家，点单照攻略不踩雷。","addr":"北岐村"},{"title":"糊汤（人均10元）","description":"宁德 · 霞浦滩涂的招牌是糊汤，街头早点本地人都认这家，点单照攻略不踩雷。","addr":"霞浦县城"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18225,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","少量零食补给","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","身份证件与手机充电宝","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 宁德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'慢一点，风景才来得及认识你。','on');
