INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('老君山人文二日','province','栾川 · 老君山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',45600,25000,2,'金顶道观群 / 十里画屏 / 追梦谷 —— 一张票打包老君山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「老君山」两日慢旅行——山岳。老君山高山茶清冽。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 栾川"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴栾川","description":"集合出发，大巴直达老君山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"金顶道观群","description":"抵达后首游金顶道观群，云海雪景封神，远赴人间惊鸿宴。","addr":"洛阳市栾川县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐栾川豆腐（人均28元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"十里画屏","description":"早起人少，十里画屏精华时段，滑道下山，省膝盖。","addr":"老君山石林","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐蝌蚪面，人均18元，补充体力。","addr":"鸡冠洞乡","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"追梦谷","description":"午后游览追梦谷，溪瀑竹林轻松线。","addr":"老君山脚下","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"金顶道观群","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"金顶道观群是老君山最有代表性的看点，云海雪景封神，远赴人间惊鸿宴。攻略把它排进主线，时间留得最足。","notice":"云海雪景封神，远赴人间惊鸿宴。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"洛阳市栾川县"},{"spotId":"S2","name":"十里画屏","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"十里画屏是老君山最有代表性的看点，滑道下山，省膝盖。攻略把它排进主线，时间留得最足。","notice":"滑道下山，省膝盖。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"老君山石林"},{"spotId":"S3","name":"追梦谷","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"追梦谷是老君山最有代表性的看点，溪瀑竹林轻松线。攻略把它排进主线，时间留得最足。","notice":"溪瀑竹林轻松线。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"老君山脚下"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"栾川豆腐（人均28元）","description":"栾川 · 老君山的招牌是栾川豆腐，山城豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"栾川县城"},{"title":"蝌蚪面（人均18元）","description":"栾川 · 老君山的招牌是蝌蚪面，老君山农家本地人都认这家，点单照攻略不踩雷。","addr":"鸡冠洞乡"},{"title":"玉米糁汤（人均10元）","description":"栾川 · 老君山的招牌是玉米糁汤，农家早餐本地人都认这家，点单照攻略不踩雷。","addr":"景区民宿"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":20520,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","少量零食补给","身份证件与手机充电宝","相机或运动相机","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 栾川 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
