INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七彩丹霞山水人文二日','province','张掖 · 七彩丹霞','photography','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',48700,26700,12,'七彩丹霞 / 平山湖大峡谷 / 马蹄寺 —— 一张票打包七彩丹霞精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「七彩丹霞」两日慢旅行——摄影胜地。张掖圆梨啤特有风味。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 张掖"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴张掖","description":"集合出发，大巴直达七彩丹霞，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"七彩丹霞","description":"抵达后首游七彩丹霞，上帝的调色盘，4号观景台日落。","addr":"张掖市临泽县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐搓鱼面（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"平山湖大峡谷","description":"早起人少，平山湖大峡谷精华时段，张掖版科罗拉多，越野车深入。","addr":"甘州区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐炒炮，人均18元，补充体力。","addr":"大佛寺旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"马蹄寺","description":"午后游览马蹄寺，石窟与裕固族风情。","addr":"肃南县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"七彩丹霞","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"七彩丹霞是七彩丹霞最有代表性的看点，上帝的调色盘，4号观景台日落。攻略把它排进主线，时间留得最足。","notice":"上帝的调色盘，4号观景台日落。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"张掖市临泽县"},{"spotId":"S2","name":"平山湖大峡谷","coverUrl":"https://images.unsplash.co