INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雅鲁藏布大峡谷轻徒步二日','province','林芝 · 雅鲁藏布大峡谷','plateau','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',40000,22000,2,'南迦巴瓦观景台 / 雅鲁藏布大峡谷 / 鲁朗林海 —— 一张票打包雅鲁藏布大峡谷精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「雅鲁藏布大峡谷」两日慢旅行——高原。林芝松茸6-8月最鲜。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 林芝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴林芝","description":"集合出发，大巴直达雅鲁藏布大峡谷，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"南迦巴瓦观景台","description":"抵达后首游南迦巴瓦观景台，羞女峰十人九不遇，直白村最近。","addr":"米林县派镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐鲁朗石锅鸡（人均128元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"雅鲁藏布大峡谷","description":"早起人少，雅鲁藏布大峡谷精华时段，世界最深深峡，换乘游览。","addr":"林芝市","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐藏香猪，人均58元，补充体力。","addr":"派镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"鲁朗林海","description":"午后游览鲁朗林海，东方瑞士，石锅鸡之乡。","addr":"鲁朗镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"南迦巴瓦观景台","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"南迦巴瓦观景台是雅鲁藏布大峡谷最有代表性的看点，羞女峰十人九不遇，直白村最近。攻略把它排进主线，时间留得最足。","notice":"羞女峰十人九不遇，直白村最近。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"米林县派镇"},{"spotId":"S2","name":"雅鲁藏布大峡谷","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"雅鲁藏布大峡谷是雅鲁藏布大峡谷最有代表性的看点，世界最深深峡，换乘游览。攻略把它排进主线，时间留得最足。","notice":"世界最深深峡，换乘游览。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"林芝市"},{"spotId":"S3","name":"鲁朗林海","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"鲁朗林海是雅鲁藏布大峡谷最有代表性的看点，东方瑞士，石锅鸡之乡。攻略把它排进主线，时间留得最足。","notice":"东方瑞士，石锅鸡之乡。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"鲁朗镇"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"鲁朗石锅鸡（人均128元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是鲁朗石锅鸡，石锅鸡总店本地人都认这家，点单照攻略不踩雷。","addr":"鲁朗镇"},{"title":"藏香猪（人均58元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是藏香猪，工布藏餐本地人都认这家，点单照攻略不踩雷。","addr":"派镇"},{"title":"松茸炖藏鸡（人均98元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是松茸炖藏鸡，林芝菌菇宴本地人都认这家，点单照攻略不踩雷。","addr":"林芝市区"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18000,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","身份证件与手机充电宝","轻便雨衣或折叠伞","防晒霜与遮阳帽","相机或运动相机","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 林芝 的交通方便吗？","推荐先到 林芝，再打车或景区直通车前往核心景区；自驾导航直接搜雅鲁藏布大峡谷即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙坡头深度二日','province','中卫 · 沙坡头','adventure','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',46800,25700,9,'沙坡头 / 通湖草原 / 66号公路 —— 一张票打包沙坡头精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「沙坡头」两日慢旅行——探险地。中卫硒砂瓜甜到心里。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"宁夏 · 中卫"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴中卫","description":"集合出发，大巴直达沙坡头，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"沙坡头","description":"抵达后首游沙坡头，黄河飞索与羊皮筏子，沙漠骑骆驼。","addr":"中卫市沙坡头区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐硒砂瓜（人均10元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"通湖草原","description":"早起人少，通湖草原精华时段，沙漠营地篝火晚会。","addr":"阿拉善左旗","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐黄河大鲤鱼，人均58元，补充体力。","addr":"景区旁","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"66号公路","description":"午后游览66号公路，网红沙漠公路打卡。","addr":"中卫市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"沙坡头","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"沙坡头是沙坡头最有代表性的看点，黄河飞索与羊皮筏子，沙漠骑骆驼。攻略把它排进主线，时间留得最足。","notice":"黄河飞索与羊皮筏子，沙漠骑骆驼。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"中卫市沙坡头区"},{"spotId":"S2","name":"通湖草原","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"通湖草原是沙坡头最有代表性的看点，沙漠营地篝火晚会。攻略把它排进主线，时间留得最足。","notice":"沙漠营地篝火晚会。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"阿拉善左旗"},{"spotId":"S3","name":"66号公路","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"66号公路是沙坡头最有代表性的看点，网红沙漠公路打卡。攻略把它排进主线，时间留得最足。","notice":"网红沙漠公路打卡。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"中卫市"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"硒砂瓜（人均10元）","description":"中卫 · 沙坡头的招牌是硒砂瓜，路边瓜摊本地人都认这家，点单照攻略不踩雷。","addr":"沙坡头"},{"title":"黄河大鲤鱼（人均58元）","description":"中卫 · 沙坡头的招牌是黄河大鲤鱼，沙坡头渔村本地人都认这家，点单照攻略不踩雷。","addr":"景区旁"},{"title":"手抓滩羊（人均68元）","description":"中卫 · 沙坡头的招牌是手抓滩羊，夏华火锅本地人都认这家，点单照攻略不踩雷。","addr":"中卫市区"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":21060,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["墨镜与拍照道具","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","相机或运动相机","少量零食补给","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 中卫 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["到达 中卫 的交通方便吗？","推荐先到 中卫，再打车或景区直通车前往核心景区；自驾导航直接搜沙坡头即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滕王阁经典二日','province','南昌 · 滕王阁','art','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',47000,25800,5,'滕王阁 / 万寿宫历史文化街区 / 秋水广场 —— 一张票打包滕王阁精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「滕王阁」两日慢旅行——文艺。南昌瓷板画是独特纪念品。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 南昌"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南昌","description":"集合出发，大巴直达滕王阁，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"滕王阁","description":"抵达后首游滕王阁，落霞与孤鹜齐名的主阁，登顶看赣江。","addr":"南昌市东湖区仿古街58号","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐瓦罐汤（人均18元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"万寿宫历史文化街区","description":"早起人少，万寿宫历史文化街区精华时段，夜市烟火气，白天逛老建筑。","addr":"西湖区中山路","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐拌粉，人均12元，补充体力。","addr":"中山路支巷","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"秋水广场","description":"午后游览秋水广场，亚洲最大音乐喷泉群，晚上两场。","addr":"红谷滩区赣江中大道","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"滕王阁","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"滕王阁是滕王阁最有代表性的看点，落霞与孤鹜齐名的主阁，登顶看赣江。攻略把它排进主线，时间留得最足。","notice":"落霞与孤鹜齐名的主阁，登顶看赣江。这个点位上午光线最好。","durationMinutes":120,"addr":"南昌市东湖区仿古街58号"},{"spotId":"S2","name":"万寿宫历史文化街区","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"万寿宫历史文化街区是滕王阁最有代表性的看点，夜市烟火气，白天逛老建筑。攻略把它排进主线，时间留得最足。","notice":"夜市烟火气，白天逛老建筑。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"西湖区中山路"},{"spotId":"S3","name":"秋水广场","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"秋水广场是滕王阁最有代表性的看点，亚洲最大音乐喷泉群，晚上两场。攻略把它排进主线，时间留得最足。","notice":"亚洲最大音乐喷泉群，晚上两场。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"红谷滩区赣江中大道"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"瓦罐汤（人均18元）","description":"南昌 · 滕王阁的招牌是瓦罐汤，民间瓦罐汤店本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫街区巷口"},{"title":"拌粉（人均12元）","description":"南昌 · 滕王阁的招牌是拌粉，南昌拌粉总店本地人都认这家，点单照攻略不踩雷。","addr":"中山路支巷"},{"title":"白糖糕（人均8元）","description":"南昌 · 滕王阁的招牌是白糖糕，老字号糕点铺本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫内街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":21150,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["防晒霜与遮阳帽","少量零食补给","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","轻便雨衣或折叠伞","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 南昌 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('凤凰古城山水二日','province','湘西 · 凤凰古城','ancient_town','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',40100,22000,1,'沱江跳岩 / 沈从文故居 / 南华山 —— 一张票打包凤凰古城精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「凤凰古城」两日慢旅行——古镇。凤凰银饰认准足银999。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 湘西"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴湘西","description":"集合出发，大巴直达凤凰古城，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"沱江跳岩","description":"抵达后首游沱江跳岩，清晨雾气中的吊脚楼最出片。","addr":"凤凰古城沱江北门","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐血粑鸭（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"沈从文故居","description":"早起人少，沈从文故居精华时段，文学爱好者必打卡，讲解值得请。","addr":"凤凰古城中营街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐苗家酸汤鱼，人均68元，补充体力。","addr":"沱江边吊脚楼","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南华山","description":"午后游览南华山，登高俯瞰全城夜景。","addr":"凤凰城南","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"沱江跳岩","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"沱江跳岩是凤凰古城最有代表性的看点，清晨雾气中的吊脚楼最出片。攻略把它排进主线，时间留得最足。","notice":"清晨雾气中的吊脚楼最出片。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"凤凰古城沱江北门"},{"spotId":"S2","name":"沈从文故居","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"沈从文故居是凤凰古城最有代表性的看点，文学爱好者必打卡，讲解值得请。攻略把它排进主线，时间留得最足。","notice":"文学爱好者必打卡，讲解值得请。这个点位上午光线最好。","durationMinutes":60,"addr":"凤凰古城中营街"},{"spotId":"S3","name":"南华山","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"南华山是凤凰古城最有代表性的看点，登高俯瞰全城夜景。攻略把它排进主线，时间留得最足。","notice":"登高俯瞰全城夜景。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"凤凰城南"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"血粑鸭（人均58元）","description":"湘西 · 凤凰古城的招牌是血粑鸭，凤凰老字号本地人都认这家，点单照攻略不踩雷。","addr":"虹桥东路"},{"title":"苗家酸汤鱼（人均68元）","description":"湘西 · 凤凰古城的招牌是苗家酸汤鱼，古城酸汤鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"沱江边吊脚楼"},{"title":"凤凰姜糖（人均15元）","description":"湘西 · 凤凰古城的招牌是凤凰姜糖，老街姜糖铺本地人都认这家，点单照攻略不踩雷。","addr":"东正街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18045,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","换洗衣物与外套（早晚温差）","墨镜与拍照道具","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","少量零食补给","身份证件与手机充电宝"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 湘西 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
