INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九寨沟休闲二日','province','阿坝 · 九寨沟','water','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',47300,26000,2,'五花海 / 诺日朗瀑布 / 长海 —— 一张票打包九寨沟精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「九寨沟」两日慢旅行——水景。九寨沟牦牛酸奶值得尝。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达九寨沟，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"五花海","description":"抵达后首游五花海，九寨精华，孔雀河道顺光最美。","addr":"九寨沟县漳扎镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐牦牛肉汤锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"诺日朗瀑布","description":"早起人少，诺日朗瀑布精华时段，中国最宽钙华瀑布。","addr":"九寨沟中心站","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐青稞酒，人均30元，补充体力。","addr":"藏寨","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"长海","description":"午后游览长海，最大海子，雪山倒影。","addr":"九寨沟则查洼沟","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"五花海","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"五花海是九寨沟最有代表性的看点，九寨精华，孔雀河道顺光最美。攻略把它排进主线，时间留得最足。","notice":"九寨精华，孔雀河道顺光最美。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"九寨沟县漳扎镇"},{"spotId":"S2","name":"诺日朗瀑布","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"诺日朗瀑布是九寨沟最有代表性的看点，中国最宽钙华瀑布。攻略把它排进主线，时间留得最足。","notice":"中国最宽钙华瀑布。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"九寨沟中心站"},{"spotId":"S3","name":"长海","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"长海是九寨沟最有代表性的看点，最大海子，雪山倒影。攻略把它排进主线，时间留得最足。","notice":"最大海子，雪山倒影。这个点位上午光线最好。","durationMinutes":90,"addr":"九寨沟则查洼沟"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉汤锅（人均78元）","description":"阿坝 · 九寨沟的招牌是牦牛肉汤锅，沟口藏家本地人都认这家，点单照攻略不踩雷。","addr":"漳扎镇"},{"title":"青稞酒（人均30元）","description":"阿坝 · 九寨沟的招牌是青稞酒，藏家体验本地人都认这家，点单照攻略不踩雷。","addr":"藏寨"},{"title":"糌粑（人均20元）","description":"阿坝 · 九寨沟的招牌是糌粑，藏族人家本地人都认这家，点单照攻略不踩雷。","addr":"树正寨"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":21285,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","身份证件与手机充电宝","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","相机或运动相机","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('荔波小七孔精华联游二日','province','黔南 · 荔波小七孔','water','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',40300,22100,2,'小七孔古桥 / 卧龙潭 / 大七孔 —— 一张票打包荔波小七孔精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「荔波小七孔」两日慢旅行——水景。荔波青梅制品酸甜开胃。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔南"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴黔南","description":"集合出发，大巴直达荔波小七孔，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"小七孔古桥","description":"抵达后首游小七孔古桥，68级跌水瀑布起点，绿宝石湖水。","addr":"荔波县小七孔镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐酸汤鱼（人均68元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"卧龙潭","description":"早起人少，卧龙潭精华时段，蓝到不真实的深潭，漂流出片。","addr":"小七孔景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐杨梅汤，人均10元，补充体力。","addr":"小七孔镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大七孔","description":"午后游览大七孔，天生桥鬼斧神工。","addr":"荔波县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"小七孔古桥","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"小七孔古桥是荔波小七孔最有代表性的看点，68级跌水瀑布起点，绿宝石湖水。攻略把它排进主线，时间留得最足。","notice":"68级跌水瀑布起点，绿宝石湖水。这个点位上午光线最好。","durationMinutes":180,"addr":"荔波县小七孔镇"},{"spotId":"S2","name":"卧龙潭","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"卧龙潭是荔波小七孔最有代表性的看点，蓝到不真实的深潭，漂流出片。攻略把它排进主线，时间留得最足。","notice":"蓝到不真实的深潭，漂流出片。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"小七孔景区"},{"spotId":"S3","name":"大七孔","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"大七孔是荔波小七孔最有代表性的看点，天生桥鬼斧神工。攻略把它排进主线，时间留得最足。","notice":"天生桥鬼斧神工。这个点位上午光线最好。","durationMinutes":90,"addr":"荔波县"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均68元）","description":"黔南 · 荔波小七孔的招牌是酸汤鱼，凯里酸汤鱼本地人都认这家，点单照攻略不踩雷。","addr":"荔波县城"},{"title":"杨梅汤（人均10元）","description":"黔南 · 荔波小七孔的招牌是杨梅汤，街边饮品本地人都认这家，点单照攻略不踩雷。","addr":"小七孔镇"},{"title":"糯米排骨（人均42元）","description":"黔南 · 荔波小七孔的招牌是糯米排骨，布依农家本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18135,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["防晒霜与遮阳帽","墨镜与拍照道具","相机或运动相机","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('涠洲岛山水人文二日','province','北海 · 涠洲岛','sea','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',51100,28100,6,'鳄鱼山火山公园 / 五彩滩 / 滴水丹屏 —— 一张票打包涠洲岛精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「涠洲岛」两日慢旅行——海滨。涠洲岛香蕉又软又甜。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 北海"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴北海","description":"集合出发，大巴直达涠洲岛，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"鳄鱼山火山公园","description":"抵达后首游鳄鱼山火山公园，火山地质地貌，灯塔海景。","addr":"涠洲岛南湾","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐海鲜大餐（人均98元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"五彩滩","description":"早起人少，五彩滩精华时段，退潮时火山岩纹理最美。","addr":"涠洲岛东岸","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐香蕉猪，人均58元，补充体力。","addr":"滴水村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"滴水丹屏","description":"午后游览滴水丹屏，日落圣地，海水退潮捡贝壳。","addr":"涠洲岛西侧","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"鳄鱼山火山公园","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"鳄鱼山火山公园是涠洲岛最有代表性的看点，火山地质地貌，灯塔海景。攻略把它排进主线，时间留得最足。","notice":"火山地质地貌，灯塔海景。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"涠洲岛南湾"},{"spotId":"S2","name":"五彩滩","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"五彩滩是涠洲岛最有代表性的看点，退潮时火山岩纹理最美。攻略把它排进主线，时间留得最足。","notice":"退潮时火山岩纹理最美。这个点位上午光线最好。","durationMinutes":90,"addr":"涠洲岛东岸"},{"spotId":"S3","name":"滴水丹屏","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"滴水丹屏是涠洲岛最有代表性的看点，日落圣地，海水退潮捡贝壳。攻略把它排进主线，时间留得最足。","notice":"日落圣地，海水退潮捡贝壳。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"涠洲岛西侧"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜大餐（人均98元）","description":"北海 · 涠洲岛的招牌是海鲜大餐，南湾海鲜市场加工本地人都认这家，点单照攻略不踩雷。","addr":"南湾街"},{"title":"香蕉猪（人均58元）","description":"北海 · 涠洲岛的招牌是香蕉猪，岛民农家本地人都认这家，点单照攻略不踩雷。","addr":"滴水村"},{"title":"椰子冻（人均15元）","description":"北海 · 涠洲岛的招牌是椰子冻，夜市摊本地人都认这家，点单照攻略不踩雷。","addr":"南湾夜市"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":22995,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","墨镜与拍照道具","保温水杯与少量现金","相机或运动相机","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 北海 的交通方便吗？","推荐先到 北海，再打车或景区直通车前往核心景区；自驾导航直接搜涠洲岛即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["几月份去 北海 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
