INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌镇西栅山水人文二日','province','嘉兴 · 乌镇西栅','ancient_town','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',48000,26400,1,'乌镇西栅 / 木心美术馆 / 南浔古镇 —— 一张票打包乌镇西栅精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「乌镇西栅」两日慢旅行——古镇。乌镇蓝印花布制品雅致。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 嘉兴"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴嘉兴","description":"集合出发，大巴直达乌镇西栅，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乌镇西栅","description":"抵达后首游乌镇西栅，夜景封神，染坊与书院。","addr":"桐乡市乌镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐红烧羊肉（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"木心美术馆","description":"早起人少，木心美术馆精华时段，建筑与展览双重享受。","addr":"西栅景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐定胜糕，人均10元，补充体力。","addr":"乌镇南栅","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"南浔古镇","description":"午后游览南浔古镇，人少水乡，百间楼原生。","addr":"湖州南浔区","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乌镇西栅","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"乌镇西栅是乌镇西栅最有代表性的看点，夜景封神，染坊与书院。攻略把它排进主线，时间留得最足。","notice":"夜景封神，染坊与书院。这个点位上午光线最好。","durationMinutes":240,"addr":"桐乡市乌镇"},{"spotId":"S2","name":"木心美术馆","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"木心美术馆是乌镇西栅最有代表性的看点，建筑与展览双重享受。攻略把它排进主线，时间留得最足。","notice":"建筑与展览双重享受。这个点位上午光线最好。","durationMinutes":90,"addr":"西栅景区"},{"spotId":"S3","name":"南浔古镇","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"南浔古镇是乌镇西栅最有代表性的看点，人少水乡，百间楼原生。攻略把它排进主线，时间留得最足。","notice":"人少水乡，百间楼原生。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"湖州南浔区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"红烧羊肉（人均45元）","description":"嘉兴 · 乌镇西栅的招牌是红烧羊肉，书生羊肉面本地人都认这家，点单照攻略不踩雷。","addr":"西栅大街"},{"title":"定胜糕（人均10元）","description":"嘉兴 · 乌镇西栅的招牌是定胜糕，小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"乌镇南栅"},{"title":"白水鱼（人均58元）","description":"嘉兴 · 乌镇西栅的招牌是白水鱼，水乡渔家本地人都认这家，点单照攻略不踩雷。","addr":"南浔百间楼"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":21600,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","墨镜与拍照道具","相机或运动相机","保温水杯与少量现金","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 嘉兴，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
