INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('香格里拉经典二日2','province','迪庆 · 香格里拉','plateau','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',43800,24000,2,'普达措国家公园 / 松赞林寺 / 独克宗古城 —— 一张票打包香格里拉精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「香格里拉」两日慢旅行——高原。牦牛肉干认准风干原味。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 迪庆"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴迪庆","description":"集合出发，大巴直达香格里拉，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"普达措国家公园","description":"抵达后首游普达措国家公园，属都湖栈道环湖，高原慢慢走。","addr":"香格里拉市建塘镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐牦牛肉火锅（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"松赞林寺","description":"早起人少，松赞林寺精华时段，小布达拉宫，顺时针转寺。","addr":"香格里拉市佛屏山前","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐酥油茶，人均20元，补充体力。","addr":"古城内","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"独克宗古城","description":"午后游览独克宗古城，转世界最大转经筒，夜景美。","addr":"香格里拉市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"普达措国家公园","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"普达措国家公园是香格里拉最有代表性的看点，属都湖栈道环湖，高原慢慢走。攻略把它排进主线，时间留得最足。","notice":"属都湖栈道环湖，高原慢慢走。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"香格里拉市建塘镇"},{"spotId":"S2","name":"松赞林寺","coverUrl":"https://images.uns