INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大觉山精华联游二日2','province','抚州 · 大觉山','adventure','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',40500,22200,9,'大觉山漂流 / 大觉岩寺 / 古镇影视城 —— 一张票打包大觉山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「大觉山」两日慢旅行——探险地。资溪面包是当地人的骄傲。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 抚州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴抚州","description":"集合出发，大巴直达大觉山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"大觉山漂流","description":"抵达后首游大觉山漂流，华东第一漂，全程3.5公里带好换洗衣。","addr":"资溪县大觉山景区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐资溪面包（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"大觉岩寺","description":"早起人少，大觉岩寺精华时段，悬崖上的古寺，索道直达。","addr":"大觉山主峰","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐笋干烧肉，人均48元，补充体力。","addr":"大觉山游客中心","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"古镇影视城","description":"午后游览古镇影视城，仿宋古镇，拍照出片。","addr":"大觉山脚下","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"大觉山漂流","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"大觉山漂流是大觉山最有代表性的看点，华东第一漂，全程3.5公里带好换洗衣。攻略把它排进主线，时间留得最足。","notice":"华东第一漂，全程3.5公里带好换洗衣。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"资溪县大觉山景区"},{"spotId":"S2","name":"大觉岩寺","coverUrl":"ht