INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳阳楼洞庭湖山水人文二日2','province','岳阳 · 岳阳楼洞庭湖','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',39500,21700,2,'岳阳楼 / 君山岛 / 圣安寺 —— 一张票打包岳阳楼洞庭湖精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「岳阳楼洞庭湖」两日慢旅行——水景。君山银针是十大名茶之一。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 岳阳"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴岳阳","description":"集合出发，大巴直达岳阳楼洞庭湖，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"岳阳楼","description":"抵达后首游岳阳楼，洞庭天下水岳阳天下楼，背岳阳楼记免票。","addr":"岳阳市岳阳楼区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐洞庭鱼头（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"君山岛","description":"早起人少，君山岛精华时段，湘妃竹与银针茶的故乡。","addr":"洞庭湖君山岛","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐君山银针鸡片，人均68元，补充体力。","addr":"君山岛上","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"圣安寺","description":"午后游览圣安寺，古塔与湖景同框。","addr":"岳阳市南湖畔","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"岳阳楼","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"岳阳楼是岳阳楼洞庭湖最有代表性的看点，洞庭天下水岳阳天下楼，背岳阳楼记免票。攻略把它排进主线，时间留得最足。","notice":"洞庭天下水岳阳天下楼，背岳阳楼记免票。这个点位上午光线最好。","durationMinutes":90,"addr":"岳阳市岳阳楼区"},{"spotId":"S2","name":"君山岛","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"君山岛是岳阳楼洞庭湖最有代表性的看点，湘妃竹与银针茶的故乡。攻略把它排进主线，时间留得最足。","notice":"湘妃竹与银针茶的故乡。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"洞庭湖君山岛"},{"spotId":"S3","name":"圣安寺","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"圣安寺是岳阳楼洞庭湖最有代表性的看点，古塔与湖景同框。攻略把它排进主线，时间留得最足。","notice":"古塔与湖景同框。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"岳阳市南湖畔"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"洞庭鱼头（人均78元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是洞庭鱼头，巴陵全鱼席本地人都认这家，点单照攻略不踩雷。","addr":"岳阳楼景区旁"},{"title":"君山银针鸡片（人均68元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是君山银针鸡片，茶宴馆本地人都认这家，点单照攻略不踩雷。","addr":"君山岛上"},{"title":"岳阳虾饼（人均10元）","description":"岳阳 · 岳阳楼洞庭湖的招牌是岳阳虾饼，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"汴河街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":17775,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","保温水杯与少量现金","相机或运动相机","墨镜与拍照道具","常用药品（肠胃药/创可贴）","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 岳阳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
