INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('四姑娘山深度二日2','province','阿坝 · 四姑娘山','mountain','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',40900,22400,2,'双桥沟 / 长坪沟 / 猫鼻梁 —— 一张票打包四姑娘山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「四姑娘山」两日慢旅行——山岳。四姑娘山沙棘汁酸爽提神。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴阿坝","description":"集合出发，大巴直达四姑娘山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"双桥沟","description":"抵达后首游双桥沟，坐观光车看雪山峡谷，最省力。","addr":"四姑娘山镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐藏式火锅（人均78元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"长坪沟","description":"早起人少，长坪沟精华时段，木栈道进山，幺妹峰侧面。","addr":"四姑娘山镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐牦牛肉干，人均45元，补充体力。","addr":"镇主街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"猫鼻梁","description":"午后游览猫鼻梁，四峰全景最佳机位。","addr":"去四姑娘山路途","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"双桥沟","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"双桥沟是四姑娘山最有代表性的看点，坐观光车看雪山峡谷，最省力。攻略把它排进主线，时间留得最足。","notice":"坐观光车看雪山峡谷，最省力。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S2","name":"长坪沟","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"长坪沟是四姑娘山最有代表性的看点，木栈道进山，幺妹峰侧面。攻略把它排进主线，时间留得最足。","notice":"木栈道进山，幺妹峰侧面。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"四姑娘山镇"},{"spotId":"S3","name":"猫鼻梁","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"猫鼻梁是四姑娘山最有代表性的看点，四峰全景最佳机位。攻略把它排进主线，时间留得最足。","notice":"四峰全景最佳机位。这个点位上午光线最好。","durationMinutes":30,"addr":"去四姑娘山路途"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏式火锅（人均78元）","description":"阿坝 · 四姑娘山的招牌是藏式火锅，日隆镇餐馆本地人都认这家，点单照攻略不踩雷。","addr":"四姑娘山镇"},{"title":"牦牛肉干（人均45元）","description":"阿坝 · 四姑娘山的招牌是牦牛肉干，特产店本地人都认这家，点单照攻略不踩雷。","addr":"镇主街"},{"title":"酥油茶（人均15元）","description":"阿坝 · 四姑娘山的招牌是酥油茶，藏家茶馆本地人都认这家，点单照攻略不踩雷。","addr":"长坪沟口"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18405,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","常用药品（肠胃药/创可贴）","墨镜与拍照道具","防晒霜与遮阳帽","轻便雨衣或折叠伞","相机或运动相机","换洗衣物与外套（早晚温差）","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["到达 阿坝 的交通方便吗？","推荐先到 阿坝，再打车或景区直通车前往核心景区；自驾导航直接搜四姑娘山即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 阿坝 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('乌蒙大草原经典二日2','province','六盘水 · 乌蒙大草原','camp','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',42800,23500,10,'乌蒙大草原 / 野玉海 / 娘娘山 —— 一张票打包乌蒙大草原精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「乌蒙大草原」两日慢旅行——露营地。六盘水刺梨维C之王。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 六盘水"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴六盘水","description":"集合出发，大巴直达乌蒙大草原，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"乌蒙大草原","description":"抵达后首游乌蒙大草原，云上花海佛光，露营星空。","addr":"六盘水市盘州市","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐水城烙锅（人均45元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"野玉海","description":"早起人少，野玉海精华时段，海坪彝族小镇与观光小火车。","addr":"水城区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐羊肉粉，人均15元，补充体力。","addr":"盘州市","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"娘娘山","description":"午后游览娘娘山，高原湿地与温泉。","addr":"盘州市","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"乌蒙大草原","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"乌蒙大草原是乌蒙大草原最有代表性的看点，云上花海佛光，露营星空。攻略把它排进主线，时间留得最足。","notice":"云上花海佛光，露营星空。这个点位上午光线最好。","durationMinutes":180,"addr":"六盘水市盘州市"},{"spotId":"S2","name":"野玉海","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"野玉海是乌蒙大草原最有代表性的看点，海坪彝族小镇与观光小火车。攻略把它排进主线，时间留得最足。","notice":"海坪彝族小镇与观光小火车。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"水城区"},{"spotId":"S3","name":"娘娘山","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"娘娘山是乌蒙大草原最有代表性的看点，高原湿地与温泉。攻略把它排进主线，时间留得最足。","notice":"高原湿地与温泉。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"盘州市"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水城烙锅（人均45元）","description":"六盘水 · 乌蒙大草原的招牌是水城烙锅，烙锅一条街本地人都认这家，点单照攻略不踩雷。","addr":"水城区"},{"title":"羊肉粉（人均15元）","description":"六盘水 · 乌蒙大草原的招牌是羊肉粉，元坤羊肉粉本地人都认这家，点单照攻略不踩雷。","addr":"盘州市"},{"title":"刺梨汁（人均10元）","description":"六盘水 · 乌蒙大草原的招牌是刺梨汁，维C宝饮品本地人都认这家，点单照攻略不踩雷。","addr":"全区通用"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":19260,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","常用药品（肠胃药/创可贴）","少量零食补给","轻便雨衣或折叠伞","身份证件与手机充电宝","防晒霜与遮阳帽","保温水杯与少量现金","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["到达 六盘水 的交通方便吗？","推荐先到 六盘水，再打车或景区直通车前往核心景区；自驾导航直接搜乌蒙大草原即可。"],["当地有什么必吃？","到了 六盘水，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 六盘水 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武夷山山水二日2','province','南平 · 武夷山','mountain','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',45700,25100,2,'九曲溪竹筏 / 天游峰 / 大红袍景区 —— 一张票打包武夷山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「武夷山」两日慢旅行——山岳。正岩大红袍认准九龙窠。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 南平"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴南平","description":"集合出发，大巴直达武夷山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"九曲溪竹筏","description":"抵达后首游九曲溪竹筏，90分钟漂流过九曲十八弯。","addr":"武夷山市星村镇","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐武夷山熏鹅（人均48元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"天游峰","description":"早起人少，天游峰精华时段，闽山第一峰，云窝上看溪湾。","addr":"武夷山风景区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐紫溪粉，人均15元，补充体力。","addr":"三姑街","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"大红袍景区","description":"午后游览大红袍景区，母树大红袍，岩谷花香步道。","addr":"武夷山九龙窠","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"九曲溪竹筏","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"九曲溪竹筏是武夷山最有代表性的看点，90分钟漂流过九曲十八弯。攻略把它排进主线，时间留得最足。","notice":"90分钟漂流过九曲十八弯。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"武夷山市星村镇"},{"spotId":"S2","name":"天游峰","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"天游峰是武夷山最有代表性的看点，闽山第一峰，云窝上看溪湾。攻略把它排进主线，时间留得最足。","notice":"闽山第一峰，云窝上看溪湾。这个点位上午光线最好。","durationMinutes":150,"addr":"武夷山风景区"},{"spotId":"S3","name":"大红袍景区","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"大红袍景区是武夷山最有代表性的看点，母树大红袍，岩谷花香步道。攻略把它排进主线，时间留得最足。","notice":"母树大红袍，岩谷花香步道。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"武夷山九龙窠"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"武夷山熏鹅（人均48元）","description":"南平 · 武夷山的招牌是武夷山熏鹅，岚谷熏鹅店本地人都认这家，点单照攻略不踩雷。","addr":"度假区"},{"title":"紫溪粉（人均15元）","description":"南平 · 武夷山的招牌是紫溪粉，小吃店本地人都认这家，点单照攻略不踩雷。","addr":"三姑街"},{"title":"文公菜（人均58元）","description":"南平 · 武夷山的招牌是文公菜，朱子家宴本地人都认这家，点单照攻略不踩雷。","addr":"武夷宫旁"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":20565,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","相机或运动相机","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 南平 的交通方便吗？","推荐先到 南平，再打车或景区直通车前往核心景区；自驾导航直接搜武夷山即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('莫干山人文二日2','province','湖州 · 莫干山','village','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',41500,22800,1,'莫干山风景区 / 庾村文化市集 / 下渚湖湿地公园 —— 一张票打包莫干山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「莫干山」两日慢旅行——古村落。莫干山黄芽茶清雅。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 湖州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴湖州","description":"集合出发，大巴直达莫干山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"莫干山风景区","description":"抵达后首游莫干山风景区，民国别墅群与竹海，剑池飞瀑。","addr":"湖州市德清县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐笋干烧肉（人均58元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"庾村文化市集","description":"早起人少，庾村文化市集精华时段，文创小铺与骑行路线。","addr":"德清县莫干山镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐竹林土鸡煲，人均88元，补充体力。","addr":"劳岭村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"下渚湖湿地公园","description":"午后游览下渚湖湿地公园，朱鹮栖息地，芦苇迷宫。","addr":"德清县","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"莫干山风景区","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"莫干山风景区是莫干山最有代表性的看点，民国别墅群与竹海，剑池飞瀑。攻略把它排进主线，时间留得最足。","notice":"民国别墅群与竹海，剑池飞瀑。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"湖州市德清县"},{"spotId":"S2","name":"庾村文化市集","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"庾村文化市集是莫干山最有代表性的看点，文创小铺与骑行路线。攻略把它排进主线，时间留得最足。","notice":"文创小铺与骑行路线。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"德清县莫干山镇"},{"spotId":"S3","name":"下渚湖湿地公园","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"下渚湖湿地公园是莫干山最有代表性的看点，朱鹮栖息地，芦苇迷宫。攻略把它排进主线，时间留得最足。","notice":"朱鹮栖息地，芦苇迷宫。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"德清县"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"笋干烧肉（人均58元）","description":"湖州 · 莫干山的招牌是笋干烧肉，山间农家菜本地人都认这家，点单照攻略不踩雷。","addr":"莫干山镇"},{"title":"竹林土鸡煲（人均88元）","description":"湖州 · 莫干山的招牌是竹林土鸡煲，民宿餐厅本地人都认这家，点单照攻略不踩雷。","addr":"劳岭村"},{"title":"德清醉鱼（人均38元）","description":"湖州 · 莫干山的招牌是德清醉鱼，水产馆本地人都认这家，点单照攻略不踩雷。","addr":"下渚湖"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18675,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","身份证件与手机充电宝","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","少量零食补给","常用药品（肠胃药/创可贴）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 湖州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九华山休闲二日2','province','池州 · 九华山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',40300,22100,2,'肉身宝殿 / 百岁宫 / 花台栈道 —— 一张票打包九华山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「九华山」两日慢旅行——山岳。九华黄精是养生佳品。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 池州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴池州","description":"集合出发，大巴直达九华山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"肉身宝殿","description":"抵达后首游肉身宝殿，地藏菩萨道场核心，99米地藏圣像。","addr":"池州市青阳县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐九华素斋（人均38元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"百岁宫","description":"早起人少，百岁宫精华时段，缆车直达，天然肉身佛。","addr":"九华街","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐石耳炖鸡，人均78元，补充体力。","addr":"柯村","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"花台栈道","description":"午后游览花台栈道，云海佛光频出。","addr":"九华山高空栈道","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"肉身宝殿","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"肉身宝殿是九华山最有代表性的看点，地藏菩萨道场核心，99米地藏圣像。攻略把它排进主线，时间留得最足。","notice":"地藏菩萨道场核心，99米地藏圣像。这个点位上午光线最好。","durationMinutes":180,"addr":"池州市青阳县"},{"spotId":"S2","name":"百岁宫","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"百岁宫是九华山最有代表性的看点，缆车直达，天然肉身佛。攻略把它排进主线，时间留得最足。","notice":"缆车直达，天然肉身佛。这个点位上午光线最好。","durationMinutes":90,"addr":"九华街"},{"spotId":"S3","name":"花台栈道","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"花台栈道是九华山最有代表性的看点，云海佛光频出。攻略把它排进主线，时间留得最足。","notice":"云海佛光频出。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"九华山高空栈道"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"九华素斋（人均38元）","description":"池州 · 九华山的招牌是九华素斋，化城寺素斋馆本地人都认这家，点单照攻略不踩雷。","addr":"九华街"},{"title":"石耳炖鸡（人均78元）","description":"池州 · 九华山的招牌是石耳炖鸡，山间农家本地人都认这家，点单照攻略不踩雷。","addr":"柯村"},{"title":"黄精茶（人均30元）","description":"池州 · 九华山的招牌是黄精茶，特产店本地人都认这家，点单照攻略不踩雷。","addr":"九华新街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18135,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","相机或运动相机","保温水杯与少量现金","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","山区信号弱，提前下载离线地图"],"faqs":[["到达 池州 的交通方便吗？","推荐先到 池州，再打车或景区直通车前往核心景区；自驾导航直接搜九华山即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 池州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('云台山精华联游二日2','province','焦作 · 云台山','water','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',45900,25200,2,'红石峡 / 茱萸峰 / 潭瀑峡 —— 一张票打包云台山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「云台山」两日慢旅行——水景。铁棍山药焦作温县最好。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 焦作"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴焦作","description":"集合出发，大巴直达云台山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"红石峡","description":"抵达后首游红石峡，红岩碧水盆景峡谷，人再多也值。","addr":"焦作市修武县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐驴肉面（人均28元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"茱萸峰","description":"早起人少，茱萸峰精华时段，王维遥知兄弟登高处。","addr":"云台山主峰","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐山药炖排骨，人均58元，补充体力。","addr":"修武县城","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"潭瀑峡","description":"午后游览潭瀑峡，三步一泉五步一瀑。","addr":"云台山","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"红石峡","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"红石峡是云台山最有代表性的看点，红岩碧水盆景峡谷，人再多也值。攻略把它排进主线，时间留得最足。","notice":"红岩碧水盆景峡谷，人再多也值。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"焦作市修武县"},{"spotId":"S2","name":"茱萸峰","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"茱萸峰是云台山最有代表性的看点，王维遥知兄弟登高处。攻略把它排进主线，时间留得最足。","notice":"王维遥知兄弟登高处。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"云台山主峰"},{"spotId":"S3","name":"潭瀑峡","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"潭瀑峡是云台山最有代表性的看点，三步一泉五步一瀑。攻略把它排进主线，时间留得最足。","notice":"三步一泉五步一瀑。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"云台山"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉面（人均28元）","description":"焦作 · 云台山的招牌是驴肉面，修武驴肉馆本地人都认这家，点单照攻略不踩雷。","addr":"云台山岸上镇"},{"title":"山药炖排骨（人均58元）","description":"焦作 · 云台山的招牌是山药炖排骨，怀山药宴本地人都认这家，点单照攻略不踩雷。","addr":"修武县城"},{"title":"松花蛋（人均20元）","description":"焦作 · 云台山的招牌是松花蛋，特产店本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":20655,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","墨镜与拍照道具","保温水杯与少量现金","少量零食补给","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 焦作 的交通方便吗？","推荐先到 焦作，再打车或景区直通车前往核心景区；自驾导航直接搜云台山即可。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五台山山水人文二日2','province','忻州 · 五台山','mountain','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',39400,21600,2,'五爷庙 / 黛螺顶 / 显通寺 —— 一张票打包五台山精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「五台山」两日慢旅行——山岳。五台山台蘑干货珍贵。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山西 · 忻州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴忻州","description":"集合出发，大巴直达五台山，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"五爷庙","description":"抵达后首游五爷庙，香火最旺许愿灵验，早去。","addr":"忻州市五台县","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐台蘑炖山鸡（人均88元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"黛螺顶","description":"早起人少，黛螺顶精华时段，小朝台1080级台阶。","addr":"五台山台怀镇","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐莜面窝窝，人均22元，补充体力。","addr":"五台山镇","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"显通寺","description":"午后游览显通寺，五台山开山寺，铜殿铜塔。","addr":"台怀镇","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"五爷庙","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"五爷庙是五台山最有代表性的看点，香火最旺许愿灵验，早去。攻略把它排进主线，时间留得最足。","notice":"香火最旺许愿灵验，早去。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"忻州市五台县"},{"spotId":"S2","name":"黛螺顶","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"黛螺顶是五台山最有代表性的看点，小朝台1080级台阶。攻略把它排进主线，时间留得最足。","notice":"小朝台1080级台阶。这个点位上午光线最好。","durationMinutes":240,"addr":"五台山台怀镇"},{"spotId":"S3","name":"显通寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"显通寺是五台山最有代表性的看点，五台山开山寺，铜殿铜塔。攻略把它排进主线，时间留得最足。","notice":"五台山开山寺，铜殿铜塔。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"台怀镇"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"台蘑炖山鸡（人均88元）","description":"忻州 · 五台山的招牌是台蘑炖山鸡，山珍馆本地人都认这家，点单照攻略不踩雷。","addr":"台怀镇"},{"title":"莜面窝窝（人均22元）","description":"忻州 · 五台山的招牌是莜面窝窝，农家菜本地人都认这家，点单照攻略不踩雷。","addr":"五台山镇"},{"title":"素斋（人均28元）","description":"忻州 · 五台山的招牌是素斋，塔院寺素斋本地人都认这家，点单照攻略不踩雷。","addr":"塔院寺旁"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":17730,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","少量零食补给","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 忻州，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙面陈家祠轻徒步二日2','province','广州 · 沙面陈家祠','food','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',41800,22900,3,'陈家祠 / 沙面岛 / 永庆坊 —— 一张票打包沙面陈家祠精髓','["往返大巴", "行程内门票", "一晚住宿", "早餐", "领队服务"]','{"overview":"「沙面陈家祠」两日慢旅行——美食。广式腊味礼盒最体面。本攻略按province玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"两日慢旅行","paceText":"两日从容，核心景点不赶路","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 广州"},{"label":"建议游玩","value":"两日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发赴广州","description":"集合出发，大巴直达沙面陈家祠，车上介绍两日行程安排。","addr":"集合城市出发","tip":"提前一晚收拾好行李"},{"dayNo":1,"time":"11:00","title":"陈家祠","description":"抵达后首游陈家祠，岭南建筑木雕巅峰。","addr":"广州市荔湾区","tip":"直接入园，票务已含"},{"dayNo":1,"time":"17:30","title":"入住与晚餐","description":"入住特色民宿，晚餐推荐肠粉（人均15元），早睡养精神。","addr":"民宿周边","tip":"民宿含早，明早7点前吃好"},{"dayNo":2,"time":"08:00","title":"沙面岛","description":"早起人少，沙面岛精华时段，欧陆建筑群，拍照圣地。","addr":"荔湾区","tip":"晨雾时段，多拍多看"},{"dayNo":2,"time":"12:00","title":"午餐补给","description":"午餐虾饺，人均28元，补充体力。","addr":"第十甫路","tip":"下午行程不重，吃到八分饱"},{"dayNo":2,"time":"13:30","title":"永庆坊","description":"午后游览永庆坊，西关骑楼与粤剧艺术博物馆。","addr":"恩宁路","tip":"返程前最后打卡，别恋战"},{"dayNo":2,"time":"16:30","title":"集合返程","description":"统一集合返程，两日圆满收官。","addr":"返程集合点","tip":"回程车上补个觉"}],"spots":[{"spotId":"S1","name":"陈家祠","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"陈家祠是沙面陈家祠最有代表性的看点，岭南建筑木雕巅峰。攻略把它排进主线，时间留得最足。","notice":"岭南建筑木雕巅峰。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"广州市荔湾区"},{"spotId":"S2","name":"沙面岛","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"沙面岛是沙面陈家祠最有代表性的看点，欧陆建筑群，拍照圣地。攻略把它排进主线，时间留得最足。","notice":"欧陆建筑群，拍照圣地。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"荔湾区"},{"spotId":"S3","name":"永庆坊","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"永庆坊是沙面陈家祠最有代表性的看点，西关骑楼与粤剧艺术博物馆。攻略把它排进主线，时间留得最足。","notice":"西关骑楼与粤剧艺术博物馆。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"恩宁路"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肠粉（人均15元）","description":"广州 · 沙面陈家祠的招牌是肠粉，银记肠粉本地人都认这家，点单照攻略不踩雷。","addr":"上九路"},{"title":"虾饺（人均28元）","description":"广州 · 沙面陈家祠的招牌是虾饺，陶陶居本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"},{"title":"双皮奶（人均15元）","description":"广州 · 沙面陈家祠的招牌是双皮奶，南信牛奶甜品本地人都认这家，点单照攻略不踩雷。","addr":"第十甫路"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":18810,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","保温水杯与少量现金","相机或运动相机","轻便雨衣或折叠伞","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
