INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('蜀南竹海限定冒险三日','cross','宜宾 · 蜀南竹海','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',106000,58300,1,'蜀南竹海 / 李庄古镇 / 兴文石海 —— 一张票打包蜀南竹海精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「蜀南竹海」三日深度游——古村落。竹荪竹笋干货轻便。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 宜宾"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宜宾，抵达后办理入住、熟悉周边环境。","addr":"宜宾市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"蜀南竹海","description":"下午首站蜀南竹海，调整状态进入旅行节奏，忘忧谷翡翠长廊，竹林深处人家。","addr":"宜宾市长宁县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宜宾一带氛围拉满，晚餐全竹宴人均68元。","addr":"蜀南竹海","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"李庄古镇","description":"全天主景点李庄古镇，万里长江第一古镇，抗战文化。","addr":"翠屏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐李庄白肉（人均42元），早点休息。","addr":"李庄古镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"兴文石海","description":"收官兴文石海，天坑石林与僰人文化。","addr":"兴文县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐燃面后集合返程，三日旅程圆满。","addr":"宜宾市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"蜀南竹海","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"蜀南竹海是蜀南竹海最有代表性的看点，忘忧谷翡翠长廊，竹林深处人家。攻略把它排进主线，时间留得最足。","notice":"忘忧谷翡翠长廊，竹林深处人家。周边有休息区与补给点，随时停留。","durat