INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('布达拉宫经典环线三日','cross','拉萨 · 布达拉宫','plateau','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',103700,57000,2,'布达拉宫 / 大昭寺 / 色拉寺 —— 一张票打包布达拉宫精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「布达拉宫」三日深度游——高原。拉萨转经筒小件最好带。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 拉萨"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往拉萨，抵达后办理入住、熟悉周边环境。","addr":"拉萨市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"布达拉宫","description":"下午首站布达拉宫，调整状态进入旅行节奏，海拔3700宫殿，提前一天预约。","addr":"拉萨市城关区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游拉萨一带氛围拉满，晚餐藏面人均12元。","addr":"八廓街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大昭寺","description":"全天主景点大昭寺，八廓街转经道，藏地心脏。","addr":"老城区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐烤牦牛肉（人均68元），早点休息。","addr":"八角东南角","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"色拉寺","description":"收官色拉寺，辩经下午3点开始，场面壮观。","addr":"城北","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐青稞酒后集合返程，三日旅程圆满。","addr":"藏医院路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"布达拉宫","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"布达拉宫是布达拉宫最有代表性的看点，海拔3700宫殿，提前一天预约。攻略把它排进主线，时间留得最足。","notice":"海拔3700宫殿，提前一天预约。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"拉萨市城关区"},{"spotId":"S2","name":"大昭寺","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"大昭寺是布达拉宫最有代表性的看点，八廓街转经道，藏地心脏。攻略把它排进主线，时间留得最足。","notice":"八廓街转经道，藏地心脏。这个点位上午光线最好。","durationMinutes":120,"addr":"老城区"},{"spotId":"S3","name":"色拉寺","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"色拉寺是布达拉宫最有代表性的看点，辩经下午3点开始，场面壮观。攻略把它排进主线，时间留得最足。","notice":"辩经下午3点开始，场面壮观。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"城北"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏面（人均12元）","description":"拉萨 · 布达拉宫的招牌是藏面，光明港琼甜茶馆本地人都认这家，点单照攻略不踩雷。","addr":"八廓街"},{"title":"烤牦牛肉（人均68元）","description":"拉萨 · 布达拉宫的招牌是烤牦牛肉，玛吉阿米本地人都认这家，点单照攻略不踩雷。","addr":"八角东南角"},{"title":"青稞酒（人均30元）","description":"拉萨 · 布达拉宫的招牌是青稞酒，藏家宴本地人都认这家，点单照攻略不踩雷。","addr":"藏医院路"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":46665,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","相机或运动相机","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五大道瓷房子深度三日','cross','和平 · 五大道瓷房子','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',98600,54200,5,'五大道 / 瓷房子 / 古文化街 —— 一张票打包五大道瓷房子精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「五大道瓷房子」三日深度游——文艺。天津泥人张彩塑传神。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"天津 · 和平"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往和平，抵达后办理入住、熟悉周边环境。","addr":"和平市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"五大道","description":"下午首站五大道，调整状态进入旅行节奏，万国建筑博览会，马车游。","addr":"天津市和平区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游和平一带氛围拉满，晚餐煎饼果子人均10元。","addr":"和平区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"瓷房子","description":"全天主景点瓷房子，7亿瓷片房子，白天看外观。","addr":"和平区赤峰道","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐狗不理包子（人均45元），早点休息。","addr":"山东路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"古文化街","description":"收官古文化街，泥人张杨柳青年画。","addr":"南开区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐耳朵眼炸糕后集合返程，三日旅程圆满。","addr":"古文化街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"五大道","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"五大道是五大道瓷房子最有代表性的看点，万国建筑博览会，马车游。攻略把它排进主线，时间留得最足。","notice":"万国建筑博览会，马车游。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"天津市和平区"},{"spotId":"S2","name":"瓷房子","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"瓷房子是五大道瓷房子最有代表性的看点，7亿瓷片房子，白天看外观。攻略把它排进主线，时间留得最足。","notice":"7亿瓷片房子，白天看外观。这个点位上午光线最好。","durationMinutes":30,"addr":"和平区赤峰道"},{"spotId":"S3","name":"古文化街","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"古文化街是五大道瓷房子最有代表性的看点，泥人张杨柳青年画。攻略把它排进主线，时间留得最足。","notice":"泥人张杨柳青年画。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"南开区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"煎饼果子（人均10元）","description":"和平 · 五大道瓷房子的招牌是煎饼果子，南楼煎饼本地人都认这家，点单照攻略不踩雷。","addr":"和平区"},{"title":"狗不理包子（人均45元）","description":"和平 · 五大道瓷房子的招牌是狗不理包子，狗不理总店本地人都认这家，点单照攻略不踩雷。","addr":"山东路"},{"title":"耳朵眼炸糕（人均8元）","description":"和平 · 五大道瓷房子的招牌是耳朵眼炸糕，耳朵眼总店本地人都认这家，点单照攻略不踩雷。","addr":"古文化街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44370,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","墨镜与拍照道具","常用药品（肠胃药/创可贴）","保温水杯与少量现金","少量零食补给","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 和平 的交通方便吗？","推荐先到 和平，再打车或景区直通车前往核心景区；自驾导航直接搜五大道瓷房子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙虎山精华三日','cross','鹰潭 · 龙虎山','water','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',85900,47200,2,'仙水岩 / 泸溪河竹筏 / 上清古镇 —— 一张票打包龙虎山精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「龙虎山」三日深度游——水景。龙虎山道教养生茶值得带。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 鹰潭"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往鹰潭，抵达后办理入住、熟悉周边环境。","addr":"鹰潭市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"仙水岩","description":"下午首站仙水岩，调整状态进入旅行节奏，悬棺表演一天四场，提前占前排。","addr":"龙虎山仙水岩景区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游鹰潭一带氛围拉满，晚餐天师板栗烧鸡人均68元。","addr":"上清古镇长街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"泸溪河竹筏","description":"全天主景点泸溪河竹筏，顺流漂90分钟，防晒必做。","addr":"龙虎山竹筏码头","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐泸溪河鱼（人均58元），早点休息。","addr":"竹筏码头旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"上清古镇","description":"收官上清古镇，天师府在此，古街人少。","addr":"龙虎山上清镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐上清豆腐后集合返程，三日旅程圆满。","addr":"上清古街中段","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"仙水岩","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"仙水岩是龙虎山最有代表性的看点，悬棺表演一天四场，提前占前排。攻略把它排进主线，时间留得最足。","notice":"悬棺表演一天四场，提前占前排。这个点位上午光线最