INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('张家界国家森林公园山河三日','cross','张家界 · 张家界国家森林公园','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',92900,51000,2,'袁家界 / 天子山 / 金鞭溪 —— 一张票打包张家界国家森林公园精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「张家界国家森林公园」三日深度游——山岳。张家界莓茶降火神器。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 张家界"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往张家界，抵达后办理入住、熟悉周边环境。","addr":"张家界市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"袁家界","description":"下午首站袁家界，调整状态进入旅行节奏，阿凡达悬浮山原型，百龙天梯上山。","addr":"武陵源区森林公园","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游张家界一带氛围拉满，晚餐三下锅人均58元。","addr":"武陵源汽车站旁","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天子山","description":"全天主景点天子山，御笔峰日落绝佳，贺龙公园顺路。","addr":"武陵源天子山景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土家腊肉（人均48元），早点休息。","addr":"溪布街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"金鞭溪","description":"收官金鞭溪，全程7.5公里平路，溪边猕猴抢食注意。","addr":"森林公园大氧吧广场","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐岩耳炖土鸡后集合返程，三日旅程圆满。","addr":"森林公园门票站","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"袁家界","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"袁家界是张家界国家森林公园最有代表性的看点，阿凡达悬浮山原型，百龙天梯上山。攻略把它排进主线，时间留得最足。","notice":"阿凡达悬浮山原型，百龙天梯上山。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"武陵源区森林公园"},{"spotId":"S2","name":"天子山","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"天子山是张家界国家森林公园最有代表性的看点，御笔峰日落绝佳，贺龙公园顺路。攻略把它排进主线，时间留得最足。","notice":"御笔峰日落绝佳，贺龙公园顺路。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"武陵源天子山景区"},{"spotId":"S3","name":"金鞭溪","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"金鞭溪是张家界国家森林公园最有代表性的看点，全程7.5公里平路，溪边猕猴抢食注意。攻略把它排进主线，时间留得最足。","notice":"全程7.5公里平路，溪边猕猴抢食注意。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"森林公园大氧吧广场"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"三下锅（人均58元）","description":"张家界 · 张家界国家森林公园的招牌是三下锅，胡师傅三下锅本地人都认这家，点单照攻略不踩雷。","addr":"武陵源汽车站旁"},{"title":"土家腊肉（人均48元）","description":"张家界 · 张家界国家森林公园的招牌是土家腊肉，湘西腊肉馆本地人都认这家，点单照攻略不踩雷。","addr":"溪布街"},{"title":"岩耳炖土鸡（人均88元）","description":"张家界 · 张家界国家森林公园的招牌是岩耳炖土鸡，山里人家本地人都认这家，点单照攻略不踩雷。","addr":"森林公园门票站"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":41805,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","少量零食补给","保温水杯与少量现金","身份证件与手机充电宝","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["几月份去 张家界 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 张家界 的交通方便吗？","推荐先到 张家界，再打车或景区直通车前往核心景区；自驾导航直接搜张家界国家森林公园即可。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('紫鹊界梯田全景三日','cross','娄底 · 紫鹊界梯田','village','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',86400,47500,1,'紫鹊界梯田 / 正龙古村 / 梅山龙宫 —— 一张票打包紫鹊界梯田精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「紫鹊界梯田」三日深度游——古村落。新化黄精茶养生。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 娄底"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往娄底，抵达后办理入住、熟悉周边环境。","addr":"娄底市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"紫鹊界梯田","description":"下午首站紫鹊界梯田，调整状态进入旅行节奏，两千年秦人梯田，月牙山八仙过海。","addr":"娄底市新化县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游娄底一带氛围拉满，晚餐新化三合汤人均38元。","addr":"新化县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"正龙古村","description":"全天主景点正龙古村，干栏式板屋村落。","addr":"紫鹊界脚下","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐杯子糕（人均10元），早点休息。","addr":"紫鹊界","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"梅山龙宫","description":"收官梅山龙宫，地下溶洞暗河乘船。","addr":"新化县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐柴火腊肉后集合返程，三日旅程圆满。","addr":"正龙古村","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"紫鹊界梯田","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"紫鹊界梯田是紫鹊界梯田最有代表性的看点，两千年秦人梯田，月牙山八仙过海。攻略把它排进主线，时间留得最足。","notice":"两千年秦人梯田，月牙山八仙过海。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"娄底市新化县"},{"spotId":"S2","name":"正龙古村","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"正龙古村是紫鹊界梯田最有代表性的看点，干栏式板屋村落。攻略把它排进主线，时间留得最足。","notice":"干栏式板屋村落。这个点位上午光线最好。","durationMinutes":90,"addr":"紫鹊界脚下"},{"spotId":"S3","name":"梅山龙宫","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"梅山龙宫是紫鹊界梯田最有代表性的看点，地下溶洞暗河乘船。攻略把它排进主线，时间留得最足。","notice":"地下溶洞暗河乘船。这个点位上午光线最好。","durationMinutes":150,"addr":"新化县"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"新化三合汤（人均38元）","description":"娄底 · 紫鹊界梯田的招牌是新化三合汤，老字号三合汤本地人都认这家，点单照攻略不踩雷。","addr":"新化县城"},{"title":"杯子糕（人均10元）","description":"娄底 · 紫鹊界梯田的招牌是杯子糕，街头小吃本地人都认这家，点单照攻略不踩雷。","addr":"紫鹊界"},{"title":"柴火腊肉（人均45元）","description":"娄底 · 紫鹊界梯田的招牌是柴火腊肉，农家直购本地人都认这家，点单照攻略不踩雷。","addr":"正龙古村"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":38880,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","墨镜与拍照道具","防晒霜与遮阳帽","少量零食补给","相机或运动相机","常用药品（肠胃药/创可贴）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大熊猫基地都江堰秘境三日','cross','成都 · 大熊猫基地都江堰','food','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',90900,49900,3,'大熊猫繁育研究基地 / 都江堰 / 南桥夜啤酒 —— 一张票打包大熊猫基地都江堰精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「大熊猫基地都江堰」三日深度游——美食。郫县豆瓣是川菜之魂。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 成都"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往成都，抵达后办理入住、熟悉周边环境。","addr":"成都市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"大熊猫繁育研究基地","description":"下午首站大熊猫繁育研究基地，调整状态进入旅行节奏，早8点开园直奔月亮产房，熊猫最活跃。","addr":"成华区外北熊猫大道","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游成都一带氛围拉满，晚餐火锅人均110元。","addr":"建设路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"都江堰","description":"全天主景点都江堰，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。","addr":"都江堰市公园路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐串串香（人均65元），早点休息。","addr":"玉林路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"南桥夜啤酒","description":"收官南桥夜啤酒，岷江水上的夜风与美食。","addr":"都江堰市南桥","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐钟水饺后集合返程，三日旅程圆满。","addr":"人民公园旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"大熊猫繁育研究基地","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"大熊猫繁育研究基地是大熊猫基地都江堰最有代表性的看点，早8点开园直奔月亮产房，熊猫最活跃。攻略把它排进主线，时间留得最足。","notice":"早8点开园直奔月亮产房，熊猫最活跃。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"成华区外北熊猫大道"},{"spotId":"S2","name":"都江堰","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"都江堰是大熊猫基地都江堰最有代表性的看点，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。攻略把它排进主线，时间留得最足。","notice":"鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"都江堰市公园路"},{"spotId":"S3","name":"南桥夜啤酒","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"南桥夜啤酒是大熊猫基地都江堰最有代表性的看点，岷江水上的夜风与美食。攻略把它排进主线，时间留得最足。","notice":"岷江水上的夜风与美食。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"都江堰市南桥"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"火锅（人均110元）","description":"成都 · 大熊猫基地都江堰的招牌是火锅，蜀大侠本地人都认这家，点单照攻略不踩雷。","addr":"建设路"},{"title":"串串香（人均65元）","description":"成都 · 大熊猫基地都江堰的招牌是串串香，马路边边本地人都认这家，点单照攻略不踩雷。","addr":"玉林路"},{"title":"钟水饺（人均15元）","description":"成都 · 大熊猫基地都江堰的招牌是钟水饺，老字号小吃本地人都认这家，点单照攻略不踩雷。","addr":"人民公园旁"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":40905,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["轻便雨衣或折叠伞","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","相机或运动相机","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","少量零食补给","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 成都，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄果树瀑布跨省三日','cross','安顺 · 黄果树瀑布','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',84100,46200,2,'黄果树大瀑布 / 天星桥 / 陡坡塘 —— 一张票打包黄果树瀑布精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「黄果树瀑布」三日深度游——水景。安顺三刀是传统名点。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 安顺"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往安顺，抵达后办理入住、熟悉周边环境。","addr":"安顺市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄果树大瀑布","description":"下午首站黄果树大瀑布，调整状态进入旅行节奏，亚洲最大瀑布，水帘洞穿瀑而过。","addr":"安顺市镇宁县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游安顺一带氛围拉满，晚餐夺夺粉人均35元。","addr":"安顺市区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"天星桥","description":"全天主景点天星桥，石景水上盆景，数生步趣味。","addr":"黄果树景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐裹卷（人均12元），早点休息。","addr":"黄果树镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"陡坡塘","description":"收官陡坡塘，西游记片尾取景地。","addr":"黄果树景区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐布依农家餐后集合返程，三日旅程圆满。","addr":"石头寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄果树大瀑布","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"黄果树大瀑布是黄果树瀑布最有代表性的看点，亚洲最大瀑布，水帘洞穿瀑而过。攻略把它排进主线，时间留得最足。","notice":"亚洲最大瀑布，水帘洞穿瀑而过。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"安顺市镇宁县"},{"spotId":"S2","name":"天星桥","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"天星桥是黄果树瀑布最有代表性的看点，石景水上盆景，数生步趣味。攻略把它排进主线，时间留得最足。","notice":"石景水上盆景，数生步趣味。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"黄果树景区"},{"spotId":"S3","name":"陡坡塘","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"陡坡塘是黄果树瀑布最有代表性的看点，西游记片尾取景地。攻略把它排进主线，时间留得最足。","notice":"西游记片尾取景地。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"黄果树景区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"夺夺粉（人均35元）","description":"安顺 · 黄果树瀑布的招牌是夺夺粉，安顺小吃街本地人都认这家，点单照攻略不踩雷。","addr":"安顺市区"},{"title":"裹卷（人均12元）","description":"安顺 · 黄果树瀑布的招牌是裹卷，苗岭小吃本地人都认这家，点单照攻略不踩雷。","addr":"黄果树镇"},{"title":"布依农家餐（人均48元）","description":"安顺 · 黄果树瀑布的招牌是布依农家餐，石头寨本地人都认这家，点单照攻略不踩雷。","addr":"石头寨"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":37845,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","身份证件与手机充电宝","相机或运动相机","防晒霜与遮阳帽","保温水杯与少量现金","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 安顺 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 安顺，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙脊梯田限定冒险三日','cross','桂林 · 龙脊梯田','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',103000,56600,1,'平安寨七星伴月 / 金坑大寨 / 黄洛红瑶寨 —— 一张票打包龙脊梯田精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「龙脊梯田」三日深度游——古村落。龙脊辣椒酱拌饭一绝。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往桂林，抵达后办理入住、熟悉周边环境。","addr":"桂林市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"平安寨七星伴月","description":"下午首站平安寨七星伴月，调整状态进入旅行节奏，经典梯田观景台，徒步30分钟。","addr":"龙胜县龙脊镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游桂林一带氛围拉满，晚餐竹筒饭人均25元。","addr":"平安寨","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"金坑大寨","description":"全天主景点金坑大寨，缆车直达3号观景点，日落最佳。","addr":"龙脊梯田金坑","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐土鸡煲（人均68元），早点休息。","addr":"金坑梯田","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"黄洛红瑶寨","description":"收官黄洛红瑶寨，天下第一长发村表演。","addr":"龙脊山下","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐龙脊茶后集合返程，三日旅程圆满。","addr":"黄洛瑶寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"平安寨七星伴月","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"平安寨七星伴月是龙脊梯田最有代表性的看点，经典梯田观景台，徒步30分钟。攻略把它排进主线，时间留得最足。","notice":"经典梯田观景台，徒步30分钟。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"龙胜县龙脊镇"},{"spotId":"S2","name":"金坑大寨","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"金坑大寨是龙脊梯田最有代表性的看点，缆车直达3号观景点，日落最佳。攻略把它排进主线，时间留得最足。","notice":"缆车直达3号观景点，日落最佳。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"龙脊梯田金坑"},{"spotId":"S3","name":"黄洛红瑶寨","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"黄洛红瑶寨是龙脊梯田最有代表性的看点，天下第一长发村表演。攻略把它排进主线，时间留得最足。","notice":"天下第一长发村表演。提前10分钟到，避开旅行团大部队。","durationMinutes":60,"addr":"龙脊山下"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"竹筒饭（人均25元）","description":"桂林 · 龙脊梯田的招牌是竹筒饭，梯田农家本地人都认这家，点单照攻略不踩雷。","addr":"平安寨"},{"title":"土鸡煲（人均68元）","description":"桂林 · 龙脊梯田的招牌是土鸡煲，大寨农家本地人都认这家，点单照攻略不踩雷。","addr":"金坑梯田"},{"title":"龙脊茶（人均20元）","description":"桂林 · 龙脊梯田的招牌是龙脊茶，茶农家本地人都认这家，点单照攻略不踩雷。","addr":"黄洛瑶寨"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":46350,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","保温水杯与少量现金","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","相机或运动相机"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('霞浦滩涂经典环线三日','cross','宁德 · 霞浦滩涂','photography','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',101100,55600,12,'北岐滩涂 / 杨家溪 / 东壁日落 —— 一张票打包霞浦滩涂精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「霞浦滩涂」三日深度游——摄影胜地。霞浦紫菜海带全国第一。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 宁德"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往宁德，抵达后办理入住、熟悉周边环境。","addr":"宁德市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"北岐滩涂","description":"下午首站北岐滩涂，调整状态进入旅行节奏，日出紫菜架光影，摄影圣地。","addr":"霞浦县松港街道","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游宁德一带氛围拉满，晚餐霞浦剑蛏人均68元。","addr":"三沙镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"杨家溪","description":"全天主景点杨家溪，千年枫榕树群，牛群穿雾。","addr":"霞浦县牙城镇","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海带排骨汤（人均38元），早点休息。","addr":"北岐村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"东壁日落","description":"收官东壁日落，落日渔船归航机位。","addr":"霞浦县三沙镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糊汤后集合返程，三日旅程圆满。","addr":"霞浦县城","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"北岐滩涂","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"北岐滩涂是霞浦滩涂最有代表性的看点，日出紫菜架光影，摄影圣地。攻略把它排进主线，时间留得最足。","notice":"日出紫菜架光影，摄影圣地。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"霞浦县松港街道"},{"spotId":"S2","name":"杨家溪","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"杨家溪是霞浦滩涂最有代表性的看点，千年枫榕树群，牛群穿雾。攻略把它排进主线，时间留得最足。","notice":"千年枫榕树群，牛群穿雾。这个点位上午光线最好。","durationMinutes":150,"addr":"霞浦县牙城镇"},{"spotId":"S3","name":"东壁日落","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"东壁日落是霞浦滩涂最有代表性的看点，落日渔船归航机位。攻略把它排进主线，时间留得最足。","notice":"落日渔船归航机位。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"霞浦县三沙镇"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"霞浦剑蛏（人均68元）","description":"宁德 · 霞浦滩涂的招牌是霞浦剑蛏，海鲜大排档本地人都认这家，点单照攻略不踩雷。","addr":"三沙镇"},{"title":"海带排骨汤（人均38元）","description":"宁德 · 霞浦滩涂的招牌是海带排骨汤，渔家菜本地人都认这家，点单照攻略不踩雷。","addr":"北岐村"},{"title":"糊汤（人均10元）","description":"宁德 · 霞浦滩涂的招牌是糊汤，街头早点本地人都认这家，点单照攻略不踩雷。","addr":"霞浦县城"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":45495,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","墨镜与拍照道具","换洗衣物与外套（早晚温差）","少量零食补给","常用药品（肠胃药/创可贴）","相机或运动相机","防晒霜与遮阳帽","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["到达 宁德 的交通方便吗？","推荐先到 宁德，再打车或景区直通车前往核心景区；自驾导航直接搜霞浦滩涂即可。"],["当地有什么必吃？","到了 宁德，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 宁德 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('拙政园林深度三日','cross','苏州 · 拙政园林','art','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',82900,45500,5,'拙政园 / 平江路 / 虎丘 —— 一张票打包拙政园林精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「拙政园林」三日深度游——文艺。苏绣团扇工艺最精。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 苏州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往苏州，抵达后办理入住、熟悉周边环境。","addr":"苏州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"拙政园","description":"下午首站拙政园，调整状态进入旅行节奏，江南园林之母，人再多也值得。","addr":"苏州市姑苏区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游苏州一带氛围拉满，晚餐松鼠桂鱼人均128元。","addr":"太监弄","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"平江路","description":"全天主景点平江路，小桥流水人家，评弹声里喝茶。","addr":"姑苏区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蟹粉小笼（人均25元），早点休息。","addr":"临顿路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"虎丘","description":"收官虎丘，吴中第一名胜，斜塔传奇。","addr":"姑苏区山塘街","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐桂花糕后集合返程，三日旅程圆满。","addr":"山塘街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"拙政园","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"拙政园是拙政园林最有代表性的看点，江南园林之母，人再多也值得。攻略把它排进主线，时间留得最足。","notice":"江南园林之母，人再多也值得。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"苏州市姑苏区"},{"spotId":"S2","name":"平江路","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"平江路是拙政园林最有代表性的看点，小桥流水人家，评弹声里喝茶。攻略把它排进主线，时间留得最足。","notice":"小桥流水人家，评弹声里喝茶。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"姑苏区"},{"spotId":"S3","name":"虎丘","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"虎丘是拙政园林最有代表性的看点，吴中第一名胜，斜塔传奇。攻略把它排进主线，时间留得最足。","notice":"吴中第一名胜，斜塔传奇。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"姑苏区山塘街"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松鼠桂鱼（人均128元）","description":"苏州 · 拙政园林的招牌是松鼠桂鱼，得月楼本地人都认这家，点单照攻略不踩雷。","addr":"太监弄"},{"title":"蟹粉小笼（人均25元）","description":"苏州 · 拙政园林的招牌是蟹粉小笼，哑巴生煎本地人都认这家，点单照攻略不踩雷。","addr":"临顿路"},{"title":"桂花糕（人均15元）","description":"苏州 · 拙政园林的招牌是桂花糕，采芝斋本地人都认这家，点单照攻略不踩雷。","addr":"山塘街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":37305,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","身份证件与手机充电宝","相机或运动相机","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 苏州 的交通方便吗？","推荐先到 苏州，再打车或景区直通车前往核心景区；自驾导航直接搜拙政园林即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一次，把心跳交给山野。','on');
