INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('泰山全景三日','cross','泰安 · 泰山','mountain','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',95000,52200,2,'玉皇顶 / 十八盘 / 岱庙 —— 一张票打包泰山精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「泰山」三日深度游——山岳。泰山墨玉平安扣吉祥。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 泰安"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往泰安，抵达后办理入住、熟悉周边环境。","addr":"泰安市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"玉皇顶","description":"下午首站玉皇顶，调整状态进入旅行节奏，五岳之首看日出，夜爬经典。","addr":"泰安市泰山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游泰安一带氛围拉满，晚餐泰安煎饼人均12元。","addr":"红门路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"十八盘","description":"全天主景点十八盘，1600级台阶，紧十八慢十八。","addr":"泰山中天门","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐豆腐宴（人均38元），早点休息。","addr":"岱庙旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"岱庙","description":"收官岱庙，历代帝王封禅起点。","addr":"泰山区东岳大街","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐赤鳞鱼后集合返程，三日旅程圆满。","addr":"中天门","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"玉皇顶","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"玉皇顶是泰山最有代表性的看点，五岳之首看日出，夜爬经典。攻略把它排进主线，时间留得最足。","notice":"五岳之首看日出，夜爬经典。拍照记得留神脚下台阶。","durationMinutes":360,"addr":"泰安市泰山区"},{"spotId":"S2","name":"十八盘","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"十八盘是泰山最有代表性的看点，1600级台阶，紧十八慢十八。攻略把它排进主线，时间留得最足。","notice":"1600级台阶，紧十八慢十八。这个点位上午光线最好。","durationMinutes":180,"addr":"泰山中天门"},{"spotId":"S3","name":"岱庙","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"岱庙是泰山最有代表性的看点，历代帝王封禅起点。攻略把它排进主线，时间留得最足。","notice":"历代帝王封禅起点。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"泰山区东岳大街"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"泰安煎饼（人均12元）","description":"泰安 · 泰山的招牌是泰安煎饼，煎饼卷大葱本地人都认这家，点单照攻略不踩雷。","addr":"红门路"},{"title":"豆腐宴（人均38元）","description":"泰安 · 泰山的招牌是豆腐宴，岱庙豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"岱庙旁"},{"title":"赤鳞鱼（人均68元）","description":"泰安 · 泰山的招牌是赤鳞鱼，山溪鱼馆本地人都认这家，点单照攻略不踩雷。","addr":"中天门"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":42750,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","相机或运动相机","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","保温水杯与少量现金"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 泰安，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
