INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雅鲁藏布大峡谷限定冒险三日','cross','林芝 · 雅鲁藏布大峡谷','plateau','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',106500,58500,2,'南迦巴瓦观景台 / 雅鲁藏布大峡谷 / 鲁朗林海 —— 一张票打包雅鲁藏布大峡谷精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「雅鲁藏布大峡谷」三日深度游——高原。林芝松茸6-8月最鲜。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 林芝"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往林芝，抵达后办理入住、熟悉周边环境。","addr":"林芝市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"南迦巴瓦观景台","description":"下午首站南迦巴瓦观景台，调整状态进入旅行节奏，羞女峰十人九不遇，直白村最近。","addr":"米林县派镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游林芝一带氛围拉满，晚餐鲁朗石锅鸡人均128元。","addr":"鲁朗镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"雅鲁藏布大峡谷","description":"全天主景点雅鲁藏布大峡谷，世界最深深峡，换乘游览。","addr":"林芝市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐藏香猪（人均58元），早点休息。","addr":"派镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"鲁朗林海","description":"收官鲁朗林海，东方瑞士，石锅鸡之乡。","addr":"鲁朗镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐松茸炖藏鸡后集合返程，三日旅程圆满。","addr":"林芝市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"南迦巴瓦观景台","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"南迦巴瓦观景台是雅鲁藏布大峡谷最有代表性的看点，羞女峰十人九不遇，直白村最近。攻略把它排进主线，时间留得最足。","notice":"羞女峰十人九不遇，直白村最近。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"米林县派镇"},{"spotId":"S2","name":"雅鲁藏布大峡谷","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"雅鲁藏布大峡谷是雅鲁藏布大峡谷最有代表性的看点，世界最深深峡，换乘游览。攻略把它排进主线，时间留得最足。","notice":"世界最深深峡，换乘游览。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"林芝市"},{"spotId":"S3","name":"鲁朗林海","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"鲁朗林海是雅鲁藏布大峡谷最有代表性的看点，东方瑞士，石锅鸡之乡。攻略把它排进主线，时间留得最足。","notice":"东方瑞士，石锅鸡之乡。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"鲁朗镇"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"鲁朗石锅鸡（人均128元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是鲁朗石锅鸡，石锅鸡总店本地人都认这家，点单照攻略不踩雷。","addr":"鲁朗镇"},{"title":"藏香猪（人均58元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是藏香猪，工布藏餐本地人都认这家，点单照攻略不踩雷。","addr":"派镇"},{"title":"松茸炖藏鸡（人均98元）","description":"林芝 · 雅鲁藏布大峡谷的招牌是松茸炖藏鸡，林芝菌菇宴本地人都认这家，点单照攻略不踩雷。","addr":"林芝市区"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":47925,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["防晒霜与遮阳帽","相机或运动相机","轻便雨衣或折叠伞","身份证件与手机充电宝","少量零食补给","换洗衣物与外套（早晚温差）","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 林芝，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["几月份去 林芝 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('沙坡头经典环线三日','cross','中卫 · 沙坡头','adventure','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',96600,53100,9,'沙坡头 / 通湖草原 / 66号公路 —— 一张票打包沙坡头精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「沙坡头」三日深度游——探险地。中卫硒砂瓜甜到心里。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"宁夏 · 中卫"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往中卫，抵达后办理入住、熟悉周边环境。","addr":"中卫市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"沙坡头","description":"下午首站沙坡头，调整状态进入旅行节奏，黄河飞索与羊皮筏子，沙漠骑骆驼。","addr":"中卫市沙坡头区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游中卫一带氛围拉满，晚餐硒砂瓜人均10元。","addr":"沙坡头","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"通湖草原","description":"全天主景点通湖草原，沙漠营地篝火晚会。","addr":"阿拉善左旗","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐黄河大鲤鱼（人均58元），早点休息。","addr":"景区旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"66号公路","description":"收官66号公路，网红沙漠公路打卡。","addr":"中卫市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐手抓滩羊后集合返程，三日旅程圆满。","addr":"中卫市区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"沙坡头","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"沙坡头是沙坡头最有代表性的看点，黄河飞索与羊皮筏子，沙漠骑骆驼。攻略把它排进主线，时间留得最足。","notice":"黄河飞索与羊皮筏子，沙漠骑骆驼。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"中卫市沙坡头区"},{"spotId":"S2","name":"通湖草原","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"通湖草原是沙坡头最有代表性的看点，沙漠营地篝火晚会。攻略把它排进主线，时间留得最足。","notice":"沙漠营地篝火晚会。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"阿拉善左旗"},{"spotId":"S3","name":"66号公路","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"66号公路是沙坡头最有代表性的看点，网红沙漠公路打卡。攻略把它排进主线，时间留得最足。","notice":"网红沙漠公路打卡。这个点位上午光线最好。","durationMinutes":60,"addr":"中卫市"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"硒砂瓜（人均10元）","description":"中卫 · 沙坡头的招牌是硒砂瓜，路边瓜摊本地人都认这家，点单照攻略不踩雷。","addr":"沙坡头"},{"title":"黄河大鲤鱼（人均58元）","description":"中卫 · 沙坡头的招牌是黄河大鲤鱼，沙坡头渔村本地人都认这家，点单照攻略不踩雷。","addr":"景区旁"},{"title":"手抓滩羊（人均68元）","description":"中卫 · 沙坡头的招牌是手抓滩羊，夏华火锅本地人都认这家，点单照攻略不踩雷。","addr":"中卫市区"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":43470,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","相机或运动相机","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","墨镜与拍照道具","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["到达 中卫 的交通方便吗？","推荐先到 中卫，再打车或景区直通车前往核心景区；自驾导航直接搜沙坡头即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('滕王阁深度三日','cross','南昌 · 滕王阁','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',106300,58400,5,'滕王阁 / 万寿宫历史文化街区 / 秋水广场 —— 一张票打包滕王阁精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「滕王阁」三日深度游——文艺。南昌瓷板画是独特纪念品。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 南昌"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往南昌，抵达后办理入住、熟悉周边环境。","addr":"南昌市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"滕王阁","description":"下午首站滕王阁，调整状态进入旅行节奏，落霞与孤鹜齐名的主阁，登顶看赣江。","addr":"南昌市东湖区仿古街58号","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游南昌一带氛围拉满，晚餐瓦罐汤人均18元。","addr":"万寿宫街区巷口","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"万寿宫历史文化街区","description":"全天主景点万寿宫历史文化街区，夜市烟火气，白天逛老建筑。","addr":"西湖区中山路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐拌粉（人均12元），早点休息。","addr":"中山路支巷","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"秋水广场","description":"收官秋水广场，亚洲最大音乐喷泉群，晚上两场。","addr":"红谷滩区赣江中大道","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐白糖糕后集合返程，三日旅程圆满。","addr":"万寿宫内街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"滕王阁","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"滕王阁是滕王阁最有代表性的看点，落霞与孤鹜齐名的主阁，登顶看赣江。攻略把它排进主线，时间留得最足。","notice":"落霞与孤鹜齐名的主阁，登顶看赣江。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"南昌市东湖区仿古街58号"},{"spotId":"S2","name":"万寿宫历史文化街区","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"万寿宫历史文化街区是滕王阁最有代表性的看点，夜市烟火气，白天逛老建筑。攻略把它排进主线，时间留得最足。","notice":"夜市烟火气，白天逛老建筑。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"西湖区中山路"},{"spotId":"S3","name":"秋水广场","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"秋水广场是滕王阁最有代表性的看点，亚洲最大音乐喷泉群，晚上两场。攻略把它排进主线，时间留得最足。","notice":"亚洲最大音乐喷泉群，晚上两场。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"红谷滩区赣江中大道"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"瓦罐汤（人均18元）","description":"南昌 · 滕王阁的招牌是瓦罐汤，民间瓦罐汤店本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫街区巷口"},{"title":"拌粉（人均12元）","description":"南昌 · 滕王阁的招牌是拌粉，南昌拌粉总店本地人都认这家，点单照攻略不踩雷。","addr":"中山路支巷"},{"title":"白糖糕（人均8元）","description":"南昌 · 滕王阁的招牌是白糖糕，老字号糕点铺本地人都认这家，点单照攻略不踩雷。","addr":"万寿宫内街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":47835,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","保温水杯与少量现金","防晒霜与遮阳帽","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","墨镜与拍照道具","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 南昌，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('凤凰古城精华三日','cross','湘西 · 凤凰古城','ancient_town','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',99100,54500,1,'沱江跳岩 / 沈从文故居 / 南华山 —— 一张票打包凤凰古城精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「凤凰古城」三日深度游——古镇。凤凰银饰认准足银999。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 湘西"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往湘西，抵达后办理入住、熟悉周边环境。","addr":"湘西市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"沱江跳岩","description":"下午首站沱江跳岩，调整状态进入旅行节奏，清晨雾气中的吊脚楼最出片。","addr":"凤凰古城沱江北门","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游湘西一带氛围拉满，晚餐血粑鸭人均58元。","addr":"虹桥东路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"沈从文故居","description":"全天主景点沈从文故居，文学爱好者必打卡，讲解值得请。","addr":"凤凰古城中营街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐苗家酸汤鱼（人均68元），早点休息。","addr":"沱江边吊脚楼","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"南华山","description":"收官南华山，登高俯瞰全城夜景。","addr":"凤凰城南","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐凤凰姜糖后集合返程，三日旅程圆满。","addr":"东正街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"沱江跳岩","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"沱江跳岩是凤凰古城最有代表性的看点，清晨雾气中的吊脚楼最出片。攻略把它排进主线，时间留得最足。","notice":"清晨雾气中的吊脚楼最出片。这个点位上午光线最好。","durationMinutes":90,"addr":"凤凰古城沱江北门"},{"spotId":"S2","name":"沈从文故居","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"沈从文故居是凤凰古城最有代表性的看点，文学爱好者必打卡，讲解值得请。攻略把它排进主线，时间留得最足。","notice":"文学爱好者必打卡，讲解值得请。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"凤凰古城中营街"},{"spotId":"S3","name":"南华山","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"南华山是凤凰古城最有代表性的看点，登高俯瞰全城夜景。攻略把它排进主线，时间留得最足。","notice":"登高俯瞰全城夜景。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"凤凰城南"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"血粑鸭（人均58元）","description":"湘西 · 凤凰古城的招牌是血粑鸭，凤凰老字号本地人都认这家，点单照攻略不踩雷。","addr":"虹桥东路"},{"title":"苗家酸汤鱼（人均68元）","description":"湘西 · 凤凰古城的招牌是苗家酸汤鱼，古城酸汤鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"沱江边吊脚楼"},{"title":"凤凰姜糖（人均15元）","description":"湘西 · 凤凰古城的招牌是凤凰姜糖，老街姜糖铺本地人都认这家，点单照攻略不踩雷。","addr":"东正街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44595,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["保温水杯与少量现金","常用药品（肠胃药/创可贴）","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","墨镜与拍照道具","轻便雨衣或折叠伞","少量零食补给"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["当地有什么必吃？","到了 湘西，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'慢一点，风景才来得及认识你。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大理古城洱海山河三日','cross','大理 · 大理古城洱海','water','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',101300,55700,2,'洱海生态廊道 / 大理古城 / 崇圣寺三塔 —— 一张票打包大理古城洱海精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「大理古城洱海」三日深度游——水景。喜洲粑粑现烤的最香。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 大理"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往大理，抵达后办理入住、熟悉周边环境。","addr":"大理市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"洱海生态廊道","description":"下午首站洱海生态廊道，调整状态进入旅行节奏，租电动车骑行，S湾拍倒影。","addr":"大理市环海西路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游大理一带氛围拉满，晚餐白族三道茶人均48元。","addr":"喜洲古镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大理古城","description":"全天主景点大理古城，洋人街与五华楼，夜晚酒吧街热闹。","addr":"大理市一塔路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐砂锅鱼（人均78元），早点休息。","addr":"才村码头","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"崇圣寺三塔","description":"收官崇圣寺三塔，大理地标，倒影公园拍三塔。","addr":"大理市三塔路","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐乳扇后集合返程，三日旅程圆满。","addr":"古城人民路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"洱海生态廊道","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"洱海生态廊道是大理古城洱海最有代表性的看点，租电动车骑行，S湾拍倒影。攻略把它排进主线，时间留得最足。","notice":"租电动车骑行，S湾拍倒影。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"大理市环海西路"},{"spotId":"S2","name":"大理古城","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"大理古城是大理古城洱海最有代表性的看点，洋人街与五华楼，夜晚酒吧街热闹。攻略把它排进主线，时间留得最足。","notice":"洋人街与五华楼，夜晚酒吧街热闹。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"大理市一塔路"},{"spotId":"S3","name":"崇圣寺三塔","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"崇圣寺三塔是大理古城洱海最有代表性的看点，大理地标，倒影公园拍三塔。攻略把它排进主线，时间留得最足。","notice":"大理地标，倒影公园拍三塔。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"大理市三塔路"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"白族三道茶（人均48元）","description":"大理 · 大理古城洱海的招牌是白族三道茶，严家大院本地人都认这家，点单照攻略不踩雷。","addr":"喜洲古镇"},{"title":"砂锅鱼（人均78元）","description":"大理 · 大理古城洱海的招牌是砂锅鱼，大理砂锅鱼庄本地人都认这家，点单照攻略不踩雷。","addr":"才村码头"},{"title":"乳扇（人均12元）","description":"大理 · 大理古城洱海的招牌是乳扇，杨记乳扇本地人都认这家，点单照攻略不踩雷。","addr":"古城人民路"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":45585,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","墨镜与拍照道具","常用药品（肠胃药/创可贴）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","防晒霜与遮阳帽"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'山高水长，都是给你准备的惊喜。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九寨沟全景三日','cross','阿坝 · 九寨沟','water','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',104900,57600,2,'五花海 / 诺日朗瀑布 / 长海 —— 一张票打包九寨沟精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「九寨沟」三日深度游——水景。九寨沟牦牛酸奶值得尝。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 阿坝"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往阿坝，抵达后办理入住、熟悉周边环境。","addr":"阿坝市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"五花海","description":"下午首站五花海，调整状态进入旅行节奏，九寨精华，孔雀河道顺光最美。","addr":"九寨沟县漳扎镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游阿坝一带氛围拉满，晚餐牦牛肉汤锅人均78元。","addr":"漳扎镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"诺日朗瀑布","description":"全天主景点诺日朗瀑布，中国最宽钙华瀑布。","addr":"九寨沟中心站","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐青稞酒（人均30元），早点休息。","addr":"藏寨","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"长海","description":"收官长海，最大海子，雪山倒影。","addr":"九寨沟则查洼沟","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糌粑后集合返程，三日旅程圆满。","addr":"树正寨","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"五花海","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"五花海是九寨沟最有代表性的看点，九寨精华，孔雀河道顺光最美。攻略把它排进主线，时间留得最足。","notice":"九寨精华，孔雀河道顺光最美。这个点位上午光线最好。","durationMinutes":120,"addr":"九寨沟县漳扎镇"},{"spotId":"S2","name":"诺日朗瀑布","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"诺日朗瀑布是九寨沟最有代表性的看点，中国最宽钙华瀑布。攻略把它排进主线，时间留得最足。","notice":"中国最宽钙华瀑布。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"九寨沟中心站"},{"spotId":"S3","name":"长海","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"长海是九寨沟最有代表性的看点，最大海子，雪山倒影。攻略把它排进主线，时间留得最足。","notice":"最大海子，雪山倒影。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"九寨沟则查洼沟"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"牦牛肉汤锅（人均78元）","description":"阿坝 · 九寨沟的招牌是牦牛肉汤锅，沟口藏家本地人都认这家，点单照攻略不踩雷。","addr":"漳扎镇"},{"title":"青稞酒（人均30元）","description":"阿坝 · 九寨沟的招牌是青稞酒，藏家体验本地人都认这家，点单照攻略不踩雷。","addr":"藏寨"},{"title":"糌粑（人均20元）","description":"阿坝 · 九寨沟的招牌是糌粑，藏族人家本地人都认这家，点单照攻略不踩雷。","addr":"树正寨"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":47205,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["防晒霜与遮阳帽","身份证件与手机充电宝","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","墨镜与拍照道具","少量零食补给","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 阿坝 的交通方便吗？","推荐先到 阿坝，再打车或景区直通车前往核心景区；自驾导航直接搜九寨沟即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('荔波小七孔秘境三日','cross','黔南 · 荔波小七孔','water','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',87000,47800,2,'小七孔古桥 / 卧龙潭 / 大七孔 —— 一张票打包荔波小七孔精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「荔波小七孔」三日深度游——水景。荔波青梅制品酸甜开胃。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黔南，抵达后办理入住、熟悉周边环境。","addr":"黔南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"小七孔古桥","description":"下午首站小七孔古桥，调整状态进入旅行节奏，68级跌水瀑布起点，绿宝石湖水。","addr":"荔波县小七孔镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黔南一带氛围拉满，晚餐酸汤鱼人均68元。","addr":"荔波县城","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"卧龙潭","description":"全天主景点卧龙潭，蓝到不真实的深潭，漂流出片。","addr":"小七孔景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐杨梅汤（人均10元），早点休息。","addr":"小七孔镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"大七孔","description":"收官大七孔，天生桥鬼斧神工。","addr":"荔波县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糯米排骨后集合返程，三日旅程圆满。","addr":"景区出口","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"小七孔古桥","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"小七孔古桥是荔波小七孔最有代表性的看点，68级跌水瀑布起点，绿宝石湖水。攻略把它排进主线，时间留得最足。","notice":"68级跌水瀑布起点，绿宝石湖水。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"荔波县小七孔镇"},{"spotId":"S2","name":"卧龙潭","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"卧龙潭是荔波小七孔最有代表性的看点，蓝到不真实的深潭，漂流出片。攻略把它排进主线，时间留得最足。","notice":"蓝到不真实的深潭，漂流出片。这个点位上午光线最好。","durationMinutes":120,"addr":"小七孔景区"},{"spotId":"S3","name":"大七孔","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"大七孔是荔波小七孔最有代表性的看点，天生桥鬼斧神工。攻略把它排进主线，时间留得最足。","notice":"天生桥鬼斧神工。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"荔波县"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均68元）","description":"黔南 · 荔波小七孔的招牌是酸汤鱼，凯里酸汤鱼本地人都认这家，点单照攻略不踩雷。","addr":"荔波县城"},{"title":"杨梅汤（人均10元）","description":"黔南 · 荔波小七孔的招牌是杨梅汤，街边饮品本地人都认这家，点单照攻略不踩雷。","addr":"小七孔镇"},{"title":"糯米排骨（人均42元）","description":"黔南 · 荔波小七孔的招牌是糯米排骨，布依农家本地人都认这家，点单照攻略不踩雷。","addr":"景区出口"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":39150,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","保温水杯与少量现金","相机或运动相机","舒适徒步鞋（防滑鞋底）","少量零食补给","常用药品（肠胃药/创可贴）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 黔南 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 黔南，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 黔南 的交通方便吗？","推荐先到 黔南，再打车或景区直通车前往核心景区；自驾导航直接搜荔波小七孔即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('涠洲岛跨省三日','cross','北海 · 涠洲岛','sea','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',104900,57600,6,'鳄鱼山火山公园 / 五彩滩 / 滴水丹屏 —— 一张票打包涠洲岛精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「涠洲岛」三日深度游——海滨。涠洲岛香蕉又软又甜。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 北海"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往北海，抵达后办理入住、熟悉周边环境。","addr":"北海市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"鳄鱼山火山公园","description":"下午首站鳄鱼山火山公园，调整状态进入旅行节奏，火山地质地貌，灯塔海景。","addr":"涠洲岛南湾","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游北海一带氛围拉满，晚餐海鲜大餐人均98元。","addr":"南湾街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"五彩滩","description":"全天主景点五彩滩，退潮时火山岩纹理最美。","addr":"涠洲岛东岸","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐香蕉猪（人均58元），早点休息。","addr":"滴水村","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"滴水丹屏","description":"收官滴水丹屏，日落圣地，海水退潮捡贝壳。","addr":"涠洲岛西侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐椰子冻后集合返程，三日旅程圆满。","addr":"南湾夜市","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"鳄鱼山火山公园","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"鳄鱼山火山公园是涠洲岛最有代表性的看点，火山地质地貌，灯塔海景。攻略把它排进主线，时间留得最足。","notice":"火山地质地貌，灯塔海景。这个点位上午光线最好。","durationMinutes":180,"addr":"涠洲岛南湾"},{"spotId":"S2","name":"五彩滩","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"五彩滩是涠洲岛最有代表性的看点，退潮时火山岩纹理最美。攻略把它排进主线，时间留得最足。","notice":"退潮时火山岩纹理最美。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"涠洲岛东岸"},{"spotId":"S3","name":"滴水丹屏","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"滴水丹屏是涠洲岛最有代表性的看点，日落圣地，海水退潮捡贝壳。攻略把它排进主线，时间留得最足。","notice":"日落圣地，海水退潮捡贝壳。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"涠洲岛西侧"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜大餐（人均98元）","description":"北海 · 涠洲岛的招牌是海鲜大餐，南湾海鲜市场加工本地人都认这家，点单照攻略不踩雷。","addr":"南湾街"},{"title":"香蕉猪（人均58元）","description":"北海 · 涠洲岛的招牌是香蕉猪，岛民农家本地人都认这家，点单照攻略不踩雷。","addr":"滴水村"},{"title":"椰子冻（人均15元）","description":"北海 · 涠洲岛的招牌是椰子冻，夜市摊本地人都认这家，点单照攻略不踩雷。","addr":"南湾夜市"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":47205,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","墨镜与拍照道具","防晒霜与遮阳帽","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","保温水杯与少量现金","相机或运动相机","少量零食补给"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意"],"faqs":[["当地有什么必吃？","到了 北海，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 北海 的交通方便吗？","推荐先到 北海，再打车或景区直通车前往核心景区；自驾导航直接搜涠洲岛即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('西湖灵隐限定冒险三日','cross','杭州 · 西湖灵隐','water','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',87600,48100,2,'西湖断桥苏堤 / 灵隐寺飞来峰 / 龙井村 —— 一张票打包西湖灵隐精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「西湖灵隐」三日深度游——水景。明前龙井茶农直购最划算。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 杭州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往杭州，抵达后办理入住、熟悉周边环境。","addr":"杭州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"西湖断桥苏堤","description":"下午首站西湖断桥苏堤，调整状态进入旅行节奏，清晨环湖骑行，断桥残雪碑打卡。","addr":"杭州市西湖区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游杭州一带氛围拉满，晚餐西湖醋鱼人均98元。","addr":"孤山路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"灵隐寺飞来峰","description":"全天主景点灵隐寺飞来峰，石窟造像与古刹，香火鼎盛。","addr":"西湖区灵隐路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐龙井虾仁（人均58元），早点休息。","addr":"西湖天地","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"龙井村","description":"收官龙井村，茶山徒步至九溪十八涧。","addr":"西湖区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐片儿川后集合返程，三日旅程圆满。","addr":"中山中路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"西湖断桥苏堤","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"西湖断桥苏堤是西湖灵隐最有代表性的看点，清晨环湖骑行，断桥残雪碑打卡。攻略把它排进主线，时间留得最足。","notice":"清晨环湖骑行，断桥残雪碑打卡。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"杭州市西湖区"},{"spotId":"S2","name":"灵隐寺飞来峰","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"灵隐寺飞来峰是西湖灵隐最有代表性的看点，石窟造像与古刹，香火鼎盛。攻略把它排进主线，时间留得最足。","notice":"石窟造像与古刹，香火鼎盛。这个点位上午光线最好。","durationMinutes":150,"addr":"西湖区灵隐路"},{"spotId":"S3","name":"龙井村","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"龙井村是西湖灵隐最有代表性的看点，茶山徒步至九溪十八涧。攻略把它排进主线，时间留得最足。","notice":"茶山徒步至九溪十八涧。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"西湖区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"西湖醋鱼（人均98元）","description":"杭州 · 西湖灵隐的招牌是西湖醋鱼，楼外楼本地人都认这家，点单照攻略不踩雷。","addr":"孤山路"},{"title":"龙井虾仁（人均58元）","description":"杭州 · 西湖灵隐的招牌是龙井虾仁，绿茶餐厅本地人都认这家，点单照攻略不踩雷。","addr":"西湖天地"},{"title":"片儿川（人均25元）","description":"杭州 · 西湖灵隐的招牌是片儿川，菊英面馆本地人都认这家，点单照攻略不踩雷。","addr":"中山中路"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":39420,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","相机或运动相机","墨镜与拍照道具","轻便雨衣或折叠伞","少量零食补给","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('夫子庙中山陵经典环线三日','cross','南京 · 夫子庙中山陵','red','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',88100,48400,7,'中山陵 / 夫子庙秦淮河 / 明孝陵石象路 —— 一张票打包夫子庙中山陵精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「夫子庙中山陵」三日深度游——人文。南京雨花石送小朋友最爱。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 南京"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往南京，抵达后办理入住、熟悉周边环境。","addr":"南京市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"中山陵","description":"下午首站中山陵，调整状态进入旅行节奏，392级台阶，民国气势。","addr":"南京市玄武区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游南京一带氛围拉满，晚餐盐水鸭人均45元。","addr":"夫子庙","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"夫子庙秦淮河","description":"全天主景点夫子庙秦淮河，夜泊秦淮，画舫灯影。","addr":"秦淮区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐鸭血粉丝汤（人均18元），早点休息。","addr":"老门东","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"明孝陵石象路","description":"收官明孝陵石象路，秋日梧桐大道封神。","addr":"玄武区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐汤包后集合返程，三日旅程圆满。","addr":"科巷","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"中山陵","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"中山陵是夫子庙中山陵最有代表性的看点，392级台阶，民国气势。攻略把它排进主线，时间留得最足。","notice":"392级台阶，民国气势。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"南京市玄武区"},{"spotId":"S2","name":"夫子庙秦淮河","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"夫子庙秦淮河是夫子庙中山陵最有代表性的看点，夜泊秦淮，画舫灯影。攻略把它排进主线，时间留得最足。","notice":"夜泊秦淮，画舫灯影。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"秦淮区"},{"spotId":"S3","name":"明孝陵石象路","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"明孝陵石象路是夫子庙中山陵最有代表性的看点，秋日梧桐大道封神。攻略把它排进主线，时间留得最足。","notice":"秋日梧桐大道封神。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"玄武区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"盐水鸭（人均45元）","description":"南京 · 夫子庙中山陵的招牌是盐水鸭，桂花鸭专卖店本地人都认这家，点单照攻略不踩雷。","addr":"夫子庙"},{"title":"鸭血粉丝汤（人均18元）","description":"南京 · 夫子庙中山陵的招牌是鸭血粉丝汤，回味本地人都认这家，点单照攻略不踩雷。","addr":"老门东"},{"title":"汤包（人均22元）","description":"南京 · 夫子庙中山陵的招牌是汤包，鸡鸣汤包本地人都认这家，点单照攻略不踩雷。","addr":"科巷"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":39645,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","墨镜与拍照道具","身份证件与手机充电宝","保温水杯与少量现金","换洗衣物与外套（早晚温差）","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["几月份去 南京 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('武当山深度三日','cross','十堰 · 武当山','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',102300,56200,2,'金顶 / 南岩宫 / 紫霄宫 —— 一张票打包武当山精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「武当山」三日深度游——山岳。武当道茶甘醇。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 十堰"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往十堰，抵达后办理入住、熟悉周边环境。","addr":"十堰市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"金顶","description":"下午首站金顶，调整状态进入旅行节奏，武当之巅金殿，转运台。","addr":"十堰市丹江口","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游十堰一带氛围拉满，晚餐道家素斋人均48元。","addr":"武当山镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"南岩宫","description":"全天主景点南岩宫，龙头香悬崖奇观。","addr":"武当山南岩","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐武当冻豆腐（人均38元），早点休息。","addr":"南岩","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"紫霄宫","description":"收官紫霄宫，皇家道观规制。","addr":"武当山展旗峰","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐太极养生汤后集合返程，三日旅程圆满。","addr":"紫霄宫旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"金顶","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"金顶是武当山最有代表性的看点，武当之巅金殿，转运台。攻略把它排进主线，时间留得最足。","notice":"武当之巅金殿，转运台。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"十堰市丹江口"},{"spotId":"S2","name":"南岩宫","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"南岩宫是武当山最有代表性的看点，龙头香悬崖奇观。攻略把它排进主线，时间留得最足。","notice":"龙头香悬崖奇观。这个点位上午光线最好。","durationMinutes":120,"addr":"武当山南岩"},{"spotId":"S3","name":"紫霄宫","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"紫霄宫是武当山最有代表性的看点，皇家道观规制。攻略把它排进主线，时间留得最足。","notice":"皇家道观规制。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"武当山展旗峰"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"道家素斋（人均48元）","description":"十堰 · 武当山的招牌是道家素斋，太子坡素斋本地人都认这家，点单照攻略不踩雷。","addr":"武当山镇"},{"title":"武当冻豆腐（人均38元）","description":"十堰 · 武当山的招牌是武当冻豆腐，山间餐馆本地人都认这家，点单照攻略不踩雷。","addr":"南岩"},{"title":"太极养生汤（人均68元）","description":"十堰 · 武当山的招牌是太极养生汤，道医药膳本地人都认这家，点单照攻略不踩雷。","addr":"紫霄宫旁"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":46035,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","相机或运动相机","墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 十堰，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 十堰 的交通方便吗？","推荐先到 十堰，再打车或景区直通车前往核心景区；自驾导航直接搜武当山即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('兵马俑城墙精华三日','cross','西安 · 兵马俑城墙','red','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',99900,54900,7,'秦始皇兵马俑 / 西安城墙 / 大唐不夜城 —— 一张票打包兵马俑城墙精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「兵马俑城墙」三日深度游——人文。兵马俑文创手办很火。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"陕西 · 西安"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往西安，抵达后办理入住、熟悉周边环境。","addr":"西安市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"秦始皇兵马俑","description":"下午首站秦始皇兵马俑，调整状态进入旅行节奏，一号坑震撼，讲解必请。","addr":"西安市临潼区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游西安一带氛围拉满，晚餐肉夹馍人均15元。","addr":"临潼区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西安城墙","description":"全天主景点西安城墙，骑行环城14公里，日落最美。","addr":"碑林区南门","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐biangbiang面（人均22元），早点休息。","addr":"南院门","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"大唐不夜城","description":"收官大唐不夜城，不倒翁小姐姐与灯光夜市。","addr":"雁塔区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐羊肉泡馍后集合返程，三日旅程圆满。","addr":"东关正街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"秦始皇兵马俑","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"秦始皇兵马俑是兵马俑城墙最有代表性的看点，一号坑震撼，讲解必请。攻略把它排进主线，时间留得最足。","notice":"一号坑震撼，讲解必请。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"西安市临潼区"},{"spotId":"S2","name":"西安城墙","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"西安城墙是兵马俑城墙最有代表性的看点，骑行环城14公里，日落最美。攻略把它排进主线，时间留得最足。","notice":"骑行环城14公里，日落最美。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"碑林区南门"},{"spotId":"S3","name":"大唐不夜城","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"大唐不夜城是兵马俑城墙最有代表性的看点，不倒翁小姐姐与灯光夜市。攻略把它排进主线，时间留得最足。","notice":"不倒翁小姐姐与灯光夜市。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"雁塔区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"肉夹馍（人均15元）","description":"西安 · 兵马俑城墙的招牌是肉夹馍，子午路张记本地人都认这家，点单照攻略不踩雷。","addr":"临潼区"},{"title":"biangbiang面（人均22元）","description":"西安 · 兵马俑城墙的招牌是biangbiang面，老碗会本地人都认这家，点单照攻略不踩雷。","addr":"南院门"},{"title":"羊肉泡馍（人均45元）","description":"西安 · 兵马俑城墙的招牌是羊肉泡馍，老孙家本地人都认这家，点单照攻略不踩雷。","addr":"东关正街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44955,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","保温水杯与少量现金","相机或运动相机","墨镜与拍照道具","防晒霜与遮阳帽","少量零食补给"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["到达 西安 的交通方便吗？","推荐先到 西安，再打车或景区直通车前往核心景区；自驾导航直接搜兵马俑城墙即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('栈桥崂山山河三日','cross','青岛 · 栈桥崂山','sea','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',83000,45600,6,'栈桥 / 崂山仰口 / 八大关 —— 一张票打包栈桥崂山精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「栈桥崂山」三日深度游——海滨。青岛啤酒原浆当天最新鲜。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"山东 · 青岛"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往青岛，抵达后办理入住、熟悉周边环境。","addr":"青岛市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"栈桥","description":"下午首站栈桥，调整状态进入旅行节奏，回澜阁海鸥季，夜色灯光。","addr":"青岛市市南区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游青岛一带氛围拉满，晚餐海鲜水饺人均58元。","addr":"闽江路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"崂山仰口","description":"全天主景点崂山仰口，海上第一名山，觅天洞。","addr":"崂山区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐野馄饨（人均15元），早点休息。","addr":"登州路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"八大关","description":"收官八大关，万国建筑与梧桐，秋天最美。","addr":"市南区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐崂山菇炖鸡后集合返程，三日旅程圆满。","addr":"仰口湾","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"栈桥","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"栈桥是栈桥崂山最有代表性的看点，回澜阁海鸥季，夜色灯光。攻略把它排进主线，时间留得最足。","notice":"回澜阁海鸥季，夜色灯光。这个点位上午光线最好。","durationMinutes":60,"addr":"青岛市市南区"},{"spotId":"S2","name":"崂山仰口","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"崂山仰口是栈桥崂山最有代表性的看点，海上第一名山，觅天洞。攻略把它排进主线，时间留得最足。","notice":"海上第一名山，觅天洞。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"崂山区"},{"spotId":"S3","name":"八大关","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"八大关是栈桥崂山最有代表性的看点，万国建筑与梧桐，秋天最美。攻略把它排进主线，时间留得最足。","notice":"万国建筑与梧桐，秋天最美。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"市南区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"海鲜水饺（人均58元）","description":"青岛 · 栈桥崂山的招牌是海鲜水饺，船歌鱼水饺本地人都认这家，点单照攻略不踩雷。","addr":"闽江路"},{"title":"野馄饨（人均15元）","description":"青岛 · 栈桥崂山的招牌是野馄饨，夜市馄饨摊本地人都认这家，点单照攻略不踩雷。","addr":"登州路"},{"title":"崂山菇炖鸡（人均68元）","description":"青岛 · 栈桥崂山的招牌是崂山菇炖鸡，山海农家本地人都认这家，点单照攻略不踩雷。","addr":"仰口湾"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":37350,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","保温水杯与少量现金","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","相机或运动相机","常用药品（肠胃药/创可贴）","少量零食补给","轻便雨衣或折叠伞"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","看好同行老人小孩，走失原地等待"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 青岛，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'远方的炊烟，是写给旅人的信。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('七星岩全景三日','cross','肇庆 · 七星岩','water','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',100100,55000,2,'七星岩 / 鼎湖山 / 紫云谷 —— 一张票打包七星岩精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「七星岩」三日深度游——水景。端砚四大名砚之首。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 肇庆"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往肇庆，抵达后办理入住、熟悉周边环境。","addr":"肇庆市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"七星岩","description":"下午首站七星岩，调整状态进入旅行节奏，岭南第一奇观，湖山相映。","addr":"肇庆市端州区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游肇庆一带氛围拉满，晚餐裹蒸粽人均15元。","addr":"端州区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"鼎湖山","description":"全天主景点鼎湖山，北回归线上的绿宝石，庆云寺。","addr":"鼎湖区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐文庆鲤（人均68元），早点休息。","addr":"鼎湖区","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"紫云谷","description":"收官紫云谷，端砚石产地，溪水清凉。","addr":"羚羊峡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐茶油鸡后集合返程，三日旅程圆满。","addr":"七星岩东门","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"七星岩","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"七星岩是七星岩最有代表性的看点，岭南第一奇观，湖山相映。攻略把它排进主线，时间留得最足。","notice":"岭南第一奇观，湖山相映。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"肇庆市端州区"},{"spotId":"S2","name":"鼎湖山","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"鼎湖山是七星岩最有代表性的看点，北回归线上的绿宝石，庆云寺。攻略把它排进主线，时间留得最足。","notice":"北回归线上的绿宝石，庆云寺。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"鼎湖区"},{"spotId":"S3","name":"紫云谷","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"紫云谷是七星岩最有代表性的看点，端砚石产地，溪水清凉。攻略把它排进主线，时间留得最足。","notice":"端砚石产地，溪水清凉。这个点位上午光线最好。","durationMinutes":120,"addr":"羚羊峡"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"裹蒸粽（人均15元）","description":"肇庆 · 七星岩的招牌是裹蒸粽，皇中皇本地人都认这家，点单照攻略不踩雷。","addr":"端州区"},{"title":"文庆鲤（人均68元）","description":"肇庆 · 七星岩的招牌是文庆鲤，文庆鲤餐馆本地人都认这家，点单照攻略不踩雷。","addr":"鼎湖区"},{"title":"茶油鸡（人均48元）","description":"肇庆 · 七星岩的招牌是茶油鸡，农家菜馆本地人都认这家，点单照攻略不踩雷。","addr":"七星岩东门"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":45045,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","保温水杯与少量现金","防晒霜与遮阳帽","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 肇庆 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('青海湖茶卡秘境三日','cross','海南州 · 青海湖茶卡','plateau','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',88100,48400,2,'二郎剑景区 / 茶卡盐湖 / 日月山 —— 一张票打包青海湖茶卡精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「青海湖茶卡」三日深度游——高原。青海湖黄蘑菇炖汤鲜。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"青海 · 海南州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往海南州，抵达后办理入住、熟悉周边环境。","addr":"海南州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"二郎剑景区","description":"下午首站二郎剑景区，调整状态进入旅行节奏，油菜花与蓝湖，骑行湖岸。","addr":"共和县青海湖南岸","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游海南州一带氛围拉满，晚餐老酸奶人均10元。","addr":"环湖公路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"茶卡盐湖","description":"全天主景点茶卡盐湖，天空之镜，赤脚下盐滩。","addr":"乌兰县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐羊肉汤（人均35元），早点休息。","addr":"黑马河乡","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"日月山","description":"收官日月山，文成公主进藏口，倒淌河。","addr":"湟源县","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糌粑后集合返程，三日旅程圆满。","addr":"茶卡镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"二郎剑景区","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"二郎剑景区是青海湖茶卡最有代表性的看点，油菜花与蓝湖，骑行湖岸。攻略把它排进主线，时间留得最足。","notice":"油菜花与蓝湖，骑行湖岸。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"共和县青海湖南岸"},{"spotId":"S2","name":"茶卡盐湖","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"茶卡盐湖是青海湖茶卡最有代表性的看点，天空之镜，赤脚下盐滩。攻略把它排进主线，时间留得最足。","notice":"天空之镜，赤脚下盐滩。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"乌兰县"},{"spotId":"S3","name":"日月山","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"日月山是青海湖茶卡最有代表性的看点，文成公主进藏口，倒淌河。攻略把它排进主线，时间留得最足。","notice":"文成公主进藏口，倒淌河。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"湟源县"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"老酸奶（人均10元）","description":"海南州 · 青海湖茶卡的招牌是老酸奶，青海老酸奶本地人都认这家，点单照攻略不踩雷。","addr":"环湖公路"},{"title":"羊肉汤（人均35元）","description":"海南州 · 青海湖茶卡的招牌是羊肉汤，藏家羊汤本地人都认这家，点单照攻略不踩雷。","addr":"黑马河乡"},{"title":"糌粑（人均20元）","description":"海南州 · 青海湖茶卡的招牌是糌粑，牧民家访本地人都认这家，点单照攻略不踩雷。","addr":"茶卡镇"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":39645,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","轻便雨衣或折叠伞","防晒霜与遮阳帽","少量零食补给","相机或运动相机","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待"],"faqs":[["到达 海南州 的交通方便吗？","推荐先到 海南州，再打车或景区直通车前往核心景区；自驾导航直接搜青海湖茶卡即可。"],["几月份去 海南州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('呼伦贝尔草原跨省三日','cross','呼伦贝尔 · 呼伦贝尔草原','village','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',85300,46900,1,'莫日格勒河 / 额尔古纳湿地 / 恩和俄罗斯族乡 —— 一张票打包呼伦贝尔草原精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「呼伦贝尔草原」三日深度游——古村落。呼伦贝尔风干牛肉原味香。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"内蒙古 · 呼伦贝尔"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往呼伦贝尔，抵达后办理入住、熟悉周边环境。","addr":"呼伦贝尔市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"莫日格勒河","description":"下午首站莫日格勒河，调整状态进入旅行节奏，天下第一曲水，断崖机位。","addr":"陈巴尔虎旗","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游呼伦贝尔一带氛围拉满，晚餐烤羊腿人均128元。","addr":"黑山头镇","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"额尔古纳湿地","description":"全天主景点额尔古纳湿地，亚洲第一湿地，日落金色。","addr":"额尔古纳市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐蒙古锅茶（人均35元），早点休息。","addr":"陈巴尔虎旗","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"恩和俄罗斯族乡","description":"收官恩和俄罗斯族乡，木刻楞小屋与列巴。","addr":"额尔古纳市","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐俄罗斯列巴后集合返程，三日旅程圆满。","addr":"恩和乡","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"莫日格勒河","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"莫日格勒河是呼伦贝尔草原最有代表性的看点，天下第一曲水，断崖机位。攻略把它排进主线，时间留得最足。","notice":"天下第一曲水，断崖机位。这个点位上午光线最好。","durationMinutes":120,"addr":"陈巴尔虎旗"},{"spotId":"S2","name":"额尔古纳湿地","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"额尔古纳湿地是呼伦贝尔草原最有代表性的看点，亚洲第一湿地，日落金色。攻略把它排进主线，时间留得最足。","notice":"亚洲第一湿地，日落金色。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"额尔古纳市"},{"spotId":"S3","name":"恩和俄罗斯族乡","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"恩和俄罗斯族乡是呼伦贝尔草原最有代表性的看点，木刻楞小屋与列巴。攻略把它排进主线，时间留得最足。","notice":"木刻楞小屋与列巴。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"额尔古纳市"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"烤羊腿（人均128元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是烤羊腿，草原牧民人家本地人都认这家，点单照攻略不踩雷。","addr":"黑山头镇"},{"title":"蒙古锅茶（人均35元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是蒙古锅茶，牧户家访本地人都认这家，点单照攻略不踩雷。","addr":"陈巴尔虎旗"},{"title":"俄罗斯列巴（人均15元）","description":"呼伦贝尔 · 呼伦贝尔草原的招牌是俄罗斯列巴，恩和列巴坊本地人都认这家，点单照攻略不踩雷。","addr":"恩和乡"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":38385,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","少量零食补给","墨镜与拍照道具","换洗衣物与外套（早晚温差）","保温水杯与少量现金","轻便雨衣或折叠伞","相机或运动相机"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 呼伦贝尔，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('婺源篁岭限定冒险三日','cross','上饶 · 婺源篁岭','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',99900,54900,1,'晒秋人家 / 垒心桥 / 梯田花海 —— 一张票打包婺源篁岭精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「婺源篁岭」三日深度游——古村落。婺源荷包红鲤鱼可真空打包带回家。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往上饶，抵达后办理入住、熟悉周边环境。","addr":"上饶市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"晒秋人家","description":"下午首站晒秋人家，调整状态进入旅行节奏，晒秋最佳拍摄位在天街中层，上午顺光。","addr":"婺源县江湾镇篁岭村","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游上饶一带氛围拉满，晚餐蒸汽糕人均28元。","addr":"篁岭天街中段","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"垒心桥","description":"全天主景点垒心桥，桥面风大，手机拿稳。","addr":"篁岭景区索道上站","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐清明果（人均15元），早点休息。","addr":"篁岭古村巷内","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"梯田花海","description":"收官梯田花海，春季油菜花、秋季稻浪，两季都出片。","addr":"篁岭村北坡","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐荷包红鲤鱼后集合返程，三日旅程圆满。","addr":"篁岭村口第一家","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"晒秋人家","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"晒秋人家是婺源篁岭最有代表性的看点，晒秋最佳拍摄位在天街中层，上午顺光。攻略把它排进主线，时间留得最足。","notice":"晒秋最佳拍摄位在天街中层，上午顺光。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"婺源县江湾镇篁岭村"},{"spotId":"S2","name":"垒心桥","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"垒心桥是婺源篁岭最有代表性的看点，桥面风大，手机拿稳。攻略把它排进主线，时间留得最足。","notice":"桥面风大，手机拿稳。周边有休息区与补给点，随时停留。","durationMinutes":60,"addr":"篁岭景区索道上站"},{"spotId":"S3","name":"梯田花海","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"梯田花海是婺源篁岭最有代表性的看点，春季油菜花、秋季稻浪，两季都出片。攻略把它排进主线，时间留得最足。","notice":"春季油菜花、秋季稻浪，两季都出片。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"篁岭村北坡"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蒸汽糕（人均28元）","description":"上饶 · 婺源篁岭的招牌是蒸汽糕，天街食府本地人都认这家，点单照攻略不踩雷。","addr":"篁岭天街中段"},{"title":"清明果（人均15元）","description":"上饶 · 婺源篁岭的招牌是清明果，晒秋人家小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"篁岭古村巷内"},{"title":"荷包红鲤鱼（人均68元）","description":"上饶 · 婺源篁岭的招牌是荷包红鲤鱼，篁岭酒楼本地人都认这家，点单照攻略不踩雷。","addr":"篁岭村口第一家"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44955,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","墨镜与拍照道具","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","身份证件与手机充电宝"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["到达 上饶 的交通方便吗？","推荐先到 上饶，再打车或景区直通车前往核心景区；自驾导航直接搜婺源篁岭即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 上饶 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('陶溪川经典环线三日','cross','景德镇 · 陶溪川','art','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',84300,46300,5,'陶溪川文创街区 / 古窑民俗博览区 / 雕塑瓷厂乐天市集 —— 一张票打包陶溪川精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「陶溪川」三日深度游——文艺。景德镇薄胎瓷碗轻巧又体面。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 景德镇"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往景德镇，抵达后办理入住、熟悉周边环境。","addr":"景德镇市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"陶溪川文创街区","description":"下午首站陶溪川文创街区，调整状态进入旅行节奏，夜市周五六日开，手作摊最好逛。","addr":"珠山区新厂西路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游景德镇一带氛围拉满，晚餐饺子粑人均15元。","addr":"中山北路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"古窑民俗博览区","description":"全天主景点古窑民俗博览区，看柴窑镇窑复烧，拉坯体验要排队。","addr":"昌江区枫树山蟠龙岗","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐冷粉（人均12元），早点休息。","addr":"人民广场附近","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"雕塑瓷厂乐天市集","description":"收官雕塑瓷厂乐天市集，周六上午开市，淘手作好物。","addr":"新厂东路139号","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐碱水粑炒鸡蛋后集合返程，三日旅程圆满。","addr":"陶溪川周边小馆","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"陶溪川文创街区","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"陶溪川文创街区是陶溪川最有代表性的看点，夜市周五六日开，手作摊最好逛。攻略把它排进主线，时间留得最足。","notice":"夜市周五六日开，手作摊最好逛。周边有休息区与补给点，随时停留。","durationMinutes":150,"addr":"珠山区新厂西路"},{"spotId":"S2","name":"古窑民俗博览区","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"古窑民俗博览区是陶溪川最有代表性的看点，看柴窑镇窑复烧，拉坯体验要排队。攻略把它排进主线，时间留得最足。","notice":"看柴窑镇窑复烧，拉坯体验要排队。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"昌江区枫树山蟠龙岗"},{"spotId":"S3","name":"雕塑瓷厂乐天市集","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"雕塑瓷厂乐天市集是陶溪川最有代表性的看点，周六上午开市，淘手作好物。攻略把它排进主线，时间留得最足。","notice":"周六上午开市，淘手作好物。这个点位上午光线最好。","durationMinutes":90,"addr":"新厂东路139号"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"饺子粑（人均15元）","description":"景德镇 · 陶溪川的招牌是饺子粑，老字号小吃店本地人都认这家，点单照攻略不踩雷。","addr":"中山北路"},{"title":"冷粉（人均12元）","description":"景德镇 · 陶溪川的招牌是冷粉，景德镇冷粉店本地人都认这家，点单照攻略不踩雷。","addr":"人民广场附近"},{"title":"碱水粑炒鸡蛋（人均28元）","description":"景德镇 · 陶溪川的招牌是碱水粑炒鸡蛋，瓷都家常菜本地人都认这家，点单照攻略不踩雷。","addr":"陶溪川周边小馆"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":37935,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","保温水杯与少量现金"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["饮食注意卫生，海鲜过敏提前告知店家","看好同行老人小孩，走失原地等待","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["到达 景德镇 的交通方便吗？","推荐先到 景德镇，再打车或景区直通车前往核心景区；自驾导航直接搜陶溪川即可。"],["几月份去 景德镇 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳麓山橘子洲深度三日','cross','长沙 · 岳麓山橘子洲','mountain','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',99800,54800,2,'岳麓山 / 橘子洲头 / 太平老街 —— 一张票打包岳麓山橘子洲精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「岳麓山橘子洲」三日深度游——山岳。长沙湘绣摆件精致好带。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 长沙"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往长沙，抵达后办理入住、熟悉周边环境。","addr":"长沙市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"岳麓山","description":"下午首站岳麓山，调整状态进入旅行节奏，爱晚亭秋色最美，索道下山省力。","addr":"长沙市岳麓区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游长沙一带氛围拉满，晚餐茶颜悦色人均18元。","addr":"太平老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"橘子洲头","description":"全天主景点橘子洲头，青年毛泽东雕像打卡，小火车代步。","addr":"长沙市橘子洲景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐文和友臭豆腐（人均15元），早点休息。","addr":"海信广场","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"太平老街","description":"收官太平老街，臭豆腐与糖油粑粑的主场。","addr":"长沙市天心区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐糖油粑粑后集合返程，三日旅程圆满。","addr":"坡子街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"岳麓山","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"岳麓山是岳麓山橘子洲最有代表性的看点，爱晚亭秋色最美，索道下山省力。攻略把它排进主线，时间留得最足。","notice":"爱晚亭秋色最美，索道下山省力。这个点位上午光线最好。","durationMinutes":180,"addr":"长沙市岳麓区"},{"spotId":"S2","name":"橘子洲头","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"橘子洲头是岳麓山橘子洲最有代表性的看点，青年毛泽东雕像打卡，小火车代步。攻略把它排进主线，时间留得最足。","notice":"青年毛泽东雕像打卡，小火车代步。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"长沙市橘子洲景区"},{"spotId":"S3","name":"太平老街","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"太平老街是岳麓山橘子洲最有代表性的看点，臭豆腐与糖油粑粑的主场。攻略把它排进主线，时间留得最足。","notice":"臭豆腐与糖油粑粑的主场。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"长沙市天心区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"茶颜悦色（人均18元）","description":"长沙 · 岳麓山橘子洲的招牌是茶颜悦色，太平街店本地人都认这家，点单照攻略不踩雷。","addr":"太平老街"},{"title":"文和友臭豆腐（人均15元）","description":"长沙 · 岳麓山橘子洲的招牌是文和友臭豆腐，文和友本地人都认这家，点单照攻略不踩雷。","addr":"海信广场"},{"title":"糖油粑粑（人均8元）","description":"长沙 · 岳麓山橘子洲的招牌是糖油粑粑，李公庙糖油粑粑本地人都认这家，点单照攻略不踩雷。","addr":"坡子街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44910,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","少量零食补给","保温水杯与少量现金","身份证件与手机充电宝","轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["当地有什么必吃？","到了 长沙，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丽江古城玉龙雪山精华三日','cross','丽江 · 丽江古城玉龙雪山','mountain','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',84600,46500,2,'玉龙雪山 / 蓝月谷 / 丽江古城 —— 一张票打包丽江古城玉龙雪山精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「丽江古城玉龙雪山」三日深度游——山岳。雪山玫瑰饼是最热手信。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 丽江"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往丽江，抵达后办理入住、熟悉周边环境。","addr":"丽江市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"玉龙雪山","description":"下午首站玉龙雪山，调整状态进入旅行节奏，大索道直达4506米，租羽绒服买氧气瓶。","addr":"丽江市玉龙县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游丽江一带氛围拉满，晚餐腊排骨火锅人均68元。","addr":"古城区象山街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"蓝月谷","description":"全天主景点蓝月谷，牛奶蓝湖水，电瓶车游三湖。","addr":"玉龙雪山脚下","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐鸡豆凉粉（人均10元），早点休息。","addr":"四方街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"丽江古城","description":"收官丽江古城，四方街打跳，狮子山看全景。","addr":"古城区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐丽江粑粑后集合返程，三日旅程圆满。","addr":"忠义市场内","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"玉龙雪山","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"玉龙雪山是丽江古城玉龙雪山最有代表性的看点，大索道直达4506米，租羽绒服买氧气瓶。攻略把它排进主线，时间留得最足。","notice":"大索道直达4506米，租羽绒服买氧气瓶。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"丽江市玉龙县"},{"spotId":"S2","name":"蓝月谷","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"蓝月谷是丽江古城玉龙雪山最有代表性的看点，牛奶蓝湖水，电瓶车游三湖。攻略把它排进主线，时间留得最足。","notice":"牛奶蓝湖水，电瓶车游三湖。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"玉龙雪山脚下"},{"spotId":"S3","name":"丽江古城","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"丽江古城是丽江古城玉龙雪山最有代表性的看点，四方街打跳，狮子山看全景。攻略把它排进主线，时间留得最足。","notice":"四方街打跳，狮子山看全景。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"古城区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"腊排骨火锅（人均68元）","description":"丽江 · 丽江古城玉龙雪山的招牌是腊排骨火锅，象山市场本地人都认这家，点单照攻略不踩雷。","addr":"古城区象山街"},{"title":"鸡豆凉粉（人均10元）","description":"丽江 · 丽江古城玉龙雪山的招牌是鸡豆凉粉，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"四方街"},{"title":"丽江粑粑（人均12元）","description":"丽江 · 丽江古城玉龙雪山的招牌是丽江粑粑，忠义市场本地人都认这家，点单照攻略不踩雷。","addr":"忠义市场内"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":38070,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","保温水杯与少量现金","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","防晒霜与遮阳帽","少量零食补给"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 丽江，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('稻城亚丁山河三日','cross','甘孜 · 稻城亚丁','plateau','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',98700,54200,2,'牛奶海 / 五色海 / 冲古寺草坪 —— 一张票打包稻城亚丁精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「稻城亚丁」三日深度游——高原。高原反应别逞强慢慢走。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 甘孜"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往甘孜，抵达后办理入住、熟悉周边环境。","addr":"甘孜市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"牛奶海","description":"下午首站牛奶海，调整状态进入旅行节奏，海拔4600，马帮或徒步，量力而行。","addr":"稻城县香格里拉镇","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游甘孜一带氛围拉满，晚餐松茸炖鸡人均128元。","addr":"亚丁村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"五色海","description":"全天主景点五色海，最后一百步最陡，景色值得。","addr":"牛奶海上方","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酥油茶（人均15元），早点休息。","addr":"香格里拉镇","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"冲古寺草坪","description":"收官冲古寺草坪，仙乃日倒影机位。","addr":"亚丁村","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐高原土豆后集合返程，三日旅程圆满。","addr":"洛绒牛场补给点","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"牛奶海","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"牛奶海是稻城亚丁最有代表性的看点，海拔4600，马帮或徒步，量力而行。攻略把它排进主线，时间留得最足。","notice":"海拔4600，马帮或徒步，量力而行。周边有休息区与补给点，随时