INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('瘦西湖限定冒险三日','cross','扬州 · 瘦西湖','water','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',98700,54200,2,'瘦西湖 / 个园 / 东关街 —— 一张票打包瘦西湖精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「瘦西湖」三日深度游——水景。扬州漆器螺钿最精美。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 扬州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往扬州，抵达后办理入住、熟悉周边环境。","addr":"扬州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"瘦西湖","description":"下午首站瘦西湖，调整状态进入旅行节奏，两堤花柳全依水，五亭桥白塔。","addr":"扬州市邗江区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游扬州一带氛围拉满，晚餐蟹粉狮子头人均68元。","addr":"念四路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"个园","description":"全天主景点个园，四季假山一园看尽。","addr":"东关街","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐扬州炒饭（人均28元），早点休息。","addr":"东关街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"东关街","description":"收官东关街，千年古街，夜色灯笼。","addr":"广陵区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐烫干丝后集合返程，三日旅程圆满。","addr":"得胜桥","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"瘦西湖","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"瘦西湖是瘦西湖最有代表性的看点，两堤花柳全依水，五亭桥白塔。攻略把它排进主线，时间留得最足。","notice":"两堤花柳全依水，五亭桥白塔。提前10分钟到，避开旅行团大部队。","durationMinutes":180,"addr":"扬州市邗江区"},{"spotId":"S2","name":"个园","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"个园是瘦西湖最有代表性的看点，四季假山一园看尽。攻略把它排进主线，时间留得最足。","notice":"四季假山一园看尽。这个点位上午光线最好。","durationMinutes":90,"addr":"东关街"},{"spotId":"S3","name":"东关街","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"东关街是瘦西湖最有代表性的看点，千年古街，夜色灯笼。攻略把它排进主线，时间留得最足。","notice":"千年古街，夜色灯笼。这个点位上午光线最好。","durationMinutes":120,"addr":"广陵区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蟹粉狮子头（人均68元）","description":"扬州 · 瘦西湖的招牌是蟹粉狮子头，食为天本地人都认这家，点单照攻略不踩雷。","addr":"念四路"},{"title":"扬州炒饭（人均28元）","description":"扬州 · 瘦西湖的招牌是扬州炒饭，老字号本地人都认这家，点单照攻略不踩雷。","addr":"东关街"},{"title":"烫干丝（人均22元）","description":"扬州 · 瘦西湖的招牌是烫干丝，富春茶社本地人都认这家，点单照攻略不踩雷。","addr":"得胜桥"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44415,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","保温水杯与少量现金","防晒霜与遮阳帽","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["几月份去 扬州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
