INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('太湖鼋头渚跨省三日','cross','无锡 · 太湖鼋头渚','water','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',97400,53500,2,'鼋头渚 / 灵山大佛 / 南长街 —— 一张票打包太湖鼋头渚精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「太湖鼋头渚」三日深度游——水景。惠山泥人阿福最喜庆。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 无锡"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往无锡，抵达后办理入住、熟悉周边环境。","addr":"无锡市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"鼋头渚","description":"下午首站鼋头渚，调整状态进入旅行节奏，太湖第一名胜，樱花季封神。","addr":"无锡市滨湖区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游无锡一带氛围拉满，晚餐无锡小笼人均22元。","addr":"南禅寺","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"灵山大佛","description":"全天主景点灵山大佛，88米大佛，梵宫震撼。","addr":"滨湖区马山","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐酱排骨（人均48元），早点休息。","addr":"中山路","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"南长街","description":"收官南长街，古运河夜色，清名桥倒影。","addr":"梁溪区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐太湖三白后集合返程，三日旅程圆满。","addr":"鼋头渚旁","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"鼋头渚","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"鼋头渚是太湖鼋头渚最有代表性的看点，太湖第一名胜，樱花季封神。攻略把它排进主线，时间留得最足。","notice":"太湖第一名胜，樱花季封神。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"无锡市滨湖区"},{"spotId":"S2","name":"灵山大佛","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"灵山大佛是太湖鼋头渚最有代表性的看点，88米大佛，梵宫震撼。攻略把它排进主线，时间留得最足。","notice":"88米大佛，梵宫震撼。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"滨湖区马山"},{"spotId":"S3","name":"南长街","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"南长街是太湖鼋头渚最有代表性的看点，古运河夜色，清名桥倒影。攻略把它排进主线，时间留得最足。","notice":"古运河夜色，清名桥倒影。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"梁溪区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"无锡小笼（人均22元）","description":"无锡 · 太湖鼋头渚的招牌是无锡小笼，熙盛源本地人都认这家，点单照攻略不踩雷。","addr":"南禅寺"},{"title":"酱排骨（人均48元）","description":"无锡 · 太湖鼋头渚的招牌是酱排骨，三凤桥本地人都认这家，点单照攻略不踩雷。","addr":"中山路"},{"title":"太湖三白（人均98元）","description":"无锡 · 太湖鼋头渚的招牌是太湖三白，渔人码头本地人都认这家，点单照攻略不踩雷。","addr":"鼋头渚旁"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":43830,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","少量零食补给","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽","保温水杯与少量现金","轻便雨衣或折叠伞","身份证件与手机充电宝"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["几月份去 无锡 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["当地有什么必吃？","到了 无锡，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('九宫山隐水洞限定冒险三日','cross','咸宁 · 九宫山隐水洞','mountain','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',88800,48800,2,'九宫山 / 隐水洞 / 刘家桥古民居 —— 一张票打包九宫山隐水洞精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「九宫山隐水洞」三日深度游——山岳。咸宁桂花蜜香甜。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 咸宁"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往咸宁，抵达后办理入住、熟悉周边环境。","addr":"咸宁市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"九宫山","description":"下午首站九宫山，调整状态进入旅行节奏，云中湖避暑胜地，闯王陵。","addr":"咸宁市通山县","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游咸宁一带氛围拉满，晚餐贺胜桥鸡汤人均58元。","addr":"咸安区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"隐水洞","description":"全天主景点隐水洞，水路旱路双游线溶洞。","addr":"通山县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐桂花糕（人均15元），早点休息。","addr":"温泉城区","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"刘家桥古民居","description":"收官刘家桥古民居，明清廊桥古民居。","addr":"咸安区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐通山合菜面后集合返程，三日旅程圆满。","addr":"通山县","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"九宫山","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"九宫山是九宫山隐水洞最有代表性的看点，云中湖避暑胜地，闯王陵。攻略把它排进主线，时间留得最足。","notice":"云中湖避暑胜地，闯王陵。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"咸宁市通山县"},{"spotId":"S2","name":"隐水洞","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"隐水洞是九宫山隐水洞最有代表性的看点，水路旱路双游线溶洞。攻略把它排进主线，时间留得最足。","notice":"水路旱路双游线溶洞。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"通山县"},{"spotId":"S3","name":"刘家桥古民居","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"刘家桥古民居是九宫山隐水洞最有代表性的看点，明清廊桥古民居。攻略把它排进主线，时间留得最足。","notice":"明清廊桥古民居。这个点位上午光线最好。","durationMinutes":90,"addr":"咸安区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"贺胜桥鸡汤（人均58元）","description":"咸宁 · 九宫山隐水洞的招牌是贺胜桥鸡汤，贺胜桥土鸡馆本地人都认这家，点单照攻略不踩雷。","addr":"咸安区"},{"title":"桂花糕（人均15元）","description":"咸宁 · 九宫山隐水洞的招牌是桂花糕，桂花之乡本地人都认这家，点单照攻略不踩雷。","addr":"温泉城区"},{"title":"通山合菜面（人均28元）","description":"咸宁 · 九宫山隐水洞的招牌是通山合菜面，通山农家本地人都认这家，点单照攻略不踩雷。","addr":"通山县"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":39960,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["少量零食补给","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","看好同行老人小孩，走失原地等待"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 咸宁 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'好运藏在出发的行囊里。','on');
