INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('镇远古镇精华三日','cross','黔东南 · 镇远古镇','ancient_town','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',101000,55500,1,'青龙洞 / 舞阳河 / 石屏山 —— 一张票打包镇远古镇精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「镇远古镇」三日深度游——古镇。镇远蓝染布艺越洗越好看。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约10000步","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 黔东南"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黔东南，抵达后办理入住、熟悉周边环境。","addr":"黔东南市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"青龙洞","description":"下午首站青龙洞，调整状态进入旅行节奏，贴崖古建筑群，对望古城。","addr":"镇远县中和山","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黔东南一带氛围拉满，晚餐酸汤鱼人均58元。","addr":"兴隆街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"舞阳河","description":"全天主景点舞阳河，乘船看孔雀开屏峰。","addr":"镇远县","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐陈年道菜（人均30元），早点休息。","addr":"古镇主街","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"石屏山","description":"收官石屏山，俯瞰太极古城全景。","addr":"古城北侧","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐苗家腊肉后集合返程，三日旅程圆满。","addr":"舞阳河畔","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"青龙洞","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"青龙洞是镇远古镇最有代表性的看点，贴崖古建筑群，对望古城。攻略把它排进主线，时间留得最足。","notice":"贴崖古建筑群，对望古城。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"镇远县中和山"},{"spotId":"S2","name":"舞阳河","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"舞阳河是镇远古镇最有代表性的看点，乘船看孔雀开屏峰。攻略把它排进主线，时间留得最足。","notice":"乘船看孔雀开屏峰。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"镇远县"},{"spotId":"S3","name":"石屏山","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"石屏山是镇远古镇最有代表性的看点，俯瞰太极古城全景。攻略把它排进主线，时间留得最足。","notice":"俯瞰太极古城全景。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"古城北侧"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"酸汤鱼（人均58元）","description":"黔东南 · 镇远古镇的招牌是酸汤鱼，古城酸汤馆本地人都认这家，点单照攻略不踩雷。","addr":"兴隆街"},{"title":"陈年道菜（人均30元）","description":"黔东南 · 镇远古镇的招牌是陈年道菜，老字号本地人都认这家，点单照攻略不踩雷。","addr":"古镇主街"},{"title":"苗家腊肉（人均48元）","description":"黔东南 · 镇远古镇的招牌是苗家腊肉，河畔农家本地人都认这家，点单照攻略不踩雷。","addr":"舞阳河畔"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":45450,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["相机或运动相机","保温水杯与少量现金","舒适徒步鞋（防滑鞋底）","少量零食补给","常用药品（肠胃药/创可贴）","墨镜与拍照道具","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["看好同行老人小孩，走失原地等待","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["几月份去 黔东南 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('鼓浪屿山河三日','cross','厦门 · 鼓浪屿','sea','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',103000,56600,6,'日光岩 / 菽庄花园 / 沙坡尾 —— 一张票打包鼓浪屿精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「鼓浪屿」三日深度游——海滨。厦门馅饼老字号最正宗。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约6000步，爬升平缓","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 厦门"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往厦门，抵达后办理入住、熟悉周边环境。","addr":"厦门市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"日光岩","description":"下午首站日光岩，调整状态进入旅行节奏，全岛最高点看红瓦绿树海景。","addr":"鼓浪屿龙头山路","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游厦门一带氛围拉满，晚餐沙茶面人均28元。","addr":"民族路","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"菽庄花园","description":"全天主景点菽庄花园，四十四桥跨海，钢琴博物馆。","addr":"鼓浪屿港仔后路","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐海蛎煎（人均25元），早点休息。","addr":"八市","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"沙坡尾","description":"收官沙坡尾，避风坞文艺街区，猫街涂鸦。","addr":"厦门市思明区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐土笋冻后集合返程，三日旅程圆满。","addr":"斗西路","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"日光岩","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"日光岩是鼓浪屿最有代表性的看点，全岛最高点看红瓦绿树海景。攻略把它排进主线，时间留得最足。","notice":"全岛最高点看红瓦绿树海景。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"鼓浪屿龙头山路"},{"spotId":"S2","name":"菽庄花园","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"菽庄花园是鼓浪屿最有代表性的看点，四十四桥跨海，钢琴博物馆。攻略把它排进主线，时间留得最足。","notice":"四十四桥跨海，钢琴博物馆。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"鼓浪屿港仔后路"},{"spotId":"S3","name":"沙坡尾","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"沙坡尾是鼓浪屿最有代表性的看点，避风坞文艺街区，猫街涂鸦。攻略把它排进主线，时间留得最足。","notice":"避风坞文艺街区，猫街涂鸦。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"厦门市思明区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"沙茶面（人均28元）","description":"厦门 · 鼓浪屿的招牌是沙茶面，乌糖沙茶面本地人都认这家，点单照攻略不踩雷。","addr":"民族路"},{"title":"海蛎煎（人均25元）","description":"厦门 · 鼓浪屿的招牌是海蛎煎，莲欢海蛎煎本地人都认这家，点单照攻略不踩雷。","addr":"八市"},{"title":"土笋冻（人均15元）","description":"厦门 · 鼓浪屿的招牌是土笋冻，西门土笋冻本地人都认这家，点单照攻略不踩雷。","addr":"斗西路"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":46350,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","墨镜与拍照道具","相机或运动相机","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","少量零食补给","常用药品（肠胃药/创可贴）"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["贵重物品随身携带，景区人多注意","高原地区避免剧烈运动，备好氧气瓶","涉水项目穿好救生衣，听从工作人员安排","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('雁荡山全景三日','cross','温州 · 雁荡山','mountain','https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80',99800,54800,2,'灵峰 / 大龙湫 / 方洞栈道 —— 一张票打包雁荡山精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「雁荡山」三日深度游——山岳。雁荡山铁皮石斛有名。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"浙江 · 温州"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往温州，抵达后办理入住、熟悉周边环境。","addr":"温州市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"灵峰","description":"下午首站灵峰，调整状态进入旅行节奏，日景夜景两相宜，夫妻峰剪影。","addr":"乐清市雁荡山","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游温州一带氛围拉满，晚餐雁荡山石斑鱼人均58元。","addr":"响岭头村","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"大龙湫","description":"全天主景点大龙湫，190米瀑布，雨后最壮。","addr":"雁荡山","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐香鱼（人均48元），早点休息。","addr":"大龙湫下","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"方洞栈道","description":"收官方洞栈道，悬崖栈道悬空百米。","addr":"雁荡山","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐雁茗茶后集合返程，三日旅程圆满。","addr":"灵峰景区","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"灵峰","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"灵峰是雁荡山最有代表性的看点，日景夜景两相宜，夫妻峰剪影。攻略把它排进主线，时间留得最足。","notice":"日景夜景两相宜，夫妻峰剪影。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"乐清