INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄山宏村秘境三日','cross','黄山 · 黄山宏村','mountain','https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80',99300,54600,2,'黄山光明顶 / 西海大峡谷 / 宏村 —— 一张票打包黄山宏村精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「黄山宏村」三日深度游——山岳。徽墨歙砚文房收藏佳品。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约12000步，量力而行","transitText":"全程大巴接送（已含）","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"安徽 · 黄山"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往黄山，抵达后办理入住、熟悉周边环境。","addr":"黄山市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"黄山光明顶","description":"下午首站黄山光明顶，调整状态进入旅行节奏，看日出云海的主峰平台。","addr":"黄山市黄山区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游黄山一带氛围拉满，晚餐臭鳜鱼人均78元。","addr":"屯溪老街","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"西海大峡谷","description":"全天主景点西海大峡谷，网红小火车，峡谷栈道惊险。","addr":"黄山风景区","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐毛豆腐（人均20元），早点休息。","addr":"宏村月沼旁","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"宏村","description":"收官宏村，月沼南湖水墨徽州，写生圣地。","addr":"黟县宏村镇","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐黄山烧饼后集合返程，三日旅程圆满。","addr":"汤口镇","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"黄山光明顶","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"黄山光明顶是黄山宏村最有代表性的看点，看日出云海的主峰平台。攻略把它排进主线，时间留得最足。","notice":"看日出云海的主峰平台。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"黄山市黄山区"},{"spotId":"S2","name":"西海大峡谷","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"西海大峡谷是黄山宏村最有代表性的看点，网红小火车，峡谷栈道惊险。攻略把它排进主线，时间留得最足。","notice":"网红小火车，峡谷栈道惊险。周边有休息区与补给点，随时停留。","durationMinutes":240,"addr":"黄山风景区"},{"spotId":"S3","name":"宏村","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"宏村是黄山宏村最有代表性的看点，月沼南湖水墨徽州，写生圣地。攻略把它排进主线，时间留得最足。","notice":"月沼南湖水墨徽州，写生圣地。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"黟县宏村镇"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"臭鳜鱼（人均78元）","description":"黄山 · 黄山宏村的招牌是臭鳜鱼，老街第一楼本地人都认这家，点单照攻略不踩雷。","addr":"屯溪老街"},{"title":"毛豆腐（人均20元）","description":"黄山 · 黄山宏村的招牌是毛豆腐，徽州小吃本地人都认这家，点单照攻略不踩雷。","addr":"宏村月沼旁"},{"title":"黄山烧饼（人均12元）","description":"黄山 · 黄山宏村的招牌是黄山烧饼，救驾烧饼本地人都认这家，点单照攻略不踩雷。","addr":"汤口镇"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44685,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","墨镜与拍照道具","保温水杯与少量现金","身份证件与手机充电宝","轻便雨衣或折叠伞"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 黄山 的交通方便吗？","推荐先到 黄山，再打车或景区直通车前往核心景区；自驾导航直接搜黄山宏村即可。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙门石窟跨省三日','cross','洛阳 · 龙门石窟','red','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',98200,54000,7,'龙门石窟 / 白马寺 / 洛邑古城 —— 一张票打包龙门石窟精髓','["跨省大交通", "行程内门票", "两晚住宿", "两早餐三正餐", "领队服务"]','{"overview":"「龙门石窟」三日深度游——人文。洛阳牡丹饼花香浓郁。本攻略按cross玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"三日深度游","paceText":"三日走透，山河全景一网打尽","walkText":"累计步行约8000步","transitText":"全程大巴接送（已含）","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 洛阳"},{"label":"建议游玩","value":"三日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"出发抵达","description":"集合出发前往洛阳，抵达后办理入住、熟悉周边环境。","addr":"洛阳市区","tip":"三日行程行李别超重"},{"dayNo":1,"time":"14:00","title":"龙门石窟","description":"下午首站龙门石窟，调整状态进入旅行节奏，卢舍那大佛，夜游灯光版。","addr":"洛阳市洛龙区","tip":"今晚早点休息，明天是重头戏"},{"dayNo":1,"time":"18:30","title":"夜游体验","description":"夜游洛阳一带氛围拉满，晚餐水席人均88元。","addr":"老城区","tip":"夜市人多看好随身物品"},{"dayNo":2,"time":"08:30","title":"白马寺","description":"全天主景点白马寺，中国第一古刹，国际佛殿。","addr":"洛阳市","tip":"今日强度最大，穿对鞋"},{"dayNo":2,"time":"17:00","title":"晚餐休整","description":"晚餐牛肉汤（人均15元），早点休息。","addr":"瀍河区","tip":"泡个脚缓解疲劳"},{"dayNo":2,"time":"19:30","title":"特色体验","description":"自由安排：手作体验、夜市或演出，按攻略清单选一样。","addr":"住宿周边","tip":"体验项目提前电话确认"},{"dayNo":3,"time":"09:00","title":"洛邑古城","description":"收官洛邑古城，汉服打卡圣地，夜景。","addr":"老城区","tip":"中午前完成，给返程留余量"},{"dayNo":3,"time":"12:30","title":"返程","description":"午餐不翻汤后集合返程，三日旅程圆满。","addr":"老城十字街","tip":"检查随身物品别落下"}],"spots":[{"spotId":"S1","name":"龙门石窟","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"龙门石窟是龙门石窟最有代表性的看点，卢舍那大佛，夜游灯光版。攻略把它排进主线，时间留得最足。","notice":"卢舍那大佛，夜游灯光版。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"洛阳市洛龙区"},{"spotId":"S2","name":"白马寺","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"白马寺是龙门石窟最有代表性的看点，中国第一古刹，国际佛殿。攻略把它排进主线，时间留得最足。","notice":"中国第一古刹，国际佛殿。这个点位上午光线最好。","durationMinutes":120,"addr":"洛阳市"},{"spotId":"S3","name":"洛邑古城","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"洛邑古城是龙门石窟最有代表性的看点，汉服打卡圣地，夜景。攻略把它排进主线，时间留得最足。","notice":"汉服打卡圣地，夜景。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"老城区"}],"transport":[{"title":"往返交通","description":"全程大巴接送（已含），车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"水席（人均88元）","description":"洛阳 · 龙门石窟的招牌是水席，真不同本地人都认这家，点单照攻略不踩雷。","addr":"老城区"},{"title":"牛肉汤（人均15元）","description":"洛阳 · 龙门石窟的招牌是牛肉汤，马杰山牛肉汤本地人都认这家，点单照攻略不踩雷。","addr":"瀍河区"},{"title":"不翻汤（人均12元）","description":"洛阳 · 龙门石窟的招牌是不翻汤，十字街夜市本地人都认这家，点单照攻略不踩雷。","addr":"老城十字街"}],"lodging":[{"title":"住宿建议","description":"双人标间（已含）周边特色民宿/酒店，含早餐，热水充足，山里夜里凉记得备外套。"}],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":44190,"required":true},{"name":"住宿（已含）","amount":0,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","身份证件与手机充电宝","轻便雨衣或折叠伞","保温水杯与少量现金","少量零食补给","常用药品（肠胃药/创可贴）","相机或运动相机","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["看好同行老人小孩，走失原地等待","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["当地有什么必吃？","到了 洛阳，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'这一次，把心跳交给山野。','on');
