INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丹霞山在地文化线','theme','韶关 · 丹霞山','adventure','https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80',21200,11600,9,'长老峰 / 阳元石 / 翔龙湖 —— 一张票打包丹霞山精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「丹霞山」一日轻旅行——探险地。丹霞山白毛茶清甜。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广东 · 韶关"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"韶关集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"丹霞山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"长老峰","description":"首站直达长老峰，丹霞地貌命名地，观日亭日出。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"韶关市仁化县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排仁化农家菜——人均约48元，冷水猪肚是本地招牌，点菜照着攻略走。","addr":"丹霞山镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"阳元石","description":"午后游览阳元石，天然奇石打卡。","addr":"丹霞山","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"翔龙湖","description":"收官打卡翔龙湖，水上丹霞乘船。随后自由活动，采购伴手礼。","addr":"丹霞山","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"长老峰","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"长老峰是丹霞山最有代表性的看点，丹霞地貌命名地，观日亭日出。攻略把它排进主线，时间留得最足。","notice":"丹霞地貌命名地，观日亭日出。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"韶关市仁化县"},{"spotId":"S2","name":"阳元石","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"阳元石是丹霞山最有代表性的看点，天然奇石打卡。攻略把它排进主线，时间留得最足。","notice":"天然奇石打卡。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"丹霞山"},{"spotId":"S3","name":"翔龙湖","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"翔龙湖是丹霞山最有代表性的看点，水上丹霞乘船。攻略把它排进主线，时间留得最足。","notice":"水上丹霞乘船。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"丹霞山"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"冷水猪肚（人均48元）","description":"韶关 · 丹霞山的招牌是冷水猪肚，仁化农家菜本地人都认这家，点单照攻略不踩雷。","addr":"丹霞山镇"},{"title":"炒山坑螺（人均38元）","description":"韶关 · 丹霞山的招牌是炒山坑螺，山坑鱼小馆本地人都认这家，点单照攻略不踩雷。","addr":"周田镇"},{"title":"酸笋鸭（人均58元）","description":"韶关 · 丹霞山的招牌是酸笋鸭，韶关客家菜本地人都认这家，点单照攻略不踩雷。","addr":"仁化县城"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9540,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["墨镜与拍照道具","常用药品（肠胃药/创可贴）","身份证件与手机充电宝","防晒霜与遮阳帽","少量零食补给","换洗衣物与外套（早晚温差）","保温水杯与少量现金","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","高原地区避免剧烈运动，备好氧气瓶","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 韶关，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('敦煌莫高窟小众玩法线','theme','酒泉 · 敦煌莫高窟','red','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',16800,9200,7,'莫高窟 / 鸣沙山月牙泉 / 沙洲夜市 —— 一张票打包敦煌莫高窟精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「敦煌莫高窟」一日轻旅行——人文。敦煌夜光杯工艺品别致。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"甘肃 · 酒泉"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"酒泉集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"敦煌莫高窟游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"莫高窟","description":"首站直达莫高窟，千年壁画宝库，A类票提前约。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"敦煌市鸣沙山东麓","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排顺张驴肉黄面馆——人均约28元，驴肉黄面是本地招牌，点菜照着攻略走。","addr":"滨河世纪家园","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"鸣沙山月牙泉","description":"午后游览鸣沙山月牙泉，沙漠绿洲，骆驼队与滑沙。","addr":"敦煌市","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"沙洲夜市","description":"收官打卡沙洲夜市，驴肉黄面与夜市淘货。随后自由活动，采购伴手礼。","addr":"敦煌市区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"莫高窟","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"莫高窟是敦煌莫高窟最有代表性的看点，千年壁画宝库，A类票提前约。攻略把它排进主线，时间留得最足。","notice":"千年壁画宝库，A类票提前约。提前10分钟到，避开旅行团大部队。","durationMinutes":240,"addr":"敦煌市鸣沙山东麓"},{"spotId":"S2","name":"鸣沙山月牙泉","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"鸣沙山月牙泉是敦煌莫高窟最有代表性的看点，沙漠绿洲，骆驼队与滑沙。攻略把它排进主线，时间留得最足。","notice":"沙漠绿洲，骆驼队与滑沙。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"敦煌市"},{"spotId":"S3","name":"沙洲夜市","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"沙洲夜市是敦煌莫高窟最有代表性的看点，驴肉黄面与夜市淘货。攻略把它排进主线，时间留得最足。","notice":"驴肉黄面与夜市淘货。这个点位上午光线最好。","durationMinutes":120,"addr":"敦煌市区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"驴肉黄面（人均28元）","description":"酒泉 · 敦煌莫高窟的招牌是驴肉黄面，顺张驴肉黄面馆本地人都认这家，点单照攻略不踩雷。","addr":"滨河世纪家园"},{"title":"胡羊焖饼（人均58元）","description":"酒泉 · 敦煌莫高窟的招牌是胡羊焖饼，靖远尕六美味羊羔肉本地人都认这家，点单照攻略不踩雷。","addr":"沙洲路"},{"title":"杏皮水（人均8元）","description":"酒泉 · 敦煌莫高窟的招牌是杏皮水，夜市摊位本地人都认这家，点单照攻略不踩雷。","addr":"沙洲夜市"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7560,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["相机或运动相机","舒适徒步鞋（防滑鞋底）","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）","保温水杯与少量现金","墨镜与拍照道具"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 酒泉，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["到达 酒泉 的交通方便吗？","推荐先到 酒泉，再打车或景区直通车前往核心景区；自驾导航直接搜敦煌莫高窟即可。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('布达拉宫CityWalk线','theme','拉萨 · 布达拉宫','plateau','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',17400,9500,2,'布达拉宫 / 大昭寺 / 色拉寺 —— 一张票打包布达拉宫精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「布达拉宫」一日轻旅行——高原。拉萨转经筒小件最好带。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"西藏 · 拉萨"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"拉萨集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"布达拉宫游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"布达拉宫","description":"首站直达布达拉宫，海拔3700宫殿，提前一天预约。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"拉萨市城关区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排光明港琼甜茶馆——人均约12元，藏面是本地招牌，点菜照着攻略走。","addr":"八廓街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"大昭寺","description":"午后游览大昭寺，八廓街转经道，藏地心脏。","addr":"老城区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"色拉寺","description":"收官打卡色拉寺，辩经下午3点开始，场面壮观。随后自由活动，采购伴手礼。","addr":"城北","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"布达拉宫","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"布达拉宫是布达拉宫最有代表性的看点，海拔3700宫殿，提前一天预约。攻略把它排进主线，时间留得最足。","notice":"海拔3700宫殿，提前一天预约。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"拉萨市城关区"},{"spotId":"S2","name":"大昭寺","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"大昭寺是布达拉宫最有代表性的看点，八廓街转经道，藏地心脏。攻略把它排进主线，时间留得最足。","notice":"八廓街转经道，藏地心脏。这个点位上午光线最好。","durationMinutes":120,"addr":"老城区"},{"spotId":"S3","name":"色拉寺","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"色拉寺是布达拉宫最有代表性的看点，辩经下午3点开始，场面壮观。攻略把它排进主线，时间留得最足。","notice":"辩经下午3点开始，场面壮观。这个点位上午光线最好。","durationMinutes":90,"addr":"城北"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"藏面（人均12元）","description":"拉萨 · 布达拉宫的招牌是藏面，光明港琼甜茶馆本地人都认这家，点单照攻略不踩雷。","addr":"八廓街"},{"title":"烤牦牛肉（人均68元）","description":"拉萨 · 布达拉宫的招牌是烤牦牛肉，玛吉阿米本地人都认这家，点单照攻略不踩雷。","addr":"八角东南角"},{"title":"青稞酒（人均30元）","description":"拉萨 · 布达拉宫的招牌是青稞酒，藏家宴本地人都认这家，点单照攻略不踩雷。","addr":"藏医院路"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7830,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["少量零食补给","墨镜与拍照道具","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","舒适徒步鞋（防滑鞋底）","相机或运动相机","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域"],"faqs":[["当地有什么必吃？","到了 拉萨，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('五大道瓷房子味觉探索线','theme','和平 · 五大道瓷房子','art','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',22500,12300,5,'五大道 / 瓷房子 / 古文化街 —— 一张票打包五大道瓷房子精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「五大道瓷房子」一日轻旅行——文艺。天津泥人张彩塑传神。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"天津 · 和平"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"和平集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"五大道瓷房子游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"五大道","description":"首站直达五大道，万国建筑博览会，马车游。建议停留120分钟，跟着攻略动线走省一半时间。","addr":"天津市和平区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排南楼煎饼——人均约10元，煎饼果子是本地招牌，点菜照着攻略走。","addr":"和平区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"瓷房子","description":"午后游览瓷房子，7亿瓷片房子，白天看外观。","addr":"和平区赤峰道","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"古文化街","description":"收官打卡古文化街，泥人张杨柳青年画。随后自由活动，采购伴手礼。","addr":"南开区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"五大道","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"五大道是五大道瓷房子最有代表性的看点，万国建筑博览会，马车游。攻略把它排进主线，时间留得最足。","notice":"万国建筑博览会，马车游。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"天津市和平区"},{"spotId":"S2","name":"瓷房子","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"瓷房子是五大道瓷房子最有代表性的看点，7亿瓷片房子，白天看外观。攻略把它排进主线，时间留得最足。","notice":"7亿瓷片房子，白天看外观。拍照记得留神脚下台阶。","durationMinutes":30,"addr":"和平区赤峰道"},{"spotId":"S3","name":"古文化街","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"古文化街是五大道瓷房子最有代表性的看点，泥人张杨柳青年画。攻略把它排进主线，时间留得最足。","notice":"泥人张杨柳青年画。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"南开区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"煎饼果子（人均10元）","description":"和平 · 五大道瓷房子的招牌是煎饼果子，南楼煎饼本地人都认这家，点单照攻略不踩雷。","addr":"和平区"},{"title":"狗不理包子（人均45元）","description":"和平 · 五大道瓷房子的招牌是狗不理包子，狗不理总店本地人都认这家，点单照攻略不踩雷。","addr":"山东路"},{"title":"耳朵眼炸糕（人均8元）","description":"和平 · 五大道瓷房子的招牌是耳朵眼炸糕，耳朵眼总店本地人都认这家，点单照攻略不踩雷。","addr":"古文化街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":10125,"required":true},{"name":"餐饮参考","amount":100,"required":false}],"checklist":["身份证件与手机充电宝","相机或运动相机","防晒霜与遮阳帽","保温水杯与少量现金","少量零食补给","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","换洗衣物与外套（早晚温差）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["几月份去 和平 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["到达 和平 的交通方便吗？","推荐先到 和平，再打车或景区直通车前往核心景区；自驾导航直接搜五大道瓷房子即可。"]]}',2,'这一次，把心跳交给山野。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙虎山主题专线','theme','鹰潭 · 龙虎山','water','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',22000,12100,2,'仙水岩 / 泸溪河竹筏 / 上清古镇 —— 一张票打包龙虎山精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「龙虎山」一日轻旅行——水景。龙虎山道教养生茶值得带。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 鹰潭"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"鹰潭集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"龙虎山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"仙水岩","description":"首站直达仙水岩，悬棺表演一天四场，提前占前排。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"龙虎山仙水岩景区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排上清古镇饭店——人均约68元，天师板栗烧鸡是本地招牌，点菜照着攻略走。","addr":"上清古镇长街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"泸溪河竹筏","description":"午后游览泸溪河竹筏，顺流漂90分钟，防晒必做。","addr":"龙虎山竹筏码头","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"上清古镇","description":"收官打卡上清古镇，天师府在此，古街人少。随后自由活动，采购伴手礼。","addr":"龙虎山上清镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"仙水岩","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"仙水岩是龙虎山最有代表性的看点，悬棺表演一天四场，提前占前排。攻略把它排进主线，时间留得最足。","notice":"悬棺表演一天四场，提前占前排。这个点位上午光线最好。","durationMinutes":120,"addr":"龙虎山仙水岩景区"},{"spotId":"S2","name":"泸溪河竹筏","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"泸溪河竹筏是龙虎山最有代表性的看点，顺流漂90分钟，防晒必做。攻略把它排进主线，时间留得最足。","notice":"顺流漂90分钟，防晒必做。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"龙虎山竹筏码头"},{"spotId":"S3","name":"上清古镇","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"上清古镇是龙虎山最有代表性的看点，天师府在此，古街人少。攻略把它排进主线，时间留得最足。","notice":"天师府在此，古街人少。这个点位上午光线最好。","durationMinutes":120,"addr":"龙虎山上清镇"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"天师板栗烧鸡（人均68元）","description":"鹰潭 · 龙虎山的招牌是天师板栗烧鸡，上清古镇饭店本地人都认这家，点单照攻略不踩雷。","addr":"上清古镇长街"},{"title":"泸溪河鱼（人均58元）","description":"鹰潭 · 龙虎山的招牌是泸溪河鱼，仙水岩渔家本地人都认这家，点单照攻略不踩雷。","addr":"竹筏码头旁"},{"title":"上清豆腐（人均20元）","description":"鹰潭 · 龙虎山的招牌是上清豆腐，古镇豆腐坊本地人都认这家，点单照攻略不踩雷。","addr":"上清古街中段"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9900,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["保温水杯与少量现金","防晒霜与遮阳帽","轻便雨衣或折叠伞","少量零食补给","舒适徒步鞋（防滑鞋底）","墨镜与拍照道具","相机或运动相机","换洗衣物与外套（早晚温差）"],"planB":"遇到客流管控，按攻略中的备选路线反向游览，避开人流高峰。","safetyTips":["夜间出行结伴，走主路不抄小道","高原地区避免剧烈运动，备好氧气瓶","山区信号弱，提前下载离线地图","贵重物品随身携带，景区人多注意"],"faqs":[["几月份去 鹰潭 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('张家界国家森林公园深度体验线','theme','张家界 · 张家界国家森林公园','mountain','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',21500,11800,2,'袁家界 / 天子山 / 金鞭溪 —— 一张票打包张家界国家森林公园精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「张家界国家森林公园」一日轻旅行——山岳。张家界莓茶降火神器。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 张家界"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"张家界集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"张家界国家森林公园游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"袁家界","description":"首站直达袁家界，阿凡达悬浮山原型，百龙天梯上山。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"武陵源区森林公园","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排胡师傅三下锅——人均约58元，三下锅是本地招牌，点菜照着攻略走。","addr":"武陵源汽车站旁","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"天子山","description":"午后游览天子山，御笔峰日落绝佳，贺龙公园顺路。","addr":"武陵源天子山景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"金鞭溪","description":"收官打卡金鞭溪，全程7.5公里平路，溪边猕猴抢食注意。随后自由活动，采购伴手礼。","addr":"森林公园大氧吧广场","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"袁家界","coverUrl":"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80","highlights":"袁家界是张家界国家森林公园最有代表性的看点，阿凡达悬浮山原型，百龙天梯上山。攻略把它排进主线，时间留得最足。","notice":"阿凡达悬浮山原型，百龙天梯上山。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"武陵源区森林公园"},{"spotId":"S2","name":"天子山","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"天子山是张家界国家森林公园最有代表性的看点，御笔峰日落绝佳，贺龙公园顺路。攻略把它排进主线，时间留得最足。","notice":"御笔峰日落绝佳，贺龙公园顺路。这个点位上午光线最好。","durationMinutes":150,"addr":"武陵源天子山景区"},{"spotId":"S3","name":"金鞭溪","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"金鞭溪是张家界国家森林公园最有代表性的看点，全程7.5公里平路，溪边猕猴抢食注意。攻略把它排进主线，时间留得最足。","notice":"全程7.5公里平路，溪边猕猴抢食注意。周边有休息区与补给点，随时停留。","durationMinutes":180,"addr":"森林公园大氧吧广场"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"三下锅（人均58元）","description":"张家界 · 张家界国家森林公园的招牌是三下锅，胡师傅三下锅本地人都认这家，点单照攻略不踩雷。","addr":"武陵源汽车站旁"},{"title":"土家腊肉（人均48元）","description":"张家界 · 张家界国家森林公园的招牌是土家腊肉，湘西腊肉馆本地人都认这家，点单照攻略不踩雷。","addr":"溪布街"},{"title":"岩耳炖土鸡（人均88元）","description":"张家界 · 张家界国家森林公园的招牌是岩耳炖土鸡，山里人家本地人都认这家，点单照攻略不踩雷。","addr":"森林公园门票站"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9675,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","舒适徒步鞋（防滑鞋底）","少量零食补给","保温水杯与少量现金","墨镜与拍照道具","防晒霜与遮阳帽","轻便雨衣或折叠伞","相机或运动相机"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["山区信号弱，提前下载离线地图","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","涉水项目穿好救生衣，听从工作人员安排"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 张家界 的交通方便吗？","推荐先到 张家界，再打车或景区直通车前往核心景区；自驾导航直接搜张家界国家森林公园即可。"],["当地有什么必吃？","到了 张家界，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'这一程，山水都在替你说话。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('紫鹊界梯田慢生活专线','theme','娄底 · 紫鹊界梯田','village','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80',22700,12400,1,'紫鹊界梯田 / 正龙古村 / 梅山龙宫 —— 一张票打包紫鹊界梯田精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「紫鹊界梯田」一日轻旅行——古村落。新化黄精茶养生。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 娄底"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"娄底集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"紫鹊界梯田游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"紫鹊界梯田","description":"首站直达紫鹊界梯田，两千年秦人梯田，月牙山八仙过海。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"娄底市新化县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排老字号三合汤——人均约38元，新化三合汤是本地招牌，点菜照着攻略走。","addr":"新化县城","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"正龙古村","description":"午后游览正龙古村，干栏式板屋村落。","addr":"紫鹊界脚下","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"梅山龙宫","description":"收官打卡梅山龙宫，地下溶洞暗河乘船。随后自由活动，采购伴手礼。","addr":"新化县","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"紫鹊界梯田","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"紫鹊界梯田是紫鹊界梯田最有代表性的看点，两千年秦人梯田，月牙山八仙过海。攻略把它排进主线，时间留得最足。","notice":"两千年秦人梯田，月牙山八仙过海。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"娄底市新化县"},{"spotId":"S2","name":"正龙古村","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highligh