INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('大熊猫基地都江堰周末夜游线','theme','成都 · 大熊猫基地都江堰','food','https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80',18300,10000,3,'大熊猫繁育研究基地 / 都江堰 / 南桥夜啤酒 —— 一张票打包大熊猫基地都江堰精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「大熊猫基地都江堰」一日轻旅行——美食。郫县豆瓣是川菜之魂。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 成都"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"成都集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"大熊猫基地都江堰游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"大熊猫繁育研究基地","description":"首站直达大熊猫繁育研究基地，早8点开园直奔月亮产房，熊猫最活跃。建议停留192分钟，跟着攻略动线走省一半时间。","addr":"成华区外北熊猫大道","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排蜀大侠——人均约110元，火锅是本地招牌，点菜照着攻略走。","addr":"建设路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"都江堰","description":"午后游览都江堰，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。","addr":"都江堰市公园路","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"南桥夜啤酒","description":"收官打卡南桥夜啤酒，岷江水上的夜风与美食。随后自由活动，采购伴手礼。","addr":"都江堰市南桥","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"大熊猫繁育研究基地","coverUrl":"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80","highlights":"大熊猫繁育研究基地是大熊猫基地都江堰最有代表性的看点，早8点开园直奔月亮产房，熊猫最活跃。攻略把它排进主线，时间留得最足。","notice":"早8点开园直奔月亮产房，熊猫最活跃。拍照记得留神脚下台阶。","durationMinutes":240,"addr":"成华区外北熊猫大道"},{"spotId":"S2","name":"都江堰","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"都江堰是大熊猫基地都江堰最有代表性的看点，鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。攻略把它排进主线，时间留得最足。","notice":"鱼嘴分水飞沙堰宝瓶口，古人智慧震撼。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"都江堰市公园路"},{"spotId":"S3","name":"南桥夜啤酒","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"南桥夜啤酒是大熊猫基地都江堰最有代表性的看点，岷江水上的夜风与美食。攻略把它排进主线，时间留得最足。","notice":"岷江水上的夜风与美食。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"都江堰市南桥"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"火锅（人均110元）","description":"成都 · 大熊猫基地都江堰的招牌是火锅，蜀大侠本地人都认这家，点单照攻略不踩雷。","addr":"建设路"},{"title":"串串香（人均65元）","description":"成都 · 大熊猫基地都江堰的招牌是串串香，马路边边本地人都认这家，点单照攻略不踩雷。","addr":"玉林路"},{"title":"钟水饺（人均15元）","description":"成都 · 大熊猫基地都江堰的招牌是钟水饺，老字号小吃本地人都认这家，点单照攻略不踩雷。","addr":"人民公园旁"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8235,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["相机或运动相机","少量零食补给","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","轻便雨衣或折叠伞","舒适徒步鞋（防滑鞋底）","保温水杯与少量现金","身份证件与手机充电宝"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["看好同行老人小孩，走失原地等待","贵重物品随身携带，景区人多注意","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图"],"faqs":[["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('黄果树瀑布在地文化线','theme','安顺 · 黄果树瀑布','water','https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80',19300,10600,2,'黄果树大瀑布 / 天星桥 / 陡坡塘 —— 一张票打包黄果树瀑布精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「黄果树瀑布」一日轻旅行——水景。安顺三刀是传统名点。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约10000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"贵州 · 安顺"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"安顺集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"黄果树瀑布游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"黄果树大瀑布","description":"首站直达黄果树大瀑布，亚洲最大瀑布，水帘洞穿瀑而过。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"安顺市镇宁县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排安顺小吃街——人均约35元，夺夺粉是本地招牌，点菜照着攻略走。","addr":"安顺市区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"天星桥","description":"午后游览天星桥，石景水上盆景，数生步趣味。","addr":"黄果树景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"陡坡塘","description":"收官打卡陡坡塘，西游记片尾取景地。随后自由活动，采购伴手礼。","addr":"黄果树景区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"黄果树大瀑布","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"黄果树大瀑布是黄果树瀑布最有代表性的看点，亚洲最大瀑布，水帘洞穿瀑而过。攻略把它排进主线，时间留得最足。","notice":"亚洲最大瀑布，水帘洞穿瀑而过。拍照记得留神脚下台阶。","durationMinutes":180,"addr":"安顺市镇宁县"},{"spotId":"S2","name":"天星桥","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights"