INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('龙脊梯田小众玩法线','theme','桂林 · 龙脊梯田','village','https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80',18900,10300,1,'平安寨七星伴月 / 金坑大寨 / 黄洛红瑶寨 —— 一张票打包龙脊梯田精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「龙脊梯田」一日轻旅行——古村落。龙脊辣椒酱拌饭一绝。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"广西 · 桂林"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"桂林集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"龙脊梯田游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"平安寨七星伴月","description":"首站直达平安寨七星伴月，经典梯田观景台，徒步30分钟。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"龙胜县龙脊镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排梯田农家——人均约25元，竹筒饭是本地招牌，点菜照着攻略走。","addr":"平安寨","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"金坑大寨","description":"午后游览金坑大寨，缆车直达3号观景点，日落最佳。","addr":"龙脊梯田金坑","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"黄洛红瑶寨","description":"收官打卡黄洛红瑶寨，天下第一长发村表演。随后自由活动，采购伴手礼。","addr":"龙脊山下","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"平安寨七星伴月","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"平安寨七星伴月是龙脊梯田最有代表性的看点，经典梯田观景台，徒步30分钟。攻略把它排进主线，时间留得最足。","notice":"经典梯田观景台，徒步30分钟。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"龙胜县龙脊镇"},{"spotId":"S2","name":"金坑大寨","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"金坑大寨是龙脊梯田最有代表性的看点，缆车直达3号观景点，日落最佳。攻略把它排进主线，时间留得最足。","notice":"缆车直达3号观景点，日落最佳。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"龙脊梯田金坑"},{"spotId":"S3","name":"黄洛红瑶寨","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"黄洛红瑶寨是龙脊梯田最有代表性的看点，天下第一长发村表演。攻略把它排进主线，时间留得最足。","notice":"天下第一长发村表演。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"龙脊山下"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"竹筒饭（人均25元）","description":"桂林 · 龙脊梯田的招牌是竹筒饭，梯田农家本地人都认这家，点单照攻略不踩雷。","addr":"平安寨"},{"title":"土鸡煲（人均68元）","description":"桂林 · 龙脊梯田的招牌是土鸡煲，大寨农家本地人都认这家，点单照攻略不踩雷。","addr":"金坑梯田"},{"title":"龙脊茶（人均20元）","description":"桂林 · 龙脊梯田的招牌是龙脊茶，茶农家本地人都认这家，点单照攻略不踩雷。","addr":"黄洛瑶寨"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8505,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","换洗衣物与外套（早晚温差）","保温水杯与少量现金","墨镜与拍照道具","身份证件与手机充电宝","常用药品（肠胃药/创可贴）","防晒霜与遮阳帽","轻便雨衣或折叠伞"],"planB":"索道停运时启用徒步步道方案，注意预留体力与时间。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图","涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["当地有什么必吃？","到了 桂林，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 桂林 的交通方便吗？","推荐先到 桂林，再打车或景区直通车前往核心景区；自驾导航直接搜龙脊梯田即可。"]]}',2,'有些风景，照片永远差一点，比如你亲眼看到的那一刻。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('霞浦滩涂CityWalk线','theme','宁德 · 霞浦滩涂','photography','https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80',21900,12000,12,'北岐滩涂 / 杨家溪 / 东壁日落 —— 一张票打包霞浦滩涂精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「霞浦滩涂」一日轻旅行——摄影胜地。霞浦紫菜海带全国第一。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"福建 · 宁德"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"宁德集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"霞浦滩涂游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"北岐滩涂","description":"首站直达北岐滩涂，日出紫菜架光影，摄影圣地。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"霞浦县松港街道","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排海鲜大排档——人均约68元，霞浦剑蛏是本地招牌，点菜照着攻略走。","addr":"三沙镇","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"杨家溪","description":"午后游览杨家溪，千年枫榕树群，牛群穿雾。","addr":"霞浦县牙城镇","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"东壁日落","description":"收官打卡东壁日落，落日渔船归航机位。随后自由活动，采购伴手礼。","addr":"霞浦县三沙镇","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"北岐滩涂","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"北岐滩涂是霞浦滩涂最有代表性的看点，日出紫菜架光影，摄影圣地。攻略把它排进主线，时间留得最足。","notice":"日出紫菜架光影，摄影圣地。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"霞浦县松港街道"},{"spotId":"S2","name":"杨家溪","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"杨家溪是霞浦滩涂最有代表性的看点，千年枫榕树群，牛群穿雾。攻略把它排进主线，时间留得最足。","notice":"千年枫榕树群，牛群穿雾。这个点位上午光线最好。","durationMinutes":150,"addr":"霞浦县牙城镇"},{"spotId":"S3","name":"东壁日落","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"东壁日落是霞浦滩涂最有代表性的看点，落日渔船归航机位。攻略把它排进主线，时间留得最足。","notice":"落日渔船归航机位。这个点位上午光线最好。","durationMinutes":90,"addr":"霞浦县三沙镇"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"霞浦剑蛏（人均68元）","description":"宁德 · 霞浦滩涂的招牌是霞浦剑蛏，海鲜大排档本地人都认这家，点单照攻略不踩雷。","addr":"三沙镇"},{"title":"海带排骨汤（人均38元）","description":"宁德 · 霞浦滩涂的招牌是海带排骨汤，渔家菜本地人都认这家，点单照攻略不踩雷。","addr":"北岐村"},{"title":"糊汤（人均10元）","description":"宁德 · 霞浦滩涂的招牌是糊汤，街头早点本地人都认这家，点单照攻略不踩雷。","addr":"霞浦县城"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9855,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["换洗衣物与外套（早晚温差）","少量零食补给","轻便雨衣或折叠伞","保温水杯与少量现金","墨镜与拍照道具","相机或运动相机","舒适徒步鞋（防滑鞋底）","防晒霜与遮阳帽"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["贵重物品随身携带，景区人多注意","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图"],"faqs":[["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["到达 宁德 的交通方便吗？","推荐先到 宁德，再打车或景区直通车前往核心景区；自驾导航直接搜霞浦滩涂即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('拙政园林味觉探索线','theme','苏州 · 拙政园林','art','https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80',18300,10000,5,'拙政园 / 平江路 / 虎丘 —— 一张票打包拙政园林精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「拙政园林」一日轻旅行——文艺。苏绣团扇工艺最精。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江苏 · 苏州"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"苏州集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"拙政园林游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"拙政园","description":"首站直达拙政园，江南园林之母，人再多也值得。建议停留120分钟，跟着攻略动线走省一半时间。","addr":"苏州市姑苏区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排得月楼——人均约128元，松鼠桂鱼是本地招牌，点菜照着攻略走。","addr":"太监弄","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"平江路","description":"午后游览平江路，小桥流水人家，评弹声里喝茶。","addr":"姑苏区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"虎丘","description":"收官打卡虎丘，吴中第一名胜，斜塔传奇。随后自由活动，采购伴手礼。","addr":"姑苏区山塘街","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"拙政园","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"拙政园是拙政园林最有代表性的看点，江南园林之母，人再多也值得。攻略把它排进主线，时间留得最足。","notice":"江南园林之母，人再多也值得。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"苏州市姑苏区"},{"spotId":"S2","name":"平江路","coverUrl":"https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80","highlights":"平江路是拙政园林最有代表性的看点，小桥流水人家，评弹声里喝茶。攻略把它排进主线，时间留得最足。","notice":"小桥流水人家，评弹声里喝茶。提前10分钟到，避开旅行团大部队。","durationMinutes":150,"addr":"姑苏区"},{"spotId":"S3","name":"虎丘","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"虎丘是拙政园林最有代表性的看点，吴中第一名胜，斜塔传奇。攻略把它排进主线，时间留得最足。","notice":"吴中第一名胜，斜塔传奇。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"姑苏区山塘街"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松鼠桂鱼（人均128元）","description":"苏州 · 拙政园林的招牌是松鼠桂鱼，得月楼本地人都认这家，点单照攻略不踩雷。","addr":"太监弄"},{"title":"蟹粉小笼（人均25元）","description":"苏州 · 拙政园林的招牌是蟹粉小笼，哑巴生煎本地人都认这家，点单照攻略不踩雷。","addr":"临顿路"},{"title":"桂花糕（人均15元）","description":"苏州 · 拙政园林的招牌是桂花糕，采芝斋本地人都认这家，点单照攻略不踩雷。","addr":"山塘街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8235,"required":true},{"name":"餐饮参考","amount":60,"required":false}],"checklist":["墨镜与拍照道具","舒适徒步鞋（防滑鞋底）","常用药品（肠胃药/创可贴）","轻便雨衣或折叠伞","保温水杯与少量现金","相机或运动相机","少量零食补给","换洗衣物与外套（早晚温差）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","高原地区避免剧烈运动，备好氧气瓶","饮食注意卫生，海鲜过敏提前告知店家","山区信号弱，提前下载离线地图"],"faqs":[["几月份去 苏州 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["到达 苏州 的交通方便吗？","推荐先到 苏州，再打车或景区直通车前往核心景区；自驾导航直接搜拙政园林即可。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('恩施大峡谷主题专线','theme','恩施 · 恩施大峡谷','adventure','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80',20400,11200,9,'七星寨 / 云龙地缝 / 梭布垭石林 —— 一张票打包恩施大峡谷精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「恩施大峡谷」一日轻旅行——探险地。恩施玉露茶古法蒸青。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖北 · 恩施"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"恩施集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"恩施大峡谷游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"七星寨","description":"首站直达七星寨，一炷香奇观，云龙地缝联游。建议停留240分钟，跟着攻略动线走省一半时间。","addr":"恩施市沐抚街道","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排张关合渣——人均约58元，土家腊蹄子是本地招牌，点菜照着攻略走。","addr":"恩施市区","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"云龙地缝","description":"午后游览云龙地缝，U型地缝瀑布成群。","addr":"大峡谷景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"梭布垭石林","description":"收官打卡梭布垭石林，戴冠石林迷宫。随后自由活动，采购伴手礼。","addr":"恩施市太阳河乡","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"七星寨","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"七星寨是恩施大峡谷最有代表性的看点，一炷香奇观，云龙地缝联游。攻略把它排进主线，时间留得最足。","notice":"一炷香奇观，云龙地缝联游。周边有休息区与补给点，随时停留。","durationMinutes":300,"addr":"恩施市沐抚街道"},{"spotId":"S2","name":"云龙地缝","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"