INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('老君山深度体验线','theme','栾川 · 老君山','mountain','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',21700,11900,2,'金顶道观群 / 十里画屏 / 追梦谷 —— 一张票打包老君山精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「老君山」一日轻旅行——山岳。老君山高山茶清冽。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"河南 · 栾川"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"栾川集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"老君山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"金顶道观群","description":"首站直达金顶道观群，云海雪景封神，远赴人间惊鸿宴。建议停留240分钟，跟着攻略动线走省一半时间。","addr":"洛阳市栾川县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排山城豆腐宴——人均约28元，栾川豆腐是本地招牌，点菜照着攻略走。","addr":"栾川县城","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"十里画屏","description":"午后游览十里画屏，滑道下山，省膝盖。","addr":"老君山石林","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"追梦谷","description":"收官打卡追梦谷，溪瀑竹林轻松线。随后自由活动，采购伴手礼。","addr":"老君山脚下","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"金顶道观群","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"金顶道观群是老君山最有代表性的看点，云海雪景封神，远赴人间惊鸿宴。攻略把它排进主线，时间留得最足。","notice":"云海雪景封神，远赴人间惊鸿宴。拍照记得留神脚下台阶。","durationMinutes":300,"addr":"洛阳市栾川县"},{"spotId":"S2","name":"十里画屏","coverUrl":"https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80","highlights":"十里画屏是老君山最有代表性的看点，滑道下山，省膝盖。攻略把它排进主线，时间留得最足。","notice":"滑道下山，省膝盖。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"老君山石林"},{"spotId":"S3","name":"追梦谷","coverUrl":"https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80","highlights":"追梦谷是老君山最有代表性的看点，溪瀑竹林轻松线。攻略把它排进主线，时间留得最足。","notice":"溪瀑竹林轻松线。这个点位上午光线最好。","durationMinutes":120,"addr":"老君山脚下"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"栾川豆腐（人均28元）","description":"栾川 · 老君山的招牌是栾川豆腐，山城豆腐宴本地人都认这家，点单照攻略不踩雷。","addr":"栾川县城"},{"title":"蝌蚪面（人均18元）","description":"栾川 · 老君山的招牌是蝌蚪面，老君山农家本地人都认这家，点单照攻略不踩雷。","addr":"鸡冠洞乡"},{"title":"玉米糁汤（人均10元）","description":"栾川 · 老君山的招牌是玉米糁汤，农家早餐本地人都认这家，点单照攻略不踩雷。","addr":"景区民宿"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9765,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["常用药品（肠胃药/创可贴）","身份证件与手机充电宝","相机或运动相机","保温水杯与少量现金","少量零食补给","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","恶劣天气听从景区安排，不进入未开放区域","山区信号弱，提前下载离线地图"],"faqs":[["到达 栾川 的交通方便吗？","推荐先到 栾川，再打车或景区直通车前往核心景区；自驾导航直接搜老君山即可。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"],["几月份去 栾川 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"],["当地有什么必吃？","到了 栾川，跟着本攻略的美食清单走就行，本地人都在吃这几家。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
