INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('婺源篁岭小众玩法线','theme','上饶 · 婺源篁岭','village','https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?auto=format&fit=crop&w=800&q=80',19800,10800,1,'晒秋人家 / 垒心桥 / 梯田花海 —— 一张票打包婺源篁岭精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「婺源篁岭」一日轻旅行——古村落。婺源荷包红鲤鱼可真空打包带回家。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 上饶"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"上饶集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"婺源篁岭游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"晒秋人家","description":"首站直达晒秋人家，晒秋最佳拍摄位在天街中层，上午顺光。建议停留96分钟，跟着攻略动线走省一半时间。","addr":"婺源县江湾镇篁岭村","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排天街食府——人均约28元，蒸汽糕是本地招牌，点菜照着攻略走。","addr":"篁岭天街中段","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"垒心桥","description":"午后游览垒心桥，桥面风大，手机拿稳。","addr":"篁岭景区索道上站","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"梯田花海","description":"收官打卡梯田花海，春季油菜花、秋季稻浪，两季都出片。随后自由活动，采购伴手礼。","addr":"篁岭村北坡","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"晒秋人家","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"晒秋人家是婺源篁岭最有代表性的看点，晒秋最佳拍摄位在天街中层，上午顺光。攻略把它排进主线，时间留得最足。","notice":"晒秋最佳拍摄位在天街中层，上午顺光。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"婺源县江湾镇篁岭村"},{"spotId":"S2","name":"垒心桥","coverUrl":"https://images.unsplash.com/photo-1537531383496-f4749b8032cf?auto=format&fit=crop&w=800&q=80","highlights":"垒心桥是婺源篁岭最有代表性的看点，桥面风大，手机拿稳。攻略把它排进主线，时间留得最足。","notice":"桥面风大，手机拿稳。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"篁岭景区索道上站"},{"spotId":"S3","name":"梯田花海","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"梯田花海是婺源篁岭最有代表性的看点，春季油菜花、秋季稻浪，两季都出片。攻略把它排进主线，时间留得最足。","notice":"春季油菜花、秋季稻浪，两季都出片。提前10分钟到，避开旅行团大部队。","durationMinutes":90,"addr":"篁岭村北坡"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"蒸汽糕（人均28元）","description":"上饶 · 婺源篁岭的招牌是蒸汽糕，天街食府本地人都认这家，点单照攻略不踩雷。","addr":"篁岭天街中段"},{"title":"清明果（人均15元）","description":"上饶 · 婺源篁岭的招牌是清明果，晒秋人家小吃铺本地人都认这家，点单照攻略不踩雷。","addr":"篁岭古村巷内"},{"title":"荷包红鲤鱼（人均68元）","description":"上饶 · 婺源篁岭的招牌是荷包红鲤鱼，篁岭酒楼本地人都认这家，点单照攻略不踩雷。","addr":"篁岭村口第一家"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8910,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","少量零食补给","保温水杯与少量现金","轻便雨衣或折叠伞","相机或运动相机","墨镜与拍照道具","防晒霜与遮阳帽"],"planB":"若核心景区因天气或检修关闭，自动替换为同区域同类景点，行程时长不变。","safetyTips":["山区信号弱，提前下载离线地图","恶劣天气听从景区安排，不进入未开放区域","涉水项目穿好救生衣，听从工作人员安排","夜间出行结伴，走主路不抄小道"],"faqs":[["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"],["当地有什么必吃？","到了 上饶，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["到达 上饶 的交通方便吗？","推荐先到 上饶，再打车或景区直通车前往核心景区；自驾导航直接搜婺源篁岭即可。"]]}',2,'今天的夕阳，为你的抵达打光。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('陶溪川CityWalk线','theme','景德镇 · 陶溪川','art','https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80',20200,11100,5,'陶溪川文创街区 / 古窑民俗博览区 / 雕塑瓷厂乐天市集 —— 一张票打包陶溪川精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「陶溪川」一日轻旅行——文艺。景德镇薄胎瓷碗轻巧又体面。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"秋季层林尽染最出片","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"江西 · 景德镇"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"景德镇集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"陶溪川游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"陶溪川文创街区","description":"首站直达陶溪川文创街区，夜市周五六日开，手作摊最好逛。建议停留120分钟，跟着攻略动线走省一半时间。","addr":"珠山区新厂西路","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排老字号小吃店——人均约15元，饺子粑是本地招牌，点菜照着攻略走。","addr":"中山北路","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"古窑民俗博览区","description":"午后游览古窑民俗博览区，看柴窑镇窑复烧，拉坯体验要排队。","addr":"昌江区枫树山蟠龙岗","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"雕塑瓷厂乐天市集","description":"收官打卡雕塑瓷厂乐天市集，周六上午开市，淘手作好物。随后自由活动，采购伴手礼。","addr":"新厂东路139号","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"陶溪川文创街区","coverUrl":"https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80","highlights":"陶溪川文创街区是陶溪川最有代表性的看点，夜市周五六日开，手作摊最好逛。攻略把它排进主线，时间留得最足。","notice":"夜市周五六日开，手作摊最好逛。拍照记得留神脚下台阶。","durationMinutes":150,"addr":"珠山区新厂西路"},{"spotId":"S2","name":"古窑民俗博览区","coverUrl":"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80","highlights":"古窑民俗博览区是陶溪川最有代表性的看点，看柴窑镇窑复烧，拉坯体验要排队。攻略把它排进主线，时间留得最足。","notice":"看柴窑镇窑复烧，拉坯体验要排队。这个点位上午光线最好。","durationMinutes":150,"addr":"昌江区枫树山蟠龙岗"},{"spotId":"S3","name":"雕塑瓷厂乐天市集","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"雕塑瓷厂乐天市集是陶溪川最有代表性的看点，周六上午开市，淘手作好物。攻略把它排进主线，时间留得最足。","notice":"周六上午开市，淘手作好物。拍照记得留神脚下台阶。","durationMinutes":90,"addr":"新厂东路139号"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约3小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"饺子粑（人均15元）","description":"景德镇 · 陶溪川的招牌是饺子粑，老字号小吃店本地人都认这家，点单照攻略不踩雷。","addr":"中山北路"},{"title":"冷粉（人均12元）","description":"景德镇 · 陶溪川的招牌是冷粉，景德镇冷粉店本地人都认这家，点单照攻略不踩雷。","addr":"人民广场附近"},{"title":"碱水粑炒鸡蛋（人均28元）","description":"景德镇 · 陶溪川的招牌是碱水粑炒鸡蛋，瓷都家常菜本地人都认这家，点单照攻略不踩雷。","addr":"陶溪川周边小馆"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":9090,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["舒适徒步鞋（防滑鞋底）","相机或运动相机","防晒霜与遮阳帽","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","轻便雨衣或折叠伞","保温水杯与少量现金","墨镜与拍照道具"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","看好同行老人小孩，走失原地等待","饮食注意卫生，海鲜过敏提前告知店家","贵重物品随身携带，景区人多注意"],"faqs":[["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["当地有什么必吃？","到了 景德镇，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["几月份去 景德镇 最合适？","春秋两季体感最舒服、风景层次最丰富；旺季建议提前订房，避开节假日人流。"]]}',2,'把日常调成静音，听风与远方的声音。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('岳麓山橘子洲味觉探索线','theme','长沙 · 岳麓山橘子洲','mountain','https://images.unsplash.com/photo-1523531294919-4bcd7c65e216?auto=format&fit=crop&w=800&q=80',19900,10900,2,'岳麓山 / 橘子洲头 / 太平老街 —— 一张票打包岳麓山橘子洲精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「岳麓山橘子洲」一日轻旅行——山岳。长沙湘绣摆件精致好带。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约8000步","transitText":"城市公共交通","season":"春秋最佳，夏季早晚凉爽","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"湖南 · 长沙"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★☆ 适中"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"长沙集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"岳麓山橘子洲游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"岳麓山","description":"首站直达岳麓山，爱晚亭秋色最美，索道下山省力。建议停留144分钟，跟着攻略动线走省一半时间。","addr":"长沙市岳麓区","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排太平街店——人均约18元，茶颜悦色是本地招牌，点菜照着攻略走。","addr":"太平老街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"橘子洲头","description":"午后游览橘子洲头，青年毛泽东雕像打卡，小火车代步。","addr":"长沙市橘子洲景区","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"太平老街","description":"收官打卡太平老街，臭豆腐与糖油粑粑的主场。随后自由活动，采购伴手礼。","addr":"长沙市天心区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"岳麓山","coverUrl":"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=800&q=80","highlights":"岳麓山是岳麓山橘子洲最有代表性的看点，爱晚亭秋色最美，索道下山省力。攻略把它排进主线，时间留得最足。","notice":"爱晚亭秋色最美，索道下山省力。这个点位上午光线最好。","durationMinutes":180,"addr":"长沙市岳麓区"},{"spotId":"S2","name":"橘子洲头","coverUrl":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?auto=format&fit=crop&w=800&q=80","highlights":"橘子洲头是岳麓山橘子洲最有代表性的看点，青年毛泽东雕像打卡，小火车代步。攻略把它排进主线，时间留得最足。","notice":"青年毛泽东雕像打卡，小火车代步。周边有休息区与补给点，随时停留。","durationMinutes":120,"addr":"长沙市橘子洲景区"},{"spotId":"S3","name":"太平老街","coverUrl":"https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?auto=format&fit=crop&w=800&q=80","highlights":"太平老街是岳麓山橘子洲最有代表性的看点，臭豆腐与糖油粑粑的主场。攻略把它排进主线，时间留得最足。","notice":"臭豆腐与糖油粑粑的主场。拍照记得留神脚下台阶。","durationMinutes":120,"addr":"长沙市天心区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"茶颜悦色（人均18元）","description":"长沙 · 岳麓山橘子洲的招牌是茶颜悦色，太平街店本地人都认这家，点单照攻略不踩雷。","addr":"太平老街"},{"title":"文和友臭豆腐（人均15元）","description":"长沙 · 岳麓山橘子洲的招牌是文和友臭豆腐，文和友本地人都认这家，点单照攻略不踩雷。","addr":"海信广场"},{"title":"糖油粑粑（人均8元）","description":"长沙 · 岳麓山橘子洲的招牌是糖油粑粑，李公庙糖油粑粑本地人都认这家，点单照攻略不踩雷。","addr":"坡子街"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8955,"required":true},{"name":"餐饮参考","amount":80,"required":false}],"checklist":["墨镜与拍照道具","换洗衣物与外套（早晚温差）","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","保温水杯与少量现金","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）","相机或运动相机"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["高原地区避免剧烈运动，备好氧气瓶","恶劣天气听从景区安排，不进入未开放区域","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["当地有什么必吃？","到了 长沙，跟着本攻略的美食清单走就行，本地人都在吃这几家。"],["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'出发这一刻，惊喜已经在路上。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('丽江古城玉龙雪山主题专线','theme','丽江 · 丽江古城玉龙雪山','mountain','https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80',18800,10300,2,'玉龙雪山 / 蓝月谷 / 丽江古城 —— 一张票打包丽江古城玉龙雪山精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「丽江古城玉龙雪山」一日轻旅行——山岳。雪山玫瑰饼是最热手信。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约12000步，量力而行","transitText":"城市公共交通","season":"四季皆宜，夏季避暑首选","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"云南 · 丽江"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★★★ 偏强"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"丽江集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"丽江古城玉龙雪山游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"玉龙雪山","description":"首站直达玉龙雪山，大索道直达4506米，租羽绒服买氧气瓶。建议停留240分钟，跟着攻略动线走省一半时间。","addr":"丽江市玉龙县","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排象山市场——人均约68元，腊排骨火锅是本地招牌，点菜照着攻略走。","addr":"古城区象山街","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"蓝月谷","description":"午后游览蓝月谷，牛奶蓝湖水，电瓶车游三湖。","addr":"玉龙雪山脚下","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"丽江古城","description":"收官打卡丽江古城，四方街打跳，狮子山看全景。随后自由活动，采购伴手礼。","addr":"古城区","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"玉龙雪山","coverUrl":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80","highlights":"玉龙雪山是丽江古城玉龙雪山最有代表性的看点，大索道直达4506米，租羽绒服买氧气瓶。攻略把它排进主线，时间留得最足。","notice":"大索道直达4506米，租羽绒服买氧气瓶。提前10分钟到，避开旅行团大部队。","durationMinutes":300,"addr":"丽江市玉龙县"},{"spotId":"S2","name":"蓝月谷","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"蓝月谷是丽江古城玉龙雪山最有代表性的看点，牛奶蓝湖水，电瓶车游三湖。攻略把它排进主线，时间留得最足。","notice":"牛奶蓝湖水，电瓶车游三湖。提前10分钟到，避开旅行团大部队。","durationMinutes":120,"addr":"玉龙雪山脚下"},{"spotId":"S3","name":"丽江古城","coverUrl":"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=80","highlights":"丽江古城是丽江古城玉龙雪山最有代表性的看点，四方街打跳，狮子山看全景。攻略把它排进主线，时间留得最足。","notice":"四方街打跳，狮子山看全景。这个点位上午光线最好。","durationMinutes":180,"addr":"古城区"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约1.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"腊排骨火锅（人均68元）","description":"丽江 · 丽江古城玉龙雪山的招牌是腊排骨火锅，象山市场本地人都认这家，点单照攻略不踩雷。","addr":"古城区象山街"},{"title":"鸡豆凉粉（人均10元）","description":"丽江 · 丽江古城玉龙雪山的招牌是鸡豆凉粉，古城小吃摊本地人都认这家，点单照攻略不踩雷。","addr":"四方街"},{"title":"丽江粑粑（人均12元）","description":"丽江 · 丽江古城玉龙雪山的招牌是丽江粑粑，忠义市场本地人都认这家，点单照攻略不踩雷。","addr":"忠义市场内"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":8460,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["轻便雨衣或折叠伞","常用药品（肠胃药/创可贴）","保温水杯与少量现金","相机或运动相机","墨镜与拍照道具","换洗衣物与外套（早晚温差）","身份证件与手机充电宝","舒适徒步鞋（防滑鞋底）"],"planB":"若身体不适请立刻联系向导，就近医疗点信息已写入安全提示。","safetyTips":["恶劣天气听从景区安排，不进入未开放区域","贵重物品随身携带，景区人多注意","夜间出行结伴，走主路不抄小道","饮食注意卫生，海鲜过敏提前告知店家"],"faqs":[["游玩这条线大概花多少钱？","除票务外，人均餐饮按每餐30-60元预算，加上零碎交通，整体非常可控。"],["这条线路适合带小朋友吗？","整条线路节奏适中，小朋友体力足够；涉及爬山与水上项目时看护好孩子即可。"],["一个人出发会不会不方便？","完全不会，这条线路单人也很好走；路上旅伴多，拍照也有搭子。"],["需要提前准备什么装备？","一双防滑舒适的鞋最重要，其余按季节带好防晒或保暖衣物，充电宝务必充满。"]]}',2,'好运藏在出发的行囊里。','on');
INSERT INTO `travel_route` (`name`,`category`,`location`,`scene`,`image_url`,`value_cent`,`cost_cent`,`badge_id`,`highlight`,`include_json`,`guide_json`,`guide_version`,`mood_text`,`status`) VALUES ('稻城亚丁深度体验线','theme','甘孜 · 稻城亚丁','plateau','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80',17200,9400,2,'牛奶海 / 五色海 / 冲古寺草坪 —— 一张票打包稻城亚丁精髓','["市内交通", "主题体验", "向导讲解"]','{"overview":"「稻城亚丁」一日轻旅行——高原。高原反应别逞强慢慢走。本攻略按theme玩法编排，含逐时段动线、美食清单与避坑提示。","durationText":"一日轻旅行","paceText":"主题聚焦，边走边逛","walkText":"累计步行约6000步，爬升平缓","transitText":"城市公共交通","season":"夏季水量最大，冬季雪景震撼","weather":"山区多变，出发前查当地实时天气，雨具备好","facts":[{"label":"目的地","value":"四川 · 甘孜"},{"label":"建议游玩","value":"一日"},{"label":"体力消耗","value":"★☆☆ 轻松"},{"label":"行程类型","value":"实体行程（已含票务）"}],"schedules":[{"dayNo":1,"time":"08:30","title":"集合出发","description":"甘孜集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。","addr":"稻城亚丁游客中心","tip":"出发前一晚睡好，早餐别空腹"},{"dayNo":1,"time":"09:30","title":"牛奶海","description":"首站直达牛奶海，海拔4600，马帮或徒步，量力而行。建议停留288分钟，跟着攻略动线走省一半时间。","addr":"稻城县香格里拉镇","tip":"检票口集合不迷路"},{"dayNo":1,"time":"12:00","title":"地道午餐","description":"正餐安排亚丁村民宿——人均约128元，松茸炖鸡是本地招牌，点菜照着攻略走。","addr":"亚丁村","tip":"饭点人多，先落座再点单"},{"dayNo":1,"time":"14:00","title":"五色海","description":"午后游览五色海，最后一百步最陡，景色值得。","addr":"牛奶海上方","tip":"午后阳光强，防晒补水"},{"dayNo":1,"time":"16:30","title":"冲古寺草坪","description":"收官打卡冲古寺草坪，仙乃日倒影机位。随后自由活动，采购伴手礼。","addr":"亚丁村","tip":"伴手礼认准正规商店"},{"dayNo":1,"time":"17:30","title":"返程","description":"清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","addr":"返程集合点","tip":"到集合点前先上个洗手间"}],"spots":[{"spotId":"S1","name":"牛奶海","coverUrl":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80","highlights":"牛奶海是稻城亚丁最有代表性的看点，海拔4600，马帮或徒步，量力而行。攻略把它排进主线，时间留得最足。","notice":"海拔4600，马帮或徒步，量力而行。这个点位上午光线最好。","durationMinutes":360,"addr":"稻城县香格里拉镇"},{"spotId":"S2","name":"五色海","coverUrl":"https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?auto=format&fit=crop&w=800&q=80","highlights":"五色海是稻城亚丁最有代表性的看点，最后一百步最陡，景色值得。攻略把它排进主线，时间留得最足。","notice":"最后一百步最陡，景色值得。拍照记得留神脚下台阶。","durationMinutes":60,"addr":"牛奶海上方"},{"spotId":"S3","name":"冲古寺草坪","coverUrl":"https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80","highlights":"冲古寺草坪是稻城亚丁最有代表性的看点，仙乃日倒影机位。攻略把它排进主线，时间留得最足。","notice":"仙乃日倒影机位。周边有休息区与补给点，随时停留。","durationMinutes":90,"addr":"亚丁村"}],"transport":[{"title":"往返交通","description":"城市公共交通，车程约2.5小时，晕车提前备药。"},{"title":"当地接驳","description":"景区内接驳车/索道按攻略建议乘坐，既省体力又不漏景；步行段注意台阶与湿滑。"}],"dining":[{"title":"松茸炖鸡（人均128元）","description":"甘孜 · 稻城亚丁的招牌是松茸炖鸡，亚丁村民宿本地人都认这家，点单照攻略不踩雷。","addr":"亚丁村"},{"title":"酥油茶（人均15元）","description":"甘孜 · 稻城亚丁的招牌是酥油茶，藏家小屋本地人都认这家，点单照攻略不踩雷。","addr":"香格里拉镇"},{"title":"高原土豆（人均10元）","description":"甘孜 · 稻城亚丁的招牌是高原土豆，小卖部熟食本地人都认这家，点单照攻略不踩雷。","addr":"洛绒牛场补给点"}],"lodging":[],"budgetItems":[{"name":"往返交通","amount":0,"required":true},{"name":"景区门票（已含）","amount":7740,"required":true},{"name":"餐饮参考","amount":120,"required":false}],"checklist":["少量零食补给","防晒霜与遮阳帽","常用药品（肠胃药/创可贴）","墨镜与拍照道具","身份证件与手机充电宝","相机或运动相机","轻便雨衣或折叠伞","换洗衣物与外套（早晚温差）"],"planB":"高速封路或航班延误时，优先保证核心景点游览，弹性压缩自由活动时间。","safetyTips":["涉水项目穿好救生衣，听从工作人员安排","贵重物品随身携带，景区人多注意","饮食注意卫生，海鲜过敏提前告知店家","高原地区避免剧烈运动，备好氧气瓶"],"faqs":[["雨雪天气怎么办？","小雨影响不大反而出景；暴雨大雪建议改期，出发前看一眼当地天气预报更稳妥。"],["有地方寄存行李吗？","景区游客中心与集合点都有寄存柜，轻装出发玩得更尽兴。"],["到达 甘孜 的交通方便吗？","推荐先到 甘孜，再打车或景区直通车前往核心景区；自驾导航直接搜稻城亚丁即可。"],["网络信号和支付方便吗？","主流移动支付全覆盖，山区信号偶尔弱，少量现金备用更安心。"]]}',2,'好运藏在出发的行囊里。','on');